[Definition of arXiv:2602.04303, '\Large\textbf{Strong solutions to SDEs with singular drifts driven by fractional Brownian '] $($$\mathcal{F}_t$-fractional Brownian motion [nualart2002regularization] $)$ Let $(\Omega,\mathcal{F},\mathbb{P},(\mathcal{F}_t)_{t\in[0,T]})$ be a filtered probability space where $(\mathcal{F}_{t})_{t\in[0,T]}$ is a filtration such that $\mathcal{F}_0$ contains all the sets of probability zero. We say that $B^H$ $(H<1/2)$ is a $\mathcal{F}_t$-fractional Brownian motion if there exists a $\mathcal{F}_t$-Brownian motion $W$ such that $B^H$ can be formulated as
			$$B_t^H=\int_0^tK_H(t,s)\mathrm{d} W_s,$$
			where for $0<\leq s\leq t\leq T$,
			\begin{align*}
				K_H(t,s):=C_H\left[\left(\frac{t}{s}\right)^{H-\frac12}(t-s)^{H-\frac12}+\left(\frac12-H\right) s^{\frac12-H}\int_s^tr^{H-\frac32}(r-s)^{H-\frac12}\mathrm{d} r\right].
			\end{align*}

[Proposition prop:triangular-equation of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] For every \(k\ge1\),
\begin{equation}

    p_k'(t)
    =\sum_{i=1}^{k-1}i^{-\alpha}p_i(t)p_{k-i}(t)
     -k^{-\alpha}p_k(t),
    \qquad
    p_k(0)=\mathbf 1_{\{k=1\}}.
\end{equation}
In particular,
\begin{equation}

\begin{aligned}
    p_1(t)&=e^{-t},\\
    p_k(t)&=\int_0^t e^{-k^{-\alpha}(t-s)}
      \sum_{i=1}^{k-1}i^{-\alpha}p_i(s)p_{k-i}(s)\,ds,
      \qquad k\ge2.
\end{aligned}
\end{equation}

