body:
[Theorem th:strong-HDL of arXiv:2604.08154, '\small Hydrodynamic limit of the directed exclusion process'] Let $(\eta_0^n)_{n\in \mathbb{N}^*}\in \Omega_0$ be a sequence of $\mathbf{X}$-valued random variables with strong density profile $u_0$, i.e., $u_0:\mathbb{R}\to [0,1]$ is measurable and,  $\mathds{P}_0$-a.s., one has
	\begin{equation}
		\frac1n\sum_{x\in \mathbb{Z}} f(\tfrac{x}n)\,\eta_0^n(x)
		\xrightarrow{n\to \infty}\int_{\mathbb{R}} f(x)\,u_0(x)\,{\rm d} x\; \text{,}\;\;\qquad  f \in \ensuremath{\mathcal C}_c(\mathbb{R})\; \text{.}
	\end{equation}
	Define, as in Section (sec:graphical of the paper), $\eta_t^n=\eta(\eta_0^n,\,\cdot\,,t)$, $n\in \mathbb{N}^*$ (i.e., $\eta(\eta_0^n,\,\cdot\,,0)=\eta_0^n$ for each $n\in \mathbb{N}^*$, but employing a common set of Poisson clocks). 
	Then,  letting $u(\,\cdot\,,\,\cdot\,):\mathbb{R}\times [0,\infty)\to [0,1]$ 
	be the  
	entropy solution to (equation eq:HDL of the paper) with initial condition $u_0$, we have, $\widetilde\mathds{P}$-a.s.,
	\begin{align}
	\sup_{t \in [0,T]}\abs{	\frac1n\sum_{x\in \mathbb{Z}} f(\tfrac{x}n)\,\eta_{tn}^n(x)-\int_{\mathbb{R}} f(x)\,u(x,t)\, {\rm d} x}\xrightarrow{n\to\infty}0\; \text{,}\;\;\qquad T>0\; \text{,}\;\; f \in \ensuremath{\mathcal C}_c(\mathbb{R})\; \text{.}	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:stable of arXiv:2609.01672, '\textbf{All-Minors Matrix-Tree Theory for Superport Networks:\\ Completed Quotient-Inciden'] Let \(X(z)=\operatorname{diag}(z_1,\ldots,z_q)\) and define
\begin{equation}
\mathcal P_F(z_1,\ldots,z_q)
:=\sum_{I\subseteq N}\Psi_I\prod_{i\in I}z_i.
\end{equation}
Then
\begin{equation}
\boxed{\mathcal P_F(z)=\Phi_{\mathrm{valid}}\det(I_q+X(z)L),}

\end{equation}
and \(\mathcal P_F\) is multiaffine, coefficientwise nonnegative and real stable.

