body:
[Proposition 15 of arXiv:2607.09575, 'Probabilistic estimates for a system of\\noisy integrate-and-fire neurons'] For every $t \in [0,\,T]$ and $\eta > 0$, we have
	\begin{equation*}
		\lim_{h \to  0} \limsup_{N \to  +\infty} \prob\left[F_{(t+h) \wedge T}^N - F_t^N \ge \eta\right] = 0 \quad \textnormal{and} \quad \lim_{h \to  0} \limsup_{N \to  +\infty} \prob\left[F_{t}^N - F_{(t-h) \vee 0}^N \ge \eta\right] = 0
	\end{equation*}

[Definition GPpointdef of arXiv:2608.09856, '\bf Mass erasure on measured $\bbR$-trees,\\ applications to L\'evy forests'] For $i\! \in \!  \{ 1, 2\}$, let $(E_i, d_i, \rho_i, \mu_i )$ be Polish metric spaces where 
$\rho_i \! \in \! E_i$ and $\mu_i \! \in \! \mathcal{M}_{\! f} (E_i)$. We define their 
\textit{Gromov--Prokhorov pseudo-distance} by 
\begin{equation}

{\boldsymbol{\delta}}_{\mathtt{GP}} (\mu_1, \mu_2) = \inf \big\{ \delta ( \phi_1(\rho_1), \phi_2 (\rho_2)) \vee \delta_{\mathtt{Pro}}(  
\mu_1 \! \circ \! \phi_1^{-1}\! ,  \mu_2\!  \circ \! \phi_2^{-1} )  \big\} , 
\end{equation}
and if the $E_i$ are compact, their \textit{Gromov--Hausdorff and  Gromov--Hausdorf--Prokhorov distances} by
\begin{eqnarray*}
 {\boldsymbol{\delta}}_{\mathtt{GH}} (E_1 , E_2) \!\!\! \!\! &=&\!\!\! \!\! \inf \! \big\{ \delta \big( \phi_1 (\rho_1), \phi_2 (\rho_2) \big) \vee \delta_{\mathtt{Haus}} (
 \phi_1 (E_1), \phi_2(E_2) )  \big\} \quad \textrm{and} 
 \\
{\boldsymbol{\delta}}_{\mathtt{GHP}}\!  \big(\!(E_1, \mu_1), \! (E_2 , \mu_2)\!\big) 
   \!\!\!\! \!&=&   \!\!\!\!  \!   \inf \! \big\{\!  \delta \big( \phi_1 (\rho_1), \phi_2 (\rho_2) \big) \! \vee\!  \delta_{\mathtt{Haus}} (
 \phi_1 (E_1), \phi_2(E_2) ) \! \vee \!  \delta_{\mathtt{Pro}}(  
\mu_1 \! \circ \! \phi_1^{-1}\! ,  \mu_2\!   \circ \! \phi_2^{-1} )\! \}
\end{eqnarray*}
where infima are taken on all Polish metric spaces $(X, \delta)$ and all isometrical embeddings $\phi_i \! : \! 
E_i \! \rightarrow \! X$, $i\! \in \!  \{ 1,2\}$; 
here, $ \delta_{\mathtt{Haus}}$ stands for the Hausdorff distance on the space of compact subsets of $X$ and $ \delta_{\mathtt{Pro}}$ stands for the Prokhorov distance on $\mathcal{M}_{\! f} (X)$. $\hfill \square$

[Lemma 14 of arXiv:2606.22940, 'From smooth to discontinuous kernels: a variance transfer principle for hyperuniform proce'] For $ g \in \B_{ c}^{ }(B_{ 1})$,
\begin{align*}

 \overline{  \textrm{Var}}^{ \varepsilon _{ N}}\left(\X_{ N}(g_{ R})\right)\leqslant  \textrm{Var}\left( \P _{\lambda}(g_{ R})\right)

 +  C_{ f}'\|g\|_\infty ^{ 2}  R^{ d-\alpha _{ 0}}.
 \end{align*}
 In the case $ g = f$,  we have furthermore the converse
\begin{align*}
 \textrm{Var}\left(\P_{\lambda }(f_{ R})\right)\leqslant \overline{  \textrm{Var}}^{ \varepsilon _{ N}}\left(\X_{ N}(f_{ R})\right) + C_{ f}'  {  R^{ d-\alpha _{ 0}}}.
\end{align*}

