body:
[Theorem thm:main-upper-bound-het of arXiv:2510.11015, 'An interpretable universal bound for multiserver queues via a leave-one-out technique'] Consider the $GI/GI/n$\xspace queue with heterogeneous servers under the FCFS policy, satisfying Assumptions~(assump:bdd-exp-remain-het of the paper), (assump:non-lattice-het of the paper), and (assump:modified-ggn-stable-het of the paper). When the load $\rho < 1$, let $\pi$ be the unique stationary distribution of the system. Then the mean queue length under $\pi$ satisfies
    \begin{equation}

        \begin{aligned}
            \Ep{\pi}{Q} &\leq \frac{\rho\textnormal{Var}\left[\Lambda A\right] + \sum_{j=1}^n (\mu_j / \mu_{\Sigma}) \textnormal{Var}\left[\mu_j S_j\right] + 1-\rho}{2(1-\rho)}  \\
            &\mspace{23mu} + \sum_{j=1}^n \min\Big(1, \frac{\mu_j}{(1-\rho)\mu_{\Sigma}}\Big) \Big(R_{{s,j}}^{\max} - \frac{1}{2} \mathbb{E}\left[(\mu_j S_j)^2\right]\Big) \\
            &\mspace{23mu} + \frac{1}{2}\mathbb{E}\left[(\Lambda A)^2\right] - R_{a}^{\min}.
        \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 40 of arXiv:2609.03962, '$L^p$ isomorphisms for the fractional Laplacian on $\mathbb{R}^n$ and their application'] Let $n\ge2$, $0<s<2$, $p\in(1,\infty)$, and let
$f\in\Lambda^{-1,p}(\R^n)^n$, $g\in\Lambda^{s-2,p}(\R^n)$. Then
\eqref{fstokes} admits a solution $(u,P)\in V_{s,p}^n\times L^p(\R^n)$ if
and only if
\begin{equation}
  f\perp\mathcal P_{[1-n/p']}
  \qquad\text{and}\qquad
  g\perp\mathcal P_{[2-s-n/p']}.
\end{equation}
In this case the pressure $P$ is unique, and the solutions are precisely
the pairs $(u+\lambda,P)$ with
$\lambda\in(\mathcal P_{[s-1-n/p]})^n$; thus the solution is unique
whenever $s-1<n/p$, in particular for all $0<s\le1$, and unique up to an
additive constant vector when $s-1\ge n/p$. Moreover every solution
satisfies
\begin{equation}
  \norm{P}_{L^p}
  +\inf_{\lambda\in(\mathcal P_{[s-1-n/p]})^n}
   \norm{u-\lambda}_{\Lambda^{s-1,p}}
  \le C\big(\norm{f}_{\Lambda^{-1,p}}+\norm{g}_{\Lambda^{s-2,p}}\big).
\end{equation}

[Proposition lem.optproperties of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] For any $0 < T \leq 1$, the problem
    \begin{equation}
        \inf_{(m,\alpha) \in \mathcal{A}(0,\delta_0)} [m_T]_{\infty},
    \end{equation}
    admits an optimizer $(m,\alpha)$ with the following properties:
    \begin{enumerate}
        \item $m_t$ is even, in the sense that $(x \mapsto -x)_{\#} m_t = m_t$, for each $0 \leq t \leq T$, 
        \item $\alpha(t,\cdot)$ is odd, for each fixed $t$, 
        \item $\alpha$ ``points inwards", in the sense that $\alpha(t,x)x \leq 0$ for each $(t,x) \in [0,T] \times {\mathbb R}$. 
    \end{enumerate}

[Theorem thm:shuffle of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $d \geqslant 2$ be an integer and $\mu$ be a distribution on $S_d$. Let $\gamma$ denote the spectral gap of the single ball transition matrix $U$ and $q \coloneqq \min \left\{1-U(i,i): i \in [d]\right\}$. Then the following hold.

    \begin{enumerate}[label=(\alph*)]
        \item Consider a sequence $\{\mathbf{X}^{(n)}\}_{n \in \mathbb{N}}$ of multi-stack random-to-random shuffle chains where the $n^{\mathrm{th}}$ chain has parameters $(d, n, \mu)$. Then, for any fixed $\varepsilon \in (0, 1)$, we have
        \begin{equation*}
            \frac{n \log n}{2 \gamma} - O(n) \leqslant t^{(n)}_{\textup{mix}}(\varepsilon) \leqslant \max \set{\frac{1}{2 \gamma}, 1} \cdot n \log n + O(n \log \log n).
        \end{equation*}

        \item Consider a sequence $\{\mathbf{X}^{(n)}\}_{n \in \mathbb{N}}$ of restricted multi-stack random-to-random shuffle chains where the $n^{\mathrm{th}}$ chain has parameters $(d, n, \mu)$. Then, for any fixed $\varepsilon \in (0, 1)$, we have
        \begin{equation*}
            \frac{n \log n}{2 \gamma} - O(n) \leqslant t^{(n)}_{\textup{mix}}(\varepsilon) \leqslant \max \set{\frac{1}{2 \gamma}, \frac{1}{q}} \cdot n \log n + O(n \log \log n).
        \end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm infinimum of variance of arXiv:2512.12796, 'Symmetrization and the Planar Skorokhod Embedding Problem'] Let $c>0$ and let $\mathfrak{A}_{c}$
be the set of simply connected domains of fixed area $c$. Then 
\begin{equation}
\inf_{U\in\mathfrak{A}_{c}}\mathbf{Var}(\mu_{U})=0.
\end{equation}

[Proposition 5 (Laws at ascension) of arXiv:2607.16833, 'Dynamical Equations for Poisson Galton--Watson Trees and Component Densities of Sparse Inh'] For $\lambda\geq1$,
\begin{equation}
 \bP_x(A\leq\lambda)=1-q_\lambda,
\end{equation}
and, for $\lambda>1$,
\begin{align}
 \bP_x(\widehat G_{A-}\in\dd t,A\in\dd\lambda)
 &=(1-q_\lambda)T(t)\widehat\bP_{x,\lambda}(\dd t)\dd\lambda,
 \\
 \bP_x(\widehat G_{A-}\in\dd t\mid A=\lambda)
 &=(1-\widehat\lambda)T(t)
   \widehat\bP_{x,\widehat\lambda}(\dd t).

\end{align}
If $U$ is uniform on $(0,1)$, then
\begin{equation}
 (A,q_A)\stackrel d=
 \left(\frac{-\log U}{1-U},U\right).
\end{equation}
These are the typed versions of Lemma~22, equations~(81)--(84), of
\cite{AldousPitman1998}.

[Definition def-shift of point function of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Suppose that $X $ is a non-empty set and $p$ is  a point function on $X$.  Given $t \geq 0$ we define $\theta_tp$ by
\begin{equation}
\begin{aligned}
\mathrm{Dom}(\theta_tp)&:=\bigl\{s \in (0,\infty): s+t \in \mathrm{Dom}(p) \bigr\}=(\mathrm{Dom}(p)-t)\cap (0,\infty), \\
\theta_tp(s)&:= p(s+t), \;\; s \in \mathrm{Dom}(\theta_tp).
\end{aligned}
\end{equation}
In other words, if $\mathrm{Dom}(p)=\{ s_i\}$, then $\mathrm{Dom}(\theta_tp)=\{ s_i-t: s_i>t\}$ and $\theta_tp(s_i-t)=p(s_i)$.

[Proposition 15 (Sharp curvature scale) of arXiv:2609.02788, '\textbf{Quantized Einstein Metrics on \(S^7\) with \(SU(3)\)-Symmetry}'] For the sequence $g_n$ of Theorem~\ref{thm:main},
\[
 \sup_{S^7}|\Rm(g_n)|\asymp b_n^{-2}.
\]
More precisely, at either singular orbit,
\begin{equation}
 b_n^2K_{02}^{(n)}\longrightarrow-\frac{1+2c_*^2}{2}.
\end{equation}
Hence
\begin{equation}
 \frac{|K_{02}^{(n+1)}|}{|K_{02}^{(n)}|}
 \longrightarrow e^{4\pi/\sqrt{15}}.
\end{equation}

