[Definition def:MP_lin of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $s\in [0,T)$ and $\nu\in\mathcal{P}(\mathbb{R}^d)$. A probability measure $\mathbb{P}=\mathbb{P}_{s,\nu}$, on $(C_{[s,T)},\mathcal{B})$, is a solution to MP$(b,\sigma;s,\nu)$ if: 

\begin{itemize}
\item[(i)] $x_{s} \sim  \nu$ under $\mathbb{P}$;
\item[(ii)] for any $\varphi\in C_0^{\infty}(\mathbb{R}^d)$, the process defined by 
\begin{equation}
M_t : =\varphi(x_{t}) - \varphi(x_{s}) - \int_{s}^t \Big(   \langle  b(r, x_r) , \nabla \varphi(x_{r})  \rangle + \frac{1}{2}\text{tr}\big(\sigma \sigma^\top (r , x_r)  \nabla^2 \varphi(x_r)  \big) \Big) dr , \qquad t\in [s, T),
\end{equation}
is a martingale w.r.t. the natural filtration of $(x_t)_{t\in [s,T)}$.
\end{itemize}

[Theorem 14 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Let $u>0$, and let $\varphi:\mathbb{R}_+\to\mathbb{R}_+$ be bounded and measurable. Then
\begin{align*}
&\mathbb{E}\!\left(\varphi(M_T^-);\,M_T^+<u,\,H_S<H_I\right)\\
&=\frac{
\left(Z^{(\gamma)}(u)-1\right)^2
\left[
Z^{(\gamma)}(u)W_{+}^{(\gamma)\prime}(u)
-
\gamma\left(W^{(\gamma)}(u)\right)^2
\right]
}{
\gamma\left(W^{(\gamma)}(u)\right)^3
}
\int_u^\infty
\varphi(r)
\exp\!\left\{-(r-u)\frac{W_{+}^{(\gamma)\prime}(u)}{W^{(\gamma)}(u)}\right\}
\frac{
\left(W^{(\gamma)\prime}(r)\right)^2
-
W^{(\gamma)}(r)W^{(\gamma)\prime\prime}(r)
}{
Z^{(\gamma)}(r)W_{+}^{(\gamma)\prime}(r)
-
\gamma\left(W^{(\gamma)}(r)\right)^2
}
\,dr
\\[1ex]
&\quad+
\frac{1}{\gamma}
\int_0^u
\varphi(r)
\frac{
\left(Z^{(\gamma)}(r)-1\right)^2
\left[
\left(W^{(\gamma)\prime}(r)\right)^2
-
W^{(\gamma)}(r)W^{(\gamma)\prime\prime}(r)
\right]
}{
\left(W^{(\gamma)}(r)\right)^3
}
\,dr.
\end{align*}

[Lemma lem:activity-holes of arXiv:2609.02820, 'Sharpness and critical scaling of parking'] Let $\eta$ be translation invariant with $\mathbb{E}|\eta(0)|<\infty$.
	Then, for every $t\geq0$,
	\begin{equation}
		\mathbb{E} A_t(0)-\mathbb{E} H_t(0)=\mathbb{E}\eta(0)\,.
	\end{equation}

[Thm 8 of arXiv:2606.24584, '2606.24584'] Let $D$ be an $n\times n$ irreducible doubly stochastic matrix. Then $D$ is cyclic  if and only if there exists a permutation matrix $P$ such that
\begin{equation}
    P^{\intercal}DP = K_{h} \otimes J_{n'}.
\end{equation}
where $h:=h(D)$ and $n'=n/h$. Moreover, in that case, $D$ is cyclic of order $h$.

[Definition d:strongly log-dominating of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $\rho:[0,\infty)\to [0,\infty)$ be an increasing function that satisfies
\begin{equation}
    \int_0^\infty \frac{1}{r \rho(r) + 1} \, dr < \infty.
\end{equation}
Then $\rho$ is called a \textit{strongly log-dominating} function.

[Lem 7 of arXiv:2609.02327, 'On the counting function of square-full numbers'] {\cite{IV}(Vinogradov)}
			For $|t|\geqslant 10$, there exists an absolute constant $C$ such that in the region 
			\begin{equation*}
				\sigma \geqslant 1-\frac{C}{(\log |t|)^{\frac{2}{3}}(\log \log |t|)^{\frac{1}{3}}}
			\end{equation*}
			we have the bounds :
			\begin{equation}
				\zeta(\sigma+it)\ll \left (\log |t| \right)^{\frac{2}{3}+\epsilon}
			\end{equation}

			\begin{equation}
				\frac{1}{\zeta(\sigma+it)}\ll \left (\log |t| \right)^{\frac{2}{3}+\epsilon}
			\end{equation}
			for any $\epsilon>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

