\begin{equation*}
\overline{\mathcal{F}}^{\nabla}_{B_r}:=\sigma(\bar{\sigma}_x, \, \eta_b \mid x \in B_r, \, b \in \vec{E}_{B_r})
\end{equation*}
denote the sigma-algebra on $\mathbb{Z}_2^V \times\Omega^\nabla$ generated by the gradient field \textbf{and} the fuzzy chain inside $B_r$.

[Definition eq:cdbm-def of arXiv:2507.12502, 'Quantitative Edge Eigenvector Universality for Random Regular Graphs: Berry-Esseen Bounds '] The \emph{constrained Dyson Brownian motion} (CDBM) is the solution to the stochastic differential equation
\begin{equation}
\mathrm{d}\tilde{H}_t = -\frac{1}{2}\tilde{H}_t \mathrm{d} t + \frac{1}{\sqrt{N}}\mathrm{d} W_t
\end{equation}
where $W_t$ is a matrix Brownian motion on the constrained space
\[
\mathcal{M}_0 := \{M \in \mathbb{R}^{N \times N} : M = M^T, M\mathbf{e} = 0\}
\]

[Prop large minorising bounded offspring dist branching processes of arXiv:2505.12127, 'Generalised principal eigenvalues and global survival of branching Markov processes'] We assume that the branching is purely local. Then for all $\epsilon>0$ there exists a discrete-time branching process ${\bar Y}_n=(Y^1_n,\ldots,Y^{M_n}_n)$ ($n\in \mathbb{N}$) with bounded offspring distribution such that:
\begin{enumerate}
    \item The discrete-time skeleton of $\bar X$, $(\bar X_n)_{n\in \mathbb{N}}$, dominates $(\bar Y_n)_{n\in \mathbb{N}}$ in the sense that, for every starting point $y\in E$, we can couple them so that 
    \[
    {\mathbb P}_y\left(\forall n\ge 0: \sum_{i=1}^{N_n}\delta_{X^i_n}\geq \sum_{j=1}^{M_n}\delta_{Y^i_n}\right) = 1,
    \]
    where for two measures $\mu$ and $\nu$ we write $\mu\ge \nu$ if $\mu(A) \ge \nu(A)$ for every measurable $A$.
    \item The associated expectation kernel 
    \begin{equation}
    Q(y,\cdot):={\mathbb E}_x\Big[\sum_{j=1}^{M_1}\delta_{Y^i_1}\Big]
    \end{equation}
    satisfies $Q(y,\cdot)\geq (1-\epsilon)P_1(y,\cdot)$ for all $y\in E$.
\end{enumerate}

[Proposition prop: sle RN derivative critical of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Fix $\beta=\beta_c$ as the inverse temperature of the two-dimensional Ising model. There exists a constant $c_1>0$ such that for any small constant $\iota\in(0,1)$ and any interface $\gamma$, 



    \begin{align}
        {\mathbb{E}}\max\{\mathsf Z^+(\gamma),\mathsf Z^-(\gamma)\} \le \exp\Big( c_1(\frac{S(\gamma)}{N^{\frac{7}{4}}})^{1+3\kappa}\cdot \iota^{-2}\Big).
    \end{align}
    In addition, we also have \begin{align}
        &{\mathbb{P}}\Big(\max\{|\log\big(\mathsf Z^+(\gamma)\big)|,|\log(\mathsf Z^-(\gamma)\big)|\}\ge  c_1(\frac{S(\gamma)}{N^{\frac{7}{4}}})^{1+3\kappa}\cdot \iota^{-2}\Big)\le \exp\Big(- c_1^{-1}(\frac{S(\gamma)}{N^{\frac{7}{4}}})^{\frac{21\kappa}{32}}\cdot \iota^{-\frac{1}{4}}\Big).\\
        &{\mathbb{P}}\Big(|\log(\mathsf Z)|\ge
        c_1\iota^{-2})\le~ \exp\Big(- c_1^{-1} \iota^{-\frac{1}{4}}\Big).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

