[Corollary 20 (Finite-time fixed-marginal $W_2$ chaos) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under the same assumptions, for every $1\le k\le N$,
\begin{equation}
  W_2^2(P_{N,t}^{(k)},\mu_t^{\otimes k})
  \le C\frac{k}{N}\bigl(e^{L_\mathrm{cpl}t}-1\bigr).
\end{equation}

[Lem 11 of arXiv:2506.19008, 'Sprinkled Decoupling for Hammersley's Process'] Let $\upsilon\in(0,1/2)$. There exists $k_0\in\bN$ such that, for each $k\geq k_0$, there exists $M_k\subseteq \ZZ^2$ satisfying: 
\begin{enumerate}
    \item $\#M_k\leq 10 l_{k-1}^{1/2}$;
    \item If $D_k$ happens, there exists $\xx,\yy\in M_k$ such that $D_{k-1}(\xx)$ and $D_{k-1}(\yy)$ happen and 
    $$\d\left(B_{k-1}(\xx),B_{k-1}(\yy)\right)\geq \left(\per(B_{k-1}(\xx)+\per(B_{k-1}(\yy)\right)^{3/2-\upsilon}\,.$$
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 14 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $H \in \mathcal{S}(\mathbb{R})$, $s \in [0,T]$ and $n \in \mathbb{N}_+$. Then
\begin{align}
	& \Theta(n) \big\{  \mcb L^n[\mathcal{Z}_{s}^n(H)]^{2} -2 \mathcal{Z}_{s}^n(H) \mcb L^n \mathcal{Z}_{s}^n(H)  \big\} \nonumber \\
	= &\frac{\Theta(n)}{2n} \sum_{ z, w } \big[ H ( \tfrac{z - s v_n  }{n}  ) - H ( \tfrac{w - s v_n  }{n}  ) \big]^{2} [f_w( \eta_s^n ) - f_z( \eta_s^n )]^{2} [ p(w-z) r^n_{z,w}(\eta_s^n) + p(z-w) r^n_{w,z}(\eta_s^n) ]. 
\end{align}

