[Definition of arXiv:2608.10415, 'Continuous random variables'] Let $A$ be a $C^*$-algebra, coming with a trace $tr:A\to\mathbb C$.
\begin{enumerate}
\item The elements $a\in A$ are called noncommutative random variables.

\item The moments of such a variable are the numbers $M_k(a)=tr(a^k)$.

\item The law of such a variable is the functional $\mu_a:P\to tr(P(a))$.
\end{enumerate}

[Knowntheorem 26 (G. Pisier 1986 \cite{Pis}) of arXiv:2604.09365, 'Cotlar martingale transforms and related singular integrals'] Let  $1<p<\infty$ and $q$ be its conjugate exponent. For a standard normal random variable $X$, i.e., $X\sim N(0, 1)$,  we set
 $\gamma(p)=\|X\|_p$. Then, 
\begin{equation}
\|R\|_{L^p(\R^d)}
\le
\begin{cases}
\frac{\gamma(q)}{\gamma(p)}\sqrt{\frac{\pi}{2}}\,\,\|H\|_p, &1<p\leq 2,\\
\sqrt{\frac{\pi}{2}} \,\,\|H\|_p, & 2\leq p<\infty. 
\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] Fix $[s,t]\subseteq \RR$. Almost surely, for every $r\in \cT_{\0}^{
,[s,t]}$, exactly one of the following hold.
   egin{enumerate}
  \item $\Gamma_{\0}^{
,r}=\Gamma_{\0}^{
,r^-}$.
  \item $\overline{\Gamma_{\0}^{
,r}\setminus \Gamma_{\0}^{
,r^-}}$ is an excursion about $\Gamma_{\0}^{
,r^-}$. 
  \item There exist points $p_1=(x_1,t_1), p_2=(x_2,t_2), p_3 = (x_3,t_3), p_4=(x_4,t_4) \in \Gamma_{\0}^{
,r^-}\cap \ZZ_\RR$ such that $t_1<t_2=t_3<t_4$ and $\overline{\Gamma_{\0}^{
,r}\setminus \Gamma_{\0}^{
,r^-}}$ is precisely the union of two excursions about $\Gamma_{\0}^{
,r^-}$, one being a staircase from $p_1$ to $p_2$ and one being a staircase from $p_3$ to $p_4$.
  \end{enumerate}

[Lem finite_energy_approx of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For $\mathsf{P}\in  \mathcal P_{s,1}(\Gamma)$ with  $\mathcal F_{\beta}({P})<\infty$  there exists a sequence $\mathsf{P}^n\in \mathcal P_{s,1}(\Gamma)$ with $\mathcal{W}^{int}(\mathsf{P}^n)\leq \mathcal{W}^{int}(\mathsf{P})+1/n$, $\mathcal E(\mathsf{P}^n)\leq \mathcal E(\mathsf{P})+1/n$ and 
    \begin{align}
        \int \sum_{x\in \xi\cap \Lambda_1}\left\lvertx^+-x\right\rvert^p\mathsf{P}^n(d\xi)<\infty.
    \end{align}
    Furthermore, $\mathsf{P}^n\xrightarrow{n\to \infty}\mathsf{P}$  w.r.t. $\mathcal T_{\mathcal L}$ (in particular weakly) and for $n\in \IN$ there exists $q_n>0$  such that the measure $\mathsf{P}^n$ is concentrated on the set \begin{align}
        \Gamma_{q_n}=\{\xi\in \Gamma: \varphi(x-y)\leq q_n,1/q_n\leq \left\lvertx-y\right\rvert \text{ for any two distinct }x,y\in \xi \}.
    \end{align}

