	\lVert \mathcal{B}_{z,w}^{-1}(1-\Pi_{z,w})\rVert_{\lVert\cdot\rVert\to\lVert\cdot\rVert}\lesssim 1, \quad
	\lVert \mathcal{B}_{z,w}^{-1}(1-\Pi_{z,w})\rVert_{\lVert\cdot\rVert_{\textnormal{hs}}\to\lVert\cdot\rVert_{\textnormal{hs}}}\lesssim 1.
\end{equation*}

