[Theorem 3 (Caffarelli--Silvestre extension for the hierarchical Laplacian) of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] Let $f\in \mathcal{S}_0(X)$ and assume the standing hypotheses above.
Suppose that
\begin{align*}
    \kappa:=\lim_{k\to+\infty}\frac{\lambda(B_k(x))}{C(B_k(x))}
\end{align*}
exists, belongs to $(0,+\infty)$, and is independent of $x$, with convergence uniform on compact subsets of $X$. Consider the following extension problem
    \begin{align*}
        \begin{cases}
        \Delta_W\varphi(v_B)=0,&v_B\in\mathcal{T}_X;\\
        \varphi|_{\partial\mathcal{T}_X}(x)=f(x),&x\in X;\\
        \varphi(\infty)=0.
    \end{cases}
    \end{align*}
    Here $W(B,B')=\frac{1}{\kappa}\frac{m(B)\lambda(B)\lambda(B')}{C(B)}$, where $B'$ is the unique immediate super-ball of $B$. The problem has a unique solution in the canonical class of harmonic functions with an $L^2(X,m)$ trace and a flux
    \begin{align*}
        \Phi(B)=W(B,B')\left(\varphi(v_B)-\varphi(v_{B'})\right)
    \end{align*}
    of the form
    \begin{align*}
        \Phi(B)=\int_Bg_\varphi(y)dm(y),
        \qquad g_\varphi\in \mathcal{S}_0(X).
    \end{align*}
    For this solution, $g_\varphi=\kappa^{-1}L_Cf$. Given a chain $\cdots\supseteq B_{k-1}(x)\supseteq B_k(x)\supseteq B_{k+1}(x)\supseteq\cdots\ni x$, define the deformed normal derivative at $x\in\partial\mathcal{T}_X\setminus\{\infty\}$ by
    \begin{align*}
        \partial_n^{(W)}\varphi(x)=\lim_{k\to+\infty}\frac{W(B_k,B_{k-1})}{m(B_k)}(f(x)-\varphi(v_{B_{k-1}})),
    \end{align*}
    where the limit exists in $L^2(X,m)$. The corresponding Dirichlet-to-Neumann map is the hierarchical Laplacian:
    \begin{align*}
        \partial_n^{(W)}\varphi(x)=L_Cf(x).
    \end{align*}
    Here the equality holds in $L^2(X,m)$.
    The solution also satisfies the energy identity
\begin{align*}
    \frac{1}{2}\sum_{\substack{v_A,v_B\in \mathcal{T}_{X}\\v_A\sim v_B}}|\varphi(v_A)-\varphi(v_B)|^2W(A,B)
    =&\frac{1}{\kappa}\int_Xf(x)L_Cf(x)dm(x).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma defect-shape of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Assume that the initial defect 
\begin{equation}
D_{0}(x)=L_{0}(x)+L_{0}(1-x)-1  
\end{equation}
has a constant sign on $[0,1]$. Then, for every $n\geq 0$, the defect 
\begin{equation}
D_{n}(x)=L_{n}(x)+L_{n}(1-x)-1,\qquad x\in \lbrack 0,1],  
\end{equation}
has a constant sign on $[0,1]$, the sign alternates with $n$, and $|D_{n}|$
is nondecreasing on $[0,\tfrac{1}{2}]$.

