[Corollary cor: limit of departures martingale of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] Fix $\varphi \in C_b(\mathbbm{R}_+^3)$ and consider the normalized processes
	\begin{equation*}
		\bar\boldsymbol{D}^N(\varphi) \vcentcolon= \frac{\boldsymbol{D}^N(\varphi)}{N}, \quad \bar\boldsymbol{D}^{N, c}(\varphi) \vcentcolon= \frac{\boldsymbol{D}^{N, c}(\varphi)}{N} \quad \text{and} \quad \boldsymbol{X}^N(\varphi) \vcentcolon= \bar\boldsymbol{D}^N(\varphi) - \bar\boldsymbol{D}^{N, c}(\varphi).
	\end{equation*}
	Then $\boldsymbol{X}^N(\varphi) \Rightarrow 0$ in $D_\mathbbm{R}[0, \infty)$ as $N \to \infty$.

[Theorem thm:nonlin-FP of arXiv:2608.19198, 'Probabilistic Representation and Convergence of Gromov-Wasserstein Gradient Flows'] The IGW gradient flow $(\rho_t)_{t \in [0,\infty)}$ from (thm:main of the paper) solves the nonlinear FPE
\begin{equation}
    \partial_t\mu_t(x) - \nabla\cdot\left(\frac12\Sigma_{\mu_t}^{-1}\nabla\mu_t(x) + \frac14\big(\Sigma_{\mu_t}^{-1}+\Sigma_{\mu_t}^{-2}\big)x\mu_t(x) \right) =0
\end{equation}
in the distributional sense on $\mathbb{R}^d\times(0,\infty)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 (Control of the geometric velocity) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Assume \eqref{eq:un}.  Then, for every $0<t<T$,
\begin{equation}

 \lVert\partial_tF_t\rVert_{L^2(\Sigma,\dd\mu_t)}^2
 \leq c_0^{-2}
 \bigl(-W'(t)\bigr).
\end{equation}

