[Lemma lem:carpet-smoothing of arXiv:2607.24705, 'Derangetropy Operators'] For almost every $s$: $u_{s}$ is continuous, and for every
		$\varepsilon > 0$ there is $C_{s,\varepsilon}$ with
		\begin{equation}
			\Vert P_{N}u_{s}\Vert_{\infty}
			\le C_{s,\varepsilon}\,N^{-1/2+\varepsilon}
			\quad\text{for all dyadic } N,

		\end{equation}
		so that $u_{s}$ and $w_{s}$ belong to
		$C^{1/2-\varepsilon}(\mathbb{T}_{2})$ for every $\varepsilon > 0$.
		At every rational $s$ the conclusion fails: $u_{s}$ is a step
		function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:main of arXiv:2411.04690, 'Asymptotic distribution of the derivative of the taut string accompanying Wiener process'] If a convex function $\varphi$ satisfies
\begin{equation} 
\int\limits_{\mathbb{R}}  \varphi(u) e^{-2\lambda|u|} du <\infty
\quad \textrm{for some } \lambda\in (0,r)
\end{equation}
or
\begin{equation} 
     \int\limits_{\mathbb{R}}  \varphi(u) \, p_{\infty,r}(u) du =\infty
\end{equation}
then
\begin{equation} 
  \frac{1}{T}  \int_0^T \varphi(\eta'_{T,r}(t))\, dt
  \xrightarrow{\mathbb{P}} \int\limits_{\mathbb{R}} \varphi(u) \,  p_{\infty,r}(u)\, du  
\end{equation}
and
\begin{equation} 
   \liminf_{T\to\infty} \frac{1}{T}  \int_0^T \varphi(\eta'_{T,r}(t))\, dt
   \stackrel{\text{a.s.}}{\geq} \int\limits_{\mathbb{R}} \varphi(u) \,  p_{\infty,r}(u)\, du.    
\end{equation}

If a function $\varphi$ is continuous almost everywhere, locally bounded and satisfies power growth condition (equation eq:power_bound of the paper), then
\begin{equation} 
      \frac{1}{T}  \int_0^T \varphi(\eta'_{T,r}(t))\, dt
      \xrightarrow{\text{a.s.}} \int\limits_{\mathbb{R}} \varphi(u) \, p_{\infty,r}(u)\,du.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm local_wp of arXiv:2607.27472, 'The stochastic Keller--Segel system in critical spaces'] Assume that the parameters $s,s_v,q,q_v,p,\kappa$ satisfy (equation Eq_standard of the paper) and  (equation Eq_pc1_new of the paper)--(equation Eq_pc5_new of the paper), and let $g^{i}$, $i\in \{1,2\}$, satisfy Assumption (Ass_noise of the paper). 
		Then, for any $\mathfrak{F}_0$-measurable 
		\begin{equation}

			(u_0,v_0)\colon \Omega\to B^{d/q-2}_{q,p}(\mathbb{T}^d)\times  B^{d/q_v}_{q_v,p}(\mathbb{T}^d),
		\end{equation}
		there exists an   $L^p_\kappa$-maximal solution $((u,v),\sigma)$ to (equation 25.06.19.16.01 of the paper) starting at (equation eq_IV of the paper) and satisfying $\sigma>0$, $\mathbb{P}$-almost surely.
		{Moreover, if $((u,v),\sigma)$ and $((\overline{u},\overline{v}),\overline{\sigma})$ are $L^p_\kappa$-maximal solutions to (equation 25.06.19.16.01 of the paper), then 
			\begin{align*}
				\sigma = \overline{\sigma}\qquad \text{and}\qquad 
				(u,v)|_{[0,\sigma)} = (\overline{u},\overline{v})|_{[0,\sigma)}, 
			\end{align*}
			a.s., on $\{{(u_0,v_0)=(\overline{u}_0,\overline{v}_0)}\}\in \mathfrak{F}_0$, and 
			for $p\ne 2$ we have the additional regularity 
			\begin{equation*}
				u \in  H^{\theta, p}((0,\sigma_n),w_\kappa; H^{2(1-\theta)+s,q}(\mathbb{T}^d) )
				\quad \text{and}\quad v\in  H^{\theta, p}((0,\sigma_n),w_\kappa; H^{2(1-\theta)+s_v,q_v}(\mathbb{T}^d)),
			\end{equation*}
			for each $\theta\in [0,1/2)$ and $ \sigma_n \uparrow \sigma $ as in Definition (def2.2 of the paper)~(equation item_localizing_Seq of the paper).
		} (Proof in the paper; no proof environment follows the statement in the TeX.)

