[Lemma lem-Step 3 of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Let $C$ be the set defined in  (equation eqn-C_set of the paper). Let  $\overline{N}_{a_k}=\left( \overline{N}_{a_k}(t): t\geq 0\right)$ be the $\mathbb{R}$-valued process defined by
\begin{equation}
\overline{N}_{a_k}(t) \coloneqq \sum\limits_{s\leq t} a_k(\Delta \overline{M} (s)) - \int_0^t \int_{Y} a_k(F(s,\overline{u}(s),y))\, \nu (\mathrm{d} y) \, \mathrm{d}s,\;\; t\geq 0.
\end{equation}
Then for every pair  $(s,t)\in C^2_{+}$ 
\begin{equation}
\overline{\mathbb{E}} \bigl[  \overline{N}_{a_k}  (t)\lvert \mathscr{H}_{s} \bigr]= \overline{N}_{a_k}(s).
\end{equation}
Moreover,
\begin{align}
\sup_{k \ge 2}\;\;\sup_{t \in C  }\; \overline{\mathbb{E}} \left[ \lvert{\overline{N}_{a_k}(t)}\rvert^{2} \right] <\infty.
\end{align}

[Lemma lem:sampling-alg-exact-remask of arXiv:2608.23554, 'Provably adaptive sampling with uniform and remasking \\ discrete diffusion models'] Consider the remasking process with parameter \(p_M\) and let \(\rho = \sqrt{1 - p_M}\).
    Recall \(\widehat \mu_i(b)\) defined in~(eq:sampling-alg of the paper):
    \begin{equation*}
        \widehat \mu_i(b) \ \propto\ \Pr(X_{\ell}^i = x_{\ell}^i \mid X_u^i = b)\left(\widehat \Pr(X_0^i = b \mid X_{\ell}^{-i} = x_{\ell}^{-i}) e^{-u} + \nu(u, b)(1 - e^{-u})\right).
    \end{equation*}
    Then, for \(x_{\ell}^i \in [S]\),
    \begin{equation*}
        \widehat \mu_i(b) \ \propto\ \begin{cases}
            \left(\widehat \Pr(X_0^i = b \mid X_{\ell}^{-i} = x_{\ell}^{-i}) + \frac{
            \cosh(u \rho) - 1
            }{S}\right) \left(\bI\{b = x_{\ell}^i\} + \frac{\cosh(\Delta\rho) - 1}{S}\right), \quad &\text{if } b \in [S], \\
            \frac{1}{S} \sinh(u\rho)\sinh(\Delta\rho), \quad &\text{if } b = \mathrm{REMASK}, \\
            0 ,&\text{if } b = \mathrm{MASK}.
        \end{cases}
    \end{equation*}
    For \(x_{\ell}^i = \mathrm{REMASK}\),
    \begin{equation*}
        \widehat \mu_i(b) \ \propto\ \begin{cases}
                        \left(\widehat \Pr(X_0^i = b \mid X_{\ell}^{-i} = x_{\ell}^{-i}) + \frac{
            \cosh(u \rho) - 1
            }{S}\right) \rho \sinh(\Delta \rho), \quad &\text{if } b \in [S], \\
            \rho\sinh(u\rho)\cosh(\Delta\rho), \quad &\text{if } b = \mathrm{REMASK}, \\
            0 ,&\text{if } b = \mathrm{MASK}.
        \end{cases}
    \end{equation*}
    For \(x_{\ell}^i = \mathrm{MASK}\),
    \begin{equation*}
        \widehat \mu_i(b) \ \propto\ \begin{cases}
                        e^{-u}\left(\widehat \Pr(X_0^i = b \mid X_{\ell}^{-i} = x_{\ell}^{-i}) + \frac{
            \cosh(u \rho) - 1
            }{S}\right) \left(1 - e^{-\Delta}\left(\cosh(\Delta \rho) + \rho \sinh(\Delta\rho)\right)\right), \quad &\text{if } b \in [S], \\
            e^{-u}\rho\sinh(u\rho)\left(1 - e^{-\Delta} \left(\cosh(\Delta \rho) + \frac{\sinh(\Delta \rho)}{\rho}\right)\right), \quad &\text{if } b = \mathrm{REMASK}, \\
            1 - e^{-u}\left(\cosh(u \rho) + \rho \sinh(u \rho)\right) ,&\text{if } b = \mathrm{MASK}.
        \end{cases}
    \end{equation*}
    Normalization factor should be computed separately for each of the three cases: \(x_{\ell}^i \in [S], x_{\ell}^i = \mathrm{REMASK},\) and \(x_{\ell}^i = \mathrm{MASK}\).

[Prop prop-busemann-uihbot of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] Let $\{x_k^{\operatorname{b}}\}_{k\in\mathbbm Z}$ be the boundary vertices of the UIBHBOT as in the discussion just after~(equation eqn-uihbot-bdy-time of the paper). There exists a unique function $\mathcal X^{\operatorname{b}} :  \mathbbm Z \to \mathbbm Z$, called the \textbf{Busemann function}, such that $\mathcal X^{\operatorname{b}}(0) = 0$ and the following is true. Let $k,k' \in \mathbbm Z$ and let $\{w_j\}_{j\in\mathbbm N}$ be a sequence of distinct vertices of $M^{\operatorname{b}}$ such that for each $j\in\mathbbm N$, each of $x_k^{\operatorname{b}}$ and $x_{k'}^{\operatorname{b}}$ can be joined to $w_j$ by a directed path in $M^{\operatorname{b}}$. Then
\begin{equation} 
\mathcal X^{\operatorname{b}}(k') -\mathcal X^{\operatorname{b}}(k) = {\operatorname{XDP}}_{M^{\operatorname{b}}}(x_{k'} , w_j) - {\operatorname{XDP}}_{M^{\operatorname{b}}}(x_{k } , w_j) ,\quad \text{for each sufficiently large $j\in\mathbbm N$.}
\end{equation}
Furthermore, the increments $\mathcal X^{\operatorname{b}}(k) - \mathcal X^{\operatorname{b}}(k-1)$ are i.i.d., and if $\mathcal X$ is the Busemann function for $M_{0,\infty}$ as in Theorem~(thm-busemann of the paper), then 
\begin{equation}  
\mathcal X^{\operatorname{b}}(k) - \mathcal X^{\operatorname{b}}(k-1) \overset{d}{=}   \mathcal X(0) - \mathcal X(-1) .
\end{equation}

