	\begin{equation}
		\sup_{\|\mathbf{X}\|_{p\text{-var}}\leq  1}  C(\mathbf X) \leq \sup_{\|\mathbf{X}\|_{\alpha}\leq  1} C_{\alpha}(\mathbf X)<\infty\,.
