body:
[Proposition tara of arXiv:2607.02742, 'Gaussian fluctuations for the parabolic Anderson model with L\'evy white noise'] Let $F\in {\rm dom}(D)$ with $\mathbb{E}[F]=0$ and  ${\rm Var}(F)=\sigma^2 > 0$. Then, 
for any $p,q\in [1,2]$,
\begin{align*}
d_{\rm FM}\left( \frac{F}{\sigma}, Z\right) & \leq d_{\rm W}\left(\frac{F}{\sigma}, Z\right)  \leq    \gamma_1 +  \gamma_2 +  \gamma_3\\
  d_{\rm K}\left(\frac{F}{\sigma}, Z\right) & \leq  \sqrt{ \frac{\pi}{2}} (  \gamma_1 +  \gamma_2)   +  \gamma_4 +  \gamma_5+  \gamma_6 +  \gamma_7,
\end{align*}
where  $Z\sim N(0,1)$ and the seven quantities $ \gamma_1, \ldots,  \gamma_7$ are given as follows:
\begin{align}
\begin{aligned}
 \gamma_1&:=  \frac{2^{\frac2p + \frac12} }{\sqrt{\pi}}
 \sigma^{-2} \bigg( \int_{Z}  \bigg[ \int_{\bf Z}  \| D_{\xi_2}F \|_{2p}  \| D^2_{\xi_1,\xi_2}F\|_{2p} 
  \,  \mathfrak{m}(d\xi_2) \bigg]^p
  \mathfrak{m}(d\xi_1) \bigg)^{\frac1p}
\\
 \gamma_2&:=\frac{2^{\frac2p - \frac12} }{\sqrt{\pi}}
\sigma^{-2} \bigg( \int_{Z}  \bigg[ \int_{\bf Z}   \| D^2_{\xi_1,\xi_2}F\|^2_{2p}  \,  \mathfrak{m}(d\xi_2) \bigg]^p
  \mathfrak{m}(d\xi_1) \bigg)^{\frac1p}
\\
 \gamma_3&:= 2 \sigma^{-(q+1)}\int_{\bf Z} \| D_\xi F \|_{q+1}^{q+1}  \, \mathfrak{m}(d\xi)
\\
 \gamma_4&:= 2^{\frac{2}{p}} \sigma^{-2} \bigg( \int_{\bf Z} \| D_\xi F \|_{2p}^{2p}  \, \mathfrak{m}(d\xi) \bigg)^{\frac1p}
\\
 \gamma_5&:= (4p)^{\frac1p} \sigma^{-2} \bigg( \int_{Z^2} \| D^2_{\xi_1,\xi_2}  F \|_{2p}^{2p}
\, \mathfrak{m}(d\xi_1)\mathfrak{m}(d\xi_2)  \bigg)^{\frac1p}
\\
 \gamma_6&:=(2^{2+p}p)^{\frac1p} \sigma^{-2} \bigg( \int_{Z^2} \| D^2_{\xi_1,\xi_2}  F \|_{2p}^{p}
 \| D_{\xi_1}F \|_{2p}^p
\, \mathfrak{m}(d\xi_1)\mathfrak{m}(d\xi_2)  \bigg)^{\frac1p}\\
 \gamma_7&:=  \frac{  (8p)^{\frac1p} }{\sigma^2}
 \bigg( \int_{Z^2} \| D^2_{\xi_1,\xi_2}  F \|_{2p}
 \| D_{\xi_1}F \|_{2p}  \| D_{\xi_2}F \|_{2p}^{2(p-1)}
\, \mathfrak{m}(d\xi_1) \mathfrak{m}(d\xi_2)  \bigg)^{\frac1p}.
\end{aligned}

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2609.02785, 'Characterization of Stanley-Reisner varieties by their automorphism group'] The following are equivalent:
\begin{enumerate}[label=\textup{(\alph*)}]
\item $\mathcal{R}(\Delta)=\emptyset$;
\item $\operatorname{cl}=\mathrm{id}_\Delta$;
\item every face of $\Delta$ is an intersection of facets;
\item $\mathcal{A}_i(\Delta)=\emptyset$ for every $i\in[n]$;
\item $\Delta$ is fully hidden.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma keyI2 of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Under the same assumption as in the previous lemma, for any $s\in\left[s_0,\frac{e_0\tilde{\mu}_{n,N}}{\tilde{\sigma}_{n,N}}\right]$, when $N$ is large enough,
    \begin{equation*}
        N^{\frac{2}{3}}|D_{n,N}(x_N(s))|\le C(s_0,\gamma)e^{-\frac{s}{2}}
    \end{equation*}
    where $C$ is a constant determined by $s_0$ and $\gamma$

[Definition d:RegularPotential of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] We say that~$\sigma\colon {\mathbb R}^+\to {\mathbb R}$ is a \emph{regular pair potential} if~$\sigma$ is piecewise of class~$\mcC^1$ and~(equation eq:AssSmallScaleInt of the paper) simultaneously holds for~$g=\sigma$ \emph{and}~$g=-\sigma'$.

For any regular pair potential~$\sigma\colon {\mathbb R}^+\to {\mathbb R}$ we call (\emph{repulsive}) \emph{$\sigma$-interaction energy} the function
\begin{equation}
W_\sigma\colon \mbfT\times\mbfM_\circ\longrightarrow\overline{\mathbb R}\,\mathrm{,}\;\, \qquad W_\sigma\colon (\mbfs,\mbfx)\longmapsto \tfrac{1}{2}\sum_{\substack{i,j\\i\neq j}} s_i\, s_j \, \sigma\big({\mssd(x_i,x_j)}\big) \,\mathrm{,}\;\,
\end{equation}
and \emph{attractive $\sigma$-interaction energy} the function~$-W_\sigma$.

[Definition 33 (Good vertices) of arXiv:2604.25877, 'Asymptotic height of Plancherel random trees'] The set of \emph{good vertices} at depth $h$ is:
$$\mathcal G_h^{\mathrm{good}}
:=
\left\{
u:\ |u|=h,\ \mathcal G_{n,\alpha}(u),\ S_h(u)\le (v_\star+\varepsilon_1)h-\omega_n
\right\}.$$

