[Lemma 11 of arXiv:2608.21905, '\bf Ruin theory incorporating MIPP-type jumps'] For each fixed $n\geq 2$, assume the net profit condition $c>\lambda^nm$ holds in our model (\ref{one1}). Also assume $\mathcal{L}_{\xi}(\theta)$ is finite. Then the following equation 
\begin{equation}
\lambda\bigl(g_{n-1}^{\circ}(E[e^{R\xi}]) - 1\bigr) = cR,
\end{equation}
has unique positive solution, which we denote by $\hat{R}_n$.

[Lemma 20 of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] \begin{equation}
\lim_{\lambda \to \infty} \E \left[\lambda \int_A \mu_{\ph}(\dd x) \int_0^\infty \bdec{x}{x}{u}\left[F(u) e^{-\lambda F(u)}1_{\{ \tau_\Sigma>u\}}\right] p^\Sigma_u(x, x) \dd u\right] = c \E[ \mu_\ph(A)],
\end{equation}
for some non-explicit $c>0$ (according to \eqref{eq:goalbridge} we expect $c = c_\gamma = 1/ [\pi(2- \gamma^2/2)]$).

