body:
[Conjecture of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] The chain $\mathbf{X}^{\textup{ord,bal}}$ exhibits cutoff around time
    \begin{equation*}
        T \coloneqq \frac{n \log n}{2} \cdot \max\{1/q, 1/\gamma\},
    \end{equation*}
    where $\gamma$ and $q$ are defined as in Conjecture~(conj:time of the paper). (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Corollary 10 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] Let $(W_n)$ be a sequence in $\Bf$ with $|W_n| \rightarrow \infty$ as $n \rightarrow \infty$.
Assume there is a $p>0$ such that
\begin{align*}
\varphi_j \geq p \qquad \text{for all } j\in \{1,\dots,\alpha\}.
\end{align*}
Then the convergence
\begin{align*}
\frac{\chi_a\big(\Delta_{W_n}\big)-\E{ \chi_a\big(\Delta_{W_n}\big) }}{\sqrt{\V{ \chi_a\big(\Delta_{W_n}\big) }}} \;\xrightarrow{d}\; \mathcal{N}(0,1) \qquad \text{for } n \rightarrow \infty
\end{align*}
holds with the same rates of convergence of the quantities from Theorem \ref{Th:myRCM} as in Theorem \ref{Th:ZGWS1} (when replacing the intensity $\beta$ with $|W_n|$).

[Lemma lem: pivotal event bound for cle outermost of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exists a constant $c_8>0$ such that for any $\mathcal W\in\{\mathcal X^+,\mathcal X^-,\mathcal Y^+,\mathcal Y^-\}$, any $x\in I$, and any boundary condition $\xi$ on $\overline{\Lambda_{d(x)/10}(x)^c}$, 
    we have \begin{equation}
        \bar\mu^{\xi}_{\Lambda_{d(x)/10}(x)}(\mathcal{C}_x \textit{ is pivotal to }\mathcal W)\leq c_8{(\max\{d(x),1\})}^{-\frac{1}{8}}.
    \end{equation}

[Lemma lem: sub-exponential Lp norm of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Subexponential from MGF to $L^p$ bound) }For sub-exponential random variable $X \sim SE(\beta, \alpha)$, defined by the condition:
    \begin{align*}
        \mathbb{E}[e^{\theta|X|}]  \leq A\cdot e^{\beta^2 \theta^2/2}, \quad \forall \theta \in [0,1/\alpha]
    \end{align*}
    We have upper bound for $L^p$ norm, $\forall p \geq 1$, in terms of $\beta$ and $\alpha$.
    \begin{align*}
        \mathbb{E}[|X|^p] &\leq 2e\sqrt{2\beta}A^{1/p} \cdot \bigg( \beta \sqrt{p} + \alpha p \bigg)
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm EL_equations_gauge of arXiv:2506.12171, 'The multinomial dimer model'] Fix $R\subset \mathbb{R}^d$ and boundary value for the gauge flow $b'$. The limiting gauge flow $\alpha:R\to \mathcal{A}=\mathbb{R}^d$ is the unique solution to the following system of differential equations with boundary value $b'$: 
    \begin{itemize}
        \item the equation \begin{align}
            \text{div} (\nabla F(\alpha)) = \sum_{i=1}^d \pd{}{x_i} \pd{}{a_i} F(\alpha) = 0;
        \end{align}
        \item a collection of ${d\choose 2}$ equations of the form 
        \begin{align}
            \pd{ \alpha_j}{x_i} - \pd{\alpha_i }{x_j} = 0,
        \end{align}
        for all $i\neq j$ between $1$ and $d$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

