A_{1,3}=&-\kappa^{-2}\{q_{2}\alpha^{*}x^{*}(1-x^{*})-(\alpha^{*}q_{1}+\beta^{*}q_{2})x^{*}y^{*}+q_{1}\beta^{*}y^{*}(1-y^{*})\},\nonumber\\
