[Lemma SMR_perturbation_estimate of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Suppose that $\|(\sigma_k)_{k\in I}\|_{\ell^2(L^\infty(\mathbb{T}^3))}\le N$. Then for every $\varepsilon>0$ there exists $C_\varepsilon$ depending only on $\varepsilon$ and $g$ such that it holds 
     \begin{equation}
        \|\Delta \omega\|_{H^{-2}_g} + \|B \omega\|_{\mathscr{L}^2( \ell^2, H^{-1})} \le \varepsilon \|\omega\|_{H^{0}_g} + C_\varepsilon \|\omega\|_{H^{-1}}.
    \end{equation}

[Theorem 2 (Limiting law of local field) of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Under the same assumptions as in Theorem~\ref{thm:cavity}, we have
\begin{equation}
  \E\left(\langle U(l_N)\rangle-\int_{\R}U(x)d\nu_N(x)\right)^{2k}\le \frac{C}{N^k},
\end{equation}
where $C$ is a finite constant depending on $k,U,S,D,h$, and the high-temperature bound only. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 (\textsf{Continuity sets for the BLPP geodesics}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] Fix $n\in\Z_{>0}$, $\al\in\R$, and $x,\wt x\in\R$ with
  $x\neq\wt x$.  Then
  \begin{align}
    \PP\bigl(\Gamma_0^{\al}(n)=-x\bigr)=0.
  \end{align}
  Moreover, if
  \[
    A_{\wt x,x}
    =\bigl\{(\wt\ga,\ga):
      \tau_{\wt x,x}(\wt\ga,\ga)\leq n-1
    \bigr\},
  \]
  then
  \begin{align}
    \PP\bigl(
      (\Gamma_{\wt x}^{\al},\Gamma_x^{\al})
      \in\partial A_{\wt x,x}
    \bigr)=0.
  \end{align}

[Definition 9 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] $\Phi$ is said to be \textit{uniformly eventually continuous with respect to a family $\mathfrak{F}\subset\mathcal{A}$ at $x\in\X$} if 
		\begin{equation*}
			\limsup\limits_{x'\rightarrow x}\limsup\limits_{t\rightarrow\infty}\sup_{f\in\mathfrak{F}}|P_tf(x')-P_tf(x)|=0.
		\end{equation*}

[Lemma lem:spread_goodconf of arXiv:2607.08914, 'Linear spreading speed in non-monotone population models'] Let $\tilde C, \tilde \gamma, \tilde v, \tilde C', \tilde \gamma'$ be as in
  Lemmas~(lem:percolation of the paper),~(lem:shift_blocks of the paper). For every
  $\ell, \rho  \in \mathbb{N}$, $a \in \{1,\dots,V_\ell\}$, $\eta_0 \in E^\mathbb{Z}$ such
  that $\abs{ B_\ell^\mathrm{bl}(0) \cap W(\eta_0)}  \ge a$, $z\in \mathbb Z$, and
  $n \in \mathbb{L}_{\mathrm{time}}$ such that $n \ge (\rho+\abs{z}/L_\mathrm{bl}+\ell+1)T_\mathrm{bl}/\tilde v$
  \begin{equation*}
    \mathbb{P}_{\eta_0} \Big(
      \abs[\big]{B_\rho^\mathrm{bl}(\bbracket z ) \cap W(\eta_n)}
      < \frac{p_\nu V_{\rho}}{2} \Big)
    \le \tilde C e^{-\tilde \gamma \rho}
    + \tilde C' (1+V_\rho) e^{ -\tilde \gamma' a},
  \end{equation*}
  and
  \begin{equation*}
    \mathbb{P}_{\eta_0}(\tau_\mathrm{ext}< \infty) \le  \tilde C e^{-\tilde \gamma a}.
  \end{equation*}

