[Definition 5 of arXiv:2606.20169, 'THEORY OF UNCERTAIN PROBABILITY:\\ CAN WE DERIVE THE PROBABILITY DENSITY FUNCTION OF UNCER'] Given a measurable space $\left(\Pi,\mathbb{F}\right)$, the set function $\mathbb{P}$ on $\mathbb{F}$ is a measure with

\begin{longlist}
\item $\mathbb{P}\left(\mathfrak{A}\right)\geq\mathbb{P}\left(\emptyset\right)=0$ for all $\mathfrak{A}\in\mathbb{F}$;
\item 
$\mathbb{P}$ is $\sigma$-additive;
\item 
$\mathbb{P}=\mathcal{P}_{\mathbb{X}}\left(\mathcal{P}_{V_{\gamma}}\left(v_{\gamma}\right)\right)$. 
\end{longlist}

It will be proved that $\mathbb{P}\left(\Pi\right)=1$, and  is referred to as a measure of uncertain probability.

[Definition def:DU of arXiv:2601.10359, 'An Operator It\^o Formula for Volterra Gaussian Processes:\\ The Intrinsic Bracket via Cau'] A Volterra kernel $K$ satisfies the \emph{Decreusefond--\"Ust\"unel conditions} [DU] if:
(1)~$\int_0^T\int_0^t K(t,s)^2\,ds\,dt < \infty$;
(2)~there exists $H\in(0,1)$ such that $|K(t,s)|\leq C|t-s|^{H-1/2}$ for $s<t$;
(3)~$\partial_t K(t,s)$ exists and satisfies integrability conditions ensuring $\Dom(\delta^X)$ is dense.

[Lem exch_repr of arXiv:2606.15339, 'Uniform integrability of the distance to the nearest leaf in random trees'] Conditional on $\mathcal G_n$:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $\tilde d^{(U)}$ is uniform on $\Sigma_{M(\mathcal{T}_n)}$;
\item $\mathbf{P}(\mathcal E_n\mid\mathcal G_n)=1/n$;
\item $(d^{\mathrm{dfs}}_1,\dots,d^{\mathrm{dfs}}_n)\stackrel{d}{=} \left((\tilde d^{(U)}_1,\dots,\tilde d^{(U)}_n)\,\bigm|\,\mathcal E_n\right)$.
\end{enumerate}

[Definition def2.2 of arXiv:2411.13266, '\bf A new maximal regularity for parabolic equations and an application'] Let $\{{\mathbb Q}_k,\ k\in{\mathbb Z}\}$ be a filtration of partitions. For each $t,r\in \mathbb{R}$, $t\neq r$, let a ${\mathcal K}(t,r)\in L({\mathcal H};\widetilde{{\mathcal H}})$ be defined. We say ${\mathcal K}$ is an $L({\mathcal H};\widetilde{{\mathcal H}})$-valued Calder\'{o}n--Zygmund kernel relative to $\{{\mathbb Q}_k,\ k\in{\mathbb Z}\}$ if

(i) for any $t$ and $r_0>0$, ${\mathcal K}(t,\cdot)\in L^1_{loc}(B_{r_0}^c(t),L({\mathcal H};\widetilde{{\mathcal H}}))$, where $B_{r_0}^c(t)=\{r\in\mathbb{R}: |r-t|\geqslant r_0\}$;

(ii) the function $\|{\mathcal K}(t,r)-{\mathcal K}(t,\tau)\|_{L({\mathcal H};\widetilde{{\mathcal H}})}$ is measurable as a function of $(t,r,\tau)\in \mathbb{R}^3\cap\{(t,r,\tau): t\neq r,\,t\neq \tau\}$;

(iii) there is a constant $C_0\geqslant 1$, and for each $Q\in {\mathbb Q}_k$, there is a Borel set $Q^*$ such that $\overline{Q}\subset Q^*$, $|Q^*|\leqslant C_0|Q|$, and
\begin{eqnarray}
\int\limits_{\mathbb{R}\setminus Q^*}\|{\mathcal K}(t,r)-{\mathcal K}_{|k}(t,r)\|_{L({\mathcal H};\widetilde{{\mathcal H}})}dt\leqslant C_0
\end{eqnarray}
for every $r\in Q$, where
\begin{eqnarray*}
{\mathcal K}_{|k}(t,r)=\frac{1}{|Q_k(r)|}\int\limits_{Q_k(r)}{\mathcal K}(t,\tau)d\tau,
\end{eqnarray*}
and $Q_k(r)$ is the unique $\tilde{Q}\in {\mathbb Q}_k$ such that $r\in \tilde{Q}$

[Theorem 14 of arXiv:2607.17177, '2607.17177'] There exists a constant $C>0$ with the following property. For any $T>0$, $\kappa\in\R$ and $\alpha\in(0,1)$, set
\begin{equation*}
    N_*(\kappa,T,\alpha):=\min\left\{N\in\N^+:\mu_{N+1}\geq C\alpha^{-2}\exp\left(C\left(T^{-1}+T|\kappa|+|\kappa|^{2/3}\right)\right)\right\}.
\end{equation*}
If the integer $N$ in \eqref{eq noise sine} satisfies $N\geq N_*$, then the Markov semigroup $\{P_t\}_{t\geq0}$ associated with equation \eqref{sine equation} on $L^2(D)$ is $\alpha'$-asymptotically regular in time $T$ for any $\alpha'\in(\alpha,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

