 k=\nabla^2u-\kappa\otimes\kappa
       +\left(b_nV+\frac{\lambda}{n}\right)g
\end{equation}
is TT and
\begin{equation}
 \cE_gk=(F\circ F)_0
       -\frac{n-4}{2(n-1)}(\nabla^2V)_0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

