[Theorem 28 (Theorem 3.1 of \cite{ks}, with $k=1$) of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] For $p \in (0,1)$, 
\begin{equation}
    \E[\Cnt] = 2^{2^{d-1}} \left(
        \Exp{\sum_{\Gamma \in \cC^\cE} \omega(\Gamma)} 
     + \Exp{\sum_{\Gamma \in \cC^\cO} \omega(\Gamma)} 
    \right) \cdot \Rnd{1 + \Exp{-\Omega(2^d/d^4)}},
\end{equation}
where the cluster expansion series inside the exponentials converge absolutely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p:rs-lc of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] The following implications hold for a polynomial $p\in \mathbb R[z_1,\ldots, z_n]$:
\begin{align*}
    \textup{Real stable} \implies
    \textup{Completely log-concave} \implies
    \textup{Strongly log-concave} \implies
    \textup{Log-concave}
\end{align*}
If $p$ is homogeneous, $p$ is completely log-concave iff it is strongly log-concave. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo teo: weight of arXiv:2412.04918, 'On one dimensional weighted Poincar\'e inequalities for Global Sensitivity Analysis'] Let $\mu \in \mathcal{P}(a,b)$ and
let $g$ be a centered function in $\mathscr{C}^{1,2}_{*}(a,b)$. 
If $a$ (resp. $b$) is finite we assume that $g'(a)\neq 0$, or that $g'(a)=0$ and $g''(a)\neq 0$ (resp. $g'(b)\neq 0$, or that $g'(b)=0$ and $g''(b)\neq 0$). 
Then
\begin{itemize}
\item The function
\begin{equation}

w_g(x) = -\frac{1}{g'(x)\rho(x)}\int_{a}^x g(y)\rho(y)\,dy,\quad x\in (a,b), 
\end{equation}
belongs to $\mathcal{W}(a,b)$. If $a$ is finite,
the value of $w_g(a)$   depends on $g$:
\begin{itemize}
\item If $g'(a)\neq 0$, then $w_g(a)=0$.
\item If $g'(a)=0$ and $g''(a)\neq 0$, then $w_g(a)=-g(a)/g''(a)>0$.
\end{itemize}
The same conclusion holds for $w_g(b)$ if $b$ is finite.
\item  If in addition $g\in L^2(\mu)$ (which is satisfied if $a$ and $b$ are finite), then the  weighted Poincar\'e inequality (equation eq: poincar\'e of the paper) holds with weight $w_g$ and Poincar\'e constant $C_P(\mu,w_g) = 1$. Furthermore, the inequality is saturated by $g$.
\end{itemize}

