\begin{equation}

(w_g g'\rho)' =
-g \rho ,
\end{equation}
so that we get on $(a,b)$, 
\begin{equation*}
w_g' = - \frac{g}{g'} - w_g \left(\frac{g''}{g'}+\frac{\rho'}{\rho}\right).
