body:
[Definition 13 (Classical Solution to the Variational Inequality) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] A mapping $V \in \mathcal{C}^{1,2}([0, T) \times H) \cap \mathcal{C}([0, T] \times H)$ is a \emph{classical solution} to the parabolic variational inequality if it satisfies:
\begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
    \item \emph{Regularity.} $\nabla V(t, x) \in \mathrm{Dom}(A^*)$ for all $(t, x) \in [0, T) \times H$, and the map $(t, x) \mapsto A^* \nabla V(t, x)$ is continuous.
    \item \emph{Terminal condition.} $V(T, x) = \Psi(x)$ for all $x \in H$.
    \item \emph{Pointwise equation.} The variational inequality holds pointwise on $[0, T) \times H$:
    \begin{equation}

        \max \left( -\partial_t V(t, x) - \mathcal{L} V(t, x) - f(t, x), \, V(t, x) - \Phi(t, x) \right) = 0,
    \end{equation}
\end{enumerate}
where the differential operator $\mathcal{L}$ is defined by:
\begin{equation}

    \mathcal{L} V(t, x) := \langle x, A^* \nabla V(t, x) \rangle_H + \langle b(t, x), \nabla V(t, x) \rangle_H + \frac{1}{2} \Tr \big( \sigma(t, x) \sigma^*(t, x) \nabla^2 V(t, x) \big).
\end{equation}

[Lemma 20 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Let $r_0>0$. For every multi-index $\beta=(\beta_1,\dots,\beta_d)\ge0$, there exist constants $c_1,c_2,c_3>0$ such that for all $t>0$ and all $x,y\in \mathbb{R}^d$ such that $|x-y|>r_0$ it holds that
		\begin{align}
			|\partial^\beta_x p(t,x,y)|&\le c_1(\beta, r_0),\\
			|\partial^\beta_x p^D(t,x,y)|&\le c_3(\beta, r_0,\de(x)),
		\end{align}
		and for all $t>0$ and $x,y\in D$ it holds that
		\begin{align}
			|\partial^\beta_x \mathds{E}^x\left[p(t-T_D,A({T_D}),y);t>T_D\right]|&\le c_2(\beta, \de(x)). 
		\end{align}
		Moreover, both $x\mapsto p(t,x,y)$, $x\in \mathbb{R}^d$, and $x\mapsto p^D(t,x,y)$, $x\in D$, are infinitely differentiable in $x\ne y$, and for every multi-index $\beta$ it holds that $\lim_{|x|\to\infty}\partial^\beta_x p(t,x,y)=0$.

