[Definition 6 of arXiv:2512.10761, 'Special times for the point set process of the Brownian Net'] For any point $z\in\R^2$, we say it is a
   \begin{itemize}
       \item $C_n$ point if there is an incoming path $\pi\in\mathcal{N}$ at $z$ but no incoming path $\pi\in\mathcal{W}^l\cup\mathcal{W}^r$ at $z$,
       \item $C_l$ point if there is an incoming path $l\in\mathcal{W}^l$ at $z$ but no incoming path $r\in\mathcal{W}^r$ at $z$,
       \item $C_r$ point if there is an incoming path $r\in\mathcal{W}^r$ at $z$ but no incoming path $l\in\mathcal{W}^l$ at $z$.
   \end{itemize}

[Lemma 18 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] Fix~$k \ge 1$. For any~$\eps \geq \delta > 0$ and~$x,y \in \bbR^2$ with~$|x|/16 \geq |y| \geq 4\eps$,
\begin{align}
\widetilde\pi_{2k}^\delta(x,y,\eps) \asymp \pi_{2k}^\delta(|x|,|y|)^2\pi_1^\delta(\eps,|y|)^4.

\end{align}

