[Lemma lem:fubini of arXiv:2602.14617, 'Stochastic Burgers equation driven by multiplicative Rosenblatt noise: local existence, un'] Let $\Phi: [0,T] \times \mathbb{R} \times \Omega \to \mathbb{R}$ be such that:
\begin{enumerate}
    \item For each $(s,x)$, $\Phi(s,x) \in \mathbb{D}^{2,2}$.
    \item The map $(s,x) \mapsto \Phi(s,x)$ is measurable.
    \item $\int_0^T \int_\mathbb{R} \bigl( \mathbb{E}[|\Phi(s,x)|^2] + \mathbb{E}[\|\mathrm{D}\Phi(s,x)\|_{L^2(\mathbb{R})}^2] + \mathbb{E}[\|\mathrm{D}^2\Phi(s,x)\|_{L^2(\mathbb{R})^{\otimes2}}^2] \bigr) dx \, ds < \infty$.
\end{enumerate}
Then
\[
\int_\mathbb{R} \left( \int_0^T \Phi(s,x) \, \delta \mathcal{R}_s \right) dx = \int_0^T \left( \int_\mathbb{R} \Phi(s,x) dx \right) \, \delta \mathcal{R}_s \quad \text{a.s.}
\]

[Lemma 45 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$ with $d\neq 6$, there exist $C,C',c,c'>0$ such that for any $N\ge C$, $v,v'\in \widetilde{B}(cN)$ and $w,w'\in \widetilde{B}(10N)\setminus \widetilde{B}(N)$ with $|w-w'|\ge N$, 
 	  \begin{enumerate}


 	\item  When $ |v-v'|\le 1$, for any $D\subset [\widetilde{B}(C'N)]^c$, 
 	\begin{equation}
 		\mathbb{P}^{D}\big( \mathsf{H}_{v',w'}^{v,w}  \big)\asymp |v-v'|^{\frac{3}{2}}N^{-[(\frac{3d}{2}-1)\boxdot (2d-4)]}; 
 	\end{equation}



 	\item When $ |v-v'|\ge 1$, if there exists $n\in [1,c'N]$ such that $v,v'\in \widetilde{B}(10n)\setminus \widetilde{B}(n)$, then for any $D\subset \widetilde{B}(\frac{n}{C'})\cup [\widetilde{B}(C'N)]^c$, 
 	\begin{equation}
 		\mathbb{P}^{D}\big( \mathsf{H}_{v',w'}^{v,w}  \big)\asymp |v-v'|^{(3-\frac{d}{2})\boxdot 0}N^{-[(\frac{3d}{2}-1)\boxdot (2d-4)]}. 
 	\end{equation}


 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2504.04860, 'Stochastic differential equations driven by fractional Brownian motion: dependence on the '] Let $\alpha \in (0,\frac{1}{2})$ and $g\in W_2^{1-\alpha}([0,T];\mathbb{R}^m)$. Moreover, let $\mu \in C_b^{3}(\mathbb{R}^d;\mathbb{R}^d)$ and $\sigma \in C_b^{3}(\mathbb{R}^d;\mathbb{R}^{d \times m})$. Denote by $x \in W^{\alpha}_1([0,T];\mathbb{R}^d)$ the solution of 
 	\begin{align*}
 		x_t = x_0 + \int_0^t \mu(x_s) \,\mathrm{d} s + \int_0^t \sigma(x_s) \,\mathrm{d} g_s, \qquad t \in [0,T].
 	\end{align*}
 	The mapping $$\Gamma \colon W^{1-\alpha}_2([0,T];\mathbb{R}^m) \to W^\alpha_1([0,T];\mathbb{R}^d), \,\, \ g \mapsto x(g),$$ is Fréchet differentiable.
 	For $h \in W^{1-\alpha}_2([0,T];\mathbb{R}^m)$ its derivative is given by
 	\begin{align*}
 		\big(\Gamma'(g)h\big)(t) = \int_0^t \Phi_t(s) \,\mathrm{d} h_s,
 	\end{align*}
 	where $\Phi_t(s) \in \mathbb{R}^{d\times m}$ is defined as follows: letting $\partial_k$ denote the partial derivative with respect to the $k$-th variable, $s \mapsto \Phi_t(s)$ satisfies
 	\begin{align*}
 		\Phi^{ij}_t(s) = \sigma^{ij}(x_s) + \sum_{k = 1}^d \int_s^t \partial_k \mu^i(x_u) \Phi^{kj}_u(s) \,\mathrm{d} u + \sum_{k =1}^{d} \sum_{l=1}^m \int_{s}^t \partial_k \sigma^{il}(x_u) \Phi^{kj}_u(s) \,\mathrm{d} g_u^l
 	\end{align*}
 	for $ 0 \leq s \leq t \leq T$ and $\Phi^{ij}_t(s) = 0$ for $s>t$, where $i = 1, \dots,d, \ j = 1, \dots,m$. (Proof in the paper; no proof environment follows the statement in the TeX.)

