[Theorem Theorem_DBM_moments of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] Fix $N$ and let $(Y_1(\tau)\ge Y_2(\tau)\ge \dots\ge Y_N(\tau))$ denote the DBM started from zero initial condition. For each $m=1,2,\dots$ and each $0\le \tau_1\le \tau_2\le \dots\le \tau_m$, we have
 \begin{multline} 
  \mathbb E \left[ \prod_{\ell=1}^m \left(\sum_{i=1}^{N} \Bigl(Y_i(\tau_\ell)\Bigr)^{k_\ell}\right) \right]= \mathcal P_{k_m}^{N} \Biggl[\exp\left(\frac{\tau_m-\tau_{m-1}}{2} \sum_{i=1}^N (x_i)^2\right)  \mathcal P_{k_{m-1}}^{N} \Biggl[ \\  \cdots \mathcal P_{k_2}^{N} \Biggl[\exp\left(\frac{\tau_2-\tau_1}{2} \sum_{i=1}^N (x_i)^2\right) \mathcal P_{k_1}^{N} \Biggl[\exp\left(\frac{\tau_1}{2} \sum_{i=1}^N (x_i)^2\right)\Biggr]\dots\Biggr]_{x_1=\dots=x_N=0},
 \end{multline}
 where in the product we alternate applications of $\mathcal P_{k_\ell}^N$ and multiplications by $\exp(\cdot)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 13 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that conditions \ref{H0}, \ref{H1}, \ref{H2b}, \ref{H3} and \eqref{eq:cond-1} hold. For every $n\in\N$, $k\in\{1,\ldots,n\}$, $i\in\{-,+\}$ and every continuous function $g:[0,T]\times H_n\rightarrow \R$ satisfying 
\[
\sup_{t\in [0,T]}\norm{g(t,\cdot)}_{C^\theta_b(H_n)}<\infty,
\]
let $\mathfrak c>{\mathfrak c}_0$ and $u_{n,k}^{(i)}$ be the unique solution to \eqref{Def:Unki} given by Theorem \ref{Thm: soluzione-kolmogorov}.\\
Then, there exists ${\mathfrak{C}}_1=\mathfrak C_1({\mathfrak c})$ independent of  $T>0$, $n\in\N$, $k\in\{1,\ldots,n\}$, $i\in\{-,+\}$ and $g$ such that
\begin{align}
&\sup_{t\in [0,T]}\norm{\mathcal{V}_n^*\nabla_x u_{n,k}^{(i)}(t,\cdot)}_{C_b(H_n;U)}\leq \mathfrak{C}_1r_{k,i}^{\gamma_1\theta+\gamma_2(1-\theta)-1}\sup_{t\in [0,T]}\norm{g(t,\cdot)}_{C^\theta_b(H_n)},\\
&\lim_{{\mathfrak c}\rightarrow \infty}\mathfrak{C}_1=0,
\end{align}
where $r_{k,i}$ is defined in \eqref{eq:aut-r}, $\gamma_1$ and $\gamma_2$ are given by \eqref{G1} $($or \eqref{G1v}$)$ and \eqref{G2} $($or \eqref{G2v}$)$, respectively.\\ 
If, in addition, we assume that
\begin{equation}
\theta>\max\left\{\frac23,\frac{2\delta+(2\alpha-1)\vee0}{2\delta+\alpha}\right\},
\end{equation}
then there exist $\mathfrak C_2=\mathfrak{C}_2({\mathfrak c})$ and $\mathfrak C_3=\mathfrak{C}_3({\mathfrak c})$  independent of  $T>0$, $n\in\N$, $k\in\{1,\ldots,n\}$, $i\in\{-,+\}$ and $g$ such that
\begin{align}
&\sup_{t\in [0,T]}\norm{\nabla_x u_{n,k}^{(i)}(t,\cdot)}_{C_b(H_n;H_n)}\leq \mathfrak{C}_2r_{k,i}^{\gamma_3(1-\theta)-1}\sup_{t\in [0,T]}\norm{g(t,\cdot)}_{C^\theta_b(H_n)}, \\
&\sup_{t\in [0,T]}\norm{D_x\left[\mathcal{G}_n^*\nabla_x u_{n,k}^{(i)}(t,\cdot)\right]}_{C_b(H_n;\mathcal{L}(H_n;U))}\leq \mathfrak{C}_3r_{k,i}^{\gamma_3(1-\theta)-1/2}\sup_{t\in [0,T]}\norm{g(t,\cdot)}_{C^\theta_b(H_n)}
,\\
&\lim_{{\mathfrak c}\rightarrow \infty}\mathfrak{C}_2=\lim_{{\mathfrak c}\rightarrow\infty}\mathfrak{C}_3=0,
\end{align}
where $\gamma_3$ is given by \eqref{G4} $($or \eqref{G4v}$)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 7 of arXiv:2604.10705, '#1'] Let $F \in \mathscr{C}^{1,2}_l([0,T],\mathbb{R}^d)$, and let $\gamma \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$ satisfy \eqref{path_lipchitz}. Suppose that $D^{\gamma}F$ exists and that $DF$, $\nabla F$, and $D^{\gamma}F$ are all right-continuous in time. Then
\begin{align}
D^\gamma F(t, x_{\wedge t}) = D F(t,x_{\wedge t})+\langle \nabla F(t,x_{\wedge t^-}), \gamma(t,x_{\wedge t})\rangle,
\end{align}
where $\nabla F = (\partial_1 F,\ldots, \partial_d F)$ and $\langle \cdot, \cdot \rangle$ is the Euclidean inner product. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.29761, '2608.29761'] There exist constants $c,\delta_0>0$ such that for every $\gamma\in\Pi_p$, and every $0<\delta\le \delta_0$, we have
\begin{equation}	
\Lambda\left(B^{\delta}_\gamma\right)\leq C\delta^{2n-1}e^{-(n-1)\len(\gamma)}.
\end{equation}

