[Proposition prop:positive-generator of arXiv:2607.18070, 'The Brownian loop-catcher'] For every finite \(E\subset V\) and every \(0\le\lambda\le1\), the matrix
\(\mathcal A_\lambda^E\) satisfies:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
\item \(\mathcal A_\lambda^E(U,S)=0\) unless \(S\subset U\);
\item each column sum is zero;
\item if \(S\subsetneq U\), then \(\mathcal A_\lambda^E(U,S)\ge0\);
\item if \(S\ne\varnothing\), \(S\subsetneq U\), and some connected component
of \(G_E^{\rm und}[U]\) is disjoint from \(S\), then
\(\mathcal A_\lambda^E(U,S)=0\).
\end{enumerate}

[Definition 18 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] Let $1<\alpha<2$. A $[0,\infty)$-valued Markov process is called a $\alpha$-stable continuous-state branching process ($\alpha$-stable CSBP) with scaling constant $c_0>0$ if it has transition semigroup $(Q_t)_{t\geq 0}$ defined by
	\begin{equation}
		\int_0^\infty e^{-\lambda y}Q_t(x,\d y)=e^{-xu^\lambda(t)}, \quad \lambda\geq 0,x\geq 0,
	\end{equation}
	where $t\mapsto u^\lambda(t)$ is the unique positive solution of 
	\begin{equation}
		\frac{\d u^\lambda(t)}{\d t}=-c_0[u^\lambda(t)]^\alpha,\quad u^\lambda(0)=\lambda.
	\end{equation}

[Theorem 7 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, and $p\in [1,2)$,
\begin{equation}
    \max_{J\subseteq[n]:|J|=k}\left\|\Dop_J f\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-partial-isoper-Boolean}}}(p)^k\, \frac{\Wop^{\geq k}(f)}{\binom{n}{k}} \left[1+ \frac{1}{2k} \ln\left(\frac{\binom{n}{k}}{\Wop^{\geq k}(f)}\right)\right]^k,
\end{equation}
where $C^{\text{\rm\ref{thm:high-order-partial-isoper-Boolean}}}(p) = \left(1+\frac{1}{\upe(2-p)}\right)^{-1} \gtrsim 2-p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Bernoulli of arXiv:2607.10545, 'On a conjecture of Lamkin and Tkocz: Log-convexity of moments of Bernoulli sample means'] Let $p \geq 1$ and $\theta \in [0,1]$, and let $X_1, X_2, \ldots$ be i.i.d.\ $\operatorname{Bernoulli}(\theta)$ random variables. Define the sample mean by $\bar X_n = n^{-1}(X_1 + \cdots + X_n)$. For $n \in \mathbb{N}$, define
\begin{equation}
b_n(p,\theta) \vcentcolon= \mathsf{E}(\bar X_n^p) = \sum_{k = 0}^n \binom{n}{k}\left(\frac{k}{n}\right)^p\theta^k(1 - \theta)^{n - k}.
\end{equation}
Then the sequence $\{b_n(p,\theta)\}_{n \geq 1}$ is log-convex. Equivalently,
\begin{equation}
b_n(p,\theta)^2 \leq b_{n - 1}(p,\theta)b_{n + 1}(p,\theta), \qquad n \geq 2.
\end{equation}
If $p > 1$ and $0 < \theta < 1$, then every inequality in (equation eq:main.log.convexity of the paper) is strict. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Kirchhoff's formula for infinite graphs) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Suppose $(G, \weight)$ is an infinite connected weighted graph and let $\bP^\weight_G$ be the law of the (wired) USF, then
	\begin{equation*}
	    \bP^\weight_G(e \in \cT) = \weight(e) \effR{G, \weight}{e^-}{e^+},
	\end{equation*}
    where
    \begin{equation} 
        \effR{G, \weight}{e^-}{e^+} = \left\{ \Vert\theta\Vert^2_r \, : \, \theta \text{ is a unit flow from } e^- \text{ to } e^+ \right\}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 14 of arXiv:2607.22892, 'Mirror Langevin diffusions: Convergence rates and Markov chain approximations'] Assume that V is increasing if and only if $u''$ is decreasing. Moreover, 
    \begin{equation}
    V''(x) \ge \lambda u''(x) - \frac{1}{2} (Su')(x), \quad \forall\; x \in \rr. 
    \end{equation}
    Then $(\mani, g, e^{-V})$ satisfies $\CD(\lambda, \infty)$ condition.

