[Theorem 54 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that the assumptions in Section \ref{Ass-Abstract formulation} hold and that $\bX_0 \in\mathbb{H}$. Then the following assertions hold. 
\begin{trivlist}
\item[(i)]   
There exists a measure $\mathbb{P}_T$ on $\bZ_T$ solving the  martingale problem $(\bX_0,\bF,\newG_0)$ in the sense of Definition \ref{def-martingale-solution}.
\item[(ii)]
The above measure $\mathbb{P}_T$ satisfies
     \begin{equation}
       \mathbb{E}^{\mathbb{P}_T} \sup_{s \in [0,T]} \Vert \bX(s) \Vert_{\nHB}^2  + \mathbb{E}^{\mathbb{P}_T} \Vert \bX \Vert_{L^2(0,T;\StokesV \times \zero{H}{2})}^2< \infty,
     \end{equation}
and
\begin{align}

\mathbb{E}^{\mathbb{P}_T} \Vert \phi \Vert_{L^4(0,T;\newone{H})}^4<\infty,
\\

\mathbb{E}^{\mathbb{P}_T} \Vert \phi \Vert_{L^\beta(0,T;\newone{V})}^\beta<\infty.
\end{align}
\item[(iii)]
If $d=2$, we have $\mathbb{P}_T$-a.s.
     \begin{equation*}
       \Vert \bF(\bX) \Vert_{L^2(0,T;\mathbb{V}^\prime)}^2< \infty.
     \end{equation*}
 \end{trivlist} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm l:automorphism-action-resampled of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Fix $B\in\mathcal{B}(\mathbb{R}^2)$ and let $\xi,\eta_B : \Xi_\mathrm{re} \to \Xi$ be the white noises defined in (equation e:def-xi-eta of the paper).
    Then for $\mathtt{Q}, \mathrm{Q},\mathcal{Q}$ as above, we have
    \begin{align}
        \mathcal{Q} \circ \xi = 
        \xi \circ (\mathcal{Q},\mathcal{Q})
        \qquad\text{and}\qquad
        \mathcal{Q} \circ \eta_B = \eta_{\mathtt{Q}^{-1}(B)}\circ (\mathcal{Q},\mathcal{Q}),
    \end{align}
    where $\mathtt{Q}^{-1}(B)$ denotes the image of $B$ under the map $\mathtt{Q}^{-1}:\mathbb{R}^2\to\mathbb{R}^2$.

    In particular, since $(\mathcal{Q},\mathcal{Q})$ preserves $\mathbb{P}_\mathrm{re}$, we have the equality of joint distributions
    \begin{align}
        (\mathcal{Q}\circ \xi,\, \mathcal{Q}\circ \eta_B) \overset{d}{=}
        (\xi,\, \eta_{\mathtt{Q}^{-1}(B)}).
    \end{align}

