body:
[Theorem 3 (Lower bounds) of arXiv:2608.30304, '2608.30304'] Write $x=\cos\theta$, $\theta\in[0,\pi]$.
\begin{enumerate}
\item[(i)] For every $n\ge0$,
\[
\begin{aligned}
F_{n,\frac12,-\frac12}(x)
 &=\sqrt{\tfrac2\pi}\,\bigl|\sin (n+\tfrac12)\theta\bigr|,\\
F_{n,-\frac12,\frac12}(x)
 &=\sqrt{\tfrac2\pi}\,\bigl|\cos (n+\tfrac12)\theta\bigr|,\\
F_{n,\frac12,\frac12}(x)
 &=\sqrt{\tfrac2\pi}\,\bigl|\sin (n+1)\theta\bigr|,
\end{aligned}
\]
while $F_{n,-\frac12,-\frac12}(x)=\sqrt{2/\pi}\,|\cos n\theta|$ for $n\ge1$ and
$F_{0,-\frac12,-\frac12}\equiv\pi^{-1/2}$. Apart from this degree-zero
exception, the maxima are $\sqrt{2/\pi}$. In particular every admissible
constant in either \eqref{eq:main} or \eqref{eq:EMN-corollary} is at least
$\sqrt{2/\pi}$.
\item[(ii)] For every fixed $n\in\Nzero$ and every $\alpha\ge-1/2$,
\begin{equation}
F_{n,\alpha,-\frac12}(-1)^2
=\frac{(2n+\alpha+\tfrac12)\,\Gamma(n+\tfrac12)\,\Gamma(n+\alpha+\tfrac12)}
{\pi\,\Gamma(n+1)\,\Gamma(n+\alpha+1)},
\end{equation}
the right-hand side being read by continuous extension at
$(n,\alpha)=(0,-\frac12)$, where it equals $1/\pi$. Consequently
\begin{equation}
F_{n,\alpha,-\frac12}(-1)\sim
\Bigl(\frac{\Gamma(n+\tfrac12)}{\pi\,\Gamma(n+1)}\Bigr)^{1/2}\alpha^{1/4}
\qquad(\alpha\to\infty),
\end{equation}
so the fixed-degree exponent $1/4$ in $\mathcal E_n$ cannot be lowered.
\item[(iii)] For every fixed $A\ge-1/2$ and $z>0$,
\begin{equation}
 \lim_{n\to\infty}F_{n,A,A}\!\left(\cos\frac zn\right)
 =\sqrt z\,|J_A(z)|.
\end{equation}
Moreover, there is an absolute constant $c>0$ such that, for every sufficiently
large $A$, there exists an integer $n_A$ with $n_A+1\ge(2A+1)^3$ for which
\begin{equation}
 F_{n_A,A,A}\!\left(\cos\frac A{n_A}\right)\ge cA^{1/6}
\end{equation}
holds. Hence, along this sequence, $S=2A+1$, and the term $S^{1/6}$ in
$\mathcal E_n(S)$ cannot be omitted even though
$S^{1/4}(n+1)^{-1/12}\le1$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Maintheorem 4 of arXiv:2609.02878, '2609.02878'] Let $\pi: X\rightarrow Y$ be a $\mathbb{P}^1$-bundle between two projective manifolds. Suppose the
limiting cohomology class of  \eqref{eq:ammp-flow-intro} is the pullback of 
 a K\"ahler class on \(Y\) by $\pi$. Then there exit 
 \(0< c< C<\infty\) such that for any $0\leq t <T$ and $q\in Y$, we have 
 \smallskip
\begin{equation}
 \sup_{x\in X}
 (T-t)|\Rm(g(t))|_{g(t)}(x)\le C, 
\end{equation} 

\begin{equation}
 c\sqrt{T-t}
 \le \operatorname{diam}_{(X,g(t))}X_q
 \le \operatorname{diam}_{(X_q,g(t)|_{X_q})}X_q
 \le C\sqrt{T-t},
\end{equation}

where $X_q=\pi^{-1}(q)$ is the fibre of $X$ over $q$, $\operatorname{diam}_{(X,g(t))}X_q$ is the extrinsic diameter by the ambient distance on \(X\) and $\operatorname{diam}_{(X_q,g(t)|_{X_q})}X_q$ is 
 the intrinsic diameter by the induced metric on \(X_q\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] Assume that $\mu_0 \in \mathcal{N}_\mathcal{S}^{\#}$ has the form 
    \begin{align*}
        \mu = \sum_{i} \delta\{s^i\}
    \end{align*}
    for $s^i \in \mathcal{S}$ (meaning $\kappa^i=1$ for all $i$ in \eqref{Eqn: Form of bfivm's}). Then this remains true of $\mu_t$ for all $t\geq0$.

[Theorem 91 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] For any $n>0$, $(t,x)$, and
  $s\geq 0$  
\begin{equation}

E_{t,x}\sup_{r\in[0,t]}|x_{ r}-x_{0}|^{ n}
\leq N(  t ^{ n/2}+ t ^{ n}),
\end{equation}
where $N=N(n, \rho_{b},d,\delta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma cor:decor of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Assume that $\phi_\ell\randin \mathcal{C}^\infty(M)$ is a sequences of Gaussian fields that satisfies a $\mathcal{C}^k$ scaling limit as in (def:scalim of the paper), with parameters $\mathsf P_\ell=(K, \sigma_\ell,\lambda_\ell, 0,\rho)$. Let $\|j^{2k}_rK\|=\max_{0\le i\le 2k}|\frac{d^i}{dr^{i}}K(r)|$ and let $\mathfrak{D}_\ell(r)$ denote the error in the range $(\frac{r}{\lambda_\ell},\frac{r}{\lambda_\ell})$. Then, 
\begin{equation} 
\sup_{\substack{x,y\in M,
\\
\mathrm{dist}(x,y)= \frac{r}{\lambda_\ell}}
}\sigma(\phi_\ell)^{-2}\|j^{k,k}_{x,y}E_\ell\|_ {g^{\lambda(\phi_\ell)}}
\le  
\mathrm{O}(1)\max\left\{\|j^{2k}_rK\|,\mathfrak{D}_\ell(r)\right\}.
\end{equation}

