body:
[Definition of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] (Local) chiral residue conditions can be imposed in families as follows:
  \begin{enumerate}
  \item
    A \defined{family of chiral residue conditions} $(B,f,{\mathbf{R}}^\pm)$ consists of:
    \begin{enumerate}
    \item
      a tame Fréchet manifold $B$,
    \item
      a tame smooth map $f \mskip0.5mu\colon\thinspace B \to \mathbf{Dir} \times \mathbf{Ram}$, and    
    \item
      a tame Fréchet space subbundle ${\mathbf{R}}^\pm \subseteq f^*\mathbf{G}^\pm$.
    \end{enumerate}
    Set
    \begin{equation*}
      \mathbf{E}_{{\mathbf{R}}^\pm}^\pm \coloneq \paren{f^*\mathbf{res}^\pm}^{-1}({\mathbf{R}}^\pm)
    \end{equation*}
    and denote the restriction of $f^*{\mathbf{D}}$ to $\mathbf{E}_{{\mathbf{R}}^\pm}^\pm$ by
    \begin{equation*}
      {\mathbf{D}}_{{\mathbf{R}}^\pm}^{\pm} \mskip0.5mu\colon\thinspace \mathbf{E}_{{\mathbf{R}}^\pm}^\pm \to f^*\mathbf{F}^\mp.
    \end{equation*}
  \item
    \begin{enumerate}
    \item
      Decompose the universal residue bundle $\check {\mathbf{S}}$ as
      \begin{equation*}
        \check {\mathbf{S}} = \check {\mathbf{S}}^+ \oplus \check {\mathbf{S}}^-
      \end{equation*}
      into the \defined{universal chiral residue bundles} $\check {\mathbf{S}}^\pm$ over $\mathbf{Br}$.
    \item
      A \defined{family of local chiral residue conditions} $({\mathbf{B}},f,{\mathbf{V}}^\pm)$ consists of:
      \begin{enumerate}
      \item
        a tame Fréchet manifold ${\mathbf{B}}$,
      \item
        a tame smooth map $f \mskip0.5mu\colon\thinspace {\mathbf{B}} \to \mathbf{Dir} \times \mathbf{Ram}$, and
      \item
        a subbundle ${\mathbf{V}}^\pm \subseteq (p^*f)^* \check {\mathbf{S}}^\pm$.
      \end{enumerate}
      Here $f^*p \mskip0.5mu\colon\thinspace f^*\mathbf{Br} \to {\mathbf{B}}$ is the pullback of the universal branching locus and $p^*f \mskip0.5mu\colon\thinspace f^*\mathbf{Br} \to \mathbf{Br}$ is the projection map.
    \item
      A family of local chiral residue conditions $({\mathbf{B}},f,{\mathbf{V}}^\pm)$ defines a family of chiral residue conditions $({\mathbf{B}},f,{\mathbf{R}}^\pm)$
      such that for every $b \in {\mathbf{B}}$ 
      \begin{equation*}
        {\mathbf{R}}_b^\pm \coloneq \Gamma(Z_b,{\mathbf{V}}^\pm|_{Z_b}) \subseteq \Gamma(Z_b,\check S_{{\mathbf{p}}_b}^\pm)
        \quad\text{with}\quad    
        ({\mathbf{p}}_b;Z_b,[{\mathfrak l}_b]) \coloneq f(b).
        \qedhere
      \end{equation*}
    \end{enumerate}
  \end{enumerate}

[Theorem pert of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Let $b \in L_{\mathrm{loc}}^1(\mathbb{R}^d ; \mathbb{R}^d), \operatorname{div} b \in L_{\mathrm{loc}}^1(\mathbb{R}^d)$ and $u_0 \in L^{\infty}(\mathbb{R}^d)$. A  measurable process $u \in L^{\infty}([0,T] \times\mathbb{R}^d\times\Omega)$ is a  weak$^\ast$-$\mathrm{L}^{\infty}$-solution of the SPDE (equation eqn-transport-Markus of the paper) (in the sense of Definition (def-transport-weak-2 of the paper)) if and only if, 
{there exists $M>0 $ such that 
\begin{align}
    \sup_{t\in[0,T]}\| u(t, \cdot,\omega) \|_{L^\infty(\mathbb{R}^d)} \leq M,\quad\mathbb{P}\text{-a.s.},
\end{align}
}
 for every $\theta \in C_c^{\infty}(\mathbb{R}^d)$, $u_t(\theta):=\int_{\mathbb{R}^d} \theta(x) u(t, x) d x$ is $\mathbb{F}$-adapted and it has  c\`adl\`ag paths $\mathbb{P}$-a.s.  and the perturbative equation
\begin{align}
u_t(\theta)= &\int_{\mathbb{R}^d} \theta(x+L_t) u_0( x) d x\nonumber \\
& +\int_0^t  \int_{\mathbb{R}^d}\Big[b(x) \cdot D \theta(x+L_t-L_r)+\operatorname{div} b(x) \theta(x+L_t-L_r)\Big] u(r,x) d x\, d r
\end{align}
holds almost surely in $\omega \in \Omega$, for every $t \in[0, T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:left-linf of arXiv:2602.07920, 'On the position matrix of single-shelf shuffle and card guessing'] Let $n\ge 2$ and let $i\in \mathcal{E}_n$. Then
\begin{equation}
\|\widetilde\zeta^{(i)}\|_\infty
:= \max_{1\le a\le n}|\widetilde\zeta^{(i)}(a)|
\le \frac{2^i}{i!(n-i)}.
\end{equation}

