\bigl(\mathcal G^{(\beta)}_{(r-1),i^c}\bigr)'
\bigl(s_{\beta,k}^{(i)}\bigr)}
&=
\frac{\beta^{-1}\xi_{\beta,k-1}^2}{\theta_i^2}
\bigl(1+o(1)\bigr).
\end{aligned}
\end{equation}

\item
As \(\theta_i\to-\infty\),
\begin{equation}
\begin{aligned}
s_{\beta,1}^{(i)}
&=
\theta_i^2\bigl(1+o(1)\bigr),
&\qquad
-\frac{1}{
\bigl(\mathcal G^{(\beta)}_{(r-1),i^c}\bigr)'
\bigl(s_{\beta,1}^{(i)}\bigr)}
&=
2|\theta_i|+o(1).
\end{aligned}
\end{equation}

\item 
If, in addition, \(\beta\in\{1,2\}\), then, as
\(\theta_i\to-\infty\),
\begin{equation}
\begin{aligned}
\frac{s_{\beta,1}^{(i)}-\theta_i^2}
{2(-\theta_i)^{1/2}}
&\Longrightarrow
\mathcal N\!\left(0,\frac1\beta\right),
&\qquad
(-\theta_i)^{1/2}
\left[
-\frac{1}{
\bigl(\mathcal G^{(\beta)}_{(r-1),i^c}\bigr)'
\bigl(s_{\beta,1}^{(i)}\bigr)}
+2\theta_i
\right]
&\Longrightarrow
\mathcal N\!\left(0,\frac2\beta\right).
\end{aligned}
\end{equation}

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

