[Lemma lem-prob-realization of arXiv:2506.12752, 'Strong Detection Threshold for Correlated \ER Graphs with Constant Average Degree'] {}
    Denote $\mathcal O_1(J)=\{ O \in \mathcal O_{\sigma}: |O|=1, O \not\subset J \}$. We have 
    \begin{equation}
        \mathbb P_{*}(\mathcal J_{\sigma}=J) \leq \big( \tfrac{\lambda s^2}{n} \big)^{|E(J)|} \cdot \big( 1-\tfrac{\lambda s^2}{n} \big)^{|\mathcal O_1(J)|} \,.
    \end{equation}

[Lemma Heat Kernel of arXiv:2605.26869, 'Law of Large Numbers for a random walk on dynamic environments with drift'] Let $(a_n)_{n\geq 0}$ be an arbitrary positive sequence converging to 0. For $n\geq 0$ and $z\in \mathbb{Z}$, let $w = z - (2q-1)n$. As $n\rightarrow \infty$, we have that uniformly in $z\in [(2q-1)n-na_n,(2q-1)n+na_n]$:
	\begin{equation}
		\widebar{q_{2n}}(2z) = 
		\sqrt{\frac{n}{\pi \left(n^2 - z^2 \right)}} 
			\exp \left( - \frac{w^2}{n} \left( \frac{1}{4q(1-q)} \right) + O\left( \frac{w^3}{n^2} + \frac{w}{n} \right) \right)
	\end{equation}
    and the same holds for $\widebar{q_{2n+1}}(2z+1)$.

