[Definition 25 of arXiv:2609.04153, '\vspace*{-3cm}Smooth autonomous fast dynamo action on the three-torus'] We define $\mathcal D$ as the set of all velocity fields $u\in C^\infty_\sigma(\TT^3)$ with $u_3>0$ so that there exists
$\lambda\in\CC$, with $\Re(\lambda)>0$ for which the following hold:
\begin{enumerate}
    \item $1$ is an algebraically simple eigenvalue of $D_{u,\lambda}:X\to X$ 
\item $\inf_{m\geq1}
\exp\left(
    -\Re(\lambda)\inf_{a\in\TT^2}\tau_u^m(a)
\right)
\left\|DP_u^m\right\|_{L^\infty}^{\,1-r}
<1.$
\end{enumerate}

[Theorem 12 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $G$ be a $\mathbb C^{m\times m}$-valued function analytic in the open right half-plane. Then it is contractive in $\mathbb C_r$,
    \begin{equation}
      I_m\ge G(z)G(z)^*,\quad z\in\mathbb C_r,
\end{equation}
      if and only the kernel \eqref{KSS} is positive definite in $\mathbb C_r$.

[Proposition prop boundary to zero of arXiv:2504.06238, 'Infinite Boundary Friction Limit for Weak Solutions of the Stochastic Navier-Stokes Equati'] There exists a constant $C$ such that for all $n \in \mathbb{N}$,
\begin{equation} 
    \left[\sup_{\partial \mathscr{O}}(\alpha_n - \kappa)\right]\mathbbm{E}\left(\int_0^T \left\Vert u^n_s \right\Vert_{L^2(\partial \mathscr{O};\mathbb{R}^2)}^2ds\right) \leq C\mathbbm{E}\left(\left\Vert u_0 \right\Vert^2\right)
\end{equation}
and in particular,
  \begin{equation} 
   \lim_{n \rightarrow \infty} \mathbbm{E}\left(\int_0^T \left\Vert u^n_s \right\Vert_{L^2\left(\partial \mathscr{O}; \mathbb{R}^2\right)}^2 ds \right) = 0.   
  \end{equation}

