body:
[Cor APCRWsum of arXiv:2605.26869, 'Law of Large Numbers for a random walk on dynamic environments with drift'] For all $N\in \mathbb{N}$, $(\alpha_i)_{1\leq i\leq N},(q_i)_{1\leq i\leq N}\in (0,1)^N$, $(\beta_i)_{1\leq i\leq N}\in (0,\infty)^N$ and $p_\bullet>p_\circ \in (0,1)$, the following holds.
For all $\rho \in (0,\infty)$ except at most countably many, the random walk $X$ on the mixture of APCRWs defined above satisfies
\begin{equation}
\frac{X_n}{n}   \underset{n\rightarrow \infty}{\longrightarrow} v(\rho) \,\,\text{ a.s.}
\end{equation}
for some limit $v(\rho)$ such that the map $\rho \mapsto v(\rho)$ is increasing.

Moreover, if the quantity $d_i=\alpha_i(2q_i-1)$ does not depend on $i$, then the above conclusion holds for all $\rho$ except at most one value. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mainresulta 1 (Growth determined by the diameter) of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $(\mathbf q^{(m)})_{m\ge2}$ be a sequence of Bohnenblust--Hille exponents and put $d_m=d(\mathbf q^{(m)})$.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.35em]
\item The exact threshold for superpolynomial growth is
\begin{equation}
 \frac{\bigl(\log C_{\mathbf q^{(m)}}^{(m)}\bigr)}{\log m}\longrightarrow\infty
 \quad\Longleftrightarrow\quad
 \frac{m d_m}{\log m}\longrightarrow\infty.
\end{equation}

\item If $m d_m/\log m\to\infty$, then
\begin{equation}
 \frac{\log2}{4}
 \le \liminf_{m\to\infty}\frac{\bigl(\log C_{\mathbf q^{(m)}}^{(m)}\bigr)}{m d_m}
 \le \limsup_{m\to\infty}\frac{\bigl(\log C_{\mathbf q^{(m)}}^{(m)}\bigr)}{m d_m}
 \le \frac{\log2}{2},
\end{equation}
and hence $\log C_{\mathbf q^{(m)}}^{(m)}\asymp m d_m$ throughout the superpolynomial region.

\item If, in addition, $d_m\to0$, then
\begin{equation}
 \frac{\log2}{4}
 \le \liminf_{m\to\infty}\frac{\bigl(\log C_{\mathbf q^{(m)}}^{(m)}\bigr)}{m d_m}
 \le \limsup_{m\to\infty}\frac{\bigl(\log C_{\mathbf q^{(m)}}^{(m)}\bigr)}{m d_m}
 \le \frac{\vartheta}{2}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:EpmFpm of arXiv:2506.18673, 'Asymptotic Expansions of Gaussian and Laguerre Ensembles at the Soft Edge III: Generating '] There is
\begin{equation}
\lim_{n\to\infty} E_{\pm,n}(x;\xi) |_{x=\mu_{n}+\sigma_{n} s} = F_\pm(s;\xi).
\end{equation}
If $n$ is even and $0<\xi<1$, the proof requires the exclusion\footnote{If the limits are uniform, the singularities causing the exclusion points are removable.} of a discrete set $($which depends on~$\xi)$ of values of $s$.

[Proposition 11 (Finite-part asymptotics) of arXiv:2609.03339, 'Exterior Serrin Rigidity for the Homogeneous \texorpdfstring{$k$}{k}-Hessian Equation\\'] Assume $0<q\le1$ and use the normalized function $U$ from
		\eqref{eq:normal-critical} or \eqref{eq:normal-super}.  There is
		$\gamma\in\R$ such that
		\begin{equation}
			U(x)-F_q(b|x|)\longrightarrow\gamma
			\qquad\text{uniformly as }|x|\to\infty.
		\end{equation}
		Moreover,
		\begin{equation}
			DU(x)-D\bigl(F_q(b|x|)\bigr)=o(|x|^{-q}).
		\end{equation}
		Consequently,
		\begin{equation}
			\begin{cases}
				v(x)=e^\gamma b|x|(1+o(1)),\quad
				Dv(x)=e^\gamma b\dfrac{x}{|x|}+o(1),&q=1,\\[6pt]
				v(x)=b|x|+o(|x|),\quad
				Dv(x)=b\dfrac{x}{|x|}+o(1),&0<q<1.
			\end{cases}
		\end{equation}

