[Lem eq:binomial upper deviations of arXiv:2603.27144, 'On the critical fugacity of the hard-core model on regular bipartite graphs'] For every $n\in\nat$, $p\in[0,1],\epsilon>0$. Then 
\begin{align}
\mathbb{P}\left(\mathrm{Bin}(n,p)\ge(p+\epsilon)n\right) & \le e^{-nd_{\mathrm{KL}}(p+\epsilon\;\|\; p)},\\
\mathbb{P}\left(\mathrm{Bin}(n,p)\le(p-\epsilon)n\right) & \le e^{-nd_{\mathrm{KL}}(p-\epsilon\;\|\; p)}.
\end{align}

[Proposition 19 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] Let $\v\in\boldsymbol{L}^2_{loc}(\R^d)$ be a divergence-free vector field
	such that the corresponding operator $A_0=\v\cdot \nabla$ acting on $L^2(\R^d)$
	with domain $D(A_0)=C^\infty_c(\R^d)$ is essentially skew-adjoint (i.e. $A^*_0=-\overline{A_0}$).
	Let $\beta$ be an admissible function.
	If $\rho\in L^2(\R^d)$ and $f\in L^2(\R^d)$ satisfy
	\begin{equation*}
		\dive (\rho \v)=f \qquad \text{in } \ \mathscr{D}'(\R^d)
	\end{equation*}
	then
	\begin{equation*}
		\dive (\beta(\rho)\v)=\beta'(\rho) f \qquad \text{in }\
		\mathscr{D}'(\R^d).
	\end{equation*}

