body:
[Lemma 32 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] {$ $}

\begin{enumerate}  [(i)]
\item If $\alpha,  x>0$, then   \cite[\href{http://dlmf.nist.gov/5.8.E3}{(5.8.3)}]{NIST:DLMF}
\begin{equation}
  |\Gamma(\alpha+\i x)|^2 = \tfrac{\Gamma(\alpha)^2}{\prod_{k=0}^\infty\left(1+\frac{x^2}{(\alpha+k)^2}\right)}.
\end{equation}
\item If $x\ne 0,-1,\dots$, then  \cite[\href{http://dlmf.nist.gov/5.2.E2}{(5.2.2)}]{NIST:DLMF}
\begin{equation}
   \tfrac{\partial \Gamma(x)}{\partial x}=\psi(x)\Gamma(x),
\end{equation}
where $\psi$ is the {\em  digamma function}.
\item Function $x\mapsto \Gamma(\alpha+x)\Gamma(\alpha-x)$  is convex on $(-\alpha,\alpha)$ and in particular it is
a strictly decreasing function on $(-\alpha,0]$ with the minimum $\Gamma(\alpha)^2$ at $x=0$.
\item If  $\alpha>0$ and $0<p<\alpha$, then
\begin{equation}
   \Gamma(\alpha)^2< \Gamma(\alpha+p)\Gamma(\alpha-p).
\end{equation}

\item For a Pochhammer  symbol
$(a)_j =\Gamma(j+a)/\Gamma(a)$ with $a\not\in\ZZ_{\leq -1}$, we have
\begin{equation}

    (-a)_j=\tfrac{(-1)^j \Gamma (1+a )}{\Gamma (1+a-j)}, \quad j=0,1,\dots.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Knowntheorem 40 (\cite{BorJanVol2013}) of arXiv:2604.09365, 'Cotlar martingale transforms and related singular integrals'] Suppose $Y=Y_1+iY_2$ is a conformal martingale and $X=X_1+iX_2$ is an arbitrary martingale. Then 
\begin{equation}
\|Y\|_p\leq C_p\|X\|_p, \quad 1<p\leq 2, \quad C_p=\frac{1}{\sqrt{2}}\frac{a_p}{1-a_p},
\end{equation} 
 where $a_p$ is the least positive root in the interval $(0, 1)$  of the bounded Laguerre function $L_p$. Furthermore,  the inequality is sharp. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Survival with positive-density range) of arXiv:2609.00292, 'Extinction, Survival and Fluctuations for the Spatial Maki--Thompson Model on Infinite Gra'] Let \(G=(V,E)\) be a Cayley graph of superlinear growth and degree
    \(\Delta\), rooted at \(o\). For \(\lambda,\alpha>0\), consider the
    process started from a single spreader at \(o\), and put
    \(\rho:=\alpha/\lambda\). If
    \[
        q_\Delta(\rho)>p_c^{\mathrm{site}}(G),
    \]
    then \( \mathbb P(\text{global survival}) \ge \theta_G\bigl(q_\Delta(\rho)\bigr). \) If, in addition, \(G\) has
    polynomial growth of degree \(D\ge2\), then
    \begin{equation}
        \mathbb P\left(
        \liminf_{n\to\infty}
        \frac{
                |\mathcal A_\infty\cap B_G(o,n)|
            }{
                |B_G(o,n)|
            }
        \ge
        \theta_G\bigl(q_\Delta(\rho)\bigr)
        \right)
        \ge
        \theta_G\bigl(q_\Delta(\rho)\bigr).

    \end{equation}
    Moreover, there exists a universal constant \(c_0>0\) such that
    \begin{equation}
        \frac{\alpha}{\lambda}
        <
        \frac{c_0}{\Delta(1+\log\Delta)}

    \end{equation}
    implies \(q_\Delta(\rho)>p_c^{\mathrm{site}}(G)\), and hence the
    conclusions above hold. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Prop_TransversalityCriterion_EigenSpinors of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let $B$ be a manifold and $\Gamma \mskip0.5mu\colon\thinspace B \to \mathbf{Dir}$ a smooth map.
  The following are equivalent:
  \begin{enumerate}
  \item
    $\Gamma$ is transverse to $\mathrm{pr}_\mathbf{Dir} \mskip0.5mu\colon\thinspace {\mathbf{P}}\mathbf{Eig}^* \to \mathbf{Dir}$.
  \item
    For every $b \in B$ and $({\mathbf{p}},[{\mathfrak l}];[\Phi],\lambda) \in {\mathbf{P}}\mathbf{Eig}^*$ with $\Gamma(b) = {\mathbf{p}}$
    the map
    \begin{equation*}
      \delta_{\Phi,\lambda} \mskip0.5mu\colon\thinspace T_bB \times \mathbb{R} \to \paren[\big]{\ker \paren{D_{R_\Phi}-\lambda}}^*
    \end{equation*}
    defined by
    \begin{equation*}
      \delta_{\Phi,\lambda}(v,t)\kappa
      \coloneq
      \Inner*{T_{\Phi,\kappa},T_{{\mathbf{p}}}\mathrm{pr}_\mathbf{Met} \circ T_b\Gamma(v)}_{L^2}
      + \Inner*{\mu(\Phi,\kappa),\mathrm{pr}_{V_\nabla} \circ T_b\Gamma(v)}_{L^2}
      - t\Inner*{\Phi,\kappa}_{L^2}
    \end{equation*}    
    is surjective.
    Here $R_\Phi$ denotes the residue condition induced by $\Phi$.
    \qed
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 5 of arXiv:2604.22644, '2604.22644'] For $0 < q < 1$, the probability generating function of the first hitting time $\tau_N$ is given by:
\begin{align}
    E[q^{\tau_N}] = \frac{ \displaystyle \int_0^1 p q c(1;p) dp }{ \displaystyle 1 - \left( \frac{q}{2} + \int_0^1 p q b(1;p) dp \right) },
\end{align}
where $b(k;p)$ and $c(k;p)$ are the solutions to the linear difference equations defined in Theorem \ref{thm2} and Theorem \ref{thm3}, respectively.

