body:
[Theorem thm:R4 of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] Let $\alpha\in(0,d)$ and $(\zeta,\gamma)\in R_4$. In particular, this requires $d\geq3$. Then for $\xi=\frac{\zeta}{2}\in(\frac1d,\frac12)$, we have that
\begin{equation*}
\lim\limits_{N\to\infty}\frac{1}{N^{1-2\xi}}\log{\ensuremath{\mathbf Z}} _N=-\hat{h}\gamma_d\quad\text{in}~{\ensuremath{\mathbbm P}} \text{-probability},
\end{equation*}
where $\gamma_d>0$ is given in (equation eq:range_limit of the paper), and for any $\delta>0$, ${\ensuremath{\mathbf P}} _N\big(\big|\frac{|{\ensuremath{\mathcal R}} _N|}{N}-\gamma_d\big|<\delta\big)\overset{N\to\infty}{\longrightarrow}1$ in ${\ensuremath{\mathbbm P}} $-probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 (Changing the path space) of arXiv:2605.13512, '2605.13512'] Assume \ref{ass:c}, \ref{ass:c2} and \ref{ass:c0}. The set of paths $\mathcal H(x,y)$ used in equation \eqref{macroLPT} can be changed to 
 \begin{align*}
\mathcal{H}^{\rm cont}(x,y) &=\{{\bf x}\in C([0,1],\R^2_+):\mathbf{x} \text{ is piecewise }C^1,\mathbf{x}(0)=(0,0), \mathbf{x}(1)=(x,y), \\
& \phantom{xxxxxxxxx} {\bf x }(s) \in \mathcal C \text{ for a.e. }  s\in [0,1], \,  \mathbf{x}'(s)\in \R^2_+ \text{ wherever the derivative is defined}\},
\end{align*}
without changing the value of the supremum in \eqref{macroLPT}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[proposition]{prop:well_posed_averaging_limit}
   Assume \cref{hp:noise}. For each $\epsilon\in [-5,5]$ and
   $\psi_0\in H^\epsilon$, there exists a unique
   $\bar{\psi}\in C([0,T];H^{\epsilon})$ solving \eqref{eq:averaging} with $\bar{\psi}_0 =\psi_0 $ in the sense that
   the following identity holds for each $\phi\in \mathscr{S}(\R^d)$ and
   $t\in [0,T]$:
   \begin{align*}
       i\langle \bar\psi_t,\phi\rangle&=i\langle \psi_0,\phi\rangle+\int_0^t \langle\bar\psi_s, (-\Delta+V)\phi\rangle ds.
   \end{align*}
   Moreover, if $\epsilon\geq 0$, 
   \begin{align*}
       \|\bar{\psi}_t\|=\|\psi_0\|\quad \text{for all }t\geq 0.
   \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:n=1error of arXiv:2506.06559, 'Bi-infinite incipient cluster in high dimensions'] For all $F\in\mathfrak F_{00}$ the following holds.  
\\
(i) There is a constant $C_W$ such that 
\eqn{eq:n=1error}{
  \sum_{N'=0}^\infty \Psi^{1,N'}(F;u,x')
  \le C_W T(o,u,x'). }
(ii) There is a constant $C_W$ such that uniform in $v'$,
\eqn{eq:n=1error2}{
  \hat{\Psi}^{1,0}(F,u,u',v') + \sum_{N'=1}^\infty \Psi^{1,N'}(F;u,u')
  \le C_W T(o,u,u'). } (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $W$ satisfy Assumption~\ref{ass:noise} and $\alpha_W$ be given by~\eqref{eq:noise_regularity_threshold}.
    Then for any $\alpha \in (\alpha_W,1)$ and $\eps \in (0,1)$, there exist a divergence-free drift $u \in C^\alpha ([0,1]\times \T^2;\R^2)$, a set $A_\eps \subset \T^2$ with $|A_\eps| \geq 1 - \eps $, a vanishing sequence $(\kappa_q )_{q}$, and a constant $c_\eps >0$ such that
    \begin{equation}
        \P\left( \liminf_{q\to\infty}  \dist  (X_1^{\kappa_{2q}} (x, \omega) , X_1^{\kappa_{2q+1}} (x, \omega))  \geq c_\eps> 0\ \text{ for Lebesgue a.e } x\in A_\eps\right)=1.
    \end{equation}

    Furthermore, for any fixed $x \in A_\eps$, one can find a subsequence $\{\kappa_{q'}\}_{q'}$ and deterministic points $y,y'$ in $\T^2$ such that
    \begin{equation}
        \P\left(\lim_{q'\to\infty} X_1^{\kappa_{2q'}} (x, \omega)=y\neq y'=\lim_{q'\to\infty} X_1^{\kappa_{2q'+1}} (x, \omega)\right)=1.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 20 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For $\calX=(X,d^X,\mu_X),\;\calY=(Y,d^Y,\mu_Y)\in\frK(\tau)$, we define
\begin{align*}
  d^{\tau,\BL^{\kappa}}_{\frK}(\calX,\calY):=\inf_{f,g,Z}\Big\{ d^Z_{\mathrm{H}}(f(X),g(Y))\vee d^Z_{\BL^{\kappa}}(\mu_X\circ f^{-1},\mu_Y\circ g^{-1})\Big\},
\end{align*}
where the infimum is taken over all compact metric spaces $(Z,d^Z)$ and isometric embeddings $f:X\to Z$ and 
$g:Y\to Z$.

[Thm main-1 of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Let $\Omega$ be a bounded Lipchitz domain   in $\mathbb{R}^3$.
Let  $\lambda \in \Sigma_\theta$, where $\theta \in (0, \pi/2)$.
Then for any $F\in L_\sigma^\infty(\Omega)$,  the weak solution of the Dirichlet problem (equation eq-0 of the paper)   in 
$W_0^{1, 2}(\Omega; \mathbb{C}^3) \times L^2(\Omega; \mathbb{C})$
satisfies the estimate,
\begin{equation}
 |\lambda| \| u \|_{L^p (\Omega)}
\le C  \| F \|_{L^p (\Omega)}
\end{equation}
 for  $1< p\le \infty$, where $C$   depends only on $\theta$, $p$ and $\Omega$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 (Piecewise-linear approximation of time-Haar atoms) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $p \in \mathbb{N}_{+}$ and let $q \in \{0,\ldots,2^{p}-1\}$. If $0<\eta_t<2^{-(p+2)}$, then 
\begin{equation*}
\left\|\psi_{p,q}-\psi^{(\eta_{\mathrm t})}_{p,q}
\right\|_{L^2([0,T])}=
\frac{2^{1+p/2}}{\sqrt3}
\sqrt{\eta_{\mathrm t}}
\end{equation*}

