[Tm main_tm of arXiv:2607.08869, 'Inequalities for convex functions of random points inside and on the boundary of convex bo'] Let $K$ be a convex body in $\mathbb{R}^d$ satisfying one of the following:
    \begin{itemize}
        \item $d = 2$ and $\mathbb E I = \mathbb E B$;
        \item $K$ is a circumscribed polytope whose inscribed sphere center $O$ coincides with $\mathbb EI$ and $\mathbb EB$.
    \end{itemize}
    Let $\varphi: (\mathbb{R}^d)^k \to \mathbb{R}$ be a function convex in each argument.
    Then
    \begin{align}
        \mathbb E \varphi(I_1, \ldots, I_k) \leqslant  \mathbb E \varphi(B_1, \ldots, B_k),
    \end{align}
    where $I_1,\dots,I_k$ and $B_1,\dots,B_k$ are independent samples uniformly distributed inside $K$ and on $\partial K$, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $l \in \n$, $K_1(l) \geq 2k(l)+3$ and define $C_l\coloneqq 2l^{\frac{1}{d+\delta}}K_1(l)$, $\beta_l\coloneqq \sqrt{C_l^2-1}-1$ and $K_3(l)\coloneqq \sqrt{8}C_l$. Then for any $r\geq 1$,
    \begin{align*}  
    \begin{split}
    \varphi \in E^3_{r,K_3(l)} &\cap \hatMsetl \cap (E^1_{r,K_1(l)})^c \\
    &\implies \varphi(\beta_lrB^d\times(-\infty,r^2])=0 \text{ or } \exists j \in \{1,\dots,\theta_l\} \text{ such that } \varphi(\beta_lrB_j\times(-\infty,r^2])=0 ,
    \end{split}
\end{align*} 
    where $\theta_l$ is the minimal number of balls with unit radius needed to cover the ball $(K_3(l)+1)B^d$ and $B_1,\dots,B_{\theta_l}$ is the minimal cover.

