[Definition 3 of arXiv:2609.00736, 'Modalities in non-classical variations of S4'] A birelational $\csf$-model is a tuple $M=\tuple{W, W^\bot, \preceq, \R, V}$, where:
    \begin{itemize}
        \item $W$ is the set of \emph{possible worlds};
        \item $W^\bot$ is the set of \emph{fallible worlds};
        \item the \emph{intuitionistic relation} $\preceq$ is a preorder over $W$;
        \item the \emph{modal relation} $\R$ is a preorder over $W$; and
        \item $V:\mathrm{Prop}\to \mathcal{P}(W)$ is a \emph{valuation function}.
    \end{itemize}
    We require that:
    \begin{itemize}
        \item $M$ is \emph{backward confluent}, that is, $w \R v \preceq v'$ implies there is $w'$ such that $w \preceq w'$ and $w' \R v'$;
        \item for all $P\in\mathrm{Prop}$, $V(P)$ is a $\preceq$-upset and $W^\bot\subseteq V(P)$;
        \item $W^\bot$ is both a $\preceq$-upset and a $\sqsubseteq$-upset.
    \end{itemize}
    Backward confluence is illustrated in Figure \ref{figure::confluences}.

[Lemma 23 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then there exist constants $\eps_*>0$ and $c,C>0$ such that
        \begin{align}
                \inf_{\substack{|z-E_*|<\eps_*  \\ \Im z>0}}|z+g(z)|\geq c,
                \qquad
                \sup_{\substack{|z-E_*|<\eps_*  \\ \Im z>0}}\|\Pi(z)\|\leq C. \nonumber
        \end{align}
        Moreover,
        \begin{align}
                \|\Pi(z_1)-\Pi(z_2)\| \leq C|z_1-z_2|^{1/3} \nonumber
        \end{align}
        for all $z_1,z_2\in\C^+$ satisfying $|z_1-E_*|,|z_2-E_*|<\eps_*$. Consequently, $\Pi$ extends uniquely and continuously to $\{z\in\C:|z-E_*|<\eps_*,\ \Im z\geq0\}$.
        In particular,
        \begin{align}
                \Pi(E_*) := \lim_{\eta\downarrow0}\Pi(E_*+\ii\eta) 
        \end{align}
        is well defined and is a real symmetric invertible matrix.

