body:
[Definition def-transport-C1 of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Assume $b\in L^1_{loc}(\mathbb{R}^d;\mathbb{R}^d)$ and $u_0 \in C_\mathrm{b}^1(\mathbb{R}^d)$. 
A measurable and essentially bounded function  (in the sense of (equation eq-esb0 of the paper)) $u:
\Omega\times[0,\infty)\times\mathbb{R}^d \to \mathbb{R}
 $ is a $C^1$-solution to the problem (equation eqn-transport-Markus of the paper)  if it
satisfies the following four conditions: for any $T>0$,
\begin{trivlist}
\item[(i)] for almost every $\omega\in\Omega$, $u(\omega, t,\cdot)\in C^1(\mathbb{R}^d)$, 
for all $t\in[0,T]$; 
{\item[(ii)] for  almost every $\omega\in\Omega$ and every $R>0$, the gradient $Du(\omega,t,x)$ satisfies $$\sup_{t\in[0,T]}\|D u(\omega, t,\cdot)\|_{L^\infty(B(R))}<\infty.$$}
 This means that there exists a $\mathbb{P}$-full set $\Omega^\prime \subset \Omega$ such that for any $R>0$, there exists $M_R\in(0,\infty)$ such that 
 for any $t \in [0,T]$, $\omega \in \Omega^\prime,$
\begin{align*}
\|Du(\omega,t , x)\| \le M_R, \;\;  \forall x \in A^R_{t, \omega},
\end{align*}
where $A^R_{t, \omega}$ is a Borel set of $B(R)$ such that $\mathrm{Leb}( (A^R_{t, \omega})^c)=0$. Recall that $\|\cdot\|_{L^\infty(B(R))}$ denotes the essential supremum norm on $B(R)$, the closed ball of radius $R$ centered at $0$ in $\mathbb{R}^d$;
\item[(iii)] for every test function  $\theta\in C_c^{\infty}(\mathbb{R}^d)$, the process $\int_{\mathbb{R}^d}\theta(x)u(t,x)\,dx$, $t\geq 0$ is $\mathbb{F}$-adapted  and it has c\`{a}dl\`{a}g paths $\mathbb{P}$-a.s.;
\item[(iv)] for every test function  $\theta\in C_c^{\infty}(\mathbb{R}^d)$, the process $\int_{\mathbb{R}^d}\theta(x)u(t,x)\,dx$,  $t\geq 0$,  satisfies that, for every $t\geq 0$, $\mathbb{P}$-a.s.
\begin{align}
      \int_{\mathbb{R}^d}u(t,x)\,\theta(x)\,dx
    =&
    \int_{\mathbb{R}^d}u_{0}(x)\,\theta(x)\,dx
       -\int_0^t\Big(\int_{\mathbb{R}^d}b(x)\cdot D u(s,x)\theta(x)\,dx\Big) ds\nonumber\\
       &+\int_0^t\Xint\times_{B} \Bigl(\int_{\mathbb{R}^d}u(s-,x)\,[\theta(x+z)-\theta(x)]\, dx\Bigr)\tilde{\mu}(ds,dz)\nonumber\\
       &+\int_0^t\int_{B^{\mathrm{c}}} \Bigl(\int_{\mathbb{R}^d}u(s-,x)\,[\theta(x+z)-\theta(x)]\, dx\Bigr) \mu(ds,dz)\\
       &+\int_0^t\Xint\times_{B}\Bigl(\int_{\mathbb{R}^d} u(s,x)\,[\theta(x+z)-\theta(x)-\sum_{i=1}^dz_iD_i\theta(x)]\,dx\Bigr)\,\nu(dz)\, ds.\nonumber
\end{align}
The $\mathbb{P}$-a.s. means that our $\mathbb{P}$-full set depends on $t \in [0,\infty)$ and $\theta$.
\end{trivlist}

[Lemma lem_(I-H)fg_main2 of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] Using the notation in Lemma (lem_(I-H)fg_main of the paper) of $\mu,S(t),\tilde{S}(t),I(f,g),J(f,g)$ and the assumptions for $f,g$, if we assume $L_0D_tf(\cdot,t), L_0g(\cdot,t),\Omega_0D_tf(\cdot,t),\Omega_0g(\cdot,t),\partial_\alpha\Omega_0f(\cdot,t)\in L^2(\tilde{S}(t))$ instead, then for a general function $h$ we set
    $$
    W(h)=\left\lVertL_0h\right\rVert_{L^2(\widetilde{S}(t))}+\left\lVert\Omega_0h\right\rVert_{L^2(\widetilde{S}(t))},
    $$
    If in addition $D_tf\in L^2\cap L^\infty$, then
    \begin{equation}
    \begin{aligned}
    &\norm{I+\frac{t}{2\alpha}f_t\bar g}_{L^2(S(t))}+\norm{J-\frac{t}{2\alpha}f_tg}_{L^2(S(t))}\\
    \lesssim&\ \frac{1}{t}(\left\lVertD_tf\right\rVert_{L^\infty}+\left\lVertg\right\rVert_{L^\infty}+\left\lVertbf_\alpha\right\rVert_{L^\infty})\left[\left\lVertD_tf\right\rVert_{L^2}+t^{2\mu}\left\lVertg\right\rVert_{L^2}+t^\mu (W(D_tf)+W(g))+\left\lVert\partial_\alpha\Omega_0f\right\rVert_{L^2}\right]\\
    &+\frac{1}{t^{1-\mu}}\left\lVertf\right\rVert_{L^\infty}\left\lVertg\right\rVert_{L^2}+t^{\mu}\left\lVertb\right\rVert_{H^1}\left\lVertf_\alpha\right\rVert_{W^{1,\infty}}\left\lVertg\right\rVert_{L^\infty}.
    \end{aligned}
    \end{equation}

[Lemma lem::one_arm_bd_aux2 of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] We have the convergence
	\begin{equation*}
		\lim_{a\to 0} 2^{-1/4}a^{-\frac{1}{2}}|F^a(u_3^{a,\diamond})|=|\phi(\mathfrak{i};[-2,2]^2;-1-\mathfrak{i},1-\mathfrak{i})|,
	\end{equation*}
where $\phi(\cdot;[-2,2]^2;-1-\mathfrak{i},-1+\mathfrak{i})$ is the unique (up to a sign) holomorphic function defined in~[FPWFKIsing].

[Definition 24 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] The stochastic process on the probability space
$(\Omega,\mathcal{C},P)$ where $P$ is $\mathbb{H}$-valued is called
a $\mathbb{H}$-valued Brownian motion if it is Gaussian and if 
\begin{equation}
E_{\mathbb H}(B_{p}B_{q})=p\wedge q,\quad p,q\in\mathbb{H}_{+}
\end{equation}
and more generally, using \eqref{p-q} 
\begin{equation}
E_{\mathbb H}(B_{p}B_{q})=\frac{1}{2}\left(|p|_{\mathbb{H}}+|q|_{\mathbb{H}}-|p-q|_{\mathbb{H}}\right),\quad p,q\in\mathbb{H}.
\end{equation}

[Lem 48 of arXiv:2608.26068, 'All once-extended 3D TQFTs are Reshetikhin--Turaev theories'] For the embedding of $|\Gamma_{M''}\cup L''|$ defined in Construction \ref{constr:hor-glue},
    \begin{enumerate}
        \item $|\Gamma_{M''}\cup L''|$ is a surgery presentation for $(\ol{M''}\#(S^1\times S^2), |\Gamma_{M''}|)$.
        \item The link trace $X_{L''}$ has the same signature as $X_L \cup_{V_{\parOut M}} X_{L'}$.
    \end{enumerate}

[Corollary 6 ($L^2$ control) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] For any $T>0$, there exists $C>0$ such that
    \begin{equation}
    \bigl\Vert p^{i,n}(t,\cdot) \bigr\Vert_2^2 \leq \frac{C}{\sqrt{t}},\quad t\in(0,T],
    \end{equation}
    where $C$ can be chosen uniformly in $i=1,\ldots, n$ and $n\geq 1$.

[Lemma lem:barrier-exclusion of arXiv:2608.30700, 'Convex hulls and area minimizing currents in asymptotically locally hyperbolic manifolds'] Let $\Omega=\Omega_{\psi,c}$, where $c\geq c_0(\psi)$, and let $V$ be a rectifiable $p$-varifold in $M$, $1\leq p\leq n$, which is stationary in $\Omega$. Suppose that
    \begin{equation}
        \overline{\spt V}^{\,\overline{M}}
        \cap\partial_\infty\Omega=\emptyset.
    \end{equation}
    Then $\spt V\cap\Omega=\emptyset$. In particular, if $T$ is a compactly supported integral $p$-current, $|T|$ is stationary in $M\setminus\spt\partial T$, and $\spt\partial T\cap\Omega=\emptyset$, then $\spt T\cap\Omega=\emptyset$.

[Prop 6 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] Let $L(x,{\d} y)$ be a kernel on $E\times\mathscr{B}(E)$ and ${\sf d}$ be a distance function consistent with the underlying topology.
Assume there exists $D_2, C > 0$ such that:
\begin{enumerate}
    \item $L(x,{\d} y) 
    \leq D_2 \frac{{\m}({\d} y)}{{\sf d}(x,y)^p}$,
    \item ${\m}(B_r(x))\leq Cr^d$ for every $x \in E$ and $r > 0$,
\end{enumerate}
for some $d, p \in \R$, $p >d\geq0$. Here $B_r(x):=\{y\in E\mid {\sf d}(x,y)<r\}$. Then $M_\beta < \infty$, i.e.,
\eqref{eq:MbetaFinite} holds, for any $\beta > p - d$.

[Lemma l:94 of arXiv:2508.21658, 'Infinite-dimensional stochastic differential equations for Coulomb random point fields'] For each $ m \in \zN $ and $ \mu $-a.s.\,$ \aaa $, 
\begin{align}  
 ( \Emuam , \uLdmuam ) &= \uLEDastarm 
.\end{align}

[Theorem 22 of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] For $f\in \mathcal{S}(\mathbb{Q}_p^n)$, the solution of
\eqref{eq:the_Dirichlet_problem_extension} has Fourier transform
    \begin{align*}
    \hat{\varphi}_k(\boldsymbol{\xi})=\begin{cases}
        \hat{f}(\boldsymbol{\xi})
        (1-p^{-s(k+1)}\|\boldsymbol{\xi}\|_p^s),
        &k\geq-v_p(\boldsymbol{\xi});\\
        0,&k<-v_p(\boldsymbol{\xi}).
    \end{cases}
\end{align*}
At $\boldsymbol{\xi}=\boldsymbol{0}$, the first line is understood to be
$\hat\varphi_k(\boldsymbol{0})=\hat f(\boldsymbol{0})$.

