[Lemma 15 (Malliavin total variation estimate) of arXiv:2608.08177, 'Uniform-in-Time Smoluchowski--Kramers Approximation\\ in Total Variation for Fractional SD'] Let $F\in\mathbb D^{2,4}$ and $G\in\mathbb D^{1,2}$.  Suppose
$\norm{\D F}_{\cH}>0$ almost surely and
$u_F=\D F/\norm{\D F}_{\cH}^2$ belongs to the domain of $\delta$.  Then
\begin{equation}
 d_{\TV}(\Law(F),\Law(G))
 \le C\norm{F-G}_{\mathbb D^{1,2}}
 \left(
   \norm{\delta(u_F)}_{L^2}
   +\norm{\norm{\D F}_{\cH}^{-1}}_{L^2}
 \right).
\end{equation}
Moreover,
\begin{equation}
 \norm{\delta(u_F)}_{L^2}
 \le C\left(
  \norm{\norm{\D F}_{\cH}^{-1}}_{L^4}
  +\norm{\D^2F}_{L^4(\cH^{\otimes2})}
   \norm{\norm{\D F}_{\cH}^{-2}}_{L^4}
 \right).
\end{equation}

