[Lemma of arXiv:2609.00425, 'Individual and Uniform Eventual Positivity of Self-Adjoint Semigroups'] The space $H$ decomposes as $H = H_{\mathrm{even}} \oplus H_{\mathrm{odd}}$, where
    \begin{align*}
        H_{\mathrm{even}}
        &\coloneqq
        \set{x\in\ell^2(\mathbb{Z}) : x_n=x_{-n}\text{ for all }n\in\mathbb{Z}}, \\
        H_{\mathrm{odd}}
        &\coloneqq
        \set{x\in\ell^2(\mathbb{Z}) : x_n=-x_{-n}\text{ for all }n\in\mathbb{Z}}.
    \end{align*}
    Moreover, the following assertions hold:
    \begin{enumerate}[\upshape (i)]
        \item The sequence $(p_n)_{n \in \mathbb{N}_0}$ is an orthonormal basis of $H_{\mathrm{even}}$, where $p_0 \coloneqq e_0$ and
        \begin{align*}
            p_n \coloneqq \frac{1}{\sqrt{2}}(e_n+e_{-n}) \in \ell^2(\mathbb{Z}), \quad n \in \mathbb{N}.
        \end{align*}
        \item The sequence $(q_n)_{n \in \mathbb{N}}$ is an orthonormal basis of $H_{\mathrm{odd}}$, where
        \begin{align*}
            q_n \coloneqq \frac{1}{\sqrt{2}} (e_n - e_{-n}) \in \ell^2(\mathbb{Z}), \quad n \in \mathbb{N}.
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 31 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] Let~$w=w_{\ell x'+i',y'}$ and~$b=b_{\ell x+i,y}$ be vertices in the reduced Aztec diamond with~$0<\ell x'+i'<\ell N-1$,~$0\leq y'\leq \ell N-2$,~$1\leq \ell x+i\leq \ell N-1$ and~$0<y<\ell N-1$. The Coulomb gauge functions~$\mathcal F^\bullet$ and~$\mathcal F^\circ$ defined in Proposition~\ref{prop:FG} are given by
\begin{equation*}
 \mathcal F^\bullet(b)=
  \frac{1}{2\pi\i}\int_{\Gamma}
  \prod_{m=1}^{i}\frac{\gamma_mz+\alpha_m}{z-\beta_m}\prod_{m=1}^\ell (z-\beta_m)^N\frac{w^x}{z^{y+1}}f(z)\d z,
\end{equation*}
and
\begin{equation}
\mathcal F^\circ(w)=
\frac{1}{2\pi\i}\int_{\Gamma}\left(\frac{\prod_{m=1}^{i'+1}(\gamma_mz+\alpha_m)}{\prod_{m=1}^{i'}(z-\beta_m)}\right)^{-1}\prod_{m=1}^\ell(z-\beta_m)^{-N}\frac{z^{y'+1}}{w^{x'}}g(z)\d z,
\end{equation}
where 
\begin{equation}
f(z)=\sqrt{a+\i}\left(\frac{\i}{z+\frac{\alpha_1}{\gamma_1}}-\frac{a}{z-\beta_\ell}\right), \quad \text{and} \quad g(z)=\sqrt{a-\i}\left(\frac{\i a\frac{\alpha_1}{\gamma_1}}{z}+1\right)
\end{equation}

with~$a$ defined in~\eqref{eq:def_a} and given by
\begin{equation*}
a=\sqrt{\frac{\gamma_1\beta_\ell}{\alpha_1}},
\end{equation*}
and~$\Gamma$ is as in Lemma~\ref{lem:k_reduced_1xell}.

