[Lemma lem:S6V-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = L^2(C_r)$.  The seed functions
$\psi_{t,x,m}$ and $\phi_{t,x,m}$ defined in
(equation eq:S6V-seed-def of the paper) satisfy the linear problem
(equation eq:Linear-Psi-3 of the paper) and the adjoint linear problem
(equation eq:Linear-Phi-Prob of the paper) on $\mathcal{V}$ with edge
weights $(c_k, \lambda_k)$.  Explicitly:
\begin{align}
\psi_{t,x+1,m-1}
&= \psi_{t,x,m-1} + \tau^{-1}\psi_{t,x,m},
 \\
\psi_{t-1,x,m-1}
&= \psi_{t,x,m-1} + \alpha\psi_{t,x,m},

\end{align}
and
\begin{align}
\phi_{t,x,m-1}
&= \phi_{t,x+1,m-1}
   + \tau^{-1}\phi_{t,x+1,m-2},
 \\
\phi_{t,x,m-1}
&= \phi_{t-1,x,m-1}
   + \alpha\phi_{t-1,x,m-2}.

\end{align}

[Lem 10 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Assume that conditions $\mathbf{H_{a,b}^{\sqrt{u}}}$ and $\mathbf{H_{\sf \leq u}}$ are fulfilled.
    Then, the following assertions hold for every $0<s<N<\infty$.
    \begin{enumerate}
        \item[(i)] We have the identification
        \begin{equation}
        \mathbb{P}^N_{\delta_s\otimes \mu_s}\circ \left(X_2^N(t)\right)^{-1}= \mu_{t+s}, \quad 0\leq t<N-s. \end{equation}
         \item[(ii)] We have the following refinement of \Cref{thm:Stannat}, (ii.3):
         \begin{equation}
            \mathbb{P}^N_{\delta_s\otimes \mu_s}\left( X^N_1(t)\neq t+s; t<\zeta^N  \right)=0.
        \end{equation}
        \item[(iii)] The lifetime $\zeta^N$ satisfies
        \begin{equation}
         \mathbb{P}_{s,x}^N\left(\zeta^N=N-s\right)=1 \quad \mu_s\mbox{-a.e. } x\in \mathbb{R}^d,
    \end{equation}
    \end{enumerate}

[Proposition prop:Schauder of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Fix $\alpha \in (0,1)$.  Suppose $g$ is a solution to (equation eq:linear_kinetic of the paper) in $Q_2$ satisfying (equation eq:uniform_ellipticity of the paper) in $Q_2$ for some values of $\lambda$ and $\Lambda$.  Suppose that $\mathcal A, \mathcal B, \mathcal C \in C^{0,\alpha}_{\rm kin}(Q_2)$.  Then, we have
        \begin{equation}
        [g]_{C^{2,\alpha}_{\rm kin}(Q_1)} \lesssim \left(1 + [\mathcal A]_{C^{0,\alpha}_{\rm kin}(Q_2)}^\frac{2+\alpha}{\alpha}
        + [\mathcal B]_{C^{0,\alpha}_{\rm kin}(Q_2)}^\frac{2+\alpha}{1+\alpha}
        + [\mathcal C]_{C^{0,\alpha}_{\rm kin}(Q_2)}\right) \left\|g\right\|_{L^\infty(Q_2)}.
    \end{equation}   
    Further suppose that for some $k \ge 3$ and some $\alpha \in (0,1)$,
    \begin{equation}
        \left\|\mathcal A\right\|_{C^{k-3,\alpha}_{\rm kin}(Q_2)}
        + \left\|\nabla_v \mathcal A\right\|_{C^{k-3,\alpha}_{\rm kin}(Q_2)}
        + \left\|\mathcal B\right\|_{C^{k-3,\alpha}_{\rm kin}(Q_2)}
        + \left\|\mathcal C\right\|_{C^{k-3,\alpha}_{\rm kin}(Q_2)} \le \Lambda_k.
    \end{equation}
    Then there is $p_{k,\alpha}$, depending only on $k$ and $\alpha$ such that
    \begin{equation}
        [g]_{C^{k-1,\alpha}_{\rm kin}(Q_1)} \lesssim \left(1+\Lambda_k^{p_{k,\alpha}}\right) \left\|g\right\|_{L^\infty(Q_2)}.
    \end{equation}
    The implicit constants depends only on $\lambda$, $\Lambda$, and $\alpha$ and, in the case of~(equation e.Schauder_k of the paper), on $k$ as well. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 60 (Finite negative-rank reflection) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every $m\ge1$, and every $0\le r\le m$,
\begin{equation}
 \HH_r(K;q^{-m},q)=\HH_{m-r}(K;q^{-m},q).
\end{equation}
Moreover, for every zero-framed knot $K$ and every $r\ge0$,
\begin{equation}
 \HH_r(K;q,q)=1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:62 of arXiv:2508.21658, 'Infinite-dimensional stochastic differential equations for Coulomb random point fields'] The following hold:
\begin{align} & 
\sup_{ \rR , i \in \mathbb{N} } E [ \lvert \ \uLXRi (t) - \uLXRi (u) \rvert ^4 ] 
 \le (;76 of the paper) \lvert t - u \rvert ^ 2 , \text{ } 0 \le t,u < \infty 
,\\ &
\limi{a} \liminfi{ R }
P ( \max_{1\le i \le m } \maxT \lvert \ \uLXRi (t) \rvert \le a ) = 1 
,\quad m , T \in \mathbb{N} 

,\\&
\limil \inf_{ R \in \mathbb{N} }
P ( \IRT ( \uLXR ) \le l ) = 1 
,\quad T \in \mathbb{N} 

.\end{align}
Here, $ \Ct  > 0 $ is a constant.

[Prop 321-avoiding-permutons of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] The map $\Psi$ is a continuous surjective map from $\mathcal D$ to the set $\mathcal P_{\Av(321)}$ of $321$-avoiding permutons.
    Moreover, considering a $321$-avoiding permuton $\mu$ and its decomposition $\mu=\mu_{{\begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0.5,0) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}}+\mu_{{\, \begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0,0.5) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}}+\mu_{\diagup}$ as above, we have
    \begin{equation}
        \Psi^{-1}(\mu) = \big\{\proj(\mu_{{\begin{tikzpicture}[scale=.4]
  \draw (0,0) -- (0.5,0) -- (0.5,0.5);
  \draw[thick,dotted] (0,0) -- (0.5,0.5);
\end{tikzpicture}}} + \nu) : 0 \le \nu \le \mu_{\diagup} \big\} \,,
    \end{equation}
    where we recall that $\proj(\pi)$ is the pair of measures given by the projections of $\pi$ on the horizontal and vertical axes respectively.

[Lemma 11 of arXiv:2607.11773, '2607.11773'] Suppose that {\bf(H1)}-{\bf(H4)}, \eqref{thetaassum2}, \eqref{dissip1} and \eqref{dissip2} hold.
   Then for every 
   $\tau \in \mathbb{R}$, $\delta > 0$ and $D = \{ D(t): t \in \mathbb{R} \} \in \mathcal{D}$,
   there exist constants $T = T(\tau, \delta, D) \ge 3\rho$ and $ m_1 = m_1(\tau, \delta) \ge 1$
   such that for all $t \ge T$ and $m \ge m_1$,
   the solution $u$ of \eqref{lmvlds-2} satisfies
   \begin{align*}
      \mathbb{E}
         \Big[ \sup_{s \in [\tau-\rho, \tau]}
                   \sum_{|i| \ge m}
                      |u_i(s; \tau-t, \varphi)|^2
         \Big]
      + \mathbb{E}
           \Big[ \int_{\tau-\rho}^{\tau}
                    \sum_{|i| \ge m} |u_i(s; \tau-t, \varphi)|^p ds
           \Big]
      < \delta,
   \end{align*}
   where $\varphi \in L^\theta(\Omega, \mathcal{F}_{\tau-t};D_{\rho})$ with law $\mathcal{L}_{\varphi} \in D(\tau-t)$.

