[Lemma lem:generator positive of arXiv:2507.09421, 'Stability of randomly switching stochastic reaction networks with asymptotically linear tr'] In the setting of Theorem (thm:fast-switching-transience of the paper), let $I:=\operatorname{supp}(v)$ denote the set of species which are visible to $v$. For $m\in I$, let $z^m$ be the vector given to us by applying Lemma (lem:z^m of the paper) to $v$; for $m\notin I$, let $z^m$ be the vector of all zeros. For $x\in\mathbb Z^d_{\ge0}$ and $i\in\{1,2,\cdots,n\}$, let
    \begin{align*}
        h_\kappa(x,i)=1-\frac{1}{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)x_m}.
    \end{align*}
    Let $\mathcal L_\kappa$ denote the generator of the Markov chain $Z_\kappa$. Then for each large enough $\kappa$, there exists some constant $b$ (depending implicitly on $\kappa$ but not on $x$ or $i$) such that $\mathcal L_\kappa h_\kappa(x,i)>0$ whenever $v\cdot x\ge b$.
\begin{proof}
    For $i=1,\cdots,n$, let $\widetilde{\mathcal R}_i$ denote the subset of $\mathcal R_i$ consisting of reactions which do not take the $m$-th species as an input for any $m\notin I$. In words, $\widetilde{\mathcal R}_i$ is the set of reactions $y\to y'$ such that every species which appears in $y$ is visible to $v$.

We claim that if $y\to y'\notin\widetilde{\mathcal R}_i$ then $h_\kappa(x-y+y',i)\ge h_\kappa(x,i)$. Indeed, suppose that $y\to y'\notin\widetilde{\mathcal R}_i$. If $m\notin I$ then $v_m+\kappa^{-1}z^m_i=0$ and if $m\in I$ we have $y'_m-y_m\ge0$ (it is important here that $y$ is at-most-monomolecular). It follows that each term in the sum in the denominator of $h_\kappa(x-y+y',i)$ is no smaller than the corresponding term in $h_\kappa(x,i)$, so $h_\kappa(x-y+y',i)\ge h_\kappa(x,i)$ as claimed.

Notice that for each $x$ and each $i$,
\begin{align*}
    &\mathcal L_\kappa h_\kappa(x,i)\\
    &=\sum_{j\ne i}\kappa q_{ij}(h_\kappa(x,j)-h_\kappa(x,i))
    +\sum_{y\to y'\in\mathcal R_i}\lambda_{i,y\to y'}(x)(h_\kappa(x-y+y',i)-h_\kappa(x,i))\\
    &\ge\sum_{j\ne i}\kappa q_{ij}(h_\kappa(x,j)-h_\kappa(x,i))
    +\sum_{y\to y'\in\widetilde{\mathcal R}_i}\lambda_{i,y\to y'}(x)(h_\kappa(x-y+y',i)-h_\kappa(x,i))\\
    &=\frac{1}{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)x_m}\left(\sum_{j\ne i}\frac{\kappa q_{ij}\sum\limits_{m=1}^d\kappa^{-1}(z_j^m-z_i^m)x_m}{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_j)x_m}
    +\sum_{y\to y'\in\widetilde{\mathcal R}_i}\frac{\lambda_{i,y\to y'}(x)\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)(y'_m-y_m)}{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)(x_m-y_m+y'_m)}\right)\\
    &=:g_\kappa(x,i)
\end{align*}
where the inequality follows from the discussion in the previous paragraph, and the last line is the definition of $g_\kappa$.

Consider the quantity
\begin{align*}
    *:=\sum_{j\ne i}\frac{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)x_m}{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_j)x_m}\left( q_{ij}\sum\limits_{m=1}^d(z_j^m-z_i^m)x_m\right)
    +\sum_{y\to y'\in\widetilde{\mathcal R}_i}\lambda_{i,y\to y'}(x)\sum_{m=1}^d (v_m +\kappa^{-1} z^m_i)(y'_m-y_m).
\end{align*}
The difference between $*$ and $(1+\sum_{m=1}^d (v_m +\kappa^{-1} z^m_i)x_m)^2 g_\kappa(x,i)$ is 
\begin{align*}
    *\,-\,&\left(1+\sum_{m=1}^d (v_m +\kappa^{-1} z^m_i)x_m\right)^2g_\kappa(x,i)\\
    &=\sum_{y\to y'\in\widetilde{\mathcal R}_i}\sum_{m=1}^d\lambda_{i,y\to y'}(x) (v_m +\kappa^{-1} z^m_i)(y'_m-y_m)\left(1-\frac{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)x_m}{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)(x_m-y_m+y'_m)}\right)\\
    &=\sum_{y\to y'\in\widetilde{\mathcal R}_i}\sum_{m=1}^d\lambda_{i,y\to y'}(x) (v_m +\kappa^{-1} z^m_i)(y'_m-y_m)\left(\frac{\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)(y'_m-y_m)}{1+\sum\limits_{m=1}^d (v_m +\kappa^{-1} z^m_i)(x_m-y_m+y'_m)}\right).
\end{align*}
The term $\lambda_{i,y\to y'}(x) (v_m +\kappa^{-1} z^m_i)(y'_m-y_m)$ only depends on $x$ via $\lambda_{i,y\to y'}(x)$, and since the mass-action CRN associated to $M_i$ has at-most-monomolecular reactions we know that $\lambda_{i,y\to y'}(x)$ is at most linear in $x$. Moreover, by definition of $\widetilde{\mathcal R}_i$ we know that the coeffi (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn def-boltzmann of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] For $k  \in \mathbbm N$, let $\mathbbm M^{(k)}$ be the set of finite bipartite planar maps $\mathfrak m$ with a distinguished face (called the \textbf{external face}) of degree $2k$. 
For $\mathfrak m \in \mathbbm M^{(k)}$, we write $\mathcal F \mathfrak m$ for its set of non-external faces. 
Let $\mathbf{q} = \{q_i\}_{i \in \mathbbm N}$ be a sequence of non-negative real numbers. We say that $\bf{q}$ is \textbf{admissible} if 
\begin{equation*}
W_k(\mathbf{q}) := \sum_{\mathfrak m \in \mathbbm M^{(k)}} \prod_{f \in \mathcal F \mathfrak m}  q_{\deg(f) /2} < \infty , \quad \forall k \in \mathbbm N .
\end{equation*}
In this case, we define the \textbf{Boltzmann map} of perimeter $2k$ with weights $\bf q$ to be the random planar map $M $ such that for each $\mathfrak m \in \mathbbm M^{(k)}$, 
\begin{equation*}
\mathbbm P\mathopen{}\mathclose\bgroup\originalleft[ M = \mathfrak m \aftergroup\egroup\originalright] =  \frac{1}{W_k(\bf{q})}  \prod_{f \in \mathcal F \mathfrak m}  q_{\deg(f) /2} .
\end{equation*}

[Proposition 17 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] Assume $\Delta<\Delta_1$, where $\Delta_1$ is the constant in Corollary~\ref{cor:push-forward}. Then under the assumption of Theorem~\ref{thm:main}, one has
    \begin{equation}
    \HN(t+1)\leq \HN(t)+R_t,\quad t=0,1,\dots,T-1,
    \end{equation}
    where
    \begin{equation}
        R_t:=\frac{1}{N}\int_{\T^N}\rho_{N,t}(X)\left[\sum_{i=1}^N\log{\frac{\bar{\rho}_t(x_i)}{\bar{\rho}_t(\phi_{\bar{\rho}_t}^{-1}(\Phi_i(X)))}}+\log{\frac{\prod_{i=1}^N \phi_{\bar{\rho}_t}'(\phi_{\bar{\rho}_t}^{-1}(\Phi_i(X)))}{|D\Phi|(X)}}\right]\dd X.
    \end{equation}

