If $z \in   L_{{\mathbb{F}}}^2 (\Omega; C([0,T];H_{\rm loc}^1(G)))\cap L_{{\mathbb{F}}}^2 (\Omega; C^{1}([0,T];L^2_{\rm loc}(G))) $ is a solution to the equation     (system1 of the paper) satisfying that

\begin{equation}
z=\frac{\partial z}{\partial\nu} = 0 \quad\mbox{ on } (0,T)\times
S,\;\;{\mathbb{P}}\mbox{-}\hbox{\rm a.s.} ,
\end{equation}

then for the neighborhood ${\cal V}$ given in  (def1 of the paper) and some $\varepsilon\in (0,T/2)$,
it holds that

\begin{equation}
z = 0 \quad\mbox{ in } ({\cal V}\cap {\cal D}_{\rho}^+)\times
(\varepsilon,T-\varepsilon),\;\;{\mathbb{P}}\mbox{-}\hbox{\rm a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Langevinlower of arXiv:2607.10801, 'Relaxation times of non-reversible\\ Markov processes'] \begin{enumerate}[(i)]
        \item If $\alpha = 0$, then
        \begin{equation*}
            \sing(\mathcal{L})\ \leq \ 2\gamma\,.
        \end{equation*}
        In particular, $\overline{t}_\mathrm{rel} \geq \frac{1-e^{-1}}{\gamma}$ and $t_\mathrm{rel} \geq \frac{1-e^{-1}}{2\gamma}$.

        \item In general, we have
        \begin{equation*}
            \sing(\mathcal{L})\ \leq\ (\gamma^{-1}+\alpha)\widetilde m\qquad\text{with}\qquad \widetilde m\ =\ \inf_{\substack{f\in L_0^2(\nu)\\ f\text{ affine}}}\frac{\norm{\mathcal{L}_xf}}{\norm{f}}\,.
        \end{equation*}
        In particular, $\overline{t}_\mathrm{rel}\geq\frac{2(1-e^{-1})}{\widetilde m(\gamma^{-1}+\alpha)}$ and $t_\mathrm{rel}\geq\frac{1-e^{-1}}{\widetilde m(\gamma^{-1}+\alpha)}$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:lemma2 of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Consider the Bass/{\rm SI} model~{\rm ((eqs:Bass-SI-models-ME of the paper),(eqs:ER-network of the paper))} on $\lim_{M\to \infty} {\cal G}(M,\frac{\lambda}{M})$. Then
	\begin{equation}

		\overline{[S^\infty]}(t)=\sum_{d=0}^{\infty}\mathbb{P}_{\rm deg}(d) \,

		\overline{[S^\infty_{B_{d}}]}(t),
	\end{equation}
	where $\mathbb{P}_{\rm deg}(d)$ is given by~(equation eq:pois of the paper).

[Lemma 9 of arXiv:2609.01346, '2609.01346'] For all sufficiently small $\delta$ and $0<s<s_1(\delta)$,
