[Cor 33 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma \geq 1$, $0 \leq s \leq t \leq T$, $\delta \in [0, \; 1]$ and $n \in \mathbb{N}_+$. It holds
\begin{align*}
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{  \sqrt{n} } \int_s^t \dd r \sum_{x} \sum_{z=1}^{L_n-1}   [  H ( \tfrac{ \lfloor x+z - r v_n \rfloor }{n}  ) - H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )  ] a(z)   \bar{\xi}_x^{\alpha}( \eta_r^n ) \big[ \bar{\xi} _{x+z}^{\beta}( \eta_r^n ) - \bar{\xi} _{x+1}^{\beta}( \eta_r^n ) \big] \Bigg\}^{2} \Bigg] \\
	\leq & \widehat{C}(t-s)^{1+\delta} \Bigg( \frac{\big[ \Theta(n) K_n\big]^{\delta+1} }{n^{2}} + \big[  K_n \big]^2 f_{\delta}(n)   \Bigg),
\end{align*} 
where $f_{\delta}:\mathbb{N}_+ \mapsto \mathbb{R}$ is given by
\begin{align} 
\forall n \in \mathbb{N}_+, \quad f_{\delta}(n):= 
\begin{dcases}
 (L_n/n)^{ 1 - \delta } \big[ \log(L_n) \big]^{2 \delta} , \quad & \gamma  =1, \\
  (L_n/n)^{ (2-\gamma)(1 - \delta) }     n^{2 \delta (\gamma-1) }, \quad & 1 < \gamma  <2, \\
 n^{2 \delta} \big[ \log(L_n) \big]^{1 - \delta} \big[ \log(n) \big]^{-1-\delta}, \quad & \gamma  =2, \\
 n^{2 \delta}, \quad & \gamma > 2. 
\end{dcases}
\end{align}
Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem mininf of arXiv:2411.16651, 'On a problem of optimal mixing'] Let $X$ and $Y$ be compact Souslin spaces and let cost function  $c: X\times Y \to [0,+\infty)$ be continuous. Let $\mu_1,\dots,\mu_n,$ and $\nu$ be atomless probability measures on $X$ and $Y$ respectively, then 
        \begin{equation}
        \min_{\pi\in\Pi(\overline{\mu},\nu)} \int c(x,y)\; d\pi = \inf_{T\in\mathcal{T}(\overline{\mu},\nu)} \int c(x,T(x))\; d\mu
        \end{equation}

[Lemma 192 (Top order commutation identities in the first order formulation) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following identities hold for $i = 1,2,3$:
	\begin{subequations}
		\begin{align}
			\upmu \Transport \tander^N \LogDensity & = -\upmu \p_a \tander^N v^a + \, ^{(\tander^N)}\ehcurrent_{(\LogDensity)},   \\ 
			\upmu \Transport \tander^N v^i & = - \upmu \Speed^2 \p_i \tander^N \LogDensity + \, ^{(\tander^N)}\ehcurrent_{(v;1)}^i,   \\
			\upmu \Transport \tander^N \vortrenormalized^i & = \upmu \vortrenormalized^a \p_i \tander^N v^a - \upmu \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \upepsilon_{iab}\left(\Transport \tander^N v^a\right) \GradEnt^b + 	\, ^{(\tander^N)}\ehcurrent_{(\vortrenormalized;1)}^i,  \\
			\upmu \Transport \tander^N \GradEnt^i & = - \upmu \GradEnt^a \p_i \tander^N v^a + \, ^{(\tander^N)}\ehcurrent_{(\GradEnt;1)}^i, 
		\end{align}
	\end{subequations}
where $^{(\tander^N)}\ehcurrent_{(\vortrenormalized;1)}^i$ and $^{(\tander^N)}\ehcurrent_{(\GradEnt;1)}^i$ are as in \eqref{E:SHARPDECOMPOSITIONOFTOPORDEREXTERIORDERIVATIVEOFVORTFIRSTERRORTERM},\eqref{E:SHARPDECOMPOSITIONOFTOPORDEREXTERIORDERIVATIVEOFGRADENTFIRSTERRORTERM}, respectively, and: 
\begin{subequations}
		\begin{align}
			 ^{(\tander^N)}\ehcurrent_{(\LogDensity)} & = [\upmu\Transport,\tander^N]\LogDensity + [\upmu\p_a,\tander^N]v^a,  \\
			 \begin{split} 
			 	^{(\tander^N)}\ehcurrent_{(v;1)}^i & = [\upmu \Transport ,\tander^N ] v^i + \Speed^2 [\upmu \p_i,\tander^N]\LogDensity - \sum_{\substack{ \tander^{N_1}\tander^{N_2} =\tander^N \\ N_2 \le N-1}} \left( \tander^{N_1}(\Speed^2)\right) \tander^{N_2}\left( \upmu \p_i \LogDensity\right) \\
				 & \ \ - \tander^N \left\{ \upmu \exp(-\LogDensity) \frac{p_{;\Ent}}{\overline{\varrho}} \GradEnt^i\right\}.
			\end{split}
		\end{align}
	\end{subequations}
In addition, the following identities hold: 
\begin{subequations}
		\begin{align}
			\upmu \Flatcurl \left( \tander^N v\right)^i & = \upmu \exp(\LogDensity)  \tander^N \vortrenormalized^i + \, ^{(\tander^N)}\ehcurrent_{(v;2)}^i  \\
			\upmu \Flatdiv \left( \tander^N\vortrenormalized\right) & = - \vortrenormalized^a \upmu \p_a \tander^N \LogDensity + \, ^{(\tander^N)}\ehcurrent_{(\vortrenormalized;3)},  \\			
			\begin{split}  
				\upmu \left( \Flatcurl \tander^N \vortrenormalized\right)^i & = \upmu \exp(\LogDensity) \tander^N\VortVort^i + \upmu \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \left( \p_a \tander^N v^a\right) \GradEnt^i \\
				& - \upmu \exp(-2\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \GradEnt^a \p_a \tander^N v^i + \, ^{(\tander^N)}\ehcurrent_{(\vortrenormalized;2)}^i ,
			\end{split} \\
			\begin{split}  
				\upmu \Flatdiv\left( \tander^N \GradEnt\right) & = \upmu \exp(2\LogDensity) \tander^N \DivGradEnt + \upmu S^a\p_a \tander^N \LogDensity + \, ^{(\tander^N)}\ehcurrent_{(\GradEnt;3)},
			\end{split}
		\end{align}
	\end{subequations}
where  $^{(\tander^N)}\ehcurrent_{(\vortrenormalized;2)}^i$ is as in \eqref{E:SHARPDECOMPOSITIONOFTOPORDEREXTERIORDERIVATIVEOFVORTSECONDERRORTERM} and: 
	\begin{align}
			 \, ^{(\tander^N)}\ehcurrent_{(v;2)}^i & = [\upmu\Flatcurl,\tander^N] v^i  + [\tander^N,\upmu] v^i + \sum_{\substack{\tander^{N_1}\tander^{N_2} = \tander^N \\ N_1 \le N-1}} \upmu (\tander^{N_1} \vortrenormalized^i) \tander^{N_2}(\exp(\LogDensity))  \\
			^{(\tander^N)}\ehcurrent_{(\vortrenormalized;3)} & =  [\upmu \p_a,\tander^N]\vortrenormalized^a + \vortrenormalized^a [\upmu\p_a,\tander^N]\LogDensity  - \sum_{\substack{\tander^{N_1}\tander^{N_2}=\tander^N \\ N_2 \le N - 1}} \left(\tander^{N_1}\vortrenormalized^a\right) \tander^{N_2}\left(\upmu \p_a \LogDensity\right) \\
		\begin{split}
			^{(\tander^N)}\ehcurrent_{(\GradEnt;3)} & = [\upmu \p_a, \tander^N] \GradEnt^a + \sum_{\substack{\tander^{N_1}\tander^{N_2}\tander^{N_3}=\tander^N \\ N_3 \le N-1}} \left( \tander^{N_1}\upmu\right) \left(\tander^{N_2} \exp(2\LogDensity)\right) \tander^{N_3} \DivGradEnt \\
			& \ \ - S^a[\upmu\p_a,\tander^N ]\LogDensity + \sum_{\substack{\tander^{N_1}\tander^{N_2}=\tander^N \\ N_2 \le N - 1

[Prop 10 of arXiv:2604.20323, '2604.20323'] \cite[Proposition 2]{chau:jabi:meno:22-1}
Let  $b\in L^\vartheta((t,T],B_{p,q}^\beta)$ and {\color{black} $\beta\in (-1,0] $}, $1\le p,q \le \infty $.
There exists a sequence of \textcolor{black}{time-space} smooth bounded functions $(b^\varepsilon)_{\varepsilon >0} $ s.t.
\begin{equation*}
\|b-b^\varepsilon\|_{L^{\bar \vartheta}((t,T],B_{p,q}^{\tilde \beta})} \underset{\varepsilon \rightarrow 0}{\longrightarrow} 0,\quad \forall \tilde \beta<\beta,
\end{equation*}
with $\bar \vartheta=\vartheta $ if $\vartheta<+\infty $ and for any $\bar \vartheta<+\infty $ if $\vartheta=+\infty$. Moreover, there exists $ \cc\ge 1$, $\displaystyle \sup_{\varepsilon>0}|b^\varepsilon|_{L^{\bar \vartheta}((t,T],B_{p,q}^{\beta})}\le \textcolor{black}{\cc} |b|_{L^{\bar \vartheta}((t,T],B_{p,q}^{\beta})}$.

If $p,q,\vartheta<+\infty$ it then also holds, see e.g. \cite{lema:02}, that 
\begin{equation*}
\|b-b^\varepsilon\|_{L^{ \vartheta}((t,T],B_{p,q}^{\beta})} \underset{\varepsilon \rightarrow 0}{\longrightarrow} 0.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

