body:
[Lemma lm:lclt_con_time of arXiv:2605.09377, 'A factorization formula for the partition function in the semi-discrete parabolic Anderson'] For any $y \in \mathbb{Z}^d$ such that $\| y \| \leq \frac{t}{2 \sqrt{d}}$, we have for the transition probability of the continuous-time simple symmetric random walk on $\mathbb{Z}^d$ 
\begin{equation}     
p_t^y = \left(\tfrac{d}{2 \pi t} \right)^{\frac{d}{2}} 
		\exp \big( -\tfrac{d}{2t} \| y \|^2 \big) 
		\exp \left( O \left(  \frac{1}{\sqrt{t}} + \frac{\| y \|^3}{t^2} \right) \right).
\end{equation}
Therefore, for any $\sigma \in (0,1)$ and $t$ sufficiently large,
\begin{equation}
	\frac{1}{p^y_t} \leq e^{t^{\sigma}}, \qquad \forall y \in \mathbb{Z}^d: \|y\| \leq t^{\sigma}. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 43 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $(Y,Y') \in \scrd_X^{2\alpha}([0,T],W)$ and $\varphi \in L(W,\bar{W})$ be arbitrary. Then we have
\begin{align}
(\varphi(Y),\varphi(Y)') \in \scrd_X^{2\alpha}([0,T],\bar{W})
\end{align}
and the estimates
\begin{align}
\| \varphi(Y), \varphi(Y)' \|_{X,2\alpha} &\leq | \varphi | \, \| Y,Y' \|_{X,2\alpha},
\\  | \varphi(Y), \varphi(Y)' |_{X,2\alpha} &\leq | \varphi | \, | Y,Y' |_{X,2\alpha},
\\  \interleave \varphi(Y), \varphi(Y)' \interleave_{X,2\alpha} &\leq | \varphi | \, \interleave Y,Y' \interleave_{X,2\alpha}.
\end{align}

