[Theorem thm:CRP of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] If $j_n/(\log n)^2\to\infty$ and 
 \begin{equation}
 j_n = o\pp{\frac{n^{\alpha/(1+\alpha)}}{(\log\log n)^{1/(1+\alpha)}}},
 \end{equation}
  then
\begin{equation}
\frac{j_n^{(\alpha+1)/2}}{n^{\alpha/2}}\pp{C_{j_n}(\floor{s_n(t)})-s_n(t)^\alpha p_{j_n}\topp\alpha S_\alpha}_{t\in{\mathbb R}}\stackrel{a.s.w.}\to \pp{\frac{\alpha}{\Gamma(1-\alpha)}S_\alpha}^{1/2}\pp{\zeta_t}_{t\in{\mathbb R}}
\end{equation}
in $D({\mathbb R})$ equipped with the local $J_1$ topology with respect to ${\mathcal P}$, where $(\zeta_t)_{t\in{\mathbb R}}$ is a stationary Ornstein--Uhlenbeck Gaussian process, independent of ${\mathcal P}$. Namely, $(\zeta_t)_{t\in{\mathbb R}}$  is a centered Gaussian process with covariance function
\[
{\rm{Cov}}(\zeta(s),\zeta(t)) = e^{-|s-t|}, s,t\in{\mathbb R}.
\]
If $j_n\to\infty$ and (equation eq:j_n upper of the paper) hold but $j_n/(\log n)^2\not\to\infty$, then the convergence in (equation eq:CRP limit of the paper) still holds in the sense of weak convergence. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem annealed cond of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Suppose that $\xi$ has at least two distinct nonzero coefficients $\beta_p^2$ (mixed case). Let $n\ge2$. Let $\bm{u}=(u_1,\ldots,u_{n})$ and $\bm{q}=(q_1,\ldots,q_n)$
		be strictly increasing sequences in $(0,1)$, and let
		$\zeta\in\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})$.
		Using the notation of~(equation def:Par of the paper), define the \emph{prefix free en\-ergy}
		\begin{equation*}
			\mathcal{P}^{(n)}(\bm{u};\bm{q})
			\;:=\;
			\inf_{\zeta'\,\in\,\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})}
			\mathcal{P}\mathrm{arisi}(\zeta'),
		\end{equation*}
		and the \emph{$n$-step complexity functional at level $f$}
		\begin{equation*}
			\mathcal{C}^{(n)}_f(\bm{u};\bm{q})
			\;:=\;
			u_n\,\bigl(\mathcal{P}^{(n)}(\bm{u};\bm{q})-f\bigr).
		\end{equation*}

		We assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality)} The infimum $\mathcal{P}^{(n)}(\bm{u};\bm{q})$ is
			attained at $\zeta$.
			\item[\emph{(ii)}]
			\emph{(Stationarity)} $(\bm{u};\bm{q})$ is a critical point of
			$\mathcal{C}^{(n)}_f$.
		\end{enumerate}
		Fix $\varepsilon\in(0,1)$ and fix an ancestor skeleton
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)})$
		satisfying the admissibility conditions stated in Section~(section:multiple of the paper)
		(Definitions~(def:susyreplicas of the paper) and~(def:matchlaw of the paper)).

		Let $\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})$ be the number of critical points
		$\mathbf{m}$ of $F_{\mathrm{TAP},\zeta}$ lying in the orthogonal band of $\mathbf{m}^{(n-1)}$
		(and satisfying $\tfrac1N F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$). Set
		\begin{equation*}
			\mathrm{Skel}_{n-1}=\left(\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),\ldots,\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)}), F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)})\right).
		\end{equation*}

		Then
		\begin{multline}
			\lim_{\varepsilon\to0}\lim_{N\to\infty}
			\frac{1}{N}\log\mathbb{E}\Bigl[
			\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})
			\;\Big|\;
			\mathrm{Skel}_{n-1}=(0,N\mathcal{P}\mathrm{arisi}(\zeta),\ldots,0,N\mathcal{P}\mathrm{arisi}(\zeta))
			\Bigr]
			\geq
			\mathcal{C}_f^{(n)}(\bm{u};\bm{q})
			\\=
			\zeta([0,q_n))\,(\mathcal{P}\mathrm{arisi}(\zeta)-f).
		\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 17 (Symmetric ridge-product equation) of arXiv:2608.26693, '2608.26693'] Fix $c\in(0,1)$ and $r>0$, let $\rho=\rho_{c,r}$, $\lambda=\rho\boxtimes\rho$, and write
\[
Y(z):=\eta_\lambda(z),\qquad
D_{c,r}:=1+r-cr,\qquad E_{c,r}:=1+r+cr.
\]
The physical analytic branch $Y$ is characterized by the algebraic relation
\begin{equation}
P_{c,r}(z,Y(z))=0,
\end{equation}
where
\begin{equation}
P_{c,r}(z,y)
:=zy(D_{c,r}y-E_{c,r})^2
-r^2\bigl[z\{1+(c-1)y\}+cy\bigr]^2.
\end{equation}
The branch relevant to the free product is selected by
\begin{equation}
Y(z)=m_1(\rho)^2z+O(z^2),\qquad z\to0,
\end{equation}
together with the Pick normalization in Proposition~\ref{prop:subordination}.

[Theorem thm:uniqueness_heat_eq of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $(\bm{u}_t)_{t \in [0, T]}$ be an It\^o-admissible solution to (equation eq:heat_eq_coef_sig of the paper), with terminal condition $\bm{u}_T = 0\,$. Assume moreover that there exists $g : \mathbb{R}_+ \to \mathbb{R}_+$ with $g(x) = o(e^{c x^{2}})$ as $x \to \infty$ for some $c > 0\,$, such that 
    \begin{equation}
        \sup_{t \in [0, T]}|\bracket{\bm u_t}{\sigW[s]}| \leq g\left(\sup_{0 \leq r \leq s}|W_r|\right)\,, \quad s \in [0\,,T]\,.
    \end{equation}
    Then $\bm{u} \equiv 0$ on $[0\,,T]\,$.

[Corollary cor:2e-probabilities-boundarycases of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] When $\delta=1/\gamma$, the two-edge crossing probabilities satisfy
    \begin{align*}
        \pi_{(u),R}^{(2)} 
        &\asymp \begin{cases}
                    u^{-\gamma} h(R) , & \text{ on } \{R^{-d}{(\log R)^{\frac{\gamma}{1-\gamma}}}\le u\},\vspace{0.3mm}\\
                    u^{-1} g(R) & \text{ on } \{ R^{d(1-\frac 1 \gamma)} \log R\le u\le R^{-d}{(\log R)^{\frac{\gamma}{1-\gamma}}}\},\vspace{0.3mm}\\
                    1 & \text{ on } \{u\le R^{d(1-\frac 1 \gamma)}\log R\}.
                \end{cases}\\
        \pi_{r,R}^{(2)}
        &
        \asymp \begin{cases}
                    r^{d\gamma}  (\log r)^\gamma h(R) & \text{ on } \{r \leq R (\log R)^{\frac{-1}{d(1-\gamma)}}\},\vspace{0.3mm}\\
                    r^d  g(R) \log R  & \text{ on } \{R (\log R)^{\frac{-1}{d(1-\gamma)}} \leq r \leq R/2 \}.
                \end{cases}
    \end{align*}

    When $\delta=1/\gamma-1>2$, they satisfy

    \begin{align*}
        \pi_{(u),R}^{(2)} 

        &\asymp \begin{cases}
                    u^{-\gamma} h(R) & \text{ on } \{u \geq (\log R)^{-\frac 1 {1- 2\gamma}}\},\vspace{0.3mm}\\
                    u^{-\gamma \delta} g(R) & \text{ on } \{R^{d(\frac 1 {\gamma \delta}-\frac 1 \gamma)} \leq u \leq (\log R)^{-\frac 1 {1- 2\gamma}}\},\vspace{0.3mm}\\
                    1 & \text{ on } \{u\leq R^{d(\frac 1 {\gamma \delta}-\frac 1 \gamma)} \}.
                \end{cases}\\
        \pi_{r,R}^{(2)} 

        &\asymp \begin{cases}
                    r^{\frac d \delta} h(R) & \text{ on } 
                    \{ r^d \leq  (\log R)^{\frac \delta {\delta-1}}\} ,\vspace{0.3mm}\\
                    r^d g(R) & \text{ on } \{(\log R)^{\frac \delta {\delta-1}} \leq r^d  \}.
                \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 28 of arXiv:2609.02561, 'NON-NEF LOCI IN MIXED CHARACTERISTIC'] Let $f: X \rightarrow S$ be a projective morphism from a normal integral scheme to an integral Noetherian scheme.
Let $g:S'\rightarrow S$ be a flat morphism of integral Noetherian schemes such that $X':=X\times_{S}S'$ is normal (e.g., an open immersion or a localization at any point of $S$).
For every $\R$-Cartier $\R$-divisor $D$ on $X$,
\begin{equation*}
\begin{aligned}
{g'}^{-1}(\Bp(D/S)) = \Bp({g'}^{*}D/S'), \\
{g'}^{-1}(\Bm(D/S)) = \Bm({g'}^{*}D/S'),
\end{aligned}
\end{equation*}
where $g':X' \rightarrow X$ is the natural morphism.

