body:
[Thm THM61-2 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that  the volume growth condition (equation eq:41 of the paper) holds  with some constant $\alpha>0$, and the transition density function of $X$ satisfies 
\[
p(t,y,z)\leq  \frac{C_1}{t^{\alpha/\beta}}\exp\left\{-C_2\left(\frac{d(y,z)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall  0<t\leq T, \, y,z\in E,
\]
for some $\beta>1$, $T>0$, $C_1>0$ and $C_2>0$, then for any $x\in E$ and $B\in \mathscr{B}^n(E)$,
\begin{equation}
        \liminf_{t\downarrow 0}\frac{-t^{1/(\beta-1)}\cdot \left(\log \mathbb{P}^x[\sigma_B\leq t]\right)}{C_2}\geq  \widetilde{d}(x,B)^{\beta/(\beta-1)}.
\end{equation}

