[Lemma lemma3.3 of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, $x\in \mathbb{Z}^d$ and $A,D\subset  \widetilde{\mathbb{Z}}^d\setminus \widetilde{B}_x(1)$, and any increasing event $\mathsf{F}\subset \{x\xleftrightarrow{\le 0} A\}^{c}$ that is measurable with respect to $\mathcal{F}_{\widehat{\mathcal{C}}_A^{-}}$, we have 
	\begin{equation}
\mathbb{P}^{D}(\mathsf{F})	\mathbb{P}^{D}(x\xleftrightarrow{\ge 0} A)\lesssim 	\mathbb{E}^{D}\big[\widetilde{\phi}_x\cdot \mathbbm{1}_{ \mathsf{F}}  \big] =  \mathbb{E}^{D}\big[\mathcal{H}_x(\widehat{\mathcal{C}}_A^{-}\cup D) \cdot  \mathbbm{1}_{\mathsf{F}}\big]\lesssim \mathbb{P}^{D}(x\xleftrightarrow{\ge 0} A).
	\end{equation}

