[Lemma lem:grad of arXiv:2601.10568, 'Hydrodynamic Limit with a Weierstrass-type result'] Let $\ndef{\mathbf{J}_\beta}$ be the algebraic current, defined through $\mathcal{L}^{\beta,\ell_N}[\pi_0]=\nabla\tau^{-1}[-\mathbf{J}_{\beta,\ell_N}]$, where $\mathbf{J}_{\beta,\ell_N}$ is given, explicitly, by
\begin{align}
    \mathbf{J}_{\beta,\ell_N}
    =
    \frac{1}{\ell_N+1}
    \sum_{j=1}^{\ell_N}
    \mathbf{J}_{\beta}^j(\eta)
\quad\text{with}\quad
    \mathbf{J}_{\beta}^j(\eta)
    =\beta(\langle \eta\rangle_{j})
    (
    \mathbf{e}_{0,1}(\eta)
    -
    \mathbf{e}_{1,0}(\eta)
    )
    .
\end{align}

For each $\eta\in\Omega_N$, let $\ndef{P_{\ell_N}}(\eta)$ be the number of particles in the box $\llbracket0,\ell_N\rrbracket$. It holds that
\begin{align}
    \mathbf{J}_{\beta,\ell_N}=-\nabla \mathbf{H}_{\beta,\ell_N},
\end{align}
where $\mathbf{H}_{\beta,\ell_N}=\mathbf{h}_{\beta,\ell_N}+\mathbf{g}_{\beta,\ell_N}$ and 
\begin{align}

    \mathbf{h}_{\beta,\ell_N}(\eta)
    &=
    \frac{1}{\ell_N+1}
    \sum_{n=0}^{P_{\ell_N}(\eta)-1}
    \beta(\tfrac{n}{\ell_N})
    ,
    \\

    \mathbf{g}_{\beta,\ell_N}(\eta)
    &=
    \frac{1}{\ell_N+1}
    \sum_{j=1}^{\ell_N}
    \sum_{i=1}^{j}
    \tau^{-i}\mathbf{J}_{\beta,\ell_N}^j(\eta),

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

