body:
[Theorem prop_5 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $A$ be a symmetric matrix and 
\begin{eqnarray}

\alpha=\|A\|,\,\,\,\beta=\|A\|_2^2,\,\,\,\gamma=\|A\|_3^3.
\end{eqnarray}
Also, let 
\begin{eqnarray}

\eta_1(t)=\frac{1}{12\gamma^2}(\sqrt{\beta^2+4\gamma t}-\beta)(\beta^2+8\gamma t-\beta\sqrt{\beta^2+4\gamma t}\,)
\end{eqnarray}
and
\begin{eqnarray}

\eta_2(t)=\frac{t}{\alpha}-\frac{3\beta }{4\alpha}\min\bigg\{ \frac{1}{\alpha}, \frac{\sqrt{\beta^2+4\gamma t}-\beta}{2\gamma}\bigg\}.
\end{eqnarray}
Then 
\begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq \exp\big(-\kappa' \min\{\eta_1(t), \eta_2(t)\}\big),
\end{eqnarray}
where $\kappa'=\frac{b^*}{3}\approx 0.187$ with $b^*$ as the unique solution for $b$ in the equation $\frac{4}{\sqrt{3}}b\sqrt{\theta_2(b)}=1$ and~$\theta_2(b)$~as defined in~((theta_func of the paper)).

[Theorem thm:centrality-detailed of arXiv:2606.02472, 'Correlated uniform attachment trees'] Let $T_{n} \sim \mathrm{UA}(n)$ and recall that $A_K:=A_{K}(n)$ denotes the set of the $K$ most central vertices in~$T_{n}$. 
There exists a universal constant $C < \infty$ 
such that 
for every $K\in \N$, $c > 1$, and $\delta \in(0,c-1)$,
the following holds for all large enough $n \geq n_{0}(K,\delta,c)$: 
\[
\mathbb{P} \left( \babs{ A_{\ceil{c K}} (n) \cap \bclc{0,\ldots, K-1 }
}\geq \bclr{c (1-e^{-1/c})-\delta}K \right) 
\geq 1 - C \left(\frac{   c \log(c K) }{\delta ^2 K}+(0.7)^{\delta K/2}\right).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 21 of arXiv:2604.06122, 'REM universality for linear random energy'] Given $c\in (0,\gamma)$ and a $h-$measurable sequence $(C_n)_{n\in \N}$ such that
\been{

\lim_{n\to \infty}\res C_n(h)=c,\quad \gas
}
we have
\been{

\lim_{n\to \infty}\res A_n(h,C_n(h))=\hat{a}(c),\qquad \gas
}

