[Definition 4 of arXiv:2607.08314, 'Berry-Heisenberg random waves'] For any $g_{1}, g_{2} \in \Hei$, the Carnot-Carath\'eodory distance is defined by 
    \begin{align*}
         d_{cc} (g_{1}  , g_{2} ) := \inf \left\{ \int_{0}^{1} \Vert \gamma^{\prime}(t) \Vert_{\gamma (s)} ,  \gamma: [0,1] \longrightarrow \Hei , \gamma(0) = g_{1} , \gamma(1) = g_{2} ,  \gamma \text{ is horizontal }\right\}
    \end{align*}
    where $\Vert \cdot \Vert_{g}$ denotes the norm in $\mathcal{H}_{g}$ induced by the sub-Riemannian structure.

[Definition def:CAT(0) of arXiv:2512.13200, 'Martingales on a Euclidean manifold with a boundary and reflected BSDEs in non-convex doma'] Consider a metric space $(\mathcal{X},d_{\mathcal{X}})$. Then, $\mathcal{X}$ is a $CAT(0)$ space, a.k.a. Alexandrov non-positively curved space (shortly, NPC space), if, for all $(x,y,p,q) \in \mathcal{X}^4$ that admit minimizing geodesics $\gamma^{x,y}$, $\gamma^{x,p}$, $\gamma^{p,y}$, $\gamma^{x,q}$ and $\gamma^{q,y}$, we have, for all $z \in \gamma^{x,y}_{[0,1]}$,
\begin{align*} 
d_{\mathcal{X}}(p,q) \leqslant  d_{\mathbb{R}^2}(\tilde{p},\tilde{z}) + d_{\mathbb{R}^2}(\tilde{q},\tilde{z}),
\end{align*}
where $(\tilde{x},\tilde{y},\tilde{p})$ (resp., $(\tilde{x},\tilde{y},\tilde{q})$) is a triangle in $\mathbb{R}^2$ whose edges have Euclidean lengths equal to $d_{\mathcal{X}}(x,y)$, $d_{\mathcal{X}}(x,p)$, $d_{\mathcal{X}}(y,p)$ (resp., $d_{\mathcal{X}}(x,y)$, $d_{\mathcal{X}}(x,q)$, $d_{\mathcal{X}}(y,q)$), and $\tilde{z} \in [\tilde{x},\tilde{y}]$ is such that $d_{\mathbb{R}^2}(\tilde{x},\tilde{z})=d_{\mathcal{X}}(x,z)$.

[Lemma 11 of arXiv:2607.01629, 'Quadratic fluctuations of speed-change Kawasaki dynamics'] For every test function $f$, we have the following moment estimates for the remainder term $\mathcal R_1^N$:
		\begin{align*}
			&N^2\sum_{i=1}^d\sum_{x}\E_{\rho}\left[\mathcal R_{1}^N(f,x,i)^2\right]
			\leq C_{f}\left(N^{-2}L^2+N^{-d}L^{d+2}\right),
		\end{align*}
		and
		\begin{multline*}
			\quad N^4\sum_{i=1}^d\sum_{x}\E_{\rho}\left[\mathcal R_{1}^N(f,x,i)^4\right]\\
			\leq C_{f}N^{-d}\left(N^{-4}L^4+N^{-2-d}L^{d+3}+N^{-2d}L^{2d+3}+\left(N^{-4-d}L^{-2d}+N^{-2d}L^{-1}\right)\Vert \phi_L\Vert_\infty^4\right)\notag.
		\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 17 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\chi\in\Pi(G_1)$ and $\varphi\in\1_{n-2}\boxplus\chi\boxplus\chi^{-1}$ be $(s,z)$-independent.
		Also, recall
		\optionA{$\P_v(\lambda;\varphi_v,f_v,f_{v,s})$}
		\optionB{$\P_v(s,\lambda;\varphi_v,\Phi_v)$} from \eqref{eq:main-RS-period-local} and $\lambda_{\mathrm{C}}(s,z)$ from \eqref{eq:def-lambda-cont}. Then
		\begin{equation*}
			\optionA{\frac{\P_v(-\lambda_{\mathrm{C}}(s,z);\varphi_v,f_v,f_{v,s})L_v(1+2z,\chi_v^2)}
				{\prod_{\pm}L_v\left(\tfrac{n-1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm_v\right)
					L_v\left(\tfrac{1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm_v\right)}}
			\optionB{\frac{\P_v(s,-\lambda_{\mathrm{C}}(s,z);\varphi_v,\Phi_v)L_v(1+2z,\chi_v^2)}
				{\prod_{\pm}L_v\left(\tfrac{n-1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm_v\right)
					L_v\left(\tfrac{1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm_v\right)}}
		\end{equation*}
		can be analytically continued in $s,z\in\C^2$ as an entire function.

