[Definition 4 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Let $\{ \mathbb{\tilde{F}}_{i}[\cdot]\}_{i=1}^{\infty}$ be a
sequence of nonlinear expectations on $(\mathbb{R}^{d},C_{b.Lip}
(\mathbb{R}^{d}))$. $\{ \mathbb{\tilde{F}}_{i}[\cdot]\}_{i=1}^{\infty}$ is
called tight if there exists a tight sublinear expectation $\mathbb{\hat{F}
}[\cdot]$ on $(\mathbb{R}^{d},C_{b.Lip}(\mathbb{R}^{d}))$ such that
$\mathbb{\tilde{F}}_{i}[\cdot]$ is dominated by $\mathbb{\hat{F}}[\cdot]$ for
$i\geq1$.

[Proposition prop:2d_kernel_BGR of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] {borodin-gr2009q}}]

	The two-dimensional correlation kernel $\widetilde{K}(s,x;t,y)$
	of the $q$-Racah nonintersecting path ensemble is given by
	\begin{equation}

		\widetilde{K}(s,x;t,y)=
		\begin{cases}
			\displaystyle
			\sum_{n=0}^{N-1}
			(\widetilde{\mathscr{C}}_n^{t} \widetilde{\mathscr{C}}_n^{t+1}\ldots \widetilde{\mathscr{C}}_n^{s-1})^{-1}\hspace{1pt}
			f_n^s(x)\hspace{1pt} f_n^t(y),&\qquad  s\ge t;\\[12pt]
			\displaystyle
			-\sum_{n\ge N}
			(\widetilde{\mathscr{C}}_n^s \widetilde{\mathscr{C}}_n^{s+1}\ldots \widetilde{\mathscr{C}}_n^{t-1})\hspace{1pt}
			f_n^s(x)\hspace{1pt} f_n^t(y)
			,&\qquad  s<t.
		\end{cases}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 10 of arXiv:2606.20169, 'THEORY OF UNCERTAIN PROBABILITY:\\ CAN WE DERIVE THE PROBABILITY DENSITY FUNCTION OF UNCER'] The variance of an uncertain random variable $\mathbb{X}$ is defined by
\begin{equation}
\begin{aligned}
\sigma_{\mathbb{X}}^2=Var\left(\mathbb{X}\right)=E\left[\left(\mathbb{X}-E(\mathbb{X})\right)^2\right].
\end{aligned}
\end{equation}

Its nonnegative square root denoted by $\sigma_{\mathbb{X}}$ is the standard deviation of $\mathbb{X}$. If $z$ is a positive integer, then $E\left(\mathbb{X}^z\right)$ is called the $z$th moment of $\mathbb{X}$.

[Proposition prop:IPS:entropy-change:in-terms-of-generator of arXiv:2605.16904, 'Positive-rate PCA and IPS with stationary Bernoulli measures are rapidly forgetful \footno'] Let $\Phi$ be an IPS with generator~$L$ on $\Sigma^{\mathbb{Z}^d}$, and let $\lambda$ be a full-support probability measure that is stationary under~$\Phi$.  Let $\mu$ be a probability measure and $J\Subset\mathbb{Z}^d$.
	Let $\mu^t\coloneqq\mu\Phi^t$ and $D_J(t)\coloneqq D_J(\mu^t\relto\lambda)$.
	Then, at every $t\geq 0$, $D_J(t)$ is differentiable with
	\begin{equation}
		\dot{D}_J(t) =
			\sum_{w\in\Sigma^J} (\mu^t L)([w])\log\frac{\mu^t([w])}{\lambda([w])}
	\end{equation}
	unless $\mu^t([w])=0$ for some $w\in\Sigma^J$.

[Definition 6 of arXiv:2604.10705, '#1'] {}
A functional $F$ is said to be space-differentiable at $(t,x) \in [0,T]\times D([0, T],\mathbb{R}^d)$, in the direction of the canonical basis vector $e_i$, $i \in \{1,...,d\}$, if the following limit exists:
\begin{align}
    \partial_i F(t,x_{\wedge t}) &:= \lim_{h \to 0}\frac{F(t,x_{\wedge t}^{he_i})-F(t,x_{\wedge t})}{h}.
\end{align}

If $F$ is space-differentiable at $(t,x)$ in the direction of $e_i$, for every $(t,x) \in [0,T] \times D([0,T],\mathbb{R}^d)$ and every $i \in \{1,\ldots,d\}$, we say that $F$ is \emph{space-differentiable} and denote the gradient of space derivatives by $\nabla F := (\partial_1 F,\ldots,\partial_d F)$.

[Proposition prop for tightness two of arXiv:2504.06238, 'Infinite Boundary Friction Limit for Weak Solutions of the Stochastic Navier-Stokes Equati'] For any sequence of stopping times $(\gamma_n)$ with $\gamma_n: \Omega \rightarrow [0,T]$, and any  $R > 1$, $\phi \in W^{1,2}_{\sigma}$,
    \begin{equation} 
    \lim_{\delta \rightarrow 0^+}\sup_{n \in \mathbb{N}}\mathbbm{E}\left(\left\vert\left\langle \hat{u}^{n}_{(\gamma_n + \delta) \wedge T} - \hat{u}^{n}_{\gamma_n} , \phi \right\rangle \right\vert\right)= 0.
\end{equation} 
Moreover the sequence of the laws of $(u^n)$ is tight in the space of probability measures over\\ $C\left([0,T];W^{-\varepsilon,2}_{\sigma}\right)$.

[Corollary 2 of arXiv:2604.06823, 'On spectrum of sample correlation matrices from large fold tensor vectors'] Let the limiting conditions \eqref{eq-def-ratio}, \eqref{eq-def-tau} and \eqref{eq-lim-k} hold. Assume that the base random vector $\y$ is uniformly distributed on the unit sphere $S^{2n-1}$ of $\bC^n$. We set $Y' = (Y_1,\ldots,Y_m)$ and define
\begin{align*}
    M_{n,k,m}' = Y' \Lambda_m Y'^* = \sum_{\alpha=1}^m \tau_\alpha Y_\alpha Y_\alpha^*.
\end{align*}
Then there exists a probability distribution function $F_c$, such that
\begin{align*}
    \lim_{n \to \infty} F^{M_{n,k,m}'} = F_c
\end{align*}
in probability.
Moreover, in the case that $\tau_\alpha \equiv 1$, the limiting distribution function $F_c$ is exactly the Mar\v{c}enko-Pastur law with density function \eqref{eq-MP law}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Given the canonical measurable space $(\Omega,\mathcal{F}_\infty)$, the probability mesaure $\mathbb{P}$ on $(\Omega,\mathcal{F}_\infty)$, the probability kernels $\mathbb{P}_s^i$, $s\in[0,\infty)$, $i\in\mathcal{Z}$, on $(\Omega,\mathcal{F}_\infty)$, and the collection
\begin{align*}
\mathcal{P} := \big((\mathbb{P}_s^i)_{s \in [0,\infty),i\in\mathcal{Z}},\mathbb{P}\big)
\end{align*}
defined by Theorem~(TheoremCanoncialSpace of the paper) are called the \emph{canonical probability measure}, \emph{canonical probability kernels}, and \emph{canonical probability model} generated by $(\alpha, \Lambda)$, respectively.

[Lemma lem-AbstractLDP of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Let ${\mathcal X }, {\mathcal Y }$ be two Polish spaces and pick $\rho\in{\mathcal M }_1({\mathcal X })$ and let $(x_i^{{{\scriptscriptstyle{({n}})}}})_{i\in\mathbb{N}}$ be a sequence in ${\mathcal X }$ such that $\frac 1n \sum_{i=1}^n\delta_{x_i^{{{\scriptscriptstyle{({n}})}}}}$ converges weakly towards $\rho$ as $n\to\infty$. Let $\zeta\colon {\mathcal X }\times \sigma({\mathcal Y })\to[0,1]$ be a continuous Markov kernel from ${\mathcal X }$ to $ {\mathcal Y }$, where $\sigma({\mathcal Y })$ denotes the Borel sigma field on ${\mathcal Y }$. Furthermore, let $(Y_i^{{{\scriptscriptstyle{({n}})}}})_{i\in[n]}$ have the distribution $\bigotimes_{i\in [n]} \zeta(x_i^{{{\scriptscriptstyle{({n}})}}},\cdot)$. Then the empirical pair measure $\frac 1n\sum_{i=1}^n \delta_{(x_i^{{{\scriptscriptstyle{({n}})}}},Y_i^{{{\scriptscriptstyle{({n}})}}})}$ satisfies an LDP with rate function
\begin{equation}
{\mathcal M }_1({\mathcal X }\times{\mathcal Y })\ni q\mapsto \begin{cases} H_{{\mathcal X }\times{\mathcal Y }}(q\,|\,\rho\otimes \zeta)&\mbox{if }\pi_1(q)=\rho,\\
+\infty&\mbox{otherwise,}
\end{cases}
\end{equation}
where $\pi_1$ is the canonical projection ${\mathcal X }\times{\mathcal Y }\to{\mathcal X }$, and $\pi_1(q)$ is the corresponding image measure. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition propHidden of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] For any solution to the equation (equation ch-5-4.12-eq1 of the paper), we have

\begin{align}
    \notag
    &  \Big|\frac{\partial y}{\partial \nu}\Big
    |_{L^2_{{\mathbb{F}}}(0,T;L^2(\Gamma_0))} 
    \\ \notag
    & \leq e^{{\cal C}(L^2 + 1)}
    \Big(|(y_0,y_1)|_{L^2_{{\cal F}_0}(\Omega; H_0^1(G)\times L^2(G))}+ |F(\cdot,\cdot,0,0,0)|_{L^2_{{\mathbb{F}}}(0,T;L^2(G))} 
    \\
    &  \quad \quad \quad \quad \quad 
    + |K(\cdot,\cdot,0)|_{L^2_{{\mathbb{F}}}(0,T;L^2(G))}\Big).
\end{align}

