body:
[Lemma Fejer of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $f:[0,1]\rightarrow \lbrack 0,1]$ be continuous, strictly
increasing, with a unique interior fixed point $p\in (0,1)$ and
single-crossing pattern 
\begin{equation}
f(x)>x\ \ (x<p),\qquad f(x)<x\ \ (x>p).  
\end{equation}
Then:

\begin{enumerate}
\item For every $x\in \lbrack 0,1]$ 
\begin{equation}
|f(x)-p|\leq |x-p|,  
\end{equation}

with strict inequality if $x\neq p$;

\item If $x,y$ lie on the same side of $p$ (both $\leq p$ or both $\geq p$),
then 
\begin{equation*}
|f(x)-f(y)|\leq |x-y|.
\end{equation*}
\end{enumerate}

