		\FdTmonsup(D_{K+1}) \le \FdTmonsup(D_{K}) + \int_0^L J_{\mathrm{pp}} \p{\sigma_{K+1}'(t), \module[D]{\dot{\sigma}_{K+1} }(t) } \mathrm{d} t.
