body:
[Theorem TB of arXiv:2510.12480, 'Cyclic and alternating $U$-statistics'] With notations and assumptions 
as in Section~(Sprel of the paper),
the following holds for the bi-alternating $U$-statistic{} $U^{--}_n(f)$ in (equation U-- of the paper).

\begin{romenumerate}
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
We have
\begin{align}
  \operatorname{\mathbb E}{} [U^{--}_n(f)] = -\floor{\tfrac{n}{2}} \mu
=O(n),
\end{align}
and, as \ensuremath{{n\to\infty}}, we have the weak law of large numbers 
\begin{align}
  \frac{1}{\binom n2} U^{--}_n(f)\overset{\mathrm{p}}{\longrightarrow} 0.
\end{align}

  \par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
We have
\begin{align}
  \operatorname{Var}[U^{--}_n(f)] 
=\tfrac{1}{2}n^2\operatorname{Var} [f_{12}(X_1,X_2)] + O(n).
\end{align}
Moreover, there exists a
finite or infinite sequence of real numbers $(\lambda_r)_1^{R}$ 
such that
\begin{align}
n^{-1}\left(U^{--}_n(f)-\operatorname{\mathbb E}{}[U^{--}_n(f)]\right) \overset{\mathrm{d}}{\longrightarrow} 
W:=\sum_{r=1}^R\tfrac12\lambda_r(\zeta_r^2-1)
\end{align}
where $(\zeta_r)_1^R$ are  independent standard normal variables.
The coefficients
$(\lambda_r)_1^R$ in (equation tb2 of the paper) are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint 
integral operator $T_{{\widehat{f_{12}}}}$ 
on $L^2({\mathcal X}\times\ensuremath{[0,1]},\nu\times\ell)$.
We have
\begin{align}
\operatorname{Var} W = \tfrac12  \sum_{r=1}^R\lambda_r^2&
=\tfrac12\operatorname{Var}[f_{12}(X_1,X_2)].
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TB2 of the paper) where
furthermore
$f$ is symmetric, 
the coefficients
$(\lambda_r)_1^R$ in (equation tb2 of the paper) are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint 
integral operator $T_{f_{12}}$ 
on $L^2({\mathcal X},\nu)$.

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TB2 of the paper) where
furthermore
$f$ is antisymmetric, 
then also
\begin{align}

  n^{-1}U^{--}_n(f) \overset{\mathrm{d}}{\longrightarrow} 
W:=\sum_{q=1}^{Q_+}\lambda^{\mathsf a}_q\eta_q,
\end{align}
where $(\eta_q)_1^{Q_+}$ are independent random variables with the stochastic area
distribution (equation area of the paper), and
the coefficients $(\lambda^{\mathsf a}_q)_1^{Q_+}$  are the positive numbers such that the
imaginary number $\mathrm{i}\lambda^{\mathsf a}_q$ is an eigenvalue of the 
anti-self-adjoint operator $T_{f_{12}}$ on $L^2_{\mathbb C}({\mathcal X},\nu)$.
We have
\begin{align}
  \operatorname{Var} W = \sum_{q=1}^{Q_+}(\lambda^{\mathsf a}_q)^2 = \tfrac12\operatorname{Var}[f_{12}(X_1,X_2)].
\end{align}
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If $f_{12}=0$, then
\begin{align}
  \operatorname{Var}[U^{--}_{2n}(f)]&=2n\sigma^2_{\mathsf e}+O(1),
\\  
  \operatorname{Var}[U^{--}_{2n+1}(f)]&=(2n+1)\sigma^2_{\mathsf o}+O(1),
\end{align}
where
\begin{align}
  \sigma^2_{\mathsf e}&:=\tfrac12\bigl(\operatorname{Var}[f_1(X)] + \operatorname{Var}[f_2(X)]\bigr),
\\
  \sigma^2_{\mathsf o}&:=\tfrac12\operatorname{Var}[{f_1(X)+f_2(X)}].
\end{align}
Furthermore,
\begin{align}
  (2n)^{-1/2}\bigpar{U^{--}_{2n}(f)-\operatorname{\mathbb E}{} [U^{--}_{2n}(f)]}&\overset{\mathrm{d}}{\longrightarrow} N(0,\sigma^2_{\mathsf e}),
\\  
(2n+1)^{-1/2}\bigpar{U^{--}_{2n+1}(f)-\operatorname{\mathbb E}{}[U^{--}_{2n+1}(f)]}&\overset{\mathrm{d}}{\longrightarrow} N(0,\sigma^2_{\mathsf o}).
\end{align}
\end{romenumerate}

