[Theorem eq:linear_seat of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\eta \in \Omega$. Then, for any $k \in {\mathbb{N}}$ and $i \in {\mathbb{Z}}$, we have
                    \begin{align}
                        \zeta_{k}\left(T\eta, i +  k + o_{k}\left(\eta\right) \right) = \zeta_{k}\left(\eta, i \right),
                    \end{align}
                where the offset $o_{k}\left(\eta\right)$ is given by 
                    \begin{align}
                        &o_{k}\left(\eta\right) \\
                        &:= s_{\infty}\left(\eta,0\right) - s_{\infty}\left( T\eta,0\right) + 2\sum_{y = s_{\infty}\left(0\right)+ 1}^{0} \sum_{\ell = 1}^{k}  \eta^{\downarrow}_{\ell}\left(y\right) - 2\sum_{y = Ts_{\infty}\left(0\right)+1}^{0}\sum_{\ell = 1}^{k}  T\eta^{\uparrow}_{\ell}\left(y\right).
                    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:key-area-estimate-p of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] Fix $g\geq 0$, $n \geq 0$, and set $h = H+1-n$. Assume $\beta$ is sufficiently large. Let $\delta_p$ be the minimum of the constant from (clm:pi(h|h)-lower-p of the paper) and $\frac16$. There exists $c>0$ such that the following holds for every $\log^2L \leq \ell_0 \leq L^{\frac12 - \frac{\delta_p}2}$, and subsets 
    $F \subseteq V\subset \mathbb Z^2$ where $F$ has $g$ holes and $|\partial F| \leq L^{3/2}$.
    Let $\Xi = \Xi_1+\Xi_2+\Xi_3$, where for $1 < p < 2$ we define 
    \begin{equation} \Xi_1 =  \frac{|\partial V|}Le^{c\beta(\log L)^{\frac{2p-2}p}}\,,\qquad \Xi_2 = \frac{|F|}
     {\ell_0 L} e^{c\beta(\log L)^{\frac{p-1}{p}}} \,,\qquad \Xi_3 =\frac{|\partial F|\ell_0 }LL^{-\delta_p+o(1)}\,,\end{equation}
     and for $p > 2$ we define
     \begin{equation} \Xi_1 =  \frac{|\partial V|}LL^{\varepsilon_\beta}\,,\qquad \Xi_2 = \frac{|F|}
     {\ell_0 L} e^{c\sqrt{\beta\log L}}\,,\qquad \Xi_3 =\frac{|\partial F|\ell_0 }Le^{-c(\beta)\sqrt{\log L}^{\frac{p}{p-1}}}\,.\end{equation}
    \begin{enumerate}[(i)]
    \item If $1 < p < 2$ and $|F|\leq \ell_0 L e^{-c\beta(\log L)^{\frac{p-1}{p}}}$, or $p > 2$ and $|F|\leq \ell_0 L e^{-c\sqrt{\beta\log L}}$, then
    \begin{align}{\widehat\pi}^{(p),0}_V(\phi_x \geq -h,\, \forall x \in F) = \exp\left(-\xi^{(p)}_{\ell_0,h}|F| +O(\Xi) + o(L^{-5}) \right)\,.
    \end{align}
\item Otherwise, if $\mathfrak{S}$ is the event that there are no disagreement polymers $\gamma$ with $|\gamma| \geq \log L$, then
\begin{align}
    {\widehat\pi}^{(p),0}_V(\phi_x \geq -h,\, \forall x \in F) &\geq \exp\left(-\xi^{(p)}_{\ell_0,h}|F| + O(\Xi)\right)\,,\\

 {\widehat\pi}^{(p),0}_V(\phi_x \geq -h,\, \forall x \in F\mid\mathfrak{S}) &\leq \exp\left(-\xi^{(p)}_{\ell_0,h}|F| + O(\Xi)+o(L^{-5})\right)\,.
\end{align}
If $|F| \leq  \big(\frac{3\beta}{{\widehat\pi}^{(p)}_\infty(\phi_o > h)}\big)^2 $, then the last upper bound also applies to ${\widehat\pi}^{(p),0}_V(\phi_x\geq -h,\,\forall x\in F)$.
\end{enumerate}
    The same holds under ${\widehat\pi}^{(p)}_\infty$, in which case the error term $\Xi_1$ can be omitted from $\Xi$. Separately, in the special case where $F = \llbracket1,\ell\rrbracket^2$ with $ \ell_0 + 10\lceil \log L\rceil \mid \ell$, the error term $\Xi_3$ can be omitted from $\Xi$.

[Definition 16 (The fluid variable array $\wavearray$ and the partial array $\wavearraypartial$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] We define the \emph{array of wave\footnote{These ``wave-variables'' solve wave equations; 
see Theorem\,\ref{T:GEOMETRICWAVETRANSPORTSYSTEM}.} variables} as follows:
\begin{subequations}
\begin{align}  
\wavearray 
& \eqdef (\Psi_0,\Psi_1,\Psi_2,\Psi_3,\Psi_4) 
\eqdef (\LogDensity,v^1,v^2,v^3,\Ent).
\end{align}We define the \emph{partial array of wave-variables} by:
\begin{align} 
	\wavearraypartial 
	& \eqdef (\Psi_1,\Psi_2,\Psi_3,\Psi_4)
	 = (\LRiemann,v^2,v^3,\Ent).
	\end{align}  
	\end{subequations}
We define the \emph{array of velocity variables} by:
	\begin{align} 
		\velocityarray \eqdef (v^1,v^2,v^3).
	\end{align}

We define the \emph{array of small velocity variables} by:
	\begin{align} 
		\velocityarraypartial \eqdef (v^2,v^3)
	\end{align}

