[Definition 20 (Control and Cost) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] \begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
    \item[]
    \item  \emph{Admissible Control Space.} Let $\mathcal{V}_\varepsilon$ denote the space of all $\F$-progressively measurable processes $\gamma: \Omega \times [0, T] \to \R$ taking values $\mathbb{P}$-a.s. in the closed interval $[0, 1/\varepsilon]$.

    \item  \emph{Penalized Cost Functional.} For any control process $\gamma \in \mathcal{V}_\varepsilon$, the associated penalized cost functional $J_\varepsilon: [0, T] \times H \times \mathcal{V}_\varepsilon \to \R$ is defined by:
    \begin{equation} 

        J_\varepsilon(t, x; \gamma) := \E \left[ \int_t^T e^{-\int_t^s \gamma_r \mathrm{d}r} \Big( f(s, X(s)) + \gamma_s \Phi(s, X(s)) \Big) \mathrm{d}s + e^{-\int_t^T \gamma_r \mathrm{d}r} \Psi(X(T)) \right],
    \end{equation}
    where $X(s) \equiv X(s; t, x)$ is the continuous mild solution \eqref{eq:mild_solution_eq} of the underlying semilinear state equation \eqref{eq:cauchy_problem}.
\end{enumerate}

