[Lemma degree_small of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] Let $T$ be a general term of the form (equation general_term2 of the paper), denote $\hat{k} := \max_{1 \leq p \leq \mathfrak{m}_0} k_p$, let $\mathcal{M} = N^{1/3 + \epsilon + \xi_6 \epsilon}/(N \tilde{\eta})$, for some constant $0 < \xi_6 \leq 1$. 
			In the case $n_1^{(\mathrm{intot})} < 4$ we have for sufficiently large $N$,  \begin{align}
			& \left\lvertT\right\rvert \leq g(t) N \mathcal{M}^{r_{\sum}} \Big(\prod_{l=1}^{\#_{\beta}} \frac{N^{100 \epsilon}}{\tau^{r_l - 1}} \Big) \Bigg( \Big(\frac{1}{N \tilde{\eta}}\Big)^{d} + \frac{1}{N^2 \tilde{\eta}}  \Bigg), \\
			& \left\lvertT\right\rvert \leq g(t) N^2 (1 - c_0)^{\hat{k}} \mathcal{M}^{r_{\sum}}  \Big(\prod_{l=1}^{\#_{\beta}} \frac{N^{100 \epsilon}}{\tau^{r_l - 1}} \Big) \Bigg(\Big(\frac{1}{N \tilde{\eta}}\Big)^{d} + \frac{1}{N^2 \tilde{\eta}} \Bigg). 
		\end{align}
		In the case $n_1^{(\mathrm{intot})} \geq 4$, we have for sufficiently large $N$,
		\begin{equation}
			\left\lvertT\right\rvert \leq g(t) \frac{1}{N} \mathcal{M}^{r_{\sum}} \Big(\prod_{l=1}^{\#_{\beta}} \frac{N^{100 \epsilon}}{\tau^{r_l - 1}} \Big).

		\end{equation}

