[Lemma local-w of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Suppose  $d\ge 3$ and    $q>1$ satisfies the condition (equation q of the paper).
Let $(u, \phi )\in W_0^{1, 2} (E_1; \mathbb{C}^d) \times L^2(E_1; \mathbb{C})$ be a weak solution of
\begin{equation}
\left\{
\aligned
-\Delta u +\nabla \phi  & =F +\text{\rm div} (f) & \quad & \text{ in } E_1,\\
\text{\rm div}(u) & = 0 & \quad & \text{ in } E_1,\\
u & =0 & \quad  & \text{ on } \partial E_1.
\endaligned
\right.
\end{equation}
 Then
\begin{equation}
\| \nabla u \|_{L^q(E_1)} + \| u \|_{L^q(E_1)}
\le C \left\{ \| F \|_{L^q(E_1)} + \| f\|_{L^q(E_1)} \right\}.
\end{equation}
Moreover,  for any  $0<\rho <1/2$, 
\begin{equation}
\aligned
\left(\fint_{E_\rho } |\nabla u|^q \right)^{1/q}
 & \le \frac{C}{\rho}
\left(\fint_{E_{2\rho} } |u|^q\right)^{1/q}
+ C \rho  \left(\fint_{E_{2\rho} } |F|^q\right)^{1/q}
+ C \left(\fint_{E_{2\rho} } |f|^q\right)^{1/q}.
\endaligned
\end{equation}
The constant  $C>0$ depends only on $d$, $q$ and $M$.

[Lemma 6 of arXiv:2609.01770, 'Support of Dyson Brownian Motion'] For all \(0\le t\le\sigma\), and all sufficiently large \(n\),
\begin{equation}
  \Lambda_n(t)\subset S_t^{[\eps]},\quad  \Lambda_n(t)
  \cap
  \mathcal F_t^{[\eta_*]}=\varnothing.

\end{equation}

[Lemma of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] The process $X^a$ is almost surely greater than or equal to zero at $a$, i.e.\ it holds
	\begin{equation*}
		\mathbb{P}_z[\mkern1.5mu \overline{\mkern-1.5mu X_t^a \mkern-1.5mu}\mkern1.5mu(a) \geq 0 \text{ for a.e. } t\in [0,\infty)] = 1 \quad \text{for all } z\inL.
	\end{equation*}
	Further, in the sense of random measures on $[0,\infty)$, it holds
	\begin{equation*}
		\mathds{1}_{ \{ z\in[C_0] \mid \bar{z}_a=0 \} }(X^a_s) \, dL_{s}^{\var{\sigma^{(a)}}} = dL_{s}^{\var{\sigma^{(a)}}} \quad \text{$P^a_z$-a.s.\ for $\mathcal{E}^a$-q.e.\ } z\inL. 
	\end{equation*}

[Lemma lem:Bounds_on_q of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) holds, and
  that~(equation ass:stable-alpha of the paper) holds with $\alpha \in (1,2)$. Let $q_{\alpha} (y; c)$ be as defined in~(equation eq:q_limit_integral of the paper). 
Then it holds that, for every  $c>0$ and all $0 \leq y < 1$,
  \begin{equation}

      q_\alpha (y ; c) \geq (\alpha -1 ) c^{1-\frac{\alpha}{2}} ( c+y)^{\frac{\alpha}{2} -1} ( 1-y),\end{equation}
      and, moreover, for every $c >0$,
 \begin{equation}

      \lim_{y \to 0} q_\alpha (y ; c)  = 1. \end{equation}
       On the other hand, for every $\delta>0$ it holds that
 \begin{equation}

 \sup_{\delta \leq y \leq 1} q_{\alpha} (y; c) < 1.
 \end{equation}

