body:
[Lemma prob-ball-intersects of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] Let $L\geq 1$. 
	Let $F$ be an induced event and let $R$ be chosen independently and uniformly at random from $[n]$. We have

\begin{align}
	\mathbb P(B_L(R)\cap \textrm{Supp}(F) \neq \emptyset \mid F)=O_L\left(\frac{|F|}{n}\right),
\end{align}
where the notation $O_L(\cdot)$ means that the constant hidden in big-O may depend on $L$.

[Lemma 15 of arXiv:2506.19064, 'Variational formula for the logarithmic potential of free additive convolutions'] \,
    \begin{enumerate}[label=\alph*)]
        \item  Let $\beta>0$ and $\mu = \musc[\b]$. It holds that $g_{\musc[\beta]}^* = \beta$ and $g_{\musc[\beta]}^{*\prime} = \infty$. Furthermore the domain of $G_{\musc[\beta]}^{[-1]}$ is $\mathbb{R} \setminus \{0\}$, and its unique critical points in the domain are $\pm g_{\musc[\beta]}^* = \pm \beta$, for which $G_{\musc[\beta]}^{[-1]\prime\prime}(\pm \beta) = \mp2\beta^{-3}$. In particular $g = \beta$ is a local maximum of $G_{\musc[\beta]}^{[-1]}$.

        \item Let $\rho$ be a probability s.t. $z_\rho^* := \supp_- \rho \ne -\infty$, and assume that there exist constants $c_1,c_2>0$ s.t.
        \begin{equation}
            c_1^{-1}\varepsilon^{3/2}
            \le
            \rho(z_\rho^*,z_\rho^*+\varepsilon)
            \le
            c_1\varepsilon^{3/2}
            \text{ for }
            \varepsilon\in(0,c_2).
        \end{equation}
         Then (i) $g_\rho^*<\infty=g_\rho^{*\prime}$ and (ii) $G_\rho^{[-1]\prime\prime}(g_\rho^*)<0=G_\rho^{[-1]\prime}(g_\rho^*)$. In particular $g_\rho^*$ is a local maximum of $G_\rho^{[-1]}$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l.recursive-upper-bound of arXiv:2505.15283, 'Quantization of Probability Distributions via Divide-and-Conquer: Convergence and Error Pr'] Let $f(\mu) = \bar{\mu}$, then for any $n\geq 1$ ,
    \begin{equation}    
        \begin{split}            
        &\sum_{\alpha \in \{\pm\}^n } 
            \mu(\Omega_\alpha)  
            \sqrt{
                \left( 
                    \bar{\mu}_{\alpha+} - \bar{\mu}_\alpha 
                \right)
                \left( 
                    \bar{\mu}_\alpha - \bar{\mu}_{\alpha-} 
                \right)
            }\\
        &\leq
        \frac{1}{2}
        \sum_{\alpha \in \{\pm\}^{n-1} } 
