[Definition of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] We say $Y$ is an {\rm $\mathbb{H}^{\#}$-semimartingale} if it is $(\mathscr{F}_t)$-adapted and indexed by $\mathbb{H}\times [0,\infty)$ such that the following hold
 	\begin{enumerate} 
 \item[$\bullet$] For each $h\in \mathbb{H}$, the process $Y(h):=\{ Y(h,t):t\geq 0 \}$ is a c\`adl\`ag $\mathbb{R}$-valued $(\mathscr{F}_t)$-semimartingale starting from $0$;

 \item[$\bullet$] For each $m\in\mathbb{Z}_+$, $h_1,\dots,h_m\in \mathbb{H}$, and $a_1,\dots,a_m\in\mathbb{R}$, the following finite additivity holds
 		\begin{eqnarray*}
 		Y\bigg(\sum_{k=1}^m a_k h_k,t\bigg)\overset{\rm a.s.}= \sum_{k=1}^m a_k Y\big(h_k,t \big),
 		\quad t\geq 0.
 		\end{eqnarray*}

 	\end{enumerate}

[Lemma 20 (Character orthogonality) of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] \begin{align*}
        \int_{\mathbb{Z}_p^n}
        \chi_p(p^k\boldsymbol{x}\cdot\boldsymbol{\xi})d\boldsymbol{x}
        =\begin{cases}
            1,&k\geq-v_p(\boldsymbol{\xi});\\
            0,&k<-v_p(\boldsymbol{\xi}).
        \end{cases}
    \end{align*}
    and
    \begin{align*}
        \int_{\mathbb{Z}_p^n\setminus p\mathbb{Z}_p^n}
        \chi_p(p^k\boldsymbol{x}\cdot\boldsymbol{\xi})d\boldsymbol{x}
        =\begin{cases}
            1-p^{-n},&k\geq-v_p(\boldsymbol{\xi});\\
            -p^{-n},&k=-v_p(\boldsymbol{\xi})-1;\\
             0,&k\leq-v_p(\boldsymbol{\xi})-2.
        \end{cases}
    \end{align*}

