body:
[Lemma 24 of arXiv:2604.21669, 'Discontinuous transition in 2D Potts:\\ II. order-order interface convergence'] 1) There exist \(C,c\in (0,+\infty)\) such that for any \(n\geq 1\), \(i,i',j,j'\in \Z\),
	\begin{equation*}
		q_{i,i'}(n,j,j')
		\leq
		\tfrac{C}{n}e^{-c\frac{(i-j)^2 +(i'-j')^2}{n}}.
	\end{equation*}
	2) Let \(K\geq 1\). There exists \(c\in (0,+\infty)\) such that for any \(n\geq 1\), \(i,i',j,j'\in \Z\), with \(|i-j|\leq K\sqrt{n}\), and \(|i'-j'|\leq K\sqrt{n}\),
	\begin{equation*}
		q_{i,i'}(n,j,j')
		\geq
		\tfrac{1}{cn}.
	\end{equation*}
	Both statements also hold for \(\overleftarrow{q}\).

[Theorem 7 of arXiv:2605.25715, '2605.25715'] Consider two $2\times 2$ matrices $G, A$ of real numbers, where $A$ is symmetric and positive definite, i.e.
\[
G=\begin{pmatrix}a&b\\ c&d\end{pmatrix},\qquad
A=\begin{pmatrix}\alpha&\beta\\ \beta&\gamma\end{pmatrix}
\quad(\alpha>0,\ \delta:=\det(A)=\alpha\gamma-\beta^{2}>0).
\]
Then, there exists a symmetric matrix $S=\begin{pmatrix}s_{11}& s_{12}\\ s_{12}& s_{22}\end{pmatrix}$ solving \eqref{SOHHDlinalg1}, and which is of the following form:
\begin{itemize}
\item[(i)]
If $\mathrm{trace}(G)=a+d=0$, we can choose $S=0$ as symmetric solution.
\item[(ii)] If $\mathrm{trace}(G)=a+d \neq 0$ and $G$ singular, i.e. $\det(G)=ad-bc=0$, we can choose
\begin{eqnarray*}
S&=&\frac{a+d}{\alpha a^2+2\beta ab + \gamma b^2}\begin{pmatrix}a^2& ab\\ ab& b^2\end{pmatrix}, \qquad \text{if }\ b\not =0,\\[3pt]
S&=&\frac{a+d}{\alpha c^2+2\beta cd + \gamma d^2}\begin{pmatrix}c^2& cd\\ cd& d^2\end{pmatrix}, \qquad \text{if }\ b=0,\ c\not=0,
\end{eqnarray*}
and in case $b=c=0$, we may choose 
\begin{eqnarray*}
S\ =\ \begin{pmatrix}\frac{a}{\alpha}& 0\\ 0& 0\end{pmatrix}, \qquad \text{if }\ a\not =0,\qquad
S\ =\ \begin{pmatrix}0& 0\\ 0& \frac{d}{\gamma}\end{pmatrix}, \qquad \text{if }\ d\not=0.
\end{eqnarray*}
\item[(iii)] If $\mathrm{trace}(G)=a+d \neq 0$  and $G$ non-singular, i.e. $\det(G)=ad-bc\not=0$, we can choose
\begin{eqnarray*}
S\ =\ \kappa\begin{pmatrix}\gamma a(a+d) + \alpha c^2 - \gamma bc - 2\beta ac& \alpha cd + \gamma ab - 2\beta ad\\ \alpha cd + \gamma ab - 2\beta ad& \alpha d(a+d) + \gamma b^2 - \alpha bc - 2\beta bd\end{pmatrix}, 
\end{eqnarray*}
where
\[
\kappa=\frac{a+d}{ (\alpha \gamma-\beta^2) (a+d)^2 +\big( \gamma b - \alpha c + \beta(a-d)\big)^2}.
\]
\end{itemize}

