[Theorem 13 of arXiv:2606.28793, 'Randomized second order Riesz projections on the Hamming cube'] Fix $1<p<\infty$, $a\geq0$, and $C<\infty$.  Let $X$ be a Banach space.  Assume that, for every $M,n,d\geq1$ and every
$F\in\mathcal P_d(\Omega_n;\ell_2^M(X))$,
\begin{equation}

 \|G^{\mathrm{ord}}_{1,\ell_2^M(X)}F\|_{L^p(\Omega_n)}
 \leq Cd^a\|F\|_{L^p(\Omega_n;\ell_2^M(X))}.
\end{equation}
Then, for every integer $k\geq1$, every $n,d\geq1$, and every $f\in\mathcal P_d(\Omega_n;X)$,
\[
 \|G^{\mathrm{ord}}_{k,X}f\|_{L^p(\Omega_n)}
 \leq C^k d^{ka}\|f\|_{L^p(\Omega_n;X)}.
\]
Consequently,
\[
 \|G^{\mathrm{dis}}_{k,X}f\|_{L^p(\Omega_n)}
 \leq C^k d^{ka}\|f\|_{L^p(\Omega_n;X)}.
\]

[Lemma K_t_scaling of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] For $t>0$, $x\neq 0$, $k>0$, $A\subset\mathbb{R}$,
\begin{enumerate}
\item[(a)] $K_{t,n}(kx,kA) = K_{tk^{-\alpha},n}(x,A)$, $n=0,1,2,\ldots$,
\item[(b)] $K_t(kx,kA) = K_{tk^{-\alpha}}(x,A)$.
\end{enumerate}

[Lemma sqrt_l_h_convergence of arXiv:2608.12056, 'Deviation inequalities for U-processes of growing order, with applications to half-space d'] Let $C_F$ be a constant that depends only on the distribution $F$. Recall that $K_{q,m} = \sup_{z \in [-2q,2q]}\left\lvert \phi_{m-1}(z) - \frac{1}{\sqrt{2\pi}}\exp{-\frac{z^2}{2}}\right\rvert$. Under the assumptions of Theorem (thm:normality of the paper), 
    \begin{align}

        \left\lvert \mathrm{var}\left(\sqrt{m} h^{(1)}_{u}\left(X_1;z\right)\right) - \frac{1}{2\pi}\exp{-\left\lvert \dotp{z}{u} \right\rvert^2} \right\rvert \leq C_F\left(K^2_{q,N} +\frac{1}{m} + \frac{q^2}{m}\right)\,.
    \end{align}
    Moreover, for any vector $t \in \mathbb R^M$ and $(u_1, z_1), \ldots, (u_M, z_M) \in \bar{\mathcal{S}}$,
    \begin{multline}
    \mathbb E \left\lvert  \left(\sqrt{m} H(X_1; (u_i, z_i), i \in [M])\right)^2 - K(X_1; (u_i, z_i), i \in [M]) \right\rvert \\
    \leq C_F\sum_{i, j \in [M]} t_i t_j \left(K_{q,m}^2 + \frac{1}{m} + \frac{q^2}{m^2}\right)\,.
\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 of arXiv:2608.23301, 'On a Telegraph Process with Generalized Mittag-Leffler Waiting times and Velocity Driven b'] Conditional on the initial velocity $v_1$, the expected velocity associated with $\{\mathbb{X}_{\alpha}(t)\}_{t\geq0}$  is
	 	\begin{equation*}
	 		\mathbb{E}(\mathbb{V}_{\alpha}(t)|\mathbb{V}_{\alpha}(0)=v_1)= v_1 \bar{F}_{R_1}(t)+ \frac{v_1 (b+c)}{b+r+c}\sum_{n=1}^{\infty}\psi_n(t|v_1)- \frac{v_2 r}{b+r+c}\sum_{n=1}^{\infty}\xi_n(t|v_1),
	 	\end{equation*}
	 	where
	 	{\small\begin{equation*}
	 		\psi_n (t|v_1)=\sum_{k=0}^{n-1}\mathrm{Pr}\{M_{n-1}=k|S_0 =v_1\}(\lambda t^\alpha)^{\frac{b}{c}+k+1}(\mu t^\alpha)^{\frac{r}{c}+n-k-1} E_{(\alpha,\alpha),\alpha\big(\frac{b+r}{c}+n\big)+1}^{(\frac{b}{c}+k+2,\frac{r}{c}+n-k-1)}(-\lambda t^\alpha,-\mu t^\alpha)
	 	\end{equation*}}
	 	and
	 	{\small\begin{equation*}
	 			\xi_n (t|v_1)=\sum_{k=0}^{n-1}\mathrm{Pr}\{M_{n-1}=k|S_0 =v_1\}(\lambda t^\alpha)^{\frac{b}{c}+k+1}(\mu t^\alpha)^{\frac{r}{c}+n-k-1} E_{(\alpha,\alpha),\alpha\big(\frac{b+r}{c}+n\big)+1}^{(\frac{r}{c}+n-k,\frac{b}{c}+k+1)}(-\mu t^\alpha,-\lambda t^\alpha).
	 	\end{equation*}}
	 	\begin{proof}
	 		By using \eqref{ccdfLn} and Proposition \ref{PropX+YDist}, we have
	 		\begin{align}
	 			\int_{0}^{t}F_{L}^{(n-k-1)}&(t-s)f_{R^{(k+1)}+R_{n+1}}(s)\mathrm{d}s\nonumber \\
	 			&=\mu^{\frac{r}{c}+n-k-1}\lambda^{\frac{b}{c}+k+2}\int_{0}^{t}(t-s)^{\alpha\big(\frac{r}{c}+n-k-1\big)}E_{\alpha,\alpha\big(\frac{r}{c}+n-k-1\big)+1}^{\frac{r}{c}+n-k-1}(-\mu(t-s)^\alpha)\nonumber\\
	 			&\hspace{6cm} \cdot y^{\alpha\big(\frac{b}{c}+k+2\big)-1}E_{\alpha,\alpha\big(\frac{b}{c}+k+2\big)}^{\frac{b}{c}+k+2}(-\lambda s^\alpha)\mathrm{d}s \\
	 			&=(\lambda t^\alpha)^{\frac{b}{c}+k+2}(\mu t^\alpha)^{\frac{r}{c}+n-k-1} E_{(\alpha,\alpha),\alpha\big(\frac{b+r}{c}+n+1\big)+1}^{(\frac{b}{c}+k+2,\frac{r}{c}+n-k-1)}(-\lambda t^\alpha,-\mu t^\alpha).
	 	   \end{align}
	 		By using \eqref{cIntTnS0} and \eqref{cIntLRn1} in Remark 2 of Crimaldi {\it et al.} (2013), we get
	 	{	\small\begin{align*}
	 			\psi_n(t|v_1)
	 			&=\sum_{k=0}^{n-1}\mathrm{Pr}\{M_{n-1}=k|S_0 =v_1\} \int_{0}^{t}F_{L}^{(n-k-1)}(t-s)\big(f_{R}^{(k+1)}(s)-f_{R^{(k+1)}+R_{n+1}}(s)\big)\mathrm{d}s\\
	 			&=\sum_{k=0}^{n-1}\mathrm{Pr}\{M_{n-1}=k|S_0 =v_1\}(\lambda t^\alpha)^{\frac{b}{c}+k+1}(\mu t^\alpha)^{\frac{r}{c}+n-k-1}\nonumber\\
	 			&\hspace{1cm} \cdot  \Big(E_{(\alpha,\alpha),\alpha\big(\frac{b+r}{c}+n\big)+1}^{(\frac{b}{c}+k+1,\frac{r}{c}+n-k-1)}(-\lambda t^\alpha,-\mu t^\alpha)-\lambda t^{\alpha}E_{(\alpha,\alpha),\alpha\big(\frac{b+r}{c}+n+1\big)+1}^{(\frac{b}{c}+k+2,\frac{r}{c}+n-k-1)}(-\lambda t^\alpha,-\mu t^\alpha)\Big)\nonumber\\
	 			&=\sum_{k=0}^{n-1}\mathrm{Pr}\{M_{n-1}=k|S_0 =v_1\}(\lambda t^\alpha)^{\frac{b}{c}+k+1}(\mu t^\alpha)^{\frac{r}{c}+n-k-1} E_{(\alpha,\alpha),\alpha\big(\frac{b+r}{c}+n\big)+1}^{(\frac{b}{c}+k+2,\frac{r}{c}+n-k-1)}(-\lambda t^\alpha,-\mu t^\alpha),
	 		\end{align*}}
	 		where we have used the following relation in the last step:
	 		\begin{equation*}
	 			E_{(a,a),a(b+c)+1}^{(b,c)}(-xz^a,-yz^a)-xz^a E_{(a,a),a(b+c+1)+1}^{(b+1,c)}(-xz^a,-yz^a)=E_{(a,a),a(b+c)+1}^{(b+1,c)}(-xz^a,-yz^a).
	 		\end{equation*}
	 		Similarly, we can obtain $\xi_n(t|v_1)$. This proves the result.
	 	\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LM32 of arXiv:2412.08886, 'On domination for (non-symmetric) Dirichlet forms'] Let $X$ be a Borel right process properly associated with the quasi-regular Dirichlet form $({\mathscr E},{\mathscr F})$ on $L^2(E,m)$.  Then the following statements hold:
\begin{itemize} 
\item[(1)] A set $N\subset E$ is ${\mathscr E}$-polar,  if and only if it is $m$-polar. 
\item[(2)] An increasing sequence of closed subsets $\{F_n:n\geq 1\}$ of $E$ is an ${\mathscr E}$-nest if and only if 
\begin{equation}
		\mathbb{P}_x\left(\lim_{n\rightarrow \infty}T_{E\setminus F_n}<\zeta\right)=0
\end{equation}
for q.e.  $x\in E$ (equivalently,  for $m$-a.e.  $x\in E$).
\item[(3)] If $f$ is ${\mathscr E}$-quasi-continuous,  then $f$ is finely continuous q.e.  Conversely,  if $f\in {\mathscr F}$ is finely continuous q.e., then $f$ is ${\mathscr E}$-quasi-continuous. 
\item[(4)] A set $G\subset E$ is ${\mathscr E}$-quasi-open if and only if it is q.e. finely open.
\end{itemize}

[Lemma 18 of arXiv:2609.03195, 'Lecture hall polytopes and\\Lakshmibai-Seshadri paths'] Let M = $x_{\pi_1}\cdots x_{\pi_k}$ be a monomial in $\mcA(b)$ with $x_{\pi_1} \preceq \cdots \preceq x_{\pi_k}$. The followings are equivalent:
\begin{itemize}
    \item[(i)] $M$ is standard,
    \item[(ii)] $M$ is in standard form, 
    \item[(iii)] $x_{\pi_j}x_{\pi_{j+1}}$ is standard for all $j=1,\ldots,k-1$.
\end{itemize}

[Proposition prop:manifolds of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Assume that $\nu$ satisfies (eq:TI of the paper). We distinguish two cases.
    \begin{enumerate}[label=(\roman*)] 
        \item When considering the regular cost $c(x,y)=1-\langle x,y\rangle$, Sinkhorn's algorithm converges exponentially fast and for 
     $\varepsilon\leq\tau+\sqrt{\tau+\tau^2} $ the exponential convergence rate equals 
     \begin{equation*}
     1-\frac{\varepsilon^2}{\varepsilon^2+2\tau\varepsilon+\tau}\,.
     \end{equation*}
        \item When the cost considered is $c_\delta(x,y)$, Sinkhorn's algorithm converges exponentially fast and for $\varepsilon$ small enough (as in (equation eps:small:sfera:delta of the paper)) the rate of convergence is 
\begin{equation*}
1-\frac{\varepsilon^2}{\varepsilon^2+2\tau\varepsilon\left(\delta^2+\frac{2\pi}{\sqrt{1-\delta^2}}\right)+\frac{4\pi^2\tau}{1-\delta^2}}\,.
\end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] [CLT for increasing intensity] 
Let $a=(a_0,\dots,a_\alpha) \in \R^{\alpha+1}$ with $a_\alpha\neq 0$ and assume $\z {\alpha+1} {\alpha+1} {\alpha+1}(W)>0$.
Then
\begin{align*}
\frac{\chi_a(\Delta_W)-\E{ \chi_a(\Delta_W) }}{\sqrt{\V{ \chi_a(\Delta_W) }}} \;\xrightarrow{d}\; \mathcal{N}(0,1) \qquad \text{for } \beta \rightarrow \infty.
\end{align*}
Specifically, the quantities from Theorem \ref{Th:myRCM} applied to $\tilde{\chi}_a(\Delta_W)$ satisfy
\begin{align*}
\gamma_1,\gamma_3,\gamma_4,\gamma_5 = \mathcal{O}\left(\beta^{-\frac{1}{2}}\right), \qquad \gamma_2 = \mathcal{O}\left(\beta^{-\frac{3}{2}}\right), \qquad \gamma_6 = \mathcal{O}\left(\beta^{-1}\right).
\end{align*}

