[Definition defn:mild-soln of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Given an initial condition $(u_0,\eta_0)\in \mathcal{H}^0_\mu$, a process $U(\cdot)=\big(u(\cdot),\eta(\cdot)\big)$ is called a weak solution of (equation eqn:react-diff:mu of the paper) if $u(\cdotp)$ is $\mathcal{F}_t$-adapted and there exists $q\geq1$ such that $\mathbb{P}$--a.s. one has
\begin{align*}
u\in C_{w}([0,\infty);H)\cap L^2_{\emph{loc}}([0,\infty);H^1), \qquad \eta\in C({[0,\infty)};M^0_\mu),\qquad \varphi(u)\in L^q_{\emph{loc}}([0,\infty);L^q(\mathcal{O})),
\end{align*}
that is, $u(\cdotp)$ is weakly continuous in $H$ with respect to $t$, and moreover, for $\mathbb{P}$--a.s.  
\begin{align*}
\langle u(t),v\rangle_H&=\langle u_0,v\rangle_H  -\kappa\int_0^t\langle u(r),v\rangle_{H^1} \emph{d} r-(1-\kappa)\int_0^t\langle \eta(r),v\rangle_{M^0_\mu}+\int_0^t\langle \varphi(u(r)),v\rangle_H \emph{d} r\\
&\quad+\int_0^t\langle v(r),Q\emph{d} w(r)\rangle_H,\\ 
\langle \eta(t),\tilde{\eta}\rangle_{M^0_\mu}&=\langle\eta_0,\tilde{\eta}\rangle_{M^0_\mu}+  \int_0^t\langle \mathcal{T}_\mu\eta(r),\tilde{\eta}\rangle_{M^0_\mu} \emph{d}r+\int_0^t\langle u(r),\tilde{\eta}\rangle_{M^0_\mu}\emph{d} r,
\end{align*} 
{holds for all $v\in H^1\cap L^{q'}(\mathcal{O})$, where $q'\geq1$ is the H\"older conjugate of $q$, and for all $\tilde{\eta}\in M^0_\mu$.}

[Theorem 10 of arXiv:2506.16260, 'Fractional Compound Poisson Random Fields on Plane'] Let $\{T_{2\alpha_i}(t),\ t\ge0\}$, $0<\alpha_i\leq1$, $i=1,2$ 
	be two random processes whose corresponding densities are folded solutions of the following Cauchy problems:
	\begin{equation}
		\frac{\partial^{2\alpha_i}}{\partial t^{2\alpha_i}}u_{2\alpha_i}(x,t)=\frac{\partial^2}{\partial x^2}u_{2\alpha_i}(x,t),\ t>0,\,x\in\mathbb{R},
	\end{equation}	
	with initial condition $u_{2\alpha_i}(x,0)=\delta(x),\ 0<\alpha_i\leq1$, and $(\partial/\partial t)u_{2\alpha_i}(x,t)|_{t=0}=0,\ \frac{1}{2}<\alpha_i\leq1$.	
	Also, let $\{H_\beta(t_1,t_2),\ (t_1,t_2)\in\mathbb{R}^2_+\}$ be a two parameter stable subordinator. Then, the STFPRF satisfies the following time-change relationships: 
	\begin{equation}
		N_{\alpha_1,\alpha_2}^\beta(t_1,t_2)\overset{d}{=}N_\beta(T_{2\alpha_1}(t_1),T_{2\alpha_2}(t_2))\overset{d}{=}N(H_\beta(T_{2\alpha_1}(t_1),T_{2\alpha_2}(t_2))),\ (t_1,t_2)\in\mathbb{R}^2_+,
	\end{equation}
	where $\{N(t),\ t\ge0\}$ and $\{N_\beta(t_1,t_2),\ (t_1,t_2)\in\mathbb{R}^2_+\}$ are the Poisson process and the SFPRF, respectively. In (\ref{sfprfrep}), the component processes involved are independent of each other.

