[Corollary 104 of arXiv:2601.16377, '2601.16377'] In the setting of Lemma~\ref{Lemma_continuity_varyinf_ff}, there exists $\varepsilon > 0$ depending only on the constants in the assumptions with the following property. If $\boldsymbol{\mu}^{\textnormal{I}}$ satisfies the off-criticality Assumption~\ref{Assumptions_offcrit} and for any $g,h \in [H]$ and $e \in [\mathfrak{e}]$
\begin{equation}

\begin{split}
\max\big(|\hat a_h^{\prime\,\textnormal{I}}-\hat a_h^{\prime\,\textnormal{II}}|\,,\,|\hat b_h^{\prime\,\textnormal{I}}-\hat b_h^{\prime\,\textnormal{II}}|\,,\,|\theta_{g,h}^{\textnormal{I}} - \theta_{g,h}^{\textnormal{II}}|\,,\,|r_e^{\textnormal{I}}-r_e^\textnormal{II}|\big) & \leq \eps, \\
 \int_{\max (\hat a_h^{\prime\,\textnormal{I}},\hat a_h^{\prime\,\textnormal{II}})}^{\min(\hat b_h^{\prime\,\textnormal{I}},\hat b_h^{\prime\,\textnormal{II}})} \big|V_h^{\textnormal{I}}(x)-V_h^\textnormal{II}(x)\big| \dd x & \leq \eps, \\
\sup_{z\in \amsmathbb{M}_h} \big|\phi^{\pm,\textnormal{I}}_h(z)-\phi^{\pm,\textnormal{II}}_h(z)\big| & \leq \eps,
\end{split}
\end{equation}
then $\boldsymbol{\mu}^{\textnormal{II}}$ also satisfies the off-criticality Assumption~\ref{Assumptions_offcrit}.

[Corollary 15 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $\mathbf q$ be a Bohnenblust--Hille exponent with $\sigma(\mathbf q)>0$ and with at most two coordinates different from $2$. Then
\begin{equation}
 C_{\mathbf q}^{(m)}
 =2^{\frac{\sigma(\mathbf q)}{2}\left(1+(m-2)Y_1(\mathbf q)\right)}.
\end{equation}

[Corollary of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] For $n=1$, we have
\begin{equation*}
	\mathrm{Pr}\{T_1\in\mathrm{d}s\}=\sum_{j_0=1}^{k_0}\mu_{j_0}\mathrm{d}s\sum_{r=0}^{\infty}j_0\lambda_1e^{-j_0\lambda_1}e^{-r\lambda}\sum_{\Omega(k_0,r)}\prod_{j_0=1}^{k_0}\frac{(s\mu_{j_0})^{n_{j_0}}}{n_{j_0}!}e^{-s\mu_{j_0}}.
\end{equation*}
Thus, 
\begin{equation*}
	\mathrm{Pr}\{T_1<\infty\}=\sum_{j_0=1}^{k_0}\frac{\mu_{j_0}}{\mu}j_0\lambda_1e^{-j_0\lambda_1}\sum_{r=0}^{\infty}e^{-r\lambda}\sum_{\Omega(k_0,r)}z_{k_0}!\prod_{j_0=1}^{k_0}\Big(\frac{\mu_{j_0}}{\mu}\Big)^{n_{j_0}}\frac{1}{n_{j_0}!}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm haploidschweinsbergmodel of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] Suppose a population evolves according to Def~(hschwpop of the paper)
and Def~(def:haplrandomalpha of the paper)   with the law on the number of
potential offspring  as in (equation eq:4 of the paper). 
Take    $(\varepsilon_{N})_{N\in \ensuremath{\mathds N}}$ from  Def~(def:haplrandomalpha of the paper)
as in (equation eq:58 of the paper) in Lemma~(lm:scalingcNhaplSchweinsberg of the paper).   Then    $\{ \pi_{n,N}( \lfloor t/c_{N}\rfloor); t \ge 0 \}$ converges in the
sense of weak convergence in the Skorokhod topology to $\{\pi_n\}
\equiv  \{\pi_{n}(t); t \ge 0\}$ where $\{\pi_{n}\}$ is  as specified in each case.
\begin{enumerate}
\item   Suppose $1\le \alpha <2$. Then  $\{\pi_n\}$ is the Kingman-Beta$(\gamma, 2-\alpha,\alpha)$-coalescent as defined
in Def~(def:KingmanBeta of the paper) with    $\gamma=1$ and transition rates, for a given group of  $k \in \{2,3, \ldots, n\}$ blocks, 
\begin{displaymath}
\lambda_{n,k} = C^{-1}C_{\kappa} \ensuremath{\mathds{1}_{\left\{ k=2 \right\}}}  + C^{-1}  \alpha c m^{-\alpha} B(k-\alpha,n-k+\alpha)
\end{displaymath} 
where $C = C_{\kappa} +  c\alpha m^{-\alpha}B(2-\alpha,\alpha)$ and  $C_{\kappa} = \kappa\ensuremath{\mathds{1}_{\left\{ \kappa = 2 \right\}}} +  \ensuremath{\mathds{1}_{\left\{ \kappa > 2 \right\}}} $ and $m =  \ensuremath{\mathds{1}_{\left\{ \alpha = 1 \right\}}} +  \ensuremath{\mathds{1}_{\left\{ 1 < \alpha < 2 \right\}}}m_{\kappa}$  and $m_{\kappa} = \EE{X | E^{\sf c}}$   and    $B(a,b) = \Gamma(a)\Gamma(b)/\Gamma(a+b)$ is the beta function.  The transition rate when $\alpha = 1$ is then
\begin{displaymath}
\lambda_{n,k}  =  \ensuremath{\mathds{1}_{\left\{ k=2 \right\}}}C^{-1} C_{\kappa}  +  C^{-1} cB(k-1, n-k + 1)
\end{displaymath}
where $C =  C_{\kappa} +  c$.  
\item  Suppose $0 < \alpha < 1$.  Then 
$\{\pi_n\}$ is the Kingman-Poisson-Dirichlet$(\alpha,0)$-coalescent as
defined in Def~(def:kingman-poisson-dirichlet of the paper) with  $c = 1/(1+c)$ and $c^{\prime} = c/(1 + c)$.  
\end{enumerate}
In both cases, recalling   Def~(def:cNhapl of the paper), 

\begin{equation}

 \frac{1}{c_{N}} \overset{c}{\sim}
 \begin{cases}
  N & \text{when $\ensuremath{{\kappa}} > 2$} \\
  N / \log N  & \text{when  $\ensuremath{{\kappa}} = 2$} \\
\end{cases}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition k alpha epsilon, covariance estimate of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Fix $\alpha\in(0,1/2]$. Moreover, there exists $C_K>0$ such that, for all $\varepsilon\in(0,1)$ and all $z_1,z_2\in[0,1]^d$,
	\begin{equation}
		\int_0^{(t_{z_1,z_2}-C_K)_+}
		\sigma_\alpha(s)^2\,\text{d} s
		\leq
		k_\alpha^\varepsilon(z_1,z_2)
		\leq
		\int_0^{t_{z_1,z_2}+C_K}
		\sigma_\alpha(s)^2\,\text{d} s,
	\end{equation}
	where $\sigma_\alpha(s):=\sqrt{2}\,(1+2s)^{-\alpha}$ and
	$t_{z_1,z_2}:=\log\bigl(1/(\varepsilon\vee\lVert z_1-z_2\rVert_\infty)\bigr)$.

