body:
[Lemma 13 (Overlap criterion) of arXiv:2608.29501, 'Disorder Thresholds and Free Energy of Brownian Directed Polymers with\\ Product and Radia'] For every \(\beta>0\), consider the following three statements:
\begin{enumerate}[ leftmargin=0pt, labelsep=5pt, align=left]
  \item \(W_\infty(\beta)>0\) \quad \text{almost surely};
  \item \(\displaystyle \int_0^\infty I_s\,\dd s<\infty \quad\text{almost surely}\);
  \item \(\displaystyle W_t(\beta)\longrightarrow W_\infty(\beta) \quad\text{in }L^1(\Pp)\).
\end{enumerate}
Then \textup{(1)} and \textup{(2)} are equivalent, and both are implied by
\textup{(3)}. This is Proposition~2.8 of Rovira and
Tindel~\cite{RoviraTindel2005}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 of arXiv:2605.30869, 'Approximate Transitivity of Young Translation on Rough Paths'] Let \( \mathbf{X} \in \mathcal{C}^{p\text{-var}}_{\mathbf{1}}\). Then for any \( r>0 \),
\begin{equation}
C(\delta_r \mathbf{X}) = r\, C(\mathbf{X})\,.
\end{equation}
Moreover, there exists a constant \( M>0 \) such that for all \( \mathbf{X} \in \mathcal{C}^{p\text{-var}} \),
\begin{equation}
C(\mathbf{X}) \le M \|\mathbf{X}\|_{p\text{-var}}\,.
\end{equation}
In case $\mathbf{X} \in \mathcal{C}^{\alpha}_{\mathbf{1}}$ the same result holds with $C_{\alpha}(\mathbf{X})$.

[Theorem thm_limit_curves of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Assume (equation p_cont of the paper) and (equation p_lower of the paper).
Then for every $\varepsilon>0$, there exists $\delta=\delta(\varepsilon,\mathfrak{p})>0$ such that
\eeq{ 
\limsup_{n\to\infty}\frac{1}{n^{1/3}}\log\mathbb{P}\big(\mathscr{L}_n^\mathsf{far}(\varepsilon)\geqslant\mathscr{L}_n-\delta n^{1/3}\big) < 0. 
}
In particular, the following statement holds with probability one.
For any choice of convex chain $\mathcal{C}_n\subseteq\mathcal{S}_n$ such that $\#\mathcal{C}_n \geqslant \mathscr{L}_n-\delta n^{1/3}$, we have
\eeq{ 
\limsup_{n\to\infty}\inf_{f\in\argmax J}\max_{(x,y)\in\mathcal{C}_n}|f(x)-y| \leqslant \varepsilon.
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: finer asym of cnnk and cnnkef of arXiv:2603.10738, 'Pairwise Negative Correlation for Uniform Spanning\\ Subgraphs of the Complete Graph'] For any fixed $k\;\geqslant\;6$, we have 
	\begin{equation}
		\begin{aligned}
		C_{n,n+k}
		&=\sqrt{2\pi}\,n^{\,n+\frac{3k-1}{2}}
		\Bigg\{
		\chi_k\frac{2^{-\frac{3k}{2}}}{\Gamma(\frac{3k}{2})}
		+\frac{2^{-\frac{3k-1}{2}}}{\Gamma(\frac{3k-1}{2})}\bigl(k\chi_k+\tilde{\chi}_k\bigr)\,n^{-\frac12}
		\\
		&\quad+\Bigg[
		\frac{2^{-\frac{3k-2}{2}}}{\Gamma(\frac{3k-2}{2})}
		\left(\frac{k(6k+1)}{12}\chi_k+\frac{3k-1}{3}\tilde{\chi}_k+\hat{\chi}_k\right)
		+\frac{1}{12}\chi_k\frac{2^{-\frac{3k}{2}}}{\Gamma(\frac{3k}{2})}
		\Bigg]n^{-1}
		+O\!\left(n^{-\frac32}\right)
		\Bigg\}.
		\end{aligned}
	\end{equation}
	and 
		\begin{equation}
	\begin{aligned}
		C_{n,n+k}^{e,f}&
		=\sqrt{2\pi}\,n^{\,n+\frac{3k-5}{2}}
		\Bigg\{
		\frac{9k\,\chi_k}{2^{\frac{3k+2}{2}}\Gamma\!\left(\frac{3k+2}{2}\right)}
		+\frac{3(3k-1)\bigl(\tilde{\chi}_k+k\chi_k\bigr)}{2^{\frac{3k+1}{2}}\Gamma\!\left(\frac{3k+1}{2}\right)}\,n^{-\frac12}\\&
		+\frac{(9k-6)\hat{\chi}_k+\bigl(9k^2-9k+2\bigr)\tilde{\chi}_k+\frac14\bigl(18k^3-9k^2+34k+37\bigr)\chi_k}
		{2^{\frac{3k}{2}}\Gamma\!\left(\frac{3k}{2}\right)}\,n^{-1}
		+O\!\left(n^{-\frac32}\right)
		\Bigg\}.
	\end{aligned}
	\end{equation}

[Theorem general of arXiv:2602.18784, 'A note on the cooperative two-type SIR processes on Galton-Watson trees'] Consider the two-type SIR process on $GW (p)$ with parameters $\alpha_i$, $\beta_i$, $\mu_i$, $i=1,2$. At time $0$, the root is infected with both disease $A$ and disease $B$. All other vertices are susceptible to both $A$ and $B$. Let $m$ be the mean of $p$. If
    \begin{equation}
      \max\left\{\frac{\alpha_1}{\mu_1},\frac{\alpha_2}{\mu_2}\right\}\leq \frac{1}{m-1}
      \textnormal {,}
    \end{equation}
then the probability of survival is $0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Upper bound of cumulants Wigner of arXiv:2411.11341, 'Ultra high order cumulants and quantitative CLT for polynomials in Random Matrices'] Let $\mathcal{X}\sim Wigner$.  Consider the polynomial $P(\mathcal{X},\mathcal{D})$ in ((def of P of the paper)) and the random variable $\mathbf{X}$ defined in ((object of the paper)).  Suppose that $\mathbf{C}_1$ is satisfied. 
Then there exists a constant $\theta_2 \equiv \theta_2 (K, M, \mathsf{C}, t) \in (0, 1)$ such that 
\begin{align}|K_r(\mathbf{X})|\leq \frac{r!^{3M}}{(\theta_2 \sqrt{N})^{r-2}}

\end{align}
for any $N$ and $r\geq 3$. If $\mathbf{C}_1'$ is additionally assumed, we get the sharper bound
\begin{align}|K_r(\mathbf{X})|\leq \frac{r!^{M}}{(\theta_3 \sqrt{N})^{r-2}}.

\end{align}
with some constant $\theta_3\equiv \theta_3(K,M,\mathsf{C}, t) \in (0,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=(V,E)$ be a locally finite weighted graph and let $\psi\in C^{1}(0,+\infty)$. Then for any function $0<f\in\mathbb{R}^{V}$, 
\begin{equation*}
    -\Delta^{\psi}f=\Gamma^{\psi}\left(f\right)-{\psi}^{\prime}\left(1\right)\frac{\Delta f}{f}.
\end{equation*}

