[Lemma lem:head-correction-bounds of arXiv:2608.10184, 'The sharp SAT/UNSAT phase transition in random ellipsoid fitting'] Fix $C_0<\infty$ and set $K_d=\lfloor C_0d\log d\rfloor$. Fix $Z \in \mathsf{S}^d$ and let $P\in\mathcal{K}_{\kappa_0}\cap\mathbb{S}_{\mathrm{F}}$ be a support maximizer (equation eq:P-max of the paper). Put $R_d=\max_{i\le n}|r_i|$, and suppose $R_d\le C_A\sqrt{\log d/d}$ and work on $\mathcal{E}_{\mathrm{data}}$.  For each nonempty $J\subseteq[n]$ with $|J|\le K_d$, let $Q_J = \mathcal{W}_J \mathcal{W}_J^*$ and define
\begin{equation}
a_J = Q_J^{-1} r_J, \qquad
E_J = -\mathcal{W}_J^* a_J , \qquad \widetilde P_J = \frac{P + E_J}{\|P + E_J\|_{\mathrm{F}}};
\end{equation}
for $J=\varnothing$, set $a_J=0$ and $E_J=0$.  For all sufficiently large $d$, simultaneously over $|J|\le K_d$,
\begin{equation}
\widetilde P_J\in \mathcal{K}_{\kappa_1}\cap\ker\mathcal{W}_J\cap\mathbb{S}_{\mathrm{F}},
\end{equation}
and
\begin{equation}
\sup_{S \in \mathcal{K}_{\kappa_1} \cap \ker\mathcal{W}_J \cap \mathbb{S}_{\mathrm{F}}} \ip{Z}{S}
\;\ge\;
\sup_{R \in \mathcal{K}_{\kappa_0} \cap \mathbb{S}_{\mathrm{F}}} \ip{Z}{R}
\;-\; C\, \|Z\|_{\mathrm{F}}\, \frac{\log d}{\sqrt d}  .
\end{equation}

