body:
[Theorem 9 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $S_n$ be a TMERW. Let the collection of sets $\DD$ be a nested sequence generated according to an arithmetic progression, i.e for some fixed $\mu, k \in \bN$, $\PP \left(\tau =k\right)=\PP \left(\sigma =\mu-k\right)=1$. 
Write $ s^*=\frac{(2\lambda-1)(\mu-k)}{\mu - (2p-1)k}$. Let $\Sigma$ and $\widetilde{\Sigma}$ be two positive constants that depend on the parameters. Then,
\begin{enumerate}[i.]
\item If $k> \frac{\mu}{2}$, then there exists a phase transition into a diffusive, critical and superdiffusive behaviour characterised below:
\begin{enumerate}[a.]
\item When $p<\frac{1}{2}+\frac{\mu}{4k}$, then 
\begin{equation}

\frac{S_n -n s^*}{\sqrt{n}}\stackrel{d}{\longrightarrow} N (0, \Sigma),
\end{equation}
\item When $p= \frac{1}{2}+\frac{\mu}{4k}$, then 
\begin{equation}

\frac{S_n- n s^* }{\sqrt{n \log n}}\stackrel{d}{\longrightarrow} N (0,\widetilde \Sigma),
\end{equation}
\item When $\frac{1}{2}+\frac{\mu}{4k} <p \le 1$, then there exists a random variable $\xi$, such that, 
\begin{equation}

\frac{S_n- n s^* }{n^{1-\rho^*}} \longrightarrow \xi, \text{ a.s.},
\end{equation}
where $\rho^*= 1- (2p-1)\frac{k}{\mu}$. 
\end{enumerate}
\item For $k =\frac{\mu}{2}$, if  $0 \le p <1$, 
\begin{equation}

\frac{S_n -n s^*}{\sqrt{n}}\stackrel{d}{\longrightarrow} N (0, \Sigma),
\end{equation}
And when $p=1$,
\begin{equation}

\frac{S_n -n s^*}{\sqrt{n \log n}}\stackrel{d}{\longrightarrow} N (0, \widetilde\Sigma),
\end{equation}
\item If $k < \frac{\mu}{2}$, and $0 \le p \le 1$, then 
\begin{equation}

\frac{S_n -n s^*}{\sqrt{n}}\stackrel{d}{\longrightarrow} N (0, \Sigma).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 5 (Quasi-geodesics) of arXiv:2607.08632, 'Uncountably many extremal Series--Sinai states for the Ising model on Lobachevsky lattices'] Let \(k \ge 1\) and \(c \ge 0\) and let \(I\) be a \emph{closed} interval of \(\mathbb{R}\).
    A \emph{\((k, c)\)-quasigeodesic curve} \(f\) of \(X\) is an application \(f:I\to X\) such that for all \(s,\,t \in I\), we have
    \begin{equation}
        \frac{1}{k} \abs{t-s} - c
        \le 
        \distance{f(s)}{f(t)}
        \le 
        k \abs{t-s} + c.
    \end{equation}
    Moreover, if \(I\) is \emph{bounded} (\resp~\(I = \mathbb{R}\)), we say that \(f\) is a \emph{\((k, c)\)-quasigeodesic segment} (\resp~\emph{complete \((k, c)\)-quasi-geodesic}).

[Lemma lem:intersection of arXiv:2606.16259, 'Super-Arrhenius relaxation of the triangular plaquette model in any dimension'] \leavevmode
\begin{enumerate}
\item If $x\neq y$ are in $\mathbb Z^d$, then $K_x\cap K_y=\varnothing$.
\item A plaquette intersects inverted plaquettes in exactly one of the following ways:
\begin{enumerate}
\item it intersects none;
\item it intersects exactly one inverted plaquette and does so in exactly two points;
\item it has the form $2x+T_d$ for some $x\in\mathbb Z^d$ and intersects exactly the $d+1$ inverted plaquettes
$K_x,K_{x+e_1},K_{x+e_2},\dots, K_{x+e_d}$, each in one point.
\end{enumerate}
\end{enumerate}

[Theorem repres of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] If $h$ is a non-negative harmonic function, then there exists a Radon measure $\mu_h$ on $[\alpha^*, \alpha^{**}]$ satisfying
\begin{equation}
\forall z \in {\mathbb R}_+^2,\quad h(z) = \int_{[\alpha^*, \alpha^{**}]} h_\alpha(z)d\mu_h(\alpha).
\end{equation} 
Furthermore, every function defined by ((inte of the paper)) is harmonic. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] We say that $\eta\in \cB\setminus\{0\}$ is \emph{indecomposable} if for every decomposition
    \begin{align}
        \eta=\eta_1+\eta_2,\qquad \eta_1,\eta_2\in\cB,
    \end{align}
    there exists $a\in[0,1]$ such that $\eta_1=a\eta$ and $\eta_2=(1-a)\eta$.

[Prop 18 (\bf{the concentration inequality}) of arXiv:2606.08115, '2606.08115'] Let $\{S_n\}$ be a random walk with increments $X_j$, $\ex X_j = 0$, $\ex X_j^2 = \sigma^2 \in (0, +\infty)$. Then there exists a real number $C$ such that for any $\Delta > 0$ there exists a natural $N$ such that for every $n > N$
\begin{equation}

\sup_{x\in \mathbb{R}}\pr\left(S_n \in [x, x + \Delta)\right) \le \frac{C \Delta}{\sqrt{n}}.
\end{equation}
\begin{proof}
See, e.g. \cite{Petrov}, Section \RomanNumeralCaps{3}, Theorem 9.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p.hilsp of arXiv:2507.16056, 'Conditional GMC within the stochastic heat flow'] Conditioned on a realization of the $O_{I_1\ldots I_k}$s (or on $\mathscr{F}$), there exists a separable Hilbert space $\mathcal{H}$ equipped with isometric embeddings 
\begin{align}
	\jmath_{\mathcal{I}}:\ell^2(\mathcal{I}\times\mathbb{N})\hookrightarrow\mathcal{H}\ ,
	\quad
	\mathcal{I}\in\mathscr{I}\ ,
\end{align}
such that for every $\mathcal{I}\preceq\mathcal{I}'\in\mathscr{I}$
\begin{align}

	\jmath_{\mathcal{I}} = \jmath_{\mathcal{I}'}\, U^{\mathcal{I}'}_{\mathcal{I}}\ .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2602.14618, 'Finitary coding and Gaussian concentration\\ for random fields'] Let $f:B^{\Zd}\to\mathbb{R}$ be local. Let $n\in\N$, and let $\varphi^{(n)}$ be the truncated coding map (Definition \ref{def:truncA-d}). Then, for any $x,x'\in A^{\Zd}$,
\[
\big| f\circ \varphi^{(n)}(x)-f\circ \varphi^{(n)}(x') \big|
\le
\sum_{i\in\Zd}
\Bigg(
\sum_{j\in\dep(f)}
\delta_j f\;
\1\!\left\{ \|j-i\|_\infty\le r^{(n)}_\varphi(T^j x)\right\}
\Bigg)
\1_{\{x_i\neq x'_i\}}.
\]

[Propo 2 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] Assume that conditions $({\bf A1})$-$({\bf A3})$ are satisfied. Moreover, suppose that either the time horizon $T$ or the Lipschitz constant $K$ is sufficiently small so that 
\begin{eqnarray}
		(25+ 144K)Ke \max (1,T^2) < 1.
\end{eqnarray}
Then, the delayed forward-backward stochastic differential equation \eqref{Eq1} admits a unique adapted solution $(X^{t,x,\varepsilon}, Y^{t,x,\varepsilon}, Z^{t,x,\varepsilon} )$.

