body:
[Corollary 2 (Radial description of the bulk) of arXiv:2607.08696, 'Spectrum of Directed Inhomogeneous Random Graphs'] Under the assumptions of Theorem \ref{thm:bulk}, the limiting empirical spectral distribution of $A_n/\sqrt{\scaling}$ is the same as that of
\begin{equation}
\frac1{\sqrt n}G_n\bar W_n .
\end{equation}
Moreover, the limiting measure $\mu$ is radial and satisfies
\begin{equation}
\mu\left(\mathcal B(0,F(t))\right)=t,
\qquad 0<t\le 1,
\end{equation}
where
\begin{equation}
F(t)=\sqrt{\frac{t}{\mathcal S_{\bar\rho^2}(t-1)}} .
\end{equation}
Consequently, whenever $F$ is differentiable and strictly increasing, $\mu$ has density
\begin{equation}
d\mu(z)=
\begin{cases}
\frac{1}{2\pi |z| F'(F^{-1}(|z|))}\,d z,
& |z|\in(0,F(1)],\\
0, & \text{otherwise}.
\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition CH1 of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] For $s>0$, $q\in[1,\infty]$ and ${\boldsymbol{p}}\in[1,\infty]^2$, an equivalent norm of ${\mathbb B}^{s,q}_{{\boldsymbol{p}};{\boldsymbol{a}}}$ is given by
\begin{align}
\|f\|_{{\mathbb B}^{s,q}_{{\boldsymbol{p}};{\boldsymbol{a}}}}\asymp \left(\int_{{\mathbb R}^{2d}}\left(\frac{\|\delta_h^{([s]+1)}f\|_{{\boldsymbol{p}}}}{|h|^s_{\boldsymbol{a}}}\right)^q\frac{d h}{|h|^{4
d}_{\boldsymbol{a}}}\right)^{1/q}+\|f\|_{{\boldsymbol{p}}}=:[f]_{{\mathbb B}^{s,q}_{{\boldsymbol{p}};{\boldsymbol{a}}}}+\|f\|_{{\boldsymbol{p}}},
\end{align}
where $[s]$ is the integer part of $s$. In particular, ${\mathbb C}^s_{{\boldsymbol{a}}}:=\mathbf{B}^{s,\infty}_{\infty;{\boldsymbol{a}}}$ is the anisotropic
H\"older-Zygmund space, and for $s\in(0,1)$, there is a constant $C=C(\alpha,d,s)>0$ such that
\begin{align*}
  \|f\|_{{\mathbb C}^s_{{\boldsymbol{a}}}} \asymp_C\|f\|_\infty+\sup_{z\not= z'}|f(z)-f(z')|/|z-z'|^{s}_{\boldsymbol{a}},
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:empb-fixn of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Suppose $\alpha \in (0,1)$.
    Let $ \mathbf{X} _1,\dots, \mathbf{X} _n$ be adapted $\mathcal{S}_d^{[0,1]}$-valued random matrices with constant conditional mean $ \mathbf{M}  =  \mathbb E  ( \mathbf{X} _i|\mathcal{F}_{i-1})$ and constant conditional variance $ \mathbf{V}  =  \mathbb E (  ( \mathbf{X} _i -  \mathbf{M} )^2|\mathcal{F}_{i-1} )$.  Let $\overline{ \mathbf{X} }_i = \frac{1}{i}( \mathbf{X} _1+\dots+ \mathbf{X} _i)$ and $\overline{ \mathbf{X} }_0 = 0$.
     Define the following variance proxies
    \begin{gather}
       \overline{ \mathbf{V} }_0 = \frac
       1 4  \mathbf{I} , \quad  \overline{ \mathbf{V} }_k = \frac{1}{k}\sum_{i=1}^k ( \mathbf{X} _i - \overline \mathbf{X} _k)^2, \quad  \overline{v}_k = \|\overline{ \mathbf{V} }_{k}\| \vee \frac{5\log(d/\alpha)}{n},
    \end{gather}
    and set $\gamma_i = \sqrt{\frac{2\log(d/\alpha)}{n \overline{v}_{i-1}}}$ for $i=1,\dots, n$. Then,
    \begin{equation}
          \mathbb P \left( \lambda_{\max} \left( \overline{ \mathbf{X} }_n^{\gamma} -  \mathbf{M}  \right) \geqslant D_n^{\mathsf{meb2}}  \right) \leqslant \alpha, \, \text{where} \ D_n^{\mathsf{meb2}} = \frac{  \log(d/\alpha) +\lambda_{\max}\left( \sum_{i=1}^n \psi_{\mathrm{E}}(\gamma_i) ( \mathbf{X} _i - \overline{ \mathbf{X} }_{i-1})^2 \right)  }{\gamma_1 + \dots + \gamma_n}.
     \end{equation}
    Further, 










        asymptotically,
        \begin{equation}
          \lim_{n \to \infty} \sqrt{n}   D_n^{\mathsf{meb2}} = \sqrt{2\log(d/\alpha) \| \mathbf{V} \|} \quad \text{almost surely}.
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:process_level_convergence of arXiv:2607.13748, 'Load Balancing with Individually Heterogeneous Servers'] Suppose that under tie-breaking policy $\pi$, $\eta^{\pi, n}\stackrel{f}{\rightarrow} \eta^{\pi}$ and $\hat{\alpha}_1^{\pi, n}(n^{1/2}\cdot)\Rightarrow \alpha_1^{\pi}$ jointly. Then $(X_1^{\pi, n}, \boldsymbol{\xi}^{\pi, n})\Rightarrow (X_1^{\pi},\boldsymbol{\xi}^{\pi}),$ where $(X_1^{\pi},\boldsymbol{\xi}^{\pi})$ is the unique solution of
\begin{align}
     X_1^{\pi}(t) & = X_1(0) - (\varsigma+ \nu) t + \sqrt{2}W(t) - \langle \iota, \eta^{\pi}(t)\rangle\int_0^t X_1^{\pi}(s)ds + \int_0^t \langle \iota, \xi_2^{\pi}(s)\rangle ds - U_1^{\pi}(t),\\

    \langle f, \xi_2^{\pi}(t)\rangle & = \langle f, \xi_2(0)\rangle + \langle f, \alpha_1^{\pi}(U_1^{\pi}(t))\rangle - \int_0^t\langle f\times \iota, \xi_2^{\pi}(s)\rangle ds + \int_0^t \langle f\times\iota, \xi_3^{\pi}(s)\rangle ds ,\\

     \langle f, \xi_i^{\pi}(t)\rangle & = \langle f, \xi_i(0)\rangle - \int_0^t\langle f\times \iota, \xi_i^{\pi}(s)\rangle ds +  \int_0^t \langle f\times\iota, \xi_{i+1}^{\pi}(s)\rangle ds,\mbox{ for all }i\geq 3, 
\end{align}
for any fixed $L>0$ and all $f\in\Lipbar{\mathbb{R},L}(\mathbb{S})$, where $W$ is a standard Brownian motion defined on the same probability space as $\eta^\pi$ and $\alpha_1^\pi$, and may depend on these processes. Moreover, $U_1^\pi\in\mathbb{D}_{\mathbb{R}_+}[0,\infty)$ is a non-decreasing function with $U_1^\pi(0)=0$ and satisfies
\begin{align}
\int_0^\infty \mathbb{I}\bigl(X_1^\pi(s)<0\bigr) dU_1^\pi(s)=0.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor  t LIL of arXiv:2607.28167, 'Temporal properties of the stochastic fractional heat equation with rough dependence in sp'] Assume  Condition (cond A of the paper) holds.
    Choose and fix $t>0$ and $x\in \mathbb R$.  Then with probability one,
    \begin{itemize}
    \item[(a).] (Khinchin's law of the iterated logarithm)
    \begin{equation}
    \begin{split}
    \limsup_{\varepsilon \to 0}\frac{|u(t+\varepsilon, x)-u(t, x)|}{\varepsilon^{\widetilde{H}/2}\sqrt{2 \log\log(1/\varepsilon)}}= \kappa |\sigma(u(t, x))|,
    \end{split}
    \end{equation}
    where $\widetilde{H}=\frac{\alpha+2H-2}{\alpha}$.
        \item[(b).]  (Chung's law  of the iterated logarithm)
    \begin{equation}
    \begin{split}
    \liminf_{\varepsilon \to 0}\sup_{0\le r\le \varepsilon}\frac{|u(t+r, x)-u(t, x)|}{(\varepsilon/  \log\log(1/\varepsilon))^{\widetilde{H}/2}}=  \kappa\lambda_{\widetilde{H}}^{\widetilde{H}/2} |\sigma(u(t, x))|,
    \end{split}
    \end{equation}
    where $\lambda_{\widetilde{H}}$ is the small ball  constant of a fBm with index $\widetilde{H}/2$ (see, e.g., [LS01*]).
  \end{itemize}
  If   $ \beta_0>\frac{\alpha+2H-2}{\alpha}$ in Condition (cond A of the paper), then both results also hold at $t=0$ with $\kappa$ in (equation eq constant 1 of the paper) replaced by   \begin{align}
             \widetilde\kappa= \left( \frac{ \Gamma(2\widetilde{H}) }{2^{1-\widetilde{H}} \Gamma(\widetilde{H})}\right)^{1/2}.
             \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

