body:
[Theorem 3 of arXiv:2604.00756, '\textbf{Stochastic ordering tools for continuous-time Markov chains and applications to re'] Let $E \subseteq \Z^d$. Consider a CTMC $W = \brb{W(t)}_{t \geq 0}$ with state space $E \times E$ and rate matrix $Q^W$ having finite diagonal elements (i.e.\ no instantaneous states), such that for all $x, y, x', y' \in E$ with $x \neq x'$ and $y \neq y'$
        \begin{equation}

            \sum_{z' \in E} Q^W\brb{(x,y), (x',z')} = q^X(x,x')
        \end{equation}
        is independent of $y$, and
        \begin{equation}

            \sum_{z' \in E} Q^W\brb{(x,y), (z',y')} = q^Y(y,y')
        \end{equation}
        is independent of $x$. Then, there exist two CTMCs $X = \brb{X(t)}_{t \geq 0}$ and $Y = \brb{Y(t)}_{t \geq 0}$ with state space $E$ and transition rates $q^X$ and $q^Y$ respectively, such that $\tau^X \wedge \tau^Y = \tau^W$ and
        \begin{equation*}
            W(t) = \brb{X(t), Y(t)} \ \ \forall t \in [0,\tau^W).
        \end{equation*}

[Lemma 9 of arXiv:2609.02065, '\textbf{From Bowditch's question to Goldman's conjecture for type-preserving representatio'] \cite[Lemma 1.4]{goldman}
        Let $X, Y$ be smooth manifolds, and let $f: X\to Y$ be a smooth map. Suppose that 
        (a) $f$ is a submersion, and 
        (b) $f^{-1}(y)$ is path-connected for every $y\in Y$.
        Then $f$ satisfies the strong path-lifting property. Furthermore, 
        if $Y$ is path-connected, then $X$ is path-connected. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 37 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Let $a,b>0$. Let $(D,\phi,-i,\infty,-1,\eta')$ (for $\gamma\in(\sqrt2,2)$) or $(\bbH,\phi,0,\infty,-1,\eta')$ (for $\gamma\in(0,\sqrt2)$) be an embedding of the surface from 
     \begin{equation}
         \int_0^\infty a\MT(\ell,b,\ell+a)\,\d\ell
    \end{equation}
    as described in the paragraph before Theorem~\ref{thm:ASYZ3.9}. Pick $r$ from the uniform probability measure on $[0,a]$, and mark the point $w$ on $(-\infty,-1)$ such that  $(-\infty,w)$ has quantum length $r$.  Let $T$ be the duration of $\eta'$ and $\tau$ be the time when $\eta'$ hits $w$. Let $\cD_1 = (\eta'([0,\tau]),\phi,\eta|_{[0,\tau]}) {/}{\sim_\gamma}$ and $\cD_2 = (\eta'([\tau,T]),\phi,\eta|_{[\tau,T]}) {/}{\sim_\gamma}$. Then for some constant $C\in(0,\infty)$, the LQG surfaces $(\cD_1,\cD_2)$ has the law
    \begin{equation}
        C\int_0^a\int_0^\infty\int_0^b \int_0^\infty\MD(a+\ell-r;b+s-t) \times \MC(r,\ell,t,s)\,\d \ell\,\d t\,\d s\,\d r.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

