[Lemma 23 (Lemma 4.12, \cite{HanIyerEA26}) of arXiv:2604.17526, '2604.17526'] For any $\alpha > 0$, there exist constants $C_\alpha = C_\alpha(\alpha, U)>0$ (depending on $\alpha$) and $\hat C_N = \hat C_N(U, \nu) > 1$ (independent of $\alpha$) such that for any $\delta>0$, if 
\begin{equation}
N \geq \hat C_N \frac{K^2}{\delta^2}\,,\quad
T \geq C_\alpha \paren*{K^{(1+\alpha)\hat \gamma_r} + \frac{1}{\epsilon} + \log\paren*{\frac{1}{\delta}} + \log\paren*{N}}\,,
\end{equation}
then for each $2\leq k\leq K-1$, we have
\begin{equation}
\Err_{k+1, 0}(\psi_{2, k+1}) \leq \beta_k \Err_{k,0}(\psi_{2,k}) + c_k\,.
\end{equation}

Here, the constants $\beta_k, c_k$ are such that for every $k\in \set{2,\ldots, K-1}$, we have 
\begin{align}
\prod_{j=k}^{K-1} \beta_j &\leq C_\beta\,,\\

c_k&\leq \frac{\delta}{K}\,,
\end{align}
for some dimensional constant $C_\beta > 1$ (independent of $\alpha$, $\delta$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: KT estimate of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists $C>0$ and $\kappa'>0$ sufficiently small such that, for every $\varphi_-,\varphi_+ \in \mathfrak X$ and for every $T>0$,
\begin{align}
&\mathbb E[\|K_T\|_{H^{1-\kappa}}^2] 
\\&\qquad \leq C \Big(  1+  \| H(\varphi_-,\varphi_+)_T\|_{L^{2-\kappa'}}^2 + \| d(\cdot,\partial M)^{1/2} \llbracket H(\varphi_-,\varphi_+)_T^2 \rrbracket \|_{L^{2-\kappa'}}^2 
\\ &\qquad \qquad  +\| d(\cdot,\partial M) \llbracket H(\varphi_-,\varphi_+)^3 \rrbracket \|_{L^{2-\kappa'}}^2 \Big) + \mathbb E\left[ \|Z_T\|_{L^4}^4 + \frac 12 \int_0^T \| \ell_T(u)\|_{L^2_x}^2 dt \right].
\end{align}

