[Corollary 132 of arXiv:2601.16377, '2601.16377'] Assume in the setting of Theorem~\ref{Theorem_correlators_expansion} that we have $\theta_{g,g} = 1$ for every $g \in [H]$. Let $h \in [H]$ and set
\begin{equation}

\hat{W}_{1;h}^{[2]}(z) = \Op_{h}\Bigg[\bigg(\frac{1}{s_g^{\circ}}\Big\{\hat{q}^{+,[2]}_{g} + \frac{q_g^+}{2} \big\langle \bth_g^{\otimes 2}\cdot \boldsymbol{\mathcal{F}}_{\bullet,\bullet}(*,*) \big\rangle \Big\}\bigg)_{g = 1}^{H}\,;\,\boldsymbol{0}\bigg],
\end{equation}
where
\begin{equation}

\hat{q}_{h}^{+,[2]}(z) = \frac{q_h^-(z)}{24} \big\langle \bth_h(4\bth_h^2 - 6\bth_h + 3) \cdot \partial_z^2 \mathcal{G}_{\boldsymbol{\mu}}(z)\big\rangle -   \frac{\partial_z^3 U_h(z)}{12} \cdot \phi_h^{+}(z) \cdot e^{\langle \bth_h \cdot \mathcal{G}_{\boldsymbol{\mu}}(z)\rangle}.
\end{equation}
Then, \eqref{eq_x30} and \eqref{eq_x31} can be replaced with
\[
\big|W_{1;h}(z) - \N^{-1}\hat{W}_{1;h}^{[2]}(z)\big| \leq C_1 \N^{-\frac{3}{2} + \varepsilon}, \qquad \big|\hat{W}_{1;h}^{[2]}(z)\big| \leq C_1.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary polynear of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Fix $q \in [0,1)$, let $H_n\left(x|q\right)$ be the $a = 1$ continuous big q-Hermite polynomial, then for $u\in \left(0,1\right)$,
    \begin{equation}
        \lim_{n \to \infty} H_n\left(1 - \frac{u^2}{2 n^2}\right) = \cos{u}. 
    \end{equation}

[Prop approx Identity Limit of arXiv:2607.17393, 'Optimal Covariance Estimates for Schr\"odinger Semigroups with White Noise in $d=1,2$'] Fix $d\in\{1,2\}$, $x,y\in\mathbb{R}^d$ and $s,t>0$. Then, 
\begin{align}
    \mathbb{E}[\alpha_{t,s}(B_t^{x,x},\overline{B}_s^{y,y})] = \int_0^t\int_0^s \frac{\exp(-\frac{|x-y|^2}{2z(s,t,u,v)})}{(2\pi z(s,t,u,v))^{d/2}}dudv = \int_0^t\int_0^s p_{z(s,t,u,v)}(x-y)dudv
\end{align}
where 
\[z(s,t,u,v) = \frac{u(t-u)}{t}+\frac{v(s-v)}{s}\] (Proof in the paper; no proof environment follows the statement in the TeX.)

