[Lem 8 of arXiv:2608.02103, '$p$-Adic Diffusion and Random Walks on $[0,1]$'] The assignment     \begin{equation}
        C[0,1]\ni u(x) \mapsto
            \mathcal{W} u(x) = \int_0^1 w(x,y)( u(y) - u(x))\mathop{dy}
    \end{equation}
    is a well defined linear bounded operator on $C[0,1]$.

[Definition 4 of arXiv:2604.10705, '#1'] Let $s \in [0,T]$, let $a \in D([0,s],\mathbb{R}^d)$, and let $b \in D([0,T-s],\mathbb{R}^d)$. The function $\extension \in \cadlag$ is defined via
        \begin{align*}
        (a\otimes_s b)(t) := \begin{cases}
        a(t), \text{ $t < s$,}\\
        b(t-s), \text{ $t \geq s$.}
        \end{cases}
        \end{align*}
        If $a, b \in \cadlag$, $a \otimes_s b := a_{[0,s]}\otimes_s b_{[0,T-s]}$, where $a_{[0,s]}$ and $b_{[0,T-s]}$ denote the respective restriction of $a$ and of $b$ to $[0,s]$ and $[0,T-s]$.

[Lemma lem:mainBound of arXiv:2608.13452, 'Wasserstein stability of the zero cell of a Poisson hyperplane tessellation under directio'] Fix \(\gamma>0\), let \(\phi_1,\phi_2\) be nondegenerate even probability measures on $S^{d-1}$, and define stationary Poisson hyperplane processes \(\Psi_1,\Psi_2\) with common intensity \(\gamma\) and directional distributions \(\phi_1,\phi_2\), respectively.
    Let $Z_0(\Psi_1)$ and $Z_0(\Psi_2)$ be the zero cells of \(\Psi_1\) and \(\Psi_2\).
    Then, for $p \in [1, \infty)$,
    \begin{align*}
        W_{\rho_p}\bigl(Z_0(\Psi_1),Z_0(\Psi_2) \bigr) 
        \leq \frac{K_p(\phi_1,\phi_2)}{\gamma} W_{\mathrm{geo}}(\phi_1,\phi_2)^{\frac{1}{p}}, 
    \end{align*} 
    and    
    \begin{align*}
        W_{\Delta}(Z_0(\Psi_1),Z_0(\Psi_2)) 
        \leq \frac{K_\Delta(\phi_1,\phi_2)}{\gamma^d} W_{\mathrm{geo}}(\phi_1, \phi_2)^{\frac{1}{d}},
    \end{align*}
    where

\begin{align} 

        K_p(\phi_1,\phi_2)
        &:= \left(\Gamma(p+1)
        \int_{S^{d-1}} \frac{h(\Pi_1,u)^p + h(\Pi_2,u)^p}{(h(\Pi_1,u) + h(\Pi_2,u)) h(\Pi_1,u)^p h(\Pi_2,u)^p} \sigma(\mathop{}\!\mathrm{d} u) \right)^{\frac{1}{p}}
    \end{align}
    and
    \begin{align}

        K_{\Delta} (\phi_1,\phi_2)
        &:= \frac{K_d (\phi_1,\phi_2)}{2^{d-1}}\left(d!\int_{S^{d-1}}
             h(\Pi_1,u)^{-d} + h(\Pi_2,u)^{-d} \sigma(\mathrm{d}u) \right)^{\frac{d-1}{d}},
    \end{align}
    where $K_d (\phi_1,\phi_2)$ is the constant (equation def:Kp of the paper) for $p = d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

