[Corollary cor: estimates for km of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $(\lambda,C^2) \in S^0$.
  \begin{enumerate}
    \item[(i)] If $0\leq \lambda < \frac{p-1}{2}$ and $\gamma_p = \min\left(\frac{4p}{2p-2}-1, \frac{6p-4}{2p-2}-1\right)$, then there exist $B_{\lambda,p}, \varepsilon_{\lambda,p} \in (0,\infty)$ such that for all $C^2<\varepsilon_{\lambda,p}$
    \begin{equation*}
      \left(\frac{(p-1)(p-1-2\lambda)}{p^2} \right)^{\frac{1}{2-2p}} C^{\frac{2}{2p-2}} -B_{\lambda,p} C^{\gamma_p} < k_m < \left(\frac{(p-1)(p-1-2\lambda)}{p^2} \right)^{\frac{1}{2-2p}} C^{\frac{2}{2p-2}}.
    \end{equation*} 
    Moreover, for $0<\delta\ll 1$ fixed, if $\lambda \in [0,\frac{p-1}{2}-\delta]$, then $B_{\lambda,p} \in [m_{\delta,p}, M_{\delta,p}]$ for some constants $0<m_{\delta,p}, M_{\delta,p}$.

    \item[(ii)] If $\frac{p-1}{2}<\lambda < p-1$, then there exists $B_{\lambda,p}, \varepsilon_{\lambda,p} \in (0,\infty)$ such that for all $C^2<\varepsilon_{\lambda,p}$
    \begin{equation*}
      \left(\frac{2\lambda}{p-1}-1 \right)^{\frac{1}{p}}  < k_m < \left( \frac{2\lambda}{p-1}-1 \right)^{\frac{1}{p}} + B_{\lambda,p} C^{2}.
    \end{equation*}
    Moreover $\lambda \mapsto B_{\lambda,p}$ is continuous and $\lim_{\lambda\to p-1}B_{\lambda,p}=  \frac{5}{p-1}$. Also for $0<\delta\ll 1$ fixed, if $\lambda \in [\frac{p-1}{2}+\delta,p-1)$ then $B_{\lambda,p} \in [m_{\delta,p}, M_{\delta,p}]$ for some constants $0<m_{\delta,p}, M_{\delta,p}$.
  \end{enumerate}

