[Definition 13 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Reverse Shade, Shadow-Cutting Building.}

Let $(\alpha, \beta)\in \landsc$ be a building. We define its \textit{reverse shade} $\rs(\alpha, \beta)$ as the shade (on the left of a) of $(\alpha, \beta)$ from $\tau(\alpha, \beta)$ ($=(\alpha_b, \beta_b)$):
\[\rs(\alpha, \beta) :=  \left\{(x, y) \in \Half: x\leq \alpha \text{ and } \frac{\beta-y}{\alpha-x} \geq \frac{\beta_b-\beta}{\alpha_b-\alpha}\right\}.\]

From there, we further define the \textit{shadow-cutting building} $\rb$ of $(\alpha, \beta)$ as the closest building to the left of $(\alpha, \beta)$ that does not lie in $\rs(\alpha, \beta)$:
\[\rb := \max\left\{(x, y) \in L: x\leq \alpha \text{ and } \frac{\beta-y}{\alpha-x} < \frac{\beta_b-\beta}{\alpha_b-\alpha}\right\}.\]
        \begin{figure}[h]
            \centering
            \includegraphics[width=0.75\textwidth]{Figures/reverse_shade.ipe.png}
            \caption{The shadow-cutting building can be seen as the one on which the shadow of $b$ stops.}
        \end{figure}\\

[Satz thm:compactly-supported-wavelet of arXiv:2411.18155, 'Besov regularity of random wavelet series'] For each $k\in\mathds{N}$, there exists a multiresolution analysis $(V_j)_{j\in\mathds{Z}}$ of $L_2(\mathds{R})$ with scaling function $\psi_F\in L_2(\mathds{R})$ and wavelet function $\psi_M\in L_2(\mathds{R})$ such that the following hold:
\begin{enumerate}[label={(\roman*)},leftmargin=*,align=left,noitemsep]
\item{$\psi_F$ and $\psi_M$ are real-valued and compactly supported,}
\item{$\psi_F$, $\psi_M\in C^k(\mathds{R})$,}
\item{$\widehat{\psi_F}(0)=(2\piup)^{-\frac{1}{2}}$,}
\item{$\int_\mathds{R} x^\ell \psi_M(x)\mathrm{d} x =0$ for all $\ell\in\left\{0,\ldots,k\right\}$.}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:domination2supply nodestrimmed of arXiv:2601.13426, 'A uniformity principle for spatial matching'] Given any constant $\gamma \geq \max\{1,\xi^{-1} \}$,  let  $\mathsf{R}\in [0, \gamma]^{n-2} $ be a vector of service ranges. For any two additional ranges $r_1, r_2$ with $ 0 \leq r_1 \leq r_2 \leq \gamma$, any $\tau\in[0,(r_2 - r_1)/2]$, any $\varepsilon \leq w_{k, \gamma}$ and all $n \geN_{k,\xi,\gamma}$, 
    \begin{align}
        \mu_m^\varepsilon\left(\mathsf{R} \oplus \left(r_1+\tau\right) \oplus \left(r_2-\tau\right)\right)-\mu_m^\varepsilon \left(\mathsf{R} \oplus r_1 \oplus r_2 \right) \geq  \, \alpha_{k,\xi,\gamma}' \, \tau^{4} - {\beta_{k,\gamma} \, \varepsilon^{-k}}/{n}, 
    \end{align}  
    where each constant $\alpha_{k,\xi,\gamma}'$ and $\beta_{k,\gamma}$ depends only on the variables in the subscript. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2607.02406, 'On the range of competing random walks'] If $d/\beta<2$, then for all $p\ge1$,
    \begin{equation*}
        \frac{h(n)^2b(n)^d}{n^2}\mathcal I_{n,q,m}^{j\rightarrow k}\distribution\alpha^{j,k}\left(\left[\frac{2m-2}{2^q},\frac{2m-1}{2^q}\right]\times\left[\frac{2m-1}{2^q},\frac{2m}{2^q}\right]\right)
    \end{equation*}
    jointly in $j,k\in[\![N]\!]$, $j\ne k$ and $q\in[\![p]\!]$, $m\in[\![2^{q-1}]\!]$. Furthermore, we also have the convergence of the first moments.

