[Definition def:weak-solutions of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] We say that $f$ is a weak solution to~(equation e.LFD of the paper) on $(0,T)\times\mathbb T^3\times\mathbb R^3$ for $0 < T \le \infty$ if, for some $m>2$,
    \begin{equation*}
        0 \leq f \leq 1 \quad \text{a.e.}, \qquad f \in L^\infty_{\rm loc}([0,T];L^\infty_m), \qquad \nabla_v f \in L^2_{\mathrm{loc}}\big((0,T)\times\mathbb T^3\times\mathbb R^3\big),
    \end{equation*}
    and, for every
    $\psi\in C_c^\infty((0,T)\times\mathbb T^3\times\mathbb R^3)$,
    \begin{equation}
        \iiint f(\partial_t+v\cdot\nabla_x)\psi \, {\rm d} v\, {\rm d} x\, {\rm d} t = \iiint \nabla_v\psi\cdot\left(A[f(1-f)]\nabla_v f - \nabla a[f]f(1-f)\right)\, {\rm d} v\, {\rm d} x\, {\rm d} t.
    \end{equation}

