[Definition def: fluid problem of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] The set of solutions of the \emph{fluid problem} is denoted by $\mathcal{S}^+$. We say that a measure-valued function $\boldsymbol{\mu} \in D_{\mathcal{M}_F^+(\mathbbm{R}_+^2)}[0, \infty)$ is a solution of the fluid problem, and thus belongs to $\mathcal{S}^+$, if it satisfies the following conditions.
	\begin{enumerate}
		\item[(a)] We have $\boldsymbol{\mu}_t(U_g^c) = 0$ for all $t \geq 0$, where we use the notation $U_g^c \vcentcolon= \mathbbm{R}_+^2 \setminus U_g$.

		\item[(b)] The $y$-marginal of $\boldsymbol{\mu}_t$ is absolutely continuous with respect to the Lebesgue measure for all $t \geq 0$; this is the measure $A \mapsto \boldsymbol{\mu}_t(\mathbbm{R}_+ \times A)$ defined for Borel sets $A \subset \mathbbm{R}_+$.

		\item[(c)] The following integral is finite for all $t \geq 0$:
		\begin{equation*}
			\int_0^t \angled{\bar r(\boldsymbol{\mu}_s)h_g^x + h_g^y}{\boldsymbol{\mu}_s}ds = \int_0^t\int_{U_g} \left[\bar r\left(\boldsymbol{\mu}_s, y\right)h_g^x(x, y) + h_g^y(x, y)\right]\boldsymbol{\mu}_s(dx, dy)ds < \infty.
		\end{equation*}

		\item[(d)] The following equation holds for all $t \geq 0$ and $\varphi \in C_c^1(\mathbbm{R}_+^3)$:
		\begin{equation}

			\begin{split}
				\angled{\varphi_t}{\boldsymbol{\mu}_t} &= \angled{\varphi_0}{\boldsymbol{\mu}_0} + \lambda_0 \int_0^t \varphi_s(0, 0)ds - \int_0^t \angled{\varphi_s\left[\bar r(\boldsymbol{\mu}_s)h_g^x + h_g^y\right]}{\boldsymbol{\mu}_s}ds \\
				&+ \int_0^t \angled{\partial_t\varphi_s + \bar r\left(\boldsymbol{\mu}_s\right)\partial_x\varphi_s + \partial_y\varphi_s}{\boldsymbol{\mu}_s}ds.
			\end{split}
		\end{equation}
	\end{enumerate}
	We remark that the values of the test function $\varphi$ are denoted by $\varphi_t(x, y)$, with the time variable as a subscript. Also, the integrals with respect to $\boldsymbol{\mu}_s$ only involve the variables $x$ and $y$ of the integrand and keep the time variable $s$ fixed. We establish in Appendix (app: measurability properties of the paper) that the iterated integrals on the right-hand side of (equation eq: transport equation of the paper) are well-defined. Specifically, we show that the inner integrals are Borel measurable with respect to $s$.

[Proposition 2 (Standard Bernstein representations) of arXiv:2607.04467, 'Bernstein Functions at Work:\\ Coalescents, Copulas, and Subordination'] The following standard facts are used below.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.3em]
\item If \(g\in\BF\), then there are \(a,b\ge0\) and a measure \(\nu\) on
\((0,\infty)\) satisfying
\(\int_{(0,\infty)}(1\wedge t)\,\nu(dt)<\infty\) such that
\begin{equation}
g(x)=a+bx+\int_{(0,\infty)}(1-e^{-xt})\,\nu(dt).
\end{equation}

\item If \(\psi\in\SBF\) and \(\psi(0)=0\), then the potential measure with
Laplace transform \(1/\psi\) admits a representation
\begin{equation}
\frac1{\psi(\lambda)}
=b+\int_0^\infty e^{-\lambda t}u(t)\,dt,\qquad \lambda>0,
\end{equation}
where \(b\ge0\) and \(u\) has a nonincreasing locally integrable version.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 16 ($(2\times\ell)$-periodic weights) of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] Let $\{\alpha_i\}^\ell_{i=1}$ and $\{\beta_i\}^\ell_{i=1}$ be two sets of positive real numbers satisfying
\[\prod_{m=1}^\ell \alpha_m=\prod_{m=1}^\ell \beta_\ell.\]
We define $(2\times\ell)$-periodic weights in the following way, for~$i=1,\dots,\ell$ and $j=1, 2$ set
\begin{equation*}
\alpha_{1,i} = \alpha_{2,i}^{-1} = \alpha_i, \quad \beta_{1,i} = \beta_{2,i}^{-1} = \beta_i \quad \text{ and }\quad \gamma_{j,i}=\delta_{j,i}=1.
\end{equation*}

[Lem 22 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$ and $n \in \mathbb{N}_+$. Then
	\begin{align} 
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{\sqrt{n}} \int_s^t \dd r \sum_x \sum_{y=x+L_n}^{
	x+n-1}  [  H ( \tfrac{y - r v_n }{n}  ) - H ( \tfrac{x - r v_n }{n}  )  ] a(y-x)   \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \Bigg\}^{2} \Bigg] \nonumber \\
		\leq  & \widehat{C} (t-s)^{2} \Bigg\{ \frac{  \big[ \Theta(n) K_n \big]^{2}  }{ n^{4}  } \mathbbm{1}_{ \{ \gamma \geq 1 \} } + \frac{ [ \Theta(n) K_n  ]^{2} }{n^{2}} \sum_{x=L_n}^{n} x^{- 2 \gamma} \Bigg\}. 
	\end{align}
	Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}.

