[Lemma 33 (cf.\ {\cite[Proposition 3.5) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {MSS23}}] 
    Let
    \begin{align*}
        a_1 &:= a_1(\Delta, b) = F^{-1}_\mu \big(\frac{1}{\Delta -1} - \frac{p^*}{2} \big), \\
        a_2 &:= a_2(\Delta, b) = F^{-1}_\mu(1 - p^*).
    \end{align*}
    Then there exists a constant $C_\Phi = C_\Phi(p^*) > 0$, such that the weighted graph $(G'', \omega'')$ from \eqref{eq:bump_large_G''} satisfies
    \begin{equation} 
        \Phi_{(G'', \omega'')} \geq C_\Phi \frac{\exp (a_1 -a_2) }{\Delta^3 (\log n)^3}
    \end{equation}
    with probability $1 - O(n^{-2})$, provided that $p^* = p^*(\Delta, b) > 0$ is small enough.

