body:
[Lem lem-gf-bded of arXiv:2411.06301, 'Inverting the operation of conditioning a branching process on extinction'] Assume the hypotheses of Theorem~(thm-fixed-gf of the paper). 
There exists $q^0 \in (1,\infty)^d$ such that 
\begin{equation*}
f_k(q^0) < q^0_k ,\quad\forall k\in \{1,\dots,d\}. 
\end{equation*}

[Corollary 8 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] If $G$ is simply connected, then $G$ is semisimple, $\Lambda_G=2\pi Q_G^\vee$, where $Q_G^\vee$ is the coroot lattice, and $\varepsilon_G\equiv1$. Consequently
		\begin{equation}
			q_t^{\C}(\exp Z)
			=\frac{\vol(G)e^{t|\rho_G|^2}}{(4\pi t)^{\dim G/2}}
			\frac{\displaystyle\sum_{\gamma\in\Lambda_G}
				\Pi_G(Z+\gamma)
				e^{-\langle Z+\gamma,Z+\gamma\rangle/4t}}
			{\mathscr S_G(Z)},
		\end{equation}
		where the quotient is understood through its entire continuation across the removable singularities. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2609.00183, '2609.00183'] Let $u$ be a harmonic map to an $N$-dimensional conical DM-complex $Y_C$ with splitting $u=(V,v):B_{\sigma_j}(0) \to (\mathbb{R}^j \times Y_C^{N-j},d_G)$ satisfying $\Ord_{\phi,v}(0,R_0)\leq \Lambda \text{ and } \sup_{B_{\sigma_j}(0)}|\nabla u| \leq M.$ Let $0 < \rho < 1$ and $0<\eta<\eta_1$ where $\eta_1$ is chosen in the sense of Lemma \ref{bd5.12}. Then, there exist $\sigma_{\ref{bd5.13}},\delta_{\ref{bd5.13}}=(\sigma_{\ref{bd5.13}},\delta_{\ref{bd5.13}})(n,\rho,\eta,M,X,\Lambda)>0$ such that if $0<\sigma<\sigma_{\ref{bd5.13}}$ and $0<\delta<\delta_{\ref{bd5.13}}$ and
    \begin{itemize}
        \item the set $F:=\{x \in \mathcal{S}^k_{0,\eta,\delta\sigma}(v) \cap B_{\sigma}(0): W^{8\sigma}_{\sigma}(x,v) <\delta\} \ \rho\sigma$-effectively spans a $k$-dimensional affine space $V,$
        \item there exists $y \in B_{\sigma}(0) \cap V$ with $W^{8\sigma}_{\sigma}(y,v)<\delta,$
    \end{itemize}
    then $v$ is not $(\theta\eta,t,k+1)$-homogeneous at $y$ for all $t \in [2\rho\sigma,2\sigma]$, where $\theta=\frac{1}{2C}$ and $C$ is as in Corollary \ref{cor1}.

[Proposition 12 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Let $g$ be integrable with respect to $\Pi_Q$. Then there is a full Harris set $H\in\calX$ such that, for every $x\in H$,

\begin{equation*}
\frac{1}{n}\sum_{m=0}^{n-1}g(J_m,J_{m+1},X_{m+1})
\xrightarrow[n\to\infty]{} \bar g,
\qquad \Pp_x\hbox{-a.s.}
\end{equation*}

In particular,

\begin{equation*}
\frac{S_n}{n}\xrightarrow[n\to\infty]{} \mu=(\mu_1,\ldots,\mu_d),
\qquad \Pp_x\hbox{-a.s.}
\end{equation*}

coordinatewise, for every $x\in H$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Kolmogorov criterion of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $\{(X^n_{t})_{t\in \mathbb R}\}_{n\geq 1}$ be a sequence of $\mathbb R^d$-valued continuous processes defined on  probability spaces $(\Omega^n,\mathcal{F}^n,P^n)$ such that
    \begin{itemize}
        \item the family $\{P^n\circ (X^n_0)^{-1}\}_{n\geq 1}$ is tight \footnote{A family $\{P_i\}_{i\in I}$ of probabilities on $\mathbb{R}^d$ is said to be tight if for any $\epsilon>0$, there exists a compact subset $K$ of $\mathbb{R}^d$ such that $\sup_{i\in I}P_i(K^c)<\epsilon$.} on $\mathbb R^d$;
        \item there exist $C>0,\alpha>0,\beta>0$ such that for any $t,s\in \mathbb R$ and any $n\geq 1$
        \[
        \mathbb E_{P^n}[|X_t^n-X_s^n|^{\alpha}]\leq C|t-s|^{1+\beta}.
        \]
    \end{itemize}
    Then the family $\{P^n\circ (X^n)^{-1}\}_{n\geq 1}$ is a   relatively compact subset of the space of probability measures on $C(\mathbb{R},\mathbb{R}^d)$ with respect to the weak convergence topology. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 24 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\gamma\in(0,1)$ and $\alpha\in\mathbb R$. The assignment
\begin{equation}

\hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}:Z\hat C^{\gamma}(\Delta^3_T;B_\alpha)\to \mathfrak Q_{\mathrm{fr}}^{\gamma,\alpha},
\quad h\mapsto \hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}h,\quad 
\bigl(\hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}h\bigr)^\tau:=[r_{\mathrm d}^\tau(h)]_\tau,
\end{equation}
is a well defined continuous linear map such that
\begin{enumerate}
\item for every $\tau\in[0,T]$ and every representative $r^\tau\in \bigl(\hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}h\bigr)^\tau$, $\delta r^\tau = h^\tau$; 

\item in particular, for every $0\le s\le u\le t\le T$ and every representative $r^t\in \bigl(\hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}h\bigr)^t$, $(\delta r^t)_{tus}=h_{tus}$;  

\item for every $h\in Z\hat C^{\gamma}(\Delta^3_T;B_\alpha)$, the uniform estimate $\|\hat\Lambda_{S,\gamma,\alpha}^{\mathrm q}h\|_{\mathfrak Q_{\mathrm{fr}}^{\gamma,\alpha}}\le C_{\gamma, T} M_{\alpha,T}\|h\|_{\gamma,\alpha}$ holds.  
\end{enumerate}

[Proposition 23 (Posterior index-information accounting) of arXiv:2608.21709, 'Posterior Information Dynamics of Diffusion Models for Linear Inverse Problems'] For \(t>0\), the posterior responsibility of index \(i\) at a noisy state
\(X_t=x\) is
\begin{equation}

\Prob(I=i\mid x,r)
=
\frac{
w_i(r)\exp\{-\|x-a_tx_i\|^2/(2\Delta_t)\}
}{
\sum_j w_j(r)\exp\{-\|x-a_tx_j\|^2/(2\Delta_t)\}
}.
\end{equation}
Moreover,
\begin{equation}

h(X_t\mid r)
=
\frac d2\log(2\pi e\Delta_t)
+
H(I\mid r)
-
H(I\mid X_t,r).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 11 (Homotopy Transfer) of arXiv:2608.28200, '\textbf On the Formality of Configuration Spaces of $\aka$'] Given such an SDR datum, there exists an $A_\infty$-algebra structure $\{m_n\}_{n \ge 1}$ on $H^\bullet(A)$ uniquely determined by the CDGA structure of $A$ and the maps $(i, p, h)$. In particular:
\begin{itemize}
    \item $m_1 = 0$;
    \item $m_2(a, b) = p(i(a) \cdot i(b))$, which recovers the standard multiplication on $H^\bullet(A)$;
    \item For $n \ge 3$, the operations $m_n$ are defined via summation over planar rooted trees, where edges are decorated by the homotopy $h$ and vertices by the multiplication in $A$.
\end{itemize} 
Moreover, there exists an $A_\infty$ quasi-isomorphism between $H^*(A)$ and $A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma convolution of arXiv:2609.00425, 'Individual and Uniform Eventual Positivity of Self-Adjoint Semigroups'] Let $(d_j)_{j \in \mathbb{N}_0}$ be a sequence in $[1,\infty)$ and let $(\pi_j)_{j \in \mathbb{N}_0}$ be a sequence in $(0,\infty)$ such that the following assertions hold:
    \begin{enumerate}[\upshape (a)]
        \item $\displaystyle \sum_{j \in \mathbb{N}_0} \pi_j = 1$.
        \item $\kappa \coloneqq \displaystyle \sum_{j \in \mathbb{N}_0}d_j \pi_j < \infty$.
        \item $\displaystyle \sum_{j \in \mathbb{N}_0} d_j^2 \pi_j < \infty$.
    \end{enumerate}
    Consider the function
    \begin{align*}
        k \colon [0, \infty) \to \mathbb{R}, \quad k(t)\coloneqq \frac{1}{\kappa} \sum_{j \in \mathbb{N}_0} d_j^2 \pi_j \mathrm{e}^{- d_j t}.
    \end{align*}
    Then the convolution resolvent
    \begin{align*}
        \rho \colon [0, \infty) \to \mathbb{R}, \quad \rho\coloneqq\sum_{m=1}^{\infty}k^{\ast m}
    \end{align*}
    is well-defined and bounded on $[0,\infty)$.

