[Thm app_thm_invisibleHand of arXiv:2411.16464, 'Generating social networks with static and dynamic utility-maximization approaches'] For any $\mathcal{G}(\mathscr{I} , \alpha, C)$ with $\mathcal{C}$ the compatibility matrix defined as $\mathcal{C} = (c_{i,j})_{1\leq i,j\leq N}$ ($\mathcal{C}^{i}$ its ith-column), and $(\alpha^i)^*$ the solution vector of the Individual optimization problem (IOP) evaluated on $c^i$, the compatibility list derived from $\mathcal{C}_{i}$, if
\begin{enumerate}
\item $\exists \bar c \in \mathbb{R}^{N} \text{s.t. } \forall i \in \Iintv*{1, N }, \mathcal{C}^i \in \mathscr{S}(\bar c)$, with $\mathscr{S}(\bar c)$ the symmetric group of $\bar c$
\item there exists $(H,S)$ two functions satisfying conditions of Definition (app_def_utilityFunc of the paper) such that $\forall i \in \Iintv*{1, N }, (\mathscr{I})_i = (P_i, U_i), \forall j \in \Iintv*{1, N-1 }, \frac{\partial U_i}{\partial \alpha^i_j} = H(c_j^i, \alpha_j^i) + S(\alpha^i)$
\end{enumerate}
Then there exists $\hat \alpha  \in \mathbb{R}^{n_N}$ such that $\forall i \in \Iintv*{1, N }, (\alpha^i)^* \in \mathscr{S}(\hat \alpha)$. Moreover, $\alpha^{**}$ the solution of the associated SOP, verifies: $$\forall (i,j) \in \Iintv*{1, N }^2, \alpha^{**}_{i,j} = (\alpha^{\max{\{i,j\}}})^*_{\min{\{i,j\}}}$$

[Theorem 40 of arXiv:2512.00213, 'On strong sharp phase transition in the random connection model'] Assume that $\|d_\varphi\|_{1,1}>0$.  We have the following:
\begin{enumerate}
\item[{\rm (i)}] $t_T\ge \|d_\varphi\|_{\infty,1}^{-1}$.
        \item[{\rm (ii)}] For $t<t_T$ there exists $\delta_1:=\delta_1(t)$ 
such that $\esssup\limits_{p\in\BM}\BE_t e^{\delta_1 |V^{(0,p)}|}<\infty$.
        \item[{\rm (iii)}]  If 
        \begin{align*}
          \esssup\limits_{p\in\BM} \int_{\|x\|>u} \varphi(x,p,q) \, d x \, \BQ(d q)
        \end{align*}
        decays exponentially fast as $u\to\infty$, then for $t<t_T$ there exists $\delta_2:=\delta_2(t)$ such that 
        \begin{align*}
            \esssup\limits_{p\in\BM}\BE_t e^{\delta_2 D(V^{(0,p)})}<\infty.
        \end{align*}
       \item [{\rm (iv)}] Suppose $n\in\N$ satisfies \eqref{c:main}. Then $t_T=t_c\in(0,\infty)$ and 
$\bar{c}_{t_c}=\BE_{t_c}\int |V^{(0,p)}|\,\BQ(dp)=\infty$.
        \item[{\rm (v)}] Suppose $n\in\N$ satisfies \eqref{c:main}. Then
        \begin{align*}
        \|c(t)\|_r\ge \frac{t_c}{\Delta_n(t)(t_c-t)},
    \end{align*}
    for $t<t_c$ and for all $r\in[1,\infty]$. 
       \item[{\rm (vi)}] Suppose that $n\in\N$ satisfies \eqref{c:main} and let $\delta>0$.  
Then 
\begin{align*}
    \|\theta(t)\|_r \geq \left(\frac{\bar\theta(t_c)}{\delta}+\frac{\I\{\bar\theta(t_c)=0\}}{2t\Delta_n(t)}\right)(t-t_c),
\end{align*}
for all $t\in[t_c, t_c + \delta]$ and $r\in\left[1,\infty\right]$. 
\end{enumerate}

