[Lemma 27 of arXiv:2605.16868, '\ttl'] Under Assumption \ref{assumption:GNGop}, there exists some $K \in (0,\infty)$ such that
\begin{equation}

\frac{1}{N} \sum_{i=1}^N \E \sup_{0 \le t \le T} |\bar{Q}_i^N(t)-\breve{Q}_i^N(t)|\le K \frac{1}{N} \sum_{i=1}^N \E \sup_{0 \le t \le T} |\bar{X}_i^N(t)-\breve{X}_i^N(t)|.
\end{equation}

[Proposition 3 of arXiv:2604.04840, 'Bounding the Gap Between Zeros of the Variable-\\Parameter Confluent Hypergeometric Functi'] With $\text{Re}(b) > 0$ and $\xi \neq \eta$,

	\begin{equation}

		\begin{split}
			\int\limits_0^z t^{b-1}e^{-t} & \Phi(\xi,b,t)\Phi(\eta,b,t)dt \\ & = \frac{e^{-z}z^b}{b(\eta - \xi)} [\eta \Phi(\xi,b,z)\Phi(\eta + 1, b + 1, z) - \xi \Phi(\eta, b, z) \Phi(\xi + 1, b + 1, z)]
		\end{split}
	\end{equation}\\

	\noindent Given $\Phi(a,b,t)$ with $\text{Re}(b)>0$ and $k=b/2-a$,

	\begin{equation}

		\begin{split}
			\int\limits_0^z \left( \frac{k}{t} - \frac{1}{2} \right) & e^{-t} t^b \Phi^2(a,b,t) dt \\ & = z^{b+1} e^{-z} \left[ \left( \frac{2k - b + 1}{2z} \right) \Phi^2(a,b,z) + \left(\frac{a}{b}\right)^2 \Phi^2(a+1,b+1,z) \right] \\ & + z^b e^{-z} \frac{a}{b} (b-z-1) \Phi(a,b,z) \Phi(a+1,b+1,z)
		\end{split}
	\end{equation}

[Lemma 32 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] If $T_{\lfloor (\log n)^{\frac{3+2\varepsilon}{6}}\rfloor}-T_M=\sum_{m=M+1}^{\lfloor(\log n)^{\frac{3+2\varepsilon}{6}}\rfloor}\zeta_m\ge\tfrac{1}{3}\delta n$, then
