[Proposition 8 of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Let $\beta\le \beta_0$ and $h,D\in\R$. Let $U:\R\to\R$ be smooth, with derivatives of moderate growth. For a cavity field $l$ and $r=\langle l\rangle$, with Gaussian reference variance $p-q$, we have, for every positive integer $k$,
\begin{equation}
  \E\left[\frac{\langle U(l)W(\beta l+h)\rangle}{\langle W(\beta l+h)\rangle}
  -\frac{\E_\xi[U(\xi+r)W(\beta(\xi+r)+h)]}{\Wtil(\beta r+h)}\right]^{2k}\le \frac{K}{N^k}.
\end{equation}
Here $K$ is uniform over the system size and over $0<\beta\le\beta_0$, by the uniformity of \eqref{eq:known-overlap-estimate}.

[Corollary 21 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $T>0\in\mathbb C^{m\times m}$ and $t\in\mathbb R$ be such that $T^{-1}+tT>0$.
  $F$ and $\sigma$ are related by
     \begin{equation}

    \shabox{\mbox{$F(z)=T^{-1}+(T^{-1}+tT)^{1/2}\sigma(z)T^{-1/2}$}.}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 32 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] For each $R>0,$ one has
\[
{\cal S}_{{\rm eu}}(\mu)=\sup_{f\in C_{b}(\Sigma_{R})}\big\{\int_{\Sigma_{R}}fd\mu+\lambda_{0}^{{\rm eu};f,R}\big\}
\]
for any probability measure $\mu$ supported on $\Sigma_{R}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:generallift of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $P_t$ and $P_{t,O}$ be contraction $C_0$-semigroups on $\mathcal{H}$ and $\mathcal{H}_O$ with generators $\mathsf{L}$ and $\mathsf{L}_O$, respectively.

 $P_t$ is a second-order \emph{lifted semigroup} of $P_{t,O}$ if
    \begin{enumerate}[label=(\roman*)]
     \item 
        The domain relation holds
        \begin{align*}
            \dom(\mathsf{L}_O) \subset \dom(\mathsf{L})\,.
        \end{align*}








        \item   There holds, for any $x \in \mathcal{H}_O$, $y \in \dom(\mathsf{L}) \cap \mathcal{H}_O$, 
        \begin{align} 
            \langle x, \mathsf{L} y \rangle_{\mathcal{H}} = 0 \,. \tag{L1}
        \end{align}
        \item  There exists a positive  bounded operator $\mathsf{S}: \mathcal{H}_O^\perp \to  \mathcal{H}_O^\perp$ such that
        \begin{align} 
            \langle \mathsf{L} x,  \mathsf{S} \mathsf{L} y \rangle_{\mathcal{H}} = - \langle x, \mathsf{L}_O y \rangle_{\mathcal{H}_O}\,,\quad  \forall x \in \dom(\mathsf{L}) \cap \mathcal{H}_O,\, y \in \dom(\mathsf{L}_O)\,. \tag{L2}
        \end{align}
        \end{enumerate}
    In this case, we also say that $P_{t,O}$ is a \emph{collapsed semigroup} of $P_t$.

