[Lemma lem:wp:frozenLemma of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:lyapunov of the paper) with $\|\nabla W\|_{L^\infty} < \infty$. Let $\hat{\mu} \in \mathcal{P}_{\kappa, d, T}$ be a probability measure that satisfies the following integrability condition:\begin{equation}
    \int_0^T \bigg[\int_{(\ensuremath{\mathbb{R}}^d)^{1 + \kappa}} |\mathbf{x}|\hat{\mu}_t(d\mathbf{x})\bigg]dt < \infty.

\end{equation}
Then, given $b$ as defined in (equation eq:results:drift of the paper),   
there exists a progressively measurable function $\hat{\gamma}_{\hat{\mu}}:[0, T] \times \ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}^d$ such that
\begin{equation}
    \hat{\gamma}_{\hat{\mu}}(t, x, y) = \left\{ \begin{aligned}&\mathbb E^{\hat{\mu}}\big[ b(\mathbf{Y}(t)) \big| Y_0(t) = x, Y_1(t) = y\big], &\quad &\text{for }\hat{\mu}_t\text{-a.e. }x, y \in \ensuremath{\mathbb{R}}^d,  \\
    &\nabla U(x) &\quad &\text{otherwise}.
    \end{aligned}\right. \quad t \in [0, T].

\end{equation}
Moreover, there exists $C \in (0, \infty)$ such that
\begin{equation}
    \sup_{\hat{\mu} \in \mathcal{P}_{\kappa, d, T}}\bigg\{ \sup_{(t, x, y) \in [0, T] \times (\ensuremath{\mathbb{R}}^d)^2} \frac{|\hat{\gamma}_{\hat{\mu}}(t,  x, y)|}{1 + |x| + |y|} \bigg\}\leq C,

\end{equation}
and a unique in a law solution to the following SDE:\begin{equation}

                \begin{aligned}               d\hat{X}_0(t) &= - \bigg( \nabla U\big(\hat{X}_0(t)\big) + \sum_{v = 1}^\kappa \nabla W\big(\hat{X}_0(t) - \hat{X}_v(t)\big)\bigg) dt + \sqrt{2} dB_0(t), \\d\hat{X}_v(t) &= - \hat{\gamma}_{\hat{\mu}}\big(t, \hat{X}_v(t), \hat{X}_0(t)\big) dt + \sqrt{2} dB_v(t), \quad v \in \{1, \ldots, \kappa\},
                \end{aligned}
    \end{equation}
    with initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$.

