[Definition 4 (Volume-balanced sequences of functions) of arXiv:2604.22567, 'Sign-balance of random Laplace eigenfunctions'] Let $\Mcc$ be a smooth manifold, $f:\Mcc\rightarrow\R$ a real-valued measurable function, $u \in \R$ a (fixed) level, and recall that $H(\cdot)$ is the sign function \eqref{eq:H Heaviside}.

\begin{enumerate}[i.] 

\item For $x\in \Mcc$ and $0 < r < \inj(\Mcc)$, the \textit{volume-bias} of $f$ at level $u$, restricted to $B_{r}(x)$, is 
\begin{equation}

\Dc_{u}(x;r)=\Dc_{f;u}(x;r) := \frac{1}{|B_{r}(x)|}\int\limits_{B_{r}(x)} \left(H(f(y) - u) -  \tau(u)\right)  dy \in  [-2,2],
\end{equation}
with 
\begin{equation}

\tau(u):=1 - 2 \Phi(u)= \E[H(Z-u)],
\end{equation}
where $Z$ a standard Gaussian random variable and $\Phi$ is the Gaussian cdf. We denote
\begin{equation}

\widetilde{\Dc}_u(x;r)=\widetilde{\Dc}_{f;u}(x;r) := \frac{1}{|B_{r}(x)|}\int\limits_{B_{r}(x)} H(f(y) - u) dy \in  [-1,1],
\end{equation}
the uncentred variant of $\Dc_u(x;r)$.

\item Let $r_{j}\subseteq \R_{>0}$ be a sequence of positive numbers, and $f_{j}:\Mcc\rightarrow\R$ a sequence of measurable functions. The \textit{volume-imbalance} of $f_{j}$ at scale $r_{j}$ with respect to the level $u$ is
\begin{equation}

\Bc_u(f_{j};r_{j}):= \sup\limits_{\substack{x\in\Mcc}}|\Dc_u(x;r_{j})| \in [0,2].
\end{equation}
We say that the $f_{j}(\cdot)$ are \textit{volume-balanced} above the scale $r_{j}$ with respect to level $u$ if
\begin{equation}

\lim\limits_{j\rightarrow \infty} \sup_{r \ge r_j}  \Bc_u(f_{j};r) = 0.
\end{equation}
\end{enumerate}

