body:
[Teorema 12 (Double action of the transformation) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $ T=(\Phi, B, \eta, h)$ be a stochastic transformation. Consider  the solution $ X$ to $ SDE_{\mu,\sigma}$ driven by $ W$, with $ SDE_{\mu,\sigma}$ non-explosive and with respect to which $ h$ and $\eta$ are non-explosive, with $ X$ taking values in $ \tilde{M}$ and $ W$ being a Brownian motion in the probability space $ (\Omega, \mathcal{F}, \mathbb{P})$. Then, the transformed process $ P_T(X,W)=(P_T(X),P_T(W))$ is a solution to the transformed equation $E_T(SDE_{\mu,\sigma})=SDE_{E_T{(\mu)},E_T{(\sigma)}}$, with $ P_{T}(X)$ taking values in $ \tilde{M}'$ and $ P_{T}(W)$ being Brownian motion in the space $ ( \Omega, \mathcal{F'}, \mathbb{Q})$ and with
    \begin{equation*}
        P_{T}(X)= \Phi(\mathcal{H}_{\eta}(X,t)); \ \ \ \ \ \  P_{T}(W)= \mathcal{H}_{\eta}(W') 
    \end{equation*}
    \begin{equation*}
        dW'_t = \sqrt{\eta(t)}B(X_t,t)(dW_t - h(X_t,t) dt)
    \end{equation*}
    \begin{equation*} 
        \frac{d \mathbb{Q}}{d \mathbb{P}}_{| \mathcal{F}_t} = \exp \Big( \int_0^T \sum_{\alpha=1}^m h_\alpha(X_s,s) d W^\alpha_s - \frac{1}{2} \int_0^T \sum_{\alpha=1}^m (h_\alpha(X_s,s))^2 ds \Big)
    \end{equation*}
    \begin{equation*}
        \mathcal{F'}_t=\mathcal{F}_{f^{-1}(t)}.
    \end{equation*}
 \begin{equation*}
        E_{T}(\mu)= \Big( \frac{1}{\eta} [ L(\Phi) + D(\Phi) \sigma  h] \Big) \circ \Phi^{-1}; \ \ \ \ \ \ \
        E_{T}(\sigma)= \Big(\frac{1}{\sqrt{\eta}} D(\Phi)  \sigma B^{-1} \Big) \circ \Phi^{-1}.
    \end{equation*}

[Lemma part1 of arXiv:2606.15203, 'The existence of invariant sublinear expectations for $G\text{-}$SDEs'] Under the assumptions (\textbf{H1}) and \textbf{(H2)}, for any $\varphi \in B_b(\mathbb{R}^d)$, we have  
    \begin{equation}
   \nu(t,x) \coloneqq \underset{\theta \in  \mathcal{A}^{\Theta}_{t,T}}{{\rm sup}} E_P[\varphi(x+\int^T_t b(X_s^{t,x,\theta})ds+\int_t^T\theta_sdW_s)]  
 \end{equation}
  is continuous in $x$, for any $x \in \mathbb{R}^d
  $, $0 \leq t < T <\infty$.

