[Definition 7 of arXiv:2506.22085, '2506.22085'] Fix $T>0$ and a divergence free vector field $\bar J \in L^2(\bb
  T^d;\bb R^d)$
  \begin{itemize}
  \item[(HSPC)]The \emph{hydrodynamic Schr\"odinger problem with
      current constraint} is the optimization problem 
    \begin{equation*}
      \phi_T(\bar J) :=
      \frac 1T
      \inf \Big\{ I(\pi,\ms J),\; \frac 1T \ms J(\omega)
      = \int\!dx\, \bar J\cdot \omega,\; \omega \in\Omega_1\Big\}.
    \end{equation*}
   \item[(MSPC)]The \emph{measure Schr\"odinger problem with
      current constraint} is the optimization problem 
    \begin{equation*}
      \Phi_T(\bar J) :=
      \frac 1T
      \inf \Big\{ \mf F(R),\;
      \frac 1T\int\!R(dX) \,  \int_0^T\!\omega(X_t)\circ dX_t
      = \int\!dx\, \bar J\cdot \omega,\; \omega \in\Omega_1\Big\}.
    \end{equation*}   
  \end{itemize}

[Lemma 7 (Scaling and the gamma limit) of arXiv:2607.17630, 'Higher-Order Hankel Obstructions to Free Infinite Divisibility\ for Beta Distributions'] Let $c\mu$ denote the pushforward of $\mu$ under $x\mapsto cx$.  Then
\begin{equation}
 D_N(c\mu)=c^{(N+1)(N+2)}D_N(\mu).
\end{equation}
For fixed $p>0$ and $N\geq0$,
\begin{equation}
 \lim_{q\to\infty}q^{(N+1)(N+2)}D_N(\beta_{p,q})=D_N(\gamma_p),
\end{equation}
where $\gamma_p$ is the gamma distribution with shape $p$ and unit scale.
If $D_N(\gamma_p)<0$, then $\beta_{p,q}$ is not FID for all sufficiently
large $q$.

