[Lemma lem:DNOS-anti of arXiv:2606.19763, 'Optimal Sparsification of Gaussian Processes'] Suppose $T \sse \R^n$ is symmetric (that is, $t \in T$ if and only if $-t \in T$) and suppose $w(T) > 0$.  
	Then, for every $\eta>0$,
	\[
		\Prx_{\bg\sim N(0,I_n)}
		\sbra{
			\sup_{t\in T}\bg\cdot t \leq \eta\cdot  w(T)
		}
		\leq
		10\eta \,.
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2608.30602, '2608.30602'] Let $\lambda_0>0$ and $b\in \R$ be fixed, and assume that 
	$m(\lambda)= \mathcal{O}_{[b]+2}\big(\lambda^b\big)$ for 
	$\lambda\in (\lambda_0/2, \infty)$. Then, for every $k\in\mathbb{N}_0$ 
	and all $x\in\mathbb{R}$,
	\begin{equation}
		\left|\int_0^\infty e^{i\lambda x} m(\lambda) \tilde{\chi}(\lambda/\lambda_0) 
		\, d\lambda \right| \lesssim_{m,\lambda_0,k}
		\begin{cases}
			\dfrac{1}{\langle x\rangle^{k+1}|x|^{b+1}}, & \text{if } b \neq -1,\\[8pt]
			\dfrac{1}{\langle x\rangle^{k+1}\bigl(1+|\log |x||\bigr)}, & \text{if } b = -1,
		\end{cases}
	\end{equation}
	where the cut-off function $\tilde{\chi}$ is given in \eqref{cut-off-fun}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Suppose (\textbf{A1}) and (\textbf{A2}). Then, there exist $\alpha_{\mu_n}^{D^c}, \beta_{\mu_n}^{D^c}, \alpha_{\mu_n}^{D}$ and $\beta_{\mu_n}^{D}$,  
such that, almost surely, 
\begin{equation}

\E\left[ \sum\limits_{i=1}^{\tau_{n+1}} X_{\mu_{n} + i} \Big \vert \GG_n \right] =  \E[\alpha_{\mu_n}^{D^c} \vert \GG_n] \frac{S_{\mu_n}^{D^c}}{n} + \E[\beta_{\mu_n}^{D^c} \vert \GG_n], 
\end{equation}
and,
\begin{equation} 

\E\left[ \sum\limits_{i=1}^{\sigma_{n+1}} X_{\mu_{n} + \tau_{n+1} + i} \Big \vert \GG_n \right] =  \E[\alpha_{\mu_n}^{D} \vert \GG_n] \frac{S_{\mu_n}^{\sDD^c}}{n} + \E[\beta_{\mu_n}^{D} \vert \GG_n], 
\end{equation}
where
\begin{equation}

\E[\alpha_{\mu_n}^{D^c} \vert \GG_{n}] = (2p-1)\frac{\E[\tau]n}{\mu_n}+ \OO\left(\frac{1}{n}\right),\, \E[\beta_{\mu_n}^{D^c} \vert \GG_{n}] = (2\lambda-1)\frac{\E[\tau]|D_{\mu_n}|}{\mu_n} + \OO\left(\frac{1}{n}\right)
\end{equation}
and 
\begin{equation}

\E[\alpha_{\mu_n}^{D} \vert \GG_{n}] = (2p-1)\frac{\E[\sigma]n}{\mu_n} + \OO\left(\frac{1}{n}\right)\, \text{ and } 
\E[\beta_{\mu_n}^{D} \vert \GG_{n}] = (2\lambda-1)\frac{\E[\sigma]|D_{\mu_n}|}{\mu_n} + 
\OO\left(\frac{1}{n}\right),
\end{equation}
where the constant in $\OO \left(\frac{1}{n}\right)$ is uniform and deterministic almost surely. 

Furthermore, almost surely, 
 \begin{equation} 

 \lim_{n \to \infty} \E[\alpha_{\mu_n}^{D^c} \vert \GG_{n}]=(2p-1)\frac{\E[\tau]}{\mu}, \; \lim_{n \to \infty}\E[\beta_{\mu_n}^{D^c} \vert \GG_{n}]=(2\lambda-1)\frac{\E \left[\sigma \right]\E[\tau]}{\mu},  
 \end{equation} 
 and 
 \begin{equation}

 \lim_{n \to \infty}\E[\alpha_{\mu_n}^{D} \vert \GG_n]= (2p-1)\frac{\E[\sigma]}{\mu}, \;
 \lim_{n \to \infty} \E[\beta_{\mu_n}^{D} \vert \GG_{n}]= (2\lambda-1)\frac{\E^2[\sigma]}{\mu}.
\end{equation}

