[Lemma lem-compactnessLoop of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Suppose that Assumption (V) holds, then the following assertions hold.

\begin{enumerate}
\item For any $L\in(0,\infty)$ and for any $R\in \mathbb{N}$, the set $K_{R}^{\ssup {{\mathcal L }}}(L)$ is closed in the weak topology. 

\item 
\begin{equation}
\lim_{L\to \infty}\sup_{R\in\mathbb{N}}\limsup_{N\to\infty}\frac 1{|\Lambda_N|} \log \widehat{{\tt Q}}^{\ssup{\Lambda_{N},{\rm par}}}\Big(\Xi_{N,R}^{{{\scriptscriptstyle{({{\mathcal L }}})}}}\in \big(K_{R}^{{{\scriptscriptstyle{({\mathcal L }})}}}(L)\big)^{\rm  c}\Big)=-\infty.
\end{equation}

\item  For any $L\in(0,\infty)$ and for any $R\in \mathbb{N}$, the  map $\xi\mapsto \langle \xi,\widetilde{\mathfrak N}_{W}^{\ssup{\ell,{\mathcal L }}}\rangle $ is continuous on the set $K_{R}^{\ssup{{\mathcal L }}}(L)$.

\end{enumerate}

