[Definition eq:NormH of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] {Dix81}}]
A $\nu$-measur\-able vector field~$u$ is called ($\nu$-)\emph{square-integrable} if
\begin{align}
\left\lVertu\right\rVert\eqdef \braket{\int_Z \left\lVertu_\zeta\right\rVert_{\zeta}^2 \, \mathop{}\!\mathrm{d}\nu(\zeta)}^{1/2}<\infty\,\mathrm{.}
\end{align}

Two square-integrable vector fields~$u$,~$v$ are called ($\nu$-)\emph{equivalent} if~$\left\lVertu-v\right\rVert=0$. The space~$H$ of equivalence classes of square-integrable vector fields, endowed with the non-relabeled quotient norm~$\norm{{\,\cdot\,}}$, is a Hilbert space~[Dix81], called the \emph{direct integral of~$\zeta\mapsto H_\zeta$} (\emph{with underlying space~$S$}) and denoted by
\begin{align}
H=\dint[]{Z} H_\zeta \mathop{}\!\mathrm{d}\nu(\zeta) \,\mathrm{.}
\end{align}

[Thm surface sum representation in 't hooft limit of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] There exists a number $\upbeta_0(d)>0$, depending only on the dimension $d$, such that the following is true. Let $\Lambda_1\subseteq\Lambda_2\subseteq\hdots$ be any sequence of finite subsets of the lattice $\mathbb{Z}^d$ such that $\mathbb{Z}^d = \cup_{N=1}^{\infty}\Lambda_N$. If $|\upbeta|\leq \upbeta_0(d)$, then for any string $s=\{\ell_1,\dots,\ell_n\}$,
\begin{align*}
	\lim_{N\to\infty}\phi_{\Lambda_N,N,\upbeta}(s) =
	\prod_{i=1}^n\phi(\ell_i),
\end{align*}
where
\begin{equation*}
	\phi(\ell)=\sum_{K:\mathcal{P}_{\mathbb{Z}^d}\to\mathbb{N}} \phi^K(\ell), \quad\text{with}\quad \phi^K(\ell)=\sum_{M\in\mathcal{N}\mathcal{P}\mathcal{M}(\ell,K)}\upbeta^{\area(M)}w_{\infty}(M),
\end{equation*}
and the infinite sum $\phi(\ell)$ is only over finite plaquette assignments $K:\mathcal{P}_{\mathbb{Z}^d}\to\mathbb{N}$, i.e.\ plaquette assignments such that $\sum_{p\in\mathcal{P}_{\mathbb{Z}^d}}K(p)<\infty$. Moreover, the infinite sum $\phi(\ell)$ is absolutely convergent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 ({\citealp[Thm. 1) of arXiv:2608.24426, 'Sequential operator learning under dependent data'] {Pena2009article}}]

    Let $\vec{\rv}$ be a random vector in $\R^\anydim$ and $\paramcov$ be a positive-definite random matrix in $\R^{\locdim\times\anydim}$ such that:
    \begin{equation}
        \forall \anyvec \in \R^\locdim, \quad \Ex{\exp\left(\anyvec^\transpose \vec\rv - \fhalf\anyvec^\transpose \paramcov \anyvec\right)} \leq 1.
    \end{equation}
    Then, for any given fixed positive-definite matrix $\regmat$,
    \begin{align}
        &\Ex{
            \sqrt{\frac{\det\regmat}{\det(\paramcov + \regmat)}}
            \exp
            \left(
                \fhalf \vec\rv^\transpose (\paramcov + \regmat)^{-1} \vec\rv
            \right)
        }
        \leq 1,\\
        &\Ex{\exp\left(\frac{1}{4}\vec\rv^\transpose (\paramcov + \regmat)^{-1}\vec\rv\right)} \leq \sqrt{\Ex{\sqrt{\det(\eye + \regmat^{-1}\paramcov}}}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:on_Yn_Y-infty of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] \begin{itemize}
    \item [(a.)] For all $n$ sufficiently large but fixed, the process $\mathcal Y_n$ survives forever with positive probability. 
    \item [(b.)] The process $\mathcal Y_\infty$ also survives forever with positive probability.
    \item [(c.)] Moreover, denoting by $\chi_n$ the survival probability of $\mathcal Y_n$, we have
    \begin{align*}
        \lim_{n \to \infty} \chi_n=\chi,    \end{align*} where $\chi$ is the survival probability of $\mathcal Y_\infty$.
\end{itemize}

