[Lemm Lemm6.4 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Let $(Y_{i}^1, Z_{i}^1)$ and $(Y_{i}^2, Z_{i}^2)$ be two solutions to the scheme (equation linBTZ1 of the paper), respectively, such that $(G_i^1,\xi^1)$ and $(G_i^2,\xi^2)$ satisfy Assumption (assum56 of the paper). For $0\leq i\leq n$, let
				\begin{align*}
					\Upsilon_i:= \prod_{j=i}^{N-1}(1+\delta t_j\Gamma_j +\delta t_j\Pi_j \cdot {H}_j),
				\end{align*}
				where 
				\begin{align*}
					\Gamma_j:&= \frac{G_j^1(\mathbb{E}[{Y}_{j+1}^1/\mathfrak{F}_{t_j}],{Z}_j^{1})-G_j^1(\mathbb{E}[{Y}_{j+1}^{2}/\mathfrak{F}_{t_j}],{Z}_j^{1})}{\mathbb{E}[\delta{Y}_{j+1}/\mathfrak{F}_{t_j}]}{\bf 1}_{\{\mathbb{E}[\delta{Y}_{j+1}/\mathfrak{F}_{t_j}]\neq 0\}},\\
					\Pi_j:&= \frac{G_j^1(\mathbb{E}[{Y}_{j+1}^{2}/\mathfrak{F}_{t_j}],{Z}_j^{1})-G_j^1(\mathbb{E}[{Y}_{j+1}^{2}/\mathfrak{F}_{t_j}],{Z}_j^{2})}{|\delta{Z}_{j}|^2}\delta{Z}_{j}{\bf 1}_{\{\delta{Z}_{j}\neq 0\}}.
				\end{align*}
				Then the following representation holds
				\begin{align}
					\delta Y_i = \mathbb{E}\Big[\Upsilon_i\delta Y_{t_N} + \sum_{k=i}^{N-1}\delta t_k\delta G_k \frac{\Upsilon_i}{\Upsilon_k}\Big/\mathfrak{F}_{t_i}\Big].
				\end{align}
				Moreover, the following comparison principle holds true: $ Y_i^1\geq Y_i^2$,
				whenever $Y_N^1 \geq Y_N^2$ and $G_j^1(Y_i^2, Z_i^2)\geq G_j^2( Y_i^2, Z_i^2)$.

[Proposition prop:zero-potential-correction of arXiv:2607.03639, '\vspace{-0.6in}An AI-Assisted Solution to the Signed BAR Conjecture: Uniqueness in the Har'] Assume that the SRBM is a strong Markov process whose transition semigroup is Feller on $C_0(E)$, and that it has stationary probability $\pi_0$. Suppose that there are a locally bounded function $V:E\to[1,\infty)$ and constants $M,\kappa>0$ such that
\begin{equation}
 \|P_t(x,\cdot)-\pi_0\|_{\mathrm{TV}}
 \le M V(x)e^{-\kappa t},
 \qquad x\in E,\ t\ge0.
\end{equation}
Suppose also that
\begin{equation}
 c_i:=\sup_{x\in E}\mathbb E_xY_i(1)<\infty,
 \qquad i=1,\ldots,d.
\end{equation}
Let $\chi\in\mathcal M(E)$ satisfy $\chi(E)=0$ and $\int_E V\,d|\chi|<\infty,$ and let $\zeta_i\in\mathcal M(F_i)$ satisfy
\begin{equation}
 \sum_{i=1}^d\int_{F_i}D_i f\,d\zeta_i
 =\int_E f\,d\chi,
 \qquad f\in C_b^2(E).
\end{equation}
Define
\begin{align}
 \overline\pi&=\int_0^\infty \chi P_t\,dt,
                                                    \\
 \theta_i&=\sum_{n=0}^\infty(\chi P_n)K_i,
                                                    \\
 \overline\nu_i&=\theta_i+\zeta_i.              
\end{align}
Then all measures in (equation eq:ce-pi-potential of the paper)--(equation eq:ce-nu-corrected of the paper) are well defined in total variation and finite. They form a signed BAR tuple for all $f\in C_b^2(E)$, hence also for all $f\in C_c^2(E)$, and $\overline\pi(E)=0.$ If $\chi\ne0$, then $\overline\pi\ne0$.

