[Theorem 14 (Pathwise integration and weak change-of-variable formula) of arXiv:2608.07365, 'A pathwise Ito formula \\for weakly differentiable functions'] Let
$\omega\in C([0,T];\mathbb{R}^d)\cap Q_{\pi}([0,T];\mathbb{R}^d)$
satisfy \emph{(6)}, and let
$F\in\mathcal{W}_{\omega,\pi}^{2}$.
Let
$\{F_m\}_{m\geq 1}\subset C_b^2(\mathbb{R}^d)\cap
W^{2,1}(\mathbb{R}^d)$
be any sequence satisfying Definition~\ref{def:W-omega-pi}, namely

\begin{equation}
F_m(\omega(t))\longrightarrow F(\omega(t)),
\qquad t\in[0,T],

\end{equation}
\begin{equation}
\left\|
\nabla^2F_m-\nabla^2F
\right\|_{W_{\omega,\pi}^{0}}
\longrightarrow 0.

\end{equation}
For every $t\in[0,T]$, the limits
\begin{equation}
\lim_{m\to\infty}
\int_0^t
\nabla F_m(\omega(s))\,d^{\pi}\omega(s)

\end{equation}
\begin{equation}
{\rm and}\qquad [\nabla F(\omega),\omega]_{\pi}(t)
:=
\lim_{m\to\infty}
[\nabla F_m(\omega),\omega]_{\pi}(t)

\end{equation}
exist and are independent of the sequence $(F_m)_{m\geq 1}$ satisfying
\eqref{eq:pathwise-approximation-F} and
\eqref{eq:pathwise-approximation-Hessian}.
We  define the integral of $\nabla F(\omega)$ with
respect to $\omega$ along $\pi$ by
\begin{equation}
\int_0^t
\nabla F(\omega(s))\,d^{\pi}\omega(s)
:=
\lim_{m\to\infty}
\int_0^t
\nabla F_m(\omega(s))\,d^{\pi}\omega(s).

\end{equation}
This definition does not require the weak gradient $\nabla F$ to have a
finite pointwise representative at the partition points. Then
\begin{equation}
F(\omega(t))-F(\omega(0))
=
\int_0^t
\nabla F(\omega(s))\,d^{\pi}\omega(s)
+
\frac{1}{2}
[\nabla F(\omega),\omega]_{\pi}(t).

\end{equation}

[Theorem 2 of arXiv:2604.00474, 'Trap behaviors for Brownian motions'] Suppose that $w (\gamma, a) = exp(-a^{-\gamma})$. Then,
\begin{itemize}
\item For $\gamma < 2$, $\Omega_\mathsf{M}$ is not a trap domain for $X^+$;
\item For $\gamma \geq 2$, $\Omega_\mathsf{M}$ is  a trap domain for $X^+$.
\end{itemize}

