body:
[Lemma lem:Buse_global of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] Fix $s \in \mathbb{R}$. Then, on an $s$-dependent event of probability one, there exist continuous functions $C(x,s,t)$ defined for $t > s$ and $x \in \mathbb{R}$ and $a(s,t)$ defined for $t > s$ so that, for all $x,y \in \mathbb{R}$, $\xi \in \mathfrak{X}$, and $t > s$,
   \[
   L(x,s,t,\xi) 
       \le W^\xi(0,s;x,t) \le R(x,s,t,\xi),
   \] 
   where
    \begin{align*}
        L(x,s,t,\xi) &= -|\mathcal P(\xi)| - C(x,s,t)   \\
        & +  \begin{cases}
            (2\mathcal P(\xi) -a(s,t))x + (t-s)\left(\mathcal P(\xi) - \frac{a(s,t)}{2}\right)^2  &x + (t-s)\mathcal P(\xi) > \frac{a(s,t)}{2}(t-s) \\
            -\frac{x^2}{t-s} &|x + (t-s)\mathcal P(\xi)| \le \frac{a(s,t)}{2}(t-s) \\
            (2\mathcal P(\xi) + a(s,t))x + (t-s)\Bigl(\mathcal P(\xi) + \frac{a(s,t)}{2}\Bigr)^2 &x+ (t-s)\mathcal P(\xi) < -\frac{a(s,t)}{2}(t-s),
        \end{cases}
    \end{align*}
    and 
    \begin{align*}
     R(x,s,t,\xi) &= |\mathcal P(\xi)| + C(x,s,t) \\
     &+\begin{cases}
            (2\mathcal P(\xi) + a(s,t))x + t\left(\mathcal P(\xi) + \frac{a(s,t)}{2}\right)^2  &x + (t-s)\mathcal P(\xi) \ge 0 \\
            (2\mathcal P(\xi) - a(s,t))x + (t-s)\Bigl(\mathcal P(\xi) + \frac{a(s,t)}{2}\Bigr)^2 &x+ (t-s)\mathcal P(\xi) \le 0.
        \end{cases}
    \end{align*}

[Proposition 26 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] For any $\mu\in \eP(T)$,
\begin{align*}
\eF_\beta(X ; \mu)
 \le  \liminf_{\epsilon\downarrow 0} \liminf_{N \to \infty}
 \sup_{\nu\in \eP_\mu(T)}\set[\Bigg]{\frac{1}{N}\Ex{\Psi_{\beta}(\bm{X}^N; \cC_{N,\nu,\epsilon} )} 
   +  \frac{\langle\nu, \log \mu\rangle}{\beta}} .
\end{align*}
For $\mu \in \eP_+(T)$,
\begin{align*}
\eF_\beta(X ; \mu)
&\ge \limsup_{\epsilon\downarrow 0}\limsup_{N \to \infty} \sup_{\nu\in \eP(T)}
\set[\Bigg]{\frac{1}{N} \Ex{\Psi_\beta(\bm{X}^N ; \cC_{N, \nu, \epsilon})}
  + \frac{\langle \nu, \log \mu \rangle}{\beta} 
+ O(\epsilon)}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

