[Lemma 18 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] In the yellow region, on the common domain of convergence, we have
    \begin{align*}
        \hat{P}_{a,y,\theta}(z)
        &=\begin{cases}
           \frac{E\left(\theta,\frac{-\theta zy}{a+1}\right)}{E\left(\theta,\frac{za}{\theta(a+1)}\right)-z\cdot\frac{ \theta +a}{\theta(a+1)}E\left(\theta,\frac{za}{a+1}\right)},~~&~-a\leq y \leq \frac{-a}{\theta},
            \\\frac{E\left(\theta,\frac{za}{a+1}\right)}{E\left(\theta,\frac{za}{\theta(a+1)}\right)-z\cdot\frac{\theta +a}{\theta(a+1)}E\left(\theta,\frac{za}{a+1}\right)},~~&~\frac{-a}{\theta}<y\leq1.
        \end{cases}    
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 (Statistical guarantees for the posterior) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under \cref{ass:sequence_model,ass:dy_prior}, the exact posterior satisfies
    \begin{equation}
    \E\sbr{\Wp^2(\Pi_t,\delta_{\theta^\star})}
    \lesssim  t^{-(\zeta-1)/\zeta}
    \end{equation}
and
    \begin{equation}
    \fR\del[1]{(\Pi_t)_{t=0}^{T-1}}
    \lesssim T^{1/\zeta}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main:1 of arXiv:2509.06730, 'Hyperbolic branching Brownian motion: \\ the empirical limit measure'] The Hausdorff dimension of $\mu_\infty$ is almost surely given by
    \begin{equation*}
        \dim \mu_\infty = \begin{cases}
            2\beta \quad & \text{for} \quad 0 < \beta < 1/2, \\
            1 & \text{for} \quad \beta \geq 1/2. 
        \end{cases}
    \end{equation*}
    Consequently, $\dim \mu_\infty \neq \dim \Lambda$ for $\beta<1/2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

