[Lemma lem:agreement of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] Let $f_1, f_2:\mathbb{N}_0^{\mathbb{Z}^d\times\mathbb{R}_+}\to\mathbb{R}$ be functions with support in $B^1$ and $B^2$ respectively. Define
  \begin{equation}
    \hat f_1 = f_1\bigl(\hat\eta^L\bigr), \qquad \hat f_2 = f_2\bigl(\hat\eta^R\bigr),
  \end{equation}
  where $f_1(\hat\eta^L)$ means $f_1$ evaluated on the trajectory $\hat\eta^L$ extended by zero
  outside $V_1$, and similarly for $f_2$.

  Then, on the event $\mathcal{S}$,
  \begin{equation}
    f_1(\eta) = \hat f_1 \quad\text{and}\quad f_2(\eta) = \hat f_2.
  \end{equation}

