[Proposition 33 (Inequalities at level $p^\dagger$) of arXiv:2606.13648, 'Stochastic dominations for FK percolation and sharp thinning thresholds for the Ising ener'] Take $J \in (\R^+)^E$ and $p^\dagger=p^\dagger(J)=1-e^{-4J}$. Then \begin{itemize}
\item \emph{(Almost dual weak FKG)}
For any $F,F'\subseteq E$ \begin{align}
\edag_J(\A_F\cap\A_{F'})\ge \edag_J(\A_F)\edag_J(\A_{F'}).
\end{align}

\item \emph{(Almost dual weak domination)} For any $J'\ge J$ and $F\subset E$, we have
\begin{equation}
\en_{J, p^\dagger}(\A_F)\ge\en_{J',p^\dagger}(\A_F).
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

