 a^{(d-1)/2}U_C(k)-\one_{\{k\in\mathcal L_*\}}
\phi^{\perp,*}_{m,\Gamma}\left(\frac{k-am}{\sqrt a}\right)
\right|
\xrightarrow[a\to\infty]{}0.
\end{equation}

