body:
[Prop eq:SL0_OP of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$, ${\kappa}_i  >  -1$ for $1 \le i \le d_2$, let ${\alpha} = d_1-1$ and 
${\boldsymbol{\epsilon}} = (0,\ldots,0,1) \in {\mathbb R}^{d_2}$. Define 

\begin{equation} 
 {\mathsf Q}_{\bm j, \ell, m}^n(\bm x,\bm y) = \hat {\bm L}_{\bm j, n-m}^{{\boldsymbol{\kappa}}+ ({\alpha}+2m){\boldsymbol{\epsilon}}}(\bm y) |\bm y|^m 
      {\mathsf Y}_{\ell}^m \left(\frac{\bm x}{|\bm y|}\right). 
\end{equation}
Then $\{{\mathsf Q}_{\bm j, \ell, m}^n: |\bm j| = n-m, \, 1 \le \ell \le \dim {\mathcal H}_m^{d_1}, \, 0 \le m  \le n, \bm j \in {\mathbb N}_0^{d_2}\}$ 
is an orthogonal basis of ${\mathcal V}_n({\mathbb S}^{d_1-1}\!\! \rtimes {\mathbb R}_\Sigma^{d_2}, {\mathsf W}_{{\boldsymbol{\kappa}}}^L)$. Moreover, 
the norm square of ${\mathsf Q}_{\bm j, \ell, m}^n$ is given by 
\begin{equation} 
   {\mathsf h}_{m,n}^{{\boldsymbol{\kappa}}}  
       =   \frac{{\mathsf b}^L_{{\boldsymbol{\kappa}}+ \alpha{\boldsymbol{\epsilon}}}}{{\mathsf b}^L_{{\boldsymbol{\kappa}}+(\alpha + 2m) {\boldsymbol{\epsilon}}}} \bm h_{\bm j,m}^{{\boldsymbol{\kappa}}+({\alpha}+ 2m){\boldsymbol{\epsilon}}, L}
       =  ({\kappa}_{d_2} +d_1)_{2m}  \bm h_{\bm j,m}^{{\boldsymbol{\kappa}}+({\alpha}+ 2m){\boldsymbol{\epsilon}}, L}.  
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

