body:
[Corollary 10 (Hermite polynomials and differential operators) of arXiv:2605.14630, '2605.14630'] The Hermite polynomials are eigenfunctions of $\cL$. More precisely,
\begin{equation}

 (\cL H_n)(x) = -n H_n(x) 
 \qquad 
 \forall n\geqs 0\;.
\end{equation} 
Furthermore, one has 
\begin{equation}

 a^\dagger H_{n-1} = H_n\;, 
 \qquad 
 a H_n = n H_{n-1}
 \qquad 
 \forall n\geqs 1\;.
\end{equation}

[Proposition NA1-NA2-Y-reflexive of arXiv:2609.00794, 'On operators whose adjoints or second adjoints attain their norms'] Let $X$ and $Y$ be Banach spaces. Then 
\begin{equation*}
    \operatorname{QNA} (X, Y) \cap \mathcal{W}(X,Y)  = {\operatorname{NA}_1 (X, Y) \cap \mathcal{W}(X,Y)  = \operatorname{NA}_2 (X,Y) \cap \mathcal{W}(X,Y).}
\end{equation*}
In particular, if $Y$ is reflexive, then $\operatorname{QNA}(X,Y)=\operatorname{NA}_1(X,Y) = \operatorname{NA}_2(X,Y)$.

[Lemma lem:gaussian-domination of arXiv:2601.05798, '{I}mry-{M}a phenomenon for the hard-core model on $\mathbb{Z}^{2}$'] Fix $\lambda>0$.
	For all $ t \ge 0 $, we have that
	\begin{equation}
		\liminf_{j \uparrow \infty}
		\mathbb{E}\left[
			\exp\left( \frac{t F_{\Lambda_j,\lambda}(X)}{ \sqrt{|\Lambda_j|}}\right)
			\right]
		\ge
		\exp(t^2 b^2/2),
	\end{equation}
	where
	\begin{equation}
		b^2
		\ge
		\frac{1}{2} \mathbb{E}[\mathbb{E}[F_{\Lambda_j,\lambda}(X) \mid X_{\mathsf{o}}]^2]
		+
		\frac{1}{2} \mathbb{E}[\mathbb{E}[F_{\Lambda_j,\lambda}(X) \mid X_{\mathsf{o}'}]^2].
	\end{equation}
	for $\mathsf{o}=(0,0), \mathsf{o}'=(0,1)$ and for and any $j \ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 (Cluster-sum expansion at the square) of arXiv:2609.02784, 'Maximizing the fundamental Laplace--Neumann \\ eigenvalue on quadrilaterals'] For every $\e \in S^3$ we have $\tr\bigl(\widetilde B_1|_{V_0}\bigr) = 0$ and, as $t \to 0$,
\begin{equation}
\frac{1}{\lambda_1(t\e)} + \frac{1}{\lambda_2(t\e)}
\;=\; \frac{2}{\pi^2} \;+\; \bigl(\Pi_0(\e) + \Sigma_\perp(\e)\bigr)\, t^2 \;+\; O(t^3),
\end{equation}
where
\begin{align*}
\pi^6\, \Pi_0(\e) &:= \tr\bigl((\widetilde K_1|_{V_0})^2\bigr) \;-\; \pi^2\, \tr\bigl(\widetilde K_1|_{V_0}\, \widetilde M_1|_{V_0}\bigr) \;-\; \pi^2\, \tr\bigl(\widetilde K_2|_{V_0}\bigr) \;+\; \pi^4\, \tr\bigl(\widetilde M_2|_{V_0}\bigr), \\
\pi^6\, \Sigma_\perp(\e) &:= \sum_{k \in V_0} \sum_{m \in V_0^\perp} \frac{\pi^2}{\kappa_m - \pi^2}\, \bigl(\widetilde B_1\bigr)_{k, m}^2 \;\;\ge\;\; 0,
\end{align*}
and the remainder in \eqref{e:cluster-sum} is uniform for $\e \in S^3$.

[Definition def_conditional_convergence_in_probability of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] We say that the sequence of random variables $(X_{n})_{n\ge 1} $ converges to the random variable $X_{0}$ in probability, conditionally on the event $\mathcal H $ with positive probability, 
	if $X_{n} \longrightarrow  X_{0} $ in $\Prob^{\mathcal H}$-probability.
	We denote this convergence with
	\begin{equation}
		X_{n} \convergence{\Prob^{\mathcal H}} X_{0}.
	\end{equation}

[Lemma thm:equivs for Schervish of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] The following are equivalent:
		\begin{enumerate}
		\item Schervish form: for $v\in\set{0,1}$ and any $x\in[0,1]$, 
		\begin{align}
		&			\mathsf{acc}_v(v)-\mathsf{acc}_v(x)=\int_{x}^{v}{v-t}\;\;\lambda(\dd{t}).&&\text{(eq:Scherv of the paper)}\nonumber
		\end{align}
		\item For all $x,y\in[0,1]$, (i.e., replacing $v\in\set{0,1}$ by a general $y\in[0,1]$)
				\begin{align}
						&			\mathsf{acc}_v(y)-\mathsf{acc}_v(x)=\int_{x}^{y}{v-t}\;\;\lambda(\dd{t}).
				\end{align}
		\item For all $x,p\in[0,1]$,
				\begin{align}
				&\mathrm{Exp}_p\mathsf{acc}(p)-\mathrm{Exp}_p\mathsf{acc}(x)=\int_x^p (p-t)\;\lambda(\dd{t})
				\end{align}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 9 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(\mcalG\) be a flat affine group scheme over an fpqc algebraic stack \(\mcalX\). A morphism \(f\colon\mcalY\to\mcalX\) of stacks is called a \emph{\(B\mcalG\)-torsor} if there exists a representable fpqc cover \(U\to\mcalX\) by a scheme and an equivalence
  \begin{equation*}
    \mcalY\times_{\mcalX}U\simeq B_U\mcalG_U
  \end{equation*}
  of stacks over \(U\), where \(\mcalG_U\defeq\mcalG\times_{\mcalX}U\). We use the expression \(B\mcalG\)-torsor only in this sense.

[Lemma 25 (Proposition 4.1 in \cite{DLV}) of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] There exists a.s.~finite random time $\mathfrak{t}<\infty$ such that 
\begin{align}
    |\mathfrak{p}(t)-\sqrt{t}|\le t^{-1/4}\log t,\qquad \text{ for all $t\ge \mathfrak{t}$.}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 (Oriented-cut duality and the Hilbert fixed point) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $m\ge1$, $1<r<\infty$, and $r'=r/(r-1)$.  The coefficient pairing,
which is linear in its first variable, induces conjugate-linear isometric
isomorphisms
\begin{equation}

 \begin{aligned}
  \CutCoeff_{m,r'}&\longrightarrow(\CutCoeff_{m,r})^*,
  &L&\longmapsto\bigl[K\longmapsto\ip{K}{L}\bigr],\\
  \Coeff_{m,r'}&\longrightarrow(\Coeff_{m,r})^*,
  &L&\longmapsto\bigl[K\longmapsto\ip{K}{L}\bigr].
 \end{aligned}
\end{equation}
Every coefficient space in this range is reflexive.  In particular, the
quotient-sum and intersection branches are conjugate, while
\begin{equation}

 \CutCoeff_{m,2}=\mathscr K_m,
 \qquad
 \Coeff_{m,2}
 =\cH^{\odot m}\otimes\conj{\cC}\otimes\cE
\end{equation}
are Hilbert spaces with their kernel norms and are conjugate-self-dual
under the same pairing. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 26 of arXiv:2608.11695, 'Generalised stochastic curvature flow in $d \geq 2$, and sharp interface limit for the sto'] Suppose $Y \in \cC_{x,loc}^2$ and $Y' \in \cC_{x,loc}^1$, and
    \begin{equation*}
        (Y(t;x),Y'(t;x))\in\lL_{x,loc}^\infty\dD_W^{2\alpha}\;, \qquad (Z(t),Z'(t))\in\dD_W^{2\alpha}\;.
    \end{equation*}
    Then we have
    \begin{equation*}
        \left(Y(t;Z(t)),Y'(t;Z(t)) + \nabla^\sft Y(t;Z(t))Z'(t)\right)\in\dD_W^{2\alpha}\;.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2509.21253, '\bf Capacity in high dimensional percolation'] \rm{
			For $r>0$ we define the number of pioneer points $X_r$ as follows

			\[
			X_r=\left|\left\{x\in \partial \ball{0}{r}: 0\stackrel{ \ball{0}{r}}{\longleftrightarrow}   x    \right\}  \right|=|\mathcal C(0;B(0,r))\cap \partial B(0,r)|.	
			\]	
			For $x\in \partial \ball{0}{r}$ we define global and local density conditions. For $s>0$ we write
			\begin{align*}
				\mathcal{T}_s(x) = & \{ |\mathcal{C}(x;\ball{0}{r})\cap \ball{x}{s}
				| \leq s^4 (\log s)^7\} \\ &\cap \{|\mathcal{C}(x;\ball{0}{r})\cap \ball{x}{s}\cap \partial \ball{0}{r} |\leq s^2 (\log s)^7  \}.
			\end{align*}
			We now define a local density condition as follows
			\begin{align*}
				\mathcal{T}_s^\textrm{loc}(x) =&\bigcap_{y\in \ball{x}{s}} \{|\mathcal{C}(y; \ball{x}{s^d}\cap \ball{0}{r})\cap \ball{x}{s}|\leq s^4 (\log s)^4\} \\
				&\bigcap \bigcap_{y\in \ball{x}{s}\cap \partial \ball{0}{r}} \{|\mathcal{C}(y;\ball{x}{s^d}\cap \ball{0}{r}) \cap \ball{x}{s}\cap \partial \ball{0}{r}|\leq s^2 (\log s)^4 \} \\
				&\bigcap \{ \exists \ \text{ at most }  (\log s)^3 \text{ disjoint paths from }\ball{x}{s} \text{ to } \partial \ball{x}{s^d} \text{ in } \ball{0}{r} \}.
			\end{align*}
		}

[Theorem th1 of arXiv:2411.17104, 'Two-barriers-reflected BSDE with Rank-based Data'] With assumptions (\textbf{A1})-(\textbf{A3}), there is a unique quadruplet $(Y^{t,x}(\cdot),Z^{t,x}(\cdot),K^{t,x,+}(\cdot),K^{t,x,-}(\cdot))$ satisfies the properties:
\begin{enumerate}[(i)]
\setlength{\parsep}{0ex} 
\setlength{\itemsep}{0ex}
\item $Y^{t,x}(\cdot)\in S^{2}([t,T];\mathbb{R})$ and $Z^{t,x}(\cdot)\in M^{2}([t,T];\mathbb{R}^{n})$;
\item $(Y^{t,x}(\cdot),Z^{t,x}(\cdot),K^{t,x,+}(\cdot),K^{t,x,-}(\cdot))$ satisfies $(equation 3.1 of the paper)$;
\item $L(r)\leq Y^{t,x}(r) \leq U(r)$,\;$r \in [t,T]$;
\item $\int_{t}^{T}\big[Y^{t,x}(r)-L(r)\big]dK^{t,x,+}(r)=\int_{t}^{T}\big[ U(r)-Y^{t,x}(r)\big]dK^{t,x,-}(r)=0$.
\end{enumerate}

