[Theorem thm:legendre of arXiv:2607.29330, 'Large deviations for the maximum of\\ the generalized TAP free energy'] Fix a regular \(f\in(f_{\mathrm{eq}},f_1)\). Let \(\theta_f\in(0,1)\) be the
		unique minimizer defining \(\Sigma(f)\), let \(\zeta_f\) be the
		corresponding constrained Parisi minimizer, and let \(q_f\) be its first
		positive contact point. Let \(X^f\) be the Auffinger--Chen process
		associated with \(\zeta_f\). Assume the strict Plefka condition
		\begin{equation}
			1-\xi''(q_f)\mathbb{E}\left[
			\left(
			\partial_{xx}\Phi_{\zeta_f}(q_f,X^f_{q_f})
			\right)^2
			\right]>0.
		\end{equation}
		Then
		\begin{equation}
			\begin{aligned}
				\lim_{\varepsilon\downarrow0}\liminf_{N\to\infty}
				\frac1N\log\mathbb{P}\bigl(\mathcal E_{N,\varepsilon}(f)\bigr)
				&=
				\lim_{\varepsilon\downarrow0}\limsup_{N\to\infty}
				\frac1N\log\mathbb{P}\bigl(\mathcal E_{N,\varepsilon}(f)\bigr)\\
				&=
				\Sigma(f)
				=
				\inf_{\theta\in(0,1)}
				\bigl[\Lambda(\theta)-\theta f\bigr].
			\end{aligned}
		\end{equation}
		Moreover,
		\begin{equation}
			\lim_{N\to\infty}
			\frac1N
			\log
			\mathbb{E}\exp\left\{
			\theta_f\max_{\mathbf{m}\in[-1,1]^N}F_{\mathrm{TAP}}(\mathbf{m})
			\right\}
			=
			\Lambda(\theta_f).
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:parallel of arXiv:2609.02820, 'Sharpness and critical scaling of parking'] Let $U_n(x)$ be the number of steps taken from $x$ during the first $n$
	rounds. Then $U_0=0$, and for every $n\geq0$ and every $x\in\mathbb{Z}^d$,
	\begin{equation}
		U_{n+1}(x)=\Bigl(\eta(x)+\sum_yI_{y,x}(U_n(y))\Bigr)^{\!+}\,.
	\end{equation}

[Proposition 19 of arXiv:2608.24352, 'Second moments associated with finite free multiplicative convolution'] Let ${\sf K}_1$ and ${\sf K}_2$ be two partitions in $D(I,J)$, of types $t(\sK_1) =(2^{y_1}, 1^{k+l-2y_1})$ and $t(\sK_2) = (2^{y_2}, 1^{k+l-2y_2})$. Then
	\begin{align*}
		y_1  + |{\sf I}^{\times}_{\sK_2} ({\sK_1})| = y_2 + |{\sf I}^{\times}_{\sK_1} ({\sK}_2)|.
	\end{align*}
	In particular,
	\begin{align*}
		\frac{1}{2}(y_1+y_2+{\sf S}({\sf K}_1, {\sf K}_2)) = y_1 + |{\sf I}^{\times}_{\sf K_2} ({\sf K_1})| = y_2 + |{\sf I}^{\times}_{\sf K_1} ({\sf K}_2)|.
	\end{align*}

