[Lemma 10 of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Let $M_k = \begin{bmatrix}
        M_{k-1},m_k
    \end{bmatrix} \in \R^{m\times k}$ 
 be a matrix $\in \R^{m \times k}$, where $M_{k-1} \in \R^{m \times (k-1)}$ has full rank, $m_k \in \R^m $ and $k \geq m$.  
 \begin{equation}
     \Tr\Big(M_{k-1}^{\dagger}(M_{k-1}{^{\dagger}})^T\Big) \geq \Tr\Big(M_k^{\dagger}(M_k{^{\dagger}})^T\Big) 
 \end{equation}
and 
\begin{equation}
 \Big(M_{k-1}^{\dagger}(M_{k-1}{^{\dagger}})^T\Big)_{ii} \geq \Big(M_k^{\dagger}(M_k{^{\dagger}})^T \Big)_{ii}   
\end{equation}
$\forall i \in [k-1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 34 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] There are constants $C = C(\alpha, d, \sup_{t\in[0, t_1]}\|\rho_t^\mu\|_{\m C^{1,\alpha}}, L_\rho)$ and $C' = C'(\alpha, d, \sup_{t\in[0, t_1]}\|\rho_t^\mu\|_{\m C^{2,\alpha}}, L_\rho)$, such that
\begin{align}
\matnorm{JT^\mu(x) - I_d}_{\rm op} &\leq Ct_1\sup_{0\leq t\leq t_1}\|\partial_t \rho_t^\mu\|_{\m C^{0,\alpha}},\\
\sum_{k=1}^d \Big\|\frac{\partial JT^\mu(x)}{\partial x_k}\Big\|_{\rm F}^2 &\leq  C't_1^2 \sup_{0\leq t\leq t_1}\|\partial_t\rho_t^\mu\|_{\m C^{1,\alpha}}^2.
\end{align}
\myqed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 38 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] Let~$(\xi,\eta)\in \mathcal F_R\subset(-1,1)^2$ and assume~$x$ and~$y$ are as in~\eqref{eq:global_coordinates_1xell}. Furthermore, let~$i=0,1\dots,\ell-1$, and~$\eps=0,1$. Then
\begin{equation*}
\left(\cT(2(\ell x+i)+\eps,2 y+\eps),\cO(2(\ell x+i)+\eps,2 y+\eps)\right)\to \left(\mathcal Z(\Omega(\xi,\eta)),\vartheta(\Omega(\xi,\eta))\right)
\end{equation*}
as~$N\to \infty$. Moreover, the convergence is uniform on compact subsets of~$\mathcal F_R$.

