[Theo thm:Feller of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] Let $\mathbb{X}$ be a (not necessarily transient) standard process. Suppose that for some $\alpha>0$, $\mu$ is $G_\alpha$-Kato, $G_\alpha(\cdot,y), y\in X$ is l.s.c and let $F$ be the fine support of $\mu$. Assume that $F$ is closed. Then
\begin{enumerate}
 \item[\rm(1)] The semigroup  $\check{T}_t$ maps $C_0(F)$ into itself and $\check{T}_t: C_0(F)\to C_0(F)$ has Feller property.
 \item[\rm(2)] The resolvent  $V_\alpha$ maps $C_0(F)$ into itself and $V_\alpha: C_0(F)\to C_0(F)$ has Feller property.
 \end{enumerate}

[Theorem thm:FPI of arXiv:2607.10801, 'Relaxation times of non-reversible\\ Markov processes'] If  (equation eq:A1 of the paper), (equation eq:B2 of the paper) and (equation eq:C2 of the paper) are satisfied, then
    \begin{equation*}
        \norm{\overline P_tf} \ \leq \ \max\biggl(\frac{2}{m_2},\frac{1+2C_2^2}{\gamma^2}\biggr)^{1/2}\norm{\mathcal{L}\overline P_tf} \ + \ \frac{4\gamma}{t}\max\biggl(\frac{2}{m_2},\frac{1+2C_2^2}{\gamma^2}\biggr)\norm{f-P_tf}
    \end{equation*}
    for all $f\in L_0^2(\mu)$ and $t>0$. In particular,
    \begin{equation*}
        \overline t_\mathrm{rel}(P)\ \leq \  16e\max\left(\frac{2\gamma}{m_2},\frac{1+2C_2^2}{\gamma}\right)\,,\text{ and }\
        s(\mathcal{L} )\ \ge \ \frac{1-e^{-1}}{8e}\min\left(\frac{m_2}{2\gamma},\frac{\gamma}{1+2C_2^2}\right)\, .
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 18 of arXiv:2605.30779, '2605.30779'] Let $l \geq 0$ and $\Theta = (\theta_1, \dots, \theta_l)$. For every \(\varepsilon>0\), there exists a random variable \(\mathcal J' =\mathcal J'(\varepsilon)\) such that almost surely,
\begin{equation} 
\left|
a_j^{\Theta}
+\left(\frac{3\pi j}{2}\right)^{2/3}
\right|
\le j^\varepsilon,
\qquad j>\mathcal J'.
\end{equation}

[Lemma 8 of arXiv:2604.12317, 'Weak solution for distribution dependent SDEs driven by L\'{e}vy noise'] Let $\theta\in[1,\alpha),$ and $\delta_{0}$  be the Dirac measure at point $0.$ If $b(t,0,\delta_0)$ is bounded in $t\in \R_{+},$ and there exists a increasing function  $K(t)\in C([0,\infty);(0,\infty)),$ such that
\begin{equation}
        |b(t,x,\mu)-b(t,y,\nu)|\leq K(t)[|x-y|+W_{\theta}(\mu,\nu)],\quad\forall x,y\in \R^d,\mu,\nu\in \mathscr{P}_{\theta},t>0.
    \end{equation}
    Then for any $X_0$ with $\E[|X_0|^{\theta}]<\infty,$ DDSDE \eqref{EQ:MVSDE:101} has a unique strong solution $(X_t)_{t\geq 0 }.$

