[Definition 12 of arXiv:2605.16072, 'Stochastic integration \\with respect to a L\'evy basis'] Let $\big(\Omega, \mathcal{F}\!,P,(\mathcal{F}_k)_{k\in{\mathbb N}_0}\big)$ be
	a filtered probability space and $(X_k)_{k \in \mathbb{N}}$ an adapted sequence of real-valued random variables. If $\big(\Omega', \mathcal{F}',P',(\mathcal{F}'_k)_{k\in{\mathbb N}_0}\big)$ is another filtered probability space, then a sequence $(Y_k)_{k \in \mathbb{N}}$ of real-valued random variables defined on $\big(\Omega \times \Omega^\prime, \mathcal{F}\otimes \mathcal{F}', P \otimes P', (\mathcal{F}_k\otimes \mathcal{F}'_k)_{k\in{\mathbb N}_0}\big)$ is said to be a decoupled tangent sequence to $(X_k)_{k \in \mathbb{N}}$ if
	\begin{enumerate}
		\item[{\rm (a)}]     $(Y_k(\omega,\cdot))_{k \in \mathbb{N}}$ is a sequence of independent random variables on $(\Omega',\mathcal{F}',P')$ for each $\omega \in \Omega$;
		\item[{\rm (b)}]  the sequences $(X_k)_{k \in \mathbb{N}}$ and $(Y_k)_{k \in \mathbb{N}}$ satisfy for each $k\in {\mathbb N}$ that
		\[\mathcal{L}(X_k \vert \mathcal{F}_{k-1}\otimes \mathcal{F}'_{k-1})=\mathcal{L}(Y_k \vert \mathcal{F}_{k-1}\otimes \mathcal{F}'_{k-1}) \quad P \otimes P'\!-\!\text{almost surely. }\]
	\end{enumerate}

[Proposition 9 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item There exists a unique holomorphic function $\Pi:\C^+\to\C^{L\times L}$ such that, for every $z\in\C^+$, $\Om(\Pi(z),z)=0$, $\Im\Pi(z)>0$, and $\Im(z^{-1}\Pi_{11}(z))>0$.
                \item Define $\wt T(z):=z^{-1}\Pi_{11}(z)$ and $T(z):=\Pi_{22}(z)$. There exist unique positive semidefinite matrix-valued measures $V_1$ and $V_2$ on $[0,\infty)$, with values in $\C^{M\times M}$ and $\C^{N\times N}$, respectively, such that $V_1([0,\infty))=I_M$, $V_2([0,\infty))=I_N$, and
                      \begin{align}
                              \wt T(z)=\int_{[0,\infty)}\frac{V_1(\dd\la)}{\la-z},\qquad T(z)=\int_{[0,\infty)}\frac{V_2(\dd\la)}{\la-z}. \nonumber
                      \end{align}
                      Moreover, there exists a constant $C_*<\infty$ such that $\supp V_1\cup\supp V_2\subset[0,C_*]$.
                \item Let $\bnu_1:=\avg{V_1}_M$ and $\bnu_2:=\avg{V_2}_N$. Then $\bnu_1$ and $\bnu_2$ are compactly supported probability measures on $[0,\infty)$ and, with $\wt m(z):=\avg{\wt T(z)}_M$ and $m(z):=\avg{T(z)}_N$,
                      \begin{align}
                              \wt m(z)=\int_{[0,\infty)}\frac{\bnu_1(\dd\la)}{\la-z},\qquad m(z)=\int_{[0,\infty)}\frac{\bnu_2(\dd\la)}{\la-z}. \nonumber
                      \end{align}
                      Moreover,
                      \begin{align}
                              g(z)=-\avg{\Sg}_N+\int_{[0,\infty)}\frac{\la\avg{\Sg V_1(\dd\la)}_N}{\la-z}. \nonumber
                      \end{align}
                \item Writing $\bnu:=\bnu_2$, we have $\sup\supp\bnu\sim1$. Moreover, the mass at the origin is
                      \begin{align}
                              \bnu(\{0\})=\left(1-\frac{M}{N}\right)\mb 1\left(\frac{M}{N}\leq1\right). 
                      \end{align}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

