[Lemma 21 (switching identity) of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, $D\subset \widetilde{\mathbb{Z}}^d$, $v\neq w\in \widetilde{\mathbb{Z}}^d\setminus D$, and $a,b>0$, conditioned on $\big\{ v\xleftrightarrow{} w,  \widehat{\mathcal{L}}_{1/2}^{D,v}=a, \widehat{\mathcal{L}}_{1/2}^{D,w}=b  \big\}$, the occupation field $\big\{ \widehat{\mathcal{L}}_{1/2}^{D,z} \big\}_{z\in \widetilde{\mathbb{Z}}^d}$ has the same distribution as the total local time of the following four independent components:
 	 \begin{itemize}
 	 	\item[(1)] loops in the loop soup $\widetilde{\mathcal{L}}_{1/2}^{D\cup \{v,w\}}$; 


 	 	\item[(2)] a Poisson point process with intensity measure $a\cdot \mathbf{e}_{v,v}^{ D\cup  \{w\}}$; 


 	 	\item[(3)] a Poisson point process with intensity measure $b \cdot \mathbf{e}_{w,w}^{ D\cup  \{v\}}$; 


 	 	\item[(4)] a Poisson point process with intensity measure $\sqrt{ab} \cdot \mathbf{e}_{v,w}^D$, where the number of excursions is conditioned to be odd.


 	 \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 ({\cite[Proposition 2.1.1) of arXiv:2608.27054, 'GLOBAL WELL-POSEDNESS FOR THE 2D STOCHASTIC HYPOVISCOUS NAVIER-STOKES EQUATIONS'] {Ta00}}]
    Let $s\geq 0$ and $q\in(1,\infty)$ be such that 
    \begin{equation*}
        \frac{1}{q} = \frac{1}{q_1}+\frac{1}{q_2}= \frac{1}{\tilde{q}_1}+\frac{1}{\tilde{q}_2},\quad q_2, \tilde{q}_2\in (1,\infty),\, q_1,\tilde{q}_1\in (1,\infty].
    \end{equation*}
    Then
    \begin{equation*}
        \| fg \|_{H^{s,q}(\T^d)}\lesssim \|f\|_{L^{q_1}(\T^d)}\|g\|_{H^{s,q_2}(\T^d)} + \|g\|_{L^{\tilde{q}_1}(\T^d)}\|f\|_{H^{s, \tilde{q}_2}(\T^d)}, 
    \end{equation*}
    for $f\in L^{q_1}(\T^d)\cap H^{s, \tilde{q}_2}(\T^d)$ and $ g\in L^{\tilde{q}_1}(\T^d) \cap H^{s,q_2}(\T^d)$, where the constant is independent of $f$ and $g$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] Let \(p\ge 2\) and \(\gamma\in(\frac{1}{2},H)\). Under \textbf{H1}--\textbf{H3}. Then for all \(\epsilon\in(0,1]\),
\begin{eqnarray}
\mathbb{E}[\|x^\epsilon\|^p_{\gamma}] \le C_{x_0,T}, \quad \mathbb{E}[\|\bar x\|^p_{\gamma}] \le C_{x_0,T}
\end{eqnarray} 
where \(C_{x_0,T}>0\) only depends on \(x_0\) and \(T\). (Proof in the paper; no proof environment follows the statement in the TeX.)

