body:
[Theorem e:erlocal of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] For the GFF, as $T \to \infty$,
\begin{equation}

\sup_{x \in B(T)} \Big| \frac{\mathbb{E}[ \tilde{f}_T(x)  ] }{ \sqrt{2m(d-\alpha)\log T}}  - h_T(x)  \Big| \to 0 
\end{equation}
(recall that in this case $h_T|_{B(T)} = 1$ and $\alpha = d-2$). Moreover,
\begin{equation}

\tilde{f}_T - \mathbb{E}[\tilde{f}_T] \ \Rightarrow  \   f  \quad \text{ in law.} 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 2 of arXiv:2605.05986, '\bf Convergence rate of the occupation measure of { classes of ergodic processes toward th'] Let $\nu\!\in {\cal P}(\R^d)$ and let $\nu_t(\omega, dx))_{t>0}$ be a ${\cal P}(\R^d)$-valued family of random distributions  defined  on a probability space $(\Omega, {\cal A}, \P)$.
Let $p\!\in (0, +\infty)$  and let $q>p$. Let $\tzero >0$, $\beta,\gamma\!\in (0, \frac 12]$, $K_{\tzero,\b}\!\in (0,+\infty)$ and, for every $t\ge \tzero$,  let  {$\pi=(\proba_t)_{t\ge \tzero}$ be probability distributions such that the following assumption holds true}

\begin{equation}
\AUNgamma\left\{\begin{array}{ll} (i)&\forall\, t\ge \tzero, \; \forall\, A \!\in {\cal B}or(\R^d),\; \E\, \big| \nu_t(A)-\nu(A)\big| \le K_{\tzero,\b}\min \bigg(\proba_t(A), \frac{\proba_t(A)^{\b}}{t^\gamma}\bigg)\\
(ii) & {\Mpiq}:= {1\vee}\sup_{t\ge t_0}  {M_{\proba_t}(q))}<+\infty.
\end{array}\right.
\end{equation}

Then,  there exists a real constant $K_{\b,p,d,\tzero,\gamma}$ such that,  for every $t\ge \tzero$, 
\begin{equation}
\E\, {\cal W}_p^p\big(\nu_t, \nu) \le K_{\b,p,d,\tzero,\gamma}{2^q} {\Mpiq}\sum_{n\ge 0} 2^{pn} \sum_{\ell\ge 0} 2^{-p\ell} \min\bigg( 2^{-nq} ,\frac{2^{-nq\b}}{t^\gamma} 2^{d\ell(1-\b)}  \bigg).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

