body:
[Proposition prop:unknown-class-prior:auc-mse of arXiv:2609.02304, 'Bayes-Optimal BER and AUC: \\Estimation and Evaluation of Estimators'] The mean squared error of
  $\widehat{\mathrm{AUC}^*}(\thetahat)$
  is
  \begin{equation}
    \E{
      \paren{
        \widehat{\mathrm{AUC}^*}(\thetahat) 
        -
        \mathrm{AUC}^*
      }^{2}
    }
    \leq
    \frac{C}{\theta (1 - \theta) n}
    \text{,}
  \end{equation}
  where $C > 0$ is a constant that does not depend on $\theta$ or $n$.
  Therefore
  $\widehat{\mathrm{AUC}^*}(\thetahat)$
  is asymptotically unbiased.

[Proposition prop:est of arXiv:2512.17736, 'Pathwise uniqueness by noise for singular stochastic PDEs'] Assume (H0 of the paper), (H1 of the paper), (H2_0 of the paper)--(H6_0 of the paper) and, for every $n\in\mathbb N_+$ and $k\in\{1,\ldots,n\}$,
let $u_{n,k}$ be the solution to the Kolmogorov equation (equation eq:kolm of the paper) as given by Proposition~(prop:kolm of the paper). Then, the following statements hold.
\begin{itemize}
\item 
For all $\gamma\in[0,\beta]$, there exist constants $\mathfrak C_1, \mathfrak C_2>0$,
depending only on the data $\beta,\gamma,\delta,\theta,B$, such that, for every $\bar c$ satisfying (equation c of the paper)--(equation c' of the paper), for every $n\in\mathbb N_+$ and $k\in\{1,\ldots,n\}$, it holds
\begin{align}

\|u_{n,k}\|_{C^0_b(H_n)} &\leq \mathfrak C_1        \|g\|_{C^\theta_b(H)}\,,\\ 

\|A_n^\gamma Du_{n,k}\|_{C^0_b(H_n; H_n)}&\leq \frac{\mathfrak C_2}{(\bar c\lambda_k)^{\frac{1+\theta}2
-\gamma-(1-\theta)\delta}}\|g\|_{C^\theta_b(H)}\,.
\end{align}
\item If in addition $(1-\theta)\delta<\frac\theta2$, then 
for all $\gamma\in[-\delta, \frac\theta2-\delta(2-\theta))$,
there exists a constant $\mathfrak C_3>0$,
depending only on the data $\beta,\gamma,\delta,\theta,B$, such that, for every $\bar c$ satisfying (equation c of the paper)--(equation c' of the paper),
for every $n\in\mathbb N_+$ and $k\in\{1,\ldots,n\}$, it holds \begin{align}

\|D(A_n^{\gamma}Du_{n,k})\|_{C^0_b(H_n; {\mathscr L}(H_n))}
\leq \frac{\mathfrak C_3}
{(\bar c\lambda_k)^{\frac{\theta}{2}-\gamma-\delta(2-\theta)}}
\|g\|_{C^\theta_b(H)}\,.
\end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

