body:
[Definition 1 (Homogeneous $p$-variation norm) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\geq 1$. For any path $\mathbf{x}:[0,T]\rightarrow G^{\lfloor p\rfloor}(\mathbb{R}^k)$,
    \begin{equation*}
        [0,T]\ni t\mapsto \mathbf{x}_t := \left(1,\mathbf{x}^{(1)}_t,\dots,\mathbf{x}^{(\lfloor p\rfloor)}_t\right) \in G^{\lfloor p\rfloor}(\mathbb{R}^k),
    \end{equation*}
    the homogeneous $p$-variation norm of $\mathbf{x}$ is defined as
    \begin{equation*}
        \lVert \mathbf{x}\rVert_{\textup{hom $p$-var};[0,T]} := \sup_{D} \left(\sum_{i=0}^{n-1} d_{cc}(\mathbf{x}_{t_i},\mathbf{x}_{t_{i+1}})^p\right)^{1/p},
    \end{equation*}
    where $D=D_{[0,T]}$ is a partition of the time interval $[0,T]$. Then, for any $\mathbf{x},\mathbf{y}:[0,T]\rightarrow G^{\lfloor p\rfloor}(\mathbb{R}^k)$, the homogenous $p$-variation distance between $\mathbf{x}$ and $\mathbf{y}$ is defined as
    \begin{equation*}
        d_{\textup{hom $p$-var};[0,T]}(\mathbf{x},\mathbf{y}) := \sup_{D} \left(\sum_{i=0}^{n-1} d_{cc}(\mathbf{x}_{t_i,t_{i+1}},\mathbf{y}_{t_i,t_{i+1}})^p\right)^{1/p},
    \end{equation*}
    where $\mathbf{x}_{t_i,t_{i+1}}:=\mathbf{x}_{t_i}^{-1}\bullet \mathbf{x}_{t_{i+1}}$.

[Theo main result of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Assume~(hyp: pseudo lsc density of the paper),~(hyp: pseudo uniformity of the paper),~(hyp: null border of the paper) and~(hyp: getting fast to classes of the paper). Then, 
	$(L_n)$ satisfies the weak LDP with rate function $I$ satisfying 
	\begin{enumerate}
		\item if $\mu\notin \mathcal A$, then \begin{equation}
			I(\mu)=\infty;
		\end{equation}
		\item if $\mu_1,\mu_2\in \mathcal A$ and $\lambda\in [0,1]$ are such that $\lambda\mu_1+(1-\lambda)\mu_2\in \mathcal A$, then
		\begin{equation}

			I(\lambda\mu_1+(1-\lambda)\mu_2)\leqslant \lambda I(\mu_1)+(1-\lambda)I(\mu_2);
		\end{equation} 
		\item if $\mu_1,\mu_2\in \mathcal A$ are such that $\lambda\mu_1+(1-\lambda)\mu_2\in \mathcal A$ for some $\lambda\in [0,1]$ and if no class $C_j$ satisfies $\mu_1(C_j)\mu_2(C_j)>0$, then
		\begin{equation}

			I(\lambda\mu_1+(1-\lambda)\mu_2)= \lambda I(\mu_1)+(1-\lambda)I(\mu_2).
		\end{equation} 
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:sup_by_stoch_Gronwall of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Let $p\in(0,1)$ and $T>0$. There exists $c_p>0$ such that the unique solution $M^\nu_t$ of (equation eq:SPDE_viscous of the paper) starting from $M_0 \in \dot H^{-s}$ satisfies
 	\begin{align}
 		\begin{split}
 		&\sup_{\nu \in (0,1]} \Biggl(\sup_{t\in[0,T]} \mathbb{E} \|M^\nu_t\|^2_{\dot H^{-s}}
 		+2\nu \mathbb{E} \int_0^T \|M^\nu_r\|^2_{\dot H^{-s+1}}\,\mathrm{d} r\\
 		&\qquad\qquad+\eta_{d,s,\alpha} \mathbb{E} \int_0^T \|M^\nu_r\|^2_{\dot H^{-s-\alpha+1}}\,\mathrm{d} r \Biggr) \leqslant \|M_0\|^2_{\dot{H}^{-s}}e^{\rho_{d,s,\alpha}T},
 		\end{split}
 	\end{align}
    and
 	\begin{equation}
 		 \sup_{\nu \in (0,1]}\mathbb{E} \left(\sup_{t\in[0,T]} \|M^\nu_t\|^{2p}_{\dot H^{-s}}\right)
 		\leqslant c_p \|M_0\|^{2p}_{\dot{H}^{-s}}  e^{p\rho_{d,s,\alpha}T}.
 	\end{equation}

