[Defn def:1.1 of arXiv:2606.16237, 'The Backward Stochastic Partial Differential Integral Equations: Solvability and Compariso'] A triple process $(u,q,r)\in S_{\mathbb{F}}^2(0,T;H)\cap M_{\mathbb{F}}^2(0,T;V)\times M_\mathbb{F}^2(0,T;H)\times{M}_\mathscr{P}^{\nu,2}([0,T]\times Z;H)$ is called a solution of BSEE (equation eq:a2 of the paper) if for any $\eta\in V$ and all $t\in[0,T]$, it holds that
\begin{eqnarray*}
(u(t),\eta)_H &=& (\varphi,\eta)_H + \int_t^T \Big[ \langle A(s)u(s),\eta\rangle + \langle f(s,u(s),q(s),r(s,\cdot)),\eta\rangle \nonumber\\
&& + (g(s,u(s),q(s),r(s,\cdot)),\eta)_H \Big]ds - \int_t^T (q(s), \eta)_H dW_s \nonumber\\
&& - \int_t^T \int_Z (r(s,e),\eta)_H \tilde{\mu}(de,ds)\ \ \ \text{a.s.}
\end{eqnarray*}

[Definition 4 of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] Let $\beta$ be a function in $L^2([-1,1],\di\mu)$ and define
$$ g_\beta(\ell) = \int_{-1}^1 \beta(u) G_{\ell,d}(u) \di \mu(u) \,. $$
We say that $\beta$ is $Q$-admissible if
\begin{equation}
\sum_{\ell_1, \dots, \ell_Q\in \N} \prod_{i=1}^Q  |g_\beta(\ell_i)| n_{\ell_i}  \int_{-1}^1 G_{\ell_1}(u) \dotsb  G_{\ell_Q} \di \mu(u)<\infty \,.
\end{equation}

Under this condition, we define $Z_Q(\beta)\in L^2(\Omega)$ as follows
\begin{equation}

    Z_Q(\beta)
:=
\sum_{\substack{e_1, \dots, e_Q\in E \\ e_i = (\ell_i, m_i)}}
\prod_{i=1}^Q
\sqrt{|g_\beta(\ell_i)|}  \mathcal{G}_q(e_1,\dots,e_Q)
:\zeta_{e_1} \dotsb \zeta_{e_Q}: \,.
\end{equation}
