[Lemma of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] suppose that $f,g\in L^1(\R^d, \C)$ are Fourier-smooth with exponents $p,q\in[-d,\infty)$. Then $f\ast g$ is Fourier-smooth with exponent $d+p+q$.
    \begin{proof}
        Let $c$ be the joint constant such that~(equation e: fourier smooth 12 of the paper) holds for $f,g$ with their respective constants.
        Then the first part of the Fourier-smoothness of $f\ast g$ is obtained by
        \begin{equation*}
            |\widehat{(f\ast g)}(k)| = |\hat{f}(k)\hat{g}(k)| \leq c^2\frac{1}{(1+\|k\|)^\frac{d+(d+p+q)}{2}},\quad k\in\R^d. 
        \end{equation*}
        The second part follows from
        \begin{align*}
            \int_{B_2^c} \sup_{s\in B_1} |\widehat{(f\ast g)}(r(k+s))|^2\, dk &\leq \int_{B_2^c} \sup_{s\in B_1} |\hat{f}(r(k+s))|^2|\hat{g}(r(k+s))|^2\, dk\nonumber\\
            &\leq c\int_{B_2^c} \frac{\sup_{s\in B_1} |\hat{f}(r(k+s))|^2}{(1+r(\|k\|-1))^{d+q}}\, dk\nonumber\\
            &\leq cr^{-(d+q)}\int_{B_2^c} \sup_{s\in B_1} |\hat{f}(r(k+s))|^2\, dk\nonumber\\
            &= O(r^{-(d+d+p+q)})
        \end{align*}
        as $r\to\infty$.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Upper on-diagonal heat kernel bound) of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Let $d \geq 3$ and suppose that Assumption~\ref{a2-2} holds.

  \begin{enumerate}[(i)]
  \item
    Suppose there exist $m_{0} > d$ and $p \in \bigl(\max\{1,\frac{d}{m_{0}-2}\}, \infty\bigr]$, $q \in (1, \infty]$ satisfying \eqref{a1-1-2} such that

    \begin{align}
      \sup_{R \geq 1} \Norm{\theta}{p, B(R)}
      \,+\,
      \sup_{R \geq 1} \Norm{\mu_{m_{0}}}{p, B(R)}
      \,+\,
      \sup_{R \geq 1} \Norm{\nu}{q, B(R)}
      \;<\;
      \infty.
    \end{align}

    Then there exists $C_{3} \in (0, \infty)$ such that for every $t > 0$,

    \begin{align}
      p(t,o,o)
      \;\leq\;
      C_{3}\,  R_{0}^{(1/p + 1/q) m_{0}\gamma/(2\beta)}\, R_{1}^{m_{0}/\beta} 
      \cM_{0}^{(1 + m_{0}\gamma)/\beta}\,
      \biggl(
        1 + \frac{\mu_{m_{0}}(o)}{\theta(o)}
      \biggr)\, t^{-d/2},
    \end{align}

    where $R_{0}, R_{1} \geq 1$ are as in Assumption~\ref{a2-2} (for some $d' = d'(d, p, q) > d$),

    \begin{align}
      \cM_{0}
      \;\ldef\;
      \sup_{R \geq 1}\Bigl(
        \Bigl(
          \Norm{1 \vee \mu_{m_{0}}}{p, B(R)}
          \,+\, \Norm{1 \vee \theta}{p, B(R)}
        \Bigr) \cdot \Norm{1 \vee \nu}{q, B(R)}
      \Bigr),
    \end{align}

    and $\alpha, \beta, \gamma \in (0,1)$ are the same constants as in Lemma~\ref{l2-1} below associated with $m = m_{0}$.

  \item
    In the nearest neighbour case, that is when $W(x, y) \neq 0$ only if $x \sim y$, suppose there exist $p, q \in (1, \infty]$ satisfying \eqref{a1-1-2} such that the integrability condition \eqref{a1-4-1} holds (note that $\mu_{m_{0}}(x)=\mu(x)$ for any $m_{0}$ in the nearest neighbour case). Then, for every $m_{0} > d$,

    \begin{align}
      p(t,o,o)
      \;\leq\;
      C_{3} \,
      R_{0}^{(1/p + 1/q) m_{0}\gamma/(2\beta)}\, R_{1}^{m_{0}/\beta}\,
      \cM_{0}^{(1 + m_{0}\gamma)/\beta}\,
      \biggl(
        1 + \frac{\mu(o)}{\theta(o)}
      \biggr)\, t^{-d/2}.
    \end{align}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:ME_density of arXiv:2604.08889, 'Matrix Representations for Scale Functions of Spectrally Negative Lévy Processes with Rati'] A distribution on $(0,\infty)$ is called \emph{matrix-exponential} (ME) if its density can be written as
\begin{equation}
f(x) = \bm{\alpha} \mathrm{e}^{\bm{T}x} \bm{t}, \qquad x > 0,
\end{equation}
where $\bm{\alpha}$ is a $1 \times p$ row vector, $\bm{T}$ is an $p \times p$ matrix, $\bm{t}$ is an $p \times 1$ column vector, and $p\in \mathbb{N}$. 
The triplet $(\bm{\alpha}, \bm{T}, \bm{t})$ is called a \emph{matrix-exponential representation} of order $p$.

[Lemma 9 of arXiv:2604.01748, 'Largest-loop-first loop-erased random walk on $\mathbb{Z}^{4}$'] Let $d=4$. For any $\epsilon \in (0, 1)$,  there exist $C = C_{\epsilon} > 0$ and $N = N_{\epsilon} \ge 1$ depending on $\epsilon$ such that for all $n \ge N$, we have
\begin{equation}
    P \Big( \big| L_{n} - n \phi (n) \big| \ge \epsilon n \phi (n) \Big) \le C (\log n )^{-\frac{1}{2}} \log \log n.
\end{equation}

