body:
[Definition 2 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $\Gamma : [0,T]\to \ccM([0,T], \C^d)$, and let $X$ be a $d$-dimensional path-dependent process.
    We say that the pair $(\Gamma,X)$ is \emph{semimartingale differentiable} if the process
    \begin{equation*}
        \bigl(\Gamma(t)\cdot X_{[0,t]}\bigr)_{0\leq t\leq T}
    \end{equation*}
    is a continuous semimartingale and admits a representation of the form
    \begin{equation}
        \Gamma(t)\cdot X_{[0,t]} = \Gamma(0)\cdot X_{[0,0]} - \int_0^t B\bigl(s,X_{[0,s]}\bigr)\,ds + \int_0^t C(s)\,dX(s),
    \end{equation}
    where $B\colon \ccC_T^d\to \C$ is an affine non-anticipative functional and $C\colon [0,T]\to \C^d$ deterministic.
    We call $B$ and $C$ the coefficients of the semimartingale differentiability of the pair $(\Gamma,X)$.

[Theorem 50 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Let  $(\Omega,\FF,\mu)$ be a measure space and $(f_n)_{n\in \mathbb{N}}$ be a sequence in $\FF/\mathcal{B}_{[-\infty,\infty]}$. 
\begin{enumerate}[(i)]
	\item Suppose for some $g\in \FF/\mathcal{B}_{[0,\infty]}$ with $\mu[g]<\infty$, $f_n^-\leq g$ for all $n\in \mathbb{N}$. Then we have as follows.
	\begin{enumerate}[(a)]
		\item Lower semi-continuity (Fatou[{}'s lemma]): $\mu[(\liminf_{n\to\infty}f_n)^-]<\infty$ and 
\begin{equation}		
		\int \liminf_{n\to\infty}f_n\dd \mu\leq \liminf_{n\to\infty}\int f_n\dd\mu.
		\end{equation}
		\item Monotone convergence (Levi): If  $f_n\leq f_{n+1}$ for all $n\in \mathbb{N}$, then $\mu[(\lim_{n\to\infty}f_n)^-]<\infty$ and 
		\begin{equation}
		\int \lim_{n\to\infty}f_n\dd \mu= \uparrow\!\!\text{-}\!\!\lim_{n\to\infty}\int f_n\dd\mu.
		\end{equation}
	\end{enumerate}
\item Dominated convergence (Lebesgue): If there is a $\mu$-integrable $g\in \FF/\mathcal{B}_{[0,\infty]}$ with $\vert f_n\vert\leq g$ for all $n\in \mathbb{N}$ and if $\lim_{n\to\infty}f_n$ exists (everywhere), then one has  $\mu[\vert \lim_{m\to\infty}f_m\vert]<\infty$ and $\lim_{n\to\infty}\int \vert f_n-\lim_{m\to\infty}f_m\vert \dd\mu=0$ and (hence)
\begin{equation}
\int \lim_{n\to\infty}f_n\dd \mu= \lim_{n\to\infty}\int f_n\dd\mu.
\end{equation}
	\end{enumerate}
	All the integrals appearing above are well-defined. $\blacktriangle$ (Proof in the paper; no proof environment follows the statement in the TeX.)

