			&\int_{t}^{t+T}(\|\nabla \rho (s)\|_{L^2}^2+\|\nabla \sigma (s)\|_{L^2}^2+\frac{1}{\varepsilon}\|\nabla \rho (s)\|_{L^3}^3)ds\notag\\& \leq \frac{1}{2D}(2\|\sigma(t_0)\|_{L^2}^2+2\|\overline {\sigma}\|_{L^2}^2+\|\rho(t_0)\|_{L^2}^2)Te^{-2CDt},
		\end{align}
		for all $t \geq 0$, $T>0$. 
