body:
[Proposition 125 (Fixed-order sharpness of the uniform $(p,r)$-growth) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $K_{\boldsymbol 1,N}$ be the equal-weight diagonal kernel from
Definition~\ref{def:equal-weight-diagonal}.
Realize its chaos operator with either standard real Gaussian families or
standard circular complex Gaussian families, and let $g$ denote a
one-dimensional standard Gaussian of the chosen type.  For every
$2\le r<\infty$,
\begin{equation}

  \lim_{N\to\infty}
  \frac{\|\cT_{K_{\boldsymbol 1,N}}^{(m)}\|_{L^2(\Omega;\Sch_r)}}
       {\Prof_{m,r}(K_{\boldsymbol 1,N})}
  =\|g\|_{L^r}^m
  \asymp_m r^{m/2}.
\end{equation}
Let
\[
  K_{\mathrm{rk1}}
  :=1\in\C^{\otimes m}\otimes\conj{\C}\otimes\C.
\]
Then, for every $p\ge2$ and $2\le r<\infty$,
\begin{equation}

  \frac{\|\cT_{K_{\mathrm{rk1}}}^{(m)}\|_{L^p(\Omega;\Sch_r)}}
       {\Prof_{m,r}(K_{\mathrm{rk1}})}
  =\|g\|_{L^p}^m
  \asymp_m p^{m/2}.
\end{equation}
Consequently, in either fixed Gaussian model, if a function $B_m(p,r)$
satisfies
\[
  \|\cT_K^{(m)}\|_{L^p(\Omega;\Sch_r)}
  \le B_m(p,r)\,\Prof_{m,r}(K)
\]
uniformly over all finite dimensions and all nonzero coefficient kernels in
that model, then
\begin{equation}

  B_m(p,r)\ge c_m(p+r)^{m/2},
  \qquad p\ge2,\quad 2\le r<\infty.
\end{equation}
Thus, for each fixed $m$, the best constant uniform over all finite
dimensions and coefficient kernels has two-parameter order
$(p+r)^{m/2}$, up to constants depending only on $m$.  The diagonal argument alone does not determine those comparison constants
as $m$ varies; their all-order scale was determined in
Subsection~\ref{subsec:chaos-order-growth}.

[Cor 39 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] Assume $\mv>\lv$. There exists $c>0$ such that
\beqq
	\frac{1}{\tP}
	\sum_{\substack{n_1,n_2\ge1\\(n_1,n_2)\ne(1,1)}}
	\frac{|\QQ_{2,L}^{(n_1,n_2)}|}{(n_1!n_2!)^2}
	=O(e^{-cL}).
\eeqq

[Definition def: ConditionD1 of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Fix a prime $p$.
    Then, a $\widehat{R}$-module $\sM$ is said to satisfy \emph{condition $\cD_p^{1}$} if it holds for every monic $\beta(x) \in \bbZ[x]$ with irreducible reduction in $\bbF_p[x]$ that $\widehat{\sM}_{p,\beta} \de \sM\otimes_{\widehat{R}} R_{p,\beta}$ satisfies
        \begin{equation}
              \widehat{\sM}_{p,\beta}/p\widehat{\sM}_{p,\beta} \cong 0 \qquad \textnormal{or} \qquad  \widehat{\sM}_{p,\beta}/p\widehat{\sM}_{p,\beta}  \cong   \bbF_p[x] /\beta(x)\bbF_p[x].
        \end{equation}

[Lemma lem:cesaro of arXiv:2601.10624, 'Source localisation in simple random walks'] Suppose $(c_n)$ is a bounded sequence satisfying
    \begin{equation}
        \sup_{i \in [n/2,n]}|c_n - c_i| \xrightarrow[]{n\to\infty} 0. 
    \end{equation}
    Then
    \begin{equation*}
        \liminf_{n\to\infty} c_n \geqslant \liminf_{n\to\infty}{\frac{1}{n} \sum_{i=1}^n c_i}.
    \end{equation*}

