[Theorem thm:density of arXiv:2607.14266, 'The Swapping Mechanism for Interacting Diffusions: Framework, Comparison with Switching, a'] For $t>0$ and $(x,y)\in\mathbb{R}^2$,
		\begin{eqnarray}
			\notag p(x,y,t) &=&\frac{e^{-st}}{2\pi\sigma_1\sigma_2 t}\,
			\exp\!\Bigl(-\tfrac{(x-x_0-\mu_1t)^2}{2\sigma_1^2 t}-\tfrac{(y-y_0-\mu_2t)^2}{2\sigma_2^2 t}\Bigr)\\
			\notag &+&\frac{se^{-st}}{4\pi}\sum_{\epsilon\in\{\pm 1\}}\!\!\int_0^1\!\frac{(1+\epsilon\sqrt z)I_1(st\sqrt{1-z})\,\Theta(x,y,z,t,\epsilon)}{\sqrt{z(1-z)}}\mathrm{d} z\\
			&+&\frac{se^{-st}}{4\pi}\sum_{\epsilon\in\{\pm 1\}}\!\!\int_0^1\!\frac{I_0(st\sqrt{1-z})\,\Theta(y,x,z,t,\epsilon)}{\sqrt z}\mathrm{d} z,
		\end{eqnarray}
		where $I_0,I_1$ are modified Bessel functions of the first kind, and
		\begin{equation}
			\Theta(x,y,z,t,\epsilon)=\frac{\exp\!\Bigl(-\tfrac{\bigl(x-x_0-t\tfrac{(\mu_1+\mu_2)+\epsilon\sqrt z(\mu_1-\mu_2)}{2}\bigr)^2}{t\left[(\sigma_1^2+\sigma_2^2)+\epsilon\sqrt z(\sigma_1^2-\sigma_2^2)\right]}-\tfrac{\bigl(y-y_0-t\tfrac{(\mu_1+\mu_2)-\epsilon\sqrt z(\mu_1-\mu_2)}{2}\bigr)^2}{t\left[(\sigma_1^2+\sigma_2^2)-\epsilon\sqrt z(\sigma_1^2-\sigma_2^2)\right]}\Bigr)}
			{\sqrt{(\sigma_1^2+\sigma_2^2)^2-z(\sigma_1^2-\sigma_2^2)^2}}.
		\end{equation}

