body:
[Lem inf of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] Let us consider two sets $A$ and $B$ and a function $h$ on $A \cup B$.
It holds that
\begin{equation}
\inf_{z \in A \cup B} h(z) +\inf_{z \in A \cap B} h(z)
\ge \inf_{z \in A} h(z) + \inf_{z \in B} h(z).
\end{equation}
Moreover, if the inequality is strict, then
\begin{equation}
    \inf_{z \in A} h(z) = \inf_{z \in A \backslash B} h(z) < \inf_{z \in A \cap B} h(z),
\end{equation}
and the same holds if we switch the roles of $A$ and $B$.

[Lemma 18 (Local-uniform ReLU approximation of tensorized Hermite polynomials) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] There exists a universal constant $C>0$ such that for every $D, J_n \in \mathbb{N}_{+}$, $\boldsymbol{\alpha} \in \mathbb{R}^{J_{n} \times D}$ with $|\boldsymbol{\alpha}|=\sum_{r=1}^{D}\sum_{j=1}^{J_n}\alpha_{j,r}=n$, $B>0$, and $\varepsilon \in (0,1)$ there exists a $\operatorname{ReLU-MLP}$ $\Phi_{\boldsymbol{\alpha}, B, \varepsilon}^{\rm Herm}:\mathbb{R}^{J_{n} \times D}\to \mathbb{R}$ satisfying
\begin{equation*}
    \sup_{\boldsymbol{x}\in[-B,B]^{J_n\times D}}
\left|
h_{\boldsymbol\alpha}(\boldsymbol{x})
-
\Phi^{\rm Herm}_{\boldsymbol\alpha,B,\varepsilon}(\boldsymbol{x})
\right|
\le
\varepsilon.
\end{equation*}
Moreover, the width, depth, and number of non-zero parameters can be chosen as in (the second part of) Proposition \ref{prop:ChaosMode}

[Proposition 6 (Trace maximization) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $C \in \bR^{n \times n}$ and consider the optimization problem
\begin{equation} 
\max\{ \tr(CP) : P \in \bR^{n \times n}, \|P\|_{2 \rightarrow 2} \leq 1 \}.
\end{equation}
\begin{itemize}
\item[(i)] The optimal value is $\|C\|_*$.
\item[(ii)] Let $C$ have singular value decomposition $U \Sigma V^{\top}$ with the convention that $\Sigma = \diag(\sigma_1(C), \ldots, \sigma_n(C))$. Let $r = \rank(C)$ and write
\[
U = \begin{bmatrix} U_1 & U_0 \end{bmatrix}, \quad V = \begin{bmatrix} V_1 & V_0 \end{bmatrix},
\]
where $U_1, V_1 \in \bR^{n \times r}$ and $U_0, V_0 \in \bR^{n \times (n-r)}$ (if $r = n$ then $U_0$ and $V_0$ are empty). Then the set of optimizers is
\begin{equation} 
\mathscr{P}(C) := \{ P = V_1 U_1^{\intercal} + V_0 K U_0^{\intercal} : K \in \bR^{(n - r) \times (n - r)}, \|K\|_{2 \rightarrow 2} \leq 1\}.
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

