[Prop 17 of arXiv:2509.09589, 'Geometry of critical discrete structures: long-range percolation on the hierarchical latti'] [Upper bound on the two-point function]
\begin{enumeratea}
\item
Let $\alpha\in (0, d)$ and $\alpha < \theta < \min\{ 2\alpha, \alpha + d/3 \}$.
Then for $x\in\Lambda_n\setminus\{0\}$,
\begin{align}
	\pr(0 \connects x)
	\lesssim
	\begin{cases}
		\zeta_n^{-1} \| x\|^{-\alpha}\, ,\ \ \text{ if }\ \ L\leq \|x\| \leq L^{n a_0}\, ,
		\\[3pt]
		L^{-n( d + \alpha - \theta ) }\, , \text{ if }\ \ L^{n a_0}< \|x\| \leq L^n\, ,
	\end{cases}
\end{align}
where $a_0 = 2 - \theta\alpha^{-1}$.

\item 
Let $\alpha\in (0, d/3)$ and $2\alpha \leq \theta < \alpha + d/3 $.
Then
\begin{align}
\pr(0 \connects x)
\lesssim
L^{-n( d + \alpha - \theta ) }
\ \ \text{ for }\ \ x\in\Lambda_n\setminus\{0\}.
\end{align}

\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

