[Definition 33 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $E$ is a normed vector space, e.g. $E=\nU^\prime$,  and 
 $\bu \in C([0,T];E)$. The modulus of continuity of  $\bu$  on $[0,T]$ is defined by:
  \begin{equation*}
    \mc_{E}(\bu,\delta)= \sup_{s,\,t \in[0,T],\; \lvert t-s \rvert \leq \delta} \Vert \bu(t) - \bu(s) \Vert_{E}, \quad 0< \delta \leq 1.
  \end{equation*}

[Prop 29 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Let $\alpha > 1$ and let $\tilde \Pi_z^\eps \<bs(2)0>$, $\tilde \Pi_z^\eps \<ps(2)0>$ be given as in the statement of Theorem~\ref{theo: bphz_uniform_bound} with $\delta = \eps^\alpha$. Define
	\begin{equs}
		\mfm_{\<bsq>} := \widehat{H_0}\, (\widehat \rho - 1)\, \overline{\widehat{\rho}}\;, &\quad
		\mfm_{\<psq>} := \widehat{H_0}\, (\widehat \rho - 1)\;, \\
		\intertext{as well as}
		c_{\<bsq>} := 2 (2\pi)^{-2}\int_{\mbR \times \mbR} |\mfm_{\<bsq>}|^2(\tau, k) d\tau dk\;, &\quad
		c_{\<psq>} := 2 (2\pi)^{-2}\int_{\mbR \times \mbR} |\mfm_{\<psq>}|^2(\tau, k) d\tau dk\;, \\
		c_{\<halfsq>} := 2 (2\pi)^{-2}& \int_{\mbR \times \mbR} (\mfm_{\<bsq>} \mfm_{\<psq>}) (\tau, k) d\tau dk\;. 
	\end{equs}
	Then $(\xi_\eps, \tilde \Pi_z^\eps \<bs(2)0>, \tilde \Pi_z^\eps \<ps(2)0>)$ converges jointly in law in $(C^{-3/2- 2\kappa})^3$ to $(\xi, \tilde \xi_{\<bsq>}, \tilde \xi_{\<psq>})$ which is a jointly Gaussian triple of random distributions such that for test functions $\varphi_1, \varphi_2, \varphi_3$, the covariance matrix of $(\xi(\varphi_1), \tilde \xi_{\<bsq>}(\varphi_2), \tilde \xi_{\<psq>}(\varphi_3))$ is given by
	\begin{equ}[eq:covariance]
		\begin{pmatrix}
			\|\varphi_1\|_{L^2}^2 & 0 & 0 \\
			0 & c_{\<bsq>} \|\varphi_2\|_{L^2}^2 & c_{\<halfsq>} \langle \varphi_2, \varphi_3 \rangle_{L^2} \\
			0 & c_{\<halfsq>} \langle \varphi_2, \varphi_3 \rangle_{L^2} & c_{\<psq>} \|\varphi_3\|_{L^2}^2
		\end{pmatrix}\;.
	\end{equ}

	In particular, it holds that
	\begin{itemize}
		\item $c_{\<bsq>}, c_{\<psq>}$ are strictly positive;
		\item $c_{\<halfsq>}, c_{\<bsq>}, c_{\<psq>}$ depend only on the mollifier $\rho$ (in particular, they are independent of $\alpha$);
		\item $|c_{\<halfsq>}| < \sqrt{c_{\<bsq>} c_{\<psq>}}$ and $c_{\<bsq>} < c_{\<psq>}$ for every $\rho$.
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Problem 34 of arXiv:2608.26628, 'Open Problems in Mathematical Logic'] Let $L_x=\{z : z \leq_K^+ x\}$ and $U_x=\{z : z \geq_K x\}$. Are the following true?
    \begin{enumerate}
        \item[(1)] $L_x$ is countable iff $\liminf_{n\to\infty}(K(x\upharpoonright n)-K(n))<\infty$;
        \item[(2)] $U_x$ is countable iff $\liminf_{n\to\infty}(K(n)+n-K(x\upharpoonright n))<\infty$.
    \end{enumerate} (Stated as a problem by the paper; open unless the paper says otherwise.)

[Definition def:crossing_rectangles of arXiv:2608.17073, 'Near-critical percolation with sparse reinforcements'] For any $L \in \mathbb{Z}_+$, we define the \textbf{horizontal rectangle} $R_L^h$ and the \textbf{vertical rectangle} $R_L^v$ as the following subsets of $\mathbb{Z}^2$:
\begin{align*}
    R_L^h &= [0, 2L] \times [0, L], \\
    R_L^v &= [0, L] \times [0, 2L].
\end{align*}

[Conjecture conj_QM of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] {basu2017kesten}}] For any $3\le d\le 5$ and $\delta>0$, there exists a constant $c=c(d,\delta)>0$ such that for any $p\in [p_c(d),p_c(d)+\delta]$, $N\ge 1$, $Z\subset \mathbb{Z}^d$ with $B(4N)\setminus B(N) \subset Z$, $X\subset Z\cap B(N)$ and $Y\subset Z\setminus B(4N)$,  
	\begin{equation}
		\mathbb{P}_p\big(X\xleftrightarrow{} Y\ \text{in}\ Z\big)\ge c\cdot  \mathbb{P}_p\big(X\xleftrightarrow{} \partial B(2N)\ \text{in}\ Z\big)\mathbb{P}_p\big(Y\xleftrightarrow{} \partial B(2N)\ \text{in}\ Z\big).
	\end{equation}	
	Here ``$A\xleftrightarrow{} A'$ in $Z$'' means that there exists a path within $Z$ that connects $A$ and $A'$ and consists of open edges. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma 12 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Let $U \subsetneq \BC$ be a simply connected domain. Let $z \in U$ be deterministic, and let $V \subset U$ be a deterministic simply connected domain. Write $\{V_j\}_j$ for the connected components of $V^\star$ (recall~\eqref{eq:def-V-star} for the definition of $V^\star$). Let $(\Gamma_U, D_{\Gamma_U}^U, \{D_{\Gamma_U|_{V_j}}^{V_j}\}_j)$ be coupled as in \Cref{def:weak_axioms}, Axiom~\eqref{it:weak_axiom_locality} (locality). Let $\tau$ be a stopping time for the filtration $\{\mathcal{F}_t\}_{t \ge 0}$, where
\begin{equation*}
	\mathcal{F}_t \defeq \sigma\left(\SCB_s(\SCL(z); D_{\Gamma_U}^U), \Gamma_U|_{\SCB_s(\SCL(z); D_{\Gamma_U}^U)} : s \le t\right).
\end{equation*}
Then, conditionally on the $\sigma$-algebra generated by~\eqref{eq:weak_axiom_locality} and by $\SCB_\tau(\SCL(z); D_{\Gamma_U}^U)$, on the event that $\SCB_\tau(\SCL(z); D_{\Gamma_U}^U) \cap V^\star = \emptyset$, the pairs $(\Gamma_U|_{V_j}, D_{\Gamma_U|_{V_j}}^{V_j})$ are independent and their conditional laws are those of $(\Gamma_{V_j}, D_{\Gamma_{V_j}}^{V_j})$, respectively.

The same is true with a deterministic connected arc of $\partial U$ in place of $\SCL(z)$.

[Theorem of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] The following hold.
 \begin{enumerate}
 \item[(1)]  For any $\lambda \geq 0$ and $g\in L^\infty(\mathbb{R}_+;\mathbb{R}_+)$, the generalized Volterra-Riccati equation (??) has a unique global solution $V^\lambda_g \in C(\mathbb{R}_+;\mathbb{R}_+)\cap C^2\big((0,\infty);\mathbb{R}_+\big)$.

 \item[(2)] For any $K_1,K_2>0$ and $T\geq 0$, there exists a constant $C>0$ such that for any $\lambda_1,\lambda_2\in[0,K_1]$ and $g_1,g_2 \in L^\infty(\mathbb{R}_+;\mathbb{R}_+) $ with $\big\|g_1\big\|_{L^\infty_T}, \big\|g_2\big\|_{L^\infty_T}\in[0,K_2]$,
 \begin{eqnarray*}
 \sup_{t\in[0,T]} \big| V^{g_1}_{\lambda_1} (t) -V^{g_2}_{\lambda_2} (t)\big|
 \leq C\cdot \Big(\big| \lambda_1-\lambda_2 \big| + \big\|g_1-g_2\big\|_{L^\infty_T}\Big).
 \end{eqnarray*}
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 10 (\cite{Wall}) of arXiv:2608.26068, 'All once-extended 3D TQFTs are Reshetikhin--Turaev theories'] Let $M_-,H,M_+$ be $(4k-1)$-manifolds with common boundary $-\partial M_- = \partial H = \partial M_+ = \Sigma$ and $X_-, X_+$ be $4k$-manifolds with $\partial X_+ = M_+ \cup_\Sigma (-H), \partial X_- = X_0 \cup_\Sigma M_-$, and $X_0 = X_+ \cup_{H} X_-$, as in Figure \ref{fig:wall-diagram}. Then the signatures of $X_0$ and $X_\pm$ are related by $$\sigma(X_0) = \sigma(X_-) + \sigma(X_+) - \sigma(V; A, B, C)$$
    where $V = H_{2k-1}(\Sigma; \mathbb{R})$ and $A, B, C$ are the Lagrangian subspaces of $V$ associated to the inclusions $\Sigma \hookrightarrow M_-$, $\Sigma \hookrightarrow H$, $\Sigma \hookrightarrow M_+$ respectively.
    \begin{figure}[hbt!]
        \includegraphics[scale=0.5]{wall_diagram.pdf}

        \caption{Gluing $X_\pm$ to form $X_0$ in Wall's Theorem.} 
    \end{figure} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 60 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(\Perf\) be the category of perfect \(\setF_p\)-algebras.
    Write the restriction of functors \(\mcalF\) and \(\mcalG\) to the full subcategory \(\Perf \subset \Perfd\) as
    \begin{equation*}
        \mcalF_{\crys}, \mcalG_{\crys} \colon \Perf \to \CAlg^{an}_{\setF_p}.
    \end{equation*}
    Then there exists a natural transformation
    \begin{equation*}
        s \colon \mcalF_{\crys} \to \mcalG_{\crys}
    \end{equation*}
    together with an equivalence of natural transformations
    \begin{equation*}
        \rho \circ s \simeq \id_{\mcalF_{\crys}}.
    \end{equation*}

