[Thm 12 of arXiv:2607.08314, 'Berry-Heisenberg random waves'] Let $\alpha>0$ be fixed. Then the following are equivalent.

    \begin{enumerate}
        \item  There exists a left-invariant random field $\xi : \Hei \rightarrow \mathbb{C}$ such that 

        \begin{enumerate}[label=(\roman*)]
        \item $\xi$ is a Gaussian field and the random variable $\xi(g)$ is $N_{\mathbb{C}}(0,2)$ for all $g\in\Hei$;
        \item the function $g\rightarrow \xi (g)$ is smooth a.s. and it is a generalized eigenfunction for the sub-Laplacian with eigenvalue $\alpha$;
        \item the law of $\xi$ is invariant under isometries that fix the identity.
    \end{enumerate}

        \item $\xi_{\alpha}$ is a complex-valued Gaussian field whose trajectories are smooth a.s. with mean zero and covariance function $2F_{\alpha}^{(c)}$ for some $c\in  \mathcal{O}^{1}$.

        \item The field $\xi$ can be represented as
\begin{equation}
    \xi (g) =  \sqrt{c_{-1}}\, b^{\C}_{\alpha} (z)+\sum_{k=0}^{\infty} \sqrt{c_{k}} \, \xi^{k}_{\alpha} (g) , \quad g=(z,t) \in \Hei,
\end{equation}
for some $c\in  \mathcal{O}^{1}$, where $\{ b^{\C}_{\alpha} (z) , z \in \R^{2} \}$ is a complex-valued Berry random field on $\R^{2}$ and 
\begin{align}
    & \xi^{k}_{\alpha} (g) := \pi^{\frac{1}{4}} \sum_{\varepsilon = \pm 1} \sum_{j=0}^{\infty} a^{\alpha ,\varepsilon}_{kj} e^{\alpha, \varepsilon}_{kj} (g) ,
\end{align}
where $e^{\alpha, \varepsilon}_{kj}$ are the generalized $\mathcal{L}$-eigenfunctions given by \eqref{eqn.e.function} and $a^{\alpha, \varepsilon}_{kj}$ are complex-valued Gaussian random variables independent of $b^{\C}_{\alpha}$ and such that
\begin{align*}
    \E \left[ a^{\alpha, \varepsilon}_{kj} \overline{a^{\alpha, \varepsilon^{\prime}}_{k^{\prime}j^{\prime}}} \right] = \delta_{kk^{\prime}}\delta_{jj^{\prime}}\delta_{\varepsilon \varepsilon^{\prime}}.
\end{align*}
    \end{enumerate}

