[Proposition of arXiv:2604.22130, 'Reflected Stochastic Differential Equations Driven by $G$-Brownian Motion with Nonlinear C'] Suppose that $(l,r)$ and $(\tilde{l},\tilde{r})$ satisfy Assumption (ass1 of the paper). Given $S\in S_G^p(0,T)$, let $(A^l,A^r)$ (resp., $(\tilde{A}^l,\tilde{A}^u)$) be the pair of constraining processes for the reflected problem with constraints $l,r$ (resp., $\tilde{l},\tilde{r}$) for $S$. If $r\geq \tilde{r}$ and $l\leq \tilde{l}$, then for any $t\in[0,T]$, 
\begin{displaymath}
A^l_t\leq \tilde{A}^l_t, \  A^r_t\leq \tilde{A}^r_t, \textrm{ q.s.}
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t02 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Fix a function $G\colon {\mathbb T}^d_N \to {\mathbb R}$, and a finite subset $A$
of ${\mathbb Z}^d$ with at least two elements. Assume that
$\sup_{N\ge 1} K^2_N / \ell^d_N < \infty$. Then, there exists a finite
constant ${\mathfrak c}({\boldsymbol u}^N)$ which depends only on ${\boldsymbol u}^N$, the set
$A$, the dimension $d$, and is uniformly bounded in $N$, such that
\begin{equation*}
K_N\, \int  {\mathcal W}^{G,A}
\, f\; d\nu^N \; \le\;
\delta \, N^2\, I^E_{N}(f;\nu^N)
\;+\; {\mathfrak c}({\boldsymbol u}^N)\, \frac{1}{\delta}\, \{\, 1 + \Vert
G\Vert^2_\infty\,\} \, K^2_N
\, \big\{ H_N(f) \,+\, (N/\ell_N)^d \, \big\} 
\end{equation*}
for all $0<\delta<1$, density $f$ with respect to $\nu^N$ and
$N\ge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:canonical-model-is-dia-p of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] Let $L \supseteq \textbf{FIK}$, then $\mathfrak{M}_L^*$ is a $\Diamond$-p model.
  \begin{proof}
    Take any $x = (\Gamma_x, \Delta_x)$, $x' = (\Gamma_x', \Delta_x')$, and $y = (\Gamma_y, \Delta_y)$ such that $x' \geq_L^* x \sqsubset^* y$,
    then $\Gamma_x \subseteq \Gamma_x'$, $\Box^{-1} \Gamma_x \subseteq \Gamma_y$, and $\Diamond^{-1} \Delta_x \subseteq \Delta_y$ by definition.
    \begin{claim*}
      $(\Box^{-1} \Gamma_x' \cup \Gamma_y, \Diamond^{-1} \Delta_x')$ is $L$-consistent.
      \begin{subproof}
        Suppose not, then there are finite $A \subseteq \Box^{-1}\Gamma_x'$, $B \subseteq \Gamma_y$, $C \subseteq \Diamond^{-1}\Delta_x'$ such that
        $L \vdash \left(\bigwedge A \land \bigwedge B\right) \to \bigvee C$, then:
        \begin{center}
          \AxiomC{$L \vdash \left(\bigwedge A \land \bigwedge B\right) \to \bigvee C$}
          \UnaryInfC{$L \vdash \bigwedge B \to \left(\bigwedge A \to \bigvee C\right)$}
          \RightLabel{\scriptsize{$\textsf{M}_\Diamond$}}
          \UnaryInfC{$L \vdash \Diamond \bigwedge B \to \Diamond \left(\bigwedge A \to \bigvee C\right)$}
          \RightLabel{\scriptsize{$\textsf{FS1}$}}
          \UnaryInfC{$L \vdash \Diamond \bigwedge B \to \left(\Box \bigwedge A \to \Diamond \bigvee C\right)$}
          \RightLabel{\scriptsize{$\textsf{C}_\Box$, $\textsf{C}_\Diamond$}}
          \UnaryInfC{$L \vdash \Diamond \bigwedge B \to \left(\bigwedge \Box A \to \bigvee \Diamond C\right)$}
          \UnaryInfC{$L \vdash \left(\bigwedge \Box A \land \Diamond \bigwedge B\right) \to \bigvee \Diamond C$}
          \DisplayProof
        \end{center}
        Then $\Diamond \bigwedge B \notin \Gamma_x'$ by $L$-consistency of $x'$ (with $\Box A \subseteq \Gamma_x'$ and $\Diamond C \subseteq \Delta_x'$),
        then $\Diamond \bigwedge B \notin \Gamma_x$ by $\Gamma_x \subseteq \Gamma_x'$,
        then $\Diamond \bigwedge B \in \Delta_x$ by maximality of $x$,
        so $\bigwedge B \in \Delta_y$ by $\Diamond^{-1} \Delta_x \subseteq \Delta_y$,
        which is a contradiction since $B \subseteq \Gamma_y$ implies $\bigwedge B \in \Gamma_y$.
      \end{subproof}
    \end{claim*}
    Now that $(\Box^{-1} \Gamma_x' \cup \Gamma_y, \Diamond^{-1} \Delta_x')$ is $L$-consistent,
    then by Lindenbaum lemma, there is $y' = (\Gamma_y', \Delta_y') \in W_L^*$
    such that $\Gamma_y \subseteq \Gamma_y'$, $\Box^{-1} \Gamma_x' \subseteq \Gamma_y'$, and $\Diamond^{-1} \Delta_x' \subseteq \Delta_y'$,
    which imply $y \leq^* y'$ and $x' \sqsubset^* y'$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mydef def:CCLCD of arXiv:2604.11761, 'The smallest singular value of signed random combinatorial matrices'] {tran2020smallestsingularvaluerandom}}]
Given two vectors $a$ and $v$ in $\mathbb{R}^n$, as well as parameters $L, u>0$, the Combinatorial Least Common Denominator of the pair $(a, v)$ is

\begin{align*}
\operatorname{CLCD}_{L, u}^a(v):=\inf \left\{\theta>0: \operatorname{dist}\left(\theta  (\mathrm{D}(a) \otimes \mathrm{D}(v)), \mathbb{Z}^{\binom{n}{2}^2}\right)<\min (u\|\theta(\mathrm{D}(a) \otimes \mathrm{D}(v))\|_2, L)\right\} .
\end{align*}

