[Theorem 13 of arXiv:2609.03726, 'Inverse Scattering for Single Photons in Quantum Optics'] Let $n \geq 2$ and $k_\rho$ be the threshold from Lemma \ref{lem_LAP} with $l=[n/2]+1$ and $\delta=3/4$. Assume that
    \begin{equation*}
        \Sigma \cap (S\cup W) = \varnothing.
    \end{equation*}
    Assume that $z_1, z_2\in S$ and $x^* \in W$ satisfy
    \begin{equation*}
        [z_2,x^*] \cap \Sigma = \varnothing.
    \end{equation*}
    Then the data $\{\Lambda_k^{\mathrm{src}}\}_{k>k_\rho}$ determines the integral
    \begin{equation*}
        \int_0^1 \rho\bigl(z_1 + s(x^* - z_1)\bigr)\,ds.
    \end{equation*}

[Definition 1 of arXiv:2608.05514, 'It\^{o}'s formula for L\'evy-It\^{o} processes taking values in the dual of nuclear space'] Let $U$ be a topological space and consider a ring $\mathcal{R}\subseteq \mathcal{B}(U)$ that generates $\mathcal{B}(U)$.  A \emph{cylindrical martingale-valued measure} on $\R_{+} \times \mathcal{R}$ is a collection $M=(M(t,A): t \geq 0, A \in \mathcal{R})$ of cylindrical random variables in $\Phi'$ such that:
\begin{enumerate}
\item $\forall \, A \in \mathcal{R}$, $M(0,A)(\phi)= 0$ $\Prob$-a.s., $\forall \phi \in \Phi$.
\item $\forall t \geq 0$, $M(t,\emptyset)(\phi)= 0$ $\Prob$-a.s. $\forall \phi \in \Phi$ and if $A, B \in \mathcal{R}$ are disjoint then 
$$M(t,A \cup B)(\phi)= M(t,A)(\phi) + M(t,B)(\phi) \, \Prob \mbox{-a.s.}, \quad \forall \phi \in \Phi.$$
\item $\forall \, A \in \mathcal{R}$, $(M(t,A): t \geq 0)$ is a cylindrical mean-zero square integrable c\`{a}dl\`{a}g martingale. 
\end{enumerate}
We say $M$ is \emph{orthogonal} if
\begin{enumerate}\setcounter{enumi}{3}
\item For disjoint $A, B \in \mathcal{R}$, $\Exp \left( M(t,A)(\phi) M(s,B)(\varphi) \right)=0$, for each $t,s \geq 0$, $\phi, \varphi \in \Phi$. 
\end{enumerate}
We say $M$ has \emph{independent increments} if
\begin{enumerate}\setcounter{enumi}{4}
\item For $0\leq s < t$, $(M(t,A)- M(s,A))(\phi)$ is independent of $\mathcal{F}_{s}$, for all $A \in \mathcal{R}$, $\phi \in \Phi$.
\end{enumerate}
Further, we say $M$ is \emph{nuclear} if 
\begin{enumerate}\setcounter{enumi}{5}
\item  For each $A \in \mathcal{R}$, $0 \leq s < t$, $\phi \in \Phi$,  
\begin{equation}
\Exp \left( \abs{ (M(t,A)- M(s,A))(\phi)}^{2} \right) = \int_{s}^{t} \int_{A} q_{r,u}(\phi)^{2} \mu(du) dr ,
\end{equation} 
where $\mu$ is a $\sigma$-finite measure on $(U, \mathcal{B}(U))$ satisfying $\mu(A)< \infty$ $\forall \, A \in \mathcal{R}$, and $\{q_{r,u}: r \in \R_{+}, \, u \in U \}$ is a family of  continuous Hilbertian semi-norms on $\Phi$ such that for each $\phi$, $\varphi$ in $\Phi$, the map $(r,u) \mapsto q_{r,u}(\phi,\varphi)$ is $\mathcal{B}(\R_{+}) \otimes \mathcal{B}(U)/ \mathcal{B}(\R_{+})$-measurable and  bounded on $[0,T] \times U$ for all $T>0$. Here, $q_{r,u}(\cdot,\cdot)$ denotes the positive, symmetric, bilinear form associated to the Hilbertian semi-norm $q_{r,u}$.  
\end{enumerate}

[Proposition 3 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] Let \(T\) be a positive random variable with \(0<\E[T]<\infty\) and \(\E[T^2]<\infty\). Then
\begin{equation*}
    \frac{\Var(T)}{\E[T^2]}
    =\min_{\mu>0}\frac{\E[(T-\mu)^2]}{\mu^2}.
\end{equation*}
The minimizer is unique and equals 
\begin{align*}
\frac{\E[T^2]}{\E[T]}.
\end{align*}

