[Proposition 33 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let \cref{ass:gaussian-stable-selected} hold. Let $\nu_{A,N}$ be the unique
  nonzero invariant law of $K_{A,N}$. Then there are constants $C,c>0$ such that
  \begin{equation}
    \nu_{A,N}(I_\ast^c)\leq C e^{-cN}
  \end{equation}
  for all sufficiently large $N$. In particular,
  \begin{equation}
    \nu_{A,N}(I_\ast^c)\leq\frac{C}{N}
  \end{equation}
  after enlarging $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop EHI:p:GeneralCounterex of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X=(X_t)_{t \geq 0}$ be an isotropic unimodal L\'{e}vy jump process. Suppose there exist sequences $(R_{1, n})_{n=1}^\infty, (R_{2, n})_{n=1}^\infty, (R_{3, n})_{n=1}^\infty \subseteq (0, \infty)$ and a sequence $(T_n)$ of Meyer-decomposition-arising exponential stopping times, satisfying the following properties:
    \begin{itemize}
        \item For all $n$,
        \begin{equation*}
            0 < R_{1, n} < R_{2, n} < R_{1, n}+R_{2, n} < R_{3, n}.
        \end{equation*}
        \item There exists a $C>0$ such that for all $n$,
        \begin{equation} 
            R_{2, n} \leq C R_{1, n}.
        \end{equation}
        \item We have
        \begin{equation} 
            1 \gg \mathbb{P}_0 \left( \tau_{B(0, R_{1, n})} < T_n \right) \gg \mathbb{P}_0 \left( |\Delta X(T_n)| \leq R_{1, n}+R_{2, n}+R_{3, n} \right).
        \end{equation}
        \item As $n \to \infty$,
        \begin{equation} 
            \sup_{x \in B(0, R_{1, n})} \mathbb{P}_x \left( X_{\tau_{B(0, R_{1, n})}} \notin B(0, R_{2, n}) \Big| \tau_{B(0, R_{1, n})} < T_n \right) \to 0. 
        \end{equation}
        \item There exists a $c>0$ such that for all $n$, for all $x \in B(0, R_{1, n}+R_{2, n})$,
        \begin{equation}
            \mathbb{P}_x \left( X_{\tau_{B(0, R_{1, n}+R_{2, n})}} \in B(0, R_{3, n}) \Big| \tau_{B(0, R_{1, n}+R_{2, n})} < T_n \right) \geq c.
        \end{equation}
    \end{itemize}
    Then $X$ does not satisfy $\hyperref[EHI:d:ehi]{\mathrm{EHI}}$. Furthermore, if $r_n \to 0$ along a subsequence then $X$ does not satisfy $\hyperref[EHI:d:ehi]{\mathrm{EHI}}(r \leq 1)$, and if $r_n \to \infty$ along a subsequence then $X$ does not satisfy $\hyperref[EHI:d:ehi]{\mathrm{EHI}}(r \geq 1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:cutoffdiff of arXiv:2508.21055, 'Modern aspects of Markov chains:\\entropy, curvature and the cutoff phenomenon'] Any diffusion with $\rho\ge 0$ started from a deterministic  state $x\in\mathbb{X}$ satisfies the IDI ((def:IDI of the paper))  with rate 
$
\psi(t) =  2t.
$
In particular, 
\begin{eqnarray*}
\forall\varepsilon\in(0,1/2),\quad {\rm w}_{\textsc{mix}}(x,\varepsilon) & \le & \frac{1}{\gamma\varepsilon^3}+\sqrt{\frac{8{\rm t}_{\textsc{mix}}(x,\varepsilon)}{\gamma\varepsilon^3}}.
\end{eqnarray*}
Thus,  there is cutoff from $x$ as soon as $\gamma{\rm t}_{\textsc{mix}}(x,\varepsilon)\to\infty$ for some $\varepsilon\in(0,1)$. Similarly,
\begin{eqnarray*}
\forall\varepsilon\in(0,1/2),\quad {\rm w}_{\textsc{mix}}(\varepsilon) & \le & \frac{1}{\gamma\varepsilon^3}+\sqrt{\frac{8{\rm t}_{\textsc{mix}}(\varepsilon)}{\gamma\varepsilon^3}},
\end{eqnarray*}
as soon as $\mathbb{X}$ is compact, hence a worst-case cutoff occurs if and only if $\gamma{\rm t}_{\textsc{mix}}\to\infty$.

