[Proposition uniqueness of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Let $|q|<1$ and $x=\cos\theta \in \left(-1,1\right)$.  
    For $\alpha \in \mathbb{C}$, define the weight function
    \begin{equation}
    w\left(x\right) := \frac{\left(q;q\right)_{\infty}}{2\pi \sqrt{1-x^{2}}} \frac{\left|\left(e^{2i\theta};q\right)_{\infty}\right|^{2}}{\left|\left(e^{i\theta};q\right)_{\infty}\right|^{2}},\quad x=\cos\theta.
\end{equation}

    $H_n\left(x|q\right)$ is orthogonal with respect to the reference measure $w\left(x\right)$, i.e.
    \begin{equation}
        \int_{-1}^{1} H_n\left(x|q\right) H_m\left(x|q\right) w\left(x\right) dx = \delta_{m,n} \left(q;q\right)_{n},
    \end{equation}
    where $\delta_{m,n} = 1 \iff m=n$.
    In addition, $w\left(x\right)$ is the unique reference measure such that (equation ortho of the paper) holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] For each $m\in  \mathbb N$, we have	
\begin{equation}
\begin{split}
b_m^2&\leq b_{m+1}^2+2C_\gamma^2 \sum_{P_{m} \in \mathcal{P}_{m}}\|W^{\frac{1}{p}} \widehat{W}_{\kappa_{2}(P_{m})}\|^2 \Big(\mathbb{E}_{\kappa_{2}(P_{m})}\|\widehat{W}_{\kappa_{2}(P_{m})}^{-1} W^{-\frac1p}f\|_{\mathbb{C}^{d}}\Big)^2\chi_{P_m}\\
&\qquad + \sum_{P_{m+1} \in \mathcal{P}_{m+1}}\|W^{\frac{1}{p}} \widehat{W}_{\kappa_{1}(P_{m+1})}\|^2 \Big(\mathbb{E}_{\kappa_{1}(P_{m+1})}\|\widehat{W}_{\kappa_{1}(P_{m+1})}^{-1} W^{-\frac1p}f\|_{\mathbb{C}^{d}}\Big)^2\chi_{P_{m+1}}
\end{split}
\end{equation}
where $C_\gamma$ is the constant given in Lemma \ref{lem-two-cond}.
Furthermore, given an integer $N>1$, we have
\begin{equation}
\begin{split}
b_1^2&\leq b_{N}^2+(2C_\gamma^2+1) \sum_{m=1}^{N}\sum_{P_{m} \in \mathcal{P}_{m}}\|W^{\frac{1}{p}} \widehat{W}_{\kappa_{2}(P_{m})}\|^2 \Big(\mathbb{E}_{\kappa_{2}(P_{m})}\|\widehat{W}_{\kappa_{2}(P_{m})}^{-1} W^{-\frac1p}f\|_{\mathbb{C}^{d}}\Big)^2\chi_{P_m}.
\end{split}
\end{equation}

[Proposition 99 (Mixed-covariance ultraviolet defect) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $(\eta_{\nu,\cdot})_{\nu\in\mathcal N}$ take values in one common
Hilbert space and satisfy the preceding assumptions with the same $a,b$.
Put
\[
 \gamma_{\nu,\mu}(x,y)
 :=\ip{\eta_{\nu,x}}{\eta_{\mu,y}}
\]
and
\begin{equation}

 D_{\nu,\mu}^{(m)}(x,y)
 :=\gamma_{\nu,\nu}(x,y)^m+\gamma_{\mu,\mu}(x,y)^m
 -\gamma_{\nu,\mu}(x,y)^m-\gamma_{\mu,\nu}(x,y)^m.
\end{equation}
Then
\begin{equation}

 \norm{K_\nu-K_\mu}^2
 =\int_{X^2}D_{\nu,\mu}^{(m)}(x,y)
 A(x,y)\conj{B(x,y)}\,d\mu(x)d\mu(y).
\end{equation}
The integral is real and nonnegative, although its integrand need not be.
Let
\begin{equation}

 \varepsilon_{\nu,\mu}
 :=\int_{X^2}|D_{\nu,\mu}^{(m)}(x,y)|
 |A(x,y)||B(x,y)|\,d\mu(x)d\mu(y).
\end{equation}
For $\alpha\in\{\nu,\mu\}$ suppose
\[
 \norm{|\gamma_{\alpha,\alpha}|^q|A|}_{\mathrm{Schur}}
 \le L_{\alpha,q}^2,\qquad
 \norm{|\gamma_{\alpha,\alpha}|^q|B|}_{\mathrm{Schur}}
 \le R_{\alpha,q}^2.
\]
Then, for $S\subset[m]$, $k=|S|$, and $2\le r<\infty$,
\begin{align}

 &\norm{\Flat_S(\Dec_m(K_\nu-K_\mu))}_{\Sch_r}\\
 &\quad\le
 \varepsilon_{\nu,\mu}^{1/r}
 \bigl(
 L_{\nu,m-k}R_{\nu,k}
 +L_{\mu,m-k}R_{\mu,k}
 \bigr)^{1-2/r}.
\notag
\end{align}
In particular, if
\[
 O:=\sup_\nu\max_{0\le k\le m}
 L_{\nu,m-k}R_{\nu,k}<\infty,
\]
then
\begin{equation}

 \Prof_{m,r}(\Dec_m(K_\nu-K_\mu))
 \le\varepsilon_{\nu,\mu}^{1/r}(2O)^{1-2/r}.
\end{equation}
Thus a vanishing mixed defect gives coefficient convergence for every
finite $r\ge2$.  If $\cH$ is the complexification of a real Hilbert
space and all $\eta_{\nu,x}$ are real, continuity of the same-field
evaluator also gives Wick convergence.

[Lemma 32 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] For any $t\in[0,T]$, let us define a process $\wtilde{M}$ as
				\begin{align}
					\wtilde{M}(t)& := \wtilde{u}(t) -\wtilde{u}(0) -\int_0^t \bigg( \Delta \wtilde{u}(s) -|\wtilde{u}(s)|^{p-2}\wtilde{u}(s) + \big( \norm{\nabla \wtilde{u}(s)}_{L^2(\bO)}^2 + \norm{\wtilde{u}(s)}_{L^p(\bO)}^p \big) \wtilde{u}(s)\\ 
					& \qquad\qquad\qquad\qquad \quad + \frac{1}{2}\sum_{i=1}^M\kappa_i(\wtilde{u}(s)) \bigg) ds.
				\end{align}
				Then, $\wtilde{M}$ is an $L^2(\bO)-$valued continuous process.

