[Lemma 9 (Exact recoding of admissible secants) of arXiv:2608.06393, 'Intrinsic Tangential Hadamard Differentiability of Rough-BSDE Solution Maps'] Let $\varepsilon_n\to0$, $\varepsilon_n\neq0$, let
$\tau_n=(h_n,\kappa_n)\to\tau$ in $\mathbb T_{\mathbf x}^p$, and let
$\mathbf x_n=(1,x_n,\mathbb x_n)\in WG\Omega_p(E)$ satisfy
\eqref{eq:strong-contact}. Define
\begin{align}
 h_n^*&:=\frac{x_n-x}{\varepsilon_n},
 \\
 \kappa_n^*&:=
 \frac{\mathbb x_n-\mathbb x
       -\varepsilon_n^2\mathbb L(h_n^*)}{\varepsilon_n}.

\end{align}
Then
\begin{equation}
 \tau_n^*:=(h_n^*,\kappa_n^*)
 \in\mathbb T_{\mathbf x}^p,
 \qquad
 \tau_n^*\longrightarrow\tau.
\end{equation}
There are representations
$(\mathbf Z_n^*,a_n^*)\in\operatorname{Rep}_{\mathbf x}(\tau_n^*)$ such
that
\begin{equation}
 \sup_n\mathfrak b(\mathbf Z_n^*,a_n^*)<\infty
\end{equation}
and
\begin{equation}
 \mathbf x_n
 =\mathbf x^{\varepsilon_n;\mathbf Z_n^*,a_n^*}
\end{equation}
for every $n$.

