[Lemma 38 of arXiv:2607.16502, 'Asymptotic Behavior of Path Functionals for Vector-Valued Gaussian Processes at High Level'] For every \(\varepsilon>0\), \(\gamma\in(0,2]\), and
  \(\bm\Lambda\in\R_{\ge0}^k\), there exist constants
  \(\delta,c,C>0\) such that the following holds.  Let
  \[
    \left\{
      (\bm\chi_{\bm x}(\bm t))_{\bm t\in[\bm0,\bm\Lambda]}:
      \bm x\in\R^d
    \right\}
  \]
  be a family of continuous \(\R^d\)-valued Gaussian random fields for which
  the map
  \[
    \bm x\longmapsto
    \pk{\exists\,\bm t\in[\bm0,\bm\Lambda]:
      \bm\chi_{\bm x}(\bm t)>\bm x}
  \]
  is measurable.  Suppose that there exist \(G,\sigma\ge0\) and
  \(\bm w=(w_1,\ldots,w_d)^\top\), with
  \(\varepsilon\le w_i\le\varepsilon^{-1}\) for every \(i\), such that for
  every \(\bm x\in\R^d\) and every
  \(\bm t,\bm s\in[\bm0,\bm\Lambda]\),
  \begin{enumerate}[itemsep=0.3cm, topsep=0.3cm, label={\alph*)}]
    \item
    \[
      \sup_{F\subset\{1,\ldots,d\}}
      \sup_{\bm t\in[\bm0,\bm\Lambda]}
      \bm w_F^\top\E{\bm\chi_{\bm x,F}(\bm t)}
      \le G+\delta\sum_{j=1}^d|x_j|;
    \]
    \item
    \[
      \sup_{F\subset\{1,\ldots,d\}}
      \sup_{\bm t\in[\bm0,\bm\Lambda]}
      \Var{\bm w_F^\top\bm\chi_{\bm x,F}(\bm t)}
      \le\sigma^2;
    \]
    \item
    \[
      \sup_{F\subset\{1,\ldots,d\}}
      \Var{
        \bm w_F^\top\bm\chi_{\bm x,F}(\bm t)
        -\bm w_F^\top\bm\chi_{\bm x,F}(\bm s)
      }
      \le\varepsilon^{-1}|\bm t-\bm s|^\gamma.
    \]
  \end{enumerate}
  Then
  \[
    \int_{\R^d}e^{\bm w^\top\bm x}
    \pk{\exists\,\bm t\in[\bm0,\bm\Lambda]:
      \bm\chi_{\bm x}(\bm t)>\bm x}
    \,d\bm x
    \le C e^{c(G+\sigma^2)}.
  \]

[Corollary cor:three-point-suspension-skeleton of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For every $h\geq2$,
\begin{equation}
 \mathcal R(h,3)
 =\left\{\binom{h+2}{2}\right\}
 \cup
 \left\{
  \binom{h+2}{2}-\binom{h-\ell+2}{2}:2\leq\ell\leq h
 \right\}.
\end{equation}
Every value in (equation eq:three-point-spectrum of the paper) is realized by the one-step
suspension
\[
 \Sigma_{\ell,1}\{0,1\}=\{0,1,\ell\};
\]
degrees $\ell>h$ all realize the maximum $\binom{h+2}{2}$.

[Proposition 17 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] For every $1\leq p \leq \widehat{\mf q}$, $\lambda>0$, and
$g\colon \mc S_p\to \bb R$, the unique solution $\phi_{p,\epsilon}$ of
the resolvent equation \eqref{smooth_resolvent_eq} satisfies
\begin{equation}

\lim_{\epsilon \to 0}\max_{k\in S_p}\sup_{x\in \ms
E_p(k)}|\phi_{p,\epsilon}(x) - f_p(\mc M_p(k))| = 0, 
\end{equation}   
where $f_{p} \colon \mc S_p \to \bb R$ is the unique solution of the
reduced resolvent equation
\begin{equation*}

(\lambda - \widehat{\bb L}_p)f_{p} = g.
\end{equation*}

