[Proposition prop:fixeddriver of arXiv:2601.10359, 'An Operator It\^o Formula for Volterra Gaussian Processes:\\ The Intrinsic Bracket via Cau'] Let $M$ be a continuous square-integrable martingale with bracket measure $\mu$ (i.e., $\langle M\rangle_t = \int_0^t d\mu_s$). Let $K_1,K_2$ be two causal Volterra kernels such that the process $X_t := \int_0^t K_1(t,s)\,dM_s$ also satisfies
\begin{equation}
X_t = \int_0^t K_2(t,s)\,dM_s \quad \text{for all } t\in[0,T],\;\text{a.s.}
\end{equation}
Assume both kernels satisfy the Decreusefond--\"Ust\"unel conditions with respect to $\mu$. Then
\begin{equation}
\langle X\rangle^{(D^{K_1},\Pi^{K_1})}_t = \langle X\rangle^{(D^{K_2},\Pi^{K_2})}_t \quad \text{for all } t\in[0,T].
\end{equation}

[Lemm 12 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] Suppose that $\mu$ in \eqref{fbsde:equ:general}
    satisfies Assumption \ref{coefficient:assume:general}, Assumption \ref{fbsde:basic:assume:p:general},
    and is decomposed as $\mu = \sz + A$ according to Assumption \ref{ass:linear:diffusion}. 
    For all $\az\in [0,1]$ and 
    $$(s,\oz,x,y,(z_1,z_2))\in[0,T]\times \Oz\times \R^n\times\R^m \times(\R^{m\times d})^2,$$
    set
    \begin{equation}
        \Sigma(s,\az,\oz,x,y,(z_1,z_2)) 
        := \left(\sz_{\sqrt{1 - \az^2}}(s,\oz,x,y,z_1), \sz_{\az}(s,\oz,x,y,z_2)\right),
    \end{equation}
    where
    $\sz_{r}(s,\oz,x,y,z) := r\,\sz(s,\oz,x,y) + A(s,\oz,z)$ for all $r\in [0,1]$.
    Then the following properties hold:
    \begin{itemize}
        \item[(1)] Lipschitz Continuity:
        For all $\az\in [0,1]$, $s\in [0,T]$, $\oz\in\Oz$ and 
        $$\tz = (x,y,(z_1,z_2)),\quad \tz' = (x',y',(z'_1,z'_2)),$$
        we have
        \begin{align*}
            |\Sigma(s,\az,\tz) - \Sigma(s,\az,\tz')| 
            &\leq L_{\mu,1} |x - x'| + L_{\mu,2}|y - y'|\\
            &\quad\quad + L_{\mu,3} |(z_1,z_2) - (z'_1,z'_2)|,
        \end{align*}
        where $\{L_{\mu,i}\}^3_{i = 1}$ are the Lipschitz constants for $\mu$ (Assumption \ref{coefficient:assume:general});
        \item[(2)] Integrability Condition:
        The function $\Sigma(\cdot,0,0,(0,0))$ belongs to the space $\cL^{2,p}([t,T]\times\Oz,\F,\P;\R^{n\times 2d})$;
        \item[(3)] Representation Property:
        For all $z\in \R^{m\times d}$,
        \begin{align*}
            &\Sigma(s,\az,x,y,(\sqrt{1 - \az^2}z,\az z))\\
            &\quad = \left(\sqrt{1 - \az^2} \mu(s,x,y,z), \az\mu(s,x,y,z)\right).
        \end{align*}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:qjellsmall of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] For the functions $Q_{j,\ell,m}$ defined in Proposition~(prop:basisconvolution of the paper) one has
\begin{align} 
    e^{-\frac{z^2}{2n}}
    \frac{Q_{j,\ell,m}(z/\sqrt{n})}{n^{\ell+j-m/2}}
=
    O\left(\frac{1}{(\min(\sqrt{n},1+|z|))^{2\ell+2j-m}}
    \right).
\end{align}

