[Lemma lem:biggins-chernoff-block-count-exponent of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume the minimal Kahane--Peyri\`ere regime. For \(a\in\mathbb R\) and \(n\ge1\), set
\begin{equation*}
N_n(a)=\#\{u\in\{0,1\}^{n}:Q_u\ge 2^{an}\}.
\end{equation*}
Then:
\begin{enumerate}
\item For every \(a\in\mathbb R\),
\begin{equation*}
\Lambda(a):=\lim_{n\to\infty}\frac1n\log_2\mathbb E N_n(a)
=
\inf_{q\ge0}
\left\{
1+\log_2\mathbb E(W^q)-qa
\right\},
\end{equation*}
where \(W^0:=\mathbf 1_{\{W>0\}}\), and for \(q>0\) the term is \(+\infty\) if \(\mathbb E(W^q)=+\infty\).

\item If \(a<1-A_{\mathrm{loc}}(W)\), then \(\Lambda(a)>0\).

\item The function \(\Lambda\) is finite and continuous on \((-\infty,1-A_{\mathrm{loc}}(W))\).
\end{enumerate}

[Theorem T:polar of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] Under Assumptions (a:X of the paper), (a:var of the paper), and (a:SLND of the paper),

the following statements hold:
\begin{enumerate}
    \item[(i)] If there is a fixed point $z\in {\mathbb R}^d$ that is polar for $X$, then
\begin{equation}
 \int_0^{\delta_0} \frac {r^{N-1}}{\sigma^d(r)}\, dr  = \infty.
\end{equation}
    \item[(ii)] Under (equation sigma:gamma of the paper), condition (equation E:int:cond of the paper) implies that points are polar for $X$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 20 of arXiv:2608.11695, 'Generalised stochastic curvature flow in $d \geq 2$, and sharp interface limit for the sto'] Suppose $H \in \cC_b^7$. There exists $\theta>0$ such that for every realisation of the noise $\W$, we have
\begin{equation*}
    |X_t^\eps (x,u,p) - x| + |D_x X_t^\eps - \id| + |D_u X_t^\eps| + |D_p X_t^\eps| \lesssim t^\theta
\end{equation*}
uniformly over all $\eps$ and all $(x,u,p)$. Furthermore, for every multi-index $\gamma$, we have
\begin{equation*}
    \sup_{t \in [0,T]} \big| D_{\bm\theta}^\gamma \Theta_t^\eps - D_{\bm\theta}^\gamma \Theta_t \big| \lesssim d_\alpha (\W^\eps, \W)\;.
\end{equation*}
The proportionality constant depends on $T$ and $\gamma$ but is uniform over all $(x,u,p)$ and $\eps$.

[Prop eq:ST0_OP of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For ${\gamma} > - d_1$, let ${\alpha} = {\gamma} + d_1 -1$. Define 

\begin{equation} 
 {\mathsf Q}_{\bm j, \ell, m}^n(\bm x,\bm y) = \bm T_{\bm j, n-m}^{({\boldsymbol{\kappa}}, \alpha+2m)}(\bm y) (1-|\bm y|)^m 
      {\mathsf Y}_{\ell}^m \left(\frac{\bm x}{1-|\bm y|}\right). 
\end{equation}
Then $\{{\mathsf Q}_{\bm j, \ell, m}^n: |\bm j| = n-m, \, 1 \le \ell \le \dim {\mathcal H}_m^{d_1}, \, 0 \le m  \le n, \bm j \in {\mathbb N}_0^{d_2}\}$ 
is an orthogonal basis of ${\mathcal V}_n({\mathbb S}^{d_1-1}\!\! \rtimes \triangle^{d_2}, {\mathsf W}_{{\gamma}, {\boldsymbol{\kappa}}}^\triangle)$. Moreover, 
the norm square of ${\mathsf Q}_{\bm j, \ell, m}^n$ 
is given by 
\begin{equation} 
   {\mathsf h}_{m,n}^{{\gamma},{\boldsymbol{\kappa}}}  
       =   \frac{\bm b^\triangle_{({\boldsymbol{\kappa}},\alpha)}}{\bm b^\triangle_{({\boldsymbol{\kappa}}, \alpha + 2m)}} \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+ 2m), \triangle}
       = \frac{({\gamma} +d_1)_{2m}} {(|{\boldsymbol{\kappa}}|+ {\gamma} + d_1 + d_2)_{2m}} \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+ 2m), \triangle}.  
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

