[Corollary 64 of arXiv:2511.20322, 'Dissertation'] There exists a function $C \in G(\R^d)$, such that
	\[|\ph_t^h(x) - \ph_t^0(x)| \leq hC(x),\]
	for all $t\in [0,T], x\in \R^d$ and $h\in \lrates$. Consequently,
	\begin{align}

		|\E\ph_t^h(X_t^h) - \E\ph_t^0(X_t^h)| = \cO(h)
	\end{align}
	for all $t\in [0,T]$ and $h\in \lrates$.

[Lemma 15 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] For any $\varepsilon>0$,
		\begin{align*}
			\lim_{t\downarrow 0}\frac{1}{\mu(t)}\int_{\Omega_\epsilon}\P_x\left(\inf_{0\le s\le t} \phi(X_s)\le 0\right)dx =0
		\end{align*}

