[Prop base-change of arXiv:2608.26876, 'Local Bousfield classes via homological support'] Let $f^*\colon\cat T \to \cat S$ be a geometric functor of rigidly-compactly generated tt-categories and let $\varphi^h\colon\Spc^h(\cat S^c) \to \Spc^h(\cat T^c)$ be the induced map. For any~$\cat C \in \Spc^h(\cat S^c)$, the following statements hold:
	\begin{enumerate}
	\item	There is a split monomorphism $\EvarphiC \to f_*(\EC)$ in $\cat T$ which is a unital map of weak rings.
	\item	Consequently, for any $t \in \cat T$, we have
			\begin{align*}
				\EvarphiC \otimes t = 0 \quad&\Longleftrightarrow\quad f_*(E_{\cat C})\otimes t = 0, \text{ and}\\
				\ihom{\EvarphiC,t}=0 \quad&\Longleftrightarrow\quad \ihom{f_*(E_{\cat C}),t}=0.
			\end{align*}
	\item	For any $t \in \cat T$, we have
			\begin{align*}
				\Supphnaive_{\cat S}(f^*(t)) &= (\varphi^h)^{-1}(\Supphnaive_{\cat T}(t)), \text{ and}\\
				\Cosupp^h_{\cat S}(f^!(t)) &= (\varphi^h)^{-1}(\Cosupp^h_{\cat T}(t)).
			\end{align*}
	\item	Consequently, for any $t \in \cat T$, we have
			\begin{align*}
				\varphi^h(\Supphnaive_{\cat S}(f^*(t))) &= \Supphnaive_{\cat T}(t) \cap \im \varphi^h, \text{ and}\\
				\varphi^h(\Cosupp^h_{\cat S}(f^!(t))) &= \Cosupp^h_{\cat T}(t) \cap \im \varphi^h.
			\end{align*}
	\end{enumerate}

[Lem recur:upperBoundVector of arXiv:2607.09841, 'Mixing and cutoff for the systematic scan dynamics of the mean-field ferromagnetic Potts m'] Let $\{x_t = (x_t^{(1)},\dots,x_t^{(q)})\}_{t \geq 0}$ be a sequence of vectors in $\mathbb{R}_{\geq 0}^q$ such that for all $j \in Q$ and $t \geq n$, we have the recursion
\begin{align*}
x_t^{(j)} &=  \frac{\beta}{nq}\sum_{i = t-n}^{t-1} x_i^{(j)} +\frac{C}{n} \sum_{i = t-n}^{t-1}  \lVert x_i \rVert_2^2 + \frac{C}{n},
\end{align*}
where $C$ is a positive constant. Then, 
if for all $i \in \{0,\dots,n-1\}$ and all $j \in Q$, we have
$\lvert x_i^{(j)}\rvert \leq \rho$ for a small enough constant $\rho > 0$, then there exists constant $\hat C > 0$ such that
\begin{align*}
     \lVert x_t\rVert_2^2  \leq \hat C\rho^2 \gamma_n^{2t} + \frac{\hat C}{n},
\end{align*}
where $\gamma_n$ is the unique positive real root of the equation $ \sum_{i= 1}^n \gamma_n^{-i} = nq/\beta;$ 
see Section~(sec:recur of the paper) for additional details. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 (Operator-norm bound via Cauchy--Schwarz) of arXiv:2606.27774, 'Variational Formulas for the Spectrum of\\ Block Wishart Matrices'] Fix $\bZ\in\bbH_+^k$ and $\bS,\tilde\bS\in\bbH_+^k$ such that $\bF_\bZ(\bS),\bF_\bZ(\tilde\bS)$ 
are well-defined, and let $\bB,\tilde\bB\succ\bzero$.
For all integers $q\ge 1$,
\begin{equation}

\|\cuL_{\bS,\tilde\bS}^q\|_{\op\to\op}^2 
\le \|\bB\|_\op\|\bB^{-1}\|_\op\|\tilde\bB\|_\op\|\tilde\bB^{-1}\|_\op\cdot \Gamma_\bS(\bB)^q\,\Gamma_{\tilde\bS}(\tilde\bB)^q, 
\end{equation}
where 
\begin{equation}

\Gamma_\bS(\bB) := \Big\|\bB^{-1/2}\bF_\bZ(\bS)\int \bfeta(\bS,\bT)\,\bB\,\bfeta(\bS,\bT)^*\nu(\de\bT)\, \bF_\bZ(\bS)^* \bB^{-1/2}\Big\|_\op.
\end{equation}
Here $\|\cdot\|_{\op\to\op}$ is the operator norm on linear maps 
$(\C^{k\times k},\|\cdot\|_\op) \to (\C^{k\times k},\|\cdot\|_\op)$.

