body:
[Definition Slot configuration of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] A \emph{slot} is a pair of coordinates $(x,i) \in \mathbb{Z}^d \times \mathbb{N}$. The sequence of slots of the form $\{(x,i)\}_{i \geq 1}$ represents a stack of positions built over site $x$.
  A \emph{slot configuration} is an element
  \begin{equation}
    \sigma = (\sigma(x, i))_{x \in \mathbb{Z}^d, i \in \mathbb{N}} \in \{0, 1\}^{\mathbb{Z}^d \times \mathbb{N}},
  \end{equation}
  assigning to each slot either $0$ (vacant) or $1$ (occupied).
  Denote by $n(\sigma, x) = \sum_{i=1}^\infty \sigma(x, i)$ the number of particles placed in slots over $x$.

  A configuration $\sigma$ is called \emph{packed} if, for every $x \in \mathbb{Z}^d$, the occupied slots are exactly those at the bottom of the stack, that is,
  \begin{equation}
    \sigma(x, i) = \textbf{1}_{ \{ i \le n(\sigma, x) \} } = 
    \begin{cases}
      1, & i \le n(\sigma, x),\\
      0, & i > n(\sigma, x).
    \end{cases}
  \end{equation}
  Therefore, when $\sigma$ is packed, $n(\sigma, x)$ represents the \emph{height} of the stack of particles at $x$.
  Denote by $\Sigma_{\text{packed}} \subset \{0, 1\}^{\mathbb{Z}^d \times \mathbb{N}}$ the state space of all
  packed slot configurations. Given a configuration $\eta \in \mathbb{N}_0^{\mathbb{Z}^d}$, its \emph{canonical slot embedding} is the unique packed slot configuration $\sigma$ with $n(\sigma, x)=\eta(x)$, for every $x\in \mathbb{Z}^d$.

[Theorem th:gap-asymptotics1 of arXiv:2412.01489, 'One- and two-particle spectral gap identities for the symmetric inclusion process and rela'] For all graphs $G=(V,(c_{xy})_{x,y\in V})$ and   site weights $\hat\alpha = (\hat\alpha_x)_{x\in V}$,  we have
\begin{equation}
	\lim_{\varepsilon\to 0}	\frac{{\rm gap}_k(G,\varepsilon\hat\alpha)}{{\rm gap}_2(G,\varepsilon\hat\alpha)} =1\; \text{,}\;\;\qquad {k\ge 2}\; \text{.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 75 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\xi \in \bbr^m$ be arbitrary. An $\bbr^m$-valued continuous, adapted process $Y = (Y_t)_{t \in [0,T_0]}$ for some $T_0 \in (0,T]$ is called a \emph{local solution} to the Stratonovich SDE \eqref{SDE-Strat} with $Y_0 = \xi$ if
\begin{align*}
Y_t = \xi + \int_0^t f_0(s,Y_s) ds + \int_0^t f(s,Y_s) \circ dB_s, \quad t \in [0,T_0].
\end{align*}
If we can choose $T_0 = T$, then we also call $Y$ a \emph{(global) solution} to the Stratonovich SDE \eqref{SDE-Strat} with $Y_0 = \xi$.

[Prop of arXiv:2505.12127, 'Generalised principal eigenvalues and global survival of branching Markov processes'] For any $\sigma>0$ we have
\begin{equation}
    \limsup_{\sigma{\rightarrow} 0}\lambda_1'(L_0^\sigma)\leq -\frac{1}{2}.
\end{equation}
Moreover we have
\begin{equation}
\lambda_1''(L_0^\sigma)\geq \frac{7}{10}.   
\end{equation}
Therefore $\lambda_1'(L^\sigma_0)<\lambda_1''(L^\sigma_0)$ for all $\sigma>0$ sufficiently small. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 21 of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] Let $A$ be an abelian group. Then
\begin{enumerate}
    \item for any multicrossing $2$-cocycle $\theta$ with coefficients in $A$ the value $I_\theta(L)=\theta(\sigma_2(L))$ is invariant;
    \item for any negative multicrossing $3$-cocycle $\theta$ with coefficients in $A$ the value $I_\theta(L)=\theta(\sigma_3(L))$ is invariant;
    \item for any positive multicrossing $4$-cocycle $\theta$ with coefficients in $A$ the value $I_\theta(L)=\theta(\sigma_4(L))$ is invariant.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Def:Orey of arXiv:2512.06984, 'Infinite Dimensional Multifractal Analysis of the Wiener measure'] For $q \in ( 0  , 1) $, let $C_q^{\mathrm{crit}} $  be the set of \emph{critical $q$-Hölder functions} that is the set of $\bar{\omega} \in \Omega$ such that:
\begin{enumerate}
    \item  the function $ \bar{\omega} $ is $\alpha$-Hölder  for every $\alpha < q $, 
    \item the Hölder exponent of $ \bar{\omega}$ is at most $q$ in the sense that the following limit exists and equals $q$:
    \begin{equation} 
    \lim_{ n \to + \infty } \frac{ - \log \left\{  \sum_{i =1}^n \left[ \bar{\omega} \left(\frac{i}{n}  \right) - \bar{\omega} \left( \frac{i-1}{n} \right) \right]^2 \right\} }{2 \log n } = q \; . 
    \end{equation}
\end{enumerate}
We then introduce the set of \emph{critical Hölder functions} as 
\begin{equation*}
    \Omega^\mathrm{crit} := \bigcup_{ q \in (0,1) }  C_q^{\mathrm{crit}} \;. 
\end{equation*}

[Theorem 6 (EOT expansion) of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] Suppose $(\rho_t)_{t\in[0, 1]}$ satisfies Assumption~\ref{assump: density_expansion}.
Further assume that  there exists a constant $L_\rho\in(0, 1)$ such that $L_\rho \leq \rho_t(x) \leq L_\rho^{-1}$ uniformly holds for all $x\in\mb T^d$ and $t\in[0, 1]$. Following~\eqref{eqn:notation-ScB}, let
\begin{align}
\{(u_{t,k}, v_{t,k}): k=0,1,\cdots, K+1\} = \schro(\rho_t, \rho_t^{(1)}, \cdots, \rho_t^{(K+1)}).
\end{align}
Let $\alpha\in(0, 1)$ be any fixed number and $s = \lceil\frac{d+1}{2}\rceil$.
Then, for any fixed $K\in\mb N^\ast$, there exists $\varepsilon_0 > 0$ depending only  on 
\begin{align*}
\begin{cases}
  & \hbox{$\alpha$, $K$, $d$, $L_\rho$,  and}\\
  & \sup\big\{\|\rho_r^{(i)}\|_{H^{2j+s}}: r\in[t,t+\varepsilon], \,\,i,j\in\mb N,\,\, i+j\leq 2\big\},  
 \hbox{ and } \big\{\|\rho_t^{(K+2-i)}\|_{\m C^{s+2i,\alpha}}: i\in[K+2]\big\}, 
\end{cases}
\end{align*}

such that whenever $0\leq \varepsilon \leq \min\{\varepsilon_0, 1 - t\}$, we have
\begin{align}
\eot_{\varepsilon}(\rho_{t}, \rho_{t+\varepsilon}) = \varepsilon\int_{\mb T^d} \log\Big[\sum_{k=0}^K\varepsilon^k u_{t, k}\Big]\,\dd\rho_{t}  + \varepsilon\int_{\mb T^d}\log\Big[\sum_{k=0}^K \varepsilon^k v_{t,k}\Big]\,\dd\rho_{t+\varepsilon} +  O(\varepsilon^{K+1}).
\end{align}
Here, the big-O notation omits a constant depending  only on 
\begin{align*}
\begin{cases}
    & \hbox{ $d$, $\alpha$, $K$, $L_\rho$, and}\\
& 
\big\{\|\rho_t^{(K+2-i)}\|_{\m C^{2K+2i-2,\alpha}}: i\in[K+2]\big\}, \hbox{ and }

\sup\big\{\|\rho_r^{(i)}\|_{\m C^{2j}}: r\in[t, t+\varepsilon], \,\, i,j\in\mb N,\,\,i+j\leq K+1\big\}
\end{cases}.
\end{align*}
\myqed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thmhit of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] Let $T_n\coloneqq\inf\{s>0:\hat{M}(s)=n\}$ be the first-passage time of IGCP for any state $n\ge1$. Then, its distribution is given by
	\begin{align*}
		\mathrm{Pr}\{T_n\in\mathrm{d}s\}&=\sum_{j_0=1}^{k_0}\mu_{j_0}e^{-s\mu}\mathrm{d}s\sum_{m=1}^{n}\sum_{r=0}^{\infty}\sum_{\Omega(k,n-m)}\Big(\prod_{j=1}^{k}\frac{(r\lambda_{j})^{x_{j}}}{x_{j}!}\Big)e^{-r\lambda}\\ 
		&\hspace{4cm}\cdot  \sum_{\Omega(k,m)}\Big(\prod_{j=1}^{k}\frac{(j_0\lambda_{j})^{n_{j}}}{n_{j}!}\Big)e^{-j_0\lambda}\sum_{\Omega(k_0,r)}\prod_{j_0=1}^{k_0}\frac{(s\mu_{j_0})^{n_{j_0}}}{n_{j_0}!}.
	\end{align*}

