[Lem polyratber of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] For every $b\in\mathbb{N}$, 
there is a polynomial $s\in\mathcal{P}_{2bq}$ so that
$$
	\frac{1}{k!} 
	\|(\tfrac{1}{g_q}-s)^{(k)}\|_{[-\frac{1}{8q},\frac{1}{8q}]}
        \le 2^{-bq} (8q)^k
$$
for all $k\ge 0$. In particular, 
$\frac{1}{2}\frac{1}{g_q(x)} \le s(x) \le \frac{3}{2}\frac{1}{g_q(x)}$
for all $|x|\le \frac{1}{8q}$.

[Lem lemma:a_priori_estimates_1 of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] Let $\alpha > 0$, $\varrho \geq 1$, $\xi\in\mathbb{R}$ and $T\in (0,1)$.
	Let $q \colon [0,T] \to (0,\infty)$ be a function Lipschitz continuous on $[0,T]$, and differentiable on $[0,T]$ except at finitely many points.

	Then, the following holds.
	\begin{enumerate}
	    \item The function $t \in (0,T] \mapsto \mathopen{}\mathclose\bgroup\originalleft\lVertc(t)\aftergroup\egroup\originalright\rVert_2$ is decreasing; 

	    \item Let $\overline{c}(t) \coloneqq (0,c_2(t),c_3(t),\ldots)$. There exists $C=C(\alpha) > 0$ such that, for $0 < t_0 \leq t \leq T$,
	    \begin{align*}
	        \norme{\overline{c}(t)}_2 

	        &\leq \norme{\overline{c}(t_0)}_2 \exp\mathopen{}\mathclose\bgroup\originalleft(-\varrho(\lambda_1-\lambda_0) \int_{t_0}^t q(s)^{2/(2+\alpha)} \mathop{}\mathopen{}\mathrm{d} s \aftergroup\egroup\originalright) 
	    \\
	    & \quad + C \mathopen{}\mathclose\bgroup\originalleft\lVertc(t_0)\aftergroup\egroup\originalright\rVert_2 \int_{t_0}^t \frac{\mathopen{}\mathclose\bgroup\originalleft\lvertq'(s)\aftergroup\egroup\originalright\rvert}{q(s)} \exp\mathopen{}\mathclose\bgroup\originalleft( -\varrho(\lambda_1-\lambda_0)\int_s^t q(r)^{2/(2+\alpha)} \mathop{}\mathopen{}\mathrm{d} r \aftergroup\egroup\originalright) \mathop{}\mathopen{}\mathrm{d} s.
	    \end{align*}
	\end{enumerate}

