    \|\nabla w_\varepsilon(\cdot,t)\|_{L^{\theta}(\Omega)}\leq C(\theta)\cdot(1+ \sup\limits_{t>0}\|u_\varepsilon(\cdot,t)\|_{L^{\frac{3}{2}}(\Omega)})~~\mbox{for all}~~t>0.
\end{equation}

