&\leq ...","release_manifest_digest":"sha256:84886bf857838a8aaa415c3dee6a4dda2bdff60392b1fb51569f85c47b4b805a","revision_digest":"sha256:4227461f942990b9fe65c57291546b4fe356d209f7de2292f061cfab8355c86b","source_id":"arxiv:2609.02607","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

