[Defi global_markov_transform of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] [Global Markov transform]
		Let $E$ be a Polish space and $P$ a probability measure on $E^\mathbb{R}.$ \begin{enumerate}
			\item We say that $P$ admits a weak global Markov transform if there exists a Markov measure $P'$ on $E^\mathbb{R}$ and $(R_n)_{n \geq 1} \in \mathcal{A}$ such that $ P_{[R_n]} \xrightarrow[n \to + \infty]{\textnormal{f.d.}} P'.$ We say that $P'$ is a weak global Markov transform of $P.$
			\item We say that $P$ admits a strong global Markov transform if there exists a Markov measure $P'$ on $E^\mathbb{R}$ such that for every  $(R_n)_{n \geq 1} \in \mathcal{A} $, we have $P_{[R_n]} \xrightarrow[n \to + \infty]{\textnormal{f.d.}} P'.$ We say that $P'$ is the strong global Markov transform of $P.$
		\end{enumerate}

[Lemma thm9.7 of arXiv:2411.11393, '\fontsize{16}{19} \selectfont On differentiability of reward functionals corresponding to '] Let $Y=(Y_t)_{t\in [0,\infty)}$ be a standard process with continuous paths and values in an interval $J\subset \mathbb{R}$. Let $A$ be the weak infinitesimal operator of $Y$ and $\psi:J \to [0,\infty)$ a bounded measurable function with the property $\mathbb{E}_{\mathpalette\mathpalette\mathpalette\bigcdot@{.6}@{.6}@{.6}}[\psi(Y_t)]\to \psi$ weakly for $t\searrow 0$. We set $\varphi:=(\varphi_t)_{t\in[0,\infty)}$,
    \begin{align*}
        \varphi_t:= \int_0^t \psi(Y_s)ds, \quad t\ge0.
    \end{align*}
    Let $\tilde A$ denote the weak infinitesimal operator of the transition function $\tilde \mathbb{P}$ given by
    \begin{align*}
        \tilde \mathbb{P}(t,x,\Gamma) := \mathbb{E}_x[\mathds{ 1 }_{{\Gamma}}(Y_t) e^{-\varphi_t}], \quad t\ge 0, x\in J, \Gamma \in \mathcal{B}(J).
    \end{align*} Now 
    \begin{align*}
        \mathcal{D}_{\tilde A}\cap \ccc^0(J)\cap \B(J) = \mathcal{D}_{A}\cap \ccc^0(J) \cap \B(J)
    \end{align*} and 
    \begin{align*}
        \tilde A f = A f - \psi f
    \end{align*} for all $f\in  \mathcal{D}_{\tilde A}\cap \ccc^0(J)\cap \B(J)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 48 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $(f_1^-,f_1^+) \in \mathcal{B}_2$ and $c_1 \in (0,1)$. Define\footnote{$h_k$ is at definition~\ref{hkdefinition}.}
\begin{align*} 
H^1 &:= \big\{ t \in [0,\infty)\  \big| \ \forall t' \in [0,t), h_1(t') < h_1(t)\big \} \\ 
    & \ \ \cup \big\{ t \in (-\infty,0] \ \big| \ \forall t' \in (t,0], h_1(t')<h_1(t) \big\} \\
G^1 &:= \overline{H^1} \cup \{0\}.
\end{align*}
Write $\widetilde{X}_1^+(s) = \sup {f_1^+}^{-1}[1-s,1], \ \forall s \in(0,1)$. Then
\begin{equation}
   \sup_{t \in [0,\widetilde{X}_1^+(s)]} h_1(t) = h_1\big(\sup G^1_{\leq \widetilde{X}_1^+(s)}\big), \ \forall s \in (c_k,1).
\end{equation}

[Theorem Theo1 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold and  let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C5 of the paper). Then, as $t \rightarrow \infty$, $t \in \mathbb{G}$, 
\begin{align}
 e^{-\frac{\alpha}{2}t} \mathcal{Z}_{t}^{\varphi-\mathbb{E}[\varphi]} \xrightarrow[]{\rm st} \left( \frac{W}{\beta} \int_{\mathbb{G}} \mathbb{E}[(\chi^{(\varphi,h)}(s))^{2}] e^{-\alpha s} \ell( {\rm d} s) \right)^{1/2} \mathcal{N},
\end{align}
\noindent where $\beta \in (0, \infty)$ is defined in (equation eq3 of the paper), $W$ is the limit of Nerman's martingale and $\mathcal{N}$ is a standard normal random variable independent of $\mathcal{F}$ (and thus of $W$). (Proof in the paper; no proof environment follows the statement in the TeX.)

