body:
[Defn 3 of arXiv:2608.16144, 'Central limit theorem in R\'enyi divergence for lattice random variables'] [Fourier transform on $h\mathbb{Z}$]
The  Fourier transform of  $f\in \ell^1(h\mathbb Z)$ is defined by
\begin{equation*}
\widehat f(t)=\sum_{k\in\mathbb Z} f(kh)e^{itkh},\quad t\in \left[-\frac{\pi}{h}, \frac{\pi}{h}\right). 
\end{equation*}
Here, $\ell^p(h\mathbb{Z})
=\left\{
f:h\mathbb{Z}\to\mathbb{C}:\sum_{k\in\mathbb{Z}} |f(kh)|^p<\infty\right\}$ for $1\leq p <\infty$.
The Fourier inversion formula is given by
\begin{equation*}
f(kh)=\frac{h}{2\pi}	\int_{-\pi/h}^{\pi/h}\widehat f(t)e^{-itkh} \,dt.
\end{equation*}

[Lemma 2 (Proposition 2.2 in \cite{Guan-Ma2003}) of arXiv:2609.02516, 'Power convexity of the torsion function on horo-convex domains in hyperbolic space'] Suppose that $W=(w_{\alpha\beta})$ is diagonal. For $k=1,2,\cdots,n$, we have
\begin{equation}}
\frac{\partial\sigma_k(W)}{\partial w_{\alpha\beta}}=\begin{cases}
\sigma_{k-1}(W|\alpha) & \mathrm{if}\ \alpha=\beta,\\
0 & \mathrm{if}\ \alpha\neq\beta,
\end{cases}
\end{equation}
and $$\frac{\partial^2\sigma_k(W)}{\partial w_{\alpha\beta}\partial w_{\gamma\delta}}=\begin{cases}
\sigma_{k-2}(W|\alpha\gamma) & \mathrm{if}\ \alpha=\beta,\gamma=\delta,\alpha\neq\gamma,\\
-\sigma_{k-2}(W|\alpha\gamma) & \mathrm{if}\ \alpha=\delta,\beta=\gamma,\alpha\neq\gamma,\\
0 & \mathrm{otherwise}.
\end{cases}$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LEM:GAP3 of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $Q \in \mathbb{Z}$ with $Q\ge 2$, and let $d>0$ be a large constant. Then there exists $c>0$  such that if $\phi \in \mathcal{C}_Q$ with $\phi(-\infty)=0$ and $\phi(\infty)=2\pi Q$ satisfies 
\begin{align}
\textup{dist}(\phi, \mathcal{M}_Q^{d\le \cdot<(1+\eta)d}):=\inf_{\substack{\xi_1,\dots,\xi_Q \in \mathbb{R} \\ d \le \min_{i \neq j}|\xi_i-\xi_j|<(1+\eta)d } }\| \phi-m_{\xi_1,\dots,\xi_Q}   \|_{L^2(\mathbb{R})}<\delta

\end{align}

\noindent
where $\frac 12 e^{-d} \ge c \cdot \delta$, then
\begin{align*}
E(\phi) \ge |Q| E_{\textup{kink}}+ c\cdot e^{-(1+\eta)d}.
\end{align*}

