body:
[Corollary cor:Ln-clt-appendix of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] If $\beta>-1$, then
\begin{equation}
        \frac{
        L_n-\dfrac{\phi_\beta(\infty)}{\mu_\beta}\log n
        }{
        \sqrt{
        \left(
        \dfrac{\phi_\beta(\infty)^2\tau_\beta^2}{\mu_\beta^3}
        -
        \dfrac{\phi_\beta(\infty)}{\mu_\beta}
        \right)\log n
        }}
        \xrightarrow{d}\mathcal N(0,1).
\end{equation}
At $\beta=-1$,
\begin{equation}
        \frac{
        L_n-\dfrac1{2\mu_{-1}}(\log n)^2
        }{
        \sqrt{
        \dfrac{\tau_{-1}^2}{3\mu_{-1}^3}(\log n)^3
        }}
        \xrightarrow{d}\mathcal N(0,1),
\end{equation}
where
\[
        \mu_{-1}=\zeta(2),
        \qquad\text{and}\qquad
        \tau_{-1}^2=2\zeta(3).
\]

