[Theorem thm:LotzKlatt of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] [[LotzKlatt], Th. 5.2 and Ex. 5.7]

 Let $  \mathscr  C = \{B_{ i};i\geqslant 1\}$ a random equivariant   fair partition such that each $ B_{ i}$ is a unit volume convex polyhedron. Let $ m\in \mathbb{N},n\geqslant n_{ m,d},\alpha  = 2(m + 1)-d$. Assume that 
\begin{align*}
 \mathbf E \left[
\text{\rm{diam}}(B_{ *})^{ \max(2 (m + 1) ,d)}
\right]<\infty ,
\end{align*}
and for each $ i$ let $ \mathsf{P}_{ m,n,B_{ i}}, i\geqslant 1$  be a point process that is a.s. a $ m$-averaging set for  $ B_{ i}$, independent conditionally on $  \mathscr  C$. Then, provided this construction is measurable,
\begin{align*}
 \mathsf{P} = \sum_{i}\mathsf{P}_{ m,n,B_{ i}}
\end{align*}
is a $ \alpha ^{  + }$-hyperuniform $ L^{ 2}_{ loc}$ stationary random measure, and corresponds to a hyperuniform simple point process   if a.s. $ \mathsf{P}_{ m,n,B_{ i}}\cap \mathsf{P}_{ m,n,B_{ j}} = \emptyset $ for all $ i\neq j$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 124 (Continuous one-frequency phase layer) of arXiv:2607.10813, '2607.10813'] Let $0\le\delta<1$ and $\eps>0$.  For every high dyadic shell $M\ge2$ and every
$\bm\eps\in\{\pm1\}^3$,
\begin{equation}
  \int_{\mathcal R_M(\xi)}
  \mathfrak m\!\left(\Omega_a^{\bm\eps}(\xi,r)\right)^{1-\delta}
  \dd r
  \lesssim_{\delta,\eps}M^{2+\delta+\eps},
  \qquad M\gtrsim\la\xi\ra.
\end{equation}
The implicit constant is uniform in $a\in\mathfrak C$ and locally uniform in the parameter vector.

[Prop 9 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that Hypotheses \ref{H0}, \ref{H0.5} and \ref{H1} hold and let $\vartheta\in [0,1)$. For every $n\in\N$,  $\varphi\in C_b^\vartheta(H_n)$, $t>0$ and $x,h,k\in H_n$ we have
\begin{align}
&|\scal{\nabla(R_n(t)\varphi)(x)}{h}_{H_n}|\leq \|e^{tA_n}h\|_{H_n}^\vartheta \|\Gamma_{t,n}h\|^{1-\vartheta}_{H_n}\|\varphi\|_{C^\vartheta_b(H_n)},\\
&|D^2(R_n(t)\varphi)(x)(h,k)|\leq 2^{(1-\vartheta)/2}\|e^{tA_n}k\|_{H_n}^\vartheta\|\Gamma_{t,n}k\|_{H_n}^{1-\vartheta}\|\Gamma_{t,n}h\|_{H_n}\|\varphi\|_{C^\vartheta_b(H_n)},
\end{align}
where we set $C^0_b(H_n)=C_b(H_n)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $l \in \n$ and $\delta > 0$. Then for any $\varphi\in \hatMsetl$ the following implication holds
  \begin{equation}
   (x,m) \in \varphi \implies m > - l ^{\frac{2}{d+\delta}}(\norm{x}+1)^\frac{2d}{d+\delta}.
\end{equation}
Furthermore, denote $k(l) \coloneqq \frac{1}{2} \cdot 2^{\frac{d+\delta}{\delta}} \cdot l^{\frac{1}{\delta}} $, then for all $k \geq k(l)$ we have that
 \begin{equation}
    (x,m) \in \varphi \cap (((2k+1)B^d)^c\times\R) \implies m \geq -(\norm{x}-k)^2.
\end{equation}

