[Proposition prop:QGn_conditional_lower of arXiv:2605.16086, 'Loop pruning and downward deviations for maximum local time of discrete-time simple random'] For the same \(b<1-\beta\) as in Proposition~(prop:Nn_small of the paper), and for every \(n\in\mathbb{N}^+\),
\begin{equation}
\mathbb{P}(G_n\,|\,\mathcal{N}_n\le n^b,\,\xi^*(S'[0,u_n])\le \Lambda_n)\ge \gamma^{n^b}.
\end{equation}

[Theorem 16 (Gaussian perturbation comparison) of arXiv:2607.20329, '2607.20329'] Let $Z\in\mathbb K^{n\times n}$ be an arbitrary random matrix independent
		of a standard $\mathbb K$-Ginibre matrix $G_n^{\mathbb K}$.  Then, for
		every $w\in\mathbb K$ and $s\ge0$,
		\begin{equation}
			\E e^{-s|\per_{\mathbb K}(Z+G_n^{\mathbb K})-w|^2}
			\le
			\E e^{-s|\per_{\mathbb K}G_n^{\mathbb K}|^2}.
		\end{equation}
		Moreover,
		$\per_{\mathbb K}(Z+G_n^{\mathbb K})/\sqrt{n!}$
		has a density $q$ satisfying
		\begin{equation}
			\|q\|_\infty\le p_n^{\mathbb K}(0)\le\kappa_{n,\beta}.
		\end{equation}
		Consequently,
		\begin{equation}
			\sup_{w\in\mathbb K}
			\Pp\left(
			|\per_{\mathbb K}(Z+G_n^{\mathbb K})-w|
			\le\varepsilon\sqrt{n!}
			\right)
			\le
			\min\{1,\omega_\beta\kappa_{n,\beta}\varepsilon^\beta\}.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 24 of arXiv:2608.15379, 'Stochastic Jacobi fields along discontinuous martingales on Riemannian submanifolds'] Let $(E,h)$ be a compact connected Riemannian manifold.
Let $(\cE,\cF)$ be the Dirichlet form on $E$ associated with an isotropic L\'evy process given in Subsection \ref{Levymfd} and assume that $(\cE,\cF)$ has a Brownian part with coefficient $\sigma>0$.
Let $\cH_i$ ($i=1,\dots l$) be Killing vector fields on $E$.
Assume that $u$ is $\cE$-harmonic on the whole space $E$ and satisfies the assumptions of \tref{DiffHarmonic} with $\cH=\cH_i$ for each $i=1,\dots,l$.
We set $X:=u(Z)$, $J_i:=\cH_iu(Z)$, $\bJ_i:=(X,J_i)$. Fix a bounded $\bV_0$ and let $\cV$ be the solution of \eqref{parallel}.
Fix $T>0$. For each $\mathbb{R}^l$-valued \cl $\{\cF_t^Z\}_{t\geq 0}$-adapted process $K$ with a deterministic initial value such that $K$ has almost surely absolutely continuous paths and $\int_0^T|\dot{K_t}|^2dt<\infty$, we set
\begin{align*}
I_t&:=\int_0^t \lambda_g(\cV_{s-})\, d^{\gamma}X_s,\\

L^K_t&:=\frac{1}{\sigma}\int_0^t \dot{K^i}_s\lambda_h(\cH_i)(Z_{s-})\, dZ^c_s,
\end{align*}
where $\lambda_h \colon TE \to T^*E$ is the bundle isomorphism associated with the metric $h$ and $dZ^c$ stands for the continuous local martingale part of $d^{\gamma'}Z$ for some connection rule $\gamma'$ on $E$, which does not depend on the choice of $\gamma'$.
We set $Y_t:=g(\cV_t, K^iJ_{i,t})$. Then for q.e. $z\in E$, the process
\begin{align}
Y_t-Y_0- L^K_tI_t + \frac{1}{2} \int_0^tg(\cV_s, R_M^{\nabla}(K^i_s J_{i,s},dX^c_s)dX^c_s ) + \sum_{0<s\leq t}\langle \II( \cV_{s-} , K^i_s J_{i,s-}), \gamma^{\perp}(X_{s-},X_{s}) \rangle_{\delta_{\mathbb{R}^d}}
\end{align}
is a $(\Prob_z,\{\cF_t^Z\}_{t\geq 0})$-local martingale. Moreover, if $K$ satisfies
\begin{align}
\Ex_z\left[ |K_0|^2+\int_0^T|\dot{K_s}|^2 ds \right]<\infty,
\end{align}
and $K_T=0$ a.s., then the process \eqref{IBPmart} is a true martingale and
\begin{align}
\Ex_z\left[ g(\bV_0, K_0^i\cH_iu(z)) \right]&=\Ex_z \left[ -L^K_TI_T + \frac{1}{2} \int_0^T g(\cV_t, R_M^{\nabla}(K^i_t J_{i,t},dX^c_t)dX^c_t )\right. \nonumber\\
&\h \left.+ \sum_{0<t \leq T}\langle \II( \cV_{t-} , K^i_t J_{i,t-}), \gamma^{\perp}(X_{t-},X_{t}) \rangle_{\delta_{\mathbb{R}^d}} \right].
\end{align}

