[Proposition prop:mainZKROK of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] Let $\mathcal{X}_1\randin C^\infty\left(M,\mathbb{R}^{k_1}\right),\ldots,\mathcal{X}_n\randin C^\infty\left(M,\mathbb{R}^{k_n}\right)$ be independent admissible random fields such that $k_1+\cdots+k_n=m$ and let $U\subset M$ be an open set, we have:
  \begin{equation}
    \mathbb{E}\#\mathcal{S}\left\{\mathcal{X}_1,\ldots,\mathcal{X}_n;U\right\}=\int_U\ell(\zeta_{\mathcal{X}_1}(x)\wedge\cdots\wedge \zeta_{\mathcal{X}_n}(x)) \mathrm{d} M(x).
  \end{equation}
  In the case where $n=m$ and $k_1=\cdots,k_n=1$, we get
  \begin{equation}
    \mathbb{E}\#\mathcal{S}\left\{\mathcal{X}_1,\ldots,\mathcal{X}_n;U\right\}=m!\int_U\MV(\zeta_{\mathcal{X}_1}(x),\ldots, \zeta_{\mathcal{X}_m}(x)) \mathrm{d} M(x),
  \end{equation}
  and in particular if $\mathcal{X}_1,\ldots,\mathcal{X}_m$ are identically distributed:
  \begin{equation}
    \mathbb{E}\mathbb{S}\left\{\mathcal{X}_1;U\right\}=m!\int_U\vol(\zeta_{\mathcal{X}_1}(x)) \mathrm{d} M(x)
  \end{equation}
  where the volume and mixed volume are computed in the metric given by the Riemannian structure. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2609.03195, 'Lecture hall polytopes and\\Lakshmibai-Seshadri paths'] \begin{itemize}
\item[(i)] The monoid $\Pi(b)$ of L-S paths is saturated in $L(b)$, i.e. if $\pi\in L(b)$ and $k\pi\in\LS(b)$ for some non-negative integer $k$ then $\pi\in\LS(b)$.
\item[(ii)] If $\pi,\eta\in\LS(b)$ and $\pi - \eta\in\RR^{n+1}_{\ge0}$ then $\pi - \eta\in\LS(b)$.
\item[(iii)] If $\pi\in \LS(b)_k$ then there exists a unique decomposition $\pi = \pi_1 + \cdots + \pi_k$, with $\pi_i\in\LS(b)_1$ for $i=1,\ldots,k$, such that $\max\supp\pi_j\leq \min\supp\pi_{j+1}$ for $j=1,\ldots,k-1$. In particular, $\LS(b)$ is a normal monoid.
\end{itemize}

