[Lemma bounded_ratio_vertices of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Let $\varepsilon > 0$. There exists a constant $C_{\varepsilon} > 0$ such that for all $g \ge 0$ and $n \ge 2g-1$ with $\frac{g}{n} \le \frac{1}{2} - 4\varepsilon$ and for all $p_1,\dots,p_{\ell} \ge 1$ with $|\mathbf{p}| \le \varepsilon n$,
\begin{align*}
    1 \le \frac{\tau_{\mathbf{p}}(n+1,g)}{\tau_{\mathbf{p}}(n,g)} \le C_{\varepsilon},
\end{align*}
and
\begin{align*}
    C_\varepsilon^{-1} \le 
    \frac{\tau_{(p_1 + 1, p_2, \dots, p_{\ell})}(n,g)}{\tau_{(p_1, p_2, \dots, p_{\ell})}(n,g)} 
    \le 1.
\end{align*}

[Theorem thm_1.2 of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For any $d\ge 3$ with $d\neq 6$ and for any $\epsilon>0$, there exist constants $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d), 
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d,\epsilon), 
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d,\epsilon)>0$ such that for any $M\ge 1$ and $N\ge \ensuremath{C_{\ref*{const_typical_volume_1}}}M$, 
\begin{equation}
	\widehat{\mathbb{P}}_{d,N}\big(\ensuremath{c_{\ref*{const_typical_volume_3}}}M^{(\frac{d}{2}+1)\boxdot 4}  \le  \mathcal{V}_{M}^{\ge 0} \le \ensuremath{C_{\ref*{const_typical_volume_2}}}M^{(\frac{d}{2}+1)\boxdot 4} \big)\ge 1-\epsilon.
