[Theorem 5 of arXiv:2608.05679, 'Small ball probabilities and Chung's law of the iterated logarithm for Gaussian Volterra p'] Under Condition \eqref{eq constant cond}, there exist  constants
$\kappa_6,\kappa_7\in(0,\infty)$ such that
\begin{equation*}
\liminf_{t\to0^+}
\sup_{0\le s\le t}
\frac{(\log\log t^{-1})^{\gamma+\frac32}}
{t^H}|X(s)|
=
\kappa_6,
\qquad\text{a.s.,}
\end{equation*}
and
\begin{equation*}
\liminf_{t\to\infty}
\sup_{0\le s\le t}
\frac{(\log\log t)^{\gamma+\frac32}}
{t^H }|X(s)|
=
\kappa_7,
\qquad\text{a.s.}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:psd-width of arXiv:2608.10184, 'The sharp SAT/UNSAT phase transition in random ellipsoid fitting'] Let $d \ge 1$, let $Z$ be a standard Gaussian in $\mathsf{S}^{d}$, and write $Z = Z_+ - Z_-$ for its spectral decomposition into positive and negative parts.  Then,
\begin{equation}
\delta(\mathsf{S}^{d}_+) = \mathbb{E} \|Z_+\|_{\mathrm{F}}^2 = \frac{D_d}{2} = \frac{d(d+1)}{4} .
\end{equation}
Consequently, 
\begin{equation}
\sqrt{\frac{D_d}{2} - 1}
\le w\bigl(\mathbb{S}^{+}_{\mathrm{F}}(d)\bigr) \le \sqrt{\frac{D_d}{2}}\,,
\qquad
w\bigl(\mathbb{S}^{+}_{\mathrm{F}}(d) \bigr) = \frac d2 + O(1) .
\end{equation}

[Definition 77 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Let $u \in \rU$ be arbitrary but fixed. We define a function  $\varphi^u: [0,\infty) \times V \to \mathbb{C}$ by  
  \begin{equation*}

      \varphi^u(s,X)= i \duality{\Lambda(s,X)}{u}{\rU}{\rU^\prime} - \frac{1}{2} \,\duality{Q(s,X) u}{u}{\rU}{\rU^\prime}, \; \;s\geq 0, \;\; X \in V.
  \end{equation*}

[Theorem thm:BCbound of arXiv:2607.10801, 'Relaxation times of non-reversible\\ Markov processes'] Suppose that there exist constants $B,C\in[0,\infty)$ such that 
    \begin{equation}
        \norm{\overline P_tf}\ \leq\ C\norm{\mathcal{L}\overline P_tf} + \frac{B}{t}\norm{f}\qquad\text{for all }f\in L_0^2(\mu)\text{ and }t>0\,.
    \end{equation}
    Then 
    \begin{equation*}
        \norm{\overline P_t f}\ \leq \ \frac{2C+B}{t}\norm{f}\qquad\text{for all }f\in L_0^2(\mu)\text{ and }t>0\,.
    \end{equation*}
    In particular, $\overline t_\mathrm{rel}(P)\leq (2C+B)e$.

