[Theorem 5 (Finite-time convergence of the unnormalized latent recursion) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose Assumptions~\ref{assump:mdp}, \ref{assump:mix},
\ref{assump:stable_kernels}, and \ref{assump:stepsizes} hold. Moreover, choose $\alpha_{\mrm U}c_\wedge(1-\gamma)=:\lambda_\mrm U>1$ and set 
\begin{equation}
        \epsilon_n^{\mrm U}
        := \sqbk{(n+n_0^\mrm U)\crbk{ 2L_{0,\rho} + 5L_{\kappa,\rho}} \log\!\crbk{
        \frac{5 (n+n_0^{\mrm U})}{n_0^{\mrm U} }}}\inv.

\end{equation}
Then, for every $\delta\in(0,1)$,  with probability at least $1-\delta$, 
\begin{equation}
\begin{aligned}
        \norm{\theta_n^{\mrm U}-\theta^*}&\le
        \frac{3}{1-\gamma}
        \sqbk{\frac{17 n_0^{\mrm U}}{n+n_0^{\mrm U}}}^{\lambda_{\mrm U}} +
        \frac{328\tmix}{c_\wedge (1-\gamma)^2}
        \sqbk{
        \sqrt{\frac{\alpha_\mrm U(\cL_n^\mrm U(\delta) + \log\cN_\rho(\epsilon_n^\mrm U))}{n+n_0^{\mrm U}}}
        +
        \frac{\alpha_{\mrm U}^{2}}{(\lambda_{\mrm U}-1)(n+n_0^{\mrm U})}}
\end{aligned}

\end{equation}
simultaneously for all $n\ge 16\alpha_\mrm U$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 (Endpoint estimates in the low-parameter rectangle) of arXiv:2608.30304, '2608.30304'] Let $n\ge1$ and $\alpha,\beta\in[-\tfrac12,A_0]$. If
\begin{equation}
1+x\le\frac2{(n+1)^2}\qquad\text{or}\qquad 1-x\le\frac2{(n+1)^2},
\end{equation}
then $F_{n,\alpha,\beta}(x)\le24$.

[Definition e.Stratification of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] We say that ${\mathbb G}$ is a \emph{Carnot group} of step $k$ if ${\mathbb G}$  is a connected and simply connected Lie group whose Lie algebra $\mathfrak{g}$ is \emph{stratified}, that is, there are non-trivial linear subspaces $V_1,\ldots, V_k$ of $\mathfrak{g}$ such that
\begin{align*}
\mathfrak{g}=V_{1}\oplus\cdots\oplus V_{k},
\end{align*}
and
\begin{align}
& \left[V_{1}, V_{i-1}\right]=V_{i},\hskip0.1in  V_{i} \neq \{0\}, \hskip0.1in 2 \leqslant i \leqslant k,
\notag
\\
& [ V_{1}, V_{k} ]=\left\{ 0 \right\}.
\end{align}

[Proposition 21 (Sample exchangeability from exchangeable measures) of arXiv:2607.18201, 'Finding Adam in noisy trees'] Let $\mu:\cT^* \to \cP(\cT^*)$ be measurable. Given $(\bt,o)\in\cT^*$, we denote the image of it under $\mu$ as $\mu_{(\bt,o)}$. Fix $r\geq 1$. Conditionally on $((\cT_n(1;E_r),1),\dots,(\cT_n(r;E_r),r))$, let $(\sT_1,\dots,\sT_r)$ be a vector of random trees with law
    \begin{align*}
        \mu_{(\cT_n(1;E_r),1)}\times \dots \times \mu_{(\cT_n(r;E_r),r)}, 
    \end{align*}
    i.e., the trees $\sT_i$ form a conditionally independent collection, given $((\cT_n(1;E_r),1),\dots,(\cT_n(r;E_r),r))$, where $\sT_i$ has marginal law $\mu_{(\cT_n(i;E_r),i)}$ for each $i\in [r]$. Then, the vector $(\sT_1,\dots,\sT_r)$ is exchangeable.

