\sup_{0\le\theta\le1}
\bigg|
\frac{\partial^N}{\partial\theta^N}L_\theta(t)
\bigg|
\nu^{\otimes r}(\mathrm d t)
\le
C p^r (a^2\delta)^N \,.
\end{equation}

