body:
[Theorem thm:resultunknownmask of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Consider any fixed $p \in (0,1)$. Then, the following holds whenever $d \gg \log(n)^3$.

    \vspace{0.5em}
    If $p \neq \frac{1}{2}$ then:\hspace{1em} $\begin{aligned}[t]
            \dtv{\mathbb{W}(n, m, q, p, d)}{ \mathbb{M}(n, m, p)} &= \begin{cases} 1 - o(1) & \text{if } d \ll nmq^4  \hspace{1.3cm} \text{ or } \hspace{.1cm} d \ll m\sqrt{n}q^2   \\
            o(1) & \text{if } d \gg nmq^4\log(n) \hspace{.1cm} \text{ and } \hspace{.1cm} d \gg m\sqrt{n}q^2 \log(n)
            \end{cases}
        \end{aligned}$

    \vspace{0.5em}
    If $p = \frac{1}{2}$ then:\hspace{1em} $\begin{aligned}[t]
            \dtv{\mathbb{W}(n, m, q, p, d)}{ \mathbb{M}(n, m, p)} &= \begin{cases} 1 - o(1) & \text{if } d \ll nmq^4 \\
            o(1) & \text{if } d \gg nmq^4\log(n)
            \end{cases}
        \end{aligned}$

    \vspace{0.5em}
    \noindent Here, $o(1)$ denotes a function that tends to zero as $n \rightarrow \infty$. Recall further that $m \ge n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lambda close then also w close of arXiv:2603.17858, 'Decay of correlations and zeros for the hard-core model'] Given $\lambda >0$, $C>0$ and $\alpha\in(0,1)$ there exists $C'>0$ such that the following holds. Given sequences $(\lambda_n)$ and $(\widehat\lambda_n)$ in $(0,\lambda]$ satisfying $|\lambda_n-\widehat\lambda_n|<C\alpha^n$ for all $n\in \mathbb N$, the associated orbits $(w_n)$  and $(\widehat w_n)$ satisfy
    \begin{equation*}
        |w_n-\widehat w_n|\leq C' \alpha^n\quad\text{for all }n\in \mathbb N.
    \end{equation*}

[Definition 6 of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] For strict partitions $\mu,\lambda$ with $\mu\subseteq\lambda$, set
\begin{equation}
        K_X^Y(\mu,\lambda)
        =\frac{Q_{\lambda/\mu}(X)P_\lambda(Y)}{\Ht(X;Y)P_\mu(Y)}.
\end{equation}
If $\mu\nsubseteq\lambda$, set $K_X^Y(\mu,\lambda)=0$.

[Defn 4 of arXiv:2607.04730, 'Variance gamma approximation to sums of triplewise independent random variables'] The VG distribution with parameters $r>0$, $\theta\in\mathbb{R}$, $\sigma>0$, $\mu\in\mathbb{R}$ has probability density function
\begin{equation}
p(x)=\frac{1}{\sigma\sqrt{\pi}\,\Gamma\!\left(\frac{r}{2}\right)}
e^{\frac{\theta}{\sigma^{2}}(x-\mu)}
\left(\frac{|x-\mu|}{2\sqrt{\theta^{2}+\sigma^{2}}}\right)^{\frac{r-1}{2}}
K_{\frac{r-1}{2}}
\left(
\frac{\sqrt{\theta^{2}+\sigma^{2}}}{\sigma^{2}}|x-\mu|
\right),
\end{equation}
with support $\mathbb{R}$. Here $K_{\nu}(x)$ is a modified Bessel function of the second kind, defined by $K_{\nu}(x)=\int_{0}^{\infty} e^{-x\cosh(t)}\cosh(\nu t)\,dt.$ For a rv $Z$ with density \eqref{den:VG}, we write $Z\sim \mathrm{VG}(r,\theta,\sigma,\mu)$.

[Lemma 16 (Scalar Cauchy information-estimation identity) of arXiv:2608.11031, 'A Bayesian Proof of the Bernoulli Theorem'] Let $U$ be a finitely supported real random variable, let $S$ be an arbitrarily distributed random variable, and let $Z$ be standard Cauchy and independent of
$(U,S)$.  Define
\begin{equation}
  F(t):=I(U;U+tZ\mid S).

\end{equation}
Then $F$ is decreasing and convex on $(0,\infty)$, with
$\lim_{t\to\infty}F(t)=0$.
Moreover, let $U_t^{(1)},U_t^{(2)}$ be i.i.d.\ draws from the
posterior of $U$ given $(S,U+tZ)$.  Then
\begin{equation}
  F''(t)
  \le
  \frac{2}{t^2}
  \E\left[
    1\wedge
    \frac{|U_t^{(1)}-U_t^{(2)}|^2}{t^2}
  \right].

\end{equation}
Consequently,
\begin{equation}
  -F'(t)
  \le
  2\int_t^\infty
  \frac{1}{s^2}
  \E\left[
    1\wedge
    \frac{|U_s^{(1)}-U_s^{(2)}|^2}{s^2}
  \right]ds.

\end{equation}

[Corollary 19 (Gaussian dense-sampling limit) of arXiv:2608.17927, 'Near-unit-root persistence of symmetric stable \\ autoregressive sequences'] For $\alpha = 2$,
\begin{equation}

\lim_{h \downarrow 0}\frac{\lambda_{2}(h)}{h} = \frac{1}{2}, \quad
\lim_{a \uparrow 1}\frac{\Lambda(a,2)}{\log{(1/a)}} = 1.
\end{equation}

[Lemma lem:chain of arXiv:2608.09368, 'A proof of Ross's conjecture for two-site moving-target search'] Let $H,L\in\{1,2\}^n$ be a height-one pair.  Then $L$ can be
transformed into $H$ by a finite sequence of adjacent moves
\begin{equation}
 21\longrightarrow12

\end{equation}
and, if $\delta_n=1$, exactly one replacement
\begin{equation}
 2\longrightarrow1.

\end{equation}
The left prefixes at which all operations occur form a chain under
$\preceq$.  If the replacement (equation eq:replacement of the paper) occurs, it occurs
at a deepest prefix in that chain.

[Proposition thm:main-err-decomp of arXiv:2608.23554, 'Provably adaptive sampling with uniform and remasking \\ discrete diffusion models'] Let \(0 = t_0 < t_1 < \ldots < t_N \leq T\) be the time discretization. Recall \(s_t\), \(\widehat s_t\) from~(eq:score-func,eq:our-shat of the paper), and \(\widetilde s_t\) from~(def:wt-score of the paper). Then,
    \begin{equation*}
       \mathsf{KL}(q_{T - t_N} \| p_{\mathrm{output}}) \leq \mathsf{KL}(q_T \| q_{\mathrm{noise}}) + \sum_{k=0}^{N -1}\cL_{\mathrm{approx}}^{(k)} + \sum_{k=0}^{N - 1}\cL_{\mathrm{discr}}^{(k)}, 
    \end{equation*}
    where, for \(k \in \{0, \ldots, N - 1\}\), \(u = T - t_{k+1}\), and \(\ell = T - t_k\),
    \begin{equation}

    \cL_{\mathrm{approx}}^{(k)} \coloneqq \int_u^{\ell} \bE_{x_t, x_\ell \sim q_{t, \ell}} \left[ \sum_{y \neq x_t} Q_t(y, x_t) \widetilde s_t(y, x_t) D(\widehat s_t(y, x_t), \widetilde s_t(y, x_t))\right] \mathrm{d} t
    \end{equation}
    and
    \begin{equation}

    \cL_{\mathrm{discr}}^{(k)} \coloneqq \int_u^{\ell} \bE_{x_t, x_\ell \sim q_{t, \ell}} \left[ \sum_{y \neq x_t} Q_t(y, x_t)  s_t(y, x_t) D(\widetilde s_t(y, x_t), s_t(y, x_t))\right] \mathrm{d} t.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn def-ust of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] Let $G$ be a finite graph equipped with a conductance function $\mathfrak c : \mathcal E G \to (0,\infty)$. The \textbf{$\mathfrak c$-spanning tree} of $G$ is the random spanning tree $T\subset  G$ where, for each spanning tree $\mathfrak t$ of $G$,
\begin{equation}  
\mathbbm P\mathopen{}\mathclose\bgroup\originalleft[ T = \mathfrak t \aftergroup\egroup\originalright] = \frac{1}{Z} \prod_{e\in \mathcal E\mathfrak t} \mathfrak c(e) .
\end{equation} 
where $Z$ is a proportionality constant chosen to make this a probability measure.

[Theorem TSLNN of arXiv:2510.12480, 'Cyclic and alternating $U$-statistics'] We have, as \ensuremath{{n\to\infty}}, for any $f\in L^2$,
\begin{align}
  \frac{1}{\binom n2} U^{--}_n(f)\overset{\mathrm{a.s.}}{\longrightarrow} 0.
\end{align}
The same holds for $U^{-+}_n$ and $U^{+-}_n$.

[Corollary cor:mbdcII of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] Under the same setup as (prop:mbdc of the paper) except for that $J_\mathrm {II}$ is allowed to be non-empty, the estimate becomes
\begin{multline*}
\sum_{\vec r\in\mathscr B^h}|w(\vec r)|< \prod_{\ell=1}^m (2\sqrt{NN_\ell})^{k_\ell} N^{-|U|-|J|+\frac{1}{3}|J_\mathrm I|+\frac{1}{3}|J_\mathrm {II}| -\frac{1}{3}\bigl(|J_\mathrm {IV}|+|\{j\in J_\mathrm {IV}:\,\vartheta_j=\varnothing\}|+|J_\mathrm {VI.2}|+\max\{|J_\mathrm {VI.1}|,|J_\mathrm {VI.3}|\}+|J_\mathrm C|\bigr)}
\\
\times C_2^{\delta+1} \frac{h^{\delta- 2|U|}}{(\delta-2|U|)!}\exp(-C_3h^2) \big((|U|+1)\log(|U|+2)\big)^{|U|} \big(h/(|U|+1)\big)^{C_3|U|+m\mathbf{1}_{h\ge |U|}} \prod_{j\in J:\vartheta_j \ne \varnothing} \vartheta_j^{-3/2}.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:volQ'volQ of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] Let $Q$ be a positive definite quadratic form on $V^*$ and let $L\in Gl(V^*)$, then $Q\circ L$ is positive definite and we have:
  \begin{equation}
    \vol_{Q\circ L}=\frac{1}{|\det L|}\vol_Q.
  \end{equation}

