[Lemma lem:weld-blue-red of arXiv:2510.05850, 'Three-point connectivity constant for $q$-state Potts spin clusters'] Let $\kappa \in (8/3,4)$ and $\rho=\frac{3\kappa}{2}-6$. Let $\mu$ denote the law of $\mathcal{L}_{B \to R}$. Then there exists a measure $\mathrm{QA}(\rho)$ on the space of quantum surfaces with annular topology such that
    \begin{equation}
        \mathrm{QD}_{1,0} \otimes \mu = \int_0^\infty \mathrm{QA}(\rho;\ell) \times \ell\,\mathrm{QD}_{1,0}(\ell) \mathop{}\!\mathrm{d} \ell.
    \end{equation}

[Theorem thm:near-fittest-lowepi of arXiv:2508.12464, 'On the Fitness Landscape in the $\NK$ Model'] Assume $0<\alpha\le\alpha_*$. If $\beta<\beta_c,$ (equation eqn:Q-high-epi-hightemp of the paper) holds
	and if $\beta>\beta_c,$ we have that for any $0<\delta<c_1(\alpha),$
	\begin{align} 
		\limsup_{N\to\infty}\mathbb{E}\bigl\langle I(Q_{1,2}\in (0, c_1(\alpha)-\delta] \cup[c_2(\alpha)+\delta,1)\bigr\rangle_\beta=0.
	\end{align}
	Additionally, we have the following statements.
	\begin{enumerate}
		\item For any $0<\delta<c_1(\alpha),$ we have
		\begin{align}
			\begin{split}

				&\limsup_{N\to\infty}\mathbb{E}\,\overline{\kern-0.2em M\kern-0.1em }_{N,K}(\{Q_{1,2} \in (0, c_1(\alpha)-\delta] \cup[c_2(\alpha)+\delta,1)\})\\
				&\leq 2\lim_{N\to\infty}\mathbb{E} M_{N,K}-2\beta_c\Bigl(1-\sqrt{1-\frac{\delta(\Delta(\alpha)+\delta)}{2}}\Bigr).
			\end{split}
		\end{align}


		\item For any $0<\delta<1$ with $h(\delta)<2/(2-\alpha)$, we have
		\begin{align}
			\begin{split}
    &\limsup_{N\to\infty}\mathbb{E}\,\overline{\kern-0.2em M\kern-0.1em }_{N,K}(\{\delta<|R_{1,2}|<1\})\\
				&\quad \leq 2\lim_{N\to\infty}\mathbb{E} M_{N,K}-2\beta_c\Bigl(1-\sqrt{\frac{2-\alpha}{2}h(\delta)}\Bigr).
			\end{split}
		\end{align}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2609.02699, '\vspace{-0.5 cm}Gauge theory and symplectic structures'] There exists a constant $C>0$ depending only on $r$ and the geometry of $M$ such that if $(\phi,A,\beta)$ solves equations \eqref{Dirac 6d}, \eqref{Curvature 6d} then
\begin{align*}
    \|\phi\|_{C^0}^2\leq C(1+\|(F_A)^{1,1}_p\|_{C^0}+\|\beta\|_{C^0}^2)
\end{align*}

