[Theorem 4 of arXiv:2604.27205, 'An Analysis of the Diaconis-Holmes-Neal Markov Chain Sampler Under Generalized Unimodal Un'] If a chain $\Phi$ satisfies
	   \begin{equation}
		  P^m(x, A) \geq \nu_m(A)
	   \end{equation}
	   \noindent for all $x \in X$ and $A \in {\cal B}(X)$, then
	   \begin{equation}
		  ||P^n(x, \centerdot) - \pi|| \leq \rho^{\lfloor n/m\rfloor} 
	   \end{equation}
	   \noindent where $\rho = 1 - \nu_m(X)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:finitecollision of arXiv:2601.10624, 'Source localisation in simple random walks'] Suppose $\mathbb{H}$ is an infinite, connected, vertex-transitive, recurrent graph of finite degree. Further, let $a$, $b \in \mathbb{H}$ be such that the transition probability $p_{2j}(a, b)$ is positive for some $j \geqslant 0$, and consider two independent simple random walks $X_t$, $Y_t$ on $\mathbb{H}$. Then, we have
    \begin{equation*}
        \mathbb{P}(\exists t > 0 \colon X_t = Y_t \mid X_0 = a, Y_0 = b) = 1.
    \end{equation*}

