body:
[Lemma lem:Jordan2_upper_tail_lower_bound of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] For every $\varepsilon>0$ there exist positive constants $c=c(\varepsilon), \delta=\delta(\varepsilon)$ such that for all $n\geq 3$, all $v\in[ n/4]$, and all $S\in[1, \delta \left(n/v\right)^{1-\varepsilon}]$
    \begin{equation}
        \mathbb{P}\left(\widehat{\sigma}_2(v)\geq Sv\right) \geq  c \frac{1+\log(S)}{S^2}.
    \end{equation}
    Furthermore, there exist positive constants $S_0,c^\prime, \delta$ such that for all $n\geq 3$, all $v \leq n/4$ and all $S\in[S_0, \delta \tfrac{n}{v}]$,
    \begin{equation}
        \mathbb{P}\left(\widehat{\sigma}_2(v)\geq Sv\right) \geq  c^\prime \frac{1}{S^2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 13 of arXiv:2607.04012, 'Hölder regularity for backward stochastic Volterra integral equations and applications to '] Let $(\Psi, G)$ satisfy Assumption \ref{assumption-Holder-BSVIE}, and let $(Y, Z)$ be the unique solution to the BSVIE \eqref{eq:bsvie-intro}. Then there exists a version of $Z$ such that
    \begin{gather*}
        \mathbb E\bigg[
        \bigg(
        \int_0^{s\wedge r}
        |Z(t,s)-Z(t,r)|^2\,dt
        \bigg)^{\frac p2}
        \bigg]
        \leq K |s-r|^{\frac p2},
        \qquad s,r\in[0,T],
    \end{gather*}
    where $K>0$ is independent of $s$ and $r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:MassAlgebra of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Let~$\msR$ be any subalgebra of~$\mcB_b(\mbbI)$, and set
\begin{equation}
\msR_\epsilon\eqdef \left\{f\in\msR: \supp f \subset (\epsilon, 1]\right\}\,\mathrm{,}\;\, \qquad \epsilon\in\mbbI \,\mathrm{.}
\end{equation}

We say that~$\msR_0$ \emph{separates points from open sets} (\emph{in~$(0,1]$}) if for every~$s\in (0,1]$ and every open~$U\subset \mbbI \setminus\left\{s\right\}$ there exists a function~$\varphi_s\in \msR_0$ such that~$\varphi_s(s)\neq 0$ and~$\varphi_s\equiv 0$ on~$U$.

[Theorem 29 (History energy identity) of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] Let $a=1-2s\in(-1,1)$, and let $u_0\in\Sm$. Then
\begin{equation}
\|U_0\|_{L_a^2(\RN)}^2
=
\frac{2^{1-2s}}{\G(s)^2}
\int_{\Rd}\int_0^\infty
\omega^s|\mathscr G_\xi(\omega)|^2\,d\omega\,d\xi.
\end{equation}

[Theorem LLN of arXiv:2411.01731, '$L^2$-Wasserstein contraction of modified Euler schemes for SDEs with high diffusivity and'] Assume   $({\bf A}_0)$, $({\bf A}_1)$ and  $({\bf H}_1)$-$({\bf H}_5)$, and suppose further $({\bf A}_5)$ once $\beta $ involved  in $({\bf H}_5)$
satisfies  $\beta> 1/2.$
Then, for any $f\in\mathscr C_\rho$ $($given in (equation f1 of the paper)$)$, $\varepsilon\in(0,1/2)$, and $x\in\mathds R^d,$ there exist constants $C_0=C_0(x,\rho,\varepsilon,\|f\|_\rho),\sigma_0>0$ and a random time $N_{\varepsilon,\delta}=N_{\varepsilon,\delta}(x,\gamma,d)\ge 1$  such that for   $\delta\in(0,\delta_2^{\star\star}]$, $n\ge N_{\varepsilon,\delta}$, and the noise intensity $\sigma$ satisfying  $|\sigma|\ge\sigma_0,$
\begin{equation}
\bigg|\frac{1}{n}\sum_{k=0}^{n-1} f(X_{k\delta}^{\delta,x})-\pi_\8(f) \bigg|\le C_0 \big(n^{-{1}/{2}+\varepsilon}\delta^{-1/2}+\delta^{1\wedge \beta}{  d^{\frac{1}{2} (\ell_\star+  \rho) } }\big),\quad a.s.,
\end{equation}
where
$(X^{\delta,x}_{n\delta})_{n\ge 0}$  is determined by (equation E2 of the paper),    $\pi_\8$ represents the IPM of $(X_{t})_{t\ge 0}$ solving (equation E1 of the paper),  and  $\ell_\star$ was defined in (equation DD5 of the paper).
Moreover, for any $q>0,$ there is a constant $C_q^*>0$ such that
\begin{align}
	\mathbb E N_{\varepsilon,\delta}^q\le C^*_q\big(1+|x|^{2(1+\rho)} +d^{1+\rho}\big)^{\frac{q+2}{2\varepsilon}}.
\end{align}

