[Definition 55 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $\mathfrak{j}:=\lfloor (\frac12+\delta)\log_2 N\rfloor$ denote the largest integer such that $2^{\mathfrak{j}} \le N^{1/2+\delta}$. For each $j \in [0, \mathfrak{j}]$, let $a_j$ denote the minimal integer with $q_{a_j} < \max \{2^j N^{5000K\delta-1}, N^{M\delta-1} \}$; observe that the sequence $(a_j)$ is non-increasing in $j$. For each $j \in [0, \mathfrak{j}]$ and $i \in [0, a_j]$, define the sequence $\mathsf{T}_{i,j}$ inductively (starting at $(i,j) = (0, \mathfrak{j})$, and then increasing in $i \in [0, a_j]$ and decreasing in $j \in [0, \mathfrak{j}]$) by setting 
\begin{flalign*} 
	\mathsf{T}_{0,\mathfrak{j}} = N^{2 + M^2 \delta}; \quad \mathsf{T}_{i+1,j} = \mathsf{T}_{i,j} + q_i^{-2/3} N^{4/3 + M^2\delta}; \quad \mathsf{T}_{0,j} = \mathsf{T}_{a_{j+1},j+1},
\end{flalign*} 
observing that
\begin{eqnarray}

	\mathsf{T}_{i+1,j} = \mathsf{T}_{i,j} + \frac{q_i-q_{i+1}}{ q_i} \cdot N^{2+ (M^2+M) \delta}.  
\end{eqnarray}

[Lem 5 of arXiv:2604.13134, '\bf From Gaussian to Gumbel: extreme eigenvalues of complex Ginibre products with exact ra'] Let \( \widetilde{M}_{j, k}^{(n)}(x) \)  be defined as above, and let \( (Y_j)_{1\le j\le n} \) be the sequence of random variables given in Lemma \ref{ctor}. Let \( \Theta \) be a random variable, independent of \( (Y_j)_{1\le j\le n} \), following a uniform distribution on \( [0, \pi/2] \). Then, for \( 1 \le j \le n \),
\begin{equation}
\widetilde{M}_{j, j}^{(n)}(x) = \mathbb{P}\bigl( \log Y_{n+1-j} + \log \cos^2\Theta \ge k_n\psi(n) + \frac{\widetilde{a}_n + \widetilde{b}_n x}{\sqrt{\alpha_n}} \bigr)
\end{equation}
and \( \widetilde{M}_{j, k}^{(n)}(x) = 0 \) whenever \( j-k \) is odd. For even \( j-k \), 
\begin{equation}
\begin{aligned}
\widetilde{M}_{j, k}^{(n)}(x) &= \frac{2(\big( n-\frac{j+k}{2} \big)!)^{k_n}}{\pi \bigl( (n-j)! (n-k)! \bigr)^{k_n/2}} \\
&\quad \times \int_{0}^{\pi/2} \cos\bigl( (j-k)\theta \bigr) \, \mathbb{P}\bigl( \log Y_{n+1-\frac{j+k}{2}} + \log\cos^2\theta \ge k_n\psi(n) + \frac{\widetilde{a}_n + \widetilde{b}_n x}{\sqrt{\alpha_n}} \bigr) \, d\theta.
\end{aligned}
\end{equation}
Consequently, for $1\le j\neq k\le n,$ we obtain the estimate
\[
|\widetilde{M}_{j, k}^{(n)}(x)| \le \min\big\{\widetilde{M}_{\frac{j+k}{2}, \frac{j+k}{2}}^{(n)}(x), \sqrt{\widetilde{M}_{j, j}^{(n)}(x)\widetilde{M}_{k, k}^{(n)}(x)}\big\}.
\]

