body:
[Definition XY and XY/Villain models on a site percolation configuration of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] We fix an integer $L \in \ensuremath{\mathbb{N}}$, an integer $n \geq 2$, a pair of inverse temperatures $\beta_1 , \beta_2 > 0$, a percolation configuration $r \in \{0,1\}^{\Lambda_L}$, and introduce:
\begin{itemize}
    \item The XY model on the extended lattice $\ensuremath{\mathbb{Z}^d}_n$ on a percolation configuration:
\begin{multline*}
    \mu_{\Lambda_L^n, n, \beta_1 , \beta_2, r}^{\mathrm{XY}}(d\theta) := \frac{1}{Z_{\Lambda_L^n, n, \beta_1,  \beta_2, r }^{\mathrm{XY}}}\exp \left( \beta_1  \sum_{\substack{x \sim_n y \\ x \in  \ensuremath{\mathbb{Z}^d}}} r_x \cos (\theta_x - \theta_y)\right)\\  \times \exp \left( n \beta_2 \sum_{\substack{x \sim_n y \\ x , y \notin \ensuremath{\mathbb{Z}^d}}} \cos (\theta_x - \theta_y) \right) \prod_{x \in \Lambda_L^n} d \theta_x.
\end{multline*}
    \item The XY/Villain model on a percolation configuration:
    \begin{equation*}
        \mu_{\Lambda_L^3, \beta_1 , \beta_2, r}^{\mathrm{XY/Vil}}(d\theta) := \frac{1}{Z_{\Lambda_L^3, \beta_1 , \beta_2, r }^{\mathrm{XY/Vil}}}\exp \left( \beta_1  \sum_{\substack{x \sim_3 y \\ x \in \ensuremath{\mathbb{Z}^d}}} r_x \cos (\theta_x - \theta_y) \right) \prod_{\substack{x \sim_3 y \\ x , y \notin \ensuremath{\mathbb{Z}^d}}} v_{\beta_2}(\theta_x - \theta_y) \prod_{x \in \Lambda_L^3} d \theta_x.
    \end{equation*}
\end{itemize}

[Prop 39 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Assume that $\beta,D,b$ satisfy conditions $(H_\beta), (H_D), (H_b), (H_{b,\beta})$, let $0\leq u_0\in L^\infty(\mathbb{R}^d)$ such that $u_0(x)dx\in \mathcal{P}(\mathbb{R}^d)$, and let $u(\cdot,\cdot;u_0),\; \mu_t(dx):=u(t,x;u_0)dx, t\geq 0$ be the solution to \eqref{eq:BR-FP}/\eqref{eq:NL-ab}.
The following assertions hold
\begin{enumerate}
    \item[(i)] Let $0\leq s<T$ and $\nu_s=v_s(x)dx$ such that $0\leq v_s\in L^1(\mathbb{R}^d)\cap L^\infty(\mathbb{R}^d)$.

    \noindent{}If $\nu^{(1)}:=\left(\nu^{(1)}_t=v^{(1)}(t,x)dx\right)_{t\in [s,T]}$ and $\nu_t^{(2)}:=\left(\nu^{(2)}_t=v^{(2)}(t,x)dx\right)_{t\in [s,T]}$ are two right weakly-continuous solutions to the linearized Fokker-Planck equation \eqref{eq:linearizedFPE}, such that $v^{(1)},v^{(2)}\in L^\infty([s,T]\times \mathbb{R}^d)$, sharing the same initial condition $v_s(x)dx$, then
    \begin{equation*}
       \nu^{(1)}=\nu^{(2)}.
    \end{equation*}
    \item[(ii)] 
    Let $\nu_0=v_0(x)dx$ such that $0\leq v_0\in L^1(\mathbb{R}^d)\cap L^\infty(\mathbb{R}^d)$.
    Then there exists a solution $\left(\nu_t=v(t,x)dx\right)_{t\in [0,T]}$ to the linearized Fokker-Planck equation \eqref{eq:linearizedFPE} such that
    \begin{equation*}
        v\in L^\infty([0,T];L^1\cap L^\infty(\mathbb{R}^d)) \quad \mbox{and} \quad \sqrt{a^u}\nabla v\in L^2([0,T];L^2(\mathbb{R}^d)).
    \end{equation*}
    Moreover, it follows that
    \begin{equation}
        v\in C([0,T];L^2_{\sf loc}(\mathbb{R}^d)), \quad T>0,
    \end{equation}
    and if $v_0\leq c u_0$ for some $c\in (0,\infty)$, then 
    \begin{equation}
        v\in C([0,T];L^2(\mathbb{R}^d)), \quad T>0.
    \end{equation}
\end{enumerate}

