[Cor Certificate of arXiv:2609.03762, '\vspace*{-2cm} Projected Riemannian Gradient Descent for the Bures--Wasserstein Barycenter'] Let $f \in \{f_1, f_2\}$ and let $(S_t)_{t \geq 0}$ be generated by~(alg:projected_bwgd of the paper) from $S_0 \in [\alpha I, \beta I]$ (additionally $S_0 \in \mathcal{P}$ when $f = f_2$).
        For every $t \geq 0$,
        \begin{equation} 
            f(S_t) - f(S_\star) \leq \frac{\kappa^{3/2}}{2} \, \mathrm{B}\left(S_t, \mathrm{K}(S_t)\right).
        \end{equation}
        Consequently, for an absolute tolerance $\delta > 0$ one may terminate once $\mathrm{B}(S_t, \mathrm{K}(S_t)) \leq 2 \kappa^{-3/2} \delta$, at which point $f(S_t) - f(S_\star) \leq \delta$; taking $\delta = \epsilon\,(f(S_0) - f(S_\star))$ recovers the relative accuracy of~(Eq:IterationCount of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:closed of arXiv:2606.21591, '\textbf{Equal probabilities maximize the expected deficit\\ in the siblings of the coupon '] For every $\mathbf{p}\in\mathcal{P}_N$ and integer $j\ge 2$,
\begin{equation}
\mathbb{E}[U_j^N]
=\sum_{\varnothing\ne A\subseteq\{1,\dots,N\}}(-1)^{|A|-1}\,
\frac{\sum_{i\in A}p_i^{\,j}}{\bigl(\sum_{i\in A}p_i\bigr)^{j}} .
\end{equation}

[Lemma lem: improved v2 of arXiv:2512.12902, 'Non-equilibrium fluctuations for the \\stirring process with births and deaths'] We fix  an  integer number $K$ such that $2\leq K\leq N$. Let $\underline x\in \Lambda_N^{\neq, n}$ and  $\underline y\in \Lambda_N^{\neq, m}$ such that  $2\leq n+m\leq N^*-1$. For any $\,0<\tau, t\leq T$, with $t\neq \tau$, {and for any $\pi\in S_n$,} the following bound holds:
\begin{equation}
\sum_{{\substack{\underline w=(w_1,\dots,w_n):\\| \underline w\,\cap \
\underline y|=0}}}\;\;\prod_{i=1}^n P_{\tau}^{(\epsilon)}(x_{\pi(i)},w_i)|v_{n+m}^{\epsilon}(\underline{w},\underline y,t)|\lesssim\begin{cases}
\epsilon+\frac{1}{[\epsilon^{-2}\tau]^{1/2}},&\;\;m=1 \textrm{ and } n=1,2\\
\epsilon^{1+\zeta}+\frac{\epsilon}{[\epsilon^{-2}\tau]^{1/2}},
&\;\; 4\leq n+m\leq N^*-1
\end{cases}
\end{equation}
where the constant in $\lesssim$ depends on $N^*,K,T$ and it  is given by $N^*e ^{(N^*)^3K^4\pi T}N^*K^{N^*} T^{N^*/2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 5 (Stable outlier contour) of arXiv:2608.19594, 'Mesoscopic Rectangular Spikes under Subspace Local Laws:\\Outlier Values and Singular Subs'] Let $\Gamma$ be a positively oriented finite union of rectifiable Jordan curves, and let $\Omega_\Gamma$ denote the union of their interiors.  We call $\Gamma$ stable for $(\Theta_n)$ if
\[
   \overline{\Omega_\Gamma}\Subset\C\setminus[-b,b],
\]
it encloses a specified subset of the positive scalar roots $\rho(\theta_{n,i})$, and
\begin{equation}
  \sup_n\sup_{\zeta\in\Gamma}
  \norm{\bigl(\Id_{2r_n}-\calM(\zeta)\calK_n\bigr)^{-1}}_{\op}<\infty.
\end{equation}
A compact finite union of intervals $J\Subset(b,\infty)$ is called stable if the deterministic locations stay a fixed positive distance from $\partial J$ and there is a stable contour $\Gamma$ with $\Omega_\Gamma\cap\mathbb R=\operatorname{int}J$ whose enclosed positive roots are exactly those lying in $J$.

[Theorem t:TransferP of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Fix~$\pi\in\msP(\mbfT_\circ)$.
Then,
\begin{enumerate}[$(i)$, leftmargin=2.5em]
\item the operator~$\tparen{\widehat\mcL, \hCylP{}{0}}$ is essentially self-adjoint on~$L^2(\mcQ_\pi)$, and its closure $\big({\widehat\mcL_\pi,\msD(\widehat\mcL_\pi)}\big)$ is a Markov generator;

\item the Dirichlet form~$\big({\widehat\mcE_\pi,\msD(\widehat\mcE_\pi)}\big)$ generated by~$\big({\widehat\mcL_\pi,\msD(\widehat\mcL_\pi)}\big)$ is the image form of~$\big({\widehat\boldsymbol\mssE_\pi,\msD(\widehat\boldsymbol\mssE_\pi)}\big)$ via~$\mathrm{em}$, and admits carr\'e du champ operator~$\big({\widehat\mcG_\pi,\msD(\widehat\mcG_\pi)}\big)$, the closure of the bilinear form~$(\widehat\mcG,\hCylP{}{0})$ defined by
\[
\widehat\mcG(u,v)\eqdef \widehat\mcL(uv)-u \widehat\mcL v -v \widehat\mcL u\,\mathrm{,}\;\, \qquad u,v\in\hCylP{}{0}\,\mathrm{,}\;\,
\]

\item a $\mcQ_\pi$-measurable set~$\mbfA\subset\msP$ is $\widehat\mcE_\pi$-invariant if and only if~$\mbfA\in \class[\mcQ_\pi]{\mathrm{em}(\mbfC\times\mbfM)}$ for some Borel~$\mbfC\subset\mbfT_\circ$;
\end{enumerate}

