body:
[Proposition 6 (Krasikov) of arXiv:2608.30304, '2608.30304'] For $n\ge6$ and $\alpha\ge\beta\ge A_0$,
\begin{equation}
\max_{-1\le x\le1}
(1-x)^{\alpha+1/2}(1+x)^{\beta+1/2}\bigl|p_n^{(\alpha,\beta)}(x)\bigr|^2
<3\alpha^{1/3}\Bigl(1+\frac\alpha n\Bigr)^{1/6}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2607.21392, 'Gaussian Convexity Principles for Sharp Moderate Deviations of Gaussian Maxima and Critica'] There exists a universal constant $C<\infty$ such that the following holds for all $N\ge 1$ and all $\lambda\in[0,1]$.
\begin{equation}
p_N(\lambda)=\gamma + \varepsilon_N(\lambda),
\end{equation}
where $|\varepsilon_N(\lambda)|\le C\gamma^2.$ In particular, for $\lambda\in[\lambda_0,1]=[1-N^{-1/3},1],$ there exists a universal constant $A<\infty$ such that
\begin{equation}
p_N(\lambda)\le \frac1N + A N^{-4/3}.
\end{equation}

[Theorem thm: moment lb of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Fix $\alpha>\frac{n-2}{4},\beta>0$. Let $p\geq 2$ be an integer. For any $x\in M,R>0$ if $u_0$ is bounded, $u_0\geq \varepsilon>0$ in $B(x,R)$ and $\sec_M\geq -K_2>-\infty$, we have for $0<r\leq R$ \begin{equation}
        \mathbb{E}[\abs{u(t,x)}^p]\geq C \varepsilon^p\exp\left\{\max \left[\left(Q(r),C\right)\right]pt\right\}
    \end{equation}
    where $Q(r):=\beta^2(p-1)\overline{G}_{2\alpha}(r)-\frac{c}{r^2}-C$, $c,C>0$ depend on $\alpha,n,K_2$ and $R$, and $\overline{G}_\alpha(\cdot)$ is the function defined in Lemma (Lower Bound for correlation of the paper). In particular, if $R=+\infty$, we have 
    \begin{equation}
        \liminf_{t\uparrow+\infty,x\in M} \frac{\ln \mathbb{E}[\abs{u(t,x)}^p]}{t}\geq p\max\left(\sup_{0<r<+\infty}Q(r),C\right).
    \end{equation}

[Proposition 67 (Asymptotic series) of arXiv:2605.14630, '2605.14630'] For every $n\geqs0$ there exists a constant $M_n$ such that the ratio of partition 
functions satisfies 
\begin{equation}

 \biggabs{\frac{\cZ_{1,\alpha}}{\cZ_{1,0}}
 - \sum_{m=0}^n \frac{(-\alpha)^m}{m!}
 \biggexpecin{\mu_{1,0}}{\biggpar{\int_{\Lambda}\Wick{\phi(x)^4}\6x}^m}}
 \leqs M_n \alpha^{n+1}\;.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 1 (Exact compact representation and scalar closure) of arXiv:2608.30374, 'Compact and Infinite-Order Error Analysis\\ for Null-Space SVD Estimation'] Let \(\lambda\in\R\) be such that \(\mathcal Q=\mathcal Q(\sigma,\lambda)\)
is invertible, and define
\begin{equation}
    \V{w}=\mathcal{Q}^{-1}\V{\eta},
    \qquad
    \V{v}=\mathcal{Q}^{-1}(K+M)\V{\eta}.

\end{equation}
Then
\begin{equation}
    \V{\eta}^T\V{w}=1,
    \qquad
    \V{v}=\V{\eta}-\V{w}.

\end{equation}
Moreover, \(\lambda\) is an eigenvalue of
\(A=(Z+E)(Z+E)^T\) if and only if it satisfies the scalar closure
\begin{equation}
    \boxed{
    F(\sigma,\lambda)
      :=\lambda-\V{\eta}^TE(Z+E)^T\V{w}=0.}

\end{equation}
For any such root, the two unit eigenvectors on this eigenline and their
errors are
\begin{equation}
    \widehat{\V{\eta}}_{\pm}
      =\mathbin{\pm}\frac{\V{w}}{\|\V{w}\|_2},
    \qquad
    \V{\epsilon}_{\pm}
      =\mathbin{\pm}\frac{\V{w}}{\|\V{w}\|_2}-\V{\eta}.

\end{equation}
The orientation convention
\(\V{\eta}^T\widehat{\V{\eta}}>0\) selects the plus branch, so
\begin{equation}
    \boxed{\V{\epsilon}=\frac{\V{w}}{\|\V{w}\|_2}-\V{\eta}.}

\end{equation}

Equivalently, let
\begin{equation}
    \alpha_{\pm}=-1\mathbin{\pm}\frac{1}{\|\V{w}\|_2}.

\end{equation}
Then
\begin{equation}
    \boxed{
    \V{\epsilon}_{\pm}
      =\mathcal{Q}^{-1}\bigl[\alpha_{\pm}I_m-K-M\bigr]\V{\eta}
      =\alpha_{\pm}\V{w}-\V{v}.}

\end{equation}
Normalization also gives the following unsimplified quadratic formula for
\(\alpha\).  It is equivalent to \eqref{eq:compact-alpha-simple}:
\begin{equation}
    \boxed{
    \alpha=
    \frac{
      \V{w}^T\V{v}-\V{\eta}^T\V{w}
      \mathbin{\pm}
      \sqrt{
        (\V{\eta}^T\V{w}-\V{w}^T\V{v})^2
        -\|\V{w}\|_2^2
          (\|\V{v}\|_2^2-2\V{\eta}^T\V{v})
      }
    }{\|\V{w}\|_2^2}.}

\end{equation}

Writing
\(\beta=\V{\eta}^T\widehat{\V{\eta}}\), the oriented eigenpair is
equivalently characterized by the closed compact system
\begin{equation}
 \boxed{
 \mathcal Q\widehat{\V{\eta}}=\beta\V{\eta},
 \qquad
 \lambda\beta=\V{\eta}^TE(Z+E)^T\widehat{\V{\eta}},
 \qquad
 \widehat{\V{\eta}}^T\widehat{\V{\eta}}=1,
 \qquad \beta>0.}

\end{equation}
Along \(E(\sigma)=\sigma\cE\), there is a unique analytic root of
\eqref{eq:compact-secular-condition} near \((\sigma,\lambda)=(0,0)\)
with \(\lambda(0)=0\).  It is the eigenvalue branch descending from the
clean zero eigenvalue.

