[Proposition prop:resolvent-directional of arXiv:2607.03639, '\vspace{-0.6in}An AI-Assisted Solution to the Signed BAR Conjecture: Uniqueness in the Har'] Let $x\in E$. There is a linear functional $\Lambda_x:H_x\to\mathbb R$ such that, for every $w\in G_x$, the one-sided directional derivative exists and satisfies
\begin{equation}
 \partial_w^+g(x)
 :=\lim_{\varepsilon\downarrow0}
 \frac{g(x+\varepsilon w)-g(x)}{\varepsilon}
 =\Lambda_x(\mathsf L_xw).
\end{equation}
The linear functional
\begin{equation}
 \ell_x(v):=\Lambda_x(\mathsf L_xv),
 \qquad v\in\mathbb R^d,
\end{equation}
is bounded by
\begin{equation}
 \left\lvert \ell_x(v)\right\rvert
 \le\frac{K_\Gamma C_{\mathsf L}\left\lVert \nabla h\right\rVert_\infty}{\lambda}\left\lvert v\right\rvert.
\end{equation}
If $i\in I(x)$, then
\begin{equation}
 \ell_x(R_i)=0.
\end{equation}

