body:
[Lemma LB_lemma_3 of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $s := \alpha + d$. For each $p > \frac{s + 1}{2d - s}$ and each $C_4 > 0$ there is $C_3 = C_3(C_4, p) \in (0, \infty)$ such that for each $C' \ge C_4$ the quantity 
    \begin{align}
    M(m) := \frac{1}{C_3} \ (m+1)^{-p} e^{C' m^{1/\Delta}}, 
    \end{align}
    satisfies 
    \begin{align*}
    \sum_{j=0}^{m} M(j)^d M(m-j)^d \le (m+1)^{-s} M(m+1)^s, 
    \end{align*}
    where $m \in \mathbb N^+$.

[Lemma lma:parity of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $\widetilde{g} \in \widetilde{PSL}_2(\mathbb{R})$, and let $A = q(\widetilde{g}) \in SL_2(\mathbb{R})$. Suppose $A$ is noncentral hyperbolic or parabolic. Then $\mathrm{trans}(\widetilde{g}) \in \mathbb{Z}$. Moreover, 
\begin{equation*}
	\mathrm{trans}(\widetilde{g}) \equiv 0 \mod 2 \iff \tr(A) > 0
\end{equation*}
Equivalently, $\mathrm{trans}(\widetilde{g}) \equiv 1 \mod 2 \iff \tr(A) < 0$.

