[Thm Theorem12 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] For $0 < \varepsilon \leq 1$, let $\mathscr{A}(\omega)$ be the global random attractor of system (equation a1 of the paper) and $\mathscr{A_\varepsilon}(\omega)$ be the random attractor of system (equation b2 of the paper). Then for every $\omega \in \Omega$, $t > 0$,
		\begin{align*}
			\mathop {lim}\limits_{\varepsilon \rightarrow 0} dist_H(\mathscr{A_\varepsilon}(\omega),\mathscr A)=0.
		\end{align*}
		\begin{proof}	 
			Define $\mathcal{K}_\varepsilon(\omega)$ as follows:
			\begin{align*}
				\mathcal{K}_\varepsilon(\omega)=\{u \in H:\|u\|_H^2 \leq \mathcal{M}_\varepsilon(\omega)\},
			\end{align*}
			where $\mathcal{M}_\varepsilon(\omega)$ is given by
			\begin{align*}
				\mathcal{M}_\varepsilon(\omega)=z^{-2}(t,\omega)e^{\nu}[1+\frac{1}{\nu}(r_1(\omega)+r_2(\omega)+R_{f,\nu}(\omega))].
			\end{align*}
			Then for every $0 \leq \varepsilon <1$, $\mathcal{K}_\varepsilon(\omega)$ is a closed absorbing set. For every $\omega \in \Omega$, we have
			\begin{align*}
				\mathop {lim}\limits_{\varepsilon \rightarrow 0}\|\mathcal{K}_\varepsilon(\omega)\|_H^2 \leq \mathop {lim}\limits_{\varepsilon \rightarrow 0}\mathcal{M}_\varepsilon(\omega) =\mathcal{M}_0(\omega).
			\end{align*}
			Then, condition (equation h2 of the paper) is satisfied.

			By Lemma (lem10 of the paper), $E_\varepsilon(\omega)$ can be defined as: 
			\begin{align*}
				E_\varepsilon(\omega)=\{u \in H:\|u\|_V^2 \leq N_\varepsilon(\omega)\},
			\end{align*}
			where $\mathcal{N}_\varepsilon(\omega)$ is denoted by 
			\begin{align*}
				\mathcal{N}_\varepsilon(\omega)=R_4(\omega)+2R_5(\omega).
			\end{align*}
			Following from the invariance of the random attractor $\mathscr{A_\varepsilon}(\omega)$, we find 
			\begin{align*}
				\cup_{0<\varepsilon \leq 1} \mathscr{A}_\varepsilon(\omega) \subset \cup_{0<\varepsilon \leq 1} E_\varepsilon(\omega),
			\end{align*}
			which implies that 	$\cup_{0<\varepsilon \leq \varepsilon_0} \mathscr{A}_\varepsilon(\omega)$ is bounded in $H^1$. Thanks to the compactness of embedding $H^1 \hookrightarrow L^2$, we conclude that $\cup_{0<\varepsilon \leq \varepsilon_0} \mathscr{A}_\varepsilon(\omega)$ is	precompact in $H$.
			Therefore, by Theorem (Theorem10 of the paper) along with Theorem (Theorem11 of the paper), the proof is completed. 
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 23 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] Let $(Y^j,Z^j,U^j)$ be the unique solution of the RBSDE \eqref{basic equation lower} associated
	with data $(\xi^j,f^j)$ for $j \in \{1,2\}$ satisfying assumptions \textbf{(H1)}, \textbf{(H2)}. Then, for any $\beta >2$, there exists a constant $\mathfrak{c}_{\beta}>0$ such that, $s \in [0,T]$,
	\begin{equation*}
		\begin{split}
			&\mathbb{E}\left[\sup_{s \leq t \leq T}e^{\beta A_t} \left| Y^1_t-Y^2_t \right|^2 \mid \mathcal{F}_s  \right]\\
			& \leq \mathfrak{c}_{\beta}\left(\mathbb{E}\left[e^{\beta A_T}\left| \xi^1-\xi^2\right|^2 \mathcal{F}_s \right]\right.\\
			&\qquad \qquad \left.+\mathbb{E}\left[ \left.\int_{s}^{T}  e^{\beta A_r}\left|\dfrac{f^1\left(r,Y^2_r,Z^2_r,U^2_r\right)-f^2\left(r,Y^2_r,Z^2_r,U^2_r\right) }{\alpha_r}\right|^2 dr \right| \mathcal{F}_s\right]  \right).
		\end{split}
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] With a generic but fixed barycentre $\ba \in \Rd$, assume:
	\begin{itemize}
		\item a continuous cost ${c} \in C(\Rd \times \Rd)$ that satisfies the following growth condition: for  $p \in [0,2)$ and $D_1,D_2>0$,
			\begin{equation}

			-D_1 \leq c(x,y) \leq D_2 (1 + \abs{x}^p + \abs{y}^p);
		\end{equation}
		\item probabilities $\mu,\nu \in \mathcal{P}^\ba_2(\Rd)$ in convex order $\mu \preceq_c \nu$;
		\item sequences $\{\mu_{n}\}, \{\nu_{n}\} \subset \mathcal{P}^\ba_2(\Rd)$ (not necessarily in convex order) that converge to, respectively, $\mu, \nu$ in the Zolotarev-2 metric  (equivalently, in the Wasserstein-2 metric);
		\item a sequence $\eps_n >0$ that converges to zero slowly enough so that,
		\begin{equation*}
			\lim_{n \to +\infty} \frac{Z_2(\mu,\mu_{n})  + Z_2(\nu,\nu_{n})}{\eps_n}=0.
		\end{equation*}
	\end{itemize}
	Then, the problems $(\mathrm{M^2 OT}_n)$ are well-posed and they $\Gamma$-converge\footnote{More accurately, the $\Gamma$-limit is the bi-martingale problem $(\mathrm{M^2 OT})$ with the cost (A), which is equivalent to $(\mathrm{MOT})$.} to $(\mathrm{MOT})$. Accordingly,  for any $(\gamma_n,q_n)$ being a sequence of minimizers for  $(\mathrm{M^2 OT}_n)$,  up to selecting a subsequence there holds,
	\begin{equation*}
		\gamma_n \rightharpoonup \gamma \in \Gamma_{\mathrm{M}}(\mu,\nu),
	\end{equation*}
	where $\gamma$  solves $(\mathrm{MOT})$. Moreover, 
	\begin{equation*}
		\lim_{n \to +\infty} \min\, (\mathrm{M^2 OT}_n) = \min\, (\mathrm{MOT}).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 35 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $0<\gamma<1$, $\alpha\in\R$ and let $\D^{\mathsf s}_{\gamma}(\Delta_T^3;B_\alpha)$ be a subcritical admissible selection domain in the sense of Definition~\ref{def:admissible-selection-domain}.  Then the dyadic recursion above extends uniquely by continuity to a continuous linear map
\begin{equation*}
\hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}:\D^{\mathsf s}_{\gamma}(\Delta_T^3;B_\alpha) \to C^{\gamma}(\Delta_T^2;B_\alpha), \quad H\mapsto \hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}H:= R^{\mathsf s}(H),
\end{equation*}
satisfying
\begin{equation}

\hdd\hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}H=H.
\end{equation}
Moreover,
\begin{equation}

\norm{\hat\Lambda^{\mathsf s}_{S,\gamma,\alpha}H}_{\gamma,\alpha}\le C_{\gamma,\theta,T,S,\mathsf s}\norm{H}_{\gamma,\alpha}.
\end{equation}
For an individual defect outside a fixed linear domain, the same estimate holds with the right-hand side replaced by $C_{\gamma,\theta,T,S}(\norm{H}_{\gamma,\alpha}+C_H)$.

