[Theorem 1 of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] Let  $C,r_0>0$ and $n>2$ and assume that, for all $B(r)\subset  X$, $r\geq r_0$, and all $U\subset B(r)$, we have the Faber-Krahn inequality
\begin{equation*}
\lambda(U):=
\inf_{0\neq f\in\mathcal{C}_c(U)}
\frac{\cE(f)}{\|f\|_2^2}\geq \frac{C}{r^2}\left(\frac{m(B(r))}{m(U)}\right)^\frac{2}{n}.
\end{equation*}
Then there are constants $C'=C'(C,n)>0$ and $r'=r'(r,S)>0$ such that,
for all $x,y\in X$ and $t\geq r^2\geq r'^2$, we have
\begin{multline*}
\mathcal{P}_r(t,x,y)
 \leq 
\frac{C'}{\sqrt[2q(t)]{m(B_{x}(r))m(B_{y}(r))}}\\
\cdot 
\frac{\left(1\vee S^{-2}\sqrt{\rho(B_x(r),B_y(r))^2S^2+t^2}-t\right)^{\frac{n}{2}}}{\sqrt[\frac{2q(t)}{q(t)-1}]{m(B_x(\sqrt t))m(B_y(\sqrt t))}}
 \euler^{-S^{-2}t\zeta(\rho(B_x(r),B_y(r))S/t)}.
\end{multline*}
Moreover, for all $x\in X$ and $r_0\leq r_1\leq r_2$, we have
\begin{equation*}
m(B_x(r_2))\leq C'\left(\frac{m(B_x(r_2))}{m(B_x(r_0))}\right)^{\sqrt[4n]{{S}/{r_1}}}
\left(\frac{r_2}{r_1}\right)^{n} m(B_x(r_1)).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:beta_and_relations of arXiv:2606.11503, 'Percolation on hierarchical lattices'] There exists $ \uc{c:beta_and_relations} > 0$ such that, for $p \in (p_{*}, 1)$,
  \begin{equation}

    \uc{c:beta_and_relations}^{-1} (p - p_\star)^\beta
    \leq
    \theta(p)
    \leq
    \uc{c:beta_and_relations} (p - p_\star)^\beta,
  \end{equation}
  where
  \begin{equation}

    \beta = \log_\zeta \frac{|\mathcal{E}_{1}|}{d_f} = \alpha_1 \nu.
  \end{equation}

