[Lem operators of arXiv:2509.26254, '$K$-Branching Random Walk with Noisy Selection: \\ \Large Large Population Limits and Phas'] Recall the definition of $a_-(g)$ and $a_+(g)$ from (equation eq:sigmaRange of the paper). If $\bm{x} \in \mathbb{R}^{K+1}$ is non-increasing and $\sigma \in \mathbb{R}$ satisfies 
\begin{equation}
a_-(f_{\bm{x}})\vee x_{k+1} \leq \sigma \leq a_+(f_{\bm{x}}),
\end{equation}
then $s_{\sigma}(r (f_{\bm{x}})) = f_{\psi_\sigma(\bm{x})},$
where
\begin{equation}\psi_\sigma(\bm{x}) \!:= \!\begin{cases}
\left(\frac{\rho(\bm{x})_0 - \beta \sigma}{1-\beta}, \frac{\rho(\bm{x})_0 - \beta \sigma}{1-\beta}, x_1, x_2, x_3, \ldots, x_{K-1}\right) & \rho(\bm{x})_0 < \sigma, \\
\left(\rho(\bm{x})_0, x_1, \ldots, x_i, \sigma, x_{i+1}, x_{i+2}, \ldots, x_{K-1}\right) & \rho(\bm{x})_{i+1}\! <\! \sigma \!\leq \!\rho(\bm{x})_i \text{ for } 0\! \leq\! i\! \leq\! k.
\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] With high probability, good cube decomposition $\mathcal{P}$ exists, and for any $\eta>0$, 
		\begin{equation}
			\sup_{x\in {\scaleobj{1}{\square}}_m} \vert {\scaleobj{1}{\square}}(x)\vert \leqslant 3^{\eta m}.
		\end{equation}
		Here ${\scaleobj{1}{\square}}(x)$ denotes the cube in $\mathcal{P}$ containing $x$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop3 of arXiv:2606.28631, '\Large \bf On the maximal displacement of subcritical branching random walks with stretche'] Assume {\bf(H2)}.  Let $\delta, \beta \in (0,1)$ be fixed.

	(i) For all $k\in \mathbb{N}$ with $k\delta\geq K_0$ and $x>K_0$, 
	\begin{align}
		&\frac{e^{\lambda x^b}}{\ell(x) x^a } \sum_{n=1}^\infty \beta^{n}\widetilde{\mathbb{P}}\left(\max_{1\leq j \leq n} S_j \leq x, x-S_n\in [(k-1)\delta, k\delta) \right) \lesssim_\beta  \frac{e^{\lambda (k\delta)^b}}{\ell(k\delta) (k\delta)^a }.
	\end{align}
	(ii) For each $0\leq p< q$, 
	\begin{align}
		& \lim_{x\to+\infty} \frac{e^{\lambda x^b}}{\ell(x) x^a } \sum_{n=1}^\infty \beta^{n}\widetilde{\mathbb{P}}\left(\max_{1\leq j \leq n} S_j \leq x, x-S_n\in [p, q) \right) \nonumber\\
		&=\frac{1}{\mathbb{E}(e^{\gamma X})}\int_p^q \sum_{j=0}^\infty \frac{\beta^{j+1}}{1-\beta} \widetilde{\mathbb{P}}\left(z> -\min_{0\leq k\leq j} S_k \right)\mathrm{d} z. 
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:CLTregen of arXiv:2604.20327, 'Persistent Homology of the Wiener Sausage II: A Central Limit Theorem for Drifted Planar B'] As $n \to \infty$,
  \begin{equation}
    \frac{S_n}{\sqrt{n}} \xrightarrow{d} \mathcal{N}(0, \sigma_{\mathrm{cyc}}^2),
  \end{equation}
  where
  \begin{equation}
    \sigma_{\mathrm{cyc}}^2 = \operatorname{Var}(Y_0) + 2\operatorname{Cov}(Y_0, Y_1).
  \end{equation}
  Equivalently,
  \begin{equation}
    \frac{\Phi_\psi(\tau_n) - \rho_\psi \tau_n}{\sqrt{n}}
    \xrightarrow{d} \mathcal{N}(0, \sigma_{\mathrm{cyc}}^2).
