[Thme 57 (the two-nut case; Theorems \ref{thm:twonut_typeI} and \ref{thm:twonut_models}) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Let $\widehat{M}$ be a compact two-nut closing of $I \times P$ with the circle-bundle ansatz \eqref{eq:ansatz}, and let $g(t)$, $t \in [0, T)$, be a K\"ahler-Ricci flow of ansatz metrics with maximal existence time $T < \infty$. Then, the singularity at $T$ is of Type I, and the blow-up limit splits as $(\Sigma, g_\Sigma(t)) \times (\mathbb{C}^k, \textrm{flat})$, where $(\Sigma, g_\Sigma(t))$ is one of the following:
\begin{itemize}
\item $\mathbb{CP}^{m_0+m_\ell+1}$ with the shrinking Fubini--Study metric, when the fibers collapse;
\item $\operatorname{Tot}\big(\mathcal{L}_{\mathcal{I}_0}^{\oplus(m_0+1)}\big)$, the total space of a rank-$(m_0+1)$ vector bundle over the product of the $N_k$-factors ($k \geq 3$) contracting at $Q_0$, with the Dancer--Wang complete shrinking K\"ahler--Ricci soliton --- or its mirror $\operatorname{Tot}\big(\mathcal{L}_{\mathcal{I}_\infty}^{\oplus(m_\ell+1)}\big)$ for a contraction at $Q_\ell$;
\item the projectivization $\mathbb{P}\big(\mathcal{O}^{\oplus(m_0+1)} \oplus \mathcal{L}_{\mathcal{I}}^{\oplus(m_\ell+1)}\big)$ over the product of the contracting $N_k$-factors, with its unique compact shrinking K\"ahler--Ricci soliton, in the borderline case where the fiber collapse and the contraction happen simultaneously.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ be an integer and let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $f_{N}\in H^{ \odot p}$ for every $N\geq 1$. Assume that $(X_{N}, N\geq 1)$ satisfies (\ref{c1}). Let $ (\mathbb{Y}_{N}= (Y_{1,N},..., Y_{d, N}), N\geq 1)$ such that for every $j=1,..., d$, 
		\begin{equation}
			Y_{j, N}= \sum _{q=1}^{N_{0, j}}I_{q} ( g_{q, N} ^{(j)}), \mbox{ with } g_{q, N}^{(j)} \in H ^{\odot q}.
		\end{equation}
		Assume (\ref{c4}), which is equivalent to 
		\begin{equation}

			\mathbf{E}\left[ X_{N} I_{p}(g ^ {(j)}_{p,N})\right]\to _{N \to \infty} \rho _{j}, \mbox{ for } j=1,...,d.
		\end{equation} Then
		\begin{enumerate}
			\item If $\mathbb{Y}_{N} \to _{N \to \infty} \mathbb{Y}$ in $ L^{2}(\Omega)$, then 
			\begin{equation*}
				(X_{N}, \mathbb{Y}_{N})\to \xrightarrow[N\to\infty]{(d)} (Z, \mathbb{Y}),
			\end{equation*}
			where $Z\sim N(0, \sigma ^{2})$ and the characteristic function of the random vector $(Z, \mathbb{Y})$ is given by (\ref{phi}). 
			\item If $\max_{j=1,..., d}N_{0, j}\leq p$ and $ \mathbb{Y}_{N} \xrightarrow[N\to\infty]{(d)} \mathbb{Y}$,  then 
			\begin{equation*}
				(X_{N}, \mathbb{Y}_{N})\xrightarrow[N\to\infty]{(d)}  (Z, \mathbb{Y}),
			\end{equation*}
			where $Z\sim N(0, \sigma ^{2})$ and the characteristic function of the random vector $(Z, \mathbb{Y})$ is given by (\ref{phi}). 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

