[Lemma 234 ($L^2$ estimates for the easy over-differentiated vorticity integrals) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $N = \Ntop$,  let 
$\tander^N \in \mathfrak{P}^{(N)}$ be the set of top order $\nullhyparg{u}$-tangential commutator operators from
Def.\,\ref{D:STRINGSOFCOMMUTATIONVECTORFIELDS}. Let $\blowuprateofwaveWRTnumberofcommutations(N) = \blowupratetoporderwave$ denote the blowup rate of the wave variables defined in \eqref{E:BLOWUPRATEOFWAVEWRTNUMBEROFCOMMUTATORS}. 
Then the following estimates hold for
$(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$:
\begin{align}
		\begin{split} 
			& \left|  \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} \left\{\Speed^2 \exp(\LogDensity) (\multipliervectorfield \tander^N \vortrenormalized)\cdot [\upmu,\tander^N] (\Flatcurl v) + \Speed^2\exp(\LogDensity) (\multipliervectorfield \tander^N \vortrenormalized)\cdot [\tander^N,\upmu \Flatcurl] v \right\} \weight^{\blowupratetoporderwave} \ReciprocalLunitAppliedtoTimeFunction \, \voldiamond \right|, \\
			& \left|   \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} \Speed^2 \exp(\LogDensity) (\multipliervectorfield \tander^N \vortrenormalized^i ) \left\{\sum_{\substack{ \tander^{N_1}\tander^{N_2} = \tander^N \\ N_1 \le N-1}} \upmu (\tander^{N_1} \vortrenormalized^i) \tander^{N_2}(\exp(\LogDensity)) \right\} \weight^{\blowupratetoporderwave} \ReciprocalLunitAppliedtoTimeFunction \, \voldiamond \right| \\
			& \qquad \qquad \lesssim \Errortop(\ubar,u).
		\end{split}
	\end{align}

[Proposition 62 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is $r$-$\sigma$-demicontinuous;
\item[(ii)] The common $\sigma$-order and $\mathrm{u\sigma o}$ adherence of $\Ba_{F}$ is contained in $r\Ba_{F}$;
\item[(iii)] Whenever $f_{p}\toso f$, then $\|f\|\le r\liminf\|f_{p}\|$;
\item[(iii')] Whenever $f_{p}\touso f$, then $\|f\|\le r\liminf\|f_{p}\|$;
\item[(iv)] Whenever $f_{n}\toso f$, then $\|f\|\le r\liminf\|f_{n}\|$;
\item[(iv')] Whenever $f_{n}\touso f$, then $\|f\|\le r\liminf\|f_{n}\|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2606.11511, 'Convergence of a Critical Multitype Bellman--Harris Process with One Infinite-Mean Lifetim'] Consider the branching particle system described in Section~2, and assume that
the lifetime distributions satisfy \eqref{eq:F1-heavy-tail} and
\eqref{eq:finite-type-tails}. Then, for every compact set
\(D\subset\mathbb R^N\), there exists \(C_D>0\) such that

\begin{equation}
  \sup_{x\in\R^N,\ i\in\Kk}
  \Pbb_{(x,i)}\{X_t(D\times\Kk)>0\}
  \le C_D(1+t)^{-\rho},
  \qquad t\ge0 .
\end{equation}

[Lemma eq:const-made-left-Quillen of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $V$ be a faithful $G$-representation. Then
    \begin{equation}
        \textbf{\textup{L}}(V,-)\times\ensuremath{c}(-)\colon \textbf{\textup{$\bm G$-Top}}\to\cat{$\bm G$-${\textbf{\textup{L}}}$-Top}
    \end{equation}
    is left Quillen, and its left derived functor ${{\mathfrak S\kern-.4pt}}_G\to{{\mathfrak S\kern-.4pt}}_\textup{$G$-gl}$ is fully faithful.
    \begin{proof}
        It is clear that $\textbf{\textup{L}}(V,-)\times\ensuremath{c}(-)\dashv\ev_V$ is an adjunction with unit $\eta\colon X\to\textbf{\textup{L}}(V,V)\times X$ given by the inclusion of $\textup{id}_V\in\textbf{\textup{L}}(V,V)$. Combining Lemmas~(lemma:orth-spc-ev-lrQ of the paper) and~(lemma:restr-equiv-rQ of the paper) shows that $\ev_V$ is right Quillen for the $G$-global \emph{level} model structure; as the $G$-global model structure has the same cofibrations and more acyclic cofibrations (and hence the same acyclic fibrations and fewer fibrations) as the $G$-global level model structure, $\ev_V$ is then also right Quillen for the $G$-global model structure on $\cat{$\bm G$-$\textbf{\textup{L}}$-Top}$.

        For full faithfulness, it will suffice to show that the derived unit is invertible, for which we fix a fibrant replacement $i\colon\textbf{\textup{L}}(V,-)\to\mathcal L$. Then $\textbf{\textup{L}}(V,-)\times X\to\mathcal L\times X$ is a $G$-global weak equivalence for every $G$-space $X$ by Corollary~(cor:cart-prod-homotopical of the paper), and the target is fibrant by direct inspection; thus, the derived unit is given by the composite
        \[
            X\xrightarrow{\;x\mapsto(\textup{id}_V,x)\;}\textbf{\textup{L}}(V,V)\times X\xrightarrow{\;i(V)\times X\;}\mathcal L(V)\times X,
        \]
        and it suffices to show that the $G$-space $\mathcal L(V)$ (where $G$ acts diagonally) is $G$-equivariantly weakly contractible. For this, note that $\mathcal L\to 1$ is a $G$-global weak equivalence (by Lemma~(lemma:resolve-pt of the paper)) and a $G$-global fibration (by choice of $\mathcal L$), hence also an acyclic fibration in the $G$-equivariant \emph{level} model structure. The claim therefore follows from the definition of the $G$-global level weak equivalences.
    \end{proof}

[Theorem 2 (Recurrence criterion) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Consider \(T_{n}\)-walks in \(\Z^{d}\), where \((T_{n})\) is any sequence of trees with size \(n+1\) satisfying
\Cref{Assum:MaillardDimension} for some $D>1$. Also assume that the centered jump distribution \(\theta\) has finite (absolute) moment of order $\delta$ for all $\delta < 2D$. As soon as \(d<2D\), the \(T_{n}\)-walks are recurrent:
\begin{equation*}{
\frac{R^{\theta}(T_{n})}{n} \xrightarrow[n \to +\infty]{(\P)} 0. 
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 33 (Finite-time KSD propagation of chaos) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target}, \ref{ass:concentration}, and \ref{ass:ksd-kernel},
\begin{equation}
    \E\KSD_\pi(\mu_t^N,\mu_t)
    \le\frac{J_N(t)+\log C_{\mathrm{KSD}}}
             {c_{\mathrm{KSD}}\sqrt N}
    \le\frac{C}{\sqrt N}e^{\kappa t}.
\end{equation}

[Proposition 28 of arXiv:2606.09121, 'Truncated Signature Information for Mixed Fractional Brownian Paths'] For every fixed $h>0$, every $p\ge1$, and every $\gamma<H_*$,
\begin{align}
    \left\|2\pi_{22}S(Z_{t,h}^{(n)})-2\pi_{22}S(Z_{t,h})\right\|_{L^p}&=0,\\
    \left\|2\pi_{122}S(Z_{t,h}^{(n)})-2\pi_{122}S(Z_{t,h})\right\|_{L^p}&\le C_{p,\gamma,h,\theta}n^{-\gamma}.
\end{align}
For a fixed finite scale set, the constants may be chosen uniformly over the scales in that set.

