[Lemma 5 of arXiv:2609.00680, 'Sharp embeddings between quasi-Banach Besov spaces and shallow ReLU Variation spaces'] Let $0<p<\infty$, $L\in\mathbb N_0$, and $N>d/p$. Suppose that
$j\in\mathbb N_0$ and $g\in\mathcal S'(\mathbb R^d)$ has an
$L^p$ representative satisfying, for some $C>0$,
\[
\supp\widehat g\subset B(0,C2^j).
\]
Define the Peetre maximal function by
\begin{equation*}
\mathcal{P}_{j,N}^Lg(x)
:=
\sup_{y\in\R^d}
\displaystyle\sum_{|\alpha|\le L}\frac{2^{-j|\alpha|}|D^\alpha g(y)|}
{(1+2^j|x-y|)^N}.
\end{equation*}
The following estimate holds:
\begin{equation}

\|\Pmax_{j,N}^Lg\|_{L^p(\R^d)}\lesssim\|g\|_{L^p(\R^d)}.
\end{equation}

