[Definition def:weightcore of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let $\boldsymbol{\sigma} \in \R^{D}$ be a nonincreasing vector of singular values
	(padded by zeros for indices larger than $d$), and let $\varepsilon>0$ be a smoothing parameter.
	The associated \emph{weight operator core matrix}
	$\mathbf{H}_{\boldsymbol{\sigma},\varepsilon} \in \R^{d_1 \times d_2}$ is defined entrywise for $i\in[d_1]$ and $j\in[d_2]$, by one of the following choices:
	\begin{align}
		(\mathbf{H}_{\boldsymbol{\sigma},\varepsilon})_{ij}
		&= [\max(\sigma_i,\varepsilon)]^{-1},
		&& \text{left-sided [Fornasier11]},

		\\
		(\mathbf{H}_{\boldsymbol{\sigma},\varepsilon})_{ij}
		&= [\max(\sigma_j,\varepsilon)]^{-1},
		&& \text{right-sided [mohan_fazel]},

		\\
		(\mathbf{H}_{\boldsymbol{\sigma},\varepsilon})_{ij}
		&= 2[\max(\sigma_i,\varepsilon)+\max(\sigma_j,\varepsilon)]^{-1},
		&& \text{harmonic-mean [Kummerle-JMLR2018]}.

	\end{align}

[Definition See \cite{CLL_Clefts}*{Definition~3.2} of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $T$ be a small $\infty$-category. A \emph{cleft} is a wide subcategory $i\colon S\hookrightarrow T$ satisfying all of the following conditions:
    \begin{enumerate}
        \item $S$ is left-cancellable, i.e.~for any composable maps $f,g$ in $T$ such that $f$ and $fg$ belong to $S$,  also $g$ belongs to $S$.
        \item Given any $f\colon A\to B$ in $S$ and $g\colon B'\to B$ in $T$, there exists a pullback square in $\PSh(T)$ of the form
        \[
            \begin{tikzcd}
                i_!X\arrow[d]\arrow[dr,pullback]\arrow[r,"i_!f'"] & i_!B'\arrow[d,"g"]\\
                i_!A\arrow[r, "i_!f"'] & i_!B\rlap,
            \end{tikzcd}
        \]
        where $i_!\colon\PSh(S)\to\PSh(T)$ denotes left Kan extension along $i$ and we conflate elements of $S$ and $T$ with their Yoneda image as before.
        \item Given maps $f\colon A\to B$ and $g\colon B\to A$ in $T$ such that $gf=\textup{id}_A$ and $fg$ belongs to $S$, then both $f$ and $g$ belong to $S$.
    \end{enumerate}

[Corollary 213 ($L^2$ estimates for $\velocityarray$ that lose one derivative) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $1 \leq N \leq \Ntop$,
and recall the vectorfield conventions established in Def.\,\ref{D:STRINGSOFCOMMUTATIONVECTORFIELDS}. Let $\blowuprateofwaveWRTnumberofcommutations(N)$ denote the blowup rate of the wave variables defined in \eqref{E:BLOWUPRATEOFWAVEWRTNUMBEROFCOMMUTATORS}. Let $\varsigma_0$ be the constant featured in Lemma\,\ref{L:PRELIMINARYBELOWTOPORDERL2ESTIMATESFOREIKONALFUINCTIONQUANTITIES} (see also Remark\,\ref{R:SMALLNESSCONSTANTFORBELOWTOPORDERACOUSTICVARIABLES}). Then the following estimates hold for $(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$, where the implicit constants are \textbf{independent} of $\varsigma_0$:
\begin{align}
	\begin{split}
		\left\| 
			\comder^{N;1} \velocityarray \right\|_{L_{\blowuprateofwaveWRTnumberofcommutations(N)}^2\left(\ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu,u]}\right)}^2 & \lesssim  \initialsmalldoublenull^2 + \totalfluxcontrolvelocity_{[1,N]}(\ubar,u) +  (1 + \varsigma_0^{-1}) \int_{\ubar' = \leftubar}^{\ubar} \totalfluxcontrolvelocity_{[1,N-1]}(\ubar',u) \, \mathrm{d} \ubar'   \\
			& \ \ +  (1 + \varsigma_0^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N-1]}(\ubar,u') \, \mathrm{d} u' + \fundbootsmall(1 + \varsigma_0^{-1}) \strongangularcontrolvelocity_{[1,N-1]}(\ubar,u) \\
			& \ \ + \int_{u' = \moreinterestingu_1}^u \left\{\fluxcontrolVort_{\le N-1}(\ubar,u')+ \fluxcontrolGradEnt_{\le N-1}(\ubar,u')\right\} \, \mathrm{d} u'.
	\end{split}
\end{align}

