[Prop condldpdef of arXiv:2609.02682, 'LDP for tensor forms'] Assume $Q_n$ is a sequence of random symmetric zero-diagonal $v$-tensors (independent of $\mathbf{X}$) such that
\begin{align}
\|W_{Q_n}-W_\infty\|_{\square^*}=o_{\mathbb P}(1),

\end{align}
for some deterministic $W_\infty\in\mathcal W_v$.

Then $N_n(Q_n,\phi,{{\bf X}})$ satisfies a conditional LDP (see~(cor:conditional-ldp of the paper)) with speed $n$ and the deterministic good rate function $J_{W_\infty}(\cdot)$ as in (NewLDP of the paper) (i). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 of arXiv:2605.30629, 'Search at bounded speed with immigration'] Let $E$ be the event where $\mcTk/(\wtlambda q)<\delta$ for some $\delta<1$. Then
    \begin{equation}
         \lim_{\wtlambda \rightarrow \infty}\frac{\E[\mcTk^m|E^c]\P(E^c)}{(\wtlambda q \delta)^{m+k-1} e^{-\wtlambda q \delta}} = \frac{1}{(k-1)!}

    \end{equation}
    \begin{equation}
         \lim_{\wtlambda \rightarrow \infty}\frac{\E[\mcTk^m|E]\P(E) - \frac{(m+k-1)!}{(k-1)!}}{-\frac{(\wtlambda q \delta)^{m+k-1} e^{-\wtlambda q \delta}}{(k-1)!}} = 1

    \end{equation}

    \begin{equation}
         \lim_{\wtlambda \rightarrow \infty}\frac{\E\left[\left(\frac{\mcTk}{\wtlambda q}\right)^{m-1}\int_0^{\mcTk/(\wtlambda q)} f(s) ds \middle| E \right]\P(E)}{H(m, \wtlambda q, \alpha, p)/(\wtlambda q)^m} = 1

    \end{equation}

