[Theorem thm_var_formula of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Assume (equation p_cont of the paper).
There exists a universal constant $\alpha\in(0,\infty)$ (not depending on the density function $\mathfrak{p}$) such that
\eeq{ 
\lim_{n\to\infty}\frac{\mathscr{L}_n}{n^{1/3}} = \frac{\alpha}{2}\sup_{f\in\mathcal{F}}J_\mathfrak{p}(f) \quad \text{almost surely and in $L^p$ for every $p\in[1,\infty)$.}
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:IPLDP of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Assume that the initial distribution ${\mu}$ is a {space-homogeneous} Bernoulli product measure or two-sided  Markov distribution supported on $\Omega$ {and that $\mu\left(\eta\left(0\right) = \eta\left(1\right) = 1\right) > 0$}. {Let $\nu$ be the conditional probability measure such that ${\mu}$ is conditioned on $\Omega_{0}$.} Then, for any $k \in {\mathbb{N}}$, we have the following. 
                \begin{enumerate}

                    \item  {For any $i \in {\mathbb{Z}}$ and  $\mathbf{T} > 0$, under $\mu$ or $\nu$}, the following step-interpolation process,
                    \begin{align}
                        t \mapsto \frac{1}{n} {Y}^{i}_{k}\left(\left\lfloor n^2 t \right\rfloor  \right) - nt v^{\mathrm{eff}}_{k}\left( {\mu} \right),
                    \end{align}
                    converges weakly in $D[0,\mathbf{T}]$ to a Brownian motion with variance {$D_{k}$}, defined in (equation eq:dif_co of the paper) below. 

                    \item  {For any $i \in {\mathbb{Z}}$, under $\mu$ and $\nu$,} the sequence $\left({Y}^{i}_{k}\left(n\right)/ n\right)_{n \in {{\mathbb{N}}}}$ satisfies the LDP with a smooth convex rate function defined in (equation def:rate_I of the paper) below. 

                    \item  {For any {$i \in {\mathbb{Z}}$} and $p \ge 1$, we have 
                        \begin{align}
                            \lim_{n \to \infty} {\mathbb{E}}_{{\mu}}\left[ \left| \frac{{Y}^{i}_{k}\left(n\right)}{n} - v^{\mathrm{eff}}_{k}\left({\mu}\right) \right|^{p} \right] = \lim_{n \to \infty} {\mathbb{E}}_{\nu}\left[ \left| \frac{{Y}^{i}_{k}\left(n\right)}{n} - v^{\mathrm{eff}}_{k}\left({\mu}\right) \right|^{p} \right] =  0.
                        \end{align}}
                \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 13 of arXiv:2603.28226, '2603.28226'] An atomic filtration $(\mathcal F_n)_{n\ge1}$ is called $\alpha$-regular if there exists $\alpha\in(0,1]$ such that for every $n\ge2$, every parent atom $P\in\mathcal A_{n-1}$, and every child atom $C\in\mathcal A_n$ with $C\subseteq P$,
\begin{equation}

 \mathbb P(C)\ge \alpha\,\mathbb P(P).
\end{equation}

[Definition of arXiv:2510.01838, 'Shadow and percolation I: discrete landscapes with independence'] Let $A\subset \mathbb{Z}$ be a finite subset, $A=\{a_1,a_2,\dots,a_n\}$ with $a_1<a_2<\dots<a_n$.
    Let $R_0\geq 1$. We say that $A$ is \textit{$R_0$-connected} if
    \begin{equation}
        \forall i\in \llbracket 1,n-1\rrbracket,\ |a_{i+1}-a_i|\leq R_0.
    \end{equation}

[Theorem 15 (\emph{Link between $Y$ and optimal stopping in randomized strategies}) of arXiv:2607.21062, 'A new probabilistic approach for\\ mean field games of optimal stopping'] Suppose that Assumptions \ref{assumption:1A} and \ref{assumption:1B} hold. Then, for every $L \in \mathcal V$ and the associated solution $(X,Y,Z,A) \in \mathbb S^2 \times \mathbb S^2 \times \mathbb H^2 \times \mathbb A^2$ to system \eqref{MFG SDE}-\eqref{MFRBSDE}, it holds that
\begin{align}
Y_t=\underset{\hat L \in \mathcal{V}_t}{\textup{ess\,sup}}\,\mathbb{E}\bigg[\int_t^T f(s,X_s, \mathbb{E}[\bar{f}(s,X_s)L_s])\hat L_sds-\int_{t^-}^Th\bigg(s, X_s,\mathbb{E}\bigg[\int_{0^-}^T\phi(s-r)dL_r\bigg]\bigg)d\hat L_s\bigg|\mathcal{F}_t\bigg],
\end{align}
for all $0\leq t\leq T$, where $\mathcal{V}_t=\{ \hat L \in \mathcal{V}\colon\hat L_{t^-}=1\}$.

[Lemma lm:reversepinsker of arXiv:2508.21055, 'Modern aspects of Markov chains:\\entropy, curvature and the cutoff phenomenon'] For any density $f\in\mathcal {F}_1^+$, we have 
\begin{eqnarray*}
\mathrm{Ent}(f) & \le & \frac{1+\sqrt{\mathrm{Varent}(f)}}{1-\mathrm {TV}(f)}.
\end{eqnarray*}

