[Proposition p:PropertiesCylinder of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] The following assertions hold:
\begin{enumerate}[$(i)$]
\item $\hCylP{}{}$,~$\hCylP{}{\epsilon}$ are algebras w.r.t.\ the pointwise multiplication for every~$\epsilon\in\mbbI$;
\item $\epsilon\mapsto \hCylP{}{\epsilon}$ is strictly decreasing and left-continuous, i.e.
\[
\hCylP{}{\delta}\subsetneq \hCylP{}{\epsilon}\,\mathrm{,}\;\, \quad \delta>\epsilon\,\mathrm{,}\;\, \qquad \text{and} \quad \hCylP{}{\epsilon}=\cup_{\delta>\epsilon}\hCylP{}{\delta} \,\mathrm{;}\;\,
\]
\item $\hCylP{}{0}$ generates the Borel $\sigma$-algebra on~$\msP^\pa$;
\item every function in~$\hCylP{}{}$ is $\tau_\mrma$-continuous (in particular: Borel-measurable);
\item every non-constant function in~$\hCylP{}{0}$ is $\tau_\mrmn$-discontinuous at every~$\mu\in\msP^\pa$;
\item $\hCylP{}{0}$ is dense in~$L^2(\mcQ)$ for \emph{every} Borel probability measure~$\mcQ$ on~$\msP^\pa$.
\end{enumerate}

[Corollary of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] Assume $m>5/2$ and $\kappa\ge 1$. Then, it holds:
\begin{equation*}\begin{split}
&(1)\qquad\limsup_{N\rightarrow{+\infty}}\mathbb{E}_{N}\Big[\sup_{0\leq{t}\leq{T}}\|\pi_{t}^{v,N}\|_{-m}^{2}\Big] < \infty 
\\& (2)\qquad 
\lim_{n\rightarrow{+\infty}}\limsup_{N\rightarrow{+\infty}}\mathbb{E}_{N}\Big[\sup_{0\leq{t}\leq{T}}\sum_{|z|\geq{n}}(\langle \pi_{t}^{v,N},h_{z}\rangle)^{2}\gamma_{z}^{-m}\Big]=0.
\end{split}\end{equation*}

