[Thm 3 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For fixed $\mu$ such that $\mu(V_k)<1$ and for fixed $\varepsilon$, there exists $\chi=\chi(\mu,\varepsilon),\rho=\rho(\mu,\varepsilon),\varphi=\varphi(\mu,\varepsilon)>0$ such that the following holds. For any sequence of $(\chi,\rho,\varphi)$-almost-$\mu$-like shuffles with deterministic pile sizes $\bn^{(t)}=(n_0^{(t)},\cdots,n_{k-1}^{(t)})$,
		\begin{align}

			\lim_{N\to\infty} d_{\TV}
            \big(\bP(\vec\bn,\lfloor(1-\varepsilon)\overline{C}_{\mu}\log(N)\rfloor),\nu_{\Unif}\big)
            &=
            1,\\

			\lim_{N\to\infty} d_{\TV}
            \big(\bP(\vec\bn,\lfloor(1+\varepsilon)\overline{C}_{\mu}\log(N)\rfloor),\nu_{\Unif}\big)
            &=
            0,
		\end{align}
		where $\nu_{\Unif}$ is the uniform measure on $\mathsf S_N$ and the limits are uniform in $\vbn$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 113 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mf A$ be an HTM, $I$ and $J$ be sets, and $K = I\times  J$. Let one of the following conditions be satisfied:
  \begin{enumerate}
  \item [(a)] $I$ is finite and $\sm{\mf A}{j\in J}{f(i,j)}$ for every $i\in I$,
  \item [(b)] $J$ is finite and $\sm{\mf A}{i\in  I}{f(i,j)}$ for every $j\in J$.
  \end{enumerate}
  Then
  \begin{equation}

      \sum_{i\in I}\sum_{j\in J}f(i,j) = \sum_{k\in K} f(k) = \sum_{j\in J}\sum_{i\in I}f(i,j).
    \end{equation}

[Definition 1 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $\ppp$ be a stationary marked point process on $\rd \times \R$. We say that it is 
\begin{itemize}
    \item[(i)]ergodic, if for all $A,B \in \mathcal{N}(\rd \times \R)$,
\begin{equation*}
\lim_{a \rightarrow \infty} \frac{1}{\lambda^d((-a,a)^d)} \int_{(-a,a)^d} \p(\ppp\in A, T_z(\ppp) \in B) \,\dx z = \p(\ppp \in A)\p(\ppp \in B),
\end{equation*}
    \item[(ii)]mixing, if for any $A, B \in \mathcal{N}(\rd \times \R)$,
\begin{equation*}
    \lim_{\norm{z}\rightarrow \infty} \p(\ppp \in A, T_z(\ppp) \in B) = \p(\ppp \in A) \p(\ppp \in B),
\end{equation*}
    \item[(iii)] $\alpha$-mixing, if for all $0< c < \infty$,
    \begin{equation*}
    \lim_{\Delta \rightarrow \infty}  \alpha_\ppp(c,\infty;\Delta)=0.
    \end{equation*}
\end{itemize}

