[Proposition prop:nonuniform:CLT:crude of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] There exists some universal constant $a > 0$ such that 
\begin{align*}
    {\mathbb P}( E_1 > x ) 
    \;=&\;
    \Phi^c(x) 
     \,
     \Big( 1 + O\Big( \mfrac{1}{n} + \mfrac{N^{1/2}}{n^{3/2}}  + \mfrac{1+|x|^3}{\sqrt{N}}\Big) \Big)
    \qquad 
    \text{ for } 
    \quad 
    0 \leq x \leq a N^{1/6}
    \;,
    \\
    {\mathbb P}( E_1 < x ) 
    \;=&\;
    \Phi(x) 
     \,
     \Big( 1 + O\Big( \mfrac{1}{n} + \mfrac{N^{1/2}}{n^{3/2}}  + \mfrac{1+|x|^3}{\sqrt{N}}\Big) \Big)
    \qquad 
    \text{ for } 
    \quad 
    - a N^{1/6} \leq x \leq 0
    \;.
\end{align*}
Suppose in addition that $|x| = o(N^{1/6})$ and $N=o(n^3)$. If $x > 0$ with $x = \omega(1)$, then 
\begin{align*}
    {\mathbb P}( E_1 > x ) 
    \;=\; 
    (1+o(1)) \, e^{ - \frac{x^2}{2} + o(x) }
    \;.
\end{align*}
If $x < 0$ with $|x| = \omega(1)$, then
\begin{align*}
    {\mathbb P}( E_1 < x ) 
    \;=\; 
    (1+o(1)) \, e^{ - \frac{x^2}{2} + o(|x|) }
    \;.
\end{align*}
If instead $x=O(1)$, we have 
\begin{align*}
    {\mathbb P}( E_1 > x ) 
    \;=&\;
    \begin{cases}
        \Theta( e^{-x^2/2} ) 
        & 
        \text{ if } x > 0\;,
        \\
        \frac{1}{2} (1 + o(1))
        & 
        \text{ if } x = o(1)\;,
        \\
        1 - \Theta( e^{-x^2/2} ) 
        & 
        \text{ if } x < 0\;.
    \end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:joint-limit of arXiv:2608.26765, 'Beyond Client Averaging: A Client-Independent Second-Order Stationary-Bias Component in St'] For any sequences $\gamma_k\to0$ and integers $N_k\to\infty$, with fixed $H$ and no relative-rate condition,
\begin{equation}

  \lim_{k\to\infty}
  \frac{
    b_{\gamma_k,N_k,H}
    +\dfrac{\tau\sigma^2}{4a^2}\dfrac{\gamma_k}{N_k}
  }{\gamma_k^2}
  =-\frac{\tau\sigma^2}{12a}
  \frac{(H-1)(5H-1)}{H}.
\end{equation}

[Thm gauge PT correspondence of arXiv:2609.03152, 'Experiments with membranes, maps and sheaves'] For $|m|<N$ we have
    \begin{equation}

        \PTarg{}{X_{N,m}}{Z_{N,m}}{\Gm_q}{\mathsf{T}'} = \mathcal{Z}^{\mathrm{Nek}}_{N,m}(\kappa^{1/2}q ,\kappa^{1/2}q^{-1};Q)\,.
    \end{equation}
    Especially, (conj: PT GV of the paper) holds for $X_{N,m}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition general_term2 of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] [General form of term]
	Let $\mathcal{I}$ be a length $d$ multi-index of free summation indices $i_1, \dots, i_d$, with $d \geq 2$. Let $\mathfrak{m}_0$ be an integer with $2 \leq \mathfrak{m}_0 \leq d$, and introduce integers $k_p \geq 1$ for $1 \leq p \leq \mathfrak{m}_0 - 1$. As before, let $\#_{\beta}$ be an integer and $(r_k)_{k=1}^{\#_{\beta}} \in (\mathbb{Z}_{\geq 1})^{\#_{\beta}}$ be multi-indices. Finally let $g(t) : \mathbb{R}^+ \to \mathbb{R}$ be a time factor satisfying $g(t) \leq C \mathrm{e}^{-t}$. The above data defines the sequence of functions ${\mathbb R}^+ \to {\mathbb R}$,  \begin{equation}
			t \mapsto g(t) \frac{1}{N^{d- \mathfrak{m}_0}} \sum_{\mathcal{I}} \prod_{p=1}^{\mathfrak{m}_0 - 1} (\mathring{V}^{k_p})_{i_p i_{p+1}} \sum_{\beta \in [[1, K]]^{\#_{\beta}}} \EX\left[(\partial_{\beta} F) \prod_{k=1}^{\#_{\beta}} \Bigg(\sum_{\mathcal{J} \in J^{r_k}} (\partial_{\mathcal{J}} \mathcal{L}_\tau^{\beta_k}) \prod_{s=1}^{r_k} \mathrm{IF}(k, s, \mathcal{I}, \mathcal{J}) \Bigg)\right],

	\end{equation} where $\mathrm{IF}(k, s, \mathcal{I}, \mathcal{J})$ denotes inner factors (\emph{c.f., } (equation inner_fac_def of the paper)). Let $q_i$ and $q_j$ denote the basis vectors $q_{i(\mathcal{J}(s))}$ and $q_{j(\mathcal{J}(s))}$ respectively, and let $\alpha = \alpha(\mathcal{J}(s))$. Each inner factor is defined by the following data: 
	\begin{itemize}
		\item  Natural numbers $n_1^{(\mathrm{off})}$, $n_1^{(\mathrm{diag})}$, $n_1^{(\mathrm{inner})}$, $y_1$, $n_2$, and $\hat{y}_l$, $\hat{n}_l^{(\mathrm{off})}$, $\hat{n}_l^{(\mathrm{diag})}$ for $1 \leq l \leq n_2$. Further, we enforce the condition, 
		\begin{equation}
			n_1^{(\mathrm{inner})} + n_1^{(\mathrm{off})}+ n_1^{(\mathrm{diag})} + \sum_{l=1}^{n_2} \hat{n}_l^{(\mathrm{off})} + \hat{n}_l^{(\mathrm{diag})} \geq 2. 

		\end{equation}
		\item $\mathcal{I}\cup\{q_i, q_j\}$-valued indices $u_i, v_i , u_i \neq v_i,  1 \leq i \leq n_1^{(\mathrm{off})}$, and $w_i, 1 \leq i \leq n_1^{(\mathrm{diag})}$.
		\item $\mathcal{I}$-valued indices $x_i, 1 \leq i \leq n_1^{(\mathrm{inner})}$.
		\item For $1 \leq l \leq n_2$: $\mathcal{I}$-valued indices $\hat{u}_j, \hat{v}_j,\hat{u}_j \neq \hat{v}_j,  1 \leq j \leq \hat{n}_l^{(\mathrm{off})}$ and $\hat{w}_j, 1 \leq j \leq \hat{n}_l^{(\mathrm{diag})}$. 
		\item $\{i, j\}$-valued indices $z_l$ for $1 \leq l \leq n_1^{(\mathrm{inner})}$.
	\end{itemize}
		The above data uniquely defines the inner factor, 
	\begin{equation}
