[Definition Fair STIT of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $F$ is a splitting distribution and $P_F$ the corresponding probability kernel from $\cF^d_1$ to $\cF_1^d$ constructed in Remark~(r: fair STIT of the paper). Then we call a random fair partition $(\Phi,\tau)$ a \textit{fair STIT with splitting distribution} $F$ if it is invariant with respect to the probability kernel $P_F$.  To allow for the possibility of a unique invariant distribution, we also formally assume that
    \begin{equation}
        x = \int_{C(x)} z\, dz,\quad x\in\Phi.
    \end{equation}

[Lemma 3 of arXiv:2605.07184, 'Convergence of Stochastic Gradient Descent with mini-batching and infinite variance'] \Cref{assumption:function_H} holds if and only if there exists $p\geq1$ and $\delta,L>0$
  (which may depend on $p$) such that for all $t \in [0,\delta]$ and for all $\bstheta\in\Theta$,
  \begin{align}

    \vvvert \id - t\nabla H(\bstheta) \vvvert^p \leq 1 - Lt \; .
  \end{align}
  If \eqref{eq:lemma_functionH_1} holds for one $p$, then it holds for all $p\geq1$.

[Theorem thm:F=tildeF of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Suppose that $\| A_N\|_{\mathrm{op}} \le 1+\tau n^{-1}$, where $n = \sum_{j=1}^s n_j$ and $\tau > 0$ is a fixed constant. Under Assumptions (itm:B1 of the paper)--(itm:B2 of the paper) of Definition~(mixingdef of the paper), for any fixed diagram $\Gamma$ the diagram functions in Definition~(defsDF of the paper) satisfy the following asymptotic equivalence:

\begin{enumerate}
    \item[(i)] If $\Gamma$ has at least one open edge,  then\begin{equation}
F_{\Gamma}(\{n_j\})=\widetilde{F}_{\Gamma}(\{n_j\}_{j=1}^s)+O_{|E|}\Big(\left\{\big(b_n\big)^{|E_{\mathrm{int}}|-|V_{\mathrm{int}}|-1}n^{|V|-1}\right\}\big(n\Delta_n +b_n\mathcal{E}_n \big)\Big).
\end{equation}
\item[(ii)] If $\Gamma$ has no open edge, then
\begin{equation}
F_{\Gamma}(\{n_j\})=\widetilde{F}_{\Gamma}(\{n_j\}_{j=1}^s)+O_{|E|}\Big(\left\{\big(b_n\big)^{|E|-|V|}n^{|V|-2}N\right\}(n\Delta_n +b_n\mathcal{E}_n )\Big).
\end{equation}
\end{enumerate}

