[Lemma lemme detronque of arXiv:2412.02666, 'Scaling limit of first passage percolation geodesics on planar maps'] We have for all $v_1, \ldots, v_d \in \mathbb {R}$, 
 	$$
 	\left(X_t^{\varepsilon}(v_i)\right)_{ 1 \le i \le d, t\ge 0} \mathop{\longrightarrow}\limits_{\varepsilon \to 0}^{(\mathrm{d})}
 	\left(X_t (v_i)\right)_{1 \le i \le d, t \ge 0}
 	$$ in the space $\mathbb{D}(\mathbb {R}_+, \mathbb {R})^d$.

[Thm intro local curve GW g formula of arXiv:2609.02409, 'Membranes and Maps'] Suppose that $\mathsf{T}$ acts on the fibers of the local curve $Z$ with weights $\epsilon_2,\ldots,\epsilon_5$ satisfying the Calabi--Yau condition $\sum_i \epsilon_i=0$. If (conj:GW:vertex of the paper) holds for $n=1$, then
    \begin{equation}

        \GWargs{Z}{\mathsf{T}}{[C]}
        =
        \prod_{i=2}^5 \big(
            2 \sinh \tfrac{\epsilon_i}{2}
        \big)^{g_C - 1 - \deg \cL_i}
        =
        \hat{\mathsf{A}}_{\mathsf{T}}\big( \overline{M}_{g_C}(Z,[C]) \big) \,.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2604.20631, 'The Ising Model on a Two-Community Stochastic Block Model'] For $n$ large enough, we have
\begin{equation*}
\bar{Z}_{n,\beta}=
\begin{cases}
e^{n\log2} D_0^{(n)}(1+o(1)), & \text{if }\beta<\beta_c, \\[5pt]
e^{\frac{n}{2} M_1(\alpha_n)} \sum_{i=1}^2 D_i^{(n)} (1+o(1)),& \text{if } \beta  \in \big(\beta_c,\beta^*(\alpha_n)\big], \\[5pt]
    e^{\frac{n}{2} M_1(\alpha_n)} \left (\sum_{i=1}^2 D_i^{(n)}+e^{-\frac{n}{2} \varepsilon(\alpha_n)} \sum_{i=3}^4 D_i^{(n)} \right ) (1+o(1)),  & \text{if } \beta>\beta^*(\alpha_n),
\end{cases} 
\end{equation*}
where $\varepsilon(\alpha_n)$ is defined in $\eqref{def:M1M2}$.
Moreover, if $\beta=\beta_c$, we get
\begin{equation}
\sqrt[4]{n} \, e^{n\log2}  D_{\text{low}}^{(n)}\,(1+o(1))\le \bar{Z}_{n,\beta_c}\le
\sqrt{n} \, e^{n\log2}  D_{\text{up}}^{(n)}\,(1+o(1)), 
\end{equation}
where $D_{\text{low}}^{(n)}$ and $D_{\text{up}}^{(n)}$ are explicit 
uniformly bounded function of $n$, converging to finite positive constants.

