body:
[Thm 10 of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] Let  $\Phi(t,x)$ be the solution to the renewal equation \eqref{renewal eqn=3} for $t>0$ and $x\in\R$ with an absolutely continuous and compactly supported initial condition  $u_0$ in $[0,i_\dagger)\times\R$. Then for $T>i_\dagger$ sufficiently large, there is a nonnegative kernel $\mathcal{G}(t,x)$ defined  for $t\ge T$ and $x\in\R$ such that for any $\gamma_*\in(3/8,1/2)$, the following estimate holds true:
	\begin{equation}
		\Vert \Phi(t,x)-\mathcal{G}**\mathcal{F}(t,x)\Vert_{L^{\infty}_x(\R)}\le C \big(\Vert u_0\Vert_{L^\infty([0,i_\dagger)\times\R)}+\max_{[0,i_\dagger)}\big\Vert  u_0(i,x) \big\Vert_{H^1_x(\R)} \big)e^{-\frac{b}{2}t^{1-2\gamma_*}},~~~~~t\ge T.
	\end{equation}
	Here, $\mathcal{G}** \mathcal{F}(t,x):=\int_\R\int_0^t \mathcal{G}(t-s,x-y)\mathcal{F}(s,y)\md s\md y$, and $b>0$ is given in \eqref{notation}. Moreover, by  choosing $\varsigma\in(0,1/2-\gamma_*)$,  we have for  $t\ge T$, up to increasing $T$ if needed, 
	\begin{itemize}
		\item[(i)] if $|x-c_*t|\le t^{\frac{1}{2}+\varsigma}$,
		\begin{equation}

			\mathcal{G}(t,x)=\bigg[\frac{\upsilon_0}{\sqrt{2bt}}+\frac{k\upsilon_0}{4b^2t}\mathcal{P}\left(\frac{x-c_*t}{\sqrt{2bt}}\right)	\bigg]\mathscr{G}\left(\frac{x-c_*t}{\sqrt{2bt}}\right)	+\mathcal{R}(t,x),
		\end{equation} 
	 with
		$\mathcal{P}(x):=-3x	+x^3,\ x\in\R,$
 and
		\begin{equation}

			|\mathcal{R}(t,x)|\lesssim t^{\varsigma-1} e^{-\frac{(x-c_*t)^2}{4bt}	}.
		\end{equation}
	Therefore, $\mathcal{G}(t,x)=\frac{\upsilon_0}{\sqrt{2bt}}\mathscr{G}\left(\frac{x-c_*t}{\sqrt{2bt}}\right)\Big(1+o_{t\to+\infty}(1)\Big)$ for  $|x-c_*t|\le t^{\frac{1}{2}+\varsigma}$;
		\item[(ii)] if $|x-c_*t|\ge  t^{\frac{1}{2}+\varsigma}$,
		\begin{equation}

			\mathcal{G}(t,x)\lesssim t^{-\gamma_*}e^{-t^\varsigma}.
		\end{equation}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] Assume $m>5/2$ and $\kappa\ge 1$. Then:
\begin{equation*}
\limsup_{N\rightarrow{+\infty}}
\mathbb{E}_{N}\Big[\sup_{0\leq{t}\leq{T}}\|\pi_{t}^{e,N}\|_{-m}^{2}\Big] < \infty 
\end{equation*}
and 
\begin{equation*}
\lim_{n\rightarrow{+\infty}}
\limsup_{N\rightarrow{+\infty}}
\mathbb{E}_{N}\Big[\sup_{0\leq{t}\leq{T}}\sum_{|z|\geq{n}}(\langle \pi_{t}^{e,N},h_{z}\rangle)^{2}\gamma_{z}^{-m}\Big]=0.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor: limit of partial derivatives term of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] The following property holds in the set $\Gamma$ of probability one:
	\begin{align*}
		\lim_{N \to \infty} \int_0^t \angled{\varphi_s + \bar r\left(\bar\boldsymbol{\mu}_s^N\right)\psi_s}{\bar\boldsymbol{\mu}_s^N}ds = \int_0^t \angled{\varphi_s + \bar r\left(\bar\boldsymbol{\mu}_s\right)\psi_s}{\bar\boldsymbol{\mu}_s}ds
	\end{align*}
	for all $\varphi, \psi \in C_b(\mathbbm{R}_+^3)$ and all $t \geq 0$.

