\begin{equation}
\lim\limits_{n\to\infty}\sup\limits_{N\geq1}\Big\|\widehat{Z}_N^{(K)}-\widehat{Z}_{N,n}^{(K)}\Big\|_{L^2({\ensuremath{\mathbbm P}} )}=0.
