body:
[Lemma lemma_derivatives_of_p_kappa of arXiv:2609.00973, 'The Vlasov-Maxwell point charge system : study of the spherically symmetric case'] We have 
    \begin{equation}

        \begin{array}{c}
            \displaystyle \partial_a p =\frac{-\ell a^2-2m^2}{a^3\sqrt{m^2+\ell a^2}}=\frac{\ell}{pa^3}-\frac{2p}{a}, \qquad \partial_a(\kappa p)=-\frac{a^2+2m^2}{a^0a^3}  \vspace{5pt}\\
             \displaystyle \partial_a\left(\kappa p-\frac{1}{a^0}\right)=-\frac{m^2}{(a^0)^3a}-\frac{2m^2}{a^0a^3} ,\qquad \partial_a\left(\kappa -\frac{1}{a^0p}\right)=-\frac{\partial_a p}{p^2}\frac{m^2}{a^0a^2}-\frac{m^2}{p}\left(\frac{1}{a(a^0)^3}+\frac{2}{a^0a^3}\right).
        \end{array}
    \end{equation}
    For the second derivatives, we obtain 
    \begin{equation*}
        \begin{array}{c}
            \displaystyle \partial_a^2p=-\frac{\ell^2}{p^3a^6}-\frac{3\ell}{pa^4}+\frac{6p}{a^2},\quad  \partial_a^2(\kappa p)=\frac{2a^4+9m^2a^2+6m^4}{(a^0)^3a^4},\quad \partial_a^2\left(\kappa p-\frac{1}{a^0}\right)=\frac{12m^2a^4+15m^4a^2+6m^6}{(a^0)^5a^4},\vspace{5pt}\\
            \displaystyle \partial_a^2\left(\kappa -\frac{1}{a^0p}\right)=-\frac{\partial_a^2p}{p^2}\frac{m^2}{a^0a^2}+2\frac{(\partial_a p)^2}{p^3}\frac{m^2}{a^0a^2}+\frac{2m^2\partial_a p}{aa^0p^2}\left(\frac{2}{a^2}+\frac{1}{(a^0)^2}\right)+\frac{m^2}{a^0p}\left(\frac{1}{a^2(a^0)^2}+\frac{3}{(a^0)^4}+\frac{2}{(a^0)^2a^2}+\frac{6}{a^4}\right)
        \end{array}
    \end{equation*}
    Finally, the following estimates hold
    \begin{equation}

        \begin{array}{c}
            \displaystyle |\partial_ap|\lesssim \frac{p}{a},\qquad |\partial_a(\kappa p)|\lesssim \frac{a^0}{a^3},\qquad \left|\partial_a\left(\kappa-\frac{1}{a^0p}\right)\right|\lesssim \frac{1}{p}\frac{1}{a^0a^3},\qquad \left|\partial_a\left(\kappa p-\frac{1}{a^0}\right)\right|\lesssim \frac{1}{a^0a^3},\vspace{5pt}\\
            \displaystyle|\partial_a^2p|\lesssim\frac{p}{a^2},\qquad |\partial_a^2(\kappa p)|\lesssim \frac{a^0}{a^4},\qquad\left|\partial_a^2\left(\kappa-\frac{1}{a^0p}\right)\right|\lesssim \frac{1}{p}\frac{1}{a^0a^4},\qquad \left|\partial_a^2\left(\kappa p-\frac{1}{a^0}\right)\right|\lesssim \frac{1}{a^0a^4}.
        \end{array}
    \end{equation}

