body:
[Lemma lem:twoConnect of arXiv:2603.16824, 'Age-dependent random connection models with arc reciprocity: clustering and connectivity'] Let \(\mathscr{D}\) be the directed age-dependent random connection model with parameter \(\beta>0,\delta>1, \gamma\in(0,1)\) and \(\Gamma\geq 0\).  
\begin{enumerate}[(a)]
    \item Assume \(\gamma<\nicefrac{(\delta+\Gamma)}{(\delta+1)}\). Let \(\boldsymbol{x}=(x,t)\) and \(\boldsymbol{y}=(y,s)\) be two given vertices with \(s<t\) that further satisfy \(|x-y|^d\geq \beta s^{-\gamma}t^{\gamma-1}\). Then we have
        \begin{equation}
           \mathbb{P}_{\boldsymbol{x},\boldsymbol{y}}\Big\{\boldsymbol{x} \overset{2}{\underset{\boldsymbol{x},\boldsymbol{y}}{\rightsquigarrow}}\boldsymbol{y}\Big\}\leq \mathbb{E}_{\boldsymbol{x},\boldsymbol{y}}\big[\sharp\{\boldsymbol{z}=(z,u):u> t\text{ and }\boldsymbol{x}\rightsquigarrow\boldsymbol{z}\rightsquigarrow\boldsymbol{y}\}\big] \leq \beta C \; \mathbb{P}_{\boldsymbol{x},\boldsymbol{y}}\{\boldsymbol{x}\rightsquigarrow\boldsymbol{y}\}
        \end{equation}
    as well as
        \begin{equation}
           \mathbb{P}_{\boldsymbol{x},\boldsymbol{y}}\Big\{\boldsymbol{y}\overset{2}{\underset{\boldsymbol{x},\boldsymbol{y}}{\rightsquigarrow}}\boldsymbol{x}\Big\}\leq \mathbb{E}_{\boldsymbol{x},\boldsymbol{y}}\big[\sharp\{\boldsymbol{z}=(z,u):u> t\text{ and }\boldsymbol{y}\rightsquigarrow\boldsymbol{z}\rightsquigarrow\boldsymbol{x}\}\big] \leq \beta C \; \mathbb{P}_{\boldsymbol{x},\boldsymbol{y}}\{\boldsymbol{y}\rightsquigarrow\boldsymbol{x}\},
        \end{equation}
    where in both cases \(C=\tfrac{2^{d\delta+1}\omega_d \delta}{d(\delta-1)(\delta(1-\gamma)+\gamma-\Gamma)}\).
    \item If \(\gamma>\nicefrac{(\delta+\Gamma)}{(\delta+1)}\), we choose the two constants
        \[
            \alpha_1\in\big(1,\tfrac{\gamma-\Gamma}{\delta(1-\gamma)}\big) \text{ and then }\alpha_2\in\big(\alpha_1, \tfrac{\alpha_1(\gamma\delta-1)+\gamma-\Gamma}{\delta-1}\big).
        \]
    Let \(\boldsymbol{x}=(x,t)\) be a given vertex with \(t<\nicefrac{1}{2}\) and define the event 
    \[
        \mathcal{E}(\boldsymbol{x})=\Big\{\exists\boldsymbol{y}=(y,s):s<t^{\alpha_1}, |x-y|^d < t^{-\alpha_2} \text{ and } \boldsymbol{x} \overset{2}{\underset{\boldsymbol{x},\boldsymbol{y}}{\rightsquigarrow}}\boldsymbol{y} \Big\}.
    \]
    For all \(\beta>0\) there exists some \(a>0\) such that
    \begin{equation*}
        \mathbb{P}_{\boldsymbol{x}}\big(\mathcal{E}(\boldsymbol{x})\big) \geq 1-\exp(-t^{-a}).
    \end{equation*}
\end{enumerate}

