body:
[Lem 22 (Odd-sector Casimir reduction) of arXiv:2609.00922, 'The Morse Index, Nullity and Jacobi Fields of Constant-Curvature 2-Spheres in Complex Proj'] The involution $\mathscr P_\ell$ commutes with $T_\ell$, and the
Clebsch--Gordan eigenline indexed by $j$ has parity $(-1)^j$.  Hence
\begin{equation}

 \operatorname{Spec}\!\left(\left.T_\ell\right|_{\mathscr P_\ell=-1}\right)
 =\left\{(\ell-j)(2m+\ell-j+1):
 j=1,3,\ldots,2\min\{m,\ell\}-1\right\}.
\end{equation}
For $\ell\ge2$,
\begin{equation}

 \left.T_\ell\right|_{\mathscr P_\ell=-1}
 \sim_{\mathrm{cong}}
 \operatorname{diag}\bigl(\ell(\ell+1)-2,
 -2m(m+1)M_\ell^{\mathrm{odd}}\bigr).
\end{equation}

[Proposition 8 of arXiv:2606.20908, 'On It\^o-Stratonovich formula for rough sheets'] Let $f\in \cac^{\alpha}_1$ and $g\in \cac_1^{\beta}$ with $\alpha+\beta>1$. Then the Young integral $\int fdg$ is defined as 
\begin{equation}
\int fdg = f\delta g -\Lambda\bigl(\delta f\delta g\bigl)=\bigl[\id -\Lambda\delta \bigl](f\delta g),
\end{equation}
where $\Lambda$ is the sewing map from Proposition \ref{prop:Lambda}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 14 (Uniform centered dyadic block) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Assume~\eqref{eq:m-size}, \eqref{eq:S-size}, and Assumption~\ref{ass:time}.  For every finite $p\ge2$ and every $\eps>0$,
\begin{equation}
 \sup_{\Lambda\in\Dyd\cup\{\infty\}}
 \left\|\,
 \norm{B^{\circ}_{\Lambda,N,Q,M}}_{C(\Delta_T;\cL(L^2_q,L^2_n))}
 \right\|_{L^p(\Omega)}
 \lesssim_{p,T,\eps}
 C_m C_S^2 C_k\mathcal G(N)
 N^{d/2+\eps}
 \bigl(Q^{d/2+\eps}+M^{d/2+\eps}\bigr).
\end{equation}
Under the Galerkin-state condition in Assumption~\ref{ass:time}, the same estimate holds with the supremum over $\Lambda$ inside the $L^p$ norm, with a constant depending additionally on the uniform finite-state bound $L_{\rm cut}$.  For each fixed dyadic triple,
\begin{equation}
 B^{\circ}_{\Lambda,N,Q,M}
 \longrightarrow B^{\circ}_{\infty,N,Q,M}
 \quad\text{in }L^p\bigl(\Omega;C(\Delta_T;\cL(L^2_q,L^2_n))\bigr).
\end{equation}

