[Theorem 2 (General setting) of arXiv:2607.02777, 'Hypocoercivity for Hamiltonian Diffusions \\ with Singular Drift'] Let $d_1 \leq d_2$, let $Q\in \mathbb{R}^{d_1\times d_2}$ be of full rank, and let $\Sigma\colon \mathbb{R}^{d_2} \to \mathbb{R}^{d_2\times d_2}$ be pointwise symmetric.
		Assume \textup{($\Phi_1$1)} - \textup{($\Phi_1$4)}, \textup{($\Phi_2$1)} - \textup{($\Phi_2$5)}, \textup{($\Sigma$1)}, \textup{($\Sigma$2)}, \textup{(eL)}, and \textup{(eT)}. 
	  Let $(T_t)_{t\geq 0}$ denote the strongly continuous contraction semigroup on $L^2(E,\mu)$ generated by the closure of $(\sL, \core)$.
        Then for each $C \in (1,\infty)$ there is $\lambda \in (0,\infty)$ such that
		\begin{equation}

			\bigl\lVert T_t f - \textstyle\int\nolimits_{E} f \,\dmu \bigr\rVert_{L^2(E,\mu)} \leq C e^{-\lambda t} \bigl\lVert f - \textstyle\int\nolimits_{E} f \,\dmu \bigr\rVert_{L^2(E,\mu)} 
		\end{equation}
		for all $t\geq 0$ and $f\in L^2(E,\mu)$. Furthermore,
		\begin{equation*}
			\lambda = \frac{C-1}{C} \frac{\Cell}{n_1 + n_2 \Csigma + n_3 \Csigma^2}
		\end{equation*}
		for constants $n_1, n_2, n_3 \in (0,\infty)$ that are explicitly computable and independent of $\Sigma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 11 of arXiv:2607.27932, '2607.27932'] For $\mathcal M_0$ the set of minimizers of $\h_0$ and $\underline{\h}_0:=\h_0(\lambda_0)$ for some $\lambda_0\in \mathcal M_0$, we have: for any $\delta>0$,  

\begin{equation*}
\lim_{\varepsilon\to0}
\lim_{\sigma\to0}\PP\left(\exp\left[\frac{2}{\sigma^2}\left(\underline{\h}_0
-\delta\right)\right]<c_\varepsilon(\sigma)<
\exp\left[\frac{2}{\sigma^2}\left(\underline{\h}_0+\delta\right)\right]\right)=1\,
\end{equation*}
and
\begin{equation*}
\lim_{\varepsilon\to0}\lim_{\sigma\to0}\PP\left(\max\bigg({\rm dist}( x^\sigma_{c_\varepsilon(\sigma)},\m_0),{\rm dist}(
y^\sigma_{c_\varepsilon(\sigma)},\m_0)\le \delta\right)=1\,.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

