[Definition riesz kernel of arXiv:2504.14457, 'Abstract'] We call the Riesz kernel with exponent $\alpha$ the function given by
\begin{align}

f(x)=|x|^{-\alpha} \text{ for some } 0 < \alpha < d.
\end{align}
Its Fourier transform is given by
\begin{align}
    \hat{f}(\xi)= C_{\alpha,d}|\xi|^{(d-\alpha)}, 
\end{align}
where $C_{\alpha, d}$ is a constant independent of $\xi$.

[Corollary 8 of arXiv:2609.03962, '$L^p$ isomorphisms for the fractional Laplacian on $\mathbb{R}^n$ and their application'] Let $n\ge2$ and $s\in(0,1)$.
    \begin{itemize}
        \item[\textup{(i)}] If $sp>n$, then
        \begin{equation}
            \Norm{\frac{u}{|\cdot|^{s}}}_{L^p(\R^n)}
            \le C\,\norm{\flap u}_{L^p(\R^n)},
            \qquad\forall\,u\in C_{\mathrm{c}}^\infty(\R^n\setminus\{0\}).
        \end{equation}
        \item[\textup{(ii)}] If $sp=n$ and $R>0$, then
        \begin{equation}
            \norm{u\,\rho^{-s}\lg^{-1}}_{L^p(\R^n)}
            \le C_R\,\norm{\flap u}_{L^p(\R^n)},
            \qquad\forall\,u\in C_{\mathrm{c}}^\infty(B_R^c).
        \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] For $|u|\le1$, the pgf $\hat{G}^q(u,t)$ of $q$-iterated GCP is given by
{\small\begin{equation*}
\hat{G}^q(u,t)=\exp\Big(-\sum_{j_q=1}^{k_q}\lambda_{j_q}t\Big(1-\exp\Big(-j_q\sum_{j_{q-1}=1}^{k_{q-1}}\lambda_{j_{q-1}}\Big(\dots\Big(1-\exp\Big(-j_1\sum_{j=1}^{k}\lambda_j(1-u^j)\Big)\Big)\dots\Big)\Big)\Big)\Big).
\end{equation*}}

