[Theorem 4 (Sparre Andersen's formula: Probabilistic version) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $n\geq1$. Let $\xi_1,\dots,\xi_n$ be real-valued,
possibly dependent random variables with partial sums $S_k:= \xi_1+\dots+\xi_k$, $1\leq k\leq n$, and suppose that the following conditions are satisfied:
\begin{itemize}
\item [(i)]  \emph{Symmetric exchangeability:} For every permutation $\sigma$ of the set $\{1,\dots,n\}$ and every choice of signs $\eps_1,\dots,\eps_n\in \{-1,+1\}$, the following equality in distribution holds:
    $$
    (\xi_1,\dots,\xi_n) \stackrel{d}{=}(\eps_1 \xi_{\sigma(1)}, \dots, \eps_n \xi_{\sigma(n)}).
    $$
\item[(ii)] \emph{No partial-sum atoms at $0$:}
For every $1\leq i \leq n$, we have $\pr[S_i = 0] = 0$.
\end{itemize}
Then
    \begin{align*}
        \pr(S_1 > 0, S_2 > 0, \dots, S_n > 0) = \frac{1}{2^{2n}}
        \binom{2n}{n}.
    \end{align*}

[Defs 12 (Metric local structure) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Let~$\mcX$ be a topological local structure as in Definition~\ref{d:TLS}, and~$\mssd\colon X^\tym{2}\rar[0,\infty]$ be an extended distance. We say that~$(\mcX,\mssd)$ is a \emph{metric local structure}, if
\begin{enumerate}[$(a)$]
\item $\mcX$ is a topological local structure in the sense of Definition~\ref{d:TLS};

\item the space~$(X,\mssd)$ is a \emph{complete}  metric space;

\item $\msE=\msE_\mssd\eqdef \Bdd{\mssd}\cap \A$ is the localizing ring of $\A$-measurable $\mssd$-bounded sets (in particular~$\mssm$ is finite on~$\Ed$).
\end{enumerate}

If~$\mssd$ is finite, then it metrizes~$\T$,~\iref{i:d:EMLS:1} reduces to the requirement that~$(X,\mssd)$ be a complete metric space, and we say that~$(\mcX,\mssd)$ is a \emph{metric local structure}.

[Proposition prop:circuit-shape of arXiv:2608.23545, 'Eulerian walkers on $\Z^2$ have range exponent $2/3$'] Let $\mu$ be the passage function from
		Proposition~(prop:passage-limit of the paper).  Suppose that the passage-ball identity
		(equation eq:passage-balls of the paper) holds almost surely for every $n\geq0$ and that
		$\min_{|u|=1}\mu(u)>0$.  Define
		\begin{equation}
			B\coloneqq\{x\in\mathbb R^2:\mu(x)\leq1\}\, .
		\end{equation}
		Then $B$ is compact and convex and contains the origin in its interior.
		Almost surely,
		\begin{equation}
			n^{-1}A_n\longrightarrow B\, ,
		\end{equation}
		in Hausdorff distance.  Almost surely, for every $\varepsilon\in(0,1)$,
		\begin{equation}
			(1-\varepsilon)nB\cap V
			\subseteq A_n
			\subseteq(1+\varepsilon)nB\cap V\, ,
		\end{equation}
		for every sufficiently large $n$.

[Proposition 30 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] Suppose that \textbf{(H$_{1}$)}-\textbf{(H$_{4}$)} hold. For every $\mathbf{v}  \in  [\mathcal{C}^{\infty}_{0}(Q)\otimes \mathcal{C}^{\infty}(\Omega)\otimes A]^{d}$ we have the following convergence result: 
		\begin{equation}
			f^{\varepsilon }(\cdot , \cdot, \mathbf{v} ^{\varepsilon }) \longrightarrow \varrho \circ
			f(\cdot , \cdot, \mathbf{v} )\text{ in }L^{\Phi}(Q\times \Omega )\text{
				-weak } \digamma\,\Sigma \text{ as }\varepsilon \rightarrow 0\text{ },

		\end{equation}
		$\varrho $ being the canonical mapping from $\mathfrak{X}_{A}^{\Phi}$ into $
		\mathcal{X}_{A}^{\Phi}$ and $(\varrho \circ f(\cdot , \cdot, \mathbf{v}
		))(x,\omega ,y)=\varrho (f(x,\omega ,\cdot ,\mathbf{v} (x,\omega ,\cdot )))(y)$
		for $(x,\omega ,y)\in Q\times \Omega \times \mathbb{R}^{d}$.

		Furthermore, the mapping  $\mathbf{v} \rightarrow f(\cdot,\cdot, \mathbf{v})$ of $[\mathcal{C}^{\infty}_{0}(Q)\otimes \mathcal{C}^{\infty}(\Omega)\otimes A]^{d}$ into $L^{1}(Q\times \Omega ; \mathfrak{X}^{\Phi}_{A})$ extends by continuity to a mapping, still denoted by $\mathbf{v} \rightarrow f(\cdot,\cdot, \mathbf{v})$, of
		$L^{\Phi}(Q\times \Omega ; \mathfrak{X}^{\Phi}_{A})^{d}$ into $L^{1}(Q\times \Omega ; \mathfrak{X}^{\Phi}_{A})$ with the property 
		\begin{equation}
			\begin{array}{l}
				\parallel f(\cdot, \mathbf{v}) - f(\cdot, \mathbf{w}) \parallel_{L^{1}(Q\times \Omega ; \mathfrak{X}^{\Phi}_{A})} \\
				\leq c\, \left( \|1\|_{L^{\widetilde{\Phi}}(Q\times \Omega ; \mathfrak{X}^{\widetilde{\Phi}}_{A})} + \parallel \phi( 1+|\mathbf{v}|+ |\mathbf{w}|)\parallel_{L^{\widetilde{\Phi}}(Q\times \Omega ; \mathfrak{X}^{\widetilde{\Phi}}_{A})} \right)\parallel \mathbf{v}-\mathbf{w}  \parallel_{L^{\Phi}(Q\times \Omega ; \mathfrak{X}^{\Phi}_{A})^{d}}
			\end{array}
		\end{equation}
		for all $\mathbf{v}, \mathbf{w} \in L^{\Phi}(Q\times \Omega ; \mathfrak{X}^{\Phi}_{A})^{d}$.

[Proposition prop3.12 of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] For any dimension $d \geq 2$, there exist a probability $p_0 := p_0(d) < 1$ and an inverse temperature $\beta_0 := \beta_0(d) \in (0 , \infty)$ such that for any $p \geq p_0$ and any $\beta \geq \beta_0$:
\begin{itemize}
        \item In dimension $d = 2$, the function $x \mapsto \mathbb{E}_p^{\mathrm{site}} [  \left\langle \cos  ( \theta_0 - \theta_x ) \right\rangle_{\beta, r}^\mathrm{Vil}]$ decays polynomially fast in $|x|$.
        \item In dimension $d \geq  3$, the function $x \mapsto \mathbb{E}_p^{\mathrm{site}} [  \left\langle \cos  ( \theta_0 - \theta_x ) \right\rangle_{ \beta, r}^{\mathrm{Vil}}]$ is bounded away from $0$.
    \end{itemize}

