[Lemma 11 of arXiv:2608.21701, 'Superdiffusivity of random walks on the three-dimensional randomly oriented Manhattan latt'] There exists $C_\eps<\infty$ such that, for every $m,n\ge1$,
\begin{align}

&\frac{n}{\sqrt{z_{2m}(n)}} + \frac{n}{\sqrt{z_{2m+1}(n)}} +\frac{m(1+\log z_{2m+1}(n))}{z_{2m+1}(n)}+\frac{m(1+\log z_{2m}(n))}{z_{2m}(n)}
\le C_\eps K_2^{-1/2}\varepsilon_m.
\end{align}
Let $(c_m)_{m\ge1}$ be the sequence defined by
\eqref{eq:def.cm}. Then there
exist constants $0<c_-<c_+<\infty$ such that for each $m\ge 1$, we have
\begin{align}

c_-\le c_m\le c_+,\\

c_{2m-1}K_{\rm err}\le\frac12.
\end{align}
For sufficiently large $K_2$, we have
\begin{align}

\frac{c_{2m-1}}{K_1\sqrt{z_{2m}(n)}}
\le\frac12, \quad
 c_{2m}K_1\sqrt{z_{2m+1}(n)}
\ge
2\left(
1+c_{2m}K_{\rm err}\sqrt{z_{2m+1}(n)}
\right).
\end{align}

[Proposition prop:uniform of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Let $\pi$ be the discrete uniform distribution on $\mathcal{X} = \llbracket n \rrbracket$, and consider the group $G$ as in (equation eq:uniformG of the paper). For $P \in \mathcal{S}(\pi)$, we have
	$$P_{la} = \Pi.$$
	Consequently, $P_{ra} = (P_{la})_{ra} = \Pi$, and hence, for any $\varepsilon > 0$ and $1 \leq p \leq \infty$,
	\begin{align*}
		t_{\mathrm{mix},p}(P_{la},\varepsilon) = t_{\mathrm{mix},p}(P_{ra},\varepsilon) = t_{\mathrm{mix},p}((P_{la})_{ra},\varepsilon) = 1.
	\end{align*}

