[Defn def-kmsw of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] Let $\mathfrak Z : [0,n]\cap\mathbbm Z \to\mathbbm Z^2$ be a two-dimensional walk with increments 
\[\mathfrak Z(j) -\mathfrak Z(j-1) \in \Big\{(1,-1), (-1,0) , (0,1)\Big\}.\] 
The \textbf{KMSW procedure} builds a triangulation $\mathfrak m = \mathfrak m_n$ (possibly with some missing edges), equipped with an acyclic orientation, from $\mathfrak Z$ through the following inductive procedure. See Figure~(fig-kmsw of the paper) for an illustration. 

Let $(\mathfrak m_0,\lambda_0)$ be the map consisting of a single directed active edge $\lambda_0$. The only non-empty boundaries of this map are the upper-left and lower-right boundaries (which coincide). We assume that this single edge is drawn in the plane so that it is oriented from west to east.

Inductively, suppose $j\in [1,n]\cap\mathbbm Z$ and a directed map $(\mathfrak m_{j-1},\lambda_{j-1})$ with an active edge $\lambda_{j-1} \in \mathcal E(\mathfrak m_{j-1})$ (and possibly missing edges) have been defined and drawn in the plane so that all its edges are oriented from south-west to north-east. 
We let $(\mathfrak m_j,\lambda_{j})$ be the directed triangulation with an active edge (and possibly missing edges) obtained from $(\mathfrak m_{j-1},\lambda_{j-1})$ as follows:
\begin{itemize}
\item If $\mathfrak Z(j) - \mathfrak Z(j-1) = (1,-1)$, we construct $(\mathfrak m_j,\lambda_{j})$ in the following way:
\begin{itemize}
    \item If the upper-right boundary of $\mathfrak m_{j-1}$ is not empty, we consider the missing edge of the upper-right boundary of $\mathfrak m_{j-1}$ immediately to the east of $\lambda_{j-1}$ and construct $(\mathfrak m_j,\lambda_{j})$ by adding this edge  to the set of edges of $\mathfrak m_{j-1}$, orienting this edge from west to east and setting $\lambda_{j}$ equal to this new edge. See, for instance, how the triangulation $\mathfrak m_3$ is obtained from the triangulation $\mathfrak m_2$ in (fig-kmsw of the paper).

    \item Otherwise, we construct $(\mathfrak m_j,\lambda_{j})$ by adding to the set of edges of $\mathfrak m_{j-1}$ a new active edge $\lambda_{j}$ oriented from west to east, whose initial vertex coincides with the terminal vertex of $\lambda_{j-1}$. Note that $\lambda_{j}$ does not lie on the boundary of any triangle of $\mathfrak m_{j}$. See, for instance, how the triangulation $\mathfrak m_9$ is obtained from the triangulation $\mathfrak m_8$ in (fig-kmsw of the paper).
\end{itemize}

\item If $\mathfrak Z(j) - \mathfrak Z(j-1)= (-1,0)$, we construct $(\mathfrak m_j,\lambda_j)$ by adding to $\mathfrak m_{j-1}$ a new triangular face $t_j$ with a new directed edge $\lambda_{j}$ on the boundary of $t_j$ with the following properties:  The edges $\lambda_{j-1}$ and $\lambda_{j}$ both lie on the boundary of $t_j$, and their terminal vertices coincide. Moreover,
\begin{itemize}
    \item if the upper-left boundary of $\mathfrak m_{j-1}$, excluding $\lambda_{j-1}$, is not empty,  the third edge on the boundary of $t_j$ is the edge of the upper-left boundary of $\mathfrak m_{j-1}$, which lies immediately to the west of $\lambda_{j-1}$. In particular, the initial vertex of this edge coincides with the initial vertex of $\lambda_{j}$. See, for instance, how the triangulation $\mathfrak m_5$ is obtained from the triangulation $\mathfrak m_4$ in (fig-kmsw of the paper);
    \item otherwise, the third edge on the boundary $t_j$ is a new \emph{missing} edge,  with one vertex equal to the initial vertex of $\lambda_{j-1}$. Moreover, the other vertex of this missing edge coincides with the initial vertex of $\lambda_{j}$. See, for instance, how the triangulation $\mathfrak m_1$ is obtained from the map $\mathfrak m_0$ in (fig-kmsw of the paper);
\end{itemize}

\item If $\mathfrak Z(j) - \mathfrak Z(j-1) = (0,1)$, we construct $\mathfrak m_j$ by adding to $\mathfrak m_{j-1}$ a new triangle $t_j$ and a new directed edge $\lambda_{j}$ with the following properties. The edges $\lambda_{j-1}$ and $\lambda_{j}$ both lie on the boundary of $t_j$, and

[Theorem 30 (Transference of blow-up criteria) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $p\in (2,\infty),\kappa\in [0,p/2-1),q\in [2,\infty)$. Assume that one of the following settings holds:
		\begin{enumerate}
			\item $d\in \{1,2\}, X_0=\bpsn{-2-s,q}$, $X_1=\bpsn{2-s,q}$, $s\in [0,2)$,~\eqref{eq:lwp:rough:initial:data:1},~\eqref{eq:lwp:rough:initial:data:2}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg1} hold.
			\item $d\in \{1,2\}$, $ X_0=\bpsn{-2-s,q}$, $ X_1=\bpsn{2-s,q}$, $ s\in [0,1)$,~\eqref{eq:lwp:rough:initial:data:1},~\eqref{eq:lwp:rough:initial:data:2}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg2} hold.
			\item $d\in \{3,4\}$, $ X_0=\bpsn{-1-s,q}$, $ X_1=\bpsn{3-s,q}$, $ s\in [0,2)$,~\eqref{eq:lwp:rough:initial:data:3},~\eqref{eq:lwp:rough:initial:data:4}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg3} hold.
            \item $d\in \{3,4\}$,  $X_0=\bpsn{-1-s,q}$, $ X_1=\bpsn{3-s,q}$, $ s\in [0,1)$,~\eqref{eq:lwp:rough:initial:data:3},~\eqref{eq:lwp:rough:initial:data:4},
            and Assumption~\ref{Assumption:noise}\ref{assumption:hg4} hold. 
		\end{enumerate}

		\begin{itemize}
				\item 	Assume~\ref{it:gwp:rough:initial:data:1} or~\ref{it:gwp:rough:initial:data:2} with $d=1$ holds, let  $u_0\in L^0_{\F_0}(\Omega;\,_\nu B_{q,p}^{2-s-4\frac{1+\kappa}{p}}(\sO))$, and let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution granted by Theorem~\ref{lwp:rough:initial:data}. Then for all  $0<t_0<T<\infty$ it holds that
				\begin{equation}
				\P\bigg(t_0<\sigma<T, \sup_{t\in [t_0,\sigma)}\nrm{u(t)}_{L^2(\sO)}<\infty\bigg)=0.
				\end{equation}
                \item 	Assume~\ref{it:gwp:rough:initial:data:1} or~\ref{it:gwp:rough:initial:data:2} with $d=2$ holds, let  $u_0\in L^0_{\F_0}(\Omega; \,_\nu B_{q,p}^{2-s-4\frac{1+\kappa}{p}}(\sO))$, and let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution granted by Theorem~\ref{lwp:rough:initial:data}. Then for all  $0<t_0<T<\infty$ it holds that
				\begin{equation}
				\P\bigg(t_0<\sigma<T, \sup_{t\in [t_0,\sigma)}\nrm{u(t)}_{L^2(\sO)}+\nrm{u}_{L^2(t_0,\sigma; H^2(\sO))}<\infty\bigg)=0.
				\end{equation}
				\item Assume~\ref{it:gwp:rough:initial:data:3} or~\ref{it:gwp:rough:intial:data:4} with $d=3$  holds, let $u_0\in L^0_{\F_0}(\Omega; \,_\nu B_{q,p}^{3-s-4\frac{1+\kappa}{p}}(\sO))$, and let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution to \eqref{SCH} granted by Theorem~\ref{lwp:rough:initial:data}. Then for all $0<t_0<T<\infty$ it holds that 
				\begin{equation}
					\P\bigg(t_0<\sigma<T, \sup_{t\in [t_0,\sigma)}\nrm{u(t)}_{\bpsn{1}}<\infty\bigg)=0.
				\end{equation}
                \item Assume~\ref{it:gwp:rough:initial:data:3} or~\ref{it:gwp:rough:intial:data:4} with $d=4$ holds, let $u_0\in L^0_{\F_0}(\Omega;\,_\nu B_{q,p}^{3-s-4\frac{1+\kappa}{p}}(\sO))$, and let $(u,\sigma)$ be the $(p,\kappa,s,q)$-solution to \eqref{SCH} granted by Theorem~\ref{lwp:rough:initial:data}. Then for all $0<t_0<T<\infty$ it holds that 
				\begin{equation}
					\P\bigg(t_0<\sigma<T, \sup_{t\in [t_0,\sigma)}\nrm{u(t)}_{\bpsn{1}}+\nrm{u}_{L^2(t_0,\sigma; \bpsn{3})}<\infty\bigg)=0.
				\end{equation}
		\end{itemize}

