[Definition def-fixed-point of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] A point process $\Pi$ is called a fixed point\footnote{Since this is a non-standard definition, we here and henceforth use the term \textit{fixed points} to avoid any confusion with invariant distributions.} of BBM with drift $\lambda$ if for all $f\in C_c^+(\mathbb{R})$ and for all $t\geq 0$,

    \begin{equation}
        \mathbb{E}[e^{-\langle f, \theta_t^\lambda \rangle}] = \mathbb{E}[e^{-\langle f, \theta_0^\lambda \rangle}],
     \end{equation} 
    where $\theta_t^\lambda$ is given by (equation theta_t-def of the paper) with $\theta_0^\lambda = \Pi$.

[Theorem 3 (Intrinsic tangential Hadamard differentiability) of arXiv:2608.06393, 'Intrinsic Tangential Hadamard Differentiability of Rough-BSDE Solution Maps'] Suppose Assumption~\ref{ass:coefficients} holds, and fix
$\mathbf x\in WG\Omega_p(E)$. There is a unique continuous linear map
\begin{equation}
 A_{\mathbf x}:\mathbb T_{\mathbf x}^p
 \longrightarrow\mathcal X
\end{equation}
with the following properties.

\begin{enumerate}
 \item Let
 \[
  \mathfrak r:\{\tau\in\mathbb T_{\mathbf x}^p:
                    \|\tau\|_{\mathbb T_{\mathbf x}^p}\leq1\}
  \longrightarrow\bigcup_\tau\operatorname{Rep}_{\mathbf x}(\tau)
 \]
 be any set-theoretic assignment such that
 $\mathfrak r(\tau)\in\operatorname{Rep}_{\mathbf x}(\tau)$ and
 \begin{equation}
  \sup_{\|\tau\|_{\mathbb T_{\mathbf x}^p}\leq1}
  \mathfrak b\bigl(\mathfrak r(\tau)\bigr)<\infty.
 \end{equation}
 Writing $\mathfrak r(\tau)=(\mathbf Z_\tau,a_\tau)$, one has
 \begin{equation}
  \lim_{\varepsilon\to0}
  \sup_{\|\tau\|_{\mathbb T_{\mathbf x}^p}\leq1}
  \left\|
   \frac{\mathcal S(\mathbf x^{\varepsilon;\mathbf Z_\tau,a_\tau})
         -\mathcal S(\mathbf x)}{\varepsilon}
   -A_{\mathbf x}\tau
  \right\|_{\mathcal X}=0.
 \end{equation}

 \item Let $\varepsilon_n\to0$, $\varepsilon_n\neq0$, let
 $\tau_n\to\tau$ in $\mathbb T_{\mathbf x}^p$, and let
 $\mathbf x_n\in WG\Omega_p(E)$ have strong levelwise variation contact
 with $(\varepsilon_n,\tau_n)$ in the sense of
 Definition~\ref{def:strong-contact}. Then
 \begin{equation}
  \frac{\mathcal S(\mathbf x_n)-\mathcal S(\mathbf x)}{\varepsilon_n}
  \longrightarrow A_{\mathbf x}\tau
  \qquad\text{in }\mathcal X.
 \end{equation}

 \item The value $A_{\mathbf x}\tau$ depends only on the tensor tangent
 $(h,\kappa)$. It is independent of the joint lift, the decomposition of
 $\kappa$ into cross and central parts, and the self-area used in a radial
 realization.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

