[Theorem thm_momgenspider of arXiv:2411.09976, 'Occupation times on the legs of a diffusion spider'] Let $T$ be exponentially distributed with mean $1/\lambda$, $\lambda>0$, and independent of $\mathbf{X}$. 
Then, for any $z_1,\dotsc,z_R \geq 0$, 

\begin{equation} 

\mathbf{E}_\mathbf{0}\Biggl(\mathrm{exp}\biggl(- \sum_{i=1}^R z_i A_T^{(i)}\biggr)\Biggr) 
= \frac{\displaystyle 1-\sum_{j=1}^R \frac{\lambda z_j}{\lambda + z_j} \int_0^\infty \mathbf{g}_\lambda(\mathbf{0},(y,j)) \left(1 - \mathbf{E}_{(y,j)}(\mathrm{e}^{-(\lambda+z_j) H_\mathbf{0}}) \right)\beta_j\, m(\mathop{}\!\mathrm{d} y)}{\displaystyle 1+ \sum_{j=1}^R z_j \int_0^\infty \mathbf{g}_\lambda(\mathbf{0},(y,j)) \mathbf{E}_{(y,j)}(\mathrm{e}^{-(\lambda+z_j) H_\mathbf{0}})\beta_j\, m(\mathop{}\!\mathrm{d} y)}. 
\end{equation}

