body:
[Proposition 22 (Az\'ema--Yor certificates and the per-step form of the optional-stopping deficit) of arXiv:2608.20337, 'Information on trajectories:\\ martingales and random times'] Let $(M_t)_{t=0}^T$ be a nonnegative martingale with deterministic $M_0$ and $M^\ast_t:=\max_{s\le t}M_s$,
let $\Phi$ be $C^1$ and concave on $(0,\infty)$, and set
\begin{equation}
  A^\Phi_t \;:=\; \Phi(M^\ast_t)-(M^\ast_t-M_t)\,\Phi'(M^\ast_t),
  \qquad
  D_{-\Phi}(a,b)\;:=\;\Phi(b)-\Phi(a)+(a-b)\,\Phi'(b)\;\ge\;0,
\end{equation}
with $D_{-\Phi}$ the Bregman divergence of the convex function $-\Phi$.
Assume every expectation below is finite.
\begin{enumerate}[label=(\roman*),leftmargin=2em]
\item $A^\Phi$ is a supermartingale with an exact increment:
  \begin{equation}
    A^\Phi_t-A^\Phi_{t-1}
    \;=\;(M_t-M_{t-1})\,\Phi'(M^\ast_{t-1})\;-\;D_{-\Phi}\bigl(M^\ast_t,M^\ast_{t-1}\bigr).
  \end{equation}
\item The record obeys the exact identity
  \begin{equation}
    \E\bigl[\Phi(M^\ast_T)\bigr]
    \;=\;\Phi(M_0)
    \;+\;\E\bigl[(M^\ast_T-M_T)\,\Phi'(M^\ast_T)\bigr]
    \;-\;\E\Bigl[\sum_{t=1}^{T}D_{-\Phi}\bigl(M^\ast_t,M^\ast_{t-1}\bigr)\Bigr].
  \end{equation}
\item For $p>1$ and its conjugate exponent $q:=\tfrac{p}{p-1}$, at $\Phi(y)=-y^{p}/(p-1)$ the process $A^\Phi_t$ is $U(M_t,M^\ast_t)$ for the certificate function
  \begin{equation}
    U(x,y)\;:=\;y^{p}-q\,y^{p-1}x,
    \qquad 0<x\le y,
  \end{equation}
  and the optional-stopping deficit $A^\Phi_0-\E\bigl[A^\Phi_T\bigr]$ is the record's Bregman sum $\E\bigl[\sum_{t=1}^{T}D_{-\Phi}(M^\ast_t,M^\ast_{t-1})\bigr]$.
\end{enumerate}
For a nonnegative submartingale and $\Phi$ in addition nonincreasing, which $-y^{p}/(p-1)$ is, (i) holds verbatim and $A^\Phi$ is again a supermartingale, while the optional-stopping deficit $A^\Phi_0-\E\bigl[A^\Phi_T\bigr]$ exceeds the Bregman sum of (iii) by $-\E\bigl[\sum_t (M_t-M_{t-1})\Phi'(M^\ast_{t-1})\bigr]\ge0$, the drift weighted by the certificate's slope. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d:DirInt of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] {Dix81}}]
\
Let~$(Z,\mcZ,\nu)$ be a $\sigma$-finite measure space,~$\left(H_\zeta\right)_{\zeta\in Z}$ be a family of separable Hilbert spaces, and~$F$ be the linear space~$F\eqdef \prod_{\zeta\in Z} H_\zeta$. We say that~$\zeta\mapsto H_\zeta$ is a \emph{$\nu$-measurable field of Hilbert spaces} (\emph{with underlying space~$S$}) if there exists a linear subspace~$S$ of~$F$ with
\begin{enumerate}[$(a)$]
\item for every~$u\in S$, the function~$\zeta\mapsto \left\lVertu_\zeta\right\rVert_{\zeta}$ is $\nu$-measurable;
\item if~$v\in F$ is such that $\zeta\mapsto \scalar{u_\zeta}{v_\zeta}_{\zeta}$ is $\nu$-measurable for every~$u\in S$, then~$v\in S$;
\item there exists a sequence~$\left(u_n\right)_n\subset S$ such that~$\seq{u_{n,\zeta}}_n$ is a total sequence\footnote{A sequence in a Banach space~$B$ is called \emph{total} if the strong closure of its linear span coincides with~$B$.} in~$H_\zeta$ for every~$\zeta\in Z$.
\end{enumerate}

Any such $S$ is called a \emph{space of $\nu$-measurable vector fields}. Any sequence in~$S$ possessing property~(i:d:DirInt3 of the paper) is called a \emph{fundamental} sequence.

[Lemma eq:LTH_0-nsp of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For any $\gamma\geq 0$, under the Palm probability measure $\mathbb{P}_{\mathcal V }^0$ of handover, the Laplace transform of $\hat{H}^2$ is

\begin{align}
{\mathcal L }^0_{\hat{H}^2}(\gamma)&= \frac{1}{\lambda_{{\mathcal V }}}\frac{4\sqrt{\lambda}}{\pi}\left(1+\frac{\gamma}{\lambda\pi}\right)^{-3/2} \sum_{i\in [n]} v_i\left(\frac{\lambda_i}{\lambda}\right)^2
+ \frac{8}{\lambda_{{\mathcal V }}}\sum_{j<i\in [n],k\in \{1,2\}} \lambda_i\lambda_jv_iv_j\, \eta^{(k)}_{i,j}(\gamma),

\end{align}

where $\eta^{(k)}_{i,j}(\gamma)$ can be determined as in ((eq:H0-ij1 of the paper)) and  ((eq:H0-ij2 of the paper)) for $j<i\in [n]$ and $k\in \{1,2\}$ and $\Lambda_{i, j}^{(k)}= 4\lambda_i\lambda_jv_iv_j\,\eta^{(k)}_{i,j}(0)$, for $k=1,2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:fs_uppertail_interval of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] There exist constants $C,c > 0$ such that for all $S \geqslant 1$ and $y > 0$ we have
\begin{equation}
    \mathbb{P} \mleft[ \max_{s \in [-S,S]} Y_{\mathrm{FS}}(s) > y \mright] \leqslant
    C S e^{- c y^{3/2}}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

