[Theorem 10 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, the measure $\bnu$ admits the decomposition
        \begin{align}
                \bnu(\dd E) = \bnu(\{0\})\delta_0(\dd E) + \rho(E)\mb 1(E>0)\dd E, 
        \end{align}
        where $\rho$ is a nonnegative function on $(0,\infty)$ given by
        \begin{align}
                \rho(E) = \frac1\pi\lim_{\eta\downarrow0}\Im m(E+\ii\eta). \nonumber
        \end{align}
        Moreover, $\rho$ is locally $1/3$-H\"older continuous on $(0,\infty)$.
        Finally, $\rho$ is real analytic on the open set $\{E\in(0,\infty):\rho(E)>0\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 45 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] Let $p,a\in\bfN^{d+1}$ such that $|p|+|a|<\gamma$, suppose that $\partial^q_*u_\nu = u_{(\downarrow^q)^*\nu}$ for any $|q|+|\mcI(\nu)|<  |p|+|a|$. We have 
	\begin{equation}
	\partial^p\widetilde\partial^a_* u - \sum_{|\mcI_a(\mu)|\in(0,|p|)} u_\mu \overline{Z}_{\mcI_{p+a}\mu} = \widetilde\partial^{p+a}_* u .
\end{equation}

