[Lem lem-holo-asymp of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] Let $\mathbbm D = \{z\in\mathbbm C : |z| < 1\}$. Let $\psi : \overline{\mathbbm D} \to \mathbbm C$ be holomorphic on $\mathbbm D$ and continuous on $\overline{\mathbbm D}$.
Assume that there exists $\nu \in (0,1)$ and $c \in \mathbbm C \setminus i \mathbbm R$ such that
\begin{equation} 
\psi(e^{i t}) = 1 + (c \mathbbm 1_{(t > 0)} + \overline c \mathbbm 1_{(t < 0)} ) |t|^\nu  + o(t^\nu)  ,\quad \text{as $t \to 0$}. 
\end{equation} 
Then setting $b  = \operatorname{Re}(c)\sec\Big(\tfrac{\pi\nu}{2}\Big)  \in \mathbbm R\setminus \{0\}$,
\begin{equation} 
\psi(1-r) = 1  + b r^\nu + o(r^\nu)  ,\quad \text{as $r \to 0$}. 
\end{equation}

