[Theorem thm:moment of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] With $\boldsymbol{Q}$ Haar distributed ${\mathbb{F}}$-unitary matrix, we have
\begin{align*}
 E_{\mathbf{Q}} | \det \mathbf{M}({\lambda}, \mathbf{Q}) |^{\beta s} = c_{n, \beta, r,\beta s} \times
 \begin{cases}
 \sum\limits_{(\mathcal{A}_1,\dots, \mathcal{A}_r)\in {\mathcal P}_{r,n}} \prod_{j=1}^r \Delta(\mathcal{A}_j)^2 & \mbox{for } r \ge2, \ \beta s=2,\\[10pt]
 \sum\limits_{(\mathcal{A},\mathcal{A}')\in {\mathcal P}_{2,n}} \Delta(\mathcal{A})^4 \Delta(\mathcal{A}')^4 & \mbox{for } r=2, \ \beta s = 4,
 \end{cases}
\end{align*}
where
\begin{align*}
 c_{n,\beta, r, \beta s} =(\beta/2) ^{\frac{\beta}{2}rsn} \prod_{i=1}^{r}
\frac{\Gamma \bigl(\frac{\beta }{2}(rn+1-i)\bigr)}{ \Gamma \bigl(\frac{\beta}{2}((r+s)n+1-i) \bigr)} \times \begin{cases}
 1, &r\ge2,\ \beta s=2,\\
 (12/\beta)^n, &r=2,\ \beta s=4.
\end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2607.23526, 'Equivalence of Canonical and Microcanonical Ensembles for Euclidean Lattices'] The functions $Z$, $\psi$, $m$, and $\sigma^2$ are real analytic on $(0,+\infty)$, and
\begin{equation}
\psi'(\beta)=-m(\beta),\quad\psi''(\beta)=\sigma^2(\beta)>0,\quad m'(\beta)=-\sigma^2(\beta)<0.
\end{equation}
Moreover, $m(\beta)\to0$ as $\beta\to+\infty$ and $m(\beta)\to+\infty$ as $\beta\downarrow0$.  Hence $m:(0,+\infty)\to(0,+\infty)$ is a real-analytic decreasing bijection.

