[Lemma J of arXiv:2504.14457, 'Abstract'] If $m=0$, we have
	$$J_{\mathbf{0}}(t;\mathbf{t},\mathbf{x}) = \prod_{k=1}^{n} w(t+t_k,x_k).$$
	If $m > 0$, we have
	\begin{align*}
	\lefteqn{J_{\mathbf{m}}(t;\mathbf{t},\mathbf{x})}\\
	& = \sum_{\underset{m_a m_b > 0}{(a,b) \in \mathcal{P}_n}} \int_{0}^{t} ds \int_{\mathbb{R}^d} dy_1 \int_{\mathbb{R}^d} dy_2 \, (t-s)^{2H-1} p_{t_a+s}(x_a-y_1) f(y_1-y_2) p_{t_b+s}(x_b - y_2) \\
	& \qquad \qquad \times J_{\mathbf{m}'(a,b)}(t-s;\gamma_{a,b}(\mathbf{t},s),\psi_{a,b}(\mathbf{x},y_1,y_2)),
	\end{align*}
	where $\mathbf{m}'(a,b)$ and $\psi_{a,b}$ are defined as in Lemma (lemma:I of the paper) and
	\begin{itemize}
		\item $\gamma_{a,b}(\mathbf{t},s)_a = \gamma_{a,b}(\mathbf{t},s)_b = 0$, and $\gamma_{a,b}(\mathbf{t},s)_k = t_k + s$ for $k \neq a,b$;
	\end{itemize}

