[Theorem burk_thm of arXiv:2506.09364, 'A collection of results relating the geometry of plane domains and the exit time of planar'] Suppose $h$ is a positive function on a domain $D$ satisfying $(i)$ and $(ii)$ above. Suppose also that

    \begin{enumerate}
    \item[$(iii)$] There is a constant $C>0$ such that $h(z) \leq C(1+|z|^2)$ for all $z \in D$.
\end{enumerate}

Then $h(a) = E_a[T(D)]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_splitting_different_R_j of arXiv:2609.00973, 'The Vlasov-Maxwell point charge system : study of the spherically symmetric case'] Let $(t,r,\ell)\in [T_0,\infty)\times\R^*_+\times\R_+$ be fixed and 
    \begin{equation}

        A:=F^{-1}(r-\hbar),\qquad \hbar:=\frac{C}{t^4}\frac{r^2}{(r+1+\sqrt{\ell})^2},
    \end{equation}
    where $F^{-1}$ denotes the inverse function of $F(a):=\frac{a^0+\sqrt{m^2+\ell a^2}}{a^2}=\kappa p +p$ and $C>0$ is a constant depending only on $m$.
    We consider the subspaces 
    \begin{equation*}
        \begin{array}{c}
             \displaystyle\mathcal{R}_0:=\{(\theta,a)\in \R\times\R^*_+\,|\, a\leq A\}, \vspace{5pt}\\
              \displaystyle\mathcal{R}_1:=\{(\theta,a)\in \R\times\R^*_+\,|\, a> A,\,\theta< -t\widehat a\},\quad \mathcal{R}_2:=\{(\theta,a)\in \R\times\R^*_+\,|\, a> A,\,\theta> -t\widehat a\}.
        \end{array}
    \end{equation*}
    In $\mathcal{R}_0$, for any fixed $\theta\in\R$, there exists at most one $a:=\aleph(\theta;t,r,\ell)$ solution to (equation equation_curve_R_r of the paper). Moreover, it satisfies 
    \begin{equation}

        |\partial_a\widetilde{R}(\theta,\aleph)|\geq \frac{3m}{4\aleph^3}.
    \end{equation}
    In $\mathcal{R}_1$ (resp. $\mathcal{R}_2$) for each $a>A$, there exists a unique $\theta:=\theta_1(a;t,r,\ell)$ (resp. $\theta:=\theta_2(a;t,r,\ell)$) solution to (equation equation_curve_R_r of the paper). Moreover, we have the following estimates
    \begin{equation}

        \frac{1}{|\partial_\theta\widetilde{R}(\tau_j,a)|}\lesssim t^3 \frac{a^2}{a^0}+t^2\left(a|\theta_j|+\sqrt{\ell}(1+a)+a^{-1}+a\right),\qquad j=1,2.
    \end{equation}

