[Def of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] In what follows, fix $L\in\mathbb{N}_+$, let $0\leq j\leq L$ and $\eta\in\Omega_N$ be arbitrary:
    \begin{itemize}
        \item Introduce the set $W_j^L:=\llbracket -j,-j+L+1\rrbracket\backslash\{0,1\}$; 



        \item Let $m_j^L(\eta)$ be the number of particles in $W_j^L$;

        \item Let ${\langle \eta\rangle}_{W_j^L}=\tfrac{1}{L}m_j^L(\eta)$ be the density of particles in the box $W_j^L$.
    \end{itemize}

[Definition 1 of arXiv:2609.00736, 'Modalities in non-classical variations of S4'] A \emph{(modal) logic} is a set of formulas closed under necessitation and \emph{modus ponens}:
        \[
            \ax{Nec}:=\frac{\varphi}{\Box\varphi} \text{ and } \ax{MP} :=\frac{\varphi \;\;\; \varphi\to\psi}{\psi}.
        \]
    We write $\Lambda\vdash\varphi$ for $\varphi\in\Lambda$.
    $\csf$ is the least logic containing all intuitionistic tautologies, and the axioms:
    \begin{itemize}
        \item ${\ax K} := (\Box(\varphi\to\psi) \to (\Box\varphi \to \Box \psi)) \land (\Box(\varphi\to\psi) \to (\Diamond\varphi \to \Diamond \psi))$;
        \item ${\ax 4} := (\Box\varphi \to \Box\Box\varphi) \land (\Diamond\Diamond\varphi \to \Diamond \varphi)$;
        \item ${\ax T} := (\Box\varphi \to \varphi) \land (\varphi \to \Diamond \varphi)$.
    \end{itemize}

