body:
[Proposition Asymptotics of martingale M_n of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
    Assume $\mathbb E(\xi_1^2) =1$. Then, for the martingale $\{M_n\}_{n\geq 1}$, we have
    \begin{equation}{}
        \mathbb{E}(M_n^2)=\sum_{k=1}^{n}a_k^2\mu_k^2-p^2\sum_{k=1}^{n-1}\left(\frac{a_{k+1}\mu_{k+1}}{a_k\nu_{k}}\right)^2\mathbb{E}(M_{k}^2).
    \end{equation}

    In particular, if $\sum_{k=1}^\infty a_k^2\mu_k^2=\infty$, then 
    \begin{align} 
        \mathbb{E}(M_n^2) \sim \begin{cases}
             \frac{a_n^2\mu_n^2}{2(1-p)(\gamma+1)-1}n, & \text{if } 0\leq p<p_c,\\
            a_n^2\mu_n^2 \sigma_n^2, & \text{if } p=p_c,
        \end{cases}.
    \end{align}

On the other hand, if $\sum_{k=1}^\infty a_k^2\mu_k^2<\infty$, then
    $\sup_{n\geq 1}\mathbb{E}(M_n^2)<\infty$,
    and the martingale $M_n$ converges almost surely and in $L^2$ to a nondegenerate random variable, denoted as $M_\infty$.

[Lemma 24 (Concentration in window) of arXiv:2609.01143, 'The voter model on the hyperbolic graph'] Fix $0\leq\varphi<2-2\alpha$, put $p=2-\varphi$, and set
\[
\mathcal W_n:=\left\{v: \left|h(v)-\frac{R}{2\alpha}\right|\leq A_0\log\log n\right\}
\]
for a fixed $A_0>0$. Then, with high probability,
\begin{equation}
\sum_{v\notin\mathcal W_n}\de(v)^p=o(M_p), \qquad |\mathcal W_n|\leq(\log n)^{O(1)}.                       
\end{equation}

Also with high probability, uniformly for $v\in\mathcal W_n$,
\[
\de(v)=n^{1/(2\alpha)}(\log n)^{O(1)}.
\]

[Definition 22 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let $\pi$ be an $\rmbeta$-preproof of the form
    \begin{equation*}
    \begin{mathprooftree}
        \AxiomC{$\pi'$}
        \noLine
        \UnaryInfC{$\vdots$}
        \RightLabel{($\rmR$)}
        \UnaryInfC{$[\ttX] \vdash \Gamma$}
    \end{mathprooftree}
    \end{equation*}
    $\alpha$ is a linear order, and $f\colon \ttX\to \alpha$ is an increasing function that can be thought of as an assignment of variables. We define the \emph{instantiation} $\pi[\alpha,f]$ corecursively as follows: 
    If the last inference rule $\rmR$ of $\pi$ is other than $\forall^\ord$, we define $\pi[\alpha,f]$ by
    \begin{equation*}
    \begin{mathprooftree}
        \AxiomC{$\pi'[\alpha,f]$}
        \noLine
        \UnaryInfC{$\vdots$}
        \RightLabel{($\rmR$)}
        \UnaryInfC{$\Gamma[f]$}
    \end{mathprooftree}
    \end{equation*}
    Here we define $A[f]$ for an $\LK_\rmbeta$-formula $A$ as a formula obtained from $A$ by replacing an occurrence of $v\in \ttX$ by $f(v)\in \alpha$. Then we define $\Gamma[f]$ as the sequent of $A[f]$ for $A\in\Gamma$.
    If $\rmR$ is $\forall^\ord$, then $\Gamma$ is $\Gamma',\forall^\ord x A(x)$, and $\pi$ would take the form
    \begin{equation} 
    \begin{mathprooftree}
        \AxiomC{$\pi'_{\ttX'}$}
        \noLine
        \UnaryInfC{$\vdots$}
        \noLine
        \UnaryInfC{$\cdots\ [\ttX']\vdash A(w), \Gamma'\ \cdots$}

        \AxiomC{$\pi'_{\ttX,v}$}
        \noLine
        \UnaryInfC{$\vdots$}
        \noLine
        \UnaryInfC{$\cdots\ [\ttX]\vdash A(v), \Gamma'\ (v\in \ttX)\ \cdots$}

        \RightLabel{($\forall^\ord$)}
        \BinaryInfC{$[\ttX] \vdash \Gamma$}
    \end{mathprooftree}
    \end{equation}
    Here, $\ttX'$ is an one-element extension of $\ttX$, and $w\in \ttX'\setminus \ttX$. Then we define $\pi[\alpha,f]$ as follows:
    \begin{equation*}
    \begin{mathprooftree}
        \AxiomC{$\pi'_{\ttX'}[\alpha,g]$}
        \noLine
        \UnaryInfC{$\vdots$}
        \noLine
        \UnaryInfC{$\cdots\ A[\alpha,f](g(w)), \Gamma'[\alpha,f]\ \cdots$}

        \AxiomC{$\pi'_{\ttX,v}[\alpha,f]$}
        \noLine
        \UnaryInfC{$\vdots$}
        \noLine
        \UnaryInfC{$\cdots\ A[\alpha,f](f(v)), \Gamma'[\alpha,f]\ (v\in \ttX)\ \cdots$}

        \RightLabel{($\forall^\ord$)}
        \BinaryInfC{$\Gamma[\alpha,f]$}
    \end{mathprooftree}
    \end{equation*}
    Here we enumerate the left-hand side for all possible $g\colon \ttX'\to \alpha$ that extend $f\colon \ttX\to \alpha$.

[Thm Sprobab+killing of arXiv:2608.13084, '\bf Branching random walk in random environment'] Suppose that $\mu_\bullet = \delta_0$ and $m_\circ >1$. 
\begin{itemize}
\item \textbf{Infinite cluster case.} If $\theta_{{\mathbb Z}^d}(p)>0$, then for ${\bf P}_p$-a.s. $\omega \in\{\#\mathcal{C}(0)=\infty\}$, we have
\begin{equation*}
{\mathbb P}^\omega(S) >0.
\end{equation*}
\item \textbf{Finite cluster case.} For any $p\in(0,1)$, ${\bf P}_p$-a.s., we have
\begin{equation*}
\{\omega : {\mathbb P}^\omega(S)>0\} \cap  \{\#\mathcal{C}(0)<\infty\} \overset{a.s.}{=} \{\omega:  \#\mathcal{C}(0)<\infty, \ \rho_{\mathcal{C}(0)}m_\circ >1\}.
\end{equation*}
Therefore, 
\begin{equation}
{\bf P}_p(\omega: {\mathbb P}^\omega(S)>0) = \theta_{{\mathbb Z}^d}(p) + {\bf P}_p\left( \omega:  \#\mathcal{C}(0)<\infty, \ \rho_{\mathcal{C}(0)}m_\circ >1 \right).
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 98 (occupation density under ideal smoothing) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let
$\hvY(t) = \vY(t-\sss)+\xxx$
where $(\sss,\xxx)\sim\varphi$ is sampled independently of $\vY$. If $\vY$ has occupation measure $\rho_{\vY}$ as given by Definition~\ref{d:intro.cts.occ}, then $\hvY$ has occupation measure
$\rho_{\vY}*\varphi$ (the convolution of $\rho_{\vY}$ with $\varphi$).\footnote{Note that at times close to $1$ or $q_0$, $\hvY$ may not in general be well defined, since $t-\sss$ can can lie outside the time interval $[q_0,1]$. In the full proof, we work on a subinterval $[q_*,1]\subsetneq [q_0,1]$ and choose $\varphi$ such that $0\leq \sss\leq q_0-q_*\ll 1$ almost surely, thus circumventing these issues. See \eqref{e:qbar.and.qstar} and Definition~\ref{d:t.smooth}.}

\begin{proof}
For the purposes of this proof let us abbreviate $\rho=\rho_{\vY}$. 
We then calculate
\begin{align*}
&\bE \int_t f(t,\hvY(t))\,dt
= \int_{s,x} \varphi(s,x) 
	\bE \int_t
	f(t+s,\vY(t)+x)\,dt \,ds\,dx\\
&\qquad=
	\int_{s,x} \varphi(s,x)
	\int_{t,y}
	\ind\{t+s\in[0,1]\}
	f(t+s,y+x)
	\,\rho(dt\,dy)\,ds\,dx\\
&\qquad= \int_{s',x'}
	f(s',x')
	\bigg\{\int_{t,y}
	\varphi(s'-t,x'-y)\,\rho(dt\,dy)
	\bigg\}
	\,ds'\,dx'\\
&\qquad= \int_{t,y}
	f(t,y)
	\rho*\varphi(t,y)
	\,dt\,dy\,.
\end{align*}
This proves the claim.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 77 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\xi \in W$ be arbitrary. A path $(Y,Y') \in \scrd_X^{2 \alpha}([0,T_0],W)$ for some $T_0 \in (0,T]$ is called a \emph{local mild solution} to the RPDE \eqref{RPDE} with $Y_0 = \xi$ if $Y' = f(Y)$ and
\begin{align}
Y_t = S_t \xi + \int_0^t S_{t-s} f_0(s,Y_s) ds + \int_0^t S_{t-s} f(s,Y_s) d\mathbf{X}_s, \quad t \in [0,T_0].
\end{align}
If we can choose $T_0 = T$, then we also call $(Y,Y')$ a \emph{(global) mild solution} to the RPDE \eqref{RPDE} with $Y_0 = \xi$.

[Lem coverdgff of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] There exist constants $c_{\rm D},\widehat{c}>0$ such that, for all $u \geq 0$, $n \geq 1$ and ${\rm V} \subseteq {\rm D}_n$, 
\begin{equation}
	\mathbb{P}\Big( \min_{x \in {\rm V}} h_n(x) \leq -m_n+u\Big) \leq c_{\rm D} {\rm e}^{\widehat{c} u}\sqrt{\frac{|{\rm V}|}{|{\rm D}_n|}}.
\end{equation}

[Lemma 8 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_4>0$, which depends on the following values:

\begin{equation*}
\delta,\quad T, \quad \|v_0\|_{L^2(\Omega)},\quad \int_0^T \|\tilde{z}'(t)\|_{L^2(\Omega)}dt, \quad \int_0^T \|\tilde{g}(t)\|_{L^2(\Omega)}^2dt,
\end{equation*}

such that the following boundedness estimate holds for all $\nu \in (0,1)$: 

\begin{equation*}
\max_{0 \le t \le T} \|(S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z},\tilde{g}))(t)\|_{L^2(\Omega)}^2
+\int_0^T \Phi_\nu ((S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z},\tilde{g}))(t))dt \le C_4.
\end{equation*}

