[Prop convm of arXiv:2412.06480, 'A SIR epidemic model on a refining spatial grid \\ II-Central limit theorem'] For any $ \gamma> 3/2$, the  Gaussian martingale $ \mathscr{M}_{\varepsilon}\Longrightarrow \mathscr{M} := \big(\mathscr{M}^S, \mathscr{M}^I,\mathscr{M}^R\big)^{\mathtt{T}}$ in $C\big([0,T]; (\mathrm{H}^{-\gamma})^3\big)$ as $\varepsilon \to 0$, where for all $ \varphi \in \mathrm{H}^{\gamma}$
	\begin{eqnarray}
	\langle\, \mathscr{M}^S(t),\varphi \,\rangle \! \! &=&\! \! \! -\int_0^t \int_{\mathbb{T}^1} \varphi(x) \sqrt{\dfrac{\beta(x)\mathbf{s}(r,x)\mathbf{i}(r,x)}{\mathbf{a}(r,x)}}\; \dot{W}_1 (dr,dx)  - \sqrt{2\mu_S}\int_0^t\int_{\mathbb{T}^1} \varphi^{\prime}(x)\sqrt{\mathbf{s}(r,x)}\; \dot{W}_2(dr,dx), \nonumber 
	\end{eqnarray} 
	\abovedisplayskip = 0.2cm
	\begin{eqnarray}
	\langle\, \mathscr{M}^I(t),\varphi \,\rangle&=&\int_0^t\int_{\mathbb{T}^1}\varphi(x) \sqrt{\dfrac{\beta(x)\mathbf{s}(r,x)\mathbf{i}(r,x)}{\mathbf{a}(r,x)}}\; \dot{W}_1 (dr,dx) +\int_0^t\int_{\mathbb{T}^1}\varphi(x)\sqrt{\alpha(x)\mathbf{i}(r,x)}\dot{W}_3(dr,dx) \nonumber \\
	&&-\sqrt{2\mu_I}\int_0^t \int_{\mathbb{T}^1}\varphi^{\prime}(x) \sqrt{\mathbf{i}(r,x)}\; \dot{W}_4(dr,dx), \nonumber 
	\end{eqnarray} 
	\abovedisplayskip = 0.1cm 
	\begin{eqnarray}
	\langle\, \mathscr{M}^R(t),\varphi \,\rangle&=& -\int_0^t\int_{\mathbb{T}^1}\varphi(x)\sqrt{\alpha(x)\mathbf{i}(r,x)}\dot{W}_3 (dr,dx)  -\sqrt{2\mu_R}\int_0^t\int_{\mathbb{T}^1}\varphi^{\prime}(x)\sqrt{\mathbf{r}(r,x)}\; \dot{W}_5(dr,dx), \nonumber 
	\end{eqnarray} 
	and  $\dot{W_1}$, $\dot{W_2}$, $\dot{W_3}$, $\dot{W_4}$ and $\dot{W_5}$  are standard space-time white noises which are mutually independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eqn : Intro/DefDLength of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Given a subset $A$ of $\mathbb{R}^d$, a pseudometric $D$ on $A$ and a continuous path $\gamma : \intervalleff0T \rightarrow A$ for the usual topology, we define the $D$-length of $\gamma$ as
    \begin{equation}

        D(\gamma) \coloneqq \sup_{0=t_0 <\dots < t_r = T} \sum_{i=0}^{r-1} D\p{ \gamma(t_i), \gamma(t_{i+1})}.
    \end{equation}
    In the special case where $D$ is the metric induced by $\norme[1]\cdot$, we will denote by $\norme[1]\gamma$ the $D$-length of $\gamma$. We say that $\gamma$ is a $D$-\emph{geodesic} if it is Lipschitz for $\norme[1]\cdot$, and
    \begin{equation}
        D(\gamma) = D\mathopen{}\mathclose\bgroup\originalleft( \gamma(0), \gamma(T) \aftergroup\egroup\originalright).     
    \end{equation}
    For all $t\in\intervalleoo0T$ such that the following limit exists, we define the \emph{metric derivative} of $\gamma$ at $t$, with respect to $D$ as
    \begin{equation}

        \MD{\gamma}(t) \coloneqq \lim_{h\to 0} \frac{1}{\module h}D\mathopen{}\mathclose\bgroup\originalleft(  \gamma(t) , \gamma(t+h) \aftergroup\egroup\originalright).
    \end{equation}

[Proposition 22 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] For any $\lambda>0$, define
\begin{equation}
  \varphi_\lambda(z):=
  \left(
    \lambda+\frac{k a_p}{a_dk_c}z^{k_c}
  \right)^{-1/k},
  \qquad z\geq0,
\end{equation}
and
\begin{equation}
  \Phi_{\lambda}(s):=\int_0^s\varphi_\lambda(z)\ dz.
\end{equation}
Then $\Phi_{\lambda}$ solves \eqref{eq:stationary-equation} on $(0,\infty)$.

