[Theorem 5 of arXiv:2608.22595, 'Sparse Additive Off-Policy Evaluation for Reinforcement Learning with Potentially Limited '] Assume the conditions in Theorem  \ref{main1} are satisfied. With probability at least $1- \exp\{-c\log(nT \vee d)\}$, 
    we have
\begin{equation}
        \sup_{x\in \mathcal{X}^d }|\widehat{V}^{\pi}(x)-V^{\pi}(x)|\lesssim d_0L\frac{\log(nT \vee d)}{\sqrt{nT}}.
\end{equation}
If the density of distribution $\mathbb{G}$ is upper bounded from infinity, then for a deterministic policy $\pi$, we have 
\begin{equation}
        |\mathbb{E}_{x\sim \mathbb{G}}\widehat{V}^{\pi}(x)-\mathbb{E}_{x\sim \mathbb{G}}V^{\pi}(x)|\lesssim d_0\sqrt{L}\frac{\log(nT \vee d)}{\sqrt{nT}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main of arXiv:2509.26254, '$K$-Branching Random Walk with Noisy Selection: \\ \Large Large Population Limits and Phas'] For all $t\geq 0$, we define the sequence of point measures $(M^t_N)_{N\in\mathbb{N}}$ by
\begin{equation}
M^t_N := \sum_{i=1}^{N^\gamma} \delta_{Z^t_{N,i}/c_N}.
\end{equation}
Assume that 
\begin{enumerate}
\item[(i):] the sequence of initial configurations  $(M^0_N)_{N \in \mathbb{N}}$ admits a limiting log-profile $g^0 \in {\cal C}$,
\item[(ii):] the function $h$ is concave on its support, that is $\rho\geq 1$.
\end{enumerate}
Then, for all $t\in\mathbb{N}$, $(M^t_N)_{N \in \mathbb{N}}$ admits a limiting log-profile $g^t \in \mathcal{C}$. Further, $(g^t)$ satisfies a recursive equation in terms of the following discrete ``free boundary'' problem,
\begin{eqnarray}
\forall x\in\mathbb{R},  \ g^{t+1}(x) \ = \ s_{\sigma_t}\circ r(g^t)(x),  
\end{eqnarray}
where $\sigma^t$ is defined implicitly through the relation 
\begin{equation}
\sigma^t := \inf\left\{ \sigma :\: \sup_{z \in \mathbb{R}}s_\sigma(r(g))(z) \leq \gamma\right\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

