[Lemma 16 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] For every $n\geq2$,
\begin{equation}
 \ell_n\geq\frac{\pi}{n+1/2}.
\end{equation}
Consequently,
\begin{equation}
 \Delta_n\geq
 \sinh^2\left(\frac{\pi}{2n+1}\right).
\end{equation}

[Theorem of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The pmf of multivariate IGCP is given by
\begin{equation*}
\hat{p}_{\bar{\mathcal{M}}}(\bar{n},t)=\sum_{\substack{\Omega(k_i,n_i)\\i=1,2,\dots,q}}\Big(\prod_{i=1}^{q}\prod_{j_i=1}^{k_i}\frac{(\lambda_{ij_i})^{n_{ij_i}}}{n_{ij_i}!}\Big)\sum_{m=0}^{\infty}m^{\sum_{i=1}^{q}\sum_{j_i=1}^{k_i}n_{ij_i}}\sum_{\Omega(k_0,m)}\prod_{j_0=1}^{k_0}\frac{(\mu_{j_0}e^{-j_0\Lambda}t)^{x_{j_0}}}{x_{j_0}!}e^{-\mu_{j_0}t},\, \bar{n}\ge\bar{0},
\end{equation*}
where $\Omega(k_i,n_i)=\{(n_{i1},n_{i2},\dots,n_{ik_i}):\sum_{j_i=1}^{k_i}j_in_{ij_i}=n_i,\,n_{ij_i}\in\mathbb{N}_0\}$.

[Lemma 63 of arXiv:2607.18201, 'Finding Adam in noisy trees'] For any $\delta'>0$ and  $r\geq 1$, we have
    \begin{align*}
        \Prob{\max_{v: v \in D_{\cT_n}(\alpha+\delta)} Z_v> \delta' \log n}\leq \frac{1}{n^r}.
    \end{align*}

