body:
[Theorem Beta limits of arXiv:2512.05896, 'T\'oth's buses and the ``detachment process'''] \begin{enumerate} Let $m_k,M_k$ and $R_k$ be as in the previous paragraph.
\item   For $n\ge 1$ fixed, $$\lim_k \mathsf{Law}(m_k/k)=\mathsf{Beta}(1,n);\ \lim_k \mathsf{Law}(M_k/k)=\mathsf{Beta}(n,1),$$that is,  
$$\lim_{k\to\infty} P\left(\frac{m_k}{k}\le x\right)=1-(1-x)^n;\quad  \lim_{k\to\infty} P\left(\frac{M_k}{k}\le x\right)=x^n$$ for $x\in [0,1].$

\item The expectations and standard deviations satisfy 
\begin{align*}
\lim_k E(m_k/k)&=\frac{1}{n+1};\ \  \lim_k E(M_k/k)=\frac{n}{n+1};\ \ \lim_k E(R_k/k)=\frac{n-1}{n+1};\\
\lim_k\sigma(M_k/k)&=\lim_k\sigma(m_k/k)=\frac{1}{n+1}\sqrt{\frac{n}{n+2}}.
\end{align*}
\end{enumerate}

