[Definition 9 of arXiv:2608.29086, '2608.29086'] [$HOLE(\psi)$]
Given $M \subset M_0$ and $\psi \in TRAJ(M)$. $HOLE(\psi)$ denotes the collection of all holes within $|\psi |_0$, i.e.,
\begin{equation*}
HOLE(\psi):=\{ r \in REG(M_0)\ |\ \text{$r$ is a hole within $|\psi|_0$} \} \quad \subset REG(M_0).
\end{equation*}
$HOLE(\psi)$ may contain not only regions on $M$ but also regions on $M_0$.

[Corollary 13 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Suppose that $X=(X_t)_{t\in[0,T]}$ satisfies Assumption \ref{a1} (i). Let $0\leq \alpha < d$ and $0\leq \beta \leq 1$ be such that \eqref{eq:key-restriction} holds and let $n$ be an even integer. Then for any $0 \leq u < v\leq T$, any $x,y \in \rd$ and any $\tau\in[u,v]$ we have
		\begin{equation}
			\E \lvert L^{\alpha,X}(x+X_\tau,[u,v])\rvert^n \leq c_9^n n^{H\left(\theta+d-\alpha\right)n}(v-u)^{\left(1-H\left(d-\alpha\right)\right)n}[\log(e+(v-u))]^{2nd \zeta}
		\end{equation}
		and
		\begin{multline}
			\E [L^{\alpha,X}(x+h+X_\tau,[u,v])-L^{\alpha,X}(x+X_\tau,[u,v])]^{n}  \\
			\leq \|h\|^{\beta n}   c_9^n n^{H\left(\theta+d-\alpha+\beta\right)n}(v-u)^{\left(1-H\left(d-\alpha+\beta\right)\right)n}[\log(e+(v-u))]^{2nd\zeta},
		\end{multline}
		where $c_9$ and $\zeta$ are as in Proposition \ref{prop:moment-bounds}.

[Proposition prop:contour_random_narrow_exc_pos of arXiv:2512.17747, 'On exponentially height-penalized random trees'] For any sequence of events $(A_n)_{n \geq 1}$, and any $\epsilon>0$, we can choose $\delta=\delta(\epsilon)>0$ such that 
    \begin{align*}
\lim_{n\to \infty} \frac{1}{(\mu^2n)^{1/3}}\log\left(\frac{\Prob{\mathbf{T}_n \in A_n,\left|\frac{h(\mathbf{T}_n)}{(n/\mu)^{1/3}}-(2\pi^2)^{1/3}\right|<\delta}}{\CProb{\mathbb T_n \in A_n}{\left|\frac{h(\mathbb T_n)}{(n/\mu)^{1/3}}-(2\pi^2)^{1/3}\right|<\delta}} \right)< \epsilon,
    \end{align*}
    where $\mathbf{T}_n$ is a $\mu$-height-biased tree of size $n$ with $\mu\gg \frac{(\log n)^{3/2}}{\sqrt{n}}$, and recall $\mathbb T_n$ is a uniformly random plane tree.

