[Definition 115 (Regular ingoing $\gfour$-null vectorfield) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\olduLunit$ be the vectorfield defined in \eqref{E:OLDULUNIT}. Then we define $^{(\textnormal{reg})}\newuL$ to be the vectorfield:
\begin{align} 
	^{(\textnormal{reg})}\newuL \eqdef \frac{1}{2} \upmu  \olduLunit = \frac{1}{2}\upmu \Lunit + \muX.
\end{align}

[Definition 15 of arXiv:2605.16072, 'Stochastic integration \\with respect to a L\'evy basis'] \hfill 
	\begin{enumerate}
		\item[{\rm (a)}] A real-valued predictable step process $\Xi \colon \Omega \times [0,T]\times \O\to \R$ is said to be of the form 
		\begin{align} 
			\Xi(\omega, t,r)=\sum_{k=0}^{n-1} \xi_k(\omega)  \mathbb{1}_{ (t_k,t_{k+1}]}(t)\mathbb{1}_{A_k}(r),
		\end{align}
		where $0=t_0<\cdots < t_{n}=T$, $\xi_k$ is an $\F_{t_k}$-measurable real-valued random variable, and 
		$A_k\in \Borel_b(\O)$ for $k=0,\dots, n-1$. The space of all real-valued predictable step processes is denoted by $\mathcal{S}_{\rm prd}$. 
		\item[{\rm (b)}] The subspace of all real-valued predictable step processes $\Gamma$ satisfying 
		\begin{align*}
		\esssup_{\omega\in\Omega}	\sup_{(t,r)\in  [0,T]\times \O}\abs{\Gamma(\omega,t,r)}\leq 1
		\end{align*}
		is denoted by  $\mathcal{S}_{{\rm prd}}^{1}$. 
	\end{enumerate}

[Lemma 10 (Uniform \(L^2\) bound for Gaussian pencil traces) of arXiv:2608.04824, 'Strong Convergence for a General Class of Random Matrix Models'] For every fixed self-adjoint Gaussian pencil \eqref{eq:Gaussian-pencil} and
every fixed \(r\geq1\),
\[
 \sup_{n\geq1}
 \E\left|\trn_{qn}G_n^{2r}\right|^2<\infty.
\]
Consequently,
\begin{equation}
 \E\trn_{qn}G_n^{2r}
 \longrightarrow
 (\trn_q\otimes\tau)(G_\infty^{2r}).
\end{equation}

[Lemma l2 of arXiv:2603.05467, 'Thresholds for colouring the random Borsuk graph'] For all $ \lambda>\lambda_c $ and $ \varepsilon,\delta>0 $ there exist $ k=k(\lambda,\varepsilon,\delta) $ such that for all large enough $ \ell\geq \ell_0(\lambda,\varepsilon,\delta,k) $
	\begin{equation*}
		\mathbb{P}_{\lambda,\delta,B(\underline{0},\ell-2k-2)^c}(|A_{\ell,k,B(\underline{0},k)}|> 0)>1-\varepsilon.
	\end{equation*}

