[Defn of arXiv:2604.10446, 'Least singular values of shifted sparse random combinatorial matrices'] For a random vector $X\in \mathbb{R}^n$ and $\varepsilon\ge 0$, the L\'evy concentration of $X$ of width $\varepsilon$ is 
    \begin{equation*}
        \mathcal{L}(X,\varepsilon):=\sup_{x\in \mathbb{R}^n} \mathbb{P}(\|X-x\|_2<\varepsilon).
    \end{equation*}

[Cor final-coupling-subtrees of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] In the above setting, if one sets for $n\geq1$,
	\begin{align}
	\mathcal{T}'_n={\mathfrak{P}^{-1}}\bigl({\boldsymbol{\sigma}}_n\cdot\mathrm{T}_n,({\boldsymbol{\sigma}}_n)_*\,{\boldsymbol{S}}_n\bigr),
	\end{align}
	then the sequence $(\mathcal{T}'_n)_{n\geq1}$ is a coupling of the distributions $(\Sub{{\boldsymbol{\uptheta}}}{n})_{n\geq 1}$.

[Proposition 20 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] The following statements hold.

  \smallskip
  \noindent
  \textup{(i) (\textsf{Polymer endpoint moments})}  
  Recall the definition of $  Q_{x,R}^{\al,\be,\eps}$
  from  \eqref{QxR_abe}. 
  For every compact
  $K\subset\R$ and every $p\in[1,\infty)$,
  we have 

  \noi
  \begin{align}
    \sup_{\substack{x\in K,\ 0<\eps<1\\1\leq R\leq\infty}}
    \bigg\|
      \int_{\R_+^n}\ga_n
      Q_{x,R}^{\al,\be,\eps}(d\ga)
    \bigg\|_{L^p(\Omega)}<\infty.
  \end{align}
  In particular, with
  \begin{align}
    \cU_{x}^{\eps}
    =\int_{\R_+^n}
     \big[  DH_{x}^{\al,\eps}(\ga) \big]
      Q_{x}^{\al,\be,\eps}(d\ga),
  \end{align}
  one has
  \[
    \sup_{x\in K,\,0<\eps<1}
    \|\cU_x^\eps\|_{L^2(\Omega;\fH)}<\infty.
  \]

  \smallskip
  \noindent
  \textup{(ii) (\textsf{Truncated Malliavin derivative})}  For $R<\infty$,
  $\lambda\in[0,\be)$, and $\eps>0$,
  $\log Z_{x,R}^{\al,\be,\eps}(\lambda)\in\DD^{1,2}$ and
  \begin{align}
    D\log Z_{x,R}^{\al,\be,\eps}(\lambda)
    =\frac{\be}{Z_{x,R}^{\al,\be,\eps}(\lambda)}
    \be^{-n}\int_{\ga_n<R}
      e^{\lambda\ga_n+\be H_{x}^{\al,\eps}(\ga)}
     \big[ DH_{x}^{\al,\eps}(\ga) \big]\,\mu_\be(d\ga).
  \end{align}

  \smallskip
  \noindent
  \textup{(iii) (\textsf{Full Malliavin derivative})}  For every fixed
  $\eps>0$, we have
  \begin{align}
    \log Z_{x}^{\al,\be,\eps}\in\DD^{1,2}
    \quad{\rm and}
    \quad
    D\log Z_{x}^{\al,\be,\eps}
    =\be\cU_x^\eps.
  \end{align}
  Moreover,
  $
    D\log Z_{x,R}^{\al,\be,\eps}(0)
    \longrightarrow \be\cU_x^\eps
    \quad\text{in }L^2(\Omega;\fH)
$
  as $R\to\infty$.

