[Lemma 24 of arXiv:2604.24684, 'Waning Immunity Fails to Restore a Positive Epidemic Threshold on Power--Law Networks'] Fix any $\tilde{\varepsilon}\in \left(0,\frac{1}{4\tau}\right)$, and set
$
\bar\varepsilon=\frac{\tilde{\varepsilon}}{4.4\tau}
$.
Let $G=G(n,\tau)$ be a power-law random graph on $n$ vertices with exponent $\tau>2$, and let
$
\bm d=(d_1,\dots,d_n)
$
denote its degree sequence. Suppose that $v$ is a vertex of degree at least $n^{2\tilde{\varepsilon}}$. Let $A_v$ denote the event that $v$ has at least $\lceil n^{\tilde{\varepsilon}}\rceil$ distinct neighbors whose degrees all lie in the interval $(n^{\bar\varepsilon},n^{3\bar\varepsilon})$. Then, for all sufficiently large $n$,
\begin{equation}
\mathbb{P}(A_v\mid \bm d)\ge 1-\exp(-n^{\bar\varepsilon(\tau-2)}), \qquad \text{on the event $D_{\bar\varepsilon}$ defined in \eqref{eq_D}. }
\end{equation}

[Lem 19 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] If $S,S'\in \cS$ are $\vartheta$-regular for some $\vartheta>0$ such that for all $\p \in [k]_0$,  
        \begin{equation} 
            \lambda_{\mathrm{left}}^\p
             +\lambda_{\mathrm{right}}^\p< (1-\vartheta)\frac{n_\p^{(1)}}{N},    
        \end{equation} 
             then \[|E(G,G')|\leq \sum_{\p=0}^{k-1}\left[|E^\p_{\for}(G,G')|+|E^\p_{\back}(G,G')|\right]\]

