[Theorem thm:quadratic of arXiv:2606.08325, 'Digit Mixing under Polynomial Maps'] There is an absolute constant \(c_2>0\) with the following property.  If
			\begin{equation}
				\sum_{s\ge1}s\exp(-c_2R_2(s))<\infty,
			\end{equation}
			then \(X^2\) is almost surely absolutely normal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:apriori of arXiv:2411.08018, 'Last passage percolation in hierarchical environments'] The following is true almost surely.
    For all $\ell\in\llbracket1,{M}\rrbracket$, every rectangle $R^{(\ell)}\in\mathscr{R}^{(\ell)}$ enjoys the following two properties:
    \begin{enumerate}[label=(\roman*)]
        \item
        \emph{(Large area).}
        \[
            \bigl|R^{(\ell)}\bigr| \ge {\lambda}^2\frac{n^2}{2^{2\ell{\zeta}}}.
        \]
        \item
        \emph{(Controlled slope).}
        There exists $R^{(\ell-1)} \in \mathscr{R}^{(\ell-1)}$ such that $R^{(\ell)} \subset R^{(\ell-1)}$ and 
        \begin{equation*}
            \frac{1}{1+2\frac{{\rho}}{{\lambda}^2}}
            \le \frac{\mathsf{Slope}(R^{(\ell)})}{\mathsf{Slope}(R^{(\ell-1)})}
            \le 1+2\frac{{\rho}}{{\lambda}^2}.
        \end{equation*}

        Thus, iterating yields the bounds
        \begin{align}
            \left(1+2\frac{{\rho}}{{\lambda}^2}\right)^{-\ell} \le 
            \mathsf{Slope}\bigl(R^{(\ell)}\bigr)
            \le \left(1+2\frac{{\rho}}{{\lambda}^2}\right)^{\ell}.
        \end{align}
        Note that since $\ell\le {M} \le C \frac{\log n}{\log\log n}$ and $\frac{{\rho}}{{\lambda}^2}=\left(\frac{\log\log n}{\log n}\right)^{1/2}$,
        these last bounds are roughly of the form
        $e^{\pm C\left(\frac{\log n}{\log\log n}\right)^{1/2}}$
        and hence are sub-polynomial in $n$ which will be crucial in our later applications.
    \end{enumerate}

[Definition def:BD-chain of arXiv:2603.00705, '$L^2$-cutoff for the averaging process \\ on random regular graphs'] Fix $d\ge 3$.
	Let $R_t$ denote the transition kernel of the  continuous-time biased random walk on $\mathbb{N}_0:=\{0,1,2,\ldots\}$ with transition rates $p^R(i)$ (resp.\ $q^R(i)$) of jumping from $i$ to $i+1$ (resp.\ $i-1$) given by
	\begin{equation}
		p^R(i):= \begin{dcases}
			d/2 &\text{if}\ i=0\\
			d-1 &\text{if}\ i\ge 1
		\end{dcases}\ ,\qquad q^R(i):= \begin{dcases}
		0 &\text{if}\ i=0\\
			1/2 &\text{if}\ i=1\\
			1 &\text{if}\ i\ge2\ .
		\end{dcases}
	\end{equation}
	We refer to $R_t$ as the (continuous-time) \emph{slow-bond BD 	chain}.

[Lem 5 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] Suppose that assumptions $({\bf A1})$--$({\bf A3})$ hold. Furthermore, assume that either the time horizon $T$ or the Lipschitz constant $K$ is sufficiently small so that
\begin{eqnarray}
(66+ 864K)K e \max(1,T^2) < 1.
\end{eqnarray}
Then there exists a positive constant $C$, independent of $\varepsilon$, such that
\begin{eqnarray*}
\E\left[ \sup_{ 0\leq s \leq T}e^{\beta s}|X^{t,x,\varepsilon}(s) |^2 + \sup_{ 0\leq s\leq T}e^{\beta s} |Y^{t,x,\varepsilon}(s) |^2  + \int_{ 0}^Te^{\beta s} |Z^{t,x,\varepsilon}(s) |^2ds\right]  \leq C \left(1+ |x|^2\right).   
\end{eqnarray*}

