[Theorem T theorem of arXiv:2509.04349, 'Precise asymptotics for the norm of large random rectangular Toeplitz matrices'] Let $\mathbf{T}_{p\times n}$ be a sequence of non-symmetric rectangular random Toeplitz matrices defined in (equation definition of T of the paper) and satisfying assumptions (equation Lyapunov of the paper) and (equation new asymptotic regime of the paper). Then, as $n \to \infty$, the spectral norm satisfies
\begin{equation}

    \frac{\|\mathbf{T}_{p\times n}\|}{\sqrt{p\log n}} - \|\Sin_{1,n/p}\|_{2\rightarrow 2} \overset{P}{\longrightarrow} 0.
\end{equation}
If, in addition, 
\begin{equation}
    \limsup_{n\to\infty} n/p <\infty,
\end{equation}
then the convergence in probability in (equation main convergence of the paper) strengthens to convergence in $L^\gamma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 32 (Boundedness and continuity of $\delta\Pi^-$, Steps 4.a) and 4.b)) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Assume that the hypothesis of Proposition~\ref{prop_2} is satisfied, and that additionally 
for all populated $\beta'\prec\beta$ and all~$\n$ 

\begin{equation}
\begin{aligned}
\EE^{\frac{1}{q}} \left|
\partial^\n \delta \Pi_{x \beta'}(y)
\right|^{ q} \lesssim 
\ve^{\alpha-|\n|}
( \ve + |x-y|)^{| \beta' |- \alpha}\w \,.
\end{aligned}
\end{equation}

Then for every $\n$ and $l\geq0$ 

\begin{equation}
\begin{aligned}
\EE^{\frac{1}{q}} \left| 
\partial^\n \delta\Pi^-_{x\beta}(y) 
\right|^{ q} 
\lesssim 
\ve^{\alpha-2-|\n|}
( \ve+ | x-y|)^{| \beta| - \alpha} \w \, ,
\end{aligned}
\end{equation}

and

\begin{equation}
\begin{aligned}
\EE^{\frac{1}{q}} \left|
(\mathrm{id}-T_z^{\leq l}) \partial^\n \delta\Pi_{x \beta}^{-}(y) 
\right|^{ q} 
\lesssim 
\ve^{\alpha-2-|\n|-1-l}
|y-z|^{1+l}
( \ve+ | x-y| + |x-z|)^{| \beta| - \alpha} \w \,.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 1 of arXiv:2608.13374, 'Nearly Sharp Comparison Results for sliced and max-sliced Wasserstein distances'] Let $d \geq 2$. There exist constants $C_d, \varrho_d > 0$ such that, for any $\varrho \in (0, \varrho_d]$, there exist $\mu, \nu \in \cP(B_1)$ satisfying
	\begin{align*}
		W_1(\mu, \nu) & \geq \varrho\\
		\MSW_{1, 1}(\mu, \nu) & \leq C_d \varrho^{1 + d/2}\,.
	\end{align*}
	In particular, for $p = 1$, \eqref{msw_comp} can only hold with $\beta \leq \tfrac{2}{d+2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def-weak derivative of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Suppose that $u:\mathbb{R}^d \to  \mathbb{R}$ is locally Lebesgue essentially bounded  and $b:\mathbb{R}^d \to  \mathbb{R}^d$ is locally Lebesgue integrable  such that $\operatorname{div} b :\mathbb{R}^d \to  \mathbb{R}$ is locally Lebesgue integrable. \\
We define a  distribution $b \cdot  D u \in {
\mathscr D}^\prime(\mathbb{R}^d)$ by the following formula
\begin{equation}
\langle b\cdot  D u, \rho \rangle:=-\langle u  b  ,  D \rho \rangle   -\langle   u \,\operatorname{div} b, \rho \rangle, \;\; \rho \in {
\mathscr D}(\mathbb{R}^d),
\end{equation}
where ${
\mathscr D}^\prime(\mathbb{R}^d)$ is the space of distributions.

[Lemma plf of arXiv:2411.03634, '\bf{Local limit theorems for random walks on a large discrete torus }'] For  $\delta>0$ sufficiently small, there exists a constant $C_{\alpha}>0$  and $\rho<1$ such that  
		\begin{equation}
			1-\hat{p}_1(k)
			=C_{\alpha}\big(W\|k/L\|_2\big)^{\alpha}+ O\Big(\big(W\|k/L\|_2\big)^{2}\Big),
			\quad \forall\, \|k\|_2 \leq \delta \frac{L}{W},
		\end{equation}
		and 
		\begin{equation}
			\left|\hat{p}_1(k)\right|\leq \rho, \quad \forall\,\|k\|_2>\delta \frac{L}{W}.
		\end{equation}

