[Lemma lem:saturated of arXiv:2607.22220, 'Pathwise uniqueness for degenerate stochastic differential equations with H\"{o}lder conti'] Let $\zeta_i(s)$ be a non-negative progressively measurable process satisfying
\begin{equation}
0\le\zeta_i(s)\le\frac{C_R}{x_i(s)}.
\end{equation}
Then
\begin{equation}
\mathbb E\left[
\left(1-\exp\left\{-\int_r^{r+h}\zeta_i(s)\,\mathrm d s\right\}\right)^2
\Bigm|\mathcal F_r
\right]
\le C_R\left(1\wedge\frac{h}{x_i(r)}\right).
\end{equation}
Consequently,
\begin{equation}
\mathbb E\int_0^{t-h}
\rho_r^2p(x_{i+1}(r))
\left(1-\exp\left\{-\int_r^{r+h}\zeta_i(s)\,\mathrm d s\right\}\right)^2\,\mathrm d r
\le C_{T,R}h^{1/2}.
\end{equation}

[Lemma 18 of arXiv:2512.19517, 'Spiking and Resetting'] Let $I^\varepsilon$ be defined by 
\begin{equation}

\begin{split}
I^\varepsilon := \int_0^{T^\varepsilon_*}  \, r \,  (-\dot{\mu}_r^\varepsilon)  \, dr  =  \varepsilon  \int_0^{y_*^\varepsilon} \frac{h(x) }{\varepsilon f(x) + xh(x)} \, U^\varepsilon (x) \, e^{-V^\varepsilon (x)} \, dx  \ .
\end{split}
\end{equation}
There exists a constant $C>0$ such that for $\varepsilon>0$ in a neighborood of $0$, 
\begin{equation}

\begin{split}
I^\varepsilon \ge C \varepsilon  \ .
\end{split}
\end{equation}

