[Lemma ch6-l1 of arXiv:2410.23995, 'Sample path properties of parabolic SPDEs with non constant coefficients'] Suppose that assumptions $({\bf \bar{H}}_\Gamma)(1)$-$(2)$ hold. Then: 
\begin{description}
\item{(a)} For any $\delta\in\, ]0,1[$, there is a constant $C_\delta < \infty$ such that, for  $0<t\le t+h < \infty$ and $x \in \mathbb{R}^{k}$, 
\begin{equation}

\int_0^t ds\ (t-s)^{\delta-1} \int_D dy\ |\Gamma(t+h,x;s,y) - \Gamma(t,x;s,y)| \le C_\delta\, h^\delta.
\end{equation}
 \item{(b)} There is $C < \infty$ such that, for any $\alpha \in\, ]0,1[$, there is $c_\alpha < \infty$ such that $\lim_{\alpha \uparrow 1} c_\alpha = 1$ and for any $0<t\leq t+ h < \infty$ and $x \in \mathbb{R}^{k}$,
\begin{equation}

	  \int_0^t ds \int_D dy\ |\Gamma(t+h,x;s,y) - \Gamma(t,x;s,y)| \le C\, c_\alpha\, \frac{t^{1-\alpha}}{1-\alpha}\, h^\alpha.
\end{equation}
\end{description}

