[Proposition prop:esolisATvol of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] Let $\mathcal{X}$ be a non degenerate admissible scalar GRF and let $U\subset M$ be an open set. If we endow $M$ with the AT metric induced by $\mathcal{X}$, we obtain
  \begin{equation}
    \mathbb{E}\mathbb{S}\left\{\mathcal{X};U\right\}=\frac{2}{s_m}\int_U \mathrm{d} M
  \end{equation}
  where $\mathrm{d} M$ denotes the integration with respect to the Riemannian volume form, i.e., $\int_U \mathrm{d} M$ is the Riemannian volume of $U$, and where recall that $s_m$ is the volume of the Euclidean unit sphere $S^m\subset\mathbb{R}^{m+1}$.

[Lemma 18 of arXiv:2511.09280, 'Random Walk conditioned to stay above a non-flat floor: curvature effects'] Let \(n\geq 1\), \(T=1/\beta>0\). Let \(f_1,\dots, f_{n-1}:(0,+\infty)\to [0,+\infty)\) be measurable functions such that
    \begin{gather*}
        E\bigl( f_1(S_1)\cdots f_{n-1}(S_{n-1})\bgiven S_0=S_n=0, S\geq 0\bigr)<\infty,
        \\
        E\bigl( f_1(\sqrt{\beta}\BrownExc_1)\cdots f_{n-1}(\sqrt{\beta}\BrownExc_{n-1})\bigr)<\infty.
    \end{gather*}
    Let \(\mu\) be the probability measure on \(\R^{\{0,\dots, n\}}\) given by
    \begin{equation*}
        d\mu(x_0,\dots,x_n)
        \propto
        \delta(x_0)\delta(x_n)\Bigl(\prod_{i=1}^{n-1}f_i(x_i) \mathds{1}_{x_i>0} \, dx_i\Bigr) e^{-T\sum_{i=1}^n(x_i-x_{i-1})^2},
    \end{equation*}
    and \(\nu\) be the probability measure on \(\R^{\{0,\dots, n\}}\) given by
    \begin{equation*}
        d\nu(y_0,\dots,y_n)
        \propto
        \delta(y_0)\delta(y_n)g_{1,\dots,n-1}^{(n)}\bigl(\sqrt{T}y_1,\dots, \sqrt{T}y_{n-1}\bigr) \Bigl(\prod_{i=1}^{n-1}f_i(y_i) \, dy_i\Bigr).
    \end{equation*}
    Then,
    \begin{equation*}
        \mu \preccurlyeq \nu.
    \end{equation*}

