body:
[Proposition Prop:skorokhod of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] For $i = 1, \ldots, d$, we have
    \begin{equation}
        \delta^i(\sigW[T]) = W_T^i \sigW[T] - {\bf \Psi}^{{\color{NavyBlue}{\mathbf{0}}}}_{{\color{NavyBlue}{\mathbf{i}}}}(\sigW[T]).
    \end{equation}
    Moreover, if $\bm{\ell} \in \TA[d+1]$, then
    \begin{equation}
        \delta^i\left( \bracketsigW[T]{\bm{\ell}} \right) = \bracketsigW[T]{\bm{\ell} \mathrel{\sqcup \mkern -3mu \sqcup} {\color{NavyBlue}{\mathbf{i}}} - {\bf \Psi}^{{\color{NavyBlue}{\mathbf{i}}}}_{{\color{NavyBlue}{\mathbf{0}}}}(\bm{\ell})}.
    \end{equation}

