[Theorem 151 of arXiv:2601.16377, '2601.16377'] If the discrete ensemble satisfies Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and its equilibrium measure has no saturations, then we have an asymptotic equality of distributions as $\N \rightarrow \infty$
\begin{equation}
 \boldsymbol{N}^{\circ} \stackrel{\textnormal{d}}{\sim} \textnormal{\textsf{\textbf{Gau\ss{}}}}_{\amsmathbb{Z}},
\end{equation}
where the convergence in the sense of Definition~\ref{Definition_asymptotic_equivalence} is uniform for fixed constants in the assumptions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RBM-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = L^2(\mathbb{R})$.  The seed functions $\psi_{t,a,n}$
and $\phi_{t,a,n}$ defined in
\S(sec:RBM-kernel-reform of the paper) satisfy the linear problem
(equation eq:dc-clean-linear-d1 of the paper)--(equation eq:dc-clean-linear-S3 of the paper)
and its adjoint
(equation eq:dc-clean-adjoint-d1 of the paper)--(equation eq:dc-clean-adjoint-S3 of the paper)
with $\partial_1 = \partial_t$, $\partial_2 = \partial_a$,
$S_3 = e^{\partial_n}$ and constant scalar edge weights
$(c_1, \lambda_1) = (1, -\tfrac{1}{2})$,
$(c_2, \lambda_2) = (1, -1)$.
Explicitly:
\begin{align}
\psi_{t,a,n+1}
&= \partial_a \psi_{t,a,n} + \psi_{t,a,n},
 \\
\partial_t \psi_{t,a,n}
&= \tfrac{1}{2}\partial_a^2 \psi_{t,a,n}
   + \partial_a \psi_{t,a,n}
   + \tfrac{1}{2}\psi_{t,a,n},

\end{align}
and
\begin{align}
\phi_{t,a,n}
&= -\partial_a \phi_{t,a,n+1} + \phi_{t,a,n+1},
 \\
\partial_t \phi_{t,a,n}
&= -\tfrac{1}{2}\partial_a^2 \phi_{t,a,n}
   + \partial_a \phi_{t,a,n}
   - \tfrac{1}{2}\phi_{t,a,n}.

\end{align}

[Lem rationalencodingOSp of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] For every $h \in \mathcal{P}_q$, there is a rational function of the form 
$\Psi_h:=\frac{f_h}{g_{qq_0}}$ with 
$f_h,g_{qq_0}\in\mathcal{P}_{\lfloor 6qq_0(1+\log qq_0)\rfloor}$
so that
\begin{alignat*}{2}
	&\mathbf{E}[\mathop{\textnormal{tr}} h(X^N)] &&= \Psi_h(\tfrac{1}{N}),\\
	&\mathbf{E}[\mathop{\textnormal{tr}} h(Y^N)] &&= \Psi_h(-\tfrac{1}{2N})
\end{alignat*}
for all $N\in\mathbb{N}$ such that $N>qq_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary esp:small:light:tails:del=0 of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Assume that $c$ satisfies (equation eq:ass:hessia:bounded of the paper) and that $\rho$ satisfies (equation eq:ass:light:tails of the paper). Then Sinkhorn's algorithm converges exponentially fast. Moreover, if $H(c)=h(c)$ then, for 
\begin{equation}
\varepsilon\leq \sqrt{2\tauH(c)^2\,(1+(L+2)\,[R^2\vee C^{-\nicefrac2\delta}])}
\end{equation}
the rate is
\begin{equation*}
1-\frac{\varepsilon^2}{\varepsilon^2+2\tauH(c)^2(1+(L+2)^2\,[R^2\vee C^{-\nicefrac2\delta}])}\,.
\end{equation*}
Otherwise, if $H(c)>h(c)$ (and set $\nicefrac{1}{0}=+\infty$) then for
\begin{equation}
\varepsilon\leq 1\wedge\frac{\delta_H}{(R^{\delta} C-1)_+}\wedge\biggl(\tau\delta_H+2\tauH(c)^2\,(1+(L+2)^2\,C^{-\nicefrac2\delta}(1+2\delta_H)^{\nicefrac2\delta}\biggr)^{\nicefrac{\delta}{2+2\delta}}
\end{equation}
we have rate of convergence 
\begin{equation*}
1-\frac{\varepsilon^{2+\nicefrac2\delta}}{\varepsilon^2+\tau\varepsilon\delta_H+2\tauH(c)^2\,(1+(L+2)^2\,C^{-\nicefrac2\delta}(\varepsilon+2\delta_H)^{\nicefrac2\delta})}\,.
\end{equation*}

