[Proposition 1 (Hoskins and Steinerberger \cite{Hoskins-Steinerberger2022}) of arXiv:2506.08910, 'Critical points of random polynomials and finite free cumulants'] Let $p_N$ be as in \eqref{eq:random polynomial definition} and assume the measure $\mu$ is supported on the real line, has mean $0$, variance $1$, and moments of all orders. If \begin{equation}
	\tilde{p}_{k,N}(x)=\mathcal{D}_{\sqrt{N}}\partial_{k|N}p_{N}\left(x+\frac{1}{N}\sum_{j=1}^{N}X_{j}\right),
\end{equation} then, for any fixed $k\in\N$\begin{equation}
	\lim\limits_{N\rightarrow\infty}\tilde{p}_{k,N}\left(x\right)=\He_{k}(x),
\end{equation} pointwise, almost surely, where $\He_{k}$ is the degree $k$ Hermite polynomial\begin{equation}
\He_k(x)=\sum_{j=0}^{\lfloor \frac{k}{2}\rfloor}\frac{k!(-1)^{j}}{j!(k-2j)!}\frac{x^{k-2j}}{2^{j}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 20 (\cite{MMRR26}, Theorem 2.4) of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X_1,d_1,\mu_1),\dots, (X_m,d_m,\mu_m), (Y,d,\nu)$ be Polish measure spaces. For $p \leq 1$ and $t=(t_1,\dots,t_m)$ with $t_i > 0$ and $\sum_{i=1}^mt_i=1$, the following are equivalent: under the above notations,
\begin{enumerate}
    \item[(i)] For any choice of non-empty sets $A_i \in \mathcal{A}_i$ and constants $\alpha_i > 0$, define the $m$-tuple of functions $\alpha = (\alpha_1\chi_{A_1},\dots, \alpha_m\chi_{A_m})$. One has the geometric inequality
    \begin{equation}
        \int_{Y} \square \alpha(x) \,d\nu(x) \geq \M_p^{(t)}\left(\alpha_1\mu_1(A_1),\dots, \alpha_m\mu_m(A_m)\right).
    \end{equation}
    \item[(ii)] For any choice of functions $f_i \in \mathcal{F}(\mathcal{A}_i)$, one has the functional inequality
    \begin{equation}
        \int_{Y}^{\star} \square f(x) \,d\nu(x) \geq \M_p^{(t)}\left(\int_{X_1} f_1(x) \,d\mu_1(x),\dots, \int_{X_m} f_m(x) \,d\mu_m(x)\right).
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lm:randomhypergraph of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Let $\bm H_n = (H_n^{(1)}, H_n^{(2)})$ be a sequence of random 2-hypermultiplexes, where both $H_n^{(1)}$ and $H_n^{(2)}$ are $r$-uniform, which is independent of the coloring distribution such that the following hold: 
    \begin{align} 
   \bE [ \bm T(\bm H_n) | \bm H_n ] \pto \begin{pmatrix}
  \lambda_1 \\ 
  \lambda_2
  \end{pmatrix} \quad \text{ and } \quad \mathrm{Var}[ \bm T(\bm H_n) | \bm H_n ] \pto \begin{pmatrix}
  \lambda_1 & \lambda_{1, 2} \\ 
  \lambda_{1, 2} & \lambda_2
  \end{pmatrix} , 
    \end{align}
   for constants $\lambda_1, \lambda_2, \lambda_{1,2} \geq 0$, with $\lambda_{1,2} \le \lambda_1$ and $\lambda_{1,2} \le \lambda_2$. 
Then
    $$ \bm T(\bm H_n) = \left(\begin{array}{l}
        T(H_n^{(1)}) \\
        T(H_n^{(2)})
        \end{array}\right) \dto \left(\begin{array}{l}
            Z_1 + Z_{1,2}\\
           Z_2 + Z_{1,2}
            \end{array}\right) : = \bm Z , $$
    where $Z_1 \sim \Pois(\lambda_1 - \lambda_{1,2}), Z_2 \sim \Pois(\lambda_2 - \lambda_{1,2}), Z_{1,2} \sim \Pois(\lambda_{1,2})$ are independent.

