[Definition eq:intro-hu of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] A stationary  point process $ \mathsf{P}$ of $  \mathbb R^{d}$ is  hyperuniform if 
\begin{align}

\lim_{R\to \infty }\frac{  \textrm{Var}\left({\mathsf{P}}({B_{R}})\right)}{  \Leb(B_{R})} = 0.
\end{align}

[Lemma 14 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Let $\beta\in\bbR$ and $s\in\partial \cA_\tau$. Let $\phi_\e(s)$ be the average of $\phi$ over $A_\tau\cap \partial B(s;\e)$. In the sense of vague convergence of measures on the space of distributions, the limit
    \begin{equation}
        \LF_\tau^{(\beta,s)}:=\lim_{\e\to0}\e^{\frac{\beta^2}{4}}e^{\frac{\beta}{2}\phi_\e(s)} \LF_\tau  
    \end{equation}
    exists. Furthermore, there exists some constant $C(\tau,s)>0$, such that if we sample $(h,\mathbf{c})$ from $C(\tau,s)\LF_\tau \times [e^{\beta c/2}\mathrm{Leb}_\bbR(dc)]$, then 
    \begin{equation}
        \phi(z)=h(z)+\frac{\beta}{2}  \beta_i G_{\tau}(s, z) + \bfc
    \end{equation}
    has the same law as $\LF_\tau^{(\beta,s)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:projections_ppties of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] \begin{enumerate}
        \item If $\bm{p} \in \TAC[2]$, and $\sigX[]\,, \sigY[] \in \eTA[2]\,$, then $\bracket{\bm{p}}{\sigX[] \otimes \sigY[]} = \bracket{~_{\sigX[]}|\bm{p}}{\sigY[]} = \bracket{\bm{p}|_{\sigY[]}}{\sigX[]}\,$.
        \item If $\bm{p}|_{{\color{NavyBlue}{\mathbf{v}}}} \in \mathcal{A}_{\sigX[]}$ for all ${\color{NavyBlue}{\mathbf{v}}} \in V$, then $\bracket{\bm{p}}{\sigX[]\otimes {\color{NavyBlue}{\mathbf{v}}}} = \bracket{~_{\sigX[]}|\bm{p}}{{\color{NavyBlue}{\mathbf{v}}}} = \bracket{\bm{p}|_{{\color{NavyBlue}{\mathbf{v}}}}}{\sigX[]}\,$, for all $\bm p \in \eTAC[2]\,$.
    \end{enumerate}

[Proposition prop hitting balls of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Almost surely, for all $x, y \in \BD_\BQ$, for all $t_1 \le D(\SCL(x), \SCL(y)) $,
	\begin{equation*}
		D(\SCL(x), \SCL(y))  = t_1 + \inf \{ t \ge 0: \SCB_t(\SCL(y)) \cap \SCB_{t_1}(\SCL(x)) \neq \emptyset\}.
	\end{equation*}
	The same identity holds if we replace one of the loops or both of them by segments. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $(\Omega,f)$ be a topological dynamical system. Then the following statements are equivalent:
		\begin{enumerate}[(i)]
			\item  for each $X\in C(\Omega)$, we have $\overline{X}\in C(\Omega)$;
			\medskip
			\item for each $X\in C(\Omega)$, the limit $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}X\circ f^i$ converges uniformly on $\Omega$.
		\end{enumerate}

[Lemma lem:V-estimate of arXiv:2607.22220, 'Pathwise uniqueness for degenerate stochastic differential equations with H\"{o}lder conti'] For $r\le s\le r+1$,
\begin{equation}
\mathbb E{\cal Q}_s(V(s;r))\le C_{T,R}(s-r).
\end{equation}
Consequently,
\begin{equation}
\mathbb E\int_0^{t-h}{\cal Q}_{r+h}(V(r+h;r))\,\mathrm d r
\le C_{T,R}h.
\end{equation}

