\begin{align}
\varphi(\xi) = \langle r, e^{ix \xi} \rangle_{\mu} \le \|r\|_{\mu} \|e^{|\mathrm{Im}(\xi)| \cdot |x|}\|_{\mu} \le \|r\|_{\mu} e, 
