    &=
    \frac{1}{L+1}\mathbf{1}{
    \big\{
    {\langle \eta\rangle}_{L}\geq\tfrac{n+1}{L+1}
    \big\}
    }








    ,
    \\
    \mathbf{g}_{n,L}(\eta)
    &=\frac{1}{L+1}\sum_{j=1}^{L}
    \sum_{i=1}^{j}
    \mathbf{b}_{n,L}^j(\tau^{-i}\eta)
    (\mathbf{e}_{0,1}(\tau^{-i}\eta)
    -\mathbf{e}_{1,0}(\tau^{-i}\eta)
    )

    .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

