[Lemma 28 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] Let $\nu$ be a finite measure on
$\mathbb N$ and $(N_j)_{j\ge1}$ be independent Poisson random variables with means
$\nu(\{j\})$.  For every $P\ge1$ and
$\gamma\ge0$,
\begin{equation}
 \sum_{k\ge1}(1+k)^\gamma
 \Pp\!\left(\sum_{j\ge1}jN_j\ge k\right)^P
 \ll_\gamma(1+\nu(\mathbb N))^{\gamma+1}
 \sum_{k\ge1}(1+k)^\gamma\nu([k,\infty))^P.
\end{equation}

[Corollary 29 (Strict positivity and normalized hitting identity) of arXiv:2607.19752, 'Weak Equilibrium Measures and Capacity--Hitting Identities\\ for the Hypoelliptic Third-Or'] Under the hypotheses of Theorem~\ref{thm:hitting},
\[
    0<\Cap_\eps(A,B;\calD)<\infty.
\]
Consequently,
\[
    \nu_\eps=\frac{\eta_\eps}{\Cap_\eps(A,B;\calD)}
\]
is a probability measure on $\partial A$, and
\begin{equation}
    \int_{\partial A}
    \E_z[\tau_B\wedge\tau_{\partial\calD}] \nu_\eps(dz)
    =
    \frac{\displaystyle\int_{\calD}h^*(z) \pi^\eps(dz)}
    {\Cap_\eps(A,B;\calD)}.
\end{equation}

[Lemma 64 (cf.\ {\cite[Lemma 3.6 and Corollary 3.7) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {Mak24}}] 
    Assume that $\beta = \beta(n) \ll n/\log n$ and let $K > 0$ be any constant. Then for all edges $e,f$ we have
    \begin{equation} 
        |Y(e,f)| = \frac{\weight(f)}{n \xi} \big( |e \cap f| + o(1) \big),
    \end{equation}
    with probability at least $1 - O(n^{-K})$.  In particular,
    \begin{equation} 
        \Big| Y(e,f) - \frac{\weight(f)}{\xi} Y_0(e,f) \Big| = o(1) \cdot \frac{\weight(f)}{n\xi}
    \end{equation}
    with probability at least $1 - O(n^{-K})$. Furthermore, for fixed $k \geq 1$ and distinct edges $e_1, \ldots, e_k \in E$ we have
    \begin{equation} 
        \bP(e_1, \ldots, e_k \in \cT) = (1 + o(1)) \prod_{i=1}^k \frac{\weight(e_i)}{\xi} \bP_0(e_1, \ldots, e_k \in \cT). 
    \end{equation}
    with probability at least $1 - O(n^{-K})$.

