[Thm 9 of arXiv:2511.02763, 'The Cayley-Moser problem with Poissonian arrival of offers'] We have
\begin{equation}E[T_t]=\frac{1}{\lambda}\phi(\mu(t))\int_{\mu_0}^{\mu(t)}\frac{dw}{\phi(w)^2},\end{equation}
\begin{equation}
	Var[T_t]=\frac{1}{\lambda^2}\left[2\phi(\mu(t))\int_{\mu_0}^{\mu(t)}\frac{1}{\phi(u)}\int_{\mu_0}^{u}\frac{1}{\phi(w)^2}dwdu-\left[\phi(\mu(t))\int_{\mu_0}^{\mu(t)}\frac{dw}{\phi(w)^2}\right]^2\right].
\end{equation}

