[Proposition 13 (Riemann curvature of the leaves) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Fix $s \in I$ and let $X, Y, Z, W$ be horizontal and $\xi^* = \xi / H$ the unit vertical field. For the leaf metric $g_s$ of \eqref{eq:leaf-metric}:

	\emph{(i) Horizontal components.}

	\begin{equation}
		\begin{aligned}
			&\mathrm{Rm}_{g_s}(X, Y, Z, W) \;=\; \sum_{i=1}^r F_i^2\; \pi^*\mathrm{Rm}_{g_i}(X_i, Y_i, Z_i, W_i) \\
			&\qquad \;+\; \frac{1}{4}\Big( 2\, \Psi(X,Y)\, \Psi(Z,W) \;-\; \Psi(Y,Z)\, \Psi(X,W) \;+\; \Psi(X,Z)\, \Psi(Y,W) \Big).
		\end{aligned}
	\end{equation}

	\emph{(ii) Vertizontal components.}

	\begin{equation}
		\mathrm{Rm}_{g_s}(X, \xi^*, \xi^*, Y) \;=\; \frac{1}{4}\; \check{g}_s\big( \Psi^\sharp X, \; \Psi^\sharp Y \big) \;=\; \frac{1}{4} \sum_{i=1}^r \frac{\big( (F_i^2)' - \kappa_i \big)^2}{F_i^2}\; \pi^*g_i(X, Y) .
	\end{equation}

	\emph{(iii) Mixed components vanish:} $\mathrm{Rm}_{g_s}(X, Y, Z, \xi^*) = 0$. Since the fibers are one-dimensional, (i)--(iii) determine $\mathrm{Rm}_{g_s}$ completely via the symmetries of the curvature tensor. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 23 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Assume that $\bf H_u(K)$ hold.
Furthermore, let $({\sf \overline{L}_1}, {\sf D}({\sf \overline{L}_1}))$ be the generator on $L^1([0,\infty)\times \mathbb{R}^d ; \overline{\mu})$ provided by \Cref{thm:main0}.

Then there exists a maximal operator ${\sf \overline{L}^K_1}$ on $L^1([0,\infty)\times \mathbb{R}^d ; \overline{\mu})$ which extends $\sf \overline{L}^K$ given in \eqref{eq:L^K}, namely
\begin{align*}
    {\sf D}({\sf \overline{L}_1})&\ni f\mapsto {\sf \overline{L}^K_1}f \in L^1([0,\infty)\times \mathbb{R}^d ; \overline{\mu}) \\
    {\sf \overline{L}^K_1}f(t,x)&:= {\sf \overline{L}_1}f(t,x) +\int_{\mathbb{R}^d} \left[f(t,y)-f(t,x)\right]\; K(t,x,dy), \quad (t,x)\in E \;\overline{\mu}\mbox{-a.e.}, \quad f\in {\sf D}({\sf \overline{L}_1}),
\end{align*}
which is well defined and generates a $C_0$-semigroup $(T_t^K)_{t\geq 0}$ on $L^1([0,\infty)\times \mathbb{R}^d ; \overline{\mu})$.
Moreover, if $X^K$ is the right process constructed in \Cref{prop:X^K}, then the following properties hold:
\begin{enumerate}
    \item[(i)] The transition semigroup $(P_t^K)_{t\geq 0}$ of $X^K$ coincides with $(T_t^K)_{t\geq 0}$ as family of operators on $L^1([0,\infty)\times \mathbb{R}^d ; \overline{\mu})$
    \item[(ii)] There exists $E^K\in \mathcal{B}(E)$ such that $E\setminus E^K$ is $\overline{\mu}$-inessential  with respect to $\mathcal{U}^K$, $\mu_t\left(E^K(t)\right)=1$, $t\geq 0$, where recall that for a set $A\in [0,\infty)\times \mathbb{R}^d$ we define $A(t):=\left\{x\in \mathbb{R}^d : (t,x)\in A\right\}$,
    and for every $(s,x)\in E^K$ and every $f\in C_c^{\infty}((0,\infty)\times \mathbb{R}^d)$ we have that
            \begin{equation}
                \mathbb{E}^K_{(s,x)}\left\{\int_0^{t} \left|{\sf \overline{L}^K}f(X^K(r))\right|\; dr
               \right\}<\infty, \quad t\geq 0,
            \end{equation}
            and 
            \begin{equation}
                \left(f(X^K(t))-f(X^K(0))-\int_0^{t} {\sf \overline{L}^K}f(X^K(r))\; dr\right)_{t\geq 0} \; \mbox{ is a c\`adl\`ag } \left(\mathcal{F}^K_t\right)\mbox{-martingale under } \mathbb{P}^K_{(s,x)}.
            \end{equation}
\end{enumerate}

