[Theorem thm:near_critical of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] Let $d>8$
and $L \ge L_0$ with $L_0$ sufficiently large.
For both lattice trees and lattice animals,
there are constants $c \in (0,1)$ (independent of $L$)
and $C_L, \delta_L > 0$ such that
\begin{equation} 
    G_p(x) \le \frac{C_L}{|x|^{d-2}} e^{-cm(p)|x|}
\end{equation}
for all $p \in [p_c - \delta_L, p_c)$ and for all $x \in \mathbb{Z}^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.26565, 'A Horizon-Free Extrinsic Penrose Inequality'] If $0<s<t<t_0$, then
\begin{equation}
 G_t\subset G_s,
 \qquad E_s\subset E_t

\end{equation}
almost everywhere.  Moreover,
\begin{equation}
 \frac1{\cosh s}\sqrt{\frac{|\Sigma_s|}{\pi}}
 \leq
 \frac1{\cosh t}\sqrt{\frac{|\Sigma_t|}{\pi}}.

\end{equation}

[Prp 18 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Let $a \in \R$, $\alpha \in \R$, and $k \in \N_0$. Let $g$ be the smooth function $g(x) = x$.
\begin{enumerate}
    \item[\normalfont{(1)}] The delta function $\delta_a$ and the constant function $1$ both belong to $\cS_{-\frac{1}{2}-}$. 
    \item[\normalfont{(2)}] For any $T \in \cS_{\alpha}$, we have $\sD^{k} T \in \cS_{\alpha - k}$ and 
    \begin{equation}
        \norm{\sD^{k} T}_{\cS_{\alpha - k}} \leq \prod_{i=0}^{k-1}(2^{|\alpha - i| - 1} + 2^{-1})^{\frac{1}{2}} \norm{T}_{\cS_{\alpha}}.
    \end{equation}
    \item[\normalfont{(3)}] For any $T \in \cS_{\alpha}$, we have $g^{k}T \in \cS_{\alpha - k}$ and 
    \begin{equation}
        \norm{g^{k} T}_{\cS_{\alpha - k}} \leq \prod_{i=0}^{k-1}(2^{|\alpha - i| - 1} + 2^{-1})^{\frac{1}{2}} \norm{T}_{\cS_{\alpha}}.
    \end{equation}
\end{enumerate}

