[Dfn eq:defVoro of arXiv:2506.01746, '\bf Optimal Bregman quantization: existence and uniqueness of optimal quantizers revisited'] A Borel partition of $\mathbb{R}^d$ $(C_a(\Gamma))_{a\in \Gamma}$ is called a {\em Voronoi partition of $\mathbb{R}^d$ induced by $\Gamma$} if
\begin{equation}
\forall\, a \!\in \Gamma,

C_a(\Gamma) \subset  \big\{\xi \!\in \mathbb{R}^d: \|\xi-a\| \le \|\xi-x\|,\; b\!\in \Gamma  \big\}.
\end{equation}

[Deffr intro:def:MBsemimartingale of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] The process $Z_t=(Z_t^{(1)},Z_t^{(2)})^\top$ is called a semimartingale reflected Brownian motion in $\mathbb{R}_+^2$, driven by a Brownian motion $B_t$ with covariance matrix $\Sigma=(\sigma_{ij})_{1 \le i,j \le 2}\in\mathbb{R}^{2\times 2}$, drift $\mu=(\mu_i)_{i=1,2}\in\mathbb{R}^2$, and obliquely reflected on the axes according to a reflection matrix $R=(R_1,R_2)=(r_{ij})_{1 \le i,j \le 2}\in\mathbb{R}^{2\times 2}$ (where $R_j$ is its $j$-th column), if it admits the decomposition
\begin{equation}
Z_t = Z_0 + B_t + \mu t + R L_t, \qquad Z_t \in \mathbb{R}_+^2,
\end{equation}
where $L_t=(L_t^{(1)},L_t^{(2)})^\top$ is a continuous process with nondecreasing components, and each component $L_t^{(i)}$ increases only when the corresponding coordinate $Z_t^{(i)}$ is equal to $0$. The pair $(Z_t,L_t)$ is said to be a solution to the \textit{Skorokhod problem} in the quadrant for $B_t+\mu t$ with respect to the reflection matrix $R$.

[Defn 1 of arXiv:2605.07411, '\bf {A note on the equivalence of super-Poincar\'e inequality}'] \begin{itemize}
\item [(1)] We say that \emph{super-Poincar\'e inequality} (written as SPI) holds for $\mu$ and $(\E,\D(\E))$ with
associated rate function $\beta_{{\rm SP}}(\cdot)$ if
\begin{equation}
\mu(f^2)\le s\E(f,f)+\beta_{{\rm SP}}(s)\mu(|f|)^2,\ s>0,\ f\in \D(\E),
\end{equation}
where $\beta_{{\rm SP}}:\R_+ \to \R_+$ is non-increasing.

\item [(2)] We say that \emph{super log-Sobolev inequality} (written as SLSI) holds for $\mu$ and $(\E,\D(\E))$
with associated rate function $\beta_{{\rm SL}}(\cdot)$ if
\begin{equation}
\Ent_{\mu}(f^2)\le s\E(f,f)+\beta_{{\rm SL}}(s)\mu(f^2),\ s>0,\ f\in \D(\E),
\end{equation}
where $\beta_{{\rm SL}}:\R_+ \to \R_+$ is non-increasing.
\end{itemize}

\item [(3)] We say that \emph{weak log-Sobolev inequality} (written as WLSI) holds for $\mu$ and $(\E,\D(\E))$
with associated rate function $\beta_{{\rm WL}}(\cdot)$ if
\begin{equation}
\Ent_{\mu}(f^2)\le \beta_{{\rm WL}}(s)\E(f,f)+s\|f\|_\infty^2,\ s>0,\ f\in \D(\E),
\end{equation}
where $\beta_{{\rm WL}}:\R_+ \to \R_+$ is non-increasing.

[Lemma lem:cov of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $E$ be a set and $\mathbb P$ a product probability measure on $\{0, 1\}^E$. Let $A$ be an increasing event and~$e\in E$. Then
  \begin{equation}
    \mathrm{Cov}(\omega(e), \mathbf 1_A) = \mathrm{Var}(\omega(e)) \mathbb P(e \text{ pivotal for } A)
  \end{equation}

[Lemma 12 of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Under the same conditions as in Proposition~\ref{prop:ratio}, we have
\begin{equation}
  \E\left[\E_\xi\left[U(\xi+r_-)
  \left(\frac{W(\beta_-(\xi+r_-)+h)}{\Wtil_-(\beta_-r_-+h)}
  -\frac{W(\beta_-(\xi+\gamma)+h)}{\Wtil_-(\beta_-\gamma+h)}\right)\right]\right]^{2k}\le \frac{K}{N^k}.
\end{equation}

[Definition defKab of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For any $n\ge 1$, $A_1,...,A_k\subset \mathbb{Z}^d\setminus B(2dn)$ ($k\in \mathbb{N}^+$) and $a,b\ge 0$, we say $\mathcal{C}^{\ge 0}_{n}$ is $(a,b)$-good in $A_1,...,A_k$ if the following event happens:
	\begin{equation}
		\mathsf{K}_{a,b}(n;A_1,...,A_k):=  \mathsf{H}_{a}(n) \cap \big[  \cap_{i=1}^{k}  \mathsf{Q}_b(n,A_i) \big],
	\end{equation}
	where the events $\mathsf{H}_{a}$ and $\mathsf{Q}_b$ are defined as 
	\begin{equation}
		\mathsf{H}_{a}(n):=\big\{ 	\mathcal{H}^{\ge 0}_{n} \ge a n^{2-d} [\theta_d(n)]^{-1} \big\} ,  
	\end{equation}
	\begin{equation}
		 \mathsf{Q}_b(n,A_i):=\big\{   \mathcal{Q}^{\ge 0}_{n}(A_i)\le b[\theta_d(n)]^{-1}  \mathbf{Q}(A_i)\big\}.
	\end{equation}

