body:
[Theorem 6 of arXiv:2609.03791, 'Canonical Bochner--K\"{a}hler potentials via the Sasaki--K\"{a}hler correspondence'] A real-valued function $F$ on a complex manifold $M$ is a K\"{a}hler potential of a Bochner--K\"{a}hler structure at a point $p\in M$ if and only if
    \begin{equation}
        \begin{bmatrix} 0& z^* & \frac{\I}{2} \end{bmatrix} \e^{2\I AF}\begin{bmatrix} 1\\ z\\ 0 \end{bmatrix}=0
    \end{equation}
    in some coordinates $z=(z_1,\ldots,z_n)$ centered at $p$, for some matrix $A\in \mathfrak{gl}_{n+2}(\mathbb{C})$ of the form 
    \begin{equation}   
    A=\begin{bmatrix}
        0& -2\I a^* & r\\0&\I X& a\\1&0&0
    \end{bmatrix},
    \end{equation}
    where 
    \begin{itemize}
        \item $X\in \mathfrak{gl}_{n}(\mathbb{R})$ is diagonal with entries ordered such that $X_{j,j}\geq X_{j+1,j+1}$,
        \item $a$ is a vector with non-negative real entries satisfying $a_{j+1}=0$ whenever  $X_{j,j}=X_{j+1,j+1}$, and
        \item $r$ is a real number.
    \end{itemize}

    Moreover, such a matrix $A$ is uniquely determined by the germ at $p$ of the Bochner--K\"{a}hler structure being represented. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:Burkholder-Davis-Gundy Inequality of arXiv:2604.07497, 'The Three-Dimensional Stochastic EMHD System: Local Well-Posedness and Maximal Pathwise So'] Let $p > 0$ and
\begin{equation}
M_t := \int_0^t \sigma_s dB_s, 
\end{equation}
where $B_s$ is a standard Brownian motion and $\sigma$ is such that 
\[
{\mathbb E}   \Bigl( \int_0^t \|\sigma_s\|^2_{L_2(\mathscr{U},X)} ds \Bigr)^\frac{p}{2}  < +\infty.
\]
Then there exist $c_p$ and $C_p$, depending the physical dimension and value $p > 0$, such that 
\begin{equation}
c_p {\mathbb E} \Bigl( \int_0^t \|\sigma_s\|^2_{L_2(\mathscr{U},X)} ds \Bigr)^\frac{p}{2}  < {\mathbb E} \left( |M^*_T|^p \right) < C_p {\mathbb E} \Bigl( \int_0^t \|\sigma_s\|^2_{L_2(\mathscr{U},X)} ds \Bigr)^\frac{p}{2} ,
\end{equation}
where
\[
M_T^* := \sup_{t \in [0,T]} |M_t|.
\]
In addition, for $p \geq 2$, $\alpha \in \left[0,{\frac{1}{2}} \right)$ and $\sigma_s \in L^p\bigl(\Omega; L^p(0,T;L_2(\mathscr{U},X))\bigr)$, then
\begin{equation}
{\mathbb E} \| M_. \|^p_{W^{\alpha,p}(0,T;X)} \lesssim_p {\mathbb E} \int_0^T \|\sigma_t \|^p_{L_2(\mathscr{U},X)} dt. 
\end{equation}

[Proposition prop: continuity of period of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $(\lambda_n,C^2_n) \to (\lambda, C^2) \in \overline {S^0}$ such that $(\lambda,C^2) \neq (\frac{p-1}{2},0)$.
  \begin{itemize}
    \item If $(\lambda,C^2) \in S^0 $, then  $P(\lambda_n,C^2_n) \to P(\lambda,C^2) \in (0,\infty)$;
    \item If $(\lambda,C^2) \in \partial S_1^0$ with $\lambda\neq \frac{p-1}{2}$, then  $P(\lambda_n,C^2_n) \to P(\lambda,0)$;
    \item If $(\lambda,C^2) \in \partial S^0_2 $ with $\lambda<p-1$, then
      $P_{\lambda,C^2}:=\lim_n P(\lambda_n,C^2_n)$ exists as limit from inside $S^0$ and $P_{\lambda,C^2}<\pi$;
    \item If $(\lambda,C^2) =(p-1,0)$, then  $P(\lambda_n,C^2_n) \to \pi$ (as limit from inside $S^0$).
    \end{itemize}

