\begin{equation}
	\mathbf P^{\emptyset,\emptyset}_{G}[0\connect{\n_1+\n_2\:}\partial \Lambda_n]=\sum_{\ell=1}^m\mathbf P^{\emptyset,\emptyset}_G[\{0\connect{\n_1+\n_2\:}x_\ell\}\cap ...","release_manifest_digest":"sha256:d6504b8b130fbf31ee5d3f0cb3f20423af20a74e05f7deb9f4cc9b7238237603","revision_digest":"sha256:4c6607f819c7aa53e7a3806c56ea5abf64d4a353c94770c2b30212a7bb2a1649","source_id":"arxiv:2510.23423","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

