[Theorem thm:intro-pathological of arXiv:2605.26652, 'Pathological Large Deviations of the KMP Process in Dimension $d\ge 2$'] Let $(\xi^N_t)_{t\in [0,T]}$ be a KMP process on $\mathbb T_N^d$, with initial data $\xi^N_0$ drawn from an equilibrium measure $\nu^N_\rho, \rho\in (0,\infty)$. Then:
\begin{enumerate}[label=(\roman*)]
    \item in dimension $d=1$, for any $t_0\in [0,T]$, there exists a path $\Xi\in \mathcal X$ whose unique continuous-in-time representative $\xi$ admits a smooth density $u_t(x)$ for $t\neq t_0$, such that $\xi_{t_0}$ is singular with respect to the Lebesgue measure, and where \begin{equation}
    	 \inf_{\mathcal U\ni\Xi} \liminf_N \frac1N\log\mathbb{P}\left(\pi^N(\xi^N)\in \mathcal U\right)>-\infty;
    \end{equation} \item in dimension $d=2$, for any sequence $\epsilon_k>0$ and distinct times $t_k\in (0,T), k\ge 1$ which satisfy $\sum_k \epsilon_k^{\gamma}<\infty$ for some $0<\gamma<1$, there exists a path $\Xi\in \mathcal X$ whose unique c{\`a}dl{\`a}g representative $\xi$ satisfies, for each $k$, $$ \|\xi_{t_k}-\xi_{t_k-}\|_{\rm TV}=2\epsilon_k $$ and such that\begin{equation}
    	 \inf_{\mathcal U\ni\Xi} \liminf_N \frac1{N^2}\log\mathbb{P}\left(\pi^N(\xi^N)\in \mathcal U\right)>-\infty;
    \end{equation}
    \item in dimension $d\ge 3$, fix $c,M\in (0,\infty)$. Then there exists $J=J(\rho, c,M)<\infty$ such that, for any relaxed measure $\Xi$ with constant energy $e(\Xi)\le M$ and a lower bound $\Xi(dt,dx)\ge c dt dx$, it holds\begin{equation}
    	 \inf_{\mathcal U\ni \Xi}\liminf_N \frac1{N^d}\log \mathbb{P}\left(\pi^N(\xi^N)\in \mathcal U\right)\ge -J(\rho, c,M).
    \end{equation}\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Assume the same setup as in Lemma~\ref{lem::reg_Dirichlet_annular_cro}. The regularized Dirichlet energy and the partition function have the following asymptotic as $r\to\infty$: 
\begin{align} 
	\| \varphicro{n} \|_{\nabla(\A_r),\mathrm{reg}}^2=& \frac{n(n-2) \pi r}{2} -2\pi \sum_{1\le i<j\le n} \left( \log \sin \left( \frac{\beta_{j}-\beta_i}{2} \right) + \log \sin \left( \frac{\alpha_{j}-\alpha_i}{2} \right) \right) \notag\\
	& -2\pi n(n-1)\log 2 +\frac{\pi}{2r}\left(\sum_{j=1}^{n} (\alpha_j-\beta_j) \right)^2+ O(1)\ee^{-r};
\\
\LZcro{n}^{(\ell)}(r; \bs{\alpha}, \bs{\beta})=&\sqrt{2}^{n(n-1)}\LZradial{n}(\bs{\alpha})\LZradial{n}(\bs{\beta})\notag\\
&\times\exp\left(\frac{n(2-n)r}{8}-\frac{1}{8r}\left(\sum_{j=1}^{n}(\alpha_j-\beta_{j})-2n\pi\ell\right)^2+O(1)\ee^{-r}\right);
\end{align}
where $\LZradial{n}$ is defined in~\eqref{eqn::LZunitdisc_def} and the $O(1)$ terms have upper bounds independent of $(\bs{\alpha}, \bs{\beta})$.

