[Definition 31 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] We define a measure $\mu_{\beta;S}^{(n)}$ on $(\L^+,\L^-) \in \left[0,\infty \right)^{G_n} \times \left[ 0,\infty \right)^{G_n}$ via
	\begin{multline}
		\d\mu_{\beta;S}^{(n)}(\xi^+,\xi^-) \propto Z^{G_n}(\L^-)  Z^{S}(\L^+) \times \exp\Big( 2\beta(\L^-,J\L^-) + 2\beta(\L^+,J\L^+)_S - 2\beta \sum_{\substack{x \in X \\ y \in S}} J_{xy} \L^+_x \L^+_y\Big) \\ \times \exp(- \textstyle\sum_{x \in X}\I(\L^+_x,\L^-_x)) \d\l_2^X(\L^+) \d\l_2^X(\L^-) \times \d\l_2^S(\L^+)\d\l_2^S(\L^-).
	\end{multline}

[Theorem 9 of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the iterative edge-colored graph process on $V$ and $\d^{(g)}$ and $X^{(g)}$ for $g=1,\ldots,\chi$. Let $x_{\max}^{(g)}$ be the maximum degree in $(V,X^{(g)})$, and let
		\begin{align}
			d_{\max}^{(g)}&:=\max\{d_1^{(g)},\ldots,d_n^{(g)}\},
			\\\Delta^{(g)}&:=d_{\max}^{(g)}\left(x_{\max}^{(g)}+\sum_{h=1}^{g}d_{\max}^{(h)}\right)+m^{(g)}\sum_{h=g+1}^{\chi}\frac{(d_{\max}^{(h)})^2}{m^{(h)}}.
		\end{align}
		Consider the asymptotics as $m_{\min}:=\min\{m^{(1)},\ldots,m^{(\chi)}\}\to\infty$, and assume that $\Delta^{(g)}=O((m^{(g)})^{\sfrac12}/(\log m^{(g)})^2)$ for $g=1,\ldots,\chi$. Then each iteration $g=1,\ldots,\chi$ has probability $O(\Delta^{(g)}/m^{(g)})$ of rejection. In particular, for $m_{\min}$ large enough, there exist edge-disjoint simple graphs for $g=1,\ldots,\chi$ with degree sequence $\d^{(g)}$ and with no edges from $X^{(g)}$. Furthermore, any such graphs are sampled with probability $e^{O(\mathscr{E})}\mathscr{P}$, where $\mathscr{E}:=\sum_{g=1}^{\chi}\mathscr{E}(m^{(g)},\Delta^{(g)})$ and
		\begin{align}
			\mathscr{P}&:=\exp\left(\sum_{g=1}^{\chi}\left(\tfrac12\lambda_{\d^{(g)}}+\tfrac14\lambda_{\d^{(g)}}^2+\tfrac12\sum_{h=g+1}^{\chi}\lambda_{\d^{(g)},\d^{(h)}}^2+\mu_{\d^{(g)}}^{X^{(g)}}\right)\right)
			\\&\quad\cdot\prod_{g=1}^{\chi}\left(\frac1{(2m^{(g)}-1)!!}\prod_{i=1}^{n}d_i^{(g)}!\right),
		\end{align}
		which is asymptotically uniform if $\mathscr{E}=o(1)$. The total number of such graphs is thus $e^{O(\mathscr{E})}\mathscr{P}^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 12 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] The formal derivative of order $\alpha \in \mathbb{N}^{d}$
		is defined to be the formal operator on $\mathcal{X}_{A}^{\Phi}$
			given by 
		\begin{equation*}
			\overline{D}_{y}^{\alpha }=\mathcal{G}_{1}^{-1}\circ \partial ^{\alpha
			}\circ \mathcal{G}_{1}  
		\end{equation*}
		where $\partial ^{\alpha }$ is defined above. In particular,
			for $\alpha =(\delta _{ij})_{1\leq j\leq d}$ with $1\leq i\leq d$
		, $\overline{D}_{y}^{\alpha }$ is denoted by $\overline{
			\partial }/\partial y_{i}$ and is called the \textit{formal partial derivative of
		index} $i$.

[Corollary 53 (Polynomial weights and quantitative cutoff rates) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Fix $m\ge1$, $1\le r<\infty$, and $a,b\ge0$ satisfying
\eqref{eq:group-smoothing-range}.  Suppose \eqref{eq:group-growth} holds,
$c_x=\langle x\rangle^{-\sigma}$, and $\sigma>D/2$.  Then, with
$\delta=\sigma-D/2$, for every $1\le p<\infty$,
\begin{equation}

 \norm{T_{m,N}^{a,b}(c)-T_m^{a,b}(c)}_{L^p(\Omega;\Sch_r)}
 \le C_{\Gamma,D,\sigma,a,b,m,r}(p+r)^{m/2}N^{-\delta}.
\end{equation}
For a common realization and every $t\ge1$,
\begin{equation}

 \Prob\!\left(
  \norm{T_{m,N}^{a,b}(c)-T_m^{a,b}(c)}_{\Sch_r}
  >\mathrm e\,C_{\Gamma,D,\sigma,a,b,m,r}
    (t+r)^{m/2}N^{-\delta}
 \right)
 \le\mathrm e^{-t}.
\end{equation}
Consequently,
\begin{equation}

 \norm{T_{m,N}^{a,b}(c)-T_m^{a,b}(c)}_{\Sch_r}
 =O_\omega\!\left(
    N^{-\delta}(\log(e+N))^{m/2}
  \right)
 \qquad\text{almost surely}.
\end{equation}
In particular, this is $O_\omega(N^{-\eta})$ for every
$0<\eta<\delta$.
For the integer Heisenberg group $H_3(\mathbb Z)$ one may take $D=4$;
thus the sufficient range becomes
\begin{equation}

 \sigma>2,\qquad a>0,\qquad b>0,\qquad a+b>\frac4r.
\end{equation}

