body:
[Proposition 2 of arXiv:2607.13401, 'Total variation cutoff for Kac's walk on the sphere'] For every \(t\ge0\),
\begin{equation*}
        \norm{P_{n-1}^t(e_1,\cdot)-\sigma_{n-1}}_{\on{TV}}
        =
        \norm{Q_n^t(e^{(1)},\cdot)-\pi_n}_{\on{TV}} .
\end{equation*}

[Definition 3 of arXiv:2506.17094, 'Nonlinear random perturbations of Reaction Diffusion Equations'] {\em A process $X \in\,\mathcal{H}^{\,p}_{\lambda,t}(E)$ is a mild solution for equation \eqref{stoch-pde.existence} if 
\begin{equation}
X(s)=S(s-\lambda)x+\int_\lambda^s S(s-r)F(X(r))dr
+\sqrt{\e}\int_\lambda^s S(s-r) \sigma(X(r),  \E(g(X(t))|\F_r))\,dW_r,
\end{equation}
holds for every $\lambda\leq s\leq t$.
}

[Cor 2 of arXiv:2606.02570, 'Stochastic completeness for landmark space'] Suppose that the radial scalar function $k\colon [0,\infty)\to\R$ is smooth on $(0,\infty)$ and that its even extension to $\R$ is twice continuously differentiable at zero. In addition, assume that $k$ possesses a positive continuous Fourier transform $\widehat{k}\colon\R^d\to\R$ and that there exist $p\geq 1$ as well as a constant $b>0$ such that, for all sufficiently high frequencies $\xi\in\R^d$,
    \begin{displaymath}
        \widehat{k}(\xi)\geq b\|\xi\|^{-p}.
    \end{displaymath}
    Then the landmark manifold $(\Land,g)$ is stochastically complete for all $n\geq 2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

