body:
[Thm 3 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] There is a critical mass $M_c>0$ (defined in~\eqref{Mc} below) such that the following hold:
\begin{itemize}
\item [\textbf{(I)}] For any initial value $(u^0,w^0)\in \mathcal{I}_{M,\bar{M},rad}(\mathbb{B}_R)$ with $M\in (0,M_c)$ and \mbox{$\bar{M}\ge M$}, the global solution $(u,w)$ to~\eqref{E} is bounded.
\item [\textbf{(II)}] Let $M>M_c$. There is $\mu_{M}^s\in\mathbb{R}$ such that, for any $\bar{M}\ge M$, the set
\begin{equation*}
    \mathcal{F}_{M,\bar{M}} := \left\{ (u^0,w^0)\in \mathcal{I}_{M,\bar{M},rad}(\mathbb{B}_R)\ :\ \mathcal{L}(u^0,w^0)<\mu_{M}^s \right\}
\end{equation*}
is non-empty and, for any initial value $(u^0,w^0)\in \mathcal{F}_{M,\bar{M}}$, the global solution $(u,w)$ to~\eqref{E} blows up in infinite time.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pr:meta of arXiv:2412.01489, 'One- and two-particle spectral gap identities for the symmetric inclusion process and rela'] For the chain $(\ensuremath{\mathcal M}_{\hat\alpha,k}(t))_{t\ge0}$, the following two claims hold true:
	\begin{enumerate}[(a)]


		\item For every $m, m'\ge 1$ with $\Omega_{k,m}\neq \varnothing\neq \Omega_{k,m'}$ and $\eta\in \Omega_{k,m}$, we have 
	\begin{equation}
		{\bf r}_{\hat \alpha,k}^\ensuremath{\mathcal M}(\eta,\xi) = 0\; \text{,}\;\;\quad \text{for all}\ \xi \in \Omega_{k,m'}, \ m'>m\; \text{,}\;\; 
	\end{equation}
	while, when $m\ge 2$, there exist $\eta^1,\ldots,\eta^\ell \in \Omega_{k,m}$ satisfying
	\begin{equation}
{\bf r}_{\hat \alpha,k}^\ensuremath{\mathcal M}(\eta,\eta^1)\tonde{	\prod_{h=1}^{\ell-1}	{\bf r}_{\hat \alpha,k}^\ensuremath{\mathcal M}(\eta^h,\eta^{h+1})} {\bf r}_{\hat \alpha,k}^\ensuremath{\mathcal M}(\eta^\ell,\xi)>0\; \text{,}\;\;\quad \text{for some}\  \xi\in \Omega_{k,m'}, \ m'<m\; \text{.}
	\end{equation}
	As a consequence, $\Omega_{k,m}$, $m\ge 2$, consists of transient states only.

		\item  The chain $(\ensuremath{\mathcal M}_{\hat \alpha,k}(t))_{t\ge0}$ is irreducible on $\Omega_{k,1}\neq \varnothing$, and the position of the single stack evolves as ${\rm RW}(\hat \alpha)$.
		\end{enumerate}

