body:
[Theorem RDS_SDS of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Let $\left(\mathcal{B}, \{P_t\}_{t \geq 0}, \mathbf{P}, \{\vartheta_t\}_{t \geq 0}\right)$ be a stationary noise process and let \( \varphi \) be a continuous SDS in the sense of Definition~(SDSSS of the paper). Then the following statements hold. 
	\begin{enumerate}
		\item  Consider the probability space \((\Omega, \mathcal{F}, \mathbb{P})\), where 
		\[
		\Omega := \mathcal{B} \times \mathcal{B}, \quad 
		\mathcal{F} := \sigma(\mathcal{B}) \otimes \sigma(\mathcal{B}), \quad 
		\mathbb{P} := \mathbf{P} \times \mathbf{P}.
		\]

		Define \( \theta_t : \Omega \to \Omega \) by
		\begin{align}
			\begin{split}
				\theta_t(\omega^-,\omega^+) :=
				\begin{cases}
					\left(P_{t}(\omega^-,\omega^+), \vartheta_{t}\omega^+\right), & \text{for } t \ge 0,\\[4pt]
					\left(\vartheta_{-t}\omega^-, P_{-t}(\omega^+, \omega^-)\right), & \text{for } t < 0.
				\end{cases}
			\end{split}
		\end{align}
		Then \((\Omega, \mathcal{F}, \mathbb{P}, \theta)\) constitutes a measurable metric dynamical system.
		\item Define
		\begin{align}
			\begin{split}
				&\Phi: \mathbb{R}^+ \times \mathcal{X} \times \Omega \to \mathcal{X},\\
				&(t, x, (\omega^-, \omega^+)) \longmapsto \Phi^{t}_{(\omega^-, \omega^+)}(x) := \varphi^{t}_{P_{t}(\omega^-, \omega^+)}(x).
			\end{split}
		\end{align}
		Then \( \Phi \) is a continuous RDS over \((\Omega, \mathcal{F}, \mathbb{P}, \theta)\). If \( \varphi \) is of class \( C^k \) for any \( k \ge 1 \), then the same regularity holds for \( \Phi \).

		\item Suppose that \( \varphi \) admits an invariant measure \( \mu \) in the sense of Definition~(DEAFRS of the paper). For every \( t \ge 0 \), define
		\begin{align*}
			&\Theta_{t}: \mathcal{X} \times \Omega \to \mathcal{X} \times \Omega ,\\
			&(x, \omega^-, \omega^+) \longmapsto \left(\Phi^{t}_{(\omega^-, \omega^+)}(x), P_{t}(\omega^-, \omega^+), \vartheta_{t}\omega^+\right).
		\end{align*}
		Then
		\begin{align}
			\left(\mathcal{X} \times\Omega, \; 
			\sigma(\mathcal{X}) \otimes\mathcal{F}, \; 
			\mu \times \mathbf{P}, \; \Theta \right)
		\end{align}
		is a metric dynamical system.

		\item Let \(\mu\) be an ergodic invariant measure and suppose that for every \(t > 0\), the map \(\vartheta_t : \mathcal{B} \to \mathcal{B}\) is ergodic with respect to the measure \(\mathbf{P}\). 
		Then for every \(t > 0\), the map \(\Theta_t\) is ergodic with respect to \(\mu \times \mathbf{P}\).

		\item Suppose that \( \mathcal{X} \) is a separable Banach space and \( \varphi \) is a \( C^k \)-SDS for some \( k \ge 1 \). Define 
		\begin{align*}
			& \mathcal{T} : \mathbb{R}^{+} \times \mathcal{X} \times 
			\left(\mathcal{X} \times \Omega \right) \to \mathcal{X},\\
			&\left(t, y, (x, \omega^-, \omega^+)\right) \longmapsto 
			\mathcal{T}^{t}_{(x,\omega^-,\omega^+)}(y) := \mathrm{D}_{x}\Phi^{t}_{(\omega^-,\omega^+)}(y).
		\end{align*}
		Then \( \mathcal{T} \) is a linear continuous RDS over the metric dynamical system~(equation MERTCIDY of the paper).
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

