[Lemma 8 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] The velocity field  defined in~\eqref{eq:def_u} satisfies
\begin{equation*}
    u \in C^{\infty}([0,1]; C^{\alpha}(\T^2))\quad \text{for any } 0< \alpha < \frac{1}{\gamma +(1-\gamma)(1+\delta)}.
\end{equation*}
In particular, for any $\alpha \in (0,1)$ and $\gamma \in (1/2,1)$ there exists $\delta \in (0,1)$ sufficiently small so that $u \in C^{\infty}([0,1]; C^{\alpha}(\T^2))$.

[Proposition 5 (Recurrence at the critical dimension for $\alpha=2$) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Assume that \(\alpha=2\), \emph{i.e.} \(\mu\) is attracted to a
Gaussian distribution, and that $\theta$, defined here on $\Z^4$, has a finite moment of order $\delta>4$. A \(\Tree_{n}\)-walk in \(\Z^4\) with $\theta$-jumps  is recurrent:

\begin{equation*}{
\frac{R^{\theta}(\Tree_{n})}{n} \xrightarrow[n \to +\infty]{(\P)} 0.
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma2 of arXiv:2411.18775, 'Limit Theorems for the Dynamical Foundation of the Fractional Brownian Motion and Related '] For each fixed $t_0>0$ consider $(\widetilde{X}^N_t)_{t\in[0,t_0]}$ and $(\widetilde{Z}^N_t)_{t\in[0,t_0]}$ as in formulas~(equation eq:MyX of the paper) and~(equation eq:MyZ of the paper) respectively. Under assumptions of Theorem~(Thm of the paper)~(i), we have
		\begin{align*}
			\sup\limits_{t\in[0,t_0]} \mathbb{E}\left[|\widetilde{X}^N_t-\widetilde{Z}^N_t|^2  \right]\leq C M \dot v(t_0) N^{a-1}\longrightarrow 0,\qquad N\to\infty.
		\end{align*}

[Lemma lemma_new_decomposition of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For any $d\ge 3$, there exist $C,C'>0$ such that for any $N\ge 1$, $M\ge CN$, $A  \subset \widetilde{B}(\frac{N}{10C'})$ and $A',D\subset [\widetilde{B}(10C'M)]^c$, 
\begin{equation} 
	\begin{split}
		&\mathbb{P}\big(  A \xleftrightarrow{(D)}A', \widetilde{\mathcal{L}}_{1/2}^{D}[N,M]\neq 0 \big)\\
		\lesssim  & \big(\frac{N}{M}\big)^{d-2}\mathbb{P}\big( A \xleftrightarrow{(D)}\partial B(\tfrac{N}{C'}) \big)\mathbb{P}\big(A'   \xleftrightarrow{(D)} \partial B(C'M) \big).
	\end{split}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm def:decoupling_function of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] We say that $D$ is a decoupling function of order 1 if and only if $D$ is rational and satisfies (equation eq:G->F of the paper). Such a function exists if and only if
\begin{equation}
\epsilon+\delta\in \beta \mathbb{Z}+ \pi\mathbb{Z}.

\end{equation}
We say that $D$ is a decoupling function of order 2 if $D$ is rational and satisfies (equation eq:doubledecoupl of the paper). Such a function exists if and only if
\begin{equation}
2\epsilon+\vartheta-\beta \text{ and } 2\delta-\vartheta \in \beta \mathbb{Z}+ \pi\mathbb{Z}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2609.03243, 'Weighted Ces\`aro type operators on the weighted Bergman spaces in the unit ball'] For $k\geq 1$, let $E_k=\{u\in\mathbb{D}: \delta_{k+1}<|1-u|\leq \delta_k\}$. Then 
\begin{equation*}
\int_{E_k}(1-|u|^2)^{n+\alpha-1}{\rm d}A(u)\simeq \delta_{k}^{n+1+\alpha}.
\end{equation*}

[Lem 73 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] It holds that
  \begin{align*}
    R_H(K,V_n)\lesssim \left(\frac{3}{5}\right)^{n},\qquad R_{\BL^{\kappa}}(\mu,\mu_n)\lesssim \left(\frac{3}{5}\right)^{\kappa n}.
  \end{align*}

[Theorem thm:only_dirichlet of arXiv:2411.11425, 'Non-equilibrium steady states with a spatial Markov structure'] Let $\{\Lambda^n\}_{n \geq 1}$ be a symmetric, two-sided Markov family, i.e.,  $\Lambda^1$ is of the form (equation eq:form_generating of the paper)


    \begin{equation}
        \Lambda_{a,b}^1(x) = f(a,b) \cdot g(b,x) \cdot g(a,x)
    \end{equation}

        with 

    \begin{equation}
        f(a,b)^{-1} = \int_{a \wedge b}^{a \vee b} g(a,x) \cdot g(b,x) dx
    \end{equation}

    \noindent
    for some symmetric function $g:\mathbb{R}^+_0 \times \mathbb{R}^+_0 \rightarrow \mathbb{R}^+_0$. We assume $g(x,.)$ to be differentiable on $\mathbb{R}^+ \setminus \{x\}$ for all $x \in \mathbb{R}^+$.\\

    \noindent

    If $\{\Lambda^n\}_{n \geq 1}$ is both scale and shift invariant, then, for some $\sigma,t \in \mathbb{R}^+$,

    \begin{equation}
        g(a,x) = t \cdot |b-x|^{\sigma}.
    \end{equation}

    As a consequence we have, for $s = \sigma + 1$,

    \begin{equation}
         \Lambda_{a,b}^1(x) = f(a,b) \cdot  |b-x|^{s-1} \cdot |x-a|^{s-1}.
    \end{equation}

    \noindent
    In other words, we recover the density corresponding to the Dirichlet process with parameter $s$ from example (ex:Dirichlet_distribution of the paper).

