[Lemma l:stronlgy log-dominating modification of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $\rho$ be a strongly log-dominating function. Then there exists a strongly log-dominating function $\tilde\rho\leq \rho$ such that 
\begin{equation}
    \tilde\rho(2r) \leq 4 \tilde\rho(r), \quad r\geq0.
\end{equation}
\begin{proof}
Define $a_0:= \rho(0)$ and iteratively define
\begin{equation*}
    a_n := \min(4a_{n-1}, \rho(2^n-1)), \quad n\in\N.
\end{equation*}
Now, let $\tilde\rho:[0,\infty)\to[0,\infty)$ and choose
\begin{equation*}
    \tilde\rho(r) := a_{\lfloor\log_2(r+1)\rfloor},\quad r\geq 0.
\end{equation*}
Then, by construction and because $\rho$ is increasing, $\tilde\rho$ is increasing and
\begin{equation*}
    \tilde\rho(r) = a_{\lfloor\log_2(r+1)\rfloor} \leq \rho(2^{\lfloor\log_2(r+1)\rfloor}-1) \leq \rho(r), \quad r\geq0.
\end{equation*}
Additionally,~(equation e:subexponential growth of the paper) holds, as
\begin{equation*}
     \tilde\rho(2r) = a_{\lfloor\log_2(2r+1)\rfloor} \leq a_{\lfloor\log_2(r+1)\rfloor+1} \leq 4 a_{\lfloor\log_2(r+1)\rfloor} = 4 \tilde\rho(r), \quad r\geq0.
\end{equation*}
It remains to show that $\tilde\rho$ fulfills~(equation e:strongly log-dominating of the paper). We have that
\begin{equation}
    \int_0^\infty \frac{1}{r\tilde\rho(r)+1} \, dr \leq \sum_{n=0}^\infty \frac{2^n}{na_n + 1}.
\end{equation}
Choose $N_0\in\N$ such that $(n+1)a_n \geq 2$ for $n\geq N_0$. This is possible, as $a_n\to\infty$ as $n\to\infty$ because $\rho(r)\to\infty$ as $r\to\infty$. Note that this implies $4(n+1)a_n+1\geq 3((n+1)a_n+1)$ for $n\geq N_0$. Hence, for $N\geq N_0$,
\begin{align*}
    \sum_{n=0}^N \frac{2^n}{na_n + 1} &\leq \sum_{n=1}^N \frac{2^n}{4na_{n-1} + 1} + \sum_{n=0}^N \frac{2^n}{n\rho(2^n-1) + 1}\nonumber\\
    &\leq \sum_{n=N_0+1}^N \frac{2^n}{4na_{n-1} + 1} + \underbrace{ \sum_{n=1}^{N_0} \frac{2^n}{4na_{n-1} + 1} + 1 + 2\int_0^\infty \frac{1}{r\rho(r)+1}\, dr}_{=: C < \infty}\nonumber\\
    &\leq \frac{2}{3} \sum_{n=N_0+1}^N \frac{2^{n-1}}{na_{n-1} + 1} + C\nonumber\\
    &\leq \frac{2}{3} \sum_{n=0}^N \frac{2^n}{na_n + 1} + C.
\end{align*}
Therefore, the RHS of~(equation e:series bound of the paper) is bounded by $3C<\infty$, which concludes the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem thm:bernoulli-lemma of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $(X_{j,\tau})_{j\in\mathds{N}_0,\tau\in\mathds{N}}$ be a family of non-negative i.i.d.\ random variables, $\eps,\delta \in (0,\infty)$, $\mu,\nu\in (-\infty,0]$, and $\sigma\in [1,\infty)$.
Fix $d\in\mathds{N}$ and let
\begin{align*}
M_j&\mathrel{\mathop:}= \#\setcond{m\in\mathds{Z}^d}{\left\lVertm\right\rVert_{\infty}\leq 2^j}=(2^{j+1}+1)^d,\\
N_j&\mathrel{\mathop:}=\#\setcond{m\in\mathds{Z}^d}{2^j<\left\lVertm\right\rVert_\infty\leq 2^{j+1}}=M_{j+1}-M_j
\end{align*}
for $j\in\mathds{N}_0$.
Let further $(\lambda_{j,\tau})_{j\in\mathds{N}_0,\tau\in\mathds{N}}$ be a family of independent random variables, independent of $(X_{j,\tau})_{j\in\mathds{N}_0,\tau\in\mathds{N}}$ and such that $\lambda_{j,\tau}$ is Bernoulli distributed with success probability
\begin{equation*}
\varrho_{j,\tau}\mathrel{\mathop:}= 2^{j\mu}\lr{1+\frac{\left\lVert\phi(\tau)\right\rVert_\infty}{2^j }}^\nu,
\end{equation*}
where $\phi:\mathds{N}\to \mathds{Z}^d$ is a bijection such that $\tau\mapsto\left\lVert\phi(\tau)\right\rVert_\infty$ is nondecreasing.
If
\begin{equation}
\mathds{E}[X_{j,\tau}^{\sigma(1+\eps)}]< \infty\qquad\text{and}\qquad \delta+\delta\eps-\eps\geq 0,
\end{equation}
then
\begin{equation*}
\tilde{\Xi}\mathrel{\mathop:}= \sup_{j\in\mathds{N}_0}\lr{\frac{1}{M_j}\sum_{\tau=1}^{M_j}\varrho_{j,\tau}^{\frac{\delta-1}{\sigma}}\lambda_{j,\tau}X_{j,\tau}+\sup_{\ell\geq j}\frac{1}{N_\ell}\sum_{\tau=M_\ell+1}^{M_{\ell+1}}\varrho_{j,\tau}^{\frac{\delta-1}{\sigma}}\lambda_{j,\tau}X_{j,\tau}}
\end{equation*}
satisfies $\mathds{E}[\tilde{\Xi}^\sigma]<\infty$.

