\begin{equation}
\limsup_{s\to 0+}\Big(\frac{1}{\log 1/s\, \log^{(3)} 1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k\leq(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
