body:
[Corollary cor:growth of arXiv:2609.02820, 'Sharpness and critical scaling of parking'] Under the assumptions of Theorem~(thm:master of the paper),
	\begin{equation}
		\mathbb{E} U_n(0)\asymp
		\begin{cases}
			n^{(4-d)/4}&d\leq3\,,\\
			\log n&d\geq4\,.
		\end{cases}
	\end{equation}
	When $d\leq3$, we have $S_t\asymp (t+1)^{-d/4}$ for every $t\geq0$.
	When $d\geq4$, there are $0<c\leq C<\infty$ such that, for every $t\geq0$,
	\begin{equation}
		\frac{c}{t+1}\leq S_t\leq\frac{C\log(t+2)}{t+1}\,.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:prop1 of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Fix a universal constant $C_R>0$, and define 
\begin{equ}
\Xi \equiv \Xi(\xi, V,{\tt u} ,C_R)
\eqdef
\max \Big(
{\talloblong \omega\xi \talloblong}_{4}, C_R,
\|V\|_{C^9(B_0(C_R+|{\tt u}|))} \Big)\;.
\end{equ}
If there exists constants $C,p\geqslant1$ such that $T=C\Xi^{-p}$, we just write $T = T_{\Xi}$.

There exists $\tilde{T} = \tilde{T}_{\Xi} \in(0,1]$ such that, for any $T \in (0,\tilde{T}]$ and $\eps \in (0,1]$, the map
\begin{equs}
    \Phi:\binom{\theta_{\eps,}}{\tilde{R}_{\eps,}}\mapsto\binom{\Phi^\theta_{\eps,}}{\Phi^{\tilde{R}}_{\eps,}}(\theta_{\eps,},\tilde{R}_{\eps,})\eqdef\binom{-\int_{}^{T}\tilde K_{\nu,}\mathcal{R}^2_{\nu} \dot G_{\nu}  \big(\tilde{F}_{\eps,\nu}[K_{\nu}\theta_{\eps,\nu}]+\tilde{R}_{\eps,\nu}\big)\mathrm{d}\nu}{-\int_0^{}\tilde K_{,\nu}\big(
      \mathrm{D} \tilde{F}_{\eps,\nu}[K_{\nu}\theta_{\eps,\nu},\mathcal{R}_\nu\dot G_\nu \tilde{R}_{\eps,\nu}]+\Tilde{I}_{\eps,\nu}[K_\nu\theta_{\eps,\nu}]\big)
      \mathrm{d}\nu}    
 \end{equs}
is a contraction for the norm 
\begin{equs}    \nnorm{\theta_{\eps,},\tilde{R}_{\eps,}}_T\eqdef 
    \sup_{\mu\in(0,T]}{\| \theta_{\eps,\mu} 
    \|}_{L_{0;T}^\infty}\vee\sup_{\mu\in(0,T]}\mu^{-\delta/2}{\|  \tilde{R}_{\eps,\mu} 
    \|}_{L_{0;T}^\infty}\,.
\end{equs}
In particular, the system (equation eq:sys2 of the paper) has a unique solution, denoted $(\theta_{\eps,},\tilde{R}_{\eps,})$, satisfying the estimate
  \begin{equs}
        \sup_{\mu\in(0,T]}\mu^{-\delta/2}{\| \tilde{R}_{\eps,\mu} 
    \|}_{L^\infty_{0;T}}\leqslant C_R\,.
    \end{equs}
Finally, the solution $(\theta_{\eps,},\tilde{R}_{\eps,})$ is continuous in the data $(\tilde{F}_{\eps,},\Tilde{I}_{\eps,})$.

[Lemma 20 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] In the yellow region, it holds with $\lambda=\lambda(\theta,a)$ as given in \eqref{root_yellow_2} that
    \begin{align*}
       p_n^{a,y}(\theta)\sim c(\theta,a)E\left(\theta,\frac{-\theta y}{\lambda(a+1)}\right)\lambda^{n+1}
   \end{align*}
   for $-a\leq y \leq \frac{-a}{\theta}$; and 
   \begin{align*}
       p_n^{a,y}(\theta)\sim c(\theta,a)E\left(\theta,\frac{a}{\lambda(a+1)}\right)\lambda^{n+1}
   \end{align*}
   for $\frac{-a}{\theta}<y\leq1$, with the abbreviation
    \begin{align*}
       c(\theta, a)\coloneqq\frac{1}{\frac{-a}{\theta(a+1)}\left(E\left(\theta,\frac{a}{\lambda(a+1)}\right)\frac{-\theta}{a}- \frac{\theta +a}{\lambda(a+1)}
        E\left(\theta,\frac{\theta a}{\lambda(a+1)}\right)\right)} 
   \end{align*}

