body:
[Lemma 23 of arXiv:2608.21063, '\textbf{Non-bijective scaling limits and phase transitions of planar maps}'] Suppose that $\nu=1$ and that condition~\eqref{eq:bwregvar} holds for some $1<\alpha<2$.  Let $\gamma_{\mathrm{dec}}>\alpha-1$.  Suppose that for some integer $p$ with
	\begin{align*}
		p >	\max\left(2, \frac{4\alpha}{2\gamma_{\mathrm{dec}}+1-\alpha} \right)
	\end{align*}
	there is a constant $C>0$ such that
	\begin{align*}
		\sum_{k=1}^{m}\Ex{\mD_k^p} \le 	Cm^{1+p\gamma_{\mathrm{dec}}}
	\end{align*}
	for all $m\ge1$.  Then, for every $\epsilon>0$,
	\begin{align*}
		\lim_{\delta\downarrow0}
		\sup_{\substack{N\ge1\\\Pr{|\mT|=N}>0}}
		\Prb{\max_{v\in\mT_N} \sum_{u\in[o,v]_{\mT_N}} \mD_u \one_{\{d_{\mT_N}^+(u)\le\delta b_N\}} > \epsilon b_N^{\gamma_{\mathrm{dec}}} } = 0.
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Uniform logarithmic Sobolev inequality) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] For every fixed $\beta>0$, there exists $\rho_*(\beta)>0$ such that, for all $N\ge2$ and every real-valued $f\in\mathsf D_{N,\beta}$,
\begin{equation}
 \Ent_{\mathbb P_{N,\beta}}(f^2)
 \le \frac2{\rho_*(\beta)}\cE_{N,\beta}(f).
\end{equation}
Moreover, for every compact interval $I\Subset(0,\infty)$,
\begin{equation}
 \inf_{\beta\in I}\inf_{N\ge2}\rho_{N,\beta}>0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2510.25900, 'Dixie cup problem in an interlacing process'] Let the sequence $\alpha = \{a_{j}\}_{j=1}^{\infty }$ is formed as the \textit{interlacing} of two subsequences $\beta = \{b_{j}\}_{j=1}^{\infty }$ and $\delta = \{d_{j}\}_{j=1}^{\infty }$, as given in relation (\ref{sb1}).  Then,  as $N=2M \rightarrow \infty$ we have
\begin{equation}
E\left[T_{m}\left(N;\alpha\right)\right]\sim \left(D_M +B_M\right)\int_{0}^{\infty}\left[1-\prod_{j=1}^M
 \bigg(1-S_m(d_{j}u)e^{-d_{j}u}\bigg)\right]du 
\end{equation}
where, 
\begin{align*}
B_M:=\sum_{j=1}^M b_j\,\,\,\,\,\text{and}\,\,\,\,D_M:=\sum_{j=1}^M d_j,
\end{align*}
provided that the coupons from the sequence $\delta$ are far rarer than the ones from the sequence $\beta$ (see, (\ref{deca})--(\ref{cond3})). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 13 of arXiv:2607.22441, 'The martingale representation theorem for cylindrical martingale valued measures'] Let $\Phi \in \Lambda^2(M,H,G)$. Then $\Phi \in \Lambda(M,H,G)$ and for every $t \in [0,T]$, $A \in \calA$ and $g \in G$, 
\begin{equation}
\inner{(R)\int_0^t\!\! \int_A \Phi(r,u)M(dr,du)}{g}_{G} = \int_0^t\!\! \int_A \Phi(r,u)M(dr,du)(g).     
\end{equation}

