[Proposition prop:LDP of arXiv:2511.22162, 'Landau Hamiltonian with Gaussian white noise potential and the asymptotics of its bottom o'] Fix a bounded open box $B$. As $\beta \to 0$, the sequence of random variables $\lambda_1^B(0, \mathrm{h}_\beta, \mathrm{Z}_\beta)$ satisfies a LDP with rate $\beta^{2}$ and the good rate function \footnote{Given any bounded open box $B$ and $\varphi \in L^2(B)$, the operator $-\Delta + \varphi$ (with zero Dirichlet b.c. on $B$) is self-adjoint on $L^2(B)$ with compact resolvent. This can be seen by the construction given in Section (sec:construction of the paper). Indeed, it coincides with $\Phi^B(0,q)$ with $q = (G\ast\varphi, -F\ast\varphi - |\nabla G\ast\varphi|^2) \in \ccM$.}
	\begin{equ}
		I_B(x) = \inf\left\{\frac12 \left\| \varphi \right\|_{L^2(B)}^2: \text{$\varphi \in L^2(B)$ s.t. $x$ is the lowest e.v. of $-\Delta + \varphi$}\right\}, \quad x \in \R,
	\end{equ}
	with the convention $\inf \emptyset = \infty$.

[Theorem 5 (Wendel's formula: Combinatorial version) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $n, d \ge 1$ be integers with $n \geq d+1$.
For every regular $X \in \R^{d\times n}$, the cardinality of the set $\mathcal M(X)$ is given by
\begin{align*}
    |\mathcal M(X)| = 2 \sum_{j=0}^{d-1} \binom{n-1}{j}.
\end{align*}
In particular, this cardinality is the same for all regular $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2608.19576, 'Convex order preservation for graphon mean-field systems'] Assume that Assumption \ref{A:assump:1} is in force. 
    \begin{itemize}
        \item[\textup{(i)}] There exist $h_0, \widehat{C} > 0$ such that
        \begin{equation*}
            \sup_{t \geq 0} \sup_{u \in I} \mathbb{E}\Big[\big|X^u_t\big|^2\Big] \vee \sup_{h \in (0, h_0)} \sup_{t \geq 0} \sup_{u \in I} \mathbb{E}\Big[\big|\bar{X}^{u,h}_t\big|^2\Big] < \widehat{C}.
        \end{equation*}
        Moreover, there exists a constant $\widehat{\kappa}$ such that for any $h \in (0,h_0)$,
        \begin{equation*}
            \sup_{t \geq 0} \sup_{u \in I} \mathbb{E}\Big[\big|\bar{X}^{u,h}_t - \bar{X}^{u,h}_{t_m}\big|^2\Big] \leq \widehat{\kappa} (t-t_m) \leq \widehat{\kappa} h,
        \end{equation*}
        where we used the notation $t_m := \lfloor \frac{t}{h}\rfloor \cdot h$.

        \item[\textup{(ii)}] Recall $h_0 > 0$ defined in \textup{(i)}. Then, there exists $\widehat{\gamma} >0$ such that for any $h \in (0, h_0)$,
        \begin{equation*}
            \sup_{t \geq 0} \sup_{u \in I} \mathbb{E} \Big[\big|X^u_t - \bar{X}^{u,h}_t\big|^2\Big] \leq \widehat{\gamma} h^{1 \wedge 2\rho}.
        \end{equation*}
    \end{itemize}

