body:
[Lemma 17 of arXiv:2609.03185, 'Uniqueness of tangent flows in free boundary flow'] Let $u$ be a solution to the linearized equation. There exist constants $0<\delta_1<\delta_2<1$ such that the following statements hold. \begin{enumerate} 
\item If $I(u,s+1)\geq e^{\delta_1}I(u,s),$ then $I(u,s+2)\geq e^{\delta_2}I(u,s+1).$ 
\item If, at some time $s$, the decomposition of $u$ into eigenfunctions of $L$ has no component in the zero eigenspace, then either $I(u,s+1)\geq e^{\delta_2}I(u,s)$ or $I(u,s-1)\geq e^{\delta_2}I(u,s).$ \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:mapping of arXiv:2412.04032, 'Cutoff for the mixing time of the Facilitated Exclusion Process'] For all $\eta\in \mathcal{E}_{N,K}$, for all $k,l\in \mathbb{T}_K$, set
\eq{eq:sigma_mapping}{\sigma^{(k,\eta)}_l = 2 - x_{k+l}(\eta) + x_{k+l-1}(\eta).}
Then, $\sigma^{(k,\eta)} \in \Gamma_{K,2K-N}$, and the map
\begin{equation} \Phi : 
\begin{cases} \mathbb{T}_{K} \times \mathcal{E}_{N,K} \to\mathbb{T}_{N}\times \Gamma_{K,2K-N} \\
 (k,\eta) \mapsto  (x_k(\eta), \sigma^{(k,\eta)})
\end{cases}
\end{equation}
is bijective. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Recursive bound for the MGF) of arXiv:2604.13149, 'The Distributional Tail of Worst--Case Quickselect'] For every \(n\ge 0\) and every \(\theta> 0\),
\begin{equation}
\psi_{n+1}(\theta)\le G_\theta\!\bigl(\psi_n(\theta)\bigr).
\end{equation}

[Definition degree_def of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] Consider an inner factor $\mathrm{IF}(k, s, \mathcal{I}, \mathcal{J})$ as in (equation general_term of the paper). Let $d(k, s)$ denote the number of off-diagonal factors in $\im \prod_{i=1}^{n_1(k, s)} G_{u_i v_i}$, not counting the $G$-factors containing a $q$-index. Further, let $\hat{d}(k,s, l)$ be the number of off-diagonal factors in $\prod_{j=1}^{\hat{n}_l(k,s)}  G_{\hat{u}_j \hat{v}_j} $. 
		We define the degrees $d$ and $\hat{d}$ of the whole term (equation general_term of the paper) as \begin{align*}
			d & := \sum_{k=1}^{\#_{\beta}} \sum_{s=1}^{r_k} d(k, s), \\
			\hat{d} & :=  \sum_{k=1}^{\#_{\beta}} \sum_{s=1}^{r_k} \sum_{l=1}^{n_2(k, s)} \hat{d}(k, s, l). 
		\end{align*}
		Let $d_q(j)$ denote the total number of times one of $u_i, v_i$ is a $q$-index and the other $i_j \in \mathcal{I}$. Further, let $r_{\sum} := \sum_{k=1}^{\#_{\beta}} r_k$, and let $\mathfrak{r}_1$ be the number of inner factors with $d = 0, n_1 = 1$, and let $\mathfrak{r}_2$ be the number of inner factors with $d = 0, n_1 \geq 2$ and let $\mathfrak{r}_3$ be the number of inner factors with $d > 0, n_1 \geq 2$. Finally, introduce $$\mathfrak{c} := \sum_{k=1}^{\#_{\beta}} \sum_{s=1}^{r_k} \sum_{l=1}^{n_2(k, s)} \max\{1, \hat{d}(k, s, l)\},$$ and let $$n_2^{(\mathrm{tot})} := \sum_{k=1}^{\#_{\beta}} \sum_{s=1}^{r_k} n_2(k, s).$$

[Lemma lem.block-moment-bounds of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Let
		\[
		R_k\coloneqq\max_{0\le s\le \Delta\tau_k}|X^\lambda(\tau_k+s)-X^\lambda(\tau_k)|\, .
		\]
		For every integer $r\ge1$, there exists $C=C(r,d,\Lambda,r_0)<\infty$ such that, for every $\lambda\in(0,1]$ and every $k\ge0$,
		\begin{equation}
			\widehat{\mathbb E}_0^\lambda[(\Delta\tau_k)^r]\le C \lambda^{-2r},\qquad \widehat{\mathbb E}_0^\lambda[R_k^r]\le C \lambda^{-r}\, .
		\end{equation}
		Consequently,
		\begin{equation}
			\widehat{\mathbb E}_0^\lambda|\Delta X_k^\lambda|^r\le C \lambda^{-r}\qquad\text{for }k\ge0\, ,
		\end{equation}
		and, for
		\[
		W_k=\Delta X_k^\lambda-\ell(\lambda)\Delta\tau_k\, ,
		\]
		\begin{equation}
			\widehat{\mathbb E}_0^\lambda|W_k|^r\le C \lambda^{-r}\qquad\text{for }k\ge0\, .
		\end{equation}

[Corollary 23 (Coupling two clusters with two bridges.) of arXiv:2604.21669, 'Discontinuous transition in 2D Potts:\\ II. order-order interface convergence'] There exist \(n_0\geq 1, c\in (0,+\infty)\), such that for any \(n\geq n_0\), there are random variables \(T,S_0, S_1,\dots, S_{T},V,\Upsilon\) and \(T', S_0',S_1',\dots,S_{T'}',V',\Upsilon'\) defined on a common space satisfying
	\begin{enumerate}
		\item \((\Upsilon,\Upsilon')\) has the law of \((\calC,\calC')\) under \(\Phi_n(\cdot \given v_R\in \calC,\, v_R'\in \calC')\);
		\item the start and end are ordered, \(S_0\cdot \rme_2 - S_0'\cdot \rme_2 \geq \scale_n \), \(V\cdot \rme_2- V' \cdot \rme_2 \geq \scale_n \), and close to \(v_L,v_R,v_L',v_R'\): with probability \(1\),
		\begin{equation*}
			\max(\norm{v_L-S_0}_{\infty},\norm{v_L'-S_0'}_{\infty},\norm{v_R-V}_{\infty},\norm{v_R'-V'}_{\infty}) \leq \ln^{111}(n);
		\end{equation*}
		\item conditionally on \((S_0,S_0',V,V')\), \((S_0,\dots,S_{T})\) and \((S_0',\dots, S_{T'}')\) have law of two independent bridges, \(\OZwalk^{S_0,V}\otimes \OZwalk^{S_0',V'}\), conditioned on non-intersection of their diamond-envelop, defined in~\eqref{eq:def:diamond_envelop}: \(\DiaEnv(S_0,\dots,S_T)\cap \DiaEnv(S_{0}',\dots,S_{T'}') = \varnothing\);
		\item with probability \(1-o_n(1)\), \(\Upsilon\subset (S_0+\bcone)\cup (\DiaEnv(S_0,\dots,S_T))\cup (V+\fcone)\), and \(\Upsilon'\subset (S_0'+\bcone)\cup (\DiaEnv(S_0',\dots,S_{T'}'))\cup (V'+\fcone)\).
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:T1-0 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Given that there is a handover at time $0$, the time to the next handover is defined as  

\begin{equation}
T:=\inf\left\{s>0: \forall t\in (0,s], {\mathcal H }\left(S_t \right)=0, \text{ but } {\mathcal H }\left(\overline{S_s}\right)= 2\right\},

\end{equation}

which is equivalent to $T_1(0)$ under the handover Palm probability distribution.

[Theorem Thm-(u P)-long-time of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let the conditions of Theorem (Thm-(u P)-local of the paper) hold and
		$$\theta\in\left(\frac{d}{2}+p,{s-\max \{3\zeta,1\}}\right).$$
		\begin{enumerate}[label={\bf{(\arabic*)}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item $($\textbf{Global regularity and continuous dependence on initial data}$)$  Under (Hypo-DNI-1 of the paper), the Cauchy problem (equation Target problem (u P) damp of the paper) admits a global $H_{\rm div}^s$ solution. For $V\in\mathscr{V}$  as specified in (Hypo-DNI-1 of the paper), we have
			\begin{equation}
				\mathbb{E} \left[V(\|u(t)\|_{H^s}^2)\Big|\mathcal{F}_0\right]  
				\leq \Big(V(\|u_0\|^2_{H^s})+\mathscr{G}_2t\Big) {\rm e}^{\mathscr{G}_1t},
				\quad t>0.
			\end{equation}
			Moreover, 
			if $\{u_{0,m}\}_{m\ge1}$ are $\mathcal{F}_0$-measurable $H_{\rm div}^s$-valued random variables such that 
			\begin{equation}
				\sup_{m\ge1}\|u_{0,m}\|_{H^s}\le R\quad \text{for some}\  R>0 \quad  \text{and}\quad  \lim_{m\to\infty}\|u_{0,m}-u_0\|_{H^{\theta}}=0 \quad{\mathbb P}\text{-}{\rm a.s.},
			\end{equation}
			then the corresponding sequence of solutions $\{u_{m}\}_{m\ge1}$ with $u_m|_{t=0}=u_{0,m}$ satisfies
			\begin{equation}
				\lim_{m\to\infty}
				\mathbb{E} \left[1\land \|u_{m}(t)-u(t)\|^2_{H^{\theta}}\Big|\mathcal{F}_0\right]=0, \qquad t>0.
			\end{equation}

			\item  $($\textbf{Uniform-in-time estimate and invariant probability measure}$)$ If (Hypo-DNI-1 of the paper) is strengthened to (Hypo-DNI-2 of the paper), then $u$ satisfies 
			\begin{equation}
				\mathbb{E}\left[V(\|u(t)\|_{H^s}^2) \Big| \mathcal{F}_0\right]  
				\leq V(\|u_0\|^2_{H^s}), \qquad t\ge0.
			\end{equation}
			Moreover, on $\mathbb T^d$, there exists an
			invariant 
			measure $\mu$ 
			in the sense of Definition (IM definition of the paper) with $E=H_{\rm div}^s$. 

			\item $($\textbf{Uniqueness of invariant probability measure}$)$ Let $M=M_{\theta,d}>0$ be a constant satisfying $\|\cdot\|_{W^{p,\infty}}\leq M \|\cdot\|_{H^\theta}$ for $\theta>d/2+p$. If (Hypo-DNI-3 of the paper) holds, then  
			\begin{equation}
				\int_0^t\mathbb{E}  \left[V\left(\frac{\|u(t')\|^2_{W^{p,\infty}}}{M^2}\right)\Bigg|\mathcal{F}_0\right]{\,\rm{d}} t'
				\leq  \frac{V(\| u_0\|^2_{H^\theta})}{\mathscr{G}_3}\left(1-{\rm e}^{-\mathscr{G}_3t}\right),
				\quad t>0,
			\end{equation}
			As a consequence of (equation u Wlip -> 0 of the paper) and $V(0)=0$, it follows that
			the Dirac measure centered at $0$ is the \textbf{unique invariant probability measure} on both $\mathbb T^d$ and $\mathbb R^d$ when $\widetilde h(0)=0$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L:moments_as_tails of arXiv:2512.21977, 'Repeat times and a two-weight UST model'] If $X \geq 0$ is a random variable supported on $\mathbb{N}_0$, then
    \begin{align*}
        \mathbb{E}[X] &= \sum_{k=0}^\infty \mathbb{P}( X > k), \\
        \mathbb{E}[X^2] &= \sum_{k=0}^\infty (2k + 1) \mathbb{P}(X > k),
    \end{align*}

