[Proposition prop: ReductionWithoutSym of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Suppose that $\bM \sim \operatorname{Haar}(\sO^{n\times n})$. 
    Fix some $k\leq n$ and let $\bK  \sim \operatorname{Haar}(\mathfrak{m}^{k\times k})$. 
    Then, we have an equality in distribution of random $\sO$-modules: 
    \begin{align}
        \bbP\Bigl(\coker\bigl(\bM \bigr)  \in * \mid \rank_{q}\bigl(\bM \bigr) = n-k\Bigr) = \bbP\Bigl(\coker\bigl(\bK\bigr) \in * \Bigr).
    \end{align}

[Lemma 4 of arXiv:2609.02779, '2609.02779'] There exist $\rho_0,\mu,C,\lambda_0>0$ such that the following holds.  Let
$0<\rho\le\rho_0$, $0\le\lambda\le\lambda_0$, and let $a<b$ be real
numbers.  If $Z^\lambda:[a,b]\to T^*M$ is an orbit of $X_\lambda$ satisfying $Z^\lambda(s)\in B_{2\rho}(z_0)$
for every $s\in[a,b]$,
then for every $s\in[a,b]$,
\begin{equation}
 d_{T^*M}(Z^\lambda(s),z_0)
 \le
 C\rho\bigl(e^{-\mu(s-a)}+e^{-\mu(b-s)}\bigr)+C\lambda.
\end{equation}

[Thm 6 of arXiv:2606.00648, 'Asymptotic estimates for multiple point ranges of transient random walks on graphs'] Let $p \ge 1$. 
Assume that  $(U_1)$ holds and 
\[ \sum_{j \ge 1} \frac{f(j)^p}{j^{p-1}} (F_{\sup})^{j} < \infty.  \]
Then 
\begin{equation} 
\lim_{n \to \infty} E^x \left[ \left(\left( \frac{G_n (f)}{n} - C_{\sup}(f) \right)_{+}\right)^p \right] = 0 
\end{equation} 
and 
\begin{equation}   
\lim_{n \to \infty} E^x \left[ \left(\left( \frac{G_n (f)}{n} - C_{\inf}(f) \right)_{-}\right)^p \right] = 0. 
\end{equation}

