[Theorema them:counterexample_intro of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] There exists a stationary Gaussian process $(X_t)_{t \in \mathbb{R}} $ whose set of weak local Markov transforms is the set of all  the processes $(Y_t)_{t \in \mathbb{R}}$ satisfying:
		\begin{enumerate}
			\item The process $(Y_t)_{t \in \mathbb{R}}$ is centered Gaussian with constant variance function equal to $1$;
			\item The covariance function of $(Y_t)_{t \in \mathbb{R}}$ is non-negative;
			\item The process $(Y_t)_{t \in \mathbb{R}}$ is Markov.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem dimep of arXiv:2505.11721, 'Variational principles for Hausdorff and packing dimensions of fractal percolation on self'] Suppose that the vectors $p^{(t)}$, $t>0$, have positive entries. With probability~1, conditional on $\nu\neq 0$, one has 
\begin{align}
\dim_H(\mu)&=\inf_{T\in[1,\lambda]} \min (\delta_1(T),\delta_2(T))\\
\dim_P(\mu)&= \sup_{T\in[1,\lambda]} \min (\delta_1(T),\delta_2(T)),
\end{align}
where for $T>0$, 
\begin{align*}
\delta_1(T)&=T^{-1} \int_0^{\widetilde {g_s(T)}}H(W^{(t)})\,\mathrm{d}t,\\
\delta_2(T)&=T^{-1}\min_{g_1(T)\le T'\le g_s(T)}\int_0^{T'}H(W^{(t)})\,\mathrm{d}t+\int_{T'}^{g_s(T)}h(\Pi^{D(T)}_{r_t}H(W^{(t)}))\,\mathrm{d}t,
\end{align*}
$r_t$ being the index $r$ such that $g_{r-1}(T)<t\le g_r(T)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[OPEN PROBLEM - not a proved fact. Stated in arXiv:2608.26628 (problem environment).] Let $L_x=\{z : z \leq_K^+ x\}$ and $U_x=\{z : z \geq_K x\}$. Are the following true?
 \begin{enumerate}
 \item[(1)] $L_x$ is countable iff $\liminf_{n\to\infty}(K(x\upharpoonright n)-K(n))<\infty$;
 \item[(2)] $U_x$ is countable iff $\liminf_{n\to\infty}(K(n)+n-K(x\upharpoonright n))<\infty$.
 \end{enumerate} (Verbatim from the paper's TeX; symbols are the source paper's. Stated as open/conjectural; no resolution of it was found in the paper's own text by the rules of problem_index.py - a paper may still prove special cases of a conjecture it states.)

[Lem 15 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. If $\phi$ is differentiable at $x\in\Omega$ and there exists $\lambda>0$ such that
	\begin{align*}
		|p-D\phi(x)|\leqslant \lambda|y-x|,\qquad\forall y\in\Omega, p\in D^+\phi(y).
	\end{align*}
	Then the function
	\begin{align*}
		\psi(y)=\phi(x)+D\phi(x)\cdot(y-x)-\frac{\lambda}{2}|y-x|^2,\qquad y\in\Omega,
	\end{align*}
	is of class $C^{\infty}$ and touches $\phi$ from below at $x$ in $\Omega$.

[Lemma 61 (Flow $\Psi_{\beta}$) of arXiv:2608.29086, '2608.29086'] Given $M \subset H_0$, consistent $\beta \in C^1(M)$, and $abc \in Tri(M)$. Define the normal edges of $abc$ by
\begin{equation*}
ab \text{ is a normal edge of } abc \text{ if } |\beta(ab)| \geq  |\beta(bc)|,\  |\beta(ca)|.
\end{equation*}
Then, a flow $\Psi_{\beta} \in FLOW(M)$ is obtained by connecting triangles to adjacent triangles
\begin{equation*}
\text{through common edges that are not normal edges}. 
\end{equation*}
$\Psi_{\beta}$ is called the \textit{flow on $M$ defined by $\beta$}.

[Theorem 23 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $1< p<\infty$ and $\max\{1,p-1\}<q<\infty$.
    Assume that $|F|\in L^{\frac{pq}{2}}_{\loc}(\Omega_T)$ and that $u\in  L^\frac{pq}{2}_{\loc}(0,T;W^{1,\frac{pq}{2}}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{p_weak_sol}
 for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$.
    \begin{itemize}
    \item[(i)] If $1< q< 2$, then for $1< q \le q^* <\tfrac{2q}{2-q}$, then there exists a constant $c=c(n,p,q,q^*,L)$ such that 
    \[
    \biggl( \fint_{I } \frac{|u(x,t)-u_{I}(x)|^{q^*}}{|I|^\frac{q^*}{2}}\,dt \biggr)^\frac{1}{q^*}
    \le c\biggl( \fint_{I}  g(x,t)^q\,dt\biggr)^\frac{1}{q}
    \]
    for every parabolic cylinder $Q=Q_r=B\times I$ such that $2Q\Subset \Om_T$ and for almost every $x\in B$,
where $g$ is as in \eqref{p_time_grad}.
    \item[(ii)] If $q=2$, then there exists a constant $c=c(n,p,L)$ such that
    \[
    \fint_I\exp\left(\left(
   \frac{|u(x,t)-u_{I}(x)|}{\displaystyle c|I|^\frac{1}{2}\left( \fint_{I}g(x,t)^{2} \,dt\right)^{\frac{1}{2}}}\right)^{2}\right)\,dt\le c
    \]
    for every parabolic cylinder $Q=Q_r=B\times I$ such that $2Q\Subset \Om_T$ and for almost every $x\in B$,
where $g$ is as in \eqref{p_time_grad}.
    \item[(iii)] If $q>2$, then there exists a constant $c=c(n,p,q,L)$ such that
    \[
    \esssup_{t\in I}\frac{|u(x,t)-u_{I}(x)|}{|I|^\frac{1}{2}}
    \le c\left( \fint_{I} g(x,t)^q\,dt\right)^\frac{1}{q}
    \]
    for every parabolic cylinder $Q=Q_r=B\times I$ such that $2Q\Subset \Om_T$ and for almost every $x\in B$,
where $g$ is as in \eqref{p_time_grad}.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

