[Proposition prop stability of arXiv:2512.13200, 'Martingales on a Euclidean manifold with a boundary and reflected BSDEs in non-convex doma'] {Let Assumption (ass:brownian-case of the paper) hold} and let $(Y,Z,K)$ (resp. $(Y',Z',K')$) be a solution of the reflected BSDE (equation eq reflected bsde of the paper) with the terminal condition $\xi$ (resp. $\xi'$) and the generator $f$ (resp. $f'$). 
    We assume that
    \begin{itemize}
        \item Assumption (ass:brownian-case of the paper) holds with $f'$ in place of $f$,
        \item there exists a progressively measurable process $(\alpha_t)_{t \in [0,T]}$ such that $1+\1_{C_{f,z} >0}|Z'_t|+|f'(t,Y'_t,Z'_t)| \le \alpha_t$ for all $t \in [0,T]$,
        \item for all $\lambda >0$,
        \begin{equation}

            \esp{e^{\lambda \int_0^T \alpha_s\mathrm{d} s}} <+\infty.
        \end{equation}
    \end{itemize}
     We set $\Gamma^{\lambda}_t = e^{\lambda \int_0^t \alpha_s\mathrm{d} s}$ for all $\lambda>0$. Then, there exists $C>0$ such that, for any $\eta>0$, there exists a constant $\lambda_0 \ge 0$, only depending on $\eta$, $\bar{\mathcal{D}}$, $T$, $C_{f,y}$ and $C_{f,z}$, such that, for all $\lambda \ge \lambda_0$, we have
    \begin{align}
        &\esp{\sup_{t\in[0,T]}\Gamma^{\lambda}_t \Psi(Y_t,Y'_t)} +\esp{\int_0^T\Gamma^{\lambda}_t|Z_t - R(\theta(Y_t,Y'_t))Z'_t|^2 \mathrm{d} t }\\ \le&  C\esp{\Gamma^{\lambda}_T \Psi(\xi,\xi')}
        + \eta\esp{\int_0^T \Gamma^{\lambda}_t |f(t,Y'_t,Z'_t)-f'(t,Y'_t,Z'_t)|^2 \mathrm{d} t }     \nonumber  
    \end{align}
    and







    \begin{align}
        & \esp{\int_0^T|Z_t - Z'_t|^2 \mathrm{d} t }\\
        \le& C\esp{\Gamma^{\lambda}_T \Psi(\xi,\xi')
        + \int_0^T \Gamma^{\lambda}_t |f(t,Y'_t,Z'_t)-f'(t,Y'_t,Z'_t)|^2 \mathrm{d} t } \nonumber\\
        &+ \nonumber C(1+\||f'(.,0,0)|^{1/2}\|_{\ensuremath{\mathscr{B}^{2}}}^2)\esp{\Gamma^{\lambda}_T \Psi(\xi,\xi')
        + \int_0^T \Gamma^{\lambda}_t |f(t,Y'_t,Z'_t)-f'(t,Y'_t,Z'_t)|^2 \mathrm{d} t }^\frac12.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

