[Lemma Psi_bounds of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] Let $H(t)$ be the interpolation (equation interpolation_step_1 of the paper), (equation diagonal_var_interpolation_eq of the paper), or (equation gaussian_to_gaussian_interpolating_flow of the paper), and recall $\Psi$ from (equation Psi_def of the paper) and $\eta, \tilde{\eta}$ from (equation eta_defs of the paper). Then, uniformly for $t \in {\mathbb R}_{\geq 0}$,
	\begin{align}
		\Psi(t) \prec \frac{1}{N \tilde{\eta}}.

	\end{align}
		Further, for any (large) $D > 0$ it holds uniformly for $t \in {\mathbb R}^+$ that, \begin{equation}
		\sup_{\substack{E \in [E_L, -2 + N^{-2/3 + \epsilon}] \\
			u,v \in \mathbb{B}}} \max(\abs{G_{uv}(t, E + \ii \eta)}, \abs{G_{uv}(t, E + \ii \tilde{{\eta}})}) \leq 1, 

	\end{equation} with probability $\geq 1 - N^{-D}$ for $N \geq N_0(D, H)$.

[Corollary cor:HKUB-collisions of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $A>0$, $k\ge 3$, $\delta\in (0,\frac14)$, $0<t_0<T$, and $r\ge 1$. Then, for some $C>0$, and all $\mathbf x\in\mathbb{Z}^k$, $N\in \mathbb{N}$, $|\beta|\le AN^{-1/8}$ and $t\in[t_0,TN]$,
\begin{equation}
\mathbf P_\mathbf x^{(\beta,k)}
(|R_t^i-R_t^j|\le r,\,
|R_t^\ell-R_t^m|\le r)
\le C t^{-1+\delta}\; \text{,}\;\;
\end{equation}
for all distinct unordered pairs $\{i,j\}\neq\{\ell,m\}$ in $\{1,\ldots,k\}$.
Consequently,
\begin{equation}
\int_0^{TN}
\mathbf P_\mathbf x^{(\beta,k)}(
|R_t^i-R_t^j|\le r,\,
|R_t^\ell-R_t^m|\le r
)   
\,{\rm d} t
\le C N^\delta\; \text{.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-Ward of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Let $\mathcal A$ be a Hermitian matrix. Define its resolvent as $R(z):=(\mathcal A-z)^{-1}$ for any $z= E+ \mathrm{i} \eta\in \mathbb{C}_+$. Then, we have 
    \begin{equation}
    \begin{split}
\sum_x \overline {R_{xy'}}  R_{xy} = \frac{R_{y'y}-\overline{R_{yy'}}}{2\mathrm{i} \eta},\quad
\sum_x \overline {R_{y'x}}  R_{yx} = \frac{R_{yy'}-\overline{R_{y'y}}}{2\mathrm{i} \eta}.
\end{split}
\end{equation}
As a special case, if $y=y'$, we have
\begin{equation}
\sum_x |R_{xy}|^2 =\sum_x |R_{yx}|^2 = \frac{\im R_{yy}}{ \eta}.
\end{equation}

