[Lemma 2 of arXiv:2608.26288, 'Muon with Finite Newton--Schulz: The Smoothing Benefit in Nonsmooth Nonconvex Optimization'] Under~\cref{ass:general-spectral-link}, for every $C>0$ the function $\widetilde\Phi_{h,C}$ is convex and continuously differentiable on all of $\R^{m\times n}$, and its gradient is
\begin{equation}
  \nabla\widetilde\Phi_{h,C}(M) = \calH_h(M/C).

\end{equation}

[Definition 1 (Voter model) of arXiv:2609.01143, 'The voter model on the hyperbolic graph'] Let $V$ be finite and let $Q=(Q_{ij})_{i,j\in V}$ be an irreducible Markov generator, with $q(i):=-Q_{ii}$.  For $\xi\in\{0,1\}^V$ and $i,j\in V$, let $\xi^{i\leftarrow j}$ be obtained from $\xi$ by replacing the opinion at $i$ by that at $j$.  The voter model $(\xi_t)_{t\geq0}$ with copying kernel $Q$ is the Markov process on $\{0,1\}^V$ with generator
\begin{equation}
\cL f(\xi) = \sum_{i\neq j}Q_{ij} \left(f(\xi^{i\leftarrow j})-f(\xi)\right).             
\end{equation}
Thus site $i$ updates at rate $q(i)$ and, when it updates, copies $j$ with probability $Q_{ij}/q(i)$.

[Lemma 13 of arXiv:2606.01742, 'Large deviation principles for SPDEs with locally Lipschitz coefficients'] Assume that Hypotheses \ref{cond-initial}, \ref{cond-dif}  and  \ref{3} hold. If $L_{\sigma}>0$, then
\begin{align*}
\mathbb{P}\left\{\left|u_{N+1}^{ \varepsilon,h_\varepsilon}(t,x)\right|\geq e^N\right\}\leq \exp\left(-\frac{N^{\frac{3}{2}}}{2^{8}\e L_{\sigma}^2t^{\frac{1}{2}}}\right)
\end{align*}
uniformly for all $t>0$, $x\in\R$, $\e>0$,
$$N\geq \max\left\{\left(\max(2^{13}\e^2L_{\sigma}^4t,2^{11}\e^2L_{b}t)\right),4\left[\log \left(4\left(\|u_0\|_{L^\infty(\R)}+1\right)\right)+64M^4L_{\sigma}^4t\right]\right\},$$
and for every $M\geq L_b^{1/4}L_{\sigma}^{-1}$.
 If $\sigma\in L^{\infty}(\R_+\times\R)$, then
\begin{align*}
\mathbb{P}\left\{\left|u_{N+1}^{ \varepsilon,h_\varepsilon}(t,x)\right|\geq e^N\right\}\leq \exp\left(-\frac{e^{2N-4L_bt}}{8\left(4\e+1\right)\left(\|u_0\|_{L^\infty(\R)}+\|\sigma\|_{L^\infty(\R+\times\R)}t^{\frac{1}{4}}+1\right)^2}\right)
\end{align*}
uniformly for all $t>0$, $x\in\R$, $\e>0$ and
\begin{align*}
N\geq\frac{1}{2}+\frac{3}{2}\log2+2L_bt+\frac{1}{2}\log(4\e+1)+\log\left(\|u_0\|_{L^\infty(\R)}+\|\sigma\|_{L^\infty(\R+\times\R)}t^{\frac{1}{4}}+1\right).
\end{align*}

