body:
[Proposition 4 (Properties of the infimal convolution) of arXiv:2604.02312, 'A weak transport approach to the Schrödinger--Bass bridge'] Let $V$, $W$ be proper standard weak transport problems and assume that $(C_V,W)$ satisfies \Cref{aspt:coercivity} for some $r \in [1,p]$.
    Define ${C_{V\Box W}:\mathcal X\times\cP_p(\mathcal Z)\to\R\cup\{+\infty\}}$ by
    \begin{equation}
        C_{V \Box W}(x,\eta) := \inf_{\rho \in \cP_p(\mathcal Y)} \bigl\{ C_V(x,\rho) + W(\rho,\eta) \bigr\}.
    \end{equation}
    Then $C_{V\Box W}$ is a standard weak transport cost, and the infimum in \eqref{eq:CVBoxW} is attained for every $(x,\eta)\in \mathcal X\times\cP_p(\mathcal Z)$. 
    If, in addition, $(C_V,W)$ satisfies the continuity assumption~\Cref{aspt:continuity}, then $C_{V\Box W}$ is continuous on $\mathcal X\times\cP_p(\mathcal Z)$.

    Moreover, for every $\mu \in \cP_p(\mathcal X)$ and
    $\nu \in \cP_p(\mathcal Z)$,
    \begin{equation} 
        V \Box W(\mu,\nu)
        =
        \inf_{\pi \in \cpl(\mu,\nu)} \int_{\mathcal X} C_{V \Box W}(x,\pi_x)\, \mu(\rmd x).
    \end{equation}
    Finally, for every $f\in L_{b,p}(\mathcal Z)$,
    \begin{equation} 
        f^{C_{V\Box W}}
        \ge 
        \bigl(-f^{C_W}\bigr)^{C_V},
    \end{equation}
    and
    \begin{equation} 
        V \Box W(\mu,\nu)
        =
        \sup_{f \in L_{b,p}(\mathcal Z)} \left\{ \int_{\mathcal Z} f(z)\,\nu(\rmd z) + \int_{\mathcal X} \bigl(-f^{C_W}\bigr)^{C_V}(x)\,\mu(\rmd x) \right\}.
    \end{equation}

