[Lem l:Dtmoment2 of arXiv:2411.10586, 'A convergence framework for Airy$_\beta$ line ensemble\\ via pole evolution'] There exists $C>0$ such that (for any $n\in \mathbb{N}$ and $t\in{\mathbb R}$) the following holds:
\begin{enumerate}
\item For any $0<u=\OO(n^{2/3})$, it holds that \begin{align}
    \mathbb{P}(\widetilde \lambda^{(n)}_1(t)> u)\leq Ce^{-u^{3/4}/C}.
\end{align}
\item 
For any $q\geq 1$ and $w=a+\mathrm{i} b$ with $|w|=\OO(n^{2/3})$,
\begin{align}
    \mathbb{E}[|\Delta^{(n)}_t(w)+\OO(n^{-1/3}|w|)|^q]\leq \frac{(Cq)^{2q}}{b^q}, 
\end{align}
 and when $Cq^{1/2}/\sqrt{a} \le b \le a$, 
\begin{align}
    \mathbb{E}[|\Delta^{(n)}_t(w)+\OO(n^{-1/3}|w|)|^{2q}]\leq \frac{(Cq)^{2q}}{b^{4q}a^{q}} + \frac{(Cq)^q}{(a b)^q } +\frac{(Cq)^{2q}}{ n^{2q/3}a^q}.
\end{align}
\end{enumerate}

