[Lemma 1 of arXiv:2605.24445, 'Matrix concentration inequalities for time-inhomogeneous Markov chains'] \label[lemma]{lem:W_bounds_curv}
Let \(s\ge 0\),  \(\phi \in [-\pi/2,\pi/2]\), and \(j\ge 1\). Then,
\begin{align*}
\norminf{W_j}&\le \exp\!\Big(\frac{sLD}{2}\Big),
\qquad
\Lip(W_j)^\op\le \frac{s}{2}\exp\!\Big(\frac{sLD}{2}\Big)\,L,
\qquad
\Lip(W_j^\ast)^\op=\Lip(W_j)^\op,\\
\Lip(\Theta_{n,1})^\op &\le s\exp\!\Big(sLD\Big)\,L.
\end{align*}

[Proposition 3 of arXiv:2609.03098, 'Standing waves for Schr\"odinger equations with Kato class potentials and $L^\infty$-bound'] For any $1\le p\le \infty$, the following inequalities hold \footnote{ \ We will write $A(u)\lesssim B(u)$, where $A, B$ are non-negative functions dependent on the argument $u$, if there is a constant $C\ge 0$ such that $A(u)\le CB(u)$ for all $u$.}
			\begin{align}
				& \|Q_{-}u\|_{L^{p}}\lesssim \|u\|_{L^{p}},\quad \|Pu\|_{L^{p}}\lesssim \|u\|_{L^{p}},\\
				& \|Q_{+}^{d}u\|_{L^{p}} \lesssim \|u\|_{L^{p}}, \quad \|Q_{+}^{e}u\|_{L^{p}} \lesssim \|u\|_{L^{p}}, 
			\end{align}
			for all $u\in L^{2}(\R^{N})\cap L^{p}(\R^{N})$.

