[Definition def:G-Wass of arXiv:2608.13716, 'Graph Causal Optimal Transport \\ and Wasserstein Distances'] Let $G$ be a directed graph and $p \geq 1$. The $p$\textsuperscript{th} order \emph{$G$-causal Wasserstein distance} between $\mu, \nu \in \Gpprobabilities{p}{\mathcal{X}}$ is given by
    \begin{equation}
        W_{G,p}(\mu, \nu)^p \coloneq \inf_{\pi \in \Gbicouplings{\mu}{\nu}} \int d_{\mathcal{X}}(x,y)^p \, d\pi(x,y).
    \end{equation}

[Prop 32 of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] For any $M>0$, let $\{h^{\varepsilon}; 0<\varepsilon<1\}\subset \mathcal{A}_M$. Then
\begin{align*}
        \lim_{\varepsilon\rightarrow 0}\bigg\Vert \mathcal{G}^{\varepsilon}\Big(W(\cdot)+\frac{1}{\sqrt{\varepsilon}}\int^{\cdot}_0h^{\varepsilon}(s)\dd s\Big)-\mathcal{G}^0\Big(\int^{\cdot}_0h^{\varepsilon}(s)\dd s\Big)\bigg\Vert _{L^1(0,T;L^1(\mathbb{T}^N))}
    =0,
    \end{align*}
    in probability.

[Lemma 10 of arXiv:2606.31500, 'Non-Uniqueness for Nonlinear Fokker--Planck Equations and Their Associated Distribution-De'] Under Assumption~\ref{def:ass}, it holds that
\begin{align}
\|A(\rho)&-A(\tilde{\rho})\|_{C_{t,x}^1}
\lesssim
   \|\rho- \tilde{\rho} \|_{C_{t,x}^1}+\|\rho- \tilde{\rho} \|_{C_{t,x}^0}(\|\rho \|_{C_{t,x}^1}+\|\tilde\rho \|_{C_{t,x}^1}),
\notag\\
\|A(\rho)\|_{C_{t,x}^0}
&\lesssim 1,
\notag\ \
\|A(\rho)\|_{C_{t,x}^1}
\lesssim 1+\|\rho\|_{C_{t,x}^1},\ \ \|A(\rho)\|_{C_{t,x}^2}
\lesssim 1+\|\rho\|_{C_{t,x}^1}^2+\|\rho\|_{C_{t,x}^2}.
\notag
\end{align}

