Assume ((drift of the paper)) to ((simple of the paper)). Then, the functions $(h_\alpha)_{\alpha \in [\alpha^*, \alpha^{**}]}$ are harmonic and are given by the following formulae
\begin{itemize}
\item For $\alpha \in (\alpha^{*}, \alpha^{**})$, taking $(a_0, b_0) = (x(\alpha), y(\alpha))$, we have
\begin{equation}
h_{\alpha} : z_0 \longmapsto \sum_{m=-\infty}^{+\infty} \kappa_m(\alpha)e^{z_0\cdot (a_{m}, b_{m})}
\end{equation}

where $\kappa_0(\alpha) = 1$ and
\begin{equation}
\kappa_m(\alpha)=\left\{
    \begin{array}{ll}
        & (-1)^m\left[\prod_{k=0}^{\lfloor \frac{m}{2} \rfloor-1} \frac{\frac{\gamma_1}{\gamma_2}(a_{2k+1}, b_{2k+1})}{\frac{\gamma_1}{\gamma_2}(a_{2k+2}, b_{2k+2})}\right]\frac{\gamma_2(a_0, b_0)}{\gamma_2(a_{m}, b_{m})} \quad\textnormal{if}\; m > 0\\
	& (-1)^m\left[\prod_{k=0}^{\lfloor \frac{-m}{2} \rfloor-1} \frac{\frac{\gamma_2}{\gamma_1}(a_{-2k-1}, b_{-2k-1})}{\frac{\gamma_2}{\gamma_1}(a_{-2k-2}, b_{-2k-2})}\right]  \frac{\gamma_1(a_0, b_0)}{\gamma_1(a_{m}, b_{m})} \quad\textnormal{if}\; m < 0
    \end{array}
\right.
\end{equation}
(with the convention $\Pi_{k=0}^{-1} = 1$).

\item For $\alpha = \alpha^*$,
\begin{itemize}
    \item If $\frac{2}{r_{2} + 1} < \mu_2$, then $\alpha^*= 0$ and $h_{0} : z_0 \longmapsto \partial_\alpha\left[h_\alpha(z_0)\right]_{\alpha=0^+}$.
    \item If $\frac{2}{r_{2} + 1} > \mu_2$, then $\alpha^* > 0$ and taking $(a_0, b_0) = (x(\alpha^*), y(\alpha^*))$,
\begin{equation}
h_{\alpha^*} : z_0\longmapsto e^{z_0\cdot (a_{1}, b_{1})} + \sum_{m=2}^{+\infty}\widehat{\kappa}_m(\alpha^*)e^{z_0\cdot (a_{m}, b_{m})} 
\end{equation}
where 
$$
\widehat{\kappa}_m(\alpha^*)= (-1)^{m+1}\frac{\gamma_1(a_{1}, b_{1})}{\frac{\gamma_1}{\gamma_2}(a_{2}, b_{2})}\left[\prod_{k=1}^{\lfloor \frac{m}{2} \rfloor-1} \frac{\frac{\gamma_1}{\gamma_2}(a_{2k+1}, b_{2k+1})}{\frac{\gamma_1}{\gamma_2}(a_{2k+2}, b_{2k+2}}\right]\frac{1}{\gamma_2(a_{m}, b_{m})}.
$$

\item If $\frac{2}{r_{2} + 1} = \mu_2$, then $\alpha^*= 0$ and taking $(a_0, b_0) = (x(0), y(0))$,
\begin{equation}
h_{0} : z_0 \longmapsto 2e^{z_0\cdot (a_0, b_0)} + \sum_{m=-\infty}^{-1} \kappa_m(\alpha^*)e^{z_0\cdot (a_{m}, b_{m})} + \sum_{m=2}^{+\infty} \tilde\kappa_m(\alpha^*)e^{z_0\cdot (a_{m}, b_{m})}
\end{equation}
where 
$$
\tilde\kappa_m(\alpha^*)= (-1)^{m+1} \frac{\gamma_1(a_{1}, b_{1})}{\frac{\gamma_1}{\gamma_2}(a_{2}, b_{2})}\left[\prod_{k=1}^{\lfloor \frac{m}{2} \rfloor-1} \frac{\frac{\gamma_1}{\gamma_2}(a_{2k+1}, b_{2k+1})}{\frac{\gamma_1}{\gamma_2}(a_{2k+2}, b_{2k+2})}\right]\frac{1}{\gamma_2(a_{m}, b_{m})}.
$$
\end{itemize}
\item For $\alpha = \alpha^{**}$, symmetrical formulae hold replacing $r_1$ by $r_2$, $\mu_1$ by $\mu_2$ and $0$ by $\frac{\pi}{2}$.

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:KPS of arXiv:2412.01381, 'Ergodicity and mixing for locally monotone stochastic evolution equations'] Assume that $(P_t)_{t\ge 0}$ has the $e$-property and that there exists $z\in H$ such that for every bounded set $J$ and every $\delta>0$, we have
\begin{equation}
\inf_{x\in J}\liminf_{T\to\infty} Q_T(x,B(z,\delta))>0.
\end{equation}
Suppose further that for every $\varepsilon>0$ and every $x\in H$, there exists a bounded Borel set $K\subset H$ such that
\begin{equation}
\liminf_{T\to\infty} Q_T(x,K)>1-\varepsilon.
\end{equation}
Then there exists a unique invariant probability measure $\mu_\ast$ for $(P_t)_{t\ge 0}$ such that the semigroup $(P_t)_{t\ge 0}$ is weak$^\ast$-mean ergodic and the weak law of large numbers holds.

[Lemma 43 (Exponential decay of radii) of arXiv:2608.03575, '2608.03575'] Conditionally on \((G,\rho,\Theta)\), almost surely,
\begin{equation}
    \limsup_{n\to\infty}
    \frac{\log r(X_n)}{n}<0.
\end{equation}
In particular,
\begin{equation}
    \sum_{n=0}^{\infty}r(X_n)<\infty
\end{equation}
almost surely.

[Theorem prop:U_asy of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For the deformed Gaussian matrix $X$ in Definition (def:inhomo of the paper) and  under the assumptions (itm:B1 of the paper)-(itm:B2 of the paper) of Definition (mixingdef of the paper), with $n = \sum_{j=1}^s n_j$, $a=\|A_N\|_{\mathrm{op}}$, the following hold.
\begin{enumerate}[label=(\roman*)]
  \item  For all  $n_j\ge 1$, there exists a constant $C > 0$ such that
\begin{equation} 
\mathbb{E}\left[\prod_{j=1}^s \operatorname{Tr} \left(U_{n_j}\left(\frac{X}{2}\right)\right)\right]
\le (1 + a^n)(C n)^s \left\{e^{C \frac{n^{\frac{3}{2}}}{\sqrt{N}}} + (1\lor \frac{t_N}{n})^s e^{C \frac{n^2 t_N}{N}} + \Big((\frac{C n^2 t_N}{N})^{[\frac{n}{t_N}]}\land 1\Big) e^{C \frac{n^3}{N}}\right\}.
\end{equation}
  \item  If   $a \le 1 + O( N^{-\frac{1}{3}})$ and $t_N \ll n_j = O(N^{\frac{1}{3}})$, then
  \begin{equation}
   \mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \big(U_{n_j}\big(\frac{X}{2}\big)\big)\Big]
    = \mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \big( U_{n_j}\big(\frac{\widetilde{X}}{2}\big)\big)\Big]
    + o(n^s),
  \end{equation}
  where $\widetilde{X} =  \frac{1}{\sqrt{N}} W_{N}^{(\mathrm{G}\beta \mathrm{E})}+A_N$.
\end{enumerate}

