[Lemma lem-pointwise_conv of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] \begin{enumerate}
\item[(i)] There exists a set $C \subset [0,T]$ such that
\begin{enumerate}
\item[(c1)] the complement $ [0,T] \setminus C$ of $C$ is at most countable,
\item[(c2)] $\{0,T\}\subset  C$,
\item[(c3)] for every $t \in C$,
\begin{align}
\lim_{n \to \infty } {\overline{u}}_{n} (t)= \overline{u} (t) \mbox{ in } U^\prime, \; \mbox{  on $\overline{\Omega}$ }.
\end{align}
\end{enumerate}
\item[(ii)] For all $s,t \in [0,T]$ with $s \le t $ and  every $\psi  \inU$, we have on $\overline{\Omega}$,
\begin{align}
\lim_{n \to \infty } \int_{s}^{t} \ddual{V^\prime }{ \mathscr{A}_n {\overline{u}}_{n} (\sigma) }{ \psi }{V}{} \, \mathrm{d}\sigma
 =\int_{s}^{t} \ddual{V^\prime }{ \mathscr{A} \overline{u} (\sigma) }{ \psi }{V}{}\, \mathrm{d}\sigma , \quad    \\

 \lim_{n \to \infty }
 \int_{s}^{t} \ddual{V^\prime }{ B_n \bigl( {\overline{u}}_{n} (\sigma )  \bigr) }{ \psi }{V}{}  \, \mathrm{d}\sigma
= \int_{s}^{t} \ddual{V^\prime }{ B\bigl( \overline{u} (\sigma ) \bigr) }{\psi }{V}{}  \, \mathrm{d}\sigma .
\end{align}
\end{enumerate}

