\begin{align*}
    A(t,x) := \frac{1}{t} \int_0^t {\rm d}s \int_D {\rm d}z  \, p_s^D(x,z)\nu(z,D^c) = \int_{D^c}  \left[\frac{1}{t} \int_0^t \mathcal{J}(s,x,y) \,{\rm d}s \right] \mathrm{d}y.
