	 \begin{align} 
    &\hat{b}_k=0 \; (k\geq 0),\\ 
    & \hat{a}^2_{2m}=\frac{a^2_{2m}a^2_{2m+1}}{r^2_{2m-1}},\quad \hat{a}^2_{2m+1}=r^2_{2m+1},
\end{align}
where 
\begin{align}
	r_{2m+1}^2=a_{2m+2}^2+a_{2m+1}^2\prod\limits_{j=1}^{m}\frac{a_{2j-1}^2}{r_{2j-1}^2}.
\end{align}

