    \begin{equation}
        \be[|X_{t+\Delta}^\ve-X_t^\ve|^p]\leq C_{\kappa,p,s,T}(1+|x|^p+|y|^p)(\Delta^p+\Delta^{\frac{p}{\alpha}})
    \end{equation}

