[Lemma 13 of arXiv:2604.20631, 'The Ising Model on a Two-Community Stochastic Block Model'] Under assumptions \eqref{assump}, for every $\omega \in \Omega^*$ and $\sigma\in \mathcal{X}^n$,
\begin{align*}
    |\Delta_n(\sigma)| \leq \frac 32 n \rho_n,
    \end{align*}
 with $\rho_n \to 0$ as $n \to \infty$ is defined in \eqref{set_concentration}.

[Corollary 18 (\textsf{Four-moment-influence bound on Rademacher chaos}) of arXiv:2608.12451, '2608.12451'] Let $F\in L^4(\PP)$ belong to the $d$-th Rademacher chaos
and satisfy  the lattice condition \eqref{cond_La}
with shift $\theta>0$.  
Put
\noi
\begin{align}
 \mathfrak d(F)
 :=|\cR(F)|
 + (2d)!\binom{2d}{d}m_2(F)\cM(F)
\notag
\end{align}
with $\cM(F)$ the maximal influence as in \eqref{Rad_inf}.
Then, with   $c_\theta:= (1-e^{-\theta})/\theta$,

\noi
\begin{align}
 &\dTV\bigl( F+\theta,P_\theta\bigr)
  \leq c_\theta\bigg[
 |m_2(F)-\theta|
 +\frac{2d-1}{2d}\sqrt{\mathfrak{d}(F)}
 +\frac23\sqrt{m_2(F)\mathfrak{d}(F)}
 +2\mathfrak{d}(F)
 \bigg].
\notag\end{align}

