\begin{equation}  
\frac{  G_{\mathcal A} (x,y) }{\pi(y)}  =  \frac{ G_{\mathcal A}(y,x) }{\pi(x)}  .
\end{equation} 
Furthermore, for any function $f:\mathcal V\mathcal G \to \mathbbm R$ which vanishes outside of a finite set,
\begin{equation}  
\sum_{x,y\in\mathcal V\mathcal G} f(x) f(y) \frac{G_{\mathcal A}(x,y)}{\pi(y)} \geq 0.
\end{equation}

[Defn def: D of arXiv:2509.26254, '$K$-Branching Random Walk with Noisy Selection: \\ \Large Large Population Limits and Phas'] A function $g: \mathbb{R} \to \mathbb{R}_+ \cup \{-\infty\}$ belongs to the class $\mathcal{D}$ if and only if 
\begin{itemize}
\item[(a)] $g$ admits a left limit and a right limit for all $x \in \mathbb{R}$, and
\item[(b)] $g$ has bounded support $\mbox{Supp}(g) = \{x \in \mathbb{R} :\: g(x) \neq -\infty \}$, in which case we define $L(g) \leq U(g)$ such that $[L(g), U(g)]$ is the smallest interval containing $\mbox{Supp}(g)$. We call $L(g)$ and $U(g)$ the {\it lower edge} and {\it upper edge} of $g$ respectively.
\end{itemize}
A function $g: \mathbb{R} \to \mathbb{R}_+ \cup \{-\infty\}$ belongs to the class $\mathcal{C}$ if and only if $g \in \mathcal{D}$ and 
\begin{itemize}
\item[(c)] $g$ is concave on its support.
\end{itemize}

