[Definition 30 (Wick product) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] For $q\ge1$ and $h_1,\ldots,h_q\in\cH$, define
\begin{equation}

  \wick{W(h_1)\cdots W(h_q)}
  :=\left.
    \partial_{t_1}\cdots\partial_{t_q}
    \mathcal E_W\!\left(\sum_{\nu=1}^q t_\nu h_\nu\right)
  \right|_{t=0},
\end{equation}
where the derivative is taken in $L^2(\Omega)$.  For $q=0$, the Wick product
is defined to be $1$.

[Definition def:split_event of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] Define the event
  \begin{equation}
    \mathcal{S} = \mathcal{S}_1 \cap \mathcal{S}_2 \cap \mathcal{S}_3,
  \end{equation}
  where
  \begin{equation}
  \begin{gathered}
    \mathcal{S}_1 = \bigl\{\text{no priority-1 particle reaches } M_1 \text{ during }[0,T]\bigr\},\\
    \mathcal{S}_2 = \bigl\{\text{no priority-2 particle reaches } M_2 \text{ during }[0,T]\bigr\},\\
    \mathcal{S}_3 = \bigl\{\text{no priority-3 particle enters }S_1 \cup S_2\text{ during }[0,T]\bigr\}.        
  \end{gathered}
  \end{equation}

[Lem balanced-rip of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] One has \begin{subequations}
\begin{align}
\mathsf{X}\ge{} & \Bigl(\bigl[(\alpha+\beta)^{2}-4\alpha\beta\bigr]t\nonumber \\[-1mm]
 & \quad-\bigl[(\alpha+\beta)^{2}-2\alpha\beta\bigr](2-t)\delta\Bigr)\mathsf{H}^{2}\nonumber \\[-1mm]
 & -2\alpha\beta(2-t)\delta\mathsf{T}^{2},\\
\mathsf{Y}\ge{} & t[t-(2-t)\delta]\mathsf{H}^{2},\qquad0<t<1,\\
\mathsf{Z}\ge{} & [t(2-t)-(t^{2}-2t+2)\delta]\mathsf{H}^{2}\nonumber \\[-1mm]
 & -2(t-1)\delta\mathsf{T}^{2},\qquad1\le t<4/3.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

