[Proposition 18 of arXiv:2511.09930, 'Martingale dimensions for a class of metric measure spaces'] There exist positive constants $c_1$ and $c_2$ such that
\begin{equation}
2\cE(f,f)=\nu_f(U)\ge c_1\Bigl(\osc_{U}f\Bigr)^2=c_1\Bigl(\osc_{K}f\Bigr)^2\quad\text{for any $f\in\cF$}
\end{equation}
and
\begin{equation}
\nu_h(U)\le c_2\Bigl(\osc_{U}h\Bigr)^2\quad\text{for any $h\in\cH_U$}.
\end{equation}

[Definition def:cip-lip of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] A logic $L$ with a language $\mathscr{L}$ is said to enjoy \emph{Lyndon interpolation property (LIP)}
  if for every $\varphi, \psi \in \mathscr{L}$ such that $\varphi \to \psi \in L$,
  there is $\chi \in \mathscr{L}$ that satisfies the following conditions:
  \begin{enumerate}
    \item $\mathrm{V}^\bullet(\chi) \subseteq \mathrm{V}^\bullet(\varphi) \cap \mathrm{V}^\bullet(\psi)$, for each $\bullet \in \set{+, -}$;
    \item $\set{ \varphi \to \chi, \chi \to \psi } \subseteq L$.
  \end{enumerate}
  A logic $L$ is said to enjoy \emph{Craig interpolation property (CIP)} if it satisfies the above,
  but with the first condition of $\chi$ replaced by $\mathrm{V}(\chi) \subseteq \mathrm{V}(\varphi) \cap \mathrm{V}(\psi)$.

[Lemma 6 (Sparse families: Bernoulli selection) of arXiv:2607.12263, 'Random sets are close to low-discrepancy sets'] Fix \(0 < \delta < 1\). Let \(A_1,\ldots,A_D\) be an \(s\)-sparse family of subsets of $[N]$. Assume that $N$ has the form $N=n2^k$ for some positive integers $n$ and $k$. Let \(S \subset [N]\) be a random subset obtained by selecting each point independently with probability $2^{-k}$. Then there is a randomized algorithm that produces an $n$-element subset $Q\subset [N]$ such that
\begin{equation}
\E \abs{Q\cap S} \ge n(1-\delta)-\sqrt n
\end{equation}
and
\begin{equation}
	\abs*{ \frac{\abs{A_j \cap Q}}{n} - \frac{\abs{A_j}}{N}} 
	\le C\frac{\sqrt{s}}{n}\left(\frac{k}{\delta}+\log(2n)\right)
	\qquad \text{for each } j.
\end{equation}

[Proposition 23 of arXiv:2604.26898, '\bf Stochastic Scaling Limits and Synchronization \\by Noise in Deep Transformer Models'] Let $T > 0$ and step size $\dt = T/L \leq 1$. Let the discrete time points be $t_\ell = \ell \dt$ for $\ell=0, \dots, L$.
    Consider a system of $N$ particles governed by the SDE
    \begin{equ}
        dX^i_t = a(X^i_t, \mathbf{X}_t)\,dt + \sum_{k=1}^\infty \tilde \sigma_k(X^i_t)\, dB^k_t, \qquad X^i_0 = x^i_0,
    \end{equ}
    and its continuous-time Euler-Maruyama interpolation
    \begin{equ}
        \hat X^i_t = x^i_0 + \int_0^t a(\hat X^i_{t_{\ell_s}},\hat{\mathbf X}_{t_{\ell_s}})\,\dd s + \sum_{k=1}^\infty \int_0^t \tilde \sigma_k(\hat X^i_{t_{\ell_s}})\,\dd B_s^k.
    \end{equ}
    Assume that there exist constants $K_2,K_3>0$ such that for all $N\in\mathbb N$ and $x,y\in(\R^d)^N$,
    \begin{align}
        \E[|X_0^i|^2] &< \infty, \\
        \frac1N\sum_{i=1}^N \left(|a(x^i,\mathbf x)-a(y^i,\mathbf y)|^2 + \sum_{k=1}^\infty |\tilde \sigma_k(x^i)-\tilde \sigma_k(y^i)|^2\right)
        &\le K_2 \frac1N\sum_{i=1}^N |x^i-y^i|^2,  \\
        |a(x^i,\mathbf x)|^2 + \sum_{k=1}^\infty |\tilde \sigma_k(x^i)|^2 &\le K_3. 
    \end{align}
    Then
    \begin{equ}
    \E\left[\sup_{0\leq t\leq T}\frac{1}{N}\sum_{i=1}^N |X^i_t - \hat{X}^i_t|^2\right]
    \leq 16 K_2 K_3 (4T+T^2) e^{4 K_2 (4+T) T} \dt.
    \end{equ}

