[Theorem 39 (Contraction at $Q_\ell$) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] Let $\widehat{M}$ be the compactification of $(0,\ell) \times P$ such that $Q_0 := N' = N_2 \times \cdots \times N_r$ is adjoined at $\{s = 0\}$, and $Q_\ell := \mathbb{CP}^m \times N'$ is adjoined at $\{s = \ell\}$. Suppose
$T = \min_{k \geq 2}\{T_k^\ell\} < \min\big\{T_F', \min_{k\geq 2}\{T_k^0\}\big\}$.

Let $\mathcal{I}_\infty$ be the subset of $\{2, \cdots, r\}$ such that $i_\infty \in \mathcal{I}_\infty$ if and only if $T_{i_\infty}^\ell = T$. Let $\mathcal{L}_{\mathcal{I}_\infty}$ be the line bundle obtained by restricting the normal bundle $\mathcal{N}_{Q_\ell}$ of $Q_\ell \subset \widehat{M}$ --- the line bundle $L = P \times_{\mathrm{U}(1)} \mathbb{C}$ of Proposition \ref{prop:bolt-closing} --- to $\prod_{i_\infty \in \mathcal{I}_\infty} N_{i_\infty}$; then $c_1 ( \mathcal{L}_{\mathcal{I}_\infty} ) = \sum_{i_\infty \in \mathcal{I}_\infty} q_{i_\infty} a_{i_\infty}$, with each $q_{i_\infty} < 0$.

Let $K_j := (T-t_j)^{-1}$, and fix $\bar{x}' \in Q_\ell$. Consider the rescaled and dilated sequence $g_j(t) = K_j g(t_j + K_j^{-1}t)$ defined on $t \in [-K_j t_j, K_j(T-t_j))$. Then, along a subsequence,
\begin{equation}
\begin{gathered}
\big( \widehat{M}, \; g_j (t), \; \bar{x}' \big) \;\longrightarrow\; \Big( \operatorname{Tot} \big( \mathcal{L}_{\mathcal{I}_\infty} \big) \times \mathbb{C}^{n''} \,, \;\; g_L (t) \oplus g_{\mathbb{C}^{n''}}, \bar{x}'\Big) \,, t \in \big( - \infty, 1 \big).
\end{gathered}
\end{equation}
Here $n'' = m + \sum_{k \geq 2, \, k \not\in \mathcal{I}_\infty} \dim_{\mathbb{C}} N_{k}$, $\operatorname{Tot} ( \mathcal{L}_{\mathcal{I}_\infty} )$ is the total space of the line bundle $\mathcal{L}_{\mathcal{I}_\infty} \to \prod_{i_\infty \in \mathcal{I}_\infty} N_{i_\infty}$, and $g_L$ is a complete gradient shrinking K\"ahler--Ricci soliton of ansatz form on $\operatorname{Tot} ( \mathcal{L}_{\mathcal{I}_\infty} )$ --- the Feldman--Ilmanen--Knopf shrinker in \cite{FIK} when the base is a projective space, and its multi-base generalization by Dancer--Wang in \cite{DW2011} in general. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Semi-martingale measures) of arXiv:2506.15037, '2BSDE with uncertain horizon and application to stochastic control in erratic environments'] We define $\mathcal P_{t}^W$ as the set of all semi-martingale measures
$\mathbb P$ on $(\Omega,\mathcal F)$, such that $\mathbb P$-a.s.:
\begin{enumerate}
    \item $(X_s)_{s\in [t,T]}$ is a $(\mathbb P; \mathbb F)-$semi-martingale admitting the canonical decomposition
    \[X_s=X_t+\int_t^s \mu^\mathbb P_r dr+X_s^{c,\mathbb P},\] where $\mu^\mathbb P$ is an $\mathbb F-$predictable $\mathbb R^d-$valued process and $X^{c,\mathbb P}$ denotes the continuous local martingale part of $X$ under $\mathbb P$;
\item the quadratic variation process $(\langle X\rangle_s)_{s\in [t,T]}$ is absolutely continuous in time $s$ with respect to the Lebesgue measure and the process $\hat{\sigma}$ defined by
\[\hat{\sigma}_t:= \lim\sup_{\varepsilon\to 0}\frac{\langle X\rangle_t-\langle X\rangle_{t-\varepsilon}}{\varepsilon}, \] takes values in $\mathcal S_d^{\geq 0}$, $\mathbb P\text{-a.s.}$, where $\mathcal S_d^{\geq 0}$ denotes the space of symmetric and positive definite matrix in dimension $d$.
\end{enumerate}

[Lemma 51 (Synthesis-map bounds) of arXiv:2607.10813, '2607.10813'] Uniformly for $0\le t,t'\le T_0$, on separated parameter classes, and for bounded $\mathfrak H_{\mathrm{prof}}$,
\begin{align}
 \|\mathsf S_{a,N,t}\|_{\mathcal L(\mathfrak H_a,L^2_\ell)}
 &\lesssim N^{-1+\beta_a},
 \\
 \|\mathsf S_{a,N,t}-\mathsf S_{a,N,t'}\|_{
 \mathcal L(\mathfrak H_a,L^2_\ell)}
 &\lesssim_{\theta}|t-t'|^\theta N^{-1+\beta_a+\theta},
 \qquad 0<\theta\le\frac12.

\end{align}
If two admissible multipliers are inserted, their difference satisfies the
same size and time-increment majorants, up to a factor two.
For every fixed shell $N$, the difference between the cutoff synthesis map and
the limiting map tends to zero in operator norm along every admissible cofinal
sequence; the proof uses only the plateau and uniform symbol bounds.

[Lemma 10 of arXiv:2603.26303, 'Spectral Gap of Biased Adjacent-Transposition Chains'] Let $f\in \mathbb{R}^{\mathfrak{S}_n}$.
Then, for $n\ge 3$,
\begin{equation*}

\langle f,K^2f\rangle\ge \frac{1-2m_{\mathbf p}\cos(\tfrac{{\pi}}{n})}{n-1}\langle f, Kf\rangle.
\end{equation*}
In the case of equality, there exists a non-negative constant $c$ such that
\begin{align}
    \mathsf E_r \mathsf E_s f&= 0 \qquad\qquad\quad \ \ \;\text{ for $|r-s| \ge 2$;}  \\
    \mathsf E_r \mathsf E_{r+1} \mathsf E_r f &= m_{\mathbf p}^2 \mathsf E_r f  \qquad\quad\ \text{ for each $r \in \{1,\dots, n-2\}$;} \\
    \| \mathsf E_r f\| &= c \sin (r \pi/n) \quad \ \  \text{ for each $r \in \{1,\dots, n-1\}$.} 
\end{align}

