body:
[Lemma lem:meanfieldproc of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] Consider the multivariate linear-Gaussian setting, $g(x) := Gx, \enskip h(x):= Hx$ and a mean-field SDE of the form 
    \begin{align}

        d\bar{X}_t = \underbrace{G\bar{X}_t + \Sigma^{1/2}dW_t}_{\text{mutation}}  \quad + \underbrace{dI_t}_{\text{observation update}} 
    \end{align}
    with $\bar{X}_0 \sim \mathcal{N}(x; m_0, C_0)$ and the stochastic observation update term 
    \begin{align}

        dI_t = &-\frac{s}{2}K_t H (\bar{X}_t - m_t)dt + \underbrace{ (r-s) K_t \left(dZ_t - H\bar{X}_t dt  + \left(\frac{2}{r-s}\Xi\right)^{1/2} d\bar{B}_t\right)  }_{\text{Stochastic Kalman Innovation}} 
    \end{align}
    or the deterministic observation update term 
    \begin{align}

	d I_t = \left( \frac{r}{2} - s \right) K_t H (\bar{X}_t - m_t)dt   + \underbrace{\enskip  (r-s) K_t\left( dZ_t - \frac{1}{2} \left(H\bar{X}_t + Hm_t  \right) dt \right)}_{\text{Deterministic Kalman Innovation}} 
\end{align}
where $\bar{B}$ is a scalar Wiener process independent of $W, B$. The time evolution of the conditional density of $\bar{X}_t$ given $\mathcal{Z}_t$ for (equation eq:basemf of the paper) with either (equation eq:mfinfla of the paper) or (equation eq:mfinflabias of the paper) observation update terms is given by the limiting non-local replicator-mutator equation or modified Kushner equation (equation eq:modifiedkushner of the paper).  Similarly, consider observation update terms driven by piecewise smooth in time observations, 
\begin{align}

	d I_t =    - \frac{s}{2} K_t H \left( \bar{X}_t - m_t \right)dt + \enskip (r-s) K_t \left(\frac{dZ_t^d}{dt} - \frac{1}{2}H\left( \bar{X}_t + m_t  \right)\right)dt 
\end{align}
or the stochastic version 
\begin{align}

	d I_t = -\frac{s}{2}K_t H (\bar{X}_t - m_t)dt + (r-s) K_t \left(\frac{dZ_t^d}{dt} - H\bar{X}_t  \right)dt + \sqrt{r-s} K_t \Xi^{1/2} d \bar{B}_t  
\end{align}
The time evolution of the conditional density of $\bar{X}_t$ given $\mathcal{Z}_t$ for (equation eq:basemf of the paper) with either (equation eq:mfstochode of the paper) and (equation eq:mfdetode of the paper) observation update terms is given by the non-local replicator-mutator equation (equation eq:repmutlineargauss of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_compare_hdiamond of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For any $d\ge 3$, there exist $C,c>0$ such that for any event $\mathsf{F}$, $h>0$, $M\ge 10$ and $\diamond \in \{\mathbf{N},\mathbf{x},\mathbf{T}\}$ with $\diamond\ge M$, 
	\begin{equation}
	0\le 	\mathbb{P}\big(\mathsf{F},  \mathsf{H}_h^{\diamond}  \big)- \mathbb{P}\big(\mathsf{F}, \mathsf{H}_h^{\diamond} ,\bm{0}\xleftrightarrow{[h]} \infty   \big)\le Ce^{-ch^2M^{\frac{1}{d}}}.
	\end{equation}

[Definition 34 (Admissible Obstacles) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let Assumptions \ref{ass:coefficients} and \ref{ass:problem_data} hold. Let $u_\varepsilon$ be the unique mild solution of equation \eqref{eq:hjb_penalized}. A dynamic obstacle $\Phi \in Lip_m([0, T] \times H)$ is said to be \emph{admissible} for the parabolic optimal stopping problem if the associated family of penalty terms, defined by:
\begin{equation}

    \Pi_\varepsilon(t, x) := \frac{1}{\varepsilon} \left( u_\varepsilon(t, x) - \Phi(t, x) \right)^+,
\end{equation}
is uniformly bounded in the weighted parabolic topology. Specifically, there must exist a constant $K > 0$, independent of $\varepsilon > 0$, such that:
\begin{equation}

    \sup_{\varepsilon > 0} \|\Pi_\varepsilon\|_{\mathcal{B}_{m, T}} \le K.
\end{equation}

[Proposition Moments1 of arXiv:2505.11721, 'Variational principles for Hausdorff and packing dimensions of fractal percolation on self'] \begin{enumerate}  Let $q\in(1,2]$. 
\item Suppose that $\sum_{n\ge 1}\left(\prod_{k=1}^n \phi_{W^{(k)}}(q)\right)^{\frac{1}{q}}<+\infty$. Then, $\lim_{N\to +\infty} \sum_{n=1}^N H(W^{(n)})=+\infty$. Also, for all $v\in \mathcal I^*$, $(Y_n(v))_{n\ge 0}$ converges to $Y(v)$, almost surely and in $L^q$ norm. In particular, $\mathbb{E}\left(Y(v)\right) = 1$. Moreover, there exists  a constant $C=C(\# \mathcal I)> 0$  such that for all  $v\in \mathcal I^*$, $\|Y(v)\|_q\le C \sum_{n=0}^{\infty} \left(\prod_{k=1}^n \phi_{W^{(|v|+k)}}(q) \right)^{\frac{1}{q}} < +\infty$, with the convention that  the empty product at $n=0$ is equal to 1. 

In particular, if $\sup_{n\ge 1} \phi_{W^{(n)}}(q)<1$, then $\sup_{v\in\mathcal{I}^*}(\|Y(v)\|_q)_{v\in\mathcal{I}^*}<+\infty$. 

\item Suppose that  $\sup_{n\ge 1} \phi_{W^{(n)}}(q)<+\infty$ and $\liminf_{N\to +\infty}N^{-1}\sum_{n=1}^N H(W^{(n)})>0$. Then, there exists $\hat q\in (1, q)$ such that 
 $\sum_{n\ge 1}\left(\prod_{k=1}^n \phi_{W^{(k)}}(q')^{\frac{1}{q'}}\right)<+\infty$ for all $q'\in (1,\hat q]$.  

Let  $\epsilon>0$ such that 
\begin{equation}
\sum_{n=1}^NH(W^{(n)})\ge n\epsilon \text{ for all $N$ sufficiently large. }
\end{equation}
Let $N_\epsilon=\min\big \{N\ge 1:\, \forall \, N'\ge N, \sum_{n=1}^{N'}H(W^{(n)})\ge N'\epsilon\big\}$. There exists  $\tilde q\in (1,\hat q]$ such that for $q'\in (1,\tilde q]$, there are constants $C=C(q',\#\mathcal I,\epsilon)\ge 1$ and $c=c(q',\# \mathcal I,\epsilon)>0$ such that for all $N\ge N_\epsilon$,  one has $\widetilde N\le \frac{\log (\#\mathcal{I})}{\epsilon} N$ and for $v\in \mathcal{I}^N$, 
\begin{equation}
B(N,q')\le \mathbb{E}\left((Y(v))^{q'}\right) \le \frac{CN^{q'} e^{cN(q'-1)^2}}{(1-e^{-\frac{(q'-1)}{4q'}\epsilon})^{q'}}B(N,q'),
\end{equation}
where $B(N,q')=\max \Big (1, \exp \big [-(q'-1)\sum_{n=N+1}^{\widetilde N}H(W^{(n)})\big ]\Big )$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

