[Proposition prop:wegner_asymptotics of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For $x \in \mathcal{I}_{\alpha}$ and $y \in \mathcal{I}_{\beta}$, the following asymptotic regimes hold as $n, N \to \infty$:
\begin{enumerate}
    \item \textbf{Frozen regime} ($n\lambda \ll 1$):
    The transition probability is dominated by the initial state:
    \begin{equation}
        \left| p_n(x,y) - \frac{1}{M}\delta_{\alpha\beta} \right| = O(n\lambda).
    \end{equation}

    \item \textbf{Skellam regime} ($n\lambda \to \mu \in (0,\infty)$):
    The transition probability converges to the continuous-time random walk kernel:
    \begin{equation}
        \left| p_n(x,y) - \frac{1}{M}p^{\mathrm{(Skellam)}}(\beta-\alpha,\mu) \right| = O(n^{-1} M^{-1}).
    \end{equation}
    Here $p^{\mathrm{(Skellam)}}$ was defined in (equation equ:skellam of the paper).
    \item \textbf{Diffusive regime} ($n\lambda \to \infty$):
    The transition probability satisfies a local central limit theorem. For $\sigma^2 = n\lambda/d$, we have
    \begin{equation}
        \sup_{x,y} \left| p_n(x,y) - \frac{1}{M}\mathcal{G}_{n\lambda/d}(\alpha-\beta) \right| = o\Big( \frac{1}{M (n\lambda)^{d/2}} \Big).
    \end{equation}
\end{enumerate}

[Conjecture 11 (Type-$2$ constant of Tensors) of arXiv:2603.29571, 'Randomstrasse101: Open Problems of 2025'] Let $p \geq 2$, then
    \begin{equation}
    \mathbb{E} \left| \left| \sum_{i=1}^n g_i  T_i \right| \right|_{ \mathcal{I}_p} \leq  \, \tilde{\mathcal{O}}_{r,p} \left( d^{\frac12 - \frac1p } \sqrt{\sum_{i=1}^n \left| \left|  T_i \right| \right|_{ \mathcal{I}_p}^2 }\right).
    \end{equation}
    (Here $\tilde{\mathcal{O}}_{r,p}$ hides multiplicative constants depending on $r$ and $p$ as well as polylog factors in $d,n$.) (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma L:Second-der-Integrating-factor of arXiv:2606.23865, 'Uniform-in-time Gaussian fluctuations for multiscale nonlinear stochastic systems via Mall'] For any $t \ge r,$ let the process $Z$ be defined as follows:
\begin{equation}
Z_{t,r} \triangleq \exp \left[ \int_{r}^t \frac{1}{\eta}f_y(Y_s^\eta)\thinspace ds + \int_{r}^t \frac{1}{\sqrt{\eta}}\tau_y(Y_s^\eta)\thinspace dW_s^2 - \frac{1}{2\eta} \int_{r}^t \tau_y(Y_s^\eta)^2 \thinspace ds \right].
\end{equation}
Suppose that Assumption (A:Derivatives-Assumption-f of the paper) holds. Then, there exists a time-independent constant $K>0$ such that 
$$\mathbb{E} \left[ \left| Z_{t,r}\right|^{2p} \right] \le K e^{-\frac{(2p)\lambda}{\eta}(t-r)}.$$

