[Theorem 38 ({see \cite[Theorem 5.1.3, 5.1.4) of arXiv:2605.05864, 'Classification and Metrization of Classes of Smooth measures'] {FOT11}}]

 The quotient space $\bf{A}_c^+/\sim$ and the family $\c{S}$ are in one-to-one correspondence under the following relation:
 For $\mu \in \c{S}$ and $A \in \bf{A}_c^+$,
 \begin{align} 
  \mathbb{E}_{hm} \left[ \int_0^\infty e^{-\alpha s} f(X_s) \, dA_s \right] 
  = \int_E f(x) R_\alpha h(x)\, \mu(dx) 
 \end{align}
for any non-negative valued Borel measurable functions \(f\) and \(h\). Moreover, $(\ref{eq-Revuz})$ is equivalent to 
\begin{equation}
 \mathbb{E}_{hm} \left[ \int_0^t  f(X_s) \, dA_s \right] =
   \int_{E} \left(\int_{0}^{t} P_s h(x)\, ds\right) f(x)\, \mu(dx)

\end{equation}
 for any non-negative valued Borel measurable functions \(f\) and \(h\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:fixed-alpha of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] Under the assumptions of (thm:main of the paper), if $\alpha_N\equiv\alpha\in(0,\infty)$, then, for every fixed $x>0$,
\begin{align}
 \lim_{N\to\infty}\frac1{a_N^{3/2}}
 \log\mathbb P(Z_N>a_Nx)
 &=-\frac43x^{3/2},                                      \\
 \lim_{N\to\infty}\frac1{a_N^2}
 \log\mathbb P(Z_N\le-a_Nx)
 &=-\frac{\alpha^2x^2}{2\sigma^2}.                      
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 (Difference estimate) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] Let two solutions remain in the bootstrap set and have the same composite
profile.  Put
\[
 \dot r=r^{(1)}-r^{(2)},\qquad
 \dot v=v^{(1)}-v^{(2)},\qquad
 \dot\psi=\psi^{(1)}-\psi^{(2)}
\]
and
\begin{equation*}
 B=e^{\phi^a}\int_0^1
 e^{\theta\psi^{(1)}+(1-\theta)\psi^{(2)}}\,\dd\theta.
\end{equation*}
Define
\begin{equation*}
\begin{split}
 \cE_{s-1,\eps}^{\rm diff}
 =\frac12\sum_{\abs\alpha\le s-1}\int_\Om
 \bigl(&n^{(1)}\abs{\pa^\alpha\dot v}^2
 +h_i'(n^{(1)})\abs{\pa^\alpha\dot r}^2\\
 &+B\abs{\pa^\alpha\dot\psi}^2
 +\eps^2\abs{\nabla\pa^\alpha\dot\psi}^2\bigr)\,\dd x.
\end{split}
\end{equation*}
Then
\begin{equation}
  \frac{\dd}{\dd t}\cE_{s-1,\eps}^{\rm diff}
  \le C\bigl(K_a+\mathfrak N_s^{(1)}+\mathfrak N_s^{(2)}\bigr)
  \cE_{s-1,\eps}^{\rm diff}. 
\end{equation}
The constant is independent of $\eps$.

