[Proposition 24 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Fix two non-negative integers $m,k\in\ZZ_{\geq 0}$  such that $m\le k<\alpha$. Then with $u=-m$, $v=-k$ we have
  \begin{multline}
     \GG_N(\alpha,-m,-k)=  (-1)^{k+m} \tfrac{(k+m)!}{k!^2m!^2} \Gamma (\alpha )^{2 N}\\+
     \sum_{j=0}^{k-m-1}
   (-1)^j {\binom{m+k}{j}}\, \tfrac{ 2 (k-j)(k-m-j-1)!}{(2k-j)!} \Gamma (\alpha +j-k)^N \Gamma (\alpha -j+k )^N
       \\+
      (-1)^{k+m} \sum_{i=0}^{m-1} {\binom{m+k}{i}}\
     \tfrac{2 (m- i)} {(2m- i)!  ( i+k-m)!  }
   \Big[N\left(\psi(\alpha+m-i)-\psi(\alpha+i-m)\right)
    \\ +\psi(i+1)+\psi(1+i+k-m)- \psi(1+k+m-i) -\psi(1+2m-i) +\tfrac{1}{m-i}\Big] \\ \cdot  \Gamma (\alpha+ i-m )^N \Gamma (\alpha- i+m)^N.
 \end{multline}

[Coro basicproperties of arXiv:2605.07920, 'Primitive Sequences for Probability Measures on Compact Intervals'] The following hold:
    \begin{coroitems}
        \item $0 \leq \varepsilon_n \leq (b-a)^n/n!$. Consequently, $\varepsilon_n \to 0$ and $\{\varepsilon_n\}_n \in \ell^1(\mathbb{N})$. 
        \item $\varepsilon_n = (b-a)^n/n!$ for all $n \geq 0$ if and only if $X = a$ a.s., and $\varepsilon_n = 0$ for all $n \geq 1$ if and only if $X = b$ a.s.
        \item The sequence $\{n!\varepsilon_n\}_n$ is log-convex, and hence
        \begin{equation}
            \varepsilon_n^2 \leq \mleft(1 + \frac{1}{n}\mright) \varepsilon_{n-1} \varepsilon_{n+1}.
        \end{equation}
    \end{coroitems}

