[Thm corner process and product process of arXiv:2411.01104, 'Gaussian universality of $p$-adic random matrix products via corners'] Set $t=1/p$.
\begin{enumerate}
\item Let $i,n$ be integers with $1 \le i  \le n$, $\mu^{(i)} \in \Sig_{n-i+1}$, and $A^{(i)}\in\Mat_{(n-i+1)\times n}(\mathbb{Q}_p)$ be random with $\SN(A^{(i)})=\mu^{(i)}$ fixed and distribution invariant under $\GL_{n-i+1}(\mathbb{Z}_p) \times \GL_n(\mathbb{Z}_p)$ acting on the left and right. Let $A^{(i+1)} \in\Mat_{(n-i) \times n}(\mathbb{Q}_p)$ be the last $n-i$ rows of $A$. Then $\SN(A^{(i+1)})$ is a random element of $\Sig_{n-i}$ with distribution
\begin{equation}
\Pr(\SN(A^{(i+1)}) = \mu^{(i+1)}) = P_{\mu^{(i)}/\mu^{(i+1)}}(1;t) \frac{P_{\mu^{(i+1)}}(t,\ldots,t^{n-i};t)}{P_{\mu^{(i)}}(1,\ldots,t^{n-i};t)}.
\end{equation} 

\item Let $A\in\Mat_{n\times m}(\mathbb{Z}_p)$ be the same as (ex: nxm corner of invertible of the paper). Then the distribution of $\SN(A)$ is given by the Hall-Littlewood measure
$$\mathbf{P}(\SN(A)=\lambda)=\frac{P_\lambda(1,t,\ldots,t^{n-1};t)Q_\lambda(t^{m-n-1},\ldots,t^{N-n};t)}{\Pi_t(1,t,\ldots,t^{n-1};t^{m-n-1},\ldots,t^{N-n})}$$
Here $Q_\lambda$ is the Hall-Littlewood $Q$ polynomial, and $\Pi_t$ is the Cauchy Kernel, see [Macdonald].
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:gaps of arXiv:2607.10801, 'Relaxation times of non-reversible\\ Markov processes'] \begin{enumerate}[(i)]
        \item The \emph{spectral gap} of $(\mathcal{L},\dom(\mathcal{L})$ is defined as 
            \begin{equation}
                \gap(\mathcal{L})\ =\ \inf\left\{\Re(\lambda):\lambda\in\spec(-\mathcal{L}|_{\mathcal{D}_0})\right\}\,.
            \end{equation}
\item The \emph{Poincaré constant} of $(\mathcal{L},\dom(\mathcal{L}))$ is defined as 
            \begin{equation}
                \lambda(\mathcal{L})\ = \ \inf\left\{\frac{\mathcal{E}_1^\mathcal{L}(f,f)}{\norm{f}^2}:f\in \mathcal{D}_0\setminus\{0\}\right\}\,.
            \end{equation}
        \item The \emph{singular value gap} of $(\mathcal{L},\dom(\mathcal{L}))$ is defined as 
            \begin{equation}
                \sing(\mathcal{L})\ =\ \inf\left\{\frac{\mathcal{E}_2^\mathcal{L}(f,f)^{1/2}}{\norm{f}}:f\in \mathcal{D}_0\setminus\{0\}\right\}\,.

            \end{equation}
    \end{enumerate}

[Corollary cor:sc-dual-Woodbury of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] In the setting of Theorem~(thm:sc-dual-Darboux of the paper), suppose
that $\dim E < \infty$ and that
$F(u) \vcentcolon= \det_H(I-zK(u))$ is well-defined for every
$u \in \mathcal{V}$.  Then
\begin{equation}
F(u)=F(Tu)\det_E\bigl(\mathcal{M}(Tu)\bigr).
\end{equation}
Consequently, for $j \geq 2$,
\begin{equation}
\det_E(\mathcal{M}_j(u))F(u)F(S_j u)
=\det_E(C_j(u))F(Tu)F(T^{-1}S_j u).
\end{equation}

[Proposition 12 of arXiv:2607.26944, 'Improved bounds on the inradius and inverse inradius process of the convex hull of planar '] Fix $a>0$, $b>0$, and $m>1$. Let
\begin{equation}
    Q_{m,b,a}(x)=(x-1)^2\mleft(a^2(x-2)-x\mright)-m^2(x-2)(x^2-b^2),
\end{equation}
and assume that $ Q_{m,b,a}(x)\ge 0$ for all $x \ge b$. Let $(\Theta_1(y) : y\ge 0)$ and $(\Theta_2(y) : y\ge 0)$ be the inverse range processes of the coordinates of $\bm W$ defined in~\eqref{eq:Theta_1,2_BM}, and let $T_a \coloneqq \min\{\Theta_1(2a),\Theta_2(2a)\}$. At time $T_a$, recenter and rotate the path so that $\bm W (T_a)=A=(0,a)$ and the line segment of length $2a$ already contained in the convex hull is sent to the segment with endpoints $A=(0,a)$ and $B=(0,-a)$. Let $\tau_{m,b,a}$ be the first exit time from $\mathbb H_{m,b}$ of this transformed Brownian motion after $T_a$. Then,
\[
    \Theta^{\mathsf r}
    \le
    \min\{\Theta_1(2a),\Theta_2(2a)\}
    +
    \tau_{m,b,a} \quad \text{a.s.}
\]

