[Lemma MarkovFell*** of arXiv:2604.21591, '\bf Long-time dynamics of stochastic 2D hydrodynamic-type evolution equations driven by mu'] Assume that the hypotheses of Theorem (2DHD-the3.3-0 of the paper) and (equation LSWs6.3 of the paper) hold. Then $\Psi(t,\tau), t\geq \tau,$ is a continuous non-autonomous dynamical system associated with ((2DHD-1.1 of the paper)). More precise, $\Psi(t,\tau):\mathcal{P}_4({H})\rightarrow \mathcal{P}_4({H})$ satisfies that for any $\tau \in \mathbb{R}$,

	$(i)$  $\Psi(0,\tau)=I_{\mathcal{P}_{4}({H})}$;

	$(ii)$ $\Psi(t+s,\tau)=\Psi(t,s+\tau)\Psi(s,\tau)$ for any $t\geq s \geq \tau$;

	$(iii)$ $\Psi(t,\tau): \mathcal{P}_{4}({H})\rightarrow \mathcal{P}_{4}({H})$ is continuous for $t\in \mathbb{R}^+$.

[Cor typeIVandC of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] There exists a constant $C>1$ that depends on $\mathbf{k}_{1},\ldots,\mathbf{k}_{l}$ and $\sigma$, and is uniform in $N$, such that for all $N\ge 100$,
    \begin{equation}
    \begin{split}
    \left|\sum_{(E,\vec{q})}w(E,\vec{q})\right|\le& C\cdot N^{-m};\\
    \left|\sum_{(E,\vec{q})\notin \mathcal{C}}w(E,\vec{q})\right|\le& C\cdot N^{-m-1/3}.
   \end{split}
    \end{equation}

[Lemma lem: Fan Process of arXiv:2609.03755, 'The Scramble Number of Outerplanar Graphs'] Let $G$ be a maximal outerplanar graph on $n$ vertices with $n\geq 8$ and $\left( v_i,v_j\right)$ an interior edge. If $\deg\left( v_i\right)>\sqrt{2n}$ and $\deg\left( v_i\right)\geq \deg\left( v_j\right)$, then there exists a set $\mathcal{H}$ that satisfies the following:
    \begin{enumerate}

        \item $G\setminus\left( \mathcal{H}\cup \{v_i,v_j\}\right)$ is separated into components $C_1, \ldots, C_m$ such that $|C(C_i, G\setminus C_i)|\leq  3\sqrt{2n}+8$. That is, the outdegree of each component is at most $3\sqrt{2n}+8.$ 
        \item $|\mathcal{H}|\leq 2\left\lfloor \frac{\Delta}{\sqrt{2n}}\right\rfloor-2$.
    \end{enumerate}

