[Theorem Thm_UniformlyFredholm_SardSmale of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let ${\mathbf{X}}$ and ${\mathbf{Y}}$ be second-countable tame Fréchet manifolds.
  If $f \mskip0.5mu\colon\thinspace {\mathbf{X}} \to {\mathbf{Y}}$ is uniformly Fredholm,
  then its set of regular values
  \begin{equation*}
    \mathrm{RegVal}(f)
    \coloneq
    \set{
      y \in {\mathbf{Y}}
      :
      T_xf ~\text{is surjective for every}~ x \in f^{-1}(y)
    }
  \end{equation*}
  is comeager.

[Lemma lem:AFEbds of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] Let $d>8$ and $L \ge L_3$.
Suppose that $m \in [0, \frac{1}{2} m(p) \wedge \frac{1}{2} m_S({\mu_p})]$,
that $\tilde{b}(m) \le 3$,
and that $m(p) L$ and $m_S({\mu_p})L$ are sufficiently small.
Then the functions $\hat F_p ^{(m)}, \hat A_{\mu_p} ^{(m)}, \hat E_p ^{(m)}$ are $d-2$ times weakly differentiable.
In addition, there exists $\varepsilon \in (0,1)$ such that,
for any multi-index $\gamma$ with $\abs \gamma \le d-2$
and any choice of $q_1, q_2$ satisfying
\begin{equation} 
    \frac{ \abs \gamma } d < q_1^{-1} < 1,
    \qquad
    \frac{ 2 - \varepsilon + \abs \gamma } d < q_2^{-1} < 1 ,
\end{equation}
the following hold with constants independent of $p,m,L$:
\begin{align} 
\biggnorm{ \frac{ \nabla^\gamma \hat A_{\mu_p} ^{(m)} }{ \hat A_{\mu_p} ^{(m)} } }_{q_1}, \;
\biggnorm{ \frac{ \nabla^\gamma \hat F_p ^{(m)} }{ \hat F_p ^{(m)} } }_{q_1}
	\lesssim 1 , \qquad
\biggnorm{ \frac{ \nabla^\gamma \hat E_p ^{(m)} }{ \hat A_{\mu_p} ^{(m)} \hat F_p ^{(m)}} }_{q_2}
\lesssim \beta ,
\end{align}
If $\abs \gamma \ne 0$, the estimates are improved to
\begin{align} 
\biggnorm{ \frac{ \nabla^\gamma \hat A_{\mu_p} ^{(m)} }{ \hat A_{\mu_p} ^{(m)} } }_{q_1}, \;
\biggnorm{ \frac{ \nabla^\gamma \hat F_p ^{(m)} }{ \hat F_p ^{(m)} } }_{q_1}
	\lesssim L^{ \abs \gamma - d/q_1 } 	, \quad
\biggnorm{ \frac{ \nabla^\gamma \hat E_p ^{(m)} }{ \hat A_{\mu_p} ^{(m)} \hat F_p ^{(m)}} }_{q_2}
	\lesssim \beta ( L^{\abs \gamma - d/q_2} + \beta ),
\end{align}
with constants independent of $p,m,L$.

[Definition 44 (Open covering of $M$) of arXiv:2608.29086, '2608.29086'] Given $M \subset M_0$ and $S_i \subset M$ ($i \in I$), where $I \subset \mathbf{Z}$. Set $V=\{S_i \ |\ i \in I \}$. 
$V$ is called an \textit{open covering} of $M$ if 
\begin{enumerate}
\item $Int(M)=\bigcup_{i \in I} Int(S_i)$, and
\item $|S_i|$ has no hole inside ($i \in I$). 
\end{enumerate}

