[Proposition 14 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] For every $\mu\in\mathcal M_*$ the following hold.
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item The operator $G_\mu$ is positive, injective, self-adjoint and
Hilbert--Schmidt on $L^2(\mu)$, and
\begin{equation}
 G_\mu=A_\mu^{-1}.

\end{equation}
\item The form inclusion
\begin{equation}
 j_\mu:(V_\mu,\|\cdot\|_{\E,\mu})\longrightarrow L^2(\mu)

\end{equation}
is compact.  In particular, $A_\mu$ has compact resolvent, no zero mode, and
\begin{equation}
 0<\Lambda_1^\mu\le\Lambda_2^\mu\le\cdots\uparrow\infty.

\end{equation}
\item
\begin{equation}
 G_\mu:L^2(\mu)\longrightarrow C_b(D),

\end{equation}
so every eigenfunction of $A_\mu$ has a bounded continuous representative.
\end{enumerate}

[Thm of arXiv:2509.07729, 'Permuton and local limits for the Luce model'] Let $\sigma_n$ be a Luce-distributed permutation of size $n$ with exponential Sukhatme weights $\theta_i=\alpha^{n-i+1}$ for some $\alpha>0$. Fix $k\geq 1$ and $\pi\in\mathcal S_k$. Then
	\begin{equation}
		\sqrt{n} \,\frac{\pcocc(\pi,\sigma_n)-\Lambda(\pi)}{\sqrt{\nu_\infty(\pi)}}\xrightarrow{\mathrm{d}}\mathcal{N}(0,1),
	\end{equation}
	where $\Lambda(\pi)=p\mathopen{}\mathclose\bgroup\originalleft(\alpha^{-\pi^{-1}(1)},\dots, \alpha^{-\pi^{-1}(k)}\aftergroup\egroup\originalright)$ and $\nu_\infty(\pi)$ is defined as in (equation eq:nu_pi2 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Let $G$ be a finite group acting on $\mathcal{X}$, and let $\mu$ be the uniform distribution on $G$. Under Assumption (assum:pi and G of the paper), for any distribution $\pi_0$ satisfying $\pi\ll \pi_0$ and $\pi_0(gx)=\pi_0(x)$ for any $g\in G$, we have 
    \begin{equation*}
        D_{KL}\left(\pi\|\pi_G\right)\leq D_{KL}\left(\pi\|\pi_0\right).
    \end{equation*}

