body:
[Lemma Qprime-numerator of arXiv:2608.30212, 'A Painlev\'e equation for the H\"ormander-Bernhardsson constant'] For $k$ even and $c\in J_{k,0}$,
\begin{align}
\begin{split}
 \mathcal{L}_c[\mathcal{V}_c(x,.) Q_{k,c}^2]  & = \frac{-(2k+1)h_k(c) x^2 +   c \dot{h}_k(c)}{x^2(x^2-1)}
\end{split}
\end{align}

[Prop 3 (Optimality of Theorem~\ref{Theo_main2} when $p_{1}=\cdots=p_{2}=1$) of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $\eta_{1}, \cdots, \eta_{n}\stackrel{i.i.d.}{\sim}\mathcal{W}_{s}(\alpha)$ and $A$ be a symmetric diagonal-free matrix. Then for $0<\alpha\le 1$ and $t\ge 0$
	\begin{align}
		\mathbb{P}\{\vert \eta^\top A\eta-\mathbb{E}\eta^\top A\eta\vert\ge t    \}\ge C(\alpha)\exp(-c(\alpha)f_{2}(t)),\nonumber
	\end{align}
	where $\eta=(\eta_{1}, \cdots,\eta_{n})^{\top}$, $C(\alpha), c(\alpha)$ are  positive constants depending only on $\alpha$, and $f_{2}(t)$ is defined in \eqref{Eq_intro_f2}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Prop3.1 of arXiv:2411.01849, 'A tamed-adaptive Milstein scheme for stochastic differential equations with low regularity'] It holds 
	\begin{align} 
	\lim\limits_{k \to +\infty} t_k =+\infty \quad \text{a.s.} 
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_meta of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] For any matrices $A_1,A_2\in{\mathbb C}^{2N\times 2N}$ and vectors ${\bm x}, {\bm y}\in {\mathbb C}^{2N}$, we have
		\begin{equation}
			\begin{split}

				\partial_t (M_{12,t}^{A_1})_{{\bm x}{\bm y}}&=(M_{12,t}^{A_1})_{{\bm x}{\bm y}}+(\mathcal{S}[M_{12,t}^{A_1}]M_{21,t}^I)_{{\bm x}{\bm y}}, \\
				\partial_t (M_{121,t}^{A_1,A_2})_{\bm x\bm y}&=(M_{121,t}^{A_1,A_2})_{\bm x\bm y}+(\mathcal{S}[M_{121,t}^{A_1,A_2}]M_{11,t}^I)_{\bm x\bm y}+(\mathcal{S}[M_{12,t}^{A_1}]M_{121,t}^{I,A_2}))_{\bm x\bm y} +(M_{121,t}^{A_1,I})\mathcal{S}[M_{21,t}^{A_2}])_{\bm x\bm y}.
			\end{split}
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem mainthm0 of arXiv:2607.05418, 'On the Group Randomness of 0-1 Real Sequences from Binary Linear Codes'] Let $\{\mathcal{C}_n\}$ be a sequence of binary linear codes, so that $\mathcal{C}_n$ has length $n$ and dual distance $d_n^\bot$. Let $\Phi_{\mathcal{C}_n}$ be the $p_n \times n$ $\pm 1$ random matrix as constructed above, with $y:=p_n/n \in (0,1)$ fixed. Let $\mathcal{G}_{\mathcal{C}_n}$ be the Gram matrix of $\frac{1}{\sqrt{n}}\Phi_{\mathcal{C}_n}$, and $\mu_{\mathcal{C}_n}$ denote the spectral measure of $\mathcal{G}_{\mathcal{C}_n}$. Assume $d_n^\bot \geq 5$ for all $n$. Then as $n \to \infty$,
    \begin{equation}
    |\mu_{\mathcal{C}_n}(\mathbf{I})-\varrho_{\mathrm{MP}_y}(\mathbf{I})| \prec n^{-1/4}
    \end{equation}
    uniformly for all intervals $\mathbf{I} \subset \mathbb{R}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma prop:integral of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] For integer $b\ge 0$ it holds
\begin{align*}
    \int_{0}^1
    \frac{1}{\sqrt{1-u}}u^{-b-3/2}
    e^{-\frac{z^2}{2u}}du
=
    {\rm sgn}(z)
    \sqrt{2\pi} 
    e^{-\frac{z^2}{2}}
    \sum_{k=0}^{b} 
        \frac{(2k-1)!!}{z^{2k+1}}{b\choose k}.
\end{align*}
(Here we use the standard convention: $(-1)!!=1$.)

