body:
[Theorem th:3 of arXiv:2512.17736, 'Pathwise uniqueness by noise for singular stochastic PDEs'] Assume (H0 of the paper)--(H5 of the paper), (equation trace1 of the paper), and that $B$ is bounded.
\begin{itemize}
\item If (equation ineq2_al of the paper) holds, then
there exists a constant $\mathfrak L>0$, depending only on the structural data $\alpha,\beta,\delta,\theta,T,B$, such that, for every weak mild solutions $(X,W)$ and $(Y,W)$ to (equation SDE of the paper) with initial data $x,y\in D(A^\alpha)$, respectively, in the sense of Definition~(def-sol of the paper), with the same cylindrical Wiener process $W$ and defined on the same probability space, it holds that 
\begin{equation}

\|X-Y\|_{C^0([0,T];L^2(\Omega; D(A^\alpha)))}\leq \mathfrak L\|x-y\|_{D(A^\alpha)}\,.
\end{equation}
\item If (equation ineq3_al of the paper) holds, then
there exists a constant $\mathfrak L>0$, depending only on the structural data $\alpha,\beta,\delta,\theta,T,B$, such that, for every weak mild solutions $(X,W)$ and $(Y,W)$ to (equation SDE of the paper) with initial data $x,y\in H$, respectively, in the sense of Definition~(def-sol of the paper), with the same cylindrical Wiener process $W$ and defined on the same probability space, it holds that 
\begin{equation}

\|X-Y\|_{C^0([0,T];L^2(\Omega; H))}\leq \mathfrak L\|x-y\|_{H}\,.
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Supermartingale decomposition) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Under Assumption $(L)$-a.e.,	let $(f_j)_{j\ge 0}$ be a sequence of
	non-anticipative real-valued functions. Then, the following assertions are equivalent:
	\begin{itemize}
		\item [(i)] $(f_j)_{j\ge 0}$ is a supermartingale.
		\vspace{.05in}
		\item [(ii)] For every sequence $(\delta_j)_{j\ge 0 }$ of positive real numbers there are sequences $(H_j)_{j\ge 0}$ and $(A_j)_{j\ge 0}$, of non-anticipative real-valued functions defined on 
		$\mathcal{S}$, such that $(A_j)_{j\ge 0}$ is nondecreasing, $A_0 = 0$, and
		\begin{equation} 
		f_i(S)=f_0+\sum_{j=0}^{i-1}H_j(S)\Delta_jS-A_i(S)+\sum_{j=0}^{i-1}\delta_j,
		\end{equation}
		for every $S \in \Se \setminus N_f$ and $i\ge 0$. Here $N_f$ is an $\overline{I}$-null set independent of  $(\delta_j)_{j\ge 0 }$.
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:grid-gradient-short of arXiv:2608.05123, 'A central limit theorem for the random assignment problem'] At the harmonic grid,
\begin{equation}
 \frac1n\sum_{j=1}^n
 \left|\partial_{U_j}\Phi_n(\bar u_n)
 -r\{L(\bar u_{j,n})\}\right|^2\longrightarrow0.
\end{equation}

[Lemma 8 (Lemma $6.2.$, \cite{LeGallRosenRangeOfStableRandomWalks1991}) of arXiv:2607.02406, 'On the range of competing random walks'] Suppose that $d-1<\beta\le d$. Then for all $\ell\in[\![N]\!]$ and each $x,y\in\RR^d$ with $x\neq y$,
    \begin{equation}

        \underset{n\rightarrow\infty}\lim\ \underset{0\le k_1\le k_2\le n}\sup\left|\frac{h(n)b(n)^d}{n}\PP_{\lfloor b(n) x\rfloor}\left(k_1\le T_{\lfloor b(n) y\rfloor}^\ell\le k_2\right)-\int_{k_1/n}^{k_2/n}\d s\ p_s(y-x)\right|=0,
    \end{equation}
    \begin{equation}

        \underset{n\rightarrow\infty}\lim\ \underset{0\le k_1\le k_2\le n}\sup\left|\frac{b(n)^d}{n}\sum_{j=k_1}^{k_2}\PP_{\lfloor b(n)x\rfloor}\left(X_j^\ell=\lfloor b(n) y\rfloor\right)-\int_{k_1/n}^{k_2/n}\d s\ p_s(y-x)\right|=0.
    \end{equation}
    Furthermore, for any $\varepsilon>0$ and $x,y\in\RR^d$,
    \begin{equation}

       \frac{h(n)b(n)^d}{n}\PP_{\lfloor b(n)x\rfloor}\left(T_{\lfloor b(n) y\rfloor}^\ell\le n\right)\quad\text{and}\quad\frac{b(n)^d}{n}\sum_{k=0}^n\PP_{\lfloor b(n)x\rfloor}\left(X_k^\ell=\lfloor b(n) y\rfloor\right)
    \end{equation}
    are both $\lesssim|x-y|^{\beta-d-\varepsilon}+|x-y|^{\beta-d+\varepsilon}$ uniformly in $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thrm 23 of arXiv:2608.31054, 'Revisiting Picard's proof of the Picard--Weber--Weck selection theorem'] Let $\Omega :=(0,1)^d$ and $  u\in H_0(\Rot;\Omega)\cap H(\div;\Omega)$. Then, there holds $  u\in H^1(\Omega)^d$ and
    \begin{align}
        \|\Grad   u\|_{L^2(\Omega)^{d\times d}}^2 = \|\Rotcirc   u\|_{L^2(\Omega)^{d\times d}}^2 + \|\div\,   u\|_{L^2(\Omega)}^2.
    \end{align}

