[Theorem S theorem of arXiv:2509.04349, 'Precise asymptotics for the norm of large random rectangular Toeplitz matrices'] Let $\mathbf{T}_{p\times n}^{(s)}$ and $\mathbf{C}_{p\times n}^{(s)}$ be sequences of rectangular symmetric random Toeplitz and circulant matrices defined in (equation elements of Ts of the paper) and (equation elements of Cs of the paper) and satisfying assumptions (equation Lyapunov of the paper) and  (equation new asymptotic regime of the paper). Then, as $n$ diverges to infinity, the spectral norms $\|\mathbf{T}_{p\times n}^{(s)}\|$ and $\|\mathbf{C}_{p\times n}^{(s)}\|$ satisfy
\begin{equation}

    \frac{\|\mathbf{T}_{p\times n}^{(s)}\|}{\sqrt{2p\log n}}-\|\Sin_{1,n/p}\|_{2\rightarrow 2}\overset{P}\rightarrow 0,\qquad \frac{\|\mathbf{C}_{p\times n}^{(s)}\|}{\sqrt{2p\log n}}\overset{P}\rightarrow 1.
\end{equation}
If in addition (equation stronger asymptotic regime of the paper) holds, then the latter two convergences in probability strengthen to convergence in $L^\gamma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi 10 of arXiv:2511.10535, 'Eigenvalues of Brownian Motions on $\mathrm{GL}(N,\mathbb{C})$'] Let $(\A,\tau)$ be a $W^\ast$-probability space, and let $\A_1,\dots,\A_n$ be $*$-subalgebras of $\A$, sharing the same unit $1_\A$. They are said to be {\bf freely independent} or just {\bf free} if, for all $k$, for all $a_i\in\A_{j_i}$ such that $j_1\neq j_2$, $j_2\neq j_3$, \dots , $j_{k-1}\neq j_k$:
        \begin{equation}

            \tau\Big( (a_1-\tau(a_1))(a_2-\tau(a_2))\dots (a_k-\tau(a_k)) \Big) = 0.
        \end{equation}
        I.e.\ products of centered elements from adjacent-alternating algebras have trace $0$.
		Families of non-commutative random variables are said to be free if the $*$-subalgebras they generate are free.

[Theorem 3 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] For $0<\mu\le1$, there exists a unique solution $u \in \mathcal{C}\big(\R,H^1(\R)\cap L_{\mu}^2(\R)\big)$ to \eqref{NLS} with initial data $u_0\in H^1(\R)\cap L_{\mu}^2(\R)$. Given two solutions $u,u'$ with respective initial data $u_0,u_0'\in H^1(\R)\cap L_{\mu}^2(\R)$ and $T>0$, we have
\begin{equation}
\sup_{t\in[-T,T]}\|u(t)-u'(t)\|_{L^2(\IR)}\le C_{T,u_0,u_0'} \|u_0-u_0'\|_{L^2(\IR)}
\end{equation}
with $C_{T,u_0,u_0'}>0$. If moreover $u_0\in\CD_{\mu}^2$, then $u\in\CC(\R,\CD_\mu^2)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:smoothedIbPF of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] (Smoothed Versions of the IbPFs) For all $F \in C_b^1(L)$ and $h \in H_0^1 \cap H^2$ we have the IbPF
	\begin{align}
		\mathbb{E}_{\rho^{a,\varepsilon}\mu^{\beta}}\left[ \partial_h F \right] + \mathbb{E}_{\rho^{a,\varepsilon}\mu^{\beta}}\left[ F \, (h'',\cdot)_{L} \right]
		&= - \int_{\mathcal{S}'(\mathbb{R})} F(\beta(\omega)) \, \bar{h}_a \gamma_{\varepsilon}(\delta_a^{\mathrm{ext}}(\beta(\omega))) \, d\mu(\omega)\\
		&= - \langle \!\langle F(\beta), \bar{h}_a \gamma_{\varepsilon}(\beta_a) \rangle \!\rangle,\nonumber
	\end{align}
	where $\langle \!\langle\cdot,\cdot\rangle \!\rangle$ denotes the Hida dual pairing, see Subsection (sect:wna of the paper), which extends the canonical scalar product on $L^2(\mu)$. Further, the following IbPF holds:
	\begin{align}
		\mathbb{E}_{\rho^{\varepsilon}\mu^{\beta}}\left[ \partial_h F \right]
		+ \mathbb{E}_{\rho^{\varepsilon}\mu^{\beta}}\left[ F \, (h'', \cdot)_{L} \right]
		&= - \int_{\mathcal{S}'(\mathbb{R})} F(\beta(\omega)) \, \int_{(0,1)} \bar{h}_x \gamma_{\varepsilon}(\delta_x^{\mathrm{ext}}(\beta(\omega))) \,dx \, d\mu(\omega)\\
		&= - \Big\langle \mspace{-7mu} \Big\langle F(\beta), \int_{(0,1)} \bar{h}_x \gamma_{\varepsilon}(\beta_x) \, dx \Big\rangle \mspace{-7mu} \Big\rangle. \nonumber
	\end{align}

[Lemma lem:characteristic of arXiv:2608.28004, 'Hausdorff Dimension of the Set of Extreme Points\\ of a Random Countable Stable Zonotope'] For \(t\in u^\perp\),
\begin{equation}
    \bigl|\mathbb E e^{i\langle t,Y(u,v)\rangle}\bigr|
    =
    \exp\{-c_\alpha\Psi_{u,v}(t)\},
    \qquad
    \Psi_{u,v}(t)
    \mathrel{\overset{\mathrm{def}}{=}}
    \int_{S^{d-1}}
    |\langle t,x\rangle|^\alpha\,|a_{u,v}(x)|\,\sigma(\mathop{}\!\mathrm d x),
\end{equation}
where
\(c_\alpha=\alpha\int_0^\infty(1-\cos s)s^{-1-\alpha}\mathop{}\!\mathrm d s>0\).

