[Definition 113 of arXiv:2601.16377, '2601.16377'] $\mathcal{D}^{\textnormal{off}}$ is the open subset of $\mathcal D$ of Definition~\ref{Definition_ZW_set}, consisting of points such that
\begin{equation}

\big(\hat{D}_{1,1}\hat{D}_{2,1}+\theta\hat n (\hat A_2-\hat A_1)\big) \cdot \big(\hat{D}_{1,1}\hat{D}_{1,2}-\theta\hat{n}(\hat B_2-\hat B_1)\big) \neq 0.
\end{equation}

[Theorem 38 of arXiv:2506.15044, '2506.15044'] Let $X\in \mathcal{S}^\mathbb{B}$.
\begin{itemize}
  \item [$(1)$]If $(T_n,X^{(n)})$ is an FCS for $X\in \mathcal{S}^\mathbb{B}$, then $(T_n,(X^{(n)})^c)$ is an FCS for $X^c\in (\mathcal{M}^c_{\mathrm{loc},0})^\mathbb{B}$.
  \item [$(2)$]If $\tau$ is a $\mathbb{B}$-inner stopping time, then
  \begin{equation}
  (X^\tau)^c=(X^c)^\tau
  \end{equation}
  and
  \begin{equation}
  (X^\tau)^c\mathfrak{I}_\mathbb{B}=(X^c)^\tau\mathfrak{I}_\mathbb{B}=(X^\tau\mathfrak{I}_\mathbb{B})^c.
  \end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_approx_theta of arXiv:2412.05709, 'Incipient infinite clusters and volume growth for Gaussian free fields and loop soups on m'] For any $d\ge 3$ with $d\neq 6$, $\delta>0$ and any admissible $\{\mathsf{A}_h\}_{h\ge 0}$, there exists $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d,\{\mathsf{A}_h\}_{h\ge 0})>0$ such that for any $n_0,K\ge \ensuremath{C_{\ref*{const_approx_theta}}}$, $0\le h\le m^{-d^5}$, $\lambda\ge \ensuremath{C_{\ref*{const_approx_theta}}}\delta^{-1}$, and any $\diamond\in \{\mathbf{N},\mathbf{x},\mathbf{T}\}$ with $\diamond\ge m^{d^5}$, 
	 	\begin{equation}
		\big|\mathbb{I}(\mathsf{A}_h, n_0,\lambda,K,\diamond) - \mathbb{P}\big( \mathsf{A}_h \cap \mathsf{H}_h^{\diamond}\big)  \big| \le \delta \cdot \mathbb{P}( \mathsf{H}_h^{\diamond}).	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 (Lemma 2.9 \cite{Grigoryan2024}) of arXiv:2609.02732, 'Conservation of mass for solutions of Leibenson's equation on Riemannian Manifolds'] Let $u=u\left( x,t\right) $ be a non-negative bounded subsolution to \emph{(\ref{dtv})} in $M\times I$  with non-negative initial function $u(\cdot, 0)=u_0\in L^{1}(M)\cap L^{\infty}(M)$. If $\sigma\geq 1$, including $\sigma=\infty$, then the function 
		\begin{equation*}
			t\mapsto \left\Vert u(\cdot ,t)\right\Vert _{L^{\sigma}(M)}
		\end{equation*}
		is monotone decreasing in $I$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:stability of arXiv:2605.19894, 'Sharp Spectral Thresholds for Multi-View Spiked Wigner Models'] There exist constants $c,C>0$, depending only on $(B,\lambda,\Gamma)$ and $\epsilon$, such that the following stability result holds uniformly over $z\in \cU_{\Gamma}(\epsilon)$. If $(\widetilde{M},\Delta)$ satisfies
    \begin{equation}
       I_L = \rbr{ zB^{-1} - V^{-1} \Gamma V^{-1} + \Lambda - \Diag\cbr{ \lambda \odot \diag(\widetilde{M}) } } \widetilde{M} + \Delta,\quad \Im \widetilde{M} \prec 0,\quad \nbr{\Delta} \le c,
    \end{equation}
    then $\nbr{\widetilde{M} - M(z;\Gamma)}\le C\nbr{\Delta}$, where $M(z;\Gamma)$ is the valid solution from Proposition~(prop:feasibility of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2605.07832, 'A Bismut -Elworthy formula for BSDEs with degenerate noise'] Assume that condition (equation cond_traccia_gamma of the paper) is verified and let $T>0$ and $\alpha\in(0,1)$ be fixed. Hence, there exists a positive constant $c$, which only depends on $T$, such that
\begin{align*}

\|\widetilde u_t\|_{L^2(0,T;U)}    
\leq \frac{C\|a\|_U}{t^\frac12}
\end{align*}
for every $t\in(0,T]$ and every $a\in U$, where $\widetilde u_t$ is defined as in (equation damped_def_ctrl_2 of the paper) with $h=Ja$.

