body:
[Lemma lemma_densityrep_pearson of arXiv:2509.18045, 'Density convergence on Markov diffusion chaos via Stein's method'] Assume $\mathcal{Z}$ is   the Pearson distribution  associated with the Pearson diffusion   
   (equation sde_pearson of the paper) (namely, the law of $\mathcal{Z}$  is given by (equation densityanalyticformula_pearson of the paper)). Then the density function $p_Z$ admits the representation
    \begin{align*}
    p_\mathcal{Z}(x)&=\begin{cases}\E{ \mathds{1}_{\{x\leq \mathcal{Z}  \}}\rho_{1}(\mathcal{Z})}, &\quad x>\ell\,, \\
    \E{ \mathds{1}_{\{x> \mathcal{Z}  \}}\rho_{1}(\mathcal{Z})},&\quad x\leq \ell\,, \end{cases}
\end{align*}
where $\rho_1(y)= \frac{(2b_2+1)y+(b_1-m)}{b(y)}$. Moreover, if $p_\mathcal{Z}(x)$ has continuous derivatives up to order $k+1$ and $p^{(k)}(u)=0$, then we have 
 \begin{align*}
    p^{(k)}_\mathcal{Z}(x)&=\begin{cases}\E{ \mathds{1}_{\{x\leq Z  \}}\rho_{k+1}(\mathcal{Z})}, &\quad x>\ell\,, \\
    \E{ \mathds{1}_{\{x> \mathcal{Z}  \}}\rho_{k+1}(\mathcal{Z})}, &\quad x\leq \ell\,, 
    \end{cases}
\end{align*}
where $\rho_k$'s satisfy the recursive relation
\begin{align*}
      \rho_{k+1}(x)=-\rho_{k }(x)\frac{x-m+b'(x) }{b(x)}+\rho'_{k }(x) \,,\quad k=1, 2, \cdots
\end{align*}

[Prop 5 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] (i) {[}Global PAM{]} For a.e. realisation of $\xi$,
the solution $u(t,x)$ to the PAM defined by (\ref{eq:GlobalPAM})
admits the following Feynman-Kac representation:
\begin{equation}
u(t,x)=\mathbb{E}\big[e^{\int_{0}^{t}\xi(W_{s}^{x})ds}\big],
\end{equation}
where $\{W_{s}^{x}\}$ denotes a hyperbolic Brownian motion (generated
by $\Delta$) starting at $x$ that is independent of $\xi$, and
the expectation is taking with respect to $\{W_{s}^{x}\}.$

\vspace{2mm}\noindent (ii) {[}Localised PAM{]} Recall that $Q_{R}$
is the closed geodesic ball of radius $R$ centered at $o$. Consider
the following initial-boundary value problem:
\begin{equation}
\begin{cases}
\partial_{s}u_{R}(s,x)=\Delta u_{R}(s,x)+\xi(x)u_{R}(s,x), & (s,x)\in(0,\infty)\times Q_{R};\\
u_{R}(0,\cdot)\equiv1;\ u_{R}(s,\cdot)=0\ \text{on }\partial Q_{R}
\end{cases}
\end{equation}
Then solution $u_{R}(t,x)$ admits the following representation:
\[
u_{R}(s,x)=\mathbb{E}\big[e^{\int_{0}^{s}\xi(W_{r}^{x})dr};W^{x}([0,s])\subseteq Q_{R}\big].
\]

[Corollary 15 of arXiv:2609.02878, '2609.02878'] Fix \(q\in V\), where \(V\Subset Y^{\rm rv}\) lies in a Zariski product
region on whose preimage \cref{lem:general-block-volume} applies.  If
\(t_i\nearrow T\), \(\tau_i=T-t_i\), and
\begin{equation}
 \Omega_i(R):=
 \pi^{-1}\!\left(B_\eta(q,R\sqrt{\tau_i})\right)
\end{equation}
then, for every fixed \(R<\infty\),
\begin{equation}
 \Vol_{\tau_i^{-1}g(t_i)}\Omega_i(R)\le C_R
\end{equation}
for all sufficiently large \(i\).

[Definition def:AlmostSmooth of arXiv:2609.01464, 'Removability of non-isolated singularities for Einstein metrics and RCD spaces'] A compact metric measure space $(Z, d, \mathfrak{m})$ is an \textit{$n$-dimensional almost smooth metric measure space}, if there is an open subset $\Omega \subset Z$ satisfying the following conditions:
\begin{enumerate}
    \item There is a smooth $n$-dimensional Riemannian manifold $(M, g)$ and a homeomorphism $\varphi : \Omega \to M$, such that $\varphi$ defines a local isometry between $(\Omega, d)$ and $(M, d_g)$.
    \item The restriction of the measure $\mathfrak{m}$ to $\Omega$ coincides with the $n$-dimensional Hausdorff measure.
    \item The complement $Z \setminus \Omega$ has measure zero, i.e., $\mathfrak{m}(Z \setminus \Omega) = 0$, and it has zero $2$-capacity in the following sense: there is a sequence of smooth functions $\varphi_i : \Omega \to [0,1]$ with compact support in $\Omega$ such that
    \begin{enumerate}
        \item For any compact $A \Subset \Omega$, we have $\varphi_i|_A = 1$ for sufficiently large $i$.
        \item We have
        \begin{equation}
            \lim_{i\to\infty} \int_{\Omega} |\nabla \varphi_i|^2 \, \mathrm{d}\mathcal{H}^n = 0.
        \end{equation}
    \end{enumerate}
\end{enumerate}

[Proposition prop:Yspatial of arXiv:2607.25694, 'Parameter Estimation of the Stochastic Allen--Cahn Equation via variations.'] For every \(t\in[0,T]\), \(x\in \mathbb{T}\), \(h>0\), and \(p\ge2\), it holds that
\begin{equation}
\mathbf{E}\bigl|Y(t,x+h)-Y(t,x)\bigr|^{p}\le C\,h^{\frac{2p}{\beta}},
\end{equation}
for all \(\beta\in(2,3)\).

