[Definition def:unravel of arXiv:2608.08375, 'Algebraic formulas for first-passage times of Markov processes in the linear framework: ge'] Let $G$ be a strongly connected graph, and let $v \in \mathcal{V}(G)$. Then the unravelling of $G$ at vertex $v$, denoted $\mathcal{U}_v[G]$, has vertices $\mathcal{V}(\mathcal{U}_v[G]) = \mathcal{V}(G) \cup \{v^+\}$. The edges and labels of $\mathcal{U}_v[G]$ are acquired from those of $G$ through the following rules. Choose $j, k \in \mathcal{V}(G)$. 
\begin{enumerate}
    \item If $j \to_G k$ with $k \neq v$, then $j \to_{\mathcal{U}_v[G]} k$ and $\ell(j \to_{\mathcal{U}_v[G]} k) = \ell(j \to_G k)$.
    \item If $j \to_G v$, then $j \to_{\mathcal{U}_v[G]} v^+$ and $\ell(j \to_{\mathcal{U}_v[G]} v^+) = \ell(j \to_G v)$.
\end{enumerate}
There are no other edges in $\mathcal{U}_v[G]$.

[Cor const maps loc model of arXiv:2609.02409, 'Membranes and Maps'] For $Z=\mathbb{C}^{5}$, (conj:index of the paper) is equivalent to the identity
    \begin{equation}

        \GWargs{\mathbb{C}^{5}}{\mathsf{T}}{0}
        =
        \frac{1}{2}
        \sum_{g>1}
            \frac{B_{2g-2}}{2g-2}
            \left[
                \frac{\sum_{i=1}^5 \varsigma(2u\epsilon_i)}{\prod_{i=1}^5 \varsigma(u\epsilon_i)}
            \right]_{2g-2}
            u^{2g-2} \,,
    \end{equation}
    where $\sum_{i=1}^5\epsilon_i=0$. \qed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:GLPP-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{n,m,a}$ and $\phi_{n,m,a}$ satisfy the
linear problem (equation eq:Linear-Psi-3 of the paper) and the
adjoint linear problem (equation eq:Linear-Phi-Prob of the paper)
on $\mathcal{V}$ with edge weights
$(c_k, \lambda_k)$.  Explicitly:
\begin{align}
\psi_{n,m+1,a}
&= (1{-}\theta)^{-1}\psi_{n,m,a-1}
   - (1{-}\theta)^{-1}\theta\psi_{n,m,a},
 \\
\psi_{n-1,m,a-1}
&= -q(1{-}q)^{-1}\psi_{n,m,a-1}
   + (1{-}q)^{-1}\theta\psi_{n,m,a},

\end{align}
and
\begin{align}
\phi_{n,m,a-1}
&= (1{-}\theta)^{-1}\phi_{n,m+1,a}
   - (1{-}\theta)^{-1}\theta\phi_{n,m+1,a-1},
 \\
\phi_{n,m,a-1}
&= -q(1{-}q)^{-1}\phi_{n-1,m,a-1}
   + (1{-}q)^{-1}\theta\phi_{n-1,m,a-2}.

\end{align}

[Lemma lem: Estimate Slopes of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Assume (equation eq: Parameters of the paper) and let 
