[Defn def-gff of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] Let $\mathcal A\subset\mathcal V\mathcal G$ be a non-empty finite set.
The \textbf{discrete Gaussian free field on $\mathcal G$ with zero boundary condition on $\mathcal A$ and free boundary condition at $\infty$} is the centered Gaussian random function $\Psi : \mathcal V\mathcal G\to \mathbbm R$ with covariances 
\begin{equation} 
\operatorname{Cov}(\Psi(x) , \Psi(y)) = \frac{G_{\mathcal A}(x,y)}{\pi(y)} 
\end{equation} 
where $G_{\mathcal A}(x,y)$ is as in~(equation eqn-green-finite of the paper).

[Thm 19 ({\cite{QAlg05}*{\S~3.2 Corollary 5.4}}) of arXiv:2609.03836, 'Koszul Orlik--Solomon Algebras from Non-supersolvable Arrangements'] \label[Thm]{thm:regularity_Koszul}
    Suppose $R$ and $S$ are  standard graded $\mathbb{K}$-algebras and we are given a surjective graded $\mathbb{K}$-algebra homomorphism $R \twoheadrightarrow S$. Assume that $S$ has a linear free resolution as a left $R$-module.
    Then $R$ is Koszul if and only if $S$ is Koszul. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] Retain the setting of Theorem \ref{thm:compact-manifold}. When $\mu = \nu$, it holds that
    \begin{align}
        \lim\limits_{T \to +\infty} \exp(\lambda_1 T)(H(Q^{T}|P^{T})+H(P^{T}|Q^{T})) &= \sum_{i \in \mathcal{I}_{1}}p_i^2,
    \end{align}
    where $p_i = \langle \rho, \psi_i \rangle_{L^2(\diffref)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p:k-walk_bound of arXiv:2412.02087, 'The spectral distribution of random graphs with given degree sequences'] [Bounds on an arbitrary $k$-walk]

Suppose an arbitrary $k$-walk consists of $r$ ``good" repeated edges, $p$ ``good" simple edges, and $L$ ``bad" edges. Then the following bound is achieved
    \begin{align}\begin{split}
        &\mathbb{E}\biggl[\left(H_1-\frac{1}{D-1}\right)^{\alpha_1}\left(H_2-\frac{1}{D-1}\right)^{\alpha_2}\cdots\left(H_r-\frac{1}{D-1}\right)^{\alpha_r}
        \\&\left(H_{r+1}-\frac{1}{D-1}\right)\cdots\left(H_{r+p}-\frac{1}{D-1}\right)
        \\&\left(H_{r+p+1} - \frac{1}{D-1}\right)^{\beta_{r+p+1}}\cdots\left(H_{r+p+L} - \frac{1}{D-1}\right)^{\beta_{r+p+L}}



        \biggr]
        \\&\leq \frac{(1+o(1))}{(D-1)^r} \frac{C_p}{(D-1)^{\frac{3p}{2}}} \frac{C_L}{(D-1)^L}.
    \end{split}\end{align}

