[Lemma 13 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] Fix $a\in\{1,\ldots,b-1\}$ and $0\le u\le s$, and let $k\in\mathbb{N}$ be such that $n_s(p_u)\in\{2k-1,2k\}$.  Then
\begin{equation}
 \Pp^{\mathcal T_s,U;a,u}(E_{a,u})
 \le\frac{2u}{d}+\Pi_{\mathcal T_s}(k)^{b-2}.
\end{equation}
 In particular, 
\begin{equation}
 d\,q_U(\mathcal T_s)\le\frac{s^2}{d}+I_s.
\end{equation}

[Lemma l:Capacity00 of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] If~$a\geq 1$, then
\[
 \mathrm{cap}(A)^{1/a} \leq \mathrm{cap}_a(A)\leq a\, \mathrm{cap}(A)\,\mathrm{.}
\]
\begin{proof}
Let~$a>0$.
Since~$(\mssE,\msD(\mssE))$ is recurrent, so is~$\tparen{\mssE^{a},\dom{\mssE^{a}}}$.
Thus, it follows from e.g.~[FukOshTak11] that, for every Borel~$A\subset M$, for every~$a>0$,
\[
\mathrm{cap}_{a}(A) = E_\nu\tbraket{e^{-\tau^{a}_A}}
\]
where
\begin{align*}
 \tau^a_A =&\ \inf\set{t>0: X_{a t} \in A} = \inf\left\{t>0: X_t \in A\right\}/a = \tau_A/a\,\mathrm{.}
\end{align*}
Assume now that~$a\geq 1$.
By the reverse Jensen inequality,
\[
\mathrm{cap}_a(A)=E_\nu\tbraket{e^{-\tau^a_A}} = E_\nu \tbraket{e^{-\tau_A/a}} \geq E_\nu [e^{-\tau_A}]^{1/a} = \mathrm{cap}(A)^{1/a} \,\mathrm{.}
\]

Let us now show the second inequality. For every~$a\geq 1$, for every $\mssE$-capacitable~$A$,
\begin{align*}
\mathrm{cap}_a(A) &= \inf\set{a\mssE(u)+\left\lVertu\right\rVert_{L^2(\nu)}^2 : \car_A\leq u\leq \car \ \mssE\text{-q.e.}}
\\
&\leq a  \inf\set{\mssE(u)+\left\lVertu\right\rVert_{L^2(\nu)}^2 : \car_A\leq u\leq \car \ \mssE\text{-q.e.}} = a\, \mathrm{cap}(A) \,\mathrm{.} \qedhere
\end{align*}
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:S6V-H9 of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed edge weights satisfy the mixed diamond
equation
\begin{align}
\bigl(\mathcal{M}_{t,x-1,m}^{-1}
- \tfrac{1-b_2}{1-b_1}
\mathcal{M}_{t+1,x,m}^{-1}\bigr)
\mathcal{M}_{t,x,m}
- \mathcal{M}_{t+1,x-1,m+1}^{-1}
\bigl(\mathcal{M}_{t+1,x,m+1}
- \tfrac{1-b_2}{1-b_1}
\mathcal{M}_{t,x-1,m+1}\bigr) = 0
\end{align}
at each $z \in \mathbb{C}$ and
$\zeta \in \mathbb{C} \setminus \mathbb{R}_{\ge 0}$ for which all
displayed $\mathcal{M}$-values are defined.

[Lemma l.p(0)=mm+2V of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $p,q\in\mathcal Q_\infty$ satisfy $p= \partial \psi(q)$, let $V(q)$ be given as in~(equation e.V(q)= of the paper), and let $\left\langle\cdot\right\rangle_q$ be given as in~(equation e.<>_q_correct of the paper).
We have
\begin{align}
    p(0)= \mathbb{E} \left\langle \sigma\right\rangle_{q}\mathbb{E} \left\langle \sigma\right\rangle_{q}^\intercal + 2V(q).
\end{align}
In particular, when $p(0)=q(0)=0$, we have $\mathbb{E} \left\langle \sigma\right\rangle_{q}=0$.

[Lemma 18 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] For every $\delta >0$ there exists $c_{11}=c_{11}(\delta)>0$ such that for $\bbQ$-a.a.\ $\omega \in \Omega_{\lambda,\Lambda}$ there exists $N_0(\omega,\delta) \in \bbN$ such that for every $N \geq N_0(\omega,\delta)$
    \begin{equation}
        \sup_{x\in\bbZ^d}|\cL^\omega \bbE^{\omega,+}_N[\varphi_\cdot](x)| \leq \frac{c_{11}}{N^{2-\delta}} \,.
    \end{equation}

