[Defi def:regular of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $c,q\in(0,\infty)$.
We say that an innovation $ (X, U ) $ is \emph{$(c,q)$-regular}
on a set $ \mathcal V \subseteq {\mathbb R}^d $
if and only if for all $\theta\in \mathcal V$, $i\in\{1,\dots,d\}$, $\lambda\in[0,\infty)$
we have that
\bas{
  - \ln {\mathbb E}[e^{-\lambda X^{(i)}(\theta,U)^2}]\ge (c\lambda)\wedge q.
}

[Lemma twop-head of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] The two point Palm probability distribution of the head point process is 

\begin{equation}
\mathbb{P}_{{\mathcal H }}^{(t, h),(t', h')}(B):=\mathbb{P}\left({\mathcal H }^{(t, h), (t', h')}\in B\right),{\nonumber}

\end{equation} 

for any $B\in {\mathcal M }(\mathbb{H}^+)$, with ${\mathcal H }^{(t, h), (t', h')}:={\mathcal H }+ \delta_{(t, h)}+\delta_{(t', h')}$
and ${\mathcal H }$ the stationary version of the head point process. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 (Gaussian determinant benchmark) of arXiv:2607.20329, '2607.20329'] Let $\F\in\{\R,\C\}$ and $\beta=\dim_{\R}\F$.  For $n\ge2$, let $g_n$ be a
		standard $\F$-Gaussian column independent of $\Pi_{n-1,\beta}$.  Then
		\begin{equation}
			C_n^{\det}\ \stackrel{\mathrm d}=\
			\sqrt{\Pi_{n-1,\beta}}\,g_n.
		\end{equation}
		Consequently,
		\begin{align}
			C_n^{\det}(C_n^{\det})^*
			&\stackrel{\mathrm d}=
			\Pi_{n-1,\beta}g_ng_n^*,                              \\
			\|C_n^{\det}\|_2^2
			&\stackrel{\mathrm d}=\Pi_{n,\beta}.

		\end{align}
		Moreover, for every $n\ge1$,
		\begin{equation}
			\Delta_n\ \stackrel{\mathrm d}=\
			\prod_{k=1}^n\frac{\gamma_{k,\beta}}{k}.
		\end{equation}

[Thm 4 (Concentration of the magnetization) of arXiv:2608.18276, 'The branching random walk in a uniform magnetic field : magnetization concentration and ov'] Fix $h>0$ and let $\beta > \beta_c(h)>0$, where $ \beta_c(h)$ is defined by Equation \eqref{eq:beta_c}. Then, for any $\eta>0$,
\begin{align*}
  \lim_{n \to +\infty} \E \left[ \cG_{\beta,h,n}\{ \vert y_n(\sigma) - m^* \vert > \eta \} \right] =  0.
  \end{align*}
More precisely, there exist $c=c(\beta,h,\eta)>0$ and $C=C(\beta,h,\eta)<+\infty$, such that 
\begin{equation}

 \E \left[ \cG_{\beta,h,n}\{ \vert y_n(\sigma) - m^* \vert > \eta \} \right] \le C \ee^{-c n}, \qquad \forall \, n \geq 1,
  \end{equation}
  which implies
  \begin{align*}
\lim_{n\to\infty}\mathcal G_{\beta,h,n}\{\vert y_n(\sigma)-m^*\vert>\eta\}=0, \qquad \textrm{a.s.}
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

