[Theorem thm:NGlimit of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Under the setting of Theorem~(thm:infvol2pt of the paper),  let $f \in \cS (\T^d ; \R^n)$ and $c_1$ and $c_2$ be as in Theorem~(thm:infvol2pt of the paper) and (thm:plateauGen of the paper).
\begin{enumerate}
\item For $c_3 (d,\eta) = c_2 (d,\eta)^{-2}$,
\begin{align}
	\lim_{N\rightarrow \infty} \langle  e^{(\varphi,f_N) / {\sf b}_N} \rangle_{g,\nu_c ,N}  
		= \operatorname{\bf NG} \left( e^{(\psi, f) / c_3^{1/4} }  \right) .
\end{align}

\item For $c_4 (d,\eta) = \gamma(d,\eta) /  c_1 (d,\eta)$,
\begin{align}
	\lim_{N\rightarrow \infty} \langle  e^{(\varphi,f_N - \Phi_N (f_N)) / {\sf c}_N} \rangle_{g,\nu_c ,N}  
		=	
		\operatorname{\bf GF}_{\eta} \big( e^{(\psi,  f - \Phi(f) ) / c_4^{1/2} }  \big) .
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: Quasilinear Formulation of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let 
\begin{equation}

\left|\begin{array}{l}
\tilde{W}=-b\tilde{w}\\
\tilde{\Sigma}=b^2\tilde{\sigma}
\end{array}\right., \ \ 
\left|\begin{array}{l}
\tilde{\psi}=\frac{\tilde{\sigma}}{\tilde{w}}=\tilde{\psi}_{\hskip -.1pc\peye} \phi\\
\tilde{w}=\tilde{w}_{\hskip -.1pc\peye} u
\end{array}\right., \ \ \phi(u)=u+(1-u)\Psi(u)
\end{equation}
then (equation eq: Diagonalized Autonomous System of the paper) is mapped to the quasilinear problem
\begin{eqnarray}

 &&\left[1+H_2+G_2\Psi+\widetilde{\textrm{NL}}_2\right]u(1-u)\frac{d\Psi}{du}\\
\nonumber&+& \left[(1-2u)(1+H_2+G_2\Psi+\widetilde{\textrm{NL}}_2)-\gamma(1+G_1)+2uG_2\right]\Psi\\
\nonumber& = &u\left[\gamma bH_1-2(1+H_2)+\frac{\gamma b\widetilde{\textrm{NL}}_1}{x}-2\widetilde{\textrm{NL}}_2\right]
\end{eqnarray}
where $H_1,H_2,G_1,G_2$ are explicit polynomials in $(b,u)$ given by (equation eq: H_i of the paper), (equation eq: G_i of the paper), and the nonlinear terms $(\widetilde{\textrm{NL}}_{i})_{i=1,2}$ are given by (equation eq: NL_i of the paper).
Moreover, 
\begin{equation}

\left|\begin{array}{l}
\tilde{w}_{\hskip -.1pc\peye}=\frac{(c^\infty_+-c^\infty_-)\mu_+^\infty}{\tilde{d}_{20}^\infty}+\mathcal O(b)\\
\tilde{\psi}_{\hskip -.1pc\peye}=-\frac{\tilde{e}^\infty_{20}\mu^\infty_+}{\tilde{d}^\infty_{20}\lambda^\infty_-}+\mathcal O(b).
\end{array}\right.
\end{equation}

