[Definition JM of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \textbf{} A random vector $X=(X_{1},\ldots ,X_{d})$ is \textit{
jointly mixable} if there exists $k\in R$ such that 
\begin{equation}
\sum_{i=1}^{d}X_{i}=k\quad \text{a.s.}  
\end{equation}
\medskip

[Lemma 35 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Let~$\sigma\in(0,1/10)$ and let~$\gamma_{n,a}$ be as in \eqref{E:6.34ii}. For each~$a\ge0$ there exists a constant~$c'>0$ such that for all $n,k\ge1$ with $2k\le n$, all $s\ge 0$, all $u\le s$ and all $v>0$,
\begin{equation}

\begin{aligned}
Q_{n,s,u}\Biggl(\Bigl\{h(x_k)<&\frac {n-k}n\wt m_n+s-v\Bigr\}\,\cap\,\bigcap_{i=1}^n\Bigl\{h(x_i)\le\frac {n-i}n\wt m_n+s+\gamma_{n,a}(i)\Bigr\}\Biggr)
\\
&\le
c'\frac{(1+s-u)(1+s)}nE\biggl((1+X_k)^2 1_{\{X_k>v\}}\,\bigg|X_0=s-u,\,X_n=s\biggr).
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

