[Lem 5 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] The stationary density \(\pi\) satisfies 
    \begin{equation}
   \pi(0)e^{-K\Vert x\Vert_2^2}
   \leq \pi(x)
   \leq \pi(0)e^{-\varkappa\Vert x\Vert_2^2},
   \quad \forall\,x\in\R^d.
   \end{equation}
   In addition, \(\pi\) satisfies the Log-Sobolev and Poincar\'e inequalities with constants \(C_{\mathrm{LSI}}\) resp.\ \(C_\mathrm{Poin}\) such that
   \begin{equation}
   C_\mathrm{Poin}
   \leq C_{\mathrm{LSI}}
   \leq \frac{1}{2\Xi(0)}
   \exp\left\{
   \frac{L_{\mathrm{Lip}}(\Xi)\pi(0)}{\kappa}
   \right\}.
   \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem : Topology/RegPD/HW_simple_ptys of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] We adopt the same notations as in Definition~(def : Topology/RegPD/HW of the paper). 
	\begin{enumerate}[(i)]
		\item For all $K\ge 0$, $\HW{D}{ (\sigma_k)_{1\le k \le K} } \in \RegPD[\mu]$.
		\item For all $K\ge 0$,
		\begin{equation}

			\HW{D}{ (\sigma_k)_{1\le k \le K} } \ge \HW{D}{ (\sigma_k)_{1\le k \le K +1} } \ge D.
		\end{equation}
		\item If the sequence $\bigl( ( \sigma_k(0) , \sigma_k(L) ) \bigr)_{k\ge 1}$ is dense in $X^2$ for the usual topology, then
		\begin{equation}

			D= \lim_{K\to \infty} \HW{D}{ (\sigma_k)_{1\le k \le K} }.
		\end{equation}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm|generalUpperBounds of arXiv:2504.08938, 'Fourier Levels and Almost Sure Bounds on Higher-Order Derivatives in First-Passage Percola'] The sequences $(\mathcal U_k)$ and $(\mathcal L_k)$ satisfy 
\begin{eqnarray} 
&& \mathcal U_{k+1}\leq \mathcal U_k -\mathcal L_k\quad\mbox{and}\quad \mathcal L_{k+1}\geq \mathcal L_k-\mathcal U_k, \end{eqnarray} for all $k\geq 1$. Moreover, for all $k\geq 2$,
\begin{eqnarray}
&& \mathcal U_k \leq 2^{k-2}\quad\mbox{and}\quad \left|\mathcal L_k\right| \leq 2^{k-2}. \end{eqnarray}
Also, for all integers $k \geq 2$, the following holds:
\begin{eqnarray}&& \mathcal U_k \geq \binom{k-2}{\lceil\frac{k-2}2\rceil} \quad\mbox{and}\quad \left|\mathcal L_k\right| \geq \binom{k-2}{\lceil\frac{k-2}2\rceil}.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 4 of arXiv:2609.01101, '2609.01101'] Let $K/\Q$ be a fixed Galois extension, and assume GRH for $\zeta_K$.
Then, for every fixed real $k>0$ and all sufficiently large $T$,
\begin{equation}
\int_T^{2T}
\left|\zeta_K\left(\tfrac12+it\right)\right|^{2k}\,dt
\gg_{K,k}
T(\log T)^{[K:\Q]k^2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 32 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] The following (resp. deterministic and random) partitions (i.e. disjoint unions) hold:
\begin{equation}
    [k]_0^K=\bigcup_{y\in \mathcal A_{\rmleft},z\in \mathcal A_{\rmright}}\bigcup_{x\in A_{y,z}^{\stable}} B_x\quad\text{ and }\quad [N]=\bigcup_{y\in \mathcal A_{\rmleft},z\in \mathcal A_{\rmright}}\bigcup_{x\in A_{y,z}^{\stable}} \cI(B_x).
\end{equation}

[Corollary cor:est-S3 of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] For any $\beta\in(1-\frac{\alpha}{2},(\alpha-1)(1+\alpha))$ and $0<\epsilon$ there exists a constant $N=N(\alpha,\beta,d,\|b\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}},\epsilon)$ independent of $n$ so that for any $(s,t)\in[0,1]_\leqslant^2$ and any $\sigma$-algebra ${\mathscr G}\subset{\mathcal F}_{s}$ the following holds
     \begin{align}
          \|S_{s,t}^{b,n,3}\|_{L_2(\Omega)|{\mathscr G}} \leqslant& N|t-s|^{\frac{1}{2}+\epsilon}n^{-(\frac{1}{2}+\frac{\beta}{(1+\alpha)\alpha}\wedge\frac{1}{2})+2\epsilon}.
     \end{align}

