[Proposition mart-m2 of arXiv:2512.10625, 'Bessel and Dunkl processes with drift'] For all $x,\lambda\in\mathbb R^N$ and $j,l=1,\ldots,N$, 
  $$  L_k^{\lambda,Dunkl}m_{2; j,l}(x) =\delta_{j,l} + \lambda_j m_{1,l}(x) +\lambda_l m_{1,j}(x),$$
Moreover, if $(X_t^\lambda)_{t\ge0}$ is a  Dunkl processs
  with drift $\lambda$  such that the starting distribution  $P_{X_0}^\lambda\in M^1(\mathbb R^N)$ has second moments,
  then for all $j,l=1,\ldots,N$,
  \begin{align}
  ( m_{2; j,l}(X_t^\lambda)- E( m_{2; j,l}(X_t^\lambda)) &- m_{1;l}(X_t^\lambda)E( m_{1;j}(X_t^\lambda))- m_{1;j}(X_t^\lambda)E( m_{1;l}(X_t^\lambda))
  \notag \\ &+2E( m_{1;l}(X_t^\lambda))E( m_{1;j}(X_t^\lambda)) )_{t\ge0}
  \end{align}
  is a martingale.
  In particular, for $P_{X_0}^\lambda=\delta_0$ and $l,j=1,\ldots,N$,
  \begin{equation}
    E(m_{2; l,j}(X_t^\lambda))= t\delta_{j,l}+t^2 \lambda_j\lambda_l.\end{equation}

[Lemma lem:ReductionLemma of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] For any $\mathbf{w}\in\mathbb{S}^{d-1}$ let $\mathbf{v}=(v_1,\ldots,v_m)\in \mathbb{S}^{m-1}_+\subset W_m$ be such that $\mathbf{w} = (v_1 \mathbf{u}_1,\ldots,v_m\mathbf{u}_m)$ for some $\mathbf{u}_i\in\mathbb{S}^{d_i-1}$, $i\in\{1,\ldots,m\}$. Then, for all $\operatorname{bd}=(d_1,\ldots,d_m)$ with $d_i\ge 1$ and all ${\boldsymbol{\beta}}=(\beta_1,\ldots,\beta_m)$ with $\beta_i>-1$, $i\in\{1,\ldots,m\}$ we have that
        \begin{equation*}
        \mathbb{P}_{d}(Z_{\operatorname{bd}}\cap H^+(\mathbf{w},s);{\boldsymbol{\beta}},\operatorname{bd}) = \left(\prod_{i=1}^m \frac{c_{\beta_i,d_i}}{c_{\beta_i,d_i-1}c_{\beta_i}}\right) \mathbb{P}_{m}(C^+(\mathbf{v},s);(\operatorname{bd}-\mathbbm{1})/2+{\boldsymbol{\beta}}),
    \end{equation*}
    and
    \begin{equation}
    \operatorname{Vol}_{d-1}(Z_{\operatorname{bd}}\cap H(\mathbf{w},s); {\boldsymbol{\beta}},\operatorname{bd})=\left(\prod_{i=1}^m \frac{c_{\beta_i,d_i}}{c_{\beta_i,d_i-1}c_{\beta_i}}\right)\operatorname{Vol}_{m-1}(C(\mathbf{v},s);(\operatorname{bd}-\mathbbm{1})/2+{\boldsymbol{\beta}}),
    \end{equation}
    where $c_{\beta,d}$ and $c_{\beta}$ are the normalizing constants of the beta density given by (equation eq:CbetaConstant of the paper).

[Lemma l-cross of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] For each $n\geq 0$, the function $L_{n}$ has two fixed
points at $0$ and $1$, and a unique fixed point in $(0,1)$. If we denote the
latter by $c_{n}$, then
\begin{equation}
L_{n}(x)<x\quad \text{for }x\in (0,c_{n}),\qquad L_{n}(x)>x\quad \text{for }
x\in (c_{n},1).  
\end{equation}

Moreover, there exists a closed interval $O_{n}\subset (0,1)$ such that $
c_{n}\in O_{n}$ and 
\begin{equation}
L_{n}^{\prime }(x)\geq 1\quad \text{for all }x\in O_{n}.  
\end{equation}

[Theorem thm:exist+ of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] For each $n_0 \in \mathbb{N}$, and $M_{n_0} \leq j \leq N_{n_0}$, the following limits exist almost surely, uniformly on compact subsets of $[0,\infty)$:
\begin{equation} 
X_j = \lim_{\substack{n \to \infty, \\ n \geq n_0}}  X_j^{[n,n]}, \quad\quad L_{(j,j+1)} = \lim_{\substack{n \to \infty, \\ n \geq n_0}} L_{(j,j+1)}^{[n,n]}, 
\end{equation}
\begin{equation} 
X_j^- = \lim_{\substack{n \to \infty, \\ n \geq n_0}} \lim_{\substack{m \to \infty, \\ n,m\geq n_0}} X_j^{[m,n]}, \quad\quad L_{(j,j+1)}^- = \lim_{\substack{n \to \infty, \\ n \geq n_0}} \lim_{\substack{m \to \infty, \\ n,m\geq n_0}} L_{(j,j+1)}^{[m,n]},
\end{equation}
\begin{equation} 
X_j^+ = \lim_{\substack{m \to \infty, \\ m \geq n_0}} \lim_{\substack{n \to \infty, \\ n,m\geq n_0}} X_j^{[m,n]}, \quad\quad L_{(j,j+1)}^+ = \lim_{\substack{m \to \infty, \\ m \geq n_0}} \lim_{\substack{n \to \infty, \\ n,m\geq n_0}} L_{(j,j+1)}^{[m,n]}.
\end{equation}
Moreover, the processes $\{(X_j,L_{(j,j+1)})\}_{j \in \mathbb{Z}}$, $\{(X^{\pm}_j,L_{(j,j+1)}^\pm)\}_{j \in \mathbb{Z}}$ solve (equation eq:asym_eq of the paper) (with initial data $\{x_j\}$ and Brownian motions $\{B_j\}$). The collections of local times $\{L_{(j,j+1)}\}$, $\{L_{(j,j+1)}^\pm\}$  satisfy the assumption (equation eq:aloc of the paper). Furthermore, the three solutions coincide: $X_j = X_j^- = X_j^+$, and $L_{(j,j+1)} = L_{(j,j+1)}^- = L_{(j,j+1)}^+$ for all $j \in \mathbb{Z}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 8 (Class $C^1(\mathbb{R}^2)$) of arXiv:2605.18198, 'Large deviations of crowding in finite $\beta$-ensembles'] A map $Q$  is said to be a continuously differentiable function on $\R^2$ if the first partial derivatives
	\(
	\frac{\partial Q}{\partial x_1} \mbox{ and }
	\frac{\partial Q}{\partial x_2}
\)
	exist at every point of $\mathbb{R}^2$ and are continuous functions on $\mathbb{R}^2$. The set  of all continuously differentiable functions on $\R^2$ are denoted by $C^1(\mathbb{R}^2)$.

[Defn def:type2constant of arXiv:2411.10633, 'A Geometric Perspective on the Injective Norm of Sums of Random Tensors'] Given $r\geq 2$ an integer and $2 \leq p < \infty$ we define $\mathcal{C}_{r,p}(d)$ the Type-2 constant of the $\ell_p$ injective norm of order $r$ tensors to be the minimal number, such that for all positive integers $n$ and tensors $T_1, \ldots, T_n \in (\mathbb R^d)^{\otimes r}$ we have
\begin{equation}
    \mathbb E \Big\| \sum_{k=1}^n \varepsilon_k T_k\Big\|_{\mathcal{I}_p}^2 \leq \mathcal{C}_{r,p}(d)^2 \sum_{k=1}^n \left\lVertT_k\right\rVert_{\mathcal{I}_p}^2.
\end{equation}
The $\varepsilon_1, \ldots, \varepsilon_n$ are i.i.d. Rademacher random variables (i.e.: $ \varepsilon_k = 1$ or $\varepsilon_k = -1$ with probability $\frac12$ each).

