[Proposition 10 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $a_0>0$ and $\delta>0$ be chosen sufficiently small and let $(\ell_q)_{q \in \N}$, $(\kappa_q)_{q \in \N}$, $(t_q)_{q \in \N}$ be defined as in Section~\ref{subsec:parameters}; let $u$ be the velocity field constructed in Section~\ref{subsec:construction_velocity} and $(u_q)_{q\in\N}$ be given by~\eqref{eq:defn_uq}. Let $A^{(j)}\subset \T^2$ be the set defined in~\eqref{d:A-j} for any $j \in \N$. 

Then, for any $q\in \N$ there exists $\bar{q}= \bar{q} (q) \to \infty$ as $q \to \infty$, such that the following property holds true for any $q\in\N$. If $X^{\kappa_q}(y)$ is a solution to~\eqref{eq:pathwise-sde} and $\|\xi\|_\infty \leq q$, then for all $x\in A^{(\bar{q})}$ it holds that
\begin{equation}

\sup_{t\in [0,t_q]} \left|X_t^{\kappa_q}(y) - X_t^q (x) \right| \leq 2 q^2 \kappa_q \norm{\xi}_{\infty} + \frac{\ell_q}{2q}\quad \text{for all $y$ such that}\quad |y-x| < q\kappa_q \norm{\xi}_{\infty} + \frac{\ell_q}{2q^2} \,,
\end{equation}
where $X_t^q$  denotes the Lagrangian flow  associated with the smooth vector field $u_q$.

[Lemma 16 (Smooth lattice approximate identity) of arXiv:2608.22342, 'Completely Positive Entropy and Fourier Central Limit Theorems for Stationary Random Measu'] For every $h\in C_c^\infty(\bR^d;\bC)$ and every $N\geq1$, there is
$C_{h,N}<\infty$ such that, for $R\geq1$ and $s\in\bT^d$,
\begin{equation}

    K_R^h(s)
    \leq C_{h,N}R^d
      \bigl(1+R\|s\|_{\bT^d}\bigr)^{-N}.
\end{equation}
Moreover,
\begin{equation}

    \int_{\bT^d}K_R^h(s)\,ds
    =R^{-d}\sum_{k\in\bZ^d}|h(k/R)|^2
    \longrightarrow\|h\|_2^2.
\end{equation}
Consequently, if $q\in L^1(\bT^d)$, the chosen representative satisfies
$q(0)=0$, and $0$ is a Lebesgue point in the sense of
\eqref{eq:torus-lebesgue-point-definition}, then
\begin{equation}

    \int_{\bT^d}K_R^h(s)q(s)\,ds\longrightarrow0.
\end{equation}

[Theorem existence_riccati of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $\bm p \in \mathcal B\,$. Assuming that $\mathbb{E}[\exp(\bracket{\bm p}{\sigW[t,T]})] \neq 0$ for all $t \in [0,T]\,$, and letting $\bm \psi$, $\varepsilon$, and $r$ be as in Theorem (theorem:log_analyticity_general of the paper), we have
    \begin{enumerate}
        \item For any ${\color{NavyBlue}{\mathbf{v}}} \in V\,$, the function $t \mapsto \bm \psi_t^{{\color{NavyBlue}{\mathbf{v}}}}$ is $C^1$ on $[0\,, T]\,$.
        \item The following equation is satisfied:
    \begin{equation}
        \begin{cases}
            \dot{\bm{\psi}}_t  + \mathscr{R}\bm{\psi}_t = 0\,, \quad t \in [0, T]\\
            \bm \psi_T = \bm p
        \end{cases}
        \end{equation}
        \item {For any ${\color{NavyBlue}{\mathbf{v}}} \neq {\color{NavyBlue}{\mathbf{\varnothing}}}\,$, there exists a constant $C'_{\bm{p}, T, {\color{NavyBlue}{\mathbf{v}}}} > 0$ such that for all $\sigX[] \in G_{\bm{p}, r}$,} 
        $$
        \sup_{t \in [0,T]}\|\bm{\psi}_t|_{{\color{NavyBlue}{\mathbf{v}}}}\|_{\sigX[]} \leq C'_{\bm{p}, T, {\color{NavyBlue}{\mathbf{v}}}} \left(\left(1 + \frac{1}{\varepsilon \inf_{t \in [0,T]} |\bm{u}_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}|}\right)(1 + M_{\bm{p}}(\sigX[])) \exp\left(C_{\bm{p}, T} (1 + M_{\bm{p}}(\sigX[]))^{\deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm{p})} \right)\right)^{|{\color{NavyBlue}{\mathbf{v}}}|}.
        $$

    \end{enumerate}

[Lemma lem-LDPtechnical of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] On a Polish space ${\mathcal X }$, assume that an i.i.d.~sequence $(X_z)_{z\in[N]}$ is given  and another sequence $(X_z^{{{\scriptscriptstyle{({N}})}}})_{z\in[N]}$ that satisfies
\begin{equation}
\lim_{N \to\infty}\frac 1N\sum_{z=1}^N \log \mathbb{E}\big[{\operatorname e }^{f(X_z^{{{\scriptscriptstyle{({N}})}}})}\big] =\log\mathbb{E}[{\operatorname e }^{f(X_1)}],\qquad f\in{\mathcal C }_{\rm b}({\mathcal X }).
\end{equation}
Then the empirical measures $\frac 1N\sum_{z=1}^N \delta_{X_z^{{{\scriptscriptstyle{({N}})}}}}$ and $\frac 1N\sum_{z=1}^N \delta_{X_z}$ are exponentially equivalent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:resolventconvergence of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
	 Fix $\alpha, \alpha' \in \mathsf{Pair}[\![n]\!]$ with $\alpha \neq \alpha'$. Then, there exists a $\theta_{\star} \in \mathbb{R}$ for which the following holds: for every $\lambda \gtrsim e^{2\theta+ 4\pi\mathfrak{K}} + 1$, there exists $\varepsilon_{0}(\lambda) > 0$ such that for all $\varepsilon < \varepsilon_{0}(\lambda)$, the prelimiting resolvents satisfy the following:
	\begin{subequations}
	\begin{align}
	\normop{\mathcal{G}_{\varepsilon\alpha}(\lambda)}  & \lesssim \lambda^{-\frac{1}{2}} \qquad \qquad \qquad   \text{ and } \qquad \qquad \quad \normop{\mathcal{G}_{\varepsilon\alpha}(\lambda) -\mathcal{G}_{\alpha}(\lambda)} \to 0,    \\ 
	\normop{\mathcal{G}^{\ast}_{\varepsilon \alpha}(\lambda)} & \lesssim \lambda^{-\frac{1}{2}} \qquad \qquad \qquad   \text{ and } \qquad \qquad \quad \normop{\mathcal{G}^{\ast}_{\varepsilon \alpha}(\lambda) -\mathcal{G}^{\ast}_{\alpha}(\lambda)} \to 0,  \\
	\normop{\mathcal{G}_{\varepsilon \alpha\alpha'}(\lambda)} & \lesssim 1 \qquad \qquad \qquad  \quad \, \text{  and } \qquad \qquad \quad \normop{\mathcal{G}_{\varepsilon \alpha\alpha'}(\lambda) -\mathcal{G}_{\alpha\alpha'}(\lambda)} \to 0,  \\
	\normop{\prediag{\theta}{\alpha}(\lambda)} & \lesssim (\log\lambda - \theta )^{-1}  \quad \quad \,   \text{ and } \qquad \qquad \quad \prediag{\theta}{\alpha}(\lambda) -\diag{\theta_{\star}}{\alpha}(\lambda) \to 0 \, \, \text{strongly}\, \, . 
	\end{align}
	\end{subequations}
	Moreover, the series in equation~(equation eqn:prelimiting_resolvent of the paper) converges absolutely in operator norm, and the whole expression converges strongly to the limiting resolvent defined in equation~(equation eqn:limiting_resolvent of the paper).

[Theorem 35 (Kernel support theorem) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] For every $r$,
\begin{equation}
 \ker(\operatorname{gr}_r\mathcal R)
 =\operatorname{supp}_L\bigl(\mathfrak K_r(\mathcal R)\bigr)^\perp
 \subseteq G_r^*.

\end{equation}
Consequently, $\mathcal R$ is strict if and only if
\begin{equation}
 \operatorname{supp}_L\bigl(\mathfrak K_r(\mathcal R)\bigr)=G_r
 \quad\text{for every }r.

\end{equation}
Primal symbol exposure and dual depth detection are the two tensor legs of
one canonical kernel.

[Prop contpairdouble of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] There exists a positive contact pair $\big(\overline{\xi}_-, \overline{\xi}_+\big)$ on $\overline{M}$, the doubling of $M$, which is transverse to $\overline{\Phi}$, and whose unstable plane field $\overline{\eta}$ satisfies \begin{align}
        \overline{\eta} = \langle \partial_\tau \rangle \oplus T \mathcal{G}
    \end{align}
    in the collar region $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

