[Lemma 26 (Cutoff estimates) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] Let $J_\nu$ be the cutoff used in
\eqref{eq:Friedrichs-mass}--\eqref{eq:Friedrichs-momentum}.  If
$0\le r\le q$, then
\begin{equation*}
 \norm{(I-J_\nu)f}_{H^r}
 \le C\nu^{r-q}\norm f_{H^q},\qquad
 \norm{J_\nu f}_{H^q}\le C\norm f_{H^q}.
\end{equation*}
In particular, for a family bounded in $H^s$,
\[
 \norm{(J_\nu-J_\mu)f}_{H^{s-1}}
 \le C(\nu^{-1}+\mu^{-1})\norm f_{H^s}.
\]
For a family bounded only in $H^{s-1}$, the estimate actually used on the
nonlinear hyperbolic right-hand side is
\begin{equation*}
 \norm{(J_\nu-J_\mu)f}_{H^{s-2}}
 \le C(\nu^{-1}+\mu^{-1})\norm f_{H^{s-1}}.
\end{equation*}
Moreover, for a coordinate derivative $\partial_k$ and an integer $m\ge0$,
\begin{equation}
 \norm{[J_\nu,a]\partial_k f}_{H^m}
 \le C_m\left(\norm{\nabla a}_{L^\infty}\norm f_{H^m}
 +\norm{\nabla a}_{H^m}\norm f_{L^\infty}\right),

\end{equation}
with a constant independent of $\nu$ whenever the right-hand side is
finite.

[Lemma 46 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $p>2$. There exists $C>0$ such that, for any $t,\lambda \in \R$, 
	\begin{align}
		\abs{g(t) - g(\lambda) - (t-\lambda)g'(\lambda) - \frac{(t-\lambda)^2}{2} g''(\lambda)} 
		& \leq C \abs{t-\lambda}^3 (\abs{\lambda} \vee \abs{t})^{p-3},
		 \\

		\abs{g'(t) - g'(\lambda) - (t-\lambda) g''(\lambda)} 
		& \leq C \abs{t-\lambda}^2 (\abs{\lambda} \vee \abs{t})^{p-3},
		 \\

		\abs{g''(t) - g''(\lambda)} 
		& \leq C \abs{t-\lambda} (\abs{\lambda} \vee \abs{t})^{p-3}.

	\end{align}

