[Proposition prop:dgt4-linearization of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Fix $T>0$ and let $n_R\coloneqq\lfloor R^2T\rfloor$. For every
	$\varphi\in C_c^\infty(\mathbb{R}^d)$,
	\begin{equation}
	\begin{aligned}
		\mathbb{E}\Biggl[\Biggl(
		R^{(d-4)/2}
		\Biggl(
		u_{n_R}-\mathbb{E} u_{n_R}(0)
		-\sum_{j=0}^{n_R-1}
		\left(1-\frac{j}{R^2T}\right)^\kappa P^j\zeta
		\Biggr)^{(R)}(\varphi)
		\Biggr)^2\Biggr]
		\longrightarrow0\, .
	\end{aligned}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:annular-frequency-grid-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] For every \(n\ge1\), there exists a finite set \(\mathcal N_n\subset\{\xi\in\mathbb{R}^2:2^n\le\lvert\xi\rvert\le2^{n+1}\}\) such that for every \(\xi\) with \(2^n\le\lvert\xi\rvert\le2^{n+1}\), there exists \(\eta\in\mathcal N_n\) satisfying
\begin{equation}
\lvert\xi-\eta\rvert\le \frac{1}{8\pi}2^{-(s/2+\varepsilon)n}.
\end{equation}
Moreover,
\begin{equation}
\#\mathcal N_n\le C2^{(2+s+2\varepsilon)n}.
\end{equation}

[Lemma 4 (Comparison of admissible increments) of arXiv:2608.12225, 'Higher-order variation and\\ pathwise It\^o calculus on manifolds'] Let $e$ and $\widetilde e$ be two admissible increment maps. Let
$K\subset M$ be compact. There exists a neighborhood $U$ of the diagonal in $K\times K$
and 
$C_K>0$ such that for $(x,y)\in U$
\begin{equation}
    \left|
        e(x,y)^{\otimes p}
        -
        \widetilde e(x,y)^{\otimes p}
    \right|
    \leq
    C_K\,d_g(x,y)^{p+1}

\end{equation}
and
\begin{equation}
    C_K^{-1}d_g(x,y)
    \leq
    |e(x,y)|_g
    \leq
    C_Kd_g(x,y),

\end{equation}
and the same estimate holds for $\widetilde e$.

[Theorem 48 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] For a normed space $E$ the following conditions are equivalent:
\item[(i)] $\dim E<\8$;
\item[(ii)] $F:=\Co_{\ph}\left(\Ba_{E^{*}},\mathrm{w}^{*}\right)$ is a regular sublattice of $\Co\left(\Ba_{E^{*}},\mathrm{w}^{*}\right)$;
\item[(iii)] $F$ is $1$-monotonically bounded;
\item[(iv)] $F$ is semicontinuous, that is $\Ba_{F}$ is order closed in $F$;
\item[(v)] $F$ is pointwise demicontinuous;
\item[(vi)] $F$ is not anti-demicontinuous, that is the order adherence of $\Ba_{F}$ is not equal to $F$.

[Theorem thm:avg_meas of arXiv:2412.05239, 'Conditions for uniform in time convergence: applications to averaging, numerical discretis'] Suppose (ass_avg_meas of the paper) holds. Let $\nu$ be a probability measure on $\mathbb{R}^n\times \mathbb{R}^d$. Then there exists a constant $\tilde{\mathbf{C}}>0$ such that for all $t\ge 0$ and $\delta>0$,
    \begin{align}
        \mathbf{dist} (\nu^x\bar{p}_t, (\nu p_t^{\delta})^x)\le \tilde{\mathbf{C}}\delta^{\alpha}\,.
    \end{align}
    The constant $\tilde{\mathbf{C}}$ depends on the initial distribution $\nu$ and the constants $C$, $\lambda$ and $\tau$ given in (ass_avg_meas of the paper).

