[Thm 4.1 of arXiv:2608.00420, '{Weighted $L^p$ solutions of scalar BSDEs with general unbounded stochastic coefficients}\'] Assume that $\xi$ and $\xi'$ are two terminal values, $g$ and $g^{\prime}$ are two generators, and $(Y_\cdot, Z_\cdot)$ and $\left(Y_\cdot^{\prime}, Z_\cdot^{\prime}\right)$ are, respectively, solutions of BSDE$(\xi,\tau,g)$ and BSDE$\left(\xi^{\prime}, \tau, g^{\prime}\right)$. If $(Y_\cdot-Y_\cdot^{\prime})^+\in S_\tau^p(\rho_\cdot;{\mathbb R})$ and $\xi \leq \xi^{\prime}$, and either of the following conditions is satisfied:\vspace{0.2cm}

(i) $g$ satisfies (A:H2 of the paper)(iv)-(v), and $g\left(t, Y_{t}^{\prime}, Z_{t}^{\prime}\right) \leq g^{\prime}\left(t, Y_{t}^{\prime}, Z_{t}^{\prime}\right), \ \ t\in[0,\tau];$\vspace{0.1cm}

(ii) $g^{\prime}$ satisfies (A:H2 of the paper)(iv)-(v), and $g\left(t, Y_{t}, Z_{t}\right) \leq g^{\prime}\left(t, Y_{t}, Z_{t}\right), \ \ t\in[0,\tau],$\vspace{0.2cm}

\noindent then for each $t \in[0,\tau]$, we have $Y_{t} \leq Y_{t}^{\prime}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary c:WellposednessExtended of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] In the setting of Theorem~(t:DirInt of the paper), suppose further that Assumption~(ass:ContinuityH of the paper) is satisfied.
Then, there exists a unique Hunt process
\begin{equation}
\widehat\boldsymbol\mssW\eqdef \tparen{\widehat\Omega,\widehat\msF,
\widehat\mbfX_\bullet, \ttseq{\widehat P_{\mbfs,\mbfx}}_{(\mbfs,\mbfx)\in\widehat\mbfM}}\,\mathrm{,}\;\, 
\end{equation}
with~$\widehat\mbfX_\bullet$ and~$\widehat P_{\mbfs,\mbfx}$ as in~(equation eq:i:t:DirInt:6:0 of the paper), with transition semigroup~$\widehat\boldsymbol\mssp_\bullet$ satisfying
\begin{enumerate}[$(i)$]
\item $(t,\mbfx,\mbfy)\mapsto \widehat\boldsymbol\mssp_t\big({(\mbfs,\mbfx),(\mbfs,\mbfy)}\big)$ is continuous on ${\mathbb R}^+\times \mbfM^{\scriptscriptstyle\times 2}$ for every~$\mbfs\in\mbfT$;
\item $\widehat\boldsymbol\mssp_t\tparen{(\mbfs,{\,\cdot\,}),(\mbfs,{\,\cdot\,})} \in \mcC_b(\tau_\mrmp^{\scriptscriptstyle\times 2})$ for every~$t>0$ and for every~$\mbfs\in\mbfT$;
\item $\widehat\boldsymbol\mssp_t\tparen{(\mbfs,{\,\cdot\,}),(\mbfs',{\,\cdot\,})}\equiv 0$ everywhere on~$\widehat\mbfM^{\scriptscriptstyle\times 2}$ for every~$\mbfs,\mbfs'\in\mbfT$ with~$\mbfs\neq\mbfs'$;
\item $\int \widehat\boldsymbol\mssp_t \mbfu\tparen{(\mbfs,{\,\cdot\,}),(\mbfs,\mbfy)}\mathop{}\!\mathrm{d}\widehat\boldsymbol\nu_\pi(\mbfs,\mbfy)$ is a $\widehat\boldsymbol\nu_\pi$-version of~$\widehat\boldsymbol\mssH^\pi_t \mbfu$ for every~$\pi\in\msP(\mbfT)$. In particular, $\widehat\boldsymbol\nu_\pi$ is $\widehat\boldsymbol\mssp_\bullet$-super-median for every~$\pi\in\msP(\mbfT)$;
\item for every~$\mbfu\in \mcC_b(\mbfT)\otimes\Cyl{}{}$, for every~$(\mbfs,\mbfx)\in\widehat\mbfM$, the process
\begin{equation}
M^{\class{\mbfu}}_t\eqdef \mbfu(\widehat\mbfX_t)- \mbfu(\widehat\mbfX_0)-\int_0^t (\widehat\boldsymbol\mssL \mbfu)(\widehat\mbfX_s)\mathop{}\!\mathrm{d} s
\end{equation}
is an adapted square-integrable $\widehat P_{(\mbfs,\mbfx)}$-martingale with predictable quadratic variation
\begin{equation*}
\tsharpb{M^{\class{\mbfu}}}_t = \int_0^t \widehat\boldsymbol{\mathsf{\Gamma}}(\mbfu)(\widehat\mbfX_s)\mathop{}\!\mathrm{d} s \,\mathrm{.}
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

