[Corollary cor:dissipation-closure of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Under the assumptions of (thm:sharp-rigidity of the paper), for all $k \ge T_{\mathrm{rigid}}(\delta)$,
\begin{equation}
\left| \frac{E_k - E_{k+1}}{E_k} - (1 - \lambda_2^2) \right|
\le (1 - \lambda_3^2) \, \delta + (1 - \lambda_n^2) \left(\frac{\lambda_3}{\lambda_2}\right)^{2k} \frac{R_0}{|c_2|^2}.
\end{equation}
For $k$ large enough that the second term is negligible, the relative dissipation rate satisfies $d_k = 1 - \lambda_2^2 + O(\delta)$.

[Thm 11 of arXiv:2606.31287, '\bf Heat kernel lower bound estimates for symmetric pure jump processes via averaged jump '] Suppose that   ${\rm J}_{\phi,\le}$ and ${\rm CSJ} (\phi)$ hold. 
 Then the following are equivalent. 
  \begin{enumerate}
  \item[\rm (i)]   ${\rm PI}(\phi) $ holds; 


\item[\rm (ii)]   $(\sE, \sF)$ is conservative,   and both ${\rm UHK}(\phi)$ and  ${\rm NLHK}(\phi)$   hold;

\item[\rm (iii)]   $(\sE, \sF)$ is conservative,  and both   ${\rm UHK}(\phi)$ and  ${\rm NDL}(\phi)$ hold.
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop:Kdecomp of arXiv:2504.18739, 'discrete analogues of second-order Riesz transforms'] For all $j,k=1, 2, \ldots, d$ and all $m\in \mathbb{Z}^d\setminus\{0\}$, we have 
\begin{align}
    \mathcal{K}^{(jk)}(m) =  U(m)K^{(jk)}_{\mathrm{dis}}(m),
\end{align}
where
\begin{align*}
    U(m)=  -\frac{1}{\pi^{d/2}\Gamma((d+2)/2)}\int_0^\infty\int_{\mathbb{R}^d} \frac{s^{\tfrac{d}{2}}e^{-s-|z|^2}}{H\left(\tfrac{z|m|}{2\sqrt{s}}+\tfrac{m}{2}, \tfrac{|m|^2}{4s}\right)} \, dzds.
\end{align*}

