[Lemma lem:2step of arXiv:2608.04162, 'Correlation Matrices in High Dimensions:\\ The Elliptope as a Sample-Correlation Ensemble'] Suppose that $n=2k$ is even. Then
\begin{equation}    
\frac{\operatorname{Vol}(\mathcal{E}_{n+1})}{\operatorname{Vol}(\mathcal{E}_{n-1})  }
        =    
            \pi^n\frac{k}{n^{n}}\binom{n}{k}  
      \quad\text{and}\quad
     \frac{\operatorname{Vol}(\mathcal{E}_{n+2})}{\operatorname{Vol}(\mathcal{E}_n) }
     =   \pi^n \frac{2^{2n+1}}{(n+1)^{n+1}}\frac{1}{\binom{n}{k}}.   
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Satz thm:necessity-bernoulli-functions of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d,k\in\mathds{N}$, $s,\alpha,\beta,\gamma \in\mathds{R}$, $p,q\in (0,\infty]$, and $\mu,\nu \in [-d,0]$.
Assume that $f$ follows the Besov--Bernoulli{} prior with parameters $(\alpha,\beta,\gamma,\mu,\nu,k)$ and template random variable $X$ with
\begin{equation*}
\begin{cases} \:\exists\: \eps>0:\,\mathds{E}\bigl[\left\lvertX\right\rvert^{p(1+\eps)}\bigr]< \infty&\text{if }p\in (0,\infty),\\
\:\exists\:  R>0:\, \left\lvertX\right\rvert\stackrel{a.s.}{\leq}R&\text{if }p=\infty\end{cases}
\end{equation*}
and
\begin{equation*}
\mathds{P}(X\neq 0)>0.
\end{equation*}
If $f \in B^s_{p,q}(\mathds{R}^d)$ almost surely and if Properties B and B' are satisfied, then also Property A' is satisfied.

[Theorem 8 of arXiv:2607.28004, 'Folding representations of reflected diffusions'] Consider measurable functions $b:D \to \R^d$ and $\sigma:D \to \R^{d \times d}$, such that $\sigma$ satisfies the assumptions of Lemma~\ref{lem:ODE_quadrant}. 
Further, suppose that the function 
\begin{equation} 
\xi(y) = \sigma^{-1}(y)\bigg(b(y) - \tfrac{1}{2}\sum_{j=1}^d (\sigma^{\cdot j}\cdot\nabla)\sigma^{\cdot j}(y)\bigg), \qquad y \in D,
\end{equation} is bounded, where
$ (\sum_{j=1}^d (\sigma^{\cdot j}\cdot\nabla)\sigma^{\cdot j})^i = \sum_{j,\ell=1}^d \sigma^{\ell j}\,\partial_\ell\sigma^{ij}$ for $i=1,\dots,d$.
Then,
\begin{enumerate}[label = (\roman*),noitemsep]
    \item  the function $f:D \to D$ of \eqref{eq:f_quadrant} is well-defined, of class $W^{2,\infty}_{\mathrm{loc}}(D)$, has $D$ as its range, and is the unique solution of the PDE \eqref{eq:nonlinear_PDE_quadrant} satisfying \eqref{eq:f_boundary_quadrant} on the boundary;
    \item with $\xi,f$ as above and
    \begin{equation} 
\alpha(x) = \sign(x)\, \xi\big(f(|x|)\big), \qquad \text{for a.e. } x \in \R^d,
    \end{equation}
 the SDE \eqref{eq:X_SDE} has a pathwise unique, strong solution for every initial value $X_0 \in \R^d$;
    \item the process $Y = f(|X|)$ satisfies the RSDE \eqref{eq:RSDE} on $D$ with initial condition $Y_0 = f(|X_0|)$, Brownian Motion $W = \int_0^\cdot\sign(X_t)dB_t$, and normally reflecting processes
    \begin{equation}  
    \Phi^i = \int_0^\cdot \sigma^{ii}\Big(f\big(|X_t|\odot ({\bf 1}_d - e_i)\big)\Big)dL_t^0(X^i), \qquad i=1,\dots,d.
    \end{equation}  
    \end{enumerate}

[Theorem t:universal_scaling_limit of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Let $Q=I\times B$ be a parabolic cylinder with side length $\varrho\leq 1/4$ and center $(t_0,x_0)\in {\mathbb R}_+\times {\mathbb R}^d$. Suppose that (equation eq:assumption_basic_wellposedness_homogenized of the paper) holds and that, a.e.\ on $I\times \Omega$,
\begin{equation}

\mathrm{Tr}(G)=0\text{ on }2B, \quad \text{ and }\quad \nabla \cdot G =0\text{ in }\mathscr{D}'(2B).
\end{equation}
Fix $p_0,p_1,r\in [2,\infty)$ and $ \sigma>0$. Let $p_2\in [2,\infty)$ satisfy either $p_2>p_1$ or $p_2=p_1=2$. 
Let  $\chi\in C^{\infty}_{{\rm c}}(2B)$ be a cutoff function such that $\chi=1$ on $\kappa B$ for some $\kappa\in (1,2)$.

Then there exist constants $C,\gamma>0$ depending only on $\varrho, p_0,p_1,p_2,r,\sigma,d,\mu$ and $\chi$ such that for any $N\geq 1$ and $\delta\in (0,1]$ satisfying $\delta N\geq 1$, the following estimates hold: 
\begin{align*}
\Big({\mathbf E}\Big\| \overline{v}^{N,\delta}-\Big(v^{N,\delta}-\fint_B v^{N,\delta}\Big)\Big\|_{L^{p_0}(I;L^2(B))}^r \Big)^{1/r}
&\leq \frac{C}{(\delta N)^{\gamma}} \widetilde{\mathcal{E}}^{\#}_{Q},\\
\big({\mathbf E}\|\nabla \Pi^{N,\delta}-\nabla \Pi^0\|_{L^2(I;H^{-1-\sigma}(\mathbb{T}^d_B))}^r\big)^{1/r} 
&\leq \frac{C}{(\delta N)^{\gamma}} \widetilde{\mathcal{E}}^{\#}_{Q},\\
\big({\mathbf E}\|(\nabla\widetilde{\Pi}_{k,\alpha}^{N,\delta})_{k,\alpha}\|_{L^{p_1}(I;H^{-1}(\mathbb{T}^d_B;\ell^2))}^r\big)^{1/r} 
&\leq \frac{C}{(\delta N)^{\gamma}} \widetilde{\mathcal{E}}^{\#}_{Q},
\end{align*}
where $(v^{N,\delta},\pi^{N,\delta},(\widetilde{\pi}^{N,\delta}_{k,\alpha})_{k,\alpha})$ and $(\overline{v}^{N,\delta},\overline{\pi}^{N,\delta})$ are the local solutions to the stochastic and homogenized Stokes systems (equation eq:turbulent_Stokes_scaling_quantitative of the paper) and (equation eq:homogenized_PDE_linear of the paper), respectively, and $\widetilde{\mathcal{E}}^{\#}_{Q}$ is the sharp modified energy of the local solution $(v^{N,\delta},\pi^{N,\delta},(\widetilde{\pi}^{N,\delta}_{k,\alpha})_{k,\alpha})$ on $2Q$ given by
\begin{align}

\widetilde{\mathcal{E}}^{\#}_{Q}&\stackrel{{\rm def}}{=}
\Big({\mathbf E}\Big\|v^{N,\delta}-\fint_{2B}v^{N,\delta}\Big\|_{L^2(2Q)}^r \Big)^{1/r}
+ \big({\mathbf E} \| \pi^{N,\delta}\|_{L^2(2I;H^{-1}(2B))}^r\big)^{1/r}\\
\nonumber
 &+ \big({\mathbf E} \|(\widetilde{\pi}_{k,\alpha}^{N,\delta})_{k,\alpha}\|_{L^2(2Q;\ell^2)}^r\big)^{1/r}+\big({\mathbf E}\|F\|_{L^2(2Q)}^r\big)^{1/r}
+\big({\mathbf E}\|G\|_{L^{p_2}(2I;L^2(2B))}^r\big)^{1/r},
\end{align}
and $\Pi^{N,\delta}$, $\widetilde{\Pi}^{N,\delta}_{k,\alpha}$, and $\Pi^0$ denote the local approximation of the deterministic, stochastic local, and homogenized pressures, respectively, i.e.,
\begin{align}

\Pi^{N,\delta}&\stackrel{{\rm def}}{=}\mathbb{Q}_{\mathbb{T}^d_B} \Big[\chi\big[ \nabla \cdot (F+(1-D_d)\mu \nabla v^{N,\delta})\\
&\qquad \qquad \qquad \qquad 
\nonumber
- c_d \mu \sum_{k,\alpha} \theta_k^N\nabla\cdot  (\nabla \widetilde{\pi}^{N,\delta}_{k,\alpha}\otimes \sigma^\delta_{-k,\alpha} \big)\big]\Big],\\

\widetilde{\Pi}_{k,\alpha}^{N,\delta}
&\stackrel{{\rm def}}{=}\theta^N_k \mathbb{Q}_{\mathbb{T}^d_B} \Big[\chi\big((\sigma^{\delta}_{k,\alpha}\cdot \nabla)v^{N,\delta} + \sigma^{\delta}_{k,\alpha} \cdot G\big)\Big],\\

\Pi^0&\stackrel{{\rm def}}{=} \mathbb{Q}_{\mathbb{T}^d_B} \Big[\chi\big( \nabla \cdot ( F-(1-D_d)\mu \,G^\top)\big)\Big],
\end{align}
where $\mathbb{Q}_{\mathbb{T}^d_B}$ is as in Subsection (ss:Helmh_div_free of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theo:tied-SGD of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Under Assumption (assum:tied of the paper), the online SGD trajectory is governed by an infinite-dimensional ODE driven by the gradients of $\Phi$:
\begin{equation}
\! \! \frac{d \bar\mu_{(k_1, \dots, k_w)}}{dt} \! = \!- \!\sum_{\substack{i=1 \\ k_i\in\mathcal{K}}}^w \! \sum_l [\nabla\Phi(\bar{q})]_{k_i l}
\left( \bar\mu_{(k_1, \dots, k_{i-1}, l, k_i, \dots, k_w)}\! + \bar\mu_{(k_1, \dots, k_i, l, k_{i+1}, \dots, k_w)} \right)\! -\! \frac{\gamma}{2} |\alpha|_{\mathcal{K}} \bar\mu_{(k_1, \dots, k_w)},

\end{equation}
where $|\alpha|_{\mathcal{K}} \le w$ is the number of trainable indices in the multi-index $\alpha$ of length $w$. (equation eq:tied_macroscopic_equation of the paper) has a unique admissible solution and the empirical trajectory uniformly converges to it in probability.

Specifically, if the width scales such that $\max_{1\le k\le K} d_k\le d^{c_w}$ for some fixed $c_w<+\infty$ and the learning rate scales such that $\alpha_d \leq c_0(d\log d)^{-1}$ and $\alpha_d = \Omega(d^{-\iota})$ for some constants $c_0>0$ small enough and $\iota > 0$, then the empirical SGD trajectory satisfies:
\begin{equation}
\lim_{d \to \infty} \mathbb{P} \left( \sup_{t \in [0, T]} \left| \tilde\mu^{(d)}_\alpha(t) - \bar{\mu}_\alpha(t) \right| > \epsilon \right) = 0,\ \forall\epsilon>0
\end{equation}
for every multi-index $\alpha$ and for any fixed $T>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi eq:m[s] of arXiv:2608.29013, 'Weighted Homology and Cohomology of Weighted Polyhedra'] Let $L$ be an abstract simplicial $G$-complex, and let $\mathbf{m}$ be a covariant $R$-coefficient system for $G$. For each $\sigma \in L$, 
    \begin{equation}
        \mathbf{m}[\sigma]:= \Bigl( \bigoplus_{gG_{\sigma} \in G/G_{\sigma}} \mathbf{m}(G/G^g_{\sigma}) \otimes_R R\langle g\sigma \rangle \Bigr)/ J_{\mathbf{m}}[\sigma].
    \end{equation}
    Here, for $g\in G$, $G_{\sigma}^g$ denotes the subgroup $g G_{\sigma} g^{-1}$, $R\langle g\sigma \rangle$ denotes the free $R$-module generated by $g\sigma\in L$, and $J_{\mathbf{m}}[\sigma]$ denotes the submodule generated by all elements of the form 
    \begin{equation}
        x\otimes g\sigma- \mathbf{m}\bigl(\mu(g,G_{\sigma})\bigr) (x)  \otimes \sigma, 
    \end{equation}
    where $x \in \mathbf{m}(G/G^g_{\sigma})$. We use square brackets $[x\otimes g\sigma]$ to denote the elements of $\mathbf{m}[\sigma]$ represented by $x\otimes g\sigma$.

    Let $L_n$ denote the set of $n$-simplices of $L$. We define the $n$-th \textit{equivariant simplicial chain group} of $L$ by 
    \begin{equation}
        C_n(L; \mathbf{m}):= \bigoplus_{[\sigma] \subseteq L_n} \mathbf{m}[\sigma],
    \end{equation}
    where the direct sum ranges over the orbits $[\sigma]$ in $L_n$.

[Prop moment nghiem dung of arXiv:2411.01849, 'A tamed-adaptive Milstein scheme for stochastic differential equations with low regularity'] [KLN]
	Let $X=(X_t)_{t \geq 0}$ be a solution to equation (equation eqn1 of the paper). Then, for any $p \in (0,p_0]$ and $t\geq 0$,
	\begin{align*} 
		\mathbb{E} \left[\vert X_t\vert^p\right] \le \begin{cases} \left \vert x_0^2 e^{2\gamma t}+\frac{\eta}{\gamma}(e^{2\gamma t}-1)\right\vert ^{p/2} & \text{ if \;} \gamma \not = 0,\\
			\left\vert x_0^2+ 2\eta t \right\vert ^{p/2} & \text{ if\; } \gamma  = 0. \end{cases} 
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

