[Lemma 31 (Mean/variance formulas) of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $p>2$.
    Let $f \in \mathcal{C}^3(\R)$, and $\psi_\alpha=\Xi_\alpha^{-1}[f]$. Then, 
    \begin{multline}
        \int_{-1}^1 \psi_\alpha'(x)\diff\mu_{V_{\alpha}}(x) 
        \\= \frac{1}{\pi^2}\int_{-1}^1 \frac{r_\alpha'(x)}{r_\alpha(x)}\int_{-1}^1\frac{f(t)-f(x)}{t-x}\frac{\diff t}{\sigma(t)}\sigma(x)\diff x 
        - \frac{f(1)+f(-1)}{2}+\frac{1}{\pi}\int_{-1}^1f(x)\frac{\diff x}{\sigma(x)}
    \end{multline}
        and
    \begin{multline}
	\dfrac{1}{2}\int_{-1}^1V''_\alpha(x)\psi_\alpha(x)^2\diff\mu_{V_\alpha}(x)
	+\dfrac{1}{2}\iint_{[-1,1]^2}\left(\dfrac{\psi_\alpha(x)-\psi_\alpha(y)}{x-y}\right)^2\diff\mu_{V_\alpha}(x)\diff\mu_{V_\alpha}(y) \\
	= \dfrac{1}{\pi^2}\iint_{[-1,1]^2}\left(\dfrac{f(x)-f(y)}{x-y}\right)^2\dfrac{1-xy}{\sigma(x)\sigma(y)}\diff x\diff y.
    \end{multline}

