[Theorem th:cumulants of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] Let $\varrho (N)$ be a sequence of probability measures on $\hat{U} (N)$
  such that for every finite $r$ the condition ((thatonegamiswtonKinezo of the paper))
  is satisfied. Then, for every $k \in \mathbb{N}$, we have
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N} \sum_{\lambda \in
    \hat{U} (N)} \varrho (N) [\lambda] \sum_{i = 1}^N \left(
    \frac{\lambda_i + N - i}{N} \right)^k -\mathbf{m}_k \right) =
    \sum_{\pi \in \ensuremath{\operatorname{NC}} (k)} \sum_{V \in \pi}
    \ensuremath{\boldsymbol{\kappa}}_{|V|}^{(1)} \prod_{\underset{W \neq V}{W \in \pi}}
    \ensuremath{\boldsymbol{\kappa}}_{|W|}^{(0)}, 
  \end{equation}
  where $(\mathbf{m}_k)_{k \in \mathbb{N}}$ are given by ((mporw? of the paper)) and
  for every $n \in \mathbb{N}$,
  \[ \ensuremath{\boldsymbol{\kappa}}_n^{(0)} := \frac{1}{(n - 1) !}  \left.
     \frac{\mathrm{d}^n}{\mathrm{d} u^n} \left( \Psi (e^u) + \log \left( \frac{e^u -
     1}{u} \right) \right) \right|_{u = 0} \text{\quad and\quad}
     \ensuremath{\boldsymbol{\kappa}}_n^{(1)} := \frac{1}{(n - 1) !}  \left.
     \frac{\mathrm{d}^n}{\mathrm{d} u^n} \left( \Phi (e^u) - \frac{1}{2} u \right)
     \right|_{u = 0} . \]

[Definition def:zetam of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] The TAP free energy is the random function $F_{\mathrm{TAP}}: [-1,1]^N \to \mathbb{R}$ defined by
		\begin{equation}
			F_{\mathrm{TAP}}(\mathbf{m}) =  \inf_{\zeta\in \mathcal{P}([q,1]) } F_{\mathrm{TAP}, \zeta}(\mathbf{m})
		\end{equation}
		where 
		\begin{equation}
			F_{\mathrm{TAP},\zeta}(\mathbf{m}) = H(\mathbf{m})-\sum_{i=1}^N \Phi_\zeta^*(q_\mathbf{m},\cdot)(m_i)-\frac{1}{2}N\int_{q_\mathbf{m}}^1 t\xi''(t)\zeta([0,t])\mathrm{d} t \, ,
		\end{equation}
		where $q_\mathbf{m}:=\frac{1}{N}\Vert \mathbf{m}\Vert^2$, $\Phi_\zeta^*(q,\cdot)$ denotes the Legendre transform of $\Phi_\zeta(q,\cdot)$, as defined in (equation eq:PPDE of the paper), and $\zeta([0,t])$ stands with an abuse of notation for $\zeta([q,t])$. We denote by $\zeta_\mathbf{m}\in \mathcal{P}([q_\mathbf{m},1])$ the minimizer (unique by [chen2018generalized]) achieving the infimum above.

