[Proposition 15 (Stable contour transfer) of arXiv:2608.19594, 'Mesoscopic Rectangular Spikes under Subspace Local Laws:\\Outlier Values and Singular Subs'] Assume the holomorphic subspace law and weighted compatibility on a compact neighborhood of a stable contour $\Gamma$.  Let $\Omega_\Gamma$ be the region enclosed by $\Gamma$.  With probability tending to one:
\begin{enumerate}
  \item $\calW_n$ and the scalar master equation
  \begin{equation}
     \det(\Id_{2r_n}-\calM(\zeta)\calK_n)=0
  \end{equation}
  have the same number of eigenvalues or roots in $\Omega_\Gamma$, counted with algebraic multiplicity;
  \item uniformly on $\Gamma$,
  \begin{equation}
    \calE_n^*(\zeta\Id-\calW_n)^{-1}\calE_n
    -\bigl(\Id_{2r_n}-\calM(\zeta)\calK_n\bigr)^{-1}\calM(\zeta)
    \longrightarrow0
  \end{equation}
  in operator norm.
\end{enumerate}

[Lemma lem:leaf_and_tree of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] For all $x\in [n]$ and $u\in [0,1]$, we have
\begin{equation}
\mathbb E\bigl[u^{d(x)}\mathbf{1}_{x\in \mathcal{Q}_n\cap \mathcal{T}_n}\bigr] = g_k(u\eta_k) - \frac{c_{\textrm{approx}}^1(w,u)}{n}+O\Big(\frac{1}{n^2}\Big),
\end{equation}
where  $d(x)$ is the number of $\mathbf{w}$-preimages of $x\in [n]$ and $c_{\textrm{approx}}^1(w,u):=  \mathbb E_{\scriptscriptstyle BGW}[u^{Z_k}c_{\textrm{approx}}^{\tau_{\mathbf{Z}}}(w^2)\mathbf{1}_{Z_{2k}=0}]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:massive_infrared of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] ~
\begin{enumerate}
\item[(i)]
Let $d > 8$ and $L \ge L_2$.
If $m(p) L$ is sufficiently small, then
\begin{align}
\abs{ \hat F_p ^{(m)} (k) }
\gtrsim L^2 m^2 + L^2 \abs k^2 \wedge 1
	\qquad (m \in [0, \tfrac 1 2 m(p)]),
\end{align}
with the constant independent of $p, m, L$.

\item[(ii)]
Let $d > 2$ and $L \ge L_2$.
If $m_S(\mu) L$ is sufficiently small, then
\begin{align} 
\abs{ \hat A_\mu ^{(m)} (k) }
\gtrsim L^2 m^2 + L^2 \abs k^2 \wedge 1
	\qquad (m \in [0, \tfrac 1 2 m_S(\mu)]),
\end{align}
with the constant independent of $\mu,m,L$.
\end{enumerate}

