[Theo limittheo of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] Let $\lambda(n)$ denote the random partition distributed according to $M^{\mathcal A,\mathcal B}_n$. Then $\lambda(n)'_1=\dots=\lambda(n)'_s=n$ almost surely and as $n\to\infty$
\begin{equation}
\left(\frac{\lambda(n)_1-\alpha_1n}{\sqrt{n\alpha_1(1+\alpha_1)}},\dots, \frac{\lambda(n)_k-\alpha_kn}{\sqrt{n\alpha_k(1+\alpha_k)}} \right) \to \mathbf x^{GUE}_{\mathcal A},
\end{equation}
\begin{equation}
\left(\frac{\lambda(n)'_{s+1}-\beta_{s+1}n}{\sqrt{n\beta_{s+1}(1-\beta_{s+1})}},\dots, \frac{\lambda(n)'_l-\beta_ln}{\sqrt{n\beta_l(1-\beta_l)}} \right) \to \mathbf y^{GUE}_{\mathcal B},
\end{equation}
where both convergences are in distribution.\footnote{The convergences (equation limitrows of the paper) and (equation limitcolumns of the paper) are considered separately, we do not claim anything about the joint law.} In particular, in probability, $\frac{\lambda(n)_i}{n}\to \alpha_i$ for $i\in [1,k]$ and $\frac{\lambda(n)'_i}{n}\to \beta_i$ for $i\in [1,l]$.

[Theorem thm:Fourier_Wilsonloop of arXiv:2608.15923, 'Universality of two-dimensional Markovian holonomy fields'] Let $\Sigma_{g,n}$ be a compact surface of genus $g$ with $n$ boundary components, with prescribed boundary conjugacy classes $\mathfrak t=([t_1],\ldots,[t_n])$ when $n>0$. Let ${\mathbb{G}}=(V,E,F)$ be a topological map embedded in $\Sigma_{g,n}$, fix a vertex $o\in V$, and let $L=(\ell_1,\ldots,\ell_k)$ be a finite regular family of loops in $L_o({\mathbb{G}})$. Denote by $C_1,\ldots,C_r$ the surfaces with boundary obtained by cutting $\Sigma_{g,n}$ along $\ell_1,\ldots,\ell_k$, and let $F_\alpha$ be the set of faces contained in $C_\alpha$. Let $(Q_t)$ be a family of central continuous probability densities and assume that, for every $1\leq\alpha\leq r$,
\begin{equation}
 \sum_{\lambda\in\widehat G}
 d_\lambda^{2-2g_\alpha}
 \prod_{f\in F_\alpha}|a_{|f|}(\lambda)|<\infty,
\end{equation}
where $g_\alpha$ is the genus of $C_\alpha$. For any $F\in C(G^k)^{\operatorname{Ad}G}$, set
\[
 \mathcal E_{{\mathbb{G}}}(F;L)
 :=\int_{\Omega^1({\mathbb{G}},G)}
 F\bigl({\mathrm{Hol}}_{\ell_1}(U),\ldots,{\mathrm{Hol}}_{\ell_k}(U)\bigr)\,
 d\mu_{{\mathbb{G}},G,Q,\mathrm{vol},\mathfrak t}(U).
\]
Then we have the absolutely convergent decomposition
\begin{equation}
 \mathcal E_{{\mathbb{G}}}(F;L)
 =\sum_{\Lambda}\kappa_{{\mathbb{G}},Q,\mathrm{vol}}(\Lambda)\widehat W_{F,L}(\Lambda).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 12 (Number of typical vertices) of arXiv:2606.24887, '2606.24887'] Let $\delta \in (0,1)$. Let $\Gamma$ and $d$ satisfy \cref{eq:theta} and \eqref{eq:regimedlog2}. Let $\theta$ be defined as in \eqref{eq:theta}. Then there exists a constant $\tilde{\ccc}>0$ depending only on $\nu$ and $\delta$ such that with the definition 
   \begin{equation}
 \varphi^3  = \tilde{\ccc} \frac{\Gamma^5 \log N}{d^2}
		 \end{equation}
  the following holds uniformly for $w \in \C$ and $z \in \C$ with $\Im z \geq N^{-1 + \delta}$  with very high probability on the event $\{\theta =1\}$.
		\begin{enumerate}[label=(\roman*)]
			\item  Most vertices are typical:
			\begin{equation*}
				\abs{\mathcal{T}_{\varphi}^c} \le \ee^{\frac{\varphi^2d}{2^{14} (\ee\Gamma)^2}}  + 4N \ee^{-\frac{\varphi^2d}{2^{13} (\ee\Gamma)^2}} .
			\end{equation*}
			\item  Most neighbours of each vertex are typical:
			\begin{equation*}
				\Biggl(\sum_{y\in \mathcal{T}^c_{\varphi}}^{(x)} \abs{X_{xy}}^2\Biggr) \vee \Biggl(\sum_{y\in \mathcal{T}^c_{\varphi}}^{(x)} \abs{X_{yx}}^2 \Biggr)\le 2 \ccc \varphi\Gamma^{-3} + 5\mathcal{C}d^4\ee^{-\frac{\varphi^2d}{2^{14} (\ee\Gamma)^2}}
			\end{equation*}
			uniformly for $x \in [N]$.  
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

