[Tm mush of arXiv:2607.12795, 'Semi-open boundary for random walking shocks'] The identity
 \begin{equation}
  \begin{aligned}
   \frac{\,\text{d}}{\,\text{d} t}\un\nu^{\un\varrho,\underline{m}}S(t)\Bigr|_{t=0}=\sum_{i=1}^{K-1}&P(m_i,\,m_{i+1},\,\varrho_i,\,\varrho_{i+1})\cdot\bigl[\un\nu^{\un\varrho^{i\rightarrow},\underline{m}^{i,i+1}}-\un\nu^{\un\varrho,\underline{m}}\bigr]\\
   +\,&Q(m_i,\,m_{i+1},\,\varrho_i,\,\varrho_{i+1})\cdot\bigl[\un\nu^{\un\varrho^{i\leftarrow},\underline{m}^{i+1,i}}-\un\nu^{\un\varrho,\underline{m}}\bigr]
  \end{aligned}
 \end{equation}
 holds in the following special cases with the following boundary rates \(p_0\), \(q_0\), \(p_K\), \(q_K\) and parameters \(\un\varrho^{i\rightarrow}\), \(\un\varrho^{i\leftarrow}\), \(P(m_i,\,m_{i+1},\,\varrho_i,\,\varrho_{i+1})\) and \(Q(m_i,\,m_{i+1},\,\varrho_i,\,\varrho_{i+1})\):
 \begin{itemize}
  \item For the ASEP, \(m_i=0\) or \(1\),
  \begin{equation}
   \begin{aligned}
    p_0(0,\,0)&=(p+c)\varrho_1,&\qquad q_0(1,\,1)&=(q+c)(1-\varrho_1),\\
    p_K(1,\,1)&=(p+d)(1-\varrho_K),&\qquad q_K(0,\,0)&=(q+d)\varrho_K
   \end{aligned}
  \end{equation}
 and zero in all other cases, with arbitrary constants \(c\) and \(d\) in \([-\min(p,\,q),\,\infty)\), the relation
  \begin{equation}
   \frac{\varrho_i(1-\varrho_{i-1})}{\varrho_{i-1}(1-\varrho_i)}=\left\{
    \begin{aligned}
     &1,&&\text{if }m_i=0,\\
     &\frac pq,&&\text{if }m_i=1
    \end{aligned}

   \right.\qquad(1<i\le K)
  \end{equation}
  holds between the densities and the asymmetry, and
  \begin{equation}
   \hat\mu^{\varrho,m}(0)=1-\hat\mu^{\varrho,m}(1)=\left\{
    \begin{aligned}
     &1-\varrho,&&\text{if }m=0,\\
     &1,&&\text{if }m=1.
    \end{aligned}
   \right.
  \end{equation}
  In this case
  \begin{align}
   \varrho_j^{i\rightarrow}&=\left\{
    \begin{aligned}
     &\varrho_j,&&\text{for }j\ne i,\\
     &\frac{q\varrho_i}{p-(p-q)\varrho_i},&&\text{for }j=i,
    \end{aligned}
   \right.\\
   \varrho_j^{i\leftarrow}&=\left\{
    \begin{aligned}
     &\varrho_j,&&\text{for }j\ne i,\\
     &\frac{p\varrho_i}{q+(p-q)\varrho_i},&&\text{for }j=i\text{, and}
    \end{aligned}
   \right.\notag\\
   P(m_i,\,m_{i+1},\,\varrho_i,\,\varrho_{i+1})&=m_i(1-m_{i+1})\cdot\bigl[(1-\varrho_{i+1})p+\varrho_{i+1}q\bigr],\\
   Q(m_i,\,m_{i+1},\,\varrho_i,\,\varrho_{i+1})&=(1-m_i)m_{i+1}\cdot\bigl[(1-\varrho_i)q+\varrho_ip\bigr].
  \end{align}
  \item For BLP, with arbitrary non-negative \(q^+_0(x,\,x+m)\) and \(q^+_K(x,\,x+m)\) (for \(x\in\mathbb Z\), \(m\in\mathbb Z_{\ge0}\))
  \[
   \begin{aligned}
    p^+_0(x,\,x+m):&=q^+_0(x+1,\,x+m+1)\cdot\text{\rm e}^{\theta_1}f(-x),\\
    p^+_K(x,\,x+m):&=q^+_K(x-1,\,x+m-1)\cdot\text{\rm e}^{-\theta_K}f(x),
   \end{aligned}
  \]
  the boundary rates are
  \begin{equation}
   \begin{aligned}
    p_0(\omega_1,\,\omega_1+m_1)&=\text{\rm e}^{\theta_0}+f(-\omega_1)+p^+_0(\omega_1,\,\omega_1+m_1),\\
    p_K(\omega_K,\,\omega_K+m_K)&=f(\omega_K+m_K)+\e{-\theta_{K+1}}+p^+_K(\omega_K,\,\omega_K+m_K),\\
