[Cor closed-ineq of arXiv:2608.27939, 'Entropy and domination for quasi-Hitchin representations'] For the curve $\gamma$ constructed in the above Proposition, we have the following strict inequalities of the Hilbert and translation lengths: 
\begin{equation*}
    \ell^H_\rho(\gamma) < \ell^H_{\rho_0}(\gamma) \text{ and } \ell_\rho(\gamma) < \ell_{\rho_0}(\gamma).
\end{equation*}

[Proposition JM-dm1 of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \medskip \noindent \textbf{} The Lorenz normalizer is 
\begin{equation}
I_{F}=E\left[ \prod_{i=1}^{d}X_{i}\right] =\int_{H}\left(
\prod_{j=1}^{d-1}u_{j}\right) h(u)\,d\mu (u).  
\end{equation}
For $x=(x_{1},\ldots ,x_{d})\in \lbrack 0,1]^{d}$, 
\begin{equation}
L_{F}(x)=\frac{1}{I_{F}}\int_{R_{F}(x)}\left( \prod_{j=1}^{d-1}u_{j}\right)
h(u)\,d\mu (u),  
\end{equation}
where 
\begin{equation*}
R_{F}(x)=\left\{ u\in H:0\leq u_{j}\leq T_{j}^{F}(x_{j}),\ 1\leq j\leq
d-1,\quad 0\leq h(u)\leq T_{d}^{F}(x_{d})\right\} .
\end{equation*}
In particular, 
\begin{equation}
L_{d}^{F}(x)=\frac{1}{I_{F}}\int_{\{u\in H:\,0\leq h(u)\leq
T_{d}^{F}(x)\}}\left( \prod_{j=1}^{d-1}u_{j}\right) h(u)\,d\mu (u),

\end{equation}
and, for $i=1,\ldots ,d-1$, 
\begin{equation}
L_{i}^{F}(x)=\frac{1}{I_{F}}\int_{\{u\in H:\,0\leq u_{i}\leq
T_{i}^{F}(x)\}}\left( \prod_{j=1}^{d-1}u_{j}\right) h(u)\,d\mu (u).

\end{equation}
\medskip (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 7 (Critical learning rate of Polyak) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] There exists a unique critical learning rate satisfying
\[
0
<
\eta_{\polyak}^{\crit}
<
\frac{
2B(1-\rho^2)
}{
\lambda_{\max}\left[B(1-\rho)+(1+\rho)\right]
}
\]
and the critical equation
\begin{equation}

\sum_{i\geq1}
\frac{
\eta_{\polyak}^{\crit}\lambda_i(1+\rho)
}{
2B(1-\rho^2)
-
\eta_{\polyak}^{\crit}\lambda_i
\left[B(1-\rho)+(1+\rho)\right]
}
=1.
\end{equation}
The Polyak iteration is risk stable if and only if
\[
0<\eta<\eta_{\polyak}^{\crit}.
\]
Moreover,
\begin{equation}

\begin{aligned}
\frac{
2B(1-\rho^2)
}{
\lambda_{\max}\left[B(1-\rho)+(1+\rho)\right]
+
(1+\rho)\Tr(\bH)
}
\leq
\eta_{\polyak}^{\crit},
\\
\eta_{\polyak}^{\crit}
\leq
\min\left\{
\frac{
2B(1-\rho^2)
}{
\lambda_{\max}\left[B(1-\rho)+(1+\rho)\right]
},
\frac{2B(1-\rho)}{\Tr(\bH)}
\right\}.
\end{aligned}
\end{equation}
Under the power-law assumption
\(\lambda_i\eqsim i^{-\beta},\beta>1
\), when \(B\gg1,1-\rho\ll1,\) we have
\[
\eta_{\polyak}^{\crit}
\eqsim
\min\{1,B(1-\rho)\}.
\]

[Definition of arXiv:2608.10415, 'Continuous random variables'] Consider a linear map $\varphi:A\to\mathbb C$.
\begin{enumerate}
\item $\varphi$ is called positive when $a\geq0\implies\varphi(a)\geq0$.

\item $\varphi$ is called faithful and positive when $a\geq0,a\neq0\implies\varphi(a)>0$.
\end{enumerate}

[Corollary 137 (Central limit theorem) of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity}. Assume additionally that the equations \eqref{eq_equations_eqs} deterministically fix the segment filling fractions and that the equilibrium measure contains exactly one band per segment. Let $L \in \amsmathbb{Z}_{> 0}$ and a $L$-tuple of integers $\boldsymbol{h} \in [H]^L$ both independent of $\N$, let a (possibly $\N$-dependent) $L$-tuple of functions $\boldsymbol{f}(z)$ such that $f_l(z)$ is a holomorphic function of $z \in \amsmathbb{M}_{h_l}$ for any $l \in [L]$. Assume there exists a constant $C > 0$ such that $\max_{l} \sup_{z} |f_l(z)| \leq C$.

We define the random $L$-dimensional centered Gaussian vector $\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\textbf{0}}[\boldsymbol{f}]$ with covariance
\begin{equation}

\textnormal{\textsf{Cov}}_{l_1,l_2}[\boldsymbol{f}] = \oint_{\gamma_{h_{l_1}}} \oint_{\gamma_{h_{l_2}}} \frac{\dd z_1\,\dd z_2}{(2\ii\pi)^2}
 f_{l_1}(z_1) f_{l_2}(z_2)
\,\mathcal{F}_{h_{l_1},h_{l_2}}(z_{l_1},z_{l_2}).
\end{equation}
If $\boldsymbol{\ell}$ is $\P$-distributed, then as $\N \rightarrow \infty$
\begin{equation}

\left(\sum_{i = 1}^{N_{h_l}} f_{l}\bigg(\frac{\ell^{h_l}_{i}}{\N}\bigg)-\E\left[\sum_{i = 1}^{N_{h_l}} f_{l}\bigg(\frac{\ell^{h_l}_{i}}{\N}\bigg)\right]\right)_{l=1}^L\,\,\mathop{\sim}^{\textnormal{mom}} \,\,\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\textbf{0}}[\boldsymbol{f}]
\end{equation}
and the convergence in the sense of Definition~\ref{Definition_convergence_moments} is uniform for fixed choice of constants in the assumptions. Besides, for any $m \in [M]$, we have the asymptotic expansion
\begin{equation}

\E\left[\sum_{i = 1}^{N_{h_l}} f_{l}\bigg(\frac{\ell^{h_l}_{i}}{\N}\bigg)\right] = \N
\int_{\hat{a}_{h_l}'}^{\hat{b}_{h_l}'} f_{l}(x)\mu_{h_l}(x)\dd x + \mathbbm{Rest}[f_l] + O(\N^{-\frac{3}{2}+\eps}),
\end{equation}
where for fixed constants in the assumptions, $\mathbbm{Rest}[f_l]$ is uniformly bounded and the remainder $O(\N^{-\frac{3}{2} + \eps})$ is uniform as $\N \rightarrow \infty$. The term $\mathbbm{Rest}[f_l]$ depends smoothly on parameters in the following way.

Let $p \in \amsmathbb{Z}_{\geq 0}$. Suppose that we allow segment filling fractions and endpoints $(\hat{\boldsymbol{a}},\hat{\boldsymbol{b}},\hat{\boldsymbol{n}})$ to vary in some open of $\amsmathbb{R}^3$. Suppose that the weights $(w_h(x))_{h = 1}^{H}$, the parameters $(\rho_{h,j}^{\pm})_{h,j}$, the regular part of the potentials $(U_h(x))_{h = 1}^{H}$ are $p$ times continuously differentiable with respect to $(\hat{\boldsymbol{a}},\hat{\boldsymbol{b}},\hat{\boldsymbol{n}})$ while the integers $(\iota_h^{\pm})_{h = 1}^{H}$ remain constant, and that Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} hold for uniform constants and the assumption of one band per segment remain satisfied. Then $\mathbbm{Rest}[f_l]$ is $p$ times continuously differentiable with respect to $(\hat{\boldsymbol{a}},\hat{\boldsymbol{b}},\hat{\boldsymbol{n}})$ for $z$ away from the segments, and all the partial derivatives up to order $p$ are uniformly bounded for $z$ away from the segments, with constants determined by the constants in the assumptions.

If furthermore $\theta_{g,g} = 1$ for every $g \in [H]$, the term $\mathbbm{Rest}[f_l]$ and all its partial derivatives are actually $O(\frac{1}{\N})$. In particular
\begin{equation}

\left(\sum_{i = 1}^{N_{h_l}} f_{l}\bigg(\frac{\ell^{h_l}_{i}}{\N}\bigg) - \N \int_{\hat{a}_{h_l}'}^{\hat{b}_{h_l}'} f_l(x)\mu_{h_l}(x)\dd x \right)_{l = 1}^{L}  \,\,\mathop{\sim}^{\textnormal{mom}} \,\,\textnormal{\textsf{\textbf{Gau\ss{}}}}_{\textbf{0}}[\boldsymbol{f}].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $\kappa\in \Nbb^n$, $f\in \Leb^2(\Rbb^n,\gamma_n)$, and $t > 0$,
\begin{equation}
    \Dop^\kappa \Pop_t f(x) = \left(\upe^{2t}-1\right)^{-|\kappa|/2} \Exp_{\ybold\sim p_{t,x}} \left[\psi_\kappa^{t,x}(\ybold)f(\ybold)\right],
\end{equation}
where $p_{t,x}$ denotes the biased multivariate Gaussian distribution with mean vector $\upe^{-t}x$ and covariance matrix $\left(1-\upe^{-2t}\right)\Ibf_n$, and $\psi_\kappa^{t,x}(y) := h_\kappa(\frac{y-\upe^{-t} x}{\sqrt{1-\upe^{-2t}}})$.

