[Theorem EHI:t:KM of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X=(X_t)_{t \geq 0}=(B_{S_t})_{t \geq 0}$ be a subordinate Brownian motion, where $S$ is a subordinator and $B$ is a Brownian motion on $\mathbb{R}^d$, independent of $S$. Assume there exists a $C>0$ such that the jump kernel of $X$ satisfies
    \begin{equation*}
        j(r+1) \leq j(r) \leq C j(r+1) \qquad\mbox{for all $r>1$}.
    \end{equation*}
    Suppose also that the subordinator $S$ satisfies the three following conditions:
    \begin{enumerate}[label=A-\arabic*]
        \item The potential measure of $S$ has decreasing density. In other words, there exists a decreasing function $u(t)$ such that $U(dt)=u(t) \; \mathrm{d} t$.
        \item The L\'{e}vy measure of $S$ is infinite (in other words, $\mu((0, \infty))=\infty$) and has a decreasing density.
        \item There exist constants $\sigma>0$, $\lambda_0>0$, and $\delta \in (0, 1]$ such that
        \begin{equation*}
            \frac{\phi'(\lambda x)}{\phi'(\lambda)} \leq \sigma x^{-\delta} \qquad\mbox{for all $x \geq 1$ and $\lambda \geq \lambda_0$}.
        \end{equation*}
\end{enumerate}
    Then $X$ satisfies $\hyperref[EHI:d:ehi]{\mathrm{EHI}}(r \leq 1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 5 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(f\colon\mcalY\to\mcalX\) be a morphism of stacks. By \citeSta{06NW}, the induced functor between the inherited fpqc sites gives a morphism of topoi. Moreover, the canonical morphism \(f^{-1}\mcalO_{\mcalX}\to\mcalO_{\mcalY}\) is an equivalence: on every object \(T\to\mcalY\), both sides are the ring \(\Gamma(T,\mcalO_T)\). We therefore obtain a morphism of ringed fpqc topoi. We denote the resulting derived adjunction by
  \begin{equation*}
    Lf_{\mathrm{sh}}^*\colon\mcalD(\mcalX_{\fpqc},\mcalO_{\mcalX})\rightleftarrows\mcalD(\mcalY_{\fpqc},\mcalO_{\mcalY})\colon Rf_*^{\mathrm{sh}};
  \end{equation*}
  see \citeSta{07A6}. Thus
  \begin{equation*}
    Lf_{\mathrm{sh}}^*(\mathord{-})\defeq\mcalO_{\mcalY}\otimes_{f^{-1}\mcalO_{\mcalX}}^Lf^{-1}(\mathord{-}).
  \end{equation*}
  We call \(Lf_{\mathrm{sh}}^*\) the \emph{site-theoretic derived pullback} and \(Rf_*^{\mathrm{sh}}\) the \emph{site-theoretic derived pushforward}.

[Proposition forms_equal of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] Let $u,v\in C_c^\infty(\mathbb{R}_*)$. Then $u,v\in\mathcal{D}(\mathcal{E}_D)\cap \mathcal{F}$ and 
    \begin{align}
    \mathcal{E}(u,v) = \mathcal{E}_D(u,v).
    \end{align}

