[Definition def_b_sigma of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] For $\sigma \in \{-,0,+\}$ and $w \in \Omega_n^{(0)}(\mu,2^{-R}\varepsilon)$, we define the word $b^{\sigma} \in \Omega_{\textup{fin}}$ as follows. 
\begin{itemize}
\item[-] If $\#J^{\sigma}=0$, which can only happen if $\sigma \neq 0$, then we set for $j \in \llbracket 1,\overline{\alpha}_{\sigma,n} \rrbracket$,
\begin{align*}
b^{\sigma}_j = \sigma(R+\mathbbm{1}_{j \in 2 \mathbb{N}}).
\end{align*}
\item[-] If $\#J^{\sigma}>0$, let $m  \overset{\textup{\tiny def.}}{=} \overline{\alpha}_{\sigma,n} - \left(\sum_{h=1}^{\#J^{\sigma}}|u^{h,\sigma}|+\#J^{\sigma}-1\right)$, which is positive by Lemma~(lemma_overline_alpha_sigma_long_enough of the paper). Then, for all $j \in \llbracket 1, m \rrbracket$, set
\begin{align*}
b^{\sigma}_j = u^{\#J^{\sigma},\sigma}_{-1}+ \delta \mathbbm{1}_{j \in 2\mathbb{N}-1},
\end{align*}
where $\delta \in \{-1,1\}$ is chosen so that $b^{\sigma}_j \in A^{\sigma}$ for all $j \in \llbracket 1,m \rrbracket$.
\end{itemize}

[Lemma lem:quadratic-stability of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] For $\beta\in(0,1)$ and $s>0$, all matrices $A_\lambda(s,\beta)$, $\lambda\in[1,\kappa]$, are Schur stable, meaning that their spectral radii are strictly less than one, if and only if
\begin{equation}
 0<s<\frac{2(1+\beta)}{\kappa}.
\end{equation}
For OBABO, using $s=h^2(1+\beta)/2$, this is equivalent to $0<h<2/\sqrt\kappa$. Moreover, if $h\ge2/\sqrt\kappa$, the OBABO chain for the potential $U_\kappa(x)=\kappa\lvert x\rvert^2/2$ has no invariant probability law.

