[Lemma 4 of arXiv:2608.09840, 'Langevin dynamics along the zero set of real-analytic potentials'] The singularity type is lower semicontinuous on $Z$ with respect to the ordering \eqref{eq:ordering}.
Moreover, $Z_{\lambda,m}$ is a locally closed subanalytic subset of $\R^d$ and admits the representation
\begin{equation} 
Z_{\lambda,m} = \pi(E_{\lambda,m}),
\end{equation}
where $E_{\lambda,m}$ is a codimension-$m$ real-analytic submanifold and subanalytic subset of $M$. It is given explicitly by
\begin{equation} 
E_{\lambda,m} = \pi^{-1}(D) \cap \bigcup_{\substack{A \subset A_\crit \\ |A| = m}} E_A \setminus C_\textnormal{sat},
\end{equation}
where $C_\textnormal{sat} = \pi^{-1}(\pi(C))$ is the ``saturation'' along the fibers of $\pi$ of the set
\[
C = \Big( \bigcup_{\alpha \in A_\supcr} E_\alpha \Big) \cup \Big( \bigcup_{\substack{A \subset A_\crit \\ |A| > m}} E_A \Big).
\]

[Theorem Thm: LowerBound_Smaller_d of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $d \geq 1$, $\lambda > 0$, $\ell \in \mathbb N^+$, $\alpha \in (0, d)$, and $Q \in \mathcal{H}_{\alpha, K}$. 
    Then, there exists a positive constant $c_1 = c_1(d, \alpha, K, \lambda, \ell)$ such that
\begin{align}
    \lim_{M \rightarrow \infty} \mathbb P \left( \min_{x : |x| \ge M} \frac{\mathrm{AT}_\ell(x)}{(\log |x|)^\Delta} \le c_1  \right) = 0. 
\end{align}

[Lemma 34 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] There are constants $0<r_1<r_2$ and  $\zeta\in(0,1]$ such that for any $x\in\mathbb{R}^N$ and $y\in\left\{x+F_l(u,x):~u\in \mathfrak{g}^{(l)},~\|u\|_{\mathrm{HS}}<r_1\right\}$, there is a diffeomorphism $S_{x,y}$ between $M_{x,y}\cap\left\{u\in\mathfrak{g}^{(l)}:||u||_{\mathrm{HS}}<r_1\right\}$ and $M_{x,x}\cap\left\{u\in\mathfrak{g}^{(l)}:||u||_{\mathrm{HS}}<r_2\right\}$, which satisfies
\begin{equation}
\zeta\cdot m_{x,x} \leqslant \left(K(\cdot,x)~m_{x,y}\right) \circ S_{x,y}^{-1} \leqslant \frac{1}{\zeta} \cdot m_{x,x} \   \text{on}\ \left\{S_{x,y}(u);~u\in M_{x,y}~\text{and}~||u||_{\mathrm{HS}}<r_1\right\}
\end{equation}
\textit{and}
\begin{equation}
\zeta \cdot (\|S_{x,y}(u)\|_{\mathrm{CC}} + d(x, y)) \leqslant \| u \|_{\mathrm{CC}} \leqslant \frac{1}{\zeta} \cdot (\|S_{x,y}(u)\|_{\mathrm{CC}} + d(x, y))
\end{equation}
for any $u \in M_{x,y}$ with $\|u\|_{\mathrm{HS}}<r_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2608.26816, '\textbf{On the existence of maximal foliations in general relativity}'] For any $L^2_tW^{1,2}(M_t)$-tensor field $F$, we have 
    \begin{equation} 
        \|F\|_{L^{\frac{10}{3}}(M_{0}\times [0,  T])}\leq C \|F\|^{\frac{2}{5}}_{L^{\infty}_{t}L^{2}(M_{t})}\|\nabla F\|^{\frac{3}{5}}_{L^{2}(M_{0}\times [0,  T])},
    \end{equation}
    where  $\|F\|_{L^{\frac{10}{3}}(M_{0}\times [0,  T])}=[\int_{0}^{T}\int_{M_t}|F|^{\frac{10}{3}}]^{\frac{3}{10}}$,  $C=C(\alpha_0)$.

