body:
[Lemma l.spreading of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] {HSTT_vacuum}}]
	Fix any choice of parameters $\tau, \delta, r > 0$ and $x_0, v_0, v_\tau \in \mathbb R^3$ and define the associated trajectory $(x_t,v_t)$ by~(equation e.kinetic_trajectory of the paper) and path by (equation e.path of the paper). Suppose that $g$ is a nonnegative, classical supersolution to~(equation e.kfp_lower of the paper) and that
	\begin{equation}
		g_{\rm in}(x,v) > \delta \qquad \text{for each }(x,v) \in B_r(x_0)\times B_r(v_0) \qquad \text{and} \qquad \left\|\lambda\right\|_{\rm path} < \infty.
	\end{equation}
    Then, there exists a universal constant $\mu > 0$ such that whenever
    \begin{equation}
        \tau + \frac{\tau \left\|A\right\|_{\rm path}}{r^2} \leq \mu,
    \end{equation}
    there holds
	\begin{equation}
		g\left(\tau ,x,v\right) > \frac{\delta}{C_{\rm diff}} \qquad \text{for each }(x,v)\in B_{\nicefrac{r}{4}}(x_{\tau}) \times B_{\nicefrac{r}{4}}(v_\tau).
	\end{equation}
    The constant $C_{\rm diff} > 0$ depends on upper bounds for $\tau$, $|v_0 - v_\tau|$, $\|\lambda\|_{\rm path}$, $\|\mathcal B\|_{\rm path}$, and $\|\mathcal C_-\|_{\rm path}$ as well as lower bounds for $\tau$ and $r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eX_definition of arXiv:2604.16206, 'Extrapolation of max--stable random fields with Fr\'echet marginals'] The \textit{max-stable predictor} of $X_{t_0}$ is given by
	 \begin{equation}\notag
		\hat{X}_{\hat{\mathbf{\lambda}}} = M(\hat{\mathbf{\lambda}},\mathbf{X}(\mathbb{T}_f)) = \max\limits_{j=1,\ldots,n} \{\hat{\lambda}_j X_{t_j}\},
 \end{equation}
	where the vector of optimal weights $\hat{\mathbf{\lambda}}=(\hat{\lambda}_1,\ldots, \hat{\lambda}_n)$ is a solution to minimization problem 
\begin{equation}\begin{split}
	\Psi(\lambda) := & 2\mathbb{E}\left(e^{-(X_{t_0} \vee \hat{X}_\lambda)^{-\alpha}}\right) - \mathbb{E}\left(e^{-\hat{X}_\lambda^{-\alpha}}\right) - 1/2 \\ + & \gamma\left(\frac{1}{3} - \mathbb{E}\left(e^{-\hat{X}_\lambda^{-\alpha}} \vee Y \right) + \mathbb{E}\left(e^{-2 \hat{X}_\lambda^{-\alpha}}\right)\right) \longrightarrow \min\limits_{\mathbf{\lambda}\in\mathbb{R}^n_+}, \end{split}
\end{equation}
	 $Y$ is an independent copy of $e^{-\hat{X}_\mathbf{\lambda}^{-\alpha}}$, and $\gamma>0$ is a penalty weight.  If it is not possible to generate $Y$, one can use an alternative form  of the 2-Wasserstein metric in (equation eq:2Wasserst of the paper) and write
	  \begin{equation}
	\begin{split}
		\hat{\mathbf{\lambda}} &= \argmin\limits_{\mathbf{\lambda}\in\mathbb{R}^n_+} \left\{2\mathbb{E}\left(e^{-(X_{t_0} \vee \hat{X}_\mathbf{\lambda})^{-\alpha}}\right) - \mathbb{E}\left(e^{-\hat{X}_\mathbf{\lambda}^{-\alpha}}\right) -1/2 \right. \\
        &+ \left. \gamma \left(\frac{1}{3}+ \int\limits_0^1 F(u) \left(F(u)- 2u\right) du \right) \right\}
	\end{split}  \end{equation}
	with $F$ being the distribution function of $e^{-\hat{X}_\mathbf{\lambda}^{-\alpha}}$.

[Lemma l:h of arXiv:2607.22333, '\large \bf COLLISION AND NON-COLLISION FOR DIFFUSIONS ON CONFIGURATION SPACE'] There exists a family  of even functions $h_\varepsilon\in C_c^\infty(\mathbb{R})$, $0<\varepsilon<1/4$, such that
\begin{equation}
0\le h_\varepsilon\le 1,
\qquad
h_\varepsilon(t)=1\ \text{for }|t|\le \varepsilon/2,
\qquad
\mathrm{supp} h_\varepsilon\subset \{|t|<\sqrt\varepsilon\},
\end{equation}
and
\begin{equation}
|h_\varepsilon'(t)|\le \frac{c_h}{|\log\varepsilon|\,(|t|\vee \varepsilon)}
\qquad (t\in\mathbb{R}),
\end{equation}
with $c_h>0$ independent of $\varepsilon$.

[Theorem 6 (Solution of \eqref{eq:dynsys1}) of arXiv:2606.15842, 'A small noise approximation for Muller's Ratchet'] Started in $x \in \mathbb S$, the system \eqref{eq:dynsys1} has the solution
  \begin{align}
    x_k(t) & = \frac{1}{g_{\alpha t}(x)} \sum_{i=0}^k x_i e^{-\alpha i t}
      \frac{\theta^{k-i}}{(k-i)!} (1-e^{-\alpha t})^{k-i} \cdot \exp\Big(
    -\theta(1-e^{-\alpha t})\Big).
  \end{align}

