body:
[Lemma 10 of arXiv:2609.03961, 'On the exponential sum over squarefree integers'] Let $p\ne p'$ be odd primes, $m=pp'$, and let $r\ge1$ and $b$ be integers
with $(m,r)=1$ and $(b,r)=1$.  Let $I$ be a set of consecutive integers and
let $h$ be an integer with $1\le|h|<r$.  Then
\begin{equation}
  \sum_{k\in I}\chi_{pp'}(k)\e\left(\frac{bhk}r\right)
  \ll r\sqrt m\sum_{\substack{0<|s|\le mr/2\\ s+bhm\equiv0\ (\mathrm{mod}\ r)}}
  \frac1{|s|}.
\end{equation}

[Proposition exponential-tight of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let $\mathcal{V}[\cdot]$ be defined by (equation ker-V of the paper) such that (equation eq:small-KS of the paper) holds and consider the scaling
\begin{equation}
\begin{gathered}
K(\varepsilon)\to\infty,\qquad \varepsilon N_{K(\varepsilon)}\rightarrow 0,\qquad
\varepsilon N_{K(\varepsilon)}\|s'_{\eta(\varepsilon)}\|_{L^\infty}^2\lesssim 1,\qquad \eta(\varepsilon) \to 0.
\end{gathered}
 \end{equation}
 as $\varepsilon\rightarrow 0$. For every probabilistically weak renormalized kinetic solution $\rho^{\eta}$ to (equation cspde of the paper), in the sense of Definition (RKS smooth spde of the paper) with initial data $\rho_0$ of finite entropy, we let $\mu^{\varepsilon}$ be the law of $\rho^{\eta} = \rho^{\eta(\varepsilon)}$. Then there exists a sequence of compact sets $\{\mathcal{K}_M\}_{M\in\mathbb{N}}$ in $L^1_{[0,T]}L^1_{\mathbb{T}^2}$, such that
\begin{equation}
  \lim_{M\to \infty}\limsup_{\varepsilon\to 0}\varepsilon \log\mu^{\varepsilon}(\mathcal{K}^c_M) = -\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 of arXiv:2608.22816, 'A Cap-Move Reformulation of Ling's Proof of Samuels' Conjecture'] Assume the conditions and notations of \Cref{lem:cap-move}. For each $i\in [n]$, there exists a nonnegative measure $\nu_i$ on $\bR_+$ such that
\begin{align*}
	\mathsf{Cov}(S, X_i \mid S<\lambda) = \int_0^\infty (r(S_i^a)-r(S))\nu_i(da). 
\end{align*}
In addition, if $\mathrm{supp}(X_i) = \{x_1,\dots,x_m\}$ with $x_1<\cdots<x_m$, then $\mathrm{supp}(\nu_i) = \{x_1,\dots,x_{m-1}\}$.

