[Theorem 23 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] The following almost sure convergence results hold true:\\
\noindent{(i)} For $0\le p< (4a-1)/4a$, we have
\begin{equation*}
	\lim_{n\to\infty}\frac{G_n}{n}=0\ \ \text{a.s.},
\end{equation*}
\noindent{(ii)} for $p= (4a-1)/4a$, we have
\begin{equation*}
	\lim_{n\to\infty}\frac{G_n}{\sqrt{n}\log n}=0\ \ \text{a.s., and}
\end{equation*}
\noindent{(iii)} for $(4a-1)/4a<p\le 1$, we have
\begin{equation*}
\lim_{n\to\infty}\frac{G_n}{n^{2a(p-1)+1}}=\frac{L}{(2a(p-1)+2)}\ \ \text{a.s.},
\end{equation*}
where $L$ is as given in \eqref{Lvariab}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:lil-rw2mc of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] {The rates of almost sure convergence of the fluctuations around the almost sure limit in the appropriate regimes are as follows.
\begin{enumerate}
\item[a)] For $p \in \left(0, \frac{11}{16}\right)$,
\begin{align}
    &\limsup_{n \to \infty} \sqrt{\frac{n}{2\log\log n}}\left(\frac{S_n}{{n}} - \Lambda_p\right) \\
    =-&\liminf_{n \to \infty} \sqrt{\frac{n}{2\log\log n}}\left(\frac{S_n}{{n}} - \Lambda_p\right) 
    {= \sqrt{\Sigma^{(1)}_p}}, \nonumber
\end{align}
where $\Sigma^{(1)}_p$ is given by (equation eq:sigma1 of the paper), and for $p \in \left(\frac{113+\sqrt{97}}{128}, 1\right)$, there exists a constant $C > 0$ such that
\begin{align}
    &\limsup_{n \to \infty} \sqrt{\frac{n}{2\log\log n}}\left|\frac{S_n}{{n}} - \Lambda_p\right| \leq C.
\end{align}
\item[b)] For $p \in \left\{\frac{11}{16}, \frac{113+\sqrt{97}}{128}\right\}$,
\begin{align}
    &\limsup_{n \to \infty} \left(\frac{n}{2\log n\log\log\log n}\right)^{1/2}\left(\frac{S_n}{{n}} - \Lambda_p\right) 
    \\ =-&\liminf_{n \to \infty} \left(\frac{n}{2\log n\log\log\log n}\right)^{1/2}\left(\frac{S_n}{{n}} - \Lambda_p\right) 
    {= \sqrt{\Sigma^{(2)}_p}}, \nonumber
\end{align}
where $\Sigma^{(2)}_p$ is given by (equation eq:sigma2 of the paper).
\end{enumerate}} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mainthm of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] For every open set $U\subset M$ we have 
  \begin{equation}
    \mathbb{E}\mathbb{S}\left\{\mathcal{X}_0;U\right\}-\mathbb{E}\mathbb{S}\left\{\mathcal{X};U\right\}=c_m\int_U (\Psi(x)-1) \, \mathrm{d} M (x)
  \end{equation}
  where $c_m>0$ is a dimensional constant and $\mathrm{d} M (x)$ denotes integration with respect to the AT metric of $\mathcal{X}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

