body:
[Theorem thm:RGP-H7 of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed observable satisfies the mixed diamond
equation
\begin{equation}
\bigl(\mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}^{-1}
- q\mathcal{M}_{t-1, \mathbf{a}+\mathbf{2},
\mathbf{n}}^{-1}\bigr)
\mathcal{M}_{t-1, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}
- \mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}}^{-1}
\bigl(\mathcal{M}_{t-1, \mathbf{a}+\mathbf{1},
\mathbf{n}}
- q\mathcal{M}_{t, \mathbf{a},
\mathbf{n}+\mathbf{1}}\bigr) = 0,
\end{equation}
at every $(t, \mathbf{a}, \mathbf{n})$ with $t \ge 1$ and
$a_i < h_{n_i+1}(t{-}1) - 1$ for all~$i$.

[Lemma 14 (Uniform one-time boundary-approach bound) of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] Fix $T,\beta,\varepsilon>0$, $x\in\overline E_\varepsilon$, and $t\in[0,T]$.
Then
\[
\lim_{\delta\downarrow0}\;
\sup_{m\ge1}
\mathbb P_{x}^{T,\beta,\varepsilon,(m)}
\bigl(\varepsilon<|Y_t|\le \varepsilon+\delta\bigr)
=
0.
\]

[Lemma lem:flip of arXiv:2606.16259, 'Super-Arrhenius relaxation of the triangular plaquette model in any dimension'] Let $k\in\mathbb N$ and let $\mathbb{W}=(W_0, W_1, \dots, W_n)$ be a minimal good chain.
Let $0 < i < n$ be an index such that $|\ensuremath{\mathcal R}(W_i)\cap U_{k-1}| = k$.
Set $\mathcal{T}_1\coloneqq W_i\symdiff W_{i-1}$ and $\mathcal{T}_2\coloneqq W_{i+1}\symdiff W_i$, and set $W'\coloneqq W_{i-1}\symdiff\mathcal{T}_2$.
Then
\begin{enumerate}
\item $\mathcal{T}_1$ and $\mathcal{T}_2$ are disjoint spread plaquettes;
\item $|W_{i-1}\cap U_k| = |W_{i+1}\cap U_k| = k$;
\item the configurations $W_{i\pm 1}$ contain no ON lamps in $U_k\setminus U'_k$;
\item the configuration $W'$ is also critical;
\item the sequence $(W_0, W_1, \dots, W_{i-1}, W', W_{i+1}, \dots, W_n)$ is also a minimal good chain.
\end{enumerate}

[Proposition 15 of arXiv:2608.18075, '2608.18075'] For every set $D$
on which $\mathcal W$ is bounded,
\begin{align}
 \lim_{N\to\infty}\sup_{x\in D}
 \mathbf{P}_x\left\{\exists n\ge N:
   \frac1n\sum_{k=0}^{n-1}a_q(X_k,Y_k)>-4\lambda\right\}=0.
\end{align}

[Proposition 12 (Wandering decomposition) of arXiv:2608.22342, 'Completely Positive Entropy and Fourier Central Limit Theorems for Stationary Random Measu'] Let $T$ be a probability-preserving $\bZ^d$-action and let
$\mathcal A_0$ be given by Theorem~\ref{thm:kaminski-perfect-past}. Then
\begin{equation}

    L^2(X,\mu)\ominus L^2(\Pi(T))
    =\bigoplus_{k\in\bZ^d}U^kK_0.
\end{equation}
In particular, if $T$ has CPE, then
\begin{equation}

    L^2_0(X,\mu)=\bigoplus_{k\in\bZ^d}U^kK_0.
\end{equation}

[Defi action of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] For $m\in W^{1,1}( (0,T); {\mathcal P}(\mathcal X))$ and $J\in L^1((0,T); \mathbb{R}_a^{\mathcal E})$ we define
   the action functional
\begin{align*}
    \mathcal{A}(m,J)=\int_0^T F( m_t,J_t)\, dt

\end{align*}
whenever 
\begin{align}
    \partial_tm_t(x)+\sum_{y\sim x}J_t(x,y)=0 \quad\text{ for all }x\in\mathcal X,
\end{align}
and infinity otherwise.

[Definition eq:defA of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For any ${\boldsymbol{\tau}} \in\text{$\widehat{\mathcal{T}}$}$ such that $r({\boldsymbol{\tau}})\geqslant1$, we set $k\equiv k({\boldsymbol{\tau}})\eqdef\min\{i\in[p({\boldsymbol{\tau}})]:r_i=1\}$. Moreover, to have notation for writing Leibniz rule for scale derivatives of cumulants, for ${\boldsymbol{\tau}} = \big( (\tau_{i},0,u_i) \big)_{i=1}^{p({\boldsymbol{\tau}})} \in \text{$\widehat{\mathcal{T}}$} $ (note that $r({\boldsymbol{\tau}}) = 0$) and $1 \leqslant k \leqslant p({\boldsymbol{\tau}})$, we define \textcolor{white}{$\mathbf d$}
\begin{equs}
    \mathbf{d}_{k} {\boldsymbol{\tau}} \eqdef \Big( (\tau_{i}, \mathbf{1}\{i = k\},u_i) : 1 \leqslant i \leqslant p({\boldsymbol{\tau}}) \Big) \in \widehat{\mathcal{T}}\,.
\end{equs}
Note that is holds $k(\mathbf{d}_k{\boldsymbol{\tau}})=k$.

Fix ${\boldsymbol{\tau}} \in\widehat\mathcal{T}$ such that $r({\boldsymbol{\tau}})\geqslant1$, and recall the definition of $\text{$\mathrm{Ind}$}(\tau_k)$ given in Definition~(def:defBmu of the paper). Moreover, fix $v_1,v_2\in\{0,1,2\}$ such that $v_1+v_2=u_k$. We combine $v_1,v_2$ and $(\sigma_1,\sigma_2)\in\text{$\mathrm{Ind}$}(\tau_k)$ in the forest ${\boldsymbol{\sigma}} = \big((\sigma_1,v_1),(\sigma_2,v_2) \big)$. 

We then define 
\begin{equs}
\text{$ {\mathrm{Ind}}$}(\text{${{\boldsymbol{\tau}}}$})\eqdef
\Bigg\{ 
\big({\boldsymbol{\sigma}}, \pi,\rho \big):
\begin{array}{c}
(\sigma_1,\sigma_2) \in \text{$\mathrm{Ind}$}(\tau_k)\,,\\
 v_1,v_2\in\{0,1,2\}:\,v_1+v_2=u_k\,,
\\
(\pi,\rho) \in \mathcal{Q}\big([p(\text{${{\boldsymbol{\tau}}}$})]\setminus\{k\},[2]\big)
\end{array}
\Bigg\}\;.
\end{equs}
The set $\mathrm{Ind}({\boldsymbol{\tau}})$ will appear as an indexing set for a sum in our cumulant equation. 
To motivate this notation, we note that upon fixing ${\boldsymbol{\sigma}}$, we are working with a cumulant of the form (suppressing time arguments) 

\[
\kappa_{p({\boldsymbol{\tau}})}
\Big( \big(\xi^{\tau_i}_{{\eps,\mu}}: i \in [p({\boldsymbol{\tau}})] \setminus \{k\} \big), 
\xi^{\sigma_2} \graft^{\mu} \xi^{\sigma_1}
\Big)
\]
We then generate a sum over $(\pi,\rho)$ using (equation eq:relcum of the paper), each term corresponding to a product of joint cumulants indexed by the $|\rho|$ different blocks of  $\rho$. 

We fix $({\boldsymbol{\sigma}},\pi,\rho)\in\mathrm{Ind}({\boldsymbol{\tau}})$. For each $1 \leqslant q \leqslant |\rho|$, we define ${\boldsymbol{\lambda}}_{q} \in \text{$\widehat{\mathcal{T}}$}$ via the concatenation of ordered forests ${\boldsymbol{\lambda}}_q \eqdef {{\boldsymbol{\tau}}}_{\pi_q}\sqcup{{\boldsymbol{\sigma}}}_{\rho_q}$, where we set  ${\boldsymbol{\lambda}}_q={\boldsymbol{\sigma}}_{\rho_q}$ if $p({\boldsymbol{\tau}})=1$. 

Now, in order to define our analogue of the r.h.s. of (equation eq:flowLabelled of the paper) for the cumulant flow, we fix some representative $\underline{\boldsymbol{\tau}}\in {\boldsymbol{\tau}}$ verifying (equation eq:restrictionforest of the paper). For $j\in[2]$, we also fix some representatives $\underline{\sigma}_j\in\sigma_j$, along with $f\in\mathrm{Aut}(\underline{\tau}_k)$ and $n\in N(\underline{\sigma}_1)$ such that $\underline{\tau}_k=\underline{\sigma}_2\graft_n\underline{\sigma}_1$.

Then, following Remark~(rem:2_24 of the paper), we introduce the short-hand notations
 \begin{equs}       
    \ell_{\underline{\sigma}_1,\underline{\sigma}_2,j}\eqdef \begin{cases}  
  0 & \text{for} \;j= 1\,, \\
