[Definition 61 of arXiv:2607.18104, '2607.18104'] For each $j\in \N$, consider families of ASEPs on the integers $(\eta_t^{N,i,1,j})_{t \geq 0}$ and $(\eta_t^{N,i,2,j})_{t \geq 0}$ under the patched coupling with $i \in \lbr M \rbr$ and $N \in \N$. We define the $\boldsymbol{(\delta,N)}$\textbf{-patched ASEP} $(\eta^{\textup{patch},N,i}_t)_{t \geq 0}$, taking values in $\{0,1\}^{\Z/N\Z}$, as follows. First, let $j=1$, and define
\begin{equation}
\eta^{\textup{patch},N,i}_t(x) := \begin{cases} \eta_t^{N,i,1,1}(x) & \text{ if } (x,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,\frac{1}{2}\big) ,   \\
\eta_t^{N,i,2,1}(x) & \text{ if } (x,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(\frac{1}{2},1\big) , 
\end{cases}
\end{equation} where the points $x$ are understood modulo $N$. 

In order to define $\eta^{\textup{patch},N,i}_t$ for $t>\delta N^{3/2}$, we proceed inductively. Suppose that we have constructed $(\eta^{\textup{patch},N,i}_t)_{t \in [0,j \delta N^{3/2}]}$ for some $j\in \N$ (the base case $j=1$ is covered above). Then consider two families of ASEPs $(\eta^{N,i,1,j+1}_t)_{t \geq 0}$ and $(\eta^{N,i,2,j+1}_t)_{t \geq 0}$, started at time $j\delta N^{3/2}$, where assign for all $i\in \lbr M \rbr$
\begin{equation}
\begin{split}
        \eta^{N,i,1,j+1}_{j\delta N^{3/2}}(x) &= \bar{\eta}^{N,i}_{j\delta N^{3/2}}(x) \ \forall x \colon (x,j\delta N^{3/2}) \in \mathcal{I}_{\delta,N}^{\rho}\Big(-\frac{1}{8},\frac{5}{8}\Big) , \\
        \eta^{N,i,2,j+1}_{j\delta N^{3/2}}(x)&=  \bar{\eta}^{N,i}_{j\delta N^{3/2}}(x) \ \forall x \colon (x,j\delta N^{3/2}) \in \mathcal{I}_{\delta,N}^{\rho}\Big(\frac{3}{8},\frac{9}{8}\Big)  .
\end{split}
\end{equation} For all other $x$, we assign independent Bernoulli-$\rho$-random variables.
Then $(\eta^{N,i,1,j+1}_t)_{t \geq 0}$ and $(\eta^{N,i,2,j+1}_t)_{t \geq 0}$ evolve according to the patched coupling between time $j\delta  N^{3/2}$ and $(j+1)\delta N^{3/2}$, independently of the processes up to time $\delta j N^{3/2}$. Set for all $s \in [j \delta N^{3/2},(j+1)\delta N^{3/2}]$,
\begin{equation}
\eta^{\textup{patch},N,i}_{s}(x) := \begin{cases} \eta_{s}^{N,i,1,j+1}(x) & \text{ if } (x,s) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,\frac{1}{2}\big) ,   \\
\eta_s^{N,i,2,j+1}(x) & \text{ if } (x,s) \in \mathcal{I}_{\delta,N}^{\rho}\big(\frac{1}{2},1\big) . 
\end{cases}
\end{equation}

[Theorem 19 of arXiv:2607.11773, '2607.11773'] Suppose that {\bf(H1)}-{\bf(H4)}, \eqref{thetaassum1}, \eqref{thetaassum2}, \eqref{dissip1}, \eqref{dissip2} 
   and \eqref{dissip1-2} hold. 
   Then for every $\tau \in \mathbb{R}$ and $\theta \in \left(2, \tfrac{2(p-2)}{q-2} \right)$,
   there exists a positive constants $C_{\tau, \theta} = C(\tau, \theta) > 0$ and $\hat{\varepsilon} >0$ 
   such that for all $\varepsilon \in (0, \hat{\varepsilon} )$ and $\rho \in [0,1]$, 
   \begin{align} 
         \mathbb{W}_\theta \left( \mu_\tau^\varepsilon, \mu_{\tau}^0 \right)
         \le C_{\tau, \theta} \, \varepsilon^{\frac{1}{2}},
   \end{align}
   and the convergence order $\frac{1}{2}$ is optimal.

[Proposition 8 of arXiv:2606.06859, 'The rectangular finite free heat flow'] For $r_1 > \dots > r_d > 0$, we have
    \begin{equation} 
        I(r) = \sum_{k=1}^d \frac{(n+1)^2}{r_k^2} + \sum_{1 \le i < j \le d} \left( \frac{2}{(r_i - r_j)^2} + \frac{2}{(r_i + r_j)^2} \right).
    \end{equation}

