    \begin{multline}
    \left( \sum_{j\colon j\ne k} \left( \frac{1}{r_k-r_j} + \frac{1}{r_k+r_j} \right) + \frac{n+1}{r_k} \right)^2
    = \frac{(n+1)^2}{r_k^2}\\
    +\sum_{j\colon j\ne k}\left( \frac{1}{(r_k-r_j)^2} + \frac{1}{(r_k+r_j)^2} \right) + 2(n+2)\sum_{j\colon j\ne k}{ \frac{1}{r_k^2-r_j^2} }.
    \end{multline}
    Note that
    \begin{equation}
    \sum_{k=1}^d\ \sum_{j\colon j\ne k}{ \frac{1}{r_k^2-r_j^2}} = 0.
