[Proposition prop:wulffapprox of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] [addarioberry2025shapetheorembbmperiodic]
    Fix $a \in (0,1)$, let $\mathfrak{c}^*:S^{d-1}\rightarrow (a,a^{-1})$, and let $\mathcal{W}(\mathfrak{c}^*)$ be the Wulff shape of $\mathfrak{c}^*$. Then for $\epsilon\in (0,1)$ there exist finite sets $\mathcal{R},\mathcal{Q}\subset S^{d-1}$ such that 
    \begin{enumerate}[(i)]
        \item $ \bigcap_{r\in \mathcal{R}} \mathcal{H}_{r,\mathfrak{c}^*(r)}^{-}\subset(1+\epsilon)\mathcal{W}(\mathfrak{c}^*)$, and
        \item for every compact convex set $K\subset B(0,2a^{-1})$, if for every $q\in \mathcal{Q}$, $K\cap \mathcal{H}^+_{q,\mathfrak{c}^*(q)} \neq \emptyset$, then 
        \begin{equation*}
            (1-\epsilon)\mathcal{W}(\mathfrak{c}^*)\subset K.
        \end{equation*}
    \end{enumerate}

[Theorem eq:theta-logpotential of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:theta}
Let
\begin{equation}
 \theta_p(u)=\frac12-\frac12\log p-\frac{u^2}{2}
 +\int\log\abs{\sqrt{2p(p-1)}\lambda-pu}\,\rho_{\mathrm{sc}}(\,\mathrm d\lambda).
\end{equation}
Then
\begin{equation}
 \theta_p(u)=\frac12\log(p-1)
 -\frac{p-2}{4(p-1)}u^2-\mathcal I_p(u).
\end{equation}
For every continuous \(V\) bounded below,
\begin{equation}
 \Phi_p^{\rm bulk}(V)
 :=\sup_{u\in\mathbb R}\{\theta_p(u)-V(u)\}
\end{equation}
is the iterated determinant/delta de-regularization of the Gaussian pressure in (thm:gaussian-variational of the paper); see (thm:dereg-variational of the paper).  Moreover,
\begin{equation}
 \theta_p(u)=\inf_{V\in\mathcal V_\infty}
 \{\Phi_p^{\rm bulk}(V)+V(u)\},
\end{equation}
where \(\mathcal V_\infty=\bigcap_{m\ge2}\mathcal V_m\). (Proof in the paper; no proof environment follows the statement in the TeX.)

