[Lem 11 (A Priori Estimates) of arXiv:2506.13587, 'Non-exchangeable mean-field theory for adaptive weights: propagation of dissociatedness an'] Let $\overline{\mathcal{Y}} = (\overline{\mathsf{X}}, \overline{\mathsf{W}})$ be an adapted process.
The operator $\Psi$ satisfies the following moment propagation estimate: for any $t \in [0,T]$,
\begin{equation*}
\begin{aligned}
&\|\Psi^{\mathsf{X}}(\overline{\mathcal{Y}})\|_{t, L^2}^2 \leq 4 \bigg( \|\overline{\mathsf{X}}_0\|_{L^2}^2 + \|\mu\|_{L^\infty}^2 t^2 + d \nu^2 t + \|\overline{\mathsf{W}}\|_{t, L^\infty}^2 \|\sigma\|_{L^\infty}^2 t^2 \bigg),
\\
&\|\Psi^{\mathsf{W}}(\overline{\mathcal{Y}})\|_{t, L^\infty} \leq \|\overline{\mathsf{W}}_0\|_{L^\infty} + \int_0^t \Big( \|\alpha\|_{L^\infty} \|\overline{\mathsf{W}}\|_{s, L^\infty} + \|\beta\|_{L^\infty} \Big) \, \mathrm{d}s.
\end{aligned}
\end{equation*}
Here, the norms are defined as 
\begin{equation*}
\begin{aligned}
\|\overline{\mathsf{W}}\|_{t, L^\infty} \coloneqq \sup_{s \in [0,t]} \|\overline{\mathsf{W}}(s)\|_{L^\infty((\Omega \times \widehat{\Omega})^2)},
\quad \|\overline{\mathsf{X}}\|_{t, L^2} \coloneqq \sup_{s \in [0,t]} \|\overline{\mathsf{X}}(s)\|_{L^2(\Omega \times \widehat{\Omega})}.
\end{aligned}
\end{equation*}


Moreover, $\Psi$ satisfies the Lipschitz continuity estimate.
Let $\overline{\mathcal{Y}}^{(k)} = (\overline{\mathsf{X}}^{(k)}, \overline{\mathsf{W}}^{(k)})$ ($k=1,2$) be two adapted processes on the same latent space $\Omega$.
Then, for any $t \in [0,T]$,
\begin{equation*}
\begin{aligned}
& \|\Psi^{\mathsf{X}}(\overline{\mathcal{Y}}^{(1)}) - \Psi^{\mathsf{X}}(\overline{\mathcal{Y}}^{(2)})\|_{t, L^1} + \|\Psi^{\mathsf{W}}(\overline{\mathcal{Y}}^{(1)}) - \Psi^{\mathsf{W}}(\overline{\mathcal{Y}}^{(2)})\|_{t, \square}
\\
& \quad \leq \|\overline{\mathsf{X}}^{(1)}_0 - \overline{\mathsf{X}}^{(2)}_0\|_{L^1} + \|\overline{\mathsf{W}}^{(1)}_0 - \overline{\mathsf{W}}^{(2)}_0\|_{\square}
+ C(t) \int_0^t \Big( \|\overline{\mathsf{X}}^{(1)} - \overline{\mathsf{X}}^{(2)}\|_{s, L^1} + \|\overline{\mathsf{W}}^{(1)} - \overline{\mathsf{W}}^{(2)}\|_{s, \square} \Big) \, \mathrm{d}s,
\end{aligned}
\end{equation*}
where $C(t)$
depends on time, dimension, and the bounds in Assumptions~\ref{assu:coefficients} and $\|\overline{\mathsf{W}}_0\|_{L^\infty}$.
This estimate remains valid if all the cut norms $\|\cdot\|_{\square}$ are replaced by $L^1$ norms.

[Lemma SL_facts of arXiv:2601.04997, 'Fluctuations of the Boundary-Driven Symmetric Zero-Range Process from the NESS'] For each $j=0, 1, 2$, the system $\textsc{SL}_j(A)$ satisfies the following:
\begin{enumerate}[i)]

    \item the spectrum is real and an ordered sequence $\gamma_1<\gamma_2<\ldots \to\infty$; 

    \item the sequence of normalised eigenfunctions $\{\psi_n\}_n$ forms a complete, orthonormal basis of the $A^{-1}$-weighted Hilbert space      \begin{equation}
        L^2([0, 1], A(u)^{-1}\de u):=\left\{f:[0, 1]\to\mathbb{R}: \|f\|^2_{L^2([0, 1], A^{-1})}<\infty\right\},
    \end{equation}
    where $\|\cdot\|_{L^2([0, 1], A^{-1})}$ denotes the norm associated to the inner product
    \begin{equation*}
        \langle f, h\rangle_{L^2([0, 1], A^{-1})}:=\int_0^1 f(u)A(u)^{-1}h(u)\de u;
    \end{equation*} 

    \item the sequence $\{\psi_n\}_n$ defined above satisfies the bound $\|\psi_n\|_\infty \lesssim \sqrt{\gamma_n}\vee 1$.

\end{enumerate}

