[Prop p:half-strip-ES of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Let $\gamma\in(0,\frac{1}{6})$ be the parameter fixed at the beginning of (s:discrete-LPP-proxy of the paper).
    There exist $C,c,\alpha>0$ depending only on $S_1,S_2,\gamma$
    such that for all small enough $\delta>0$ and $\varepsilon\leqslant \delta^{100/\gamma}$, we have
    \begin{align}
        \sup_{u}
        \mathbb{E}\left[
            \Var(\widehat{\mathcal{L}}^\varepsilon(u)\mid \bm{\mathcal{L}}^{\mathrm{near}})
        \right]
        &\leqslant C\left(\varepsilon^{\alpha}+\frac{1}{\varepsilon^{3/2}}
        e^{-c\log^2(1/\delta)}\right),
    \end{align}
    where the supremum is over all $u=(0,z;\delta^{3/2},w)$ with $z,w\in J^\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 (Main Theorem) of arXiv:2604.05138, 'Convergence rate of $H$-property for step-graphons'] Let $W$ be a step-graphon and $P_n(W)$ be given in~\eqref{eq:defPn}. 
Then, the following items hold:

\begin{enumerate}
\item If $W$ satisfies Conditions $A$ and $B$, then there exist positive constants $c$ and $\lambda$ such that

\begin{equation}
    1 - P_n(W) \leq c\, e^{-\lambda n}.
\end{equation}

\item If $W$ does not satisfy Condition $B'$, then there exist positive constants $c$ and $\lambda$ such that

\begin{equation}
P_n(W) \leq c \, e^{-\lambda n}. 
\end{equation}

\item If $W$ satisfies Condition $B'$, but not $A$, then there exist a positive constant $c$ such that 
\begin{equation}
P_n(W) \leq \frac{c}{\sqrt{n}}.
\end{equation}

\item If $W$ satisfies Condition $A$ and $B'$, but not $B$, then there exist a $p^*\in (0,1)$ and a positive constant $c$ such that
\begin{equation}
|P_n(W) - p^*| \leq \frac{c}{\sqrt{n}}.  
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L: pulling down of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Suppose that $T$ is a monotone operator on $CDF(\overline{\mathbb{R}})$ satisfying the assumptions of Proposition (P: contractive of the paper).  If $\{F_{n}\}$ is any sequence with $F_{n} \leq TF_{n-1}$ for each $n$, then, for any $\delta > 0$, the sequence $\{ \tilde{F}_{n} \}$ given by $\tilde{F}_{n} = \max\{ F_{n} - \delta ( 1 + L )^{n}, 0 \}$ satisfies 				\begin{align}  
			\tilde{F}_{n} \leq T \tilde{F}_{n-1} \quad \text{for each} \, \, n.
		\end{align}

	In particular, if $\{F_{n}\}$ and $\{G_{n}\}$ are any two sequences in $CDF(\overline{\mathbb{R}})$ such that 

		\begin{align*}
			F_{n} \leq TF_{n - 1} \quad \text{and} \quad G_{n} \geq TG_{n - 1} \quad \text{ for each} \, \, n \in \mathbb{N} ,
		\end{align*}
	then
		\begin{align*}
			F_{n} \leq G_{n} + ( 1 + L )^{n} \sup \left\{ ( F_{0}(x) - G_{0}(x) )_{+} \, \mid \, x \in \mathbb{R} \right\}  \quad \text{for each} \, \, n.
		\end{align*}

