[Proposition prop:marginal of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] If $M_\beta = U_\beta = \{p\}$ or all graphs $G_0, G_1, \dotsc, G_K$ in the ERGM specification are forests, then
\begin{equation}
    \mleft|\mathbb{E}[X(e)] - p \mright| \lesssim \sqrt{\frac{\log n}{n}}
\end{equation}
for any $e \in \binom{[n]}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 136 ({\cite{gerbelot2021graph}}) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] In the AMP recursion \eqref{eq:IAMP-fully-general-fixed}, for any $\ell\geq 1$ and $1$-pseudo-Lipschitz $\psi$, we have the convergence in probability to the limiting random variables
\eqref{eq:state-evolution-setup} in the sense
  \begin{equation}

    \begin{aligned}
    \plim_{N\to\infty}
    \frac{1}{N}
    \sum_{n=1}^N
    \psi\Big(
    u_n[[\ell]],
    \bar{g}_n[\ell]
    , y_n[0] 
    \Big)
    &=
    \bbE\psi\Big( 
    \vec U, \vec{\bar{G}}
    , Y[0] 
     \Big)\,,
    \\
    \plim_{N\to\infty}
    \frac{1}{M}
    \sum_{m=1}^M
    \psi\Big(
    v_m[[\ell]]
    , x_m[0] 
    \Big)
    &=
    \bbE\psi\Big( \vec V,
    	X[0] \Big)\,.
    \end{aligned}
  \end{equation}
We also have convergence in Wasserstein $\bbW_2$ distance,
  \beq

    \frac{1}{N}
    \sum_{n=1}^N
    \delta_{u_n[[\ell]],
    \bar{g}_n[\ell],y_n[0]
    }
    \to \Law( \vec U,
      \vec {\bar{G}}
      , Y[0] 
      ), \qquad 
    \frac{1}{M}
    \sum_{m=1}^M
    \delta_{v_m[[\ell]], x_m[0]} 
    \to \Law(\vec V, X[0] )\,,
  \eeq
where again the convergence holds in probability as $N\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 26 of arXiv:2609.01128, 'Nonabelian Chabauty for the Thrice-punctured Line over Cyclotomic Fields'] Assume the $p$-adic period conjecture. For $K=\bQ(\zeta_8)$, $S=\left\{(1-\zeta_8)\right\}$ and primes $p$ splitting completely in $K$,
\begin{align*}
    X(\cO_{K,S})\cup \mathcal{R}_p \cup X(\bZ[\sqrt{2}]\otimes\bZ_p)_{(\sqrt{2}),\PL,2}&\subseteq X(\cO_K\otimes\bZ_p)_{S,\mathrm{PL},3},\\
    X(\cO_{K,S})\cup \mathcal{R}_p\cup X(\bZ[\sqrt{2}]\otimes\bZ_p)_{(\sqrt{2}),\PL,2}^{\min}&\subseteq X(\cO_K\otimes\bZ_p)_{S,\mathrm{PL},3}^{\min}.
\end{align*}
All of the above containments are equalities unconditionally for all primes $p<200$ which split completely in $K$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2605.21209, 'Sensitivity analysis of Stochastic Fluid Models: \\Stationary and transient quantities wit'] For any $0<x<y$,
\begin{eqnarray*}
\lefteqn{
\frac{\partial}{\partial\btheta}
\left[
	\begin{array}{cccc}
		{\bf O}_{++}&{\bf G}_{+-}^{(x,y)}(s)&
