	\end{array}
	\right]
}
\\
&=&
\Vast\{
\frac{\partial}{\partial\btheta}
	\left[
	\begin{array}{cccc}
 {\bf 0}_{++}&
\bPsi(s;\btheta)e^{{\bf D}(s;\btheta)x}&
e^{{\bf U}(s;\btheta)(y-x)}&
{\bf 0}_{+-}
\\
{\bf 0}_{-+}&
e^{{\bf D}(s;\btheta)x}&
\bXi(s;\btheta)e^{{\bf U}(s;\btheta)(y-x)}&
