  {\bf H}_{++}^{(x,y)}(s)&{\bf O}_{+-}\\
		{\bf O}_{-+}&{\bf G}_{--}^{(x,y)}(s)&{\bf H}_{-+}^{(x,y)}(s)&{\bf O}_{--}
	\end{array}
	\right]
\left(
\frac{\partial}{\partial\btheta}
\left[
	\begin{array}{cccc}
{\bf I}&{\bf 0}&
e^{{\bf U}(s;\btheta)y}&
{\bf 0}_{+-}
\\
