	\right]
\right)
\Vast\}
\\
&&
\times
\left(
{\bf I}
\otimes
\left[
	\begin{array}{cccc}
{\bf I}&{\bf 0}&
e^{{\bf U}(s;\btheta)y}&
{\bf 0}_{+-}
\\
