body:
[Theorem thm:ergodic via independece of core of arXiv:2411.02030, 'Finite ergodic components for upper probabilities'] Let $(\Omega,\mathcal{F},V,T)$ be an UPPS. Then the following statements are equivalent:
	\begin{enumerate}
		\item [(i)] $V$ is of finite ergodic components;
		\medskip
		\item [(ii)]there exist  $Q_1,\ldots,Q_n\in\mathcal{ M}(T)\cap\operatorname{core}(V)$ and $A_1,\ldots,A_n\in\mathcal{I}$ satisfying that  $\Omega=\cup_{j=1}^nA_j$, $Q_j(A_j)=1$, and $A_j\cap A_k=\emptyset$ when $j\neq k$ such that  for any  $P\in\operatorname{core}(V)$, 
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}P(B\cap T^{-i}C)=\sum_{j=1}^nQ_j(C)P(A_j\cap B)\text{ for any }B,C\in\mathcal{F}.
		\end{equation}
	\end{enumerate}

