[Theorem thm:generalized:sink of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Let $c(x,\cdot)$ be $\mathcal{C}^1(\mathcal{Y})$ and assume that there exist $\Lambda\in(0,+\infty)$, a non-negative function $\omega\colon\mathcal{Y}\times\mathcal{Y}\to\mathbb{R}$ and $N\geq 2$ such that 
\begin{equation*}
y\mapsto c(x,y)+\psi^{n}_\varepsilon(y)
\end{equation*}
is $(\Lambda,\omega)$-semiconcave uniformly in $x\in\supp(\rho)$ and $n\geq N-1$. 
\begin{enumerate}[label=(\roman*)] 
\item If $\nu$ satisfies (eq:generalized:TI of the paper), 
then for all $n\geq N-1$
\begin{equation*}
 \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{n+1,n+1})\leq \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{n+1,n})\leq  \bigg(1-\frac{\min\{ \tau\Lambda,\,\varepsilon\}}{\min\{ \tau\Lambda,\,\varepsilon\}+\tau\Lambda}\bigg)^{(n-N+2)} \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{0,0})\,.
\end{equation*}
\item 
 If Sinkhorn iterates $\nu^{n,n-1}$ satisfy (eq:generalized:TI of the paper), uniformly in $n\geq N$, then 
 \begin{equation*} 
 \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{n+1,n+1})\leq \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{n+1,n}) \leq \bigg(1-\frac{  \varepsilon }{\varepsilon+\tau \Lambda}\bigg)^{(n-N+1)} \mathrm{KL}(\pi_\varepsilon^{\rho\nu}|\pi^{0,0})\,.
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main of arXiv:2609.03607, 'Scaling limit for the pinning model in correlated Gaussian environment beyond the $L^2$-re'] Assume $H\in(\frac12,1)$ and $\rho\in(\frac{1}{2H-1},2]\Longleftrightarrow\alpha+2H>2$ and $\alpha\in(0,\frac12]$. Take
\begin{equation}
\beta_N:=\hat{\beta}\frac{L(N)}{N^{\alpha+H-1}}.
\end{equation}
Let $\widehat{Z}_{\lfloor Nt\rfloor}^{\beta_N}$ be defined as in (equation def:wick_pf of the paper). Then as $N\to\infty$, 
\begin{equation}
\widehat{Z}_{\lfloor Nt\rfloor}^{\beta_N}\overset{\text{(d)}}{\longrightarrow}u^{( \kappa_\alpha\hat{\beta})}(t,0),
\end{equation}
where $u^{(\kappa_\alpha\hat{\beta})}(t,x)$ is the $L^1$-solution of (equation def:mild of the paper) with $\beta$ replaced by $\kappa_\alpha\hat{\beta}$, and $\kappa_\alpha:=C_\alpha/g_{\rho}(1,0)$ with $C_\alpha$ the constant arising from the local limit theorem (see [Don97])
\begin{equation}
C_\alpha:=\lim\limits_{n\to\infty}n^{1-\alpha}L(n){\ensuremath{\mathbf P}} (n\in\tau)=\frac{\alpha\sin(\pi\alpha)}{\pi},
\end{equation}
and $g_\rho(t,x)$ the transition density of the symmetric stable process $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 (\cite{CT}) of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Let the triplet $(\xi^l,f^l,g^l)$, $l=1,2$, satisfy (H1)-(H3). Let $(Y^l,Z^l,K^l)\in\mathfrak{S}^2_G(0,T)$, $l=1,2$, be the solution to the following $G$-BSDE:
	\begin{displaymath}
		Y^l_t=\xi^l+\int_t^T f^l(s,Y^l_s,Z^l_s)ds+\int_t^T g^l(s,Y^l_s,Z^l_s)d\langle B\rangle_s+V_T^l-V_t^l-\int_t^T Z^l_s dB_s-(K^l_T-K^l_t),
	\end{displaymath}
	where process $\{V_t^l\}_{0\leq t\leq T}$ is continuous with finite variation. Assume that 
    \begin{align*}
        (Y^l,Z^l,K^l_T,V^l)\in S^\infty_G(0,T)\times BMO_G\times\bigcap_{p\geq 1}L^p_G(\Omega_T)\times \bigcap_{p\geq 1}S^p_G(0,T),
    \end{align*}
    and $K^l$ is a non-increasing $G$-martingale. 
    If $\xi^1\geq \xi^2$, $f^1\geq f^2$, $g^1\geq g^2$, q.s. and $V^1-V^2$ is a non-decreasing process, then we have $Y_t^1\geq Y_t^2$, q.s. for any $t\in[0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

