     \langle f, \xi_i(t)\rangle & = \langle f, \xi_i(0)\rangle + \langle f, \beta_i(t)\rangle - \int_0^t\langle f\times \iota, \xi_i(s)\rangle ds +  \int_0^t \langle f\times\iota, \xi_{i+1}(s)\rangle ds,\mbox{ for all }i\geq 3,
