[Lemma 6 of arXiv:2604.07579, 'Topology of Percolation Clusters: Central Limit Theorems beyond the Lattice'] Let $f$ be the growth function of a quasi-transitive
      graph. The function $f$ has subexponential growth if and only if
      there exists a function $g:\mathbb{N}\to\mathbb{N}$ satisfying the
      following conditions:
      \begin{enumerate}
        \item  $\lim\limits_{r\to\infty}g(r)=\infty$;

        \item  $0<g(r)<r$ for all sufficiently large $r$;

        \item  $\displaystyle \lim\limits_{r\to\infty}
          \frac{f(r)-f(r-g(r))}{f(r)}=0$.

        \item  For any fixed $k \geq 0$,
          $\lim\limits_{r\to\infty}\frac{f(2g(r)+k)}{f(r)}= 0,$
      \end{enumerate}

[Lem ;lh of arXiv:2604.12462, 'Stochastic analysis of Beckner's and related functional inequalities'] We have 
\begin{align}
 J(s,x)\le \frac{2\Gamma (1+1/q)}{p\Gamma (1+1/q-p/q)}
 \!\left( 
 \frac{q^{2}}{2}
 \right) ^{p/q}\!s^{p/q}
\end{align}
for all $s,x\ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 65 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Let $(\delta_n)_{n\in \mathbb{N}}\subset (0,1)$ such that $\delta_n \to 0$ as $n \to \infty$. Assume Assumption \ref{ass-A3} holds. Suppose that $\bu_n \to \bu$ in $L^2([0,T] \times \domO)$. Then, we have
\begin{equation}
\lim_{n \to \infty} \int_0^T \int_{\domO} \Vert \bg_{n}(t,x;\bu_n(t,x)) -  \widetilde{\bG}^{\delta_n,n}(t,x;\bu_n(t,x)) \Vert_\mathrm{Y}^2\, \d x\,\d t
=0.
\end{equation}

[Lem 7 of arXiv:2608.30763, 'Ultracontractivity of heat semigroups with non-local Robin boundary conditions via two-sid'] Let $p \geq 2$ and $0 \leq \phi \in D( L(A,-C) )$ satisfy $L(A,-C)\phi = \mu \phi$. Assume in addition that  
\begin{enumerate}[a)]
\item $\phi \in \mathrm{L}^{p}(\Omega)$ and
\item $\gamma(\phi) \in \mathrm{L}^{p}(\partial \Omega)$
\end{enumerate}
are satisfied. Then $\phi^{p/2} \in H^{1}(\Omega)$. Moreover, there exists a constant $K \geq 1$, independent
of $p$, such that
\begin{equation}
\left\| \nabla ( \phi^{p/2} ) \right\|_{\mathrm{L}^{2}(\Omega)^{d}}^{2} \ \leq \ Kp^{2} 
\left\| \phi \right\|_{\mathrm{L}^{p}(\Omega)}^{p}.
\end{equation}

[Definition def:seq-consistency of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\mathcal{Y},\hat\mathcal{Z},T)$ be a sequential gamble space.
  We say $P\in\Delta(\mathcal{Y}^T)$ is \emph{sequentially consistent} if $P$ admits a regular conditional probability measure
  \footnote{The measure $P(\cdot \mid s)$ is \emph{regular} if (i) $P(\cdot \mid s) \in \Delta(\mathcal{Y})$ holds $P$-a.s., and (ii) $s\mapsto P(\cdot \mid s)$ is a measurable function.  (Recalling that $\mathcal{Y}$ is a measurable space, we equip $\mathcal{Y}^{<T}$ with the disjoint union $\sigma$-algebra on $\mathcal{Y}^{<T} = \bigsqcup_{t< T} \mathcal{Y}^t$.)}
  and
  \begin{align}

    P(Y_{t+1} \mid Y_{1..t}) \in \Delta_0(\hat\mathcal{Z}^{(Y_{1..t})})
  \end{align}
  holds $P$-a.s.\ for all $t<T$.
  We define $\Delta_0^T(\hat\mathcal{Z}) \subseteq \Delta(\Omega)$
  to be the set of probability measures sequentially consistent with $\hat\mathcal{Z}$.

[Lem holder-bound-away-from-edge of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Using the same parameters as before, on the event
\begin{equation}
    \bigcap_{k=K}^{\widehat{K}}{\bigcap_{B^\nu\in\mathcal{B}_{{\lceil(1+\nu)k \rceil+4},n}^{R,+}}}E_1(B^\nu,s_k),
\end{equation}
the following holds. Let $x,y\in\Lambda_n$ and let $\gamma$ be a path from $x$ to $y$ with minimal diameter. Assume that $\dist(\gamma,\partial\Lambda_n)\geq R^{-L}$. Then 
\begin{equation}
    D_n(x,y)\leq C(R,\alpha,\nu) \!\left(R^{(\frac{5}{4}+3\nu)K}+R^{(\frac{1}{4}+3\nu)L}\right) \mathbf{q}_n.
\end{equation}

[Theorem thm : Intro/FdTmon of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Assume~(equation ass : Intro/main_thm/SubcriticalAtom of the paper) and~(equation ass : Intro/main_thm/ShapeThmStrong of the paper). For all $D\in \RegPD$,
    \begin{equation}
        \FdTmon (D) \coloneqq \FdTmoninf(D) = \FdTmonsup(D).
    \end{equation}
    If $\p{\sigma_k : \intervalleff0{L}\rightarrow X }_{k\ge1}$ is a highway network for $D$, then
    \begin{equation}
        \FdTmon (D)

            = \sum_{k\ge 1} \int_0^{L} J_{\mathrm{pp}} \p{\sigma_k'(t), \MD{\sigma_k}(t)}\mathrm{d} t. \end{equation}

    Moreover,

    \begin{equation}

        \begin{split} \FdTmon(D)
            &= \sup \set{ \sum_{k= 1}^K \int_0^{T_k} J_{\mathrm{pp}} \p{\gamma_k'(t), \MD{\gamma_k}(t)}\mathrm{d} t }
            {\begin{array}{c} K\in\mathbb{N}, \p{\gamma_k : \intervalleff{0}{T_k} \rightarrow X}_{1\le k\le K} \text{ $1$-Lipschitz}, \\ \text{injective and pairwise disjoint.} \end{array}  }\\

            &= \sup \set{ \sum_{k= 1}^\infty \int_0^{T_k} J_{\mathrm{pp}} \p{\gamma_k'(t), \MD{\gamma_k}(t)}\mathrm{d} t }
            {\begin{array}{c} \p{\gamma_k : \intervalleff{0}{T_k} \rightarrow X}_{k\ge 1} \text{ $1$-Lipschitz}, \\ \text{injective and pairwise disjoint.} \end{array}  }, \end{split} \end{equation}

        and

    \begin{equation}

        \FdTmon(D)
            =\int_X \max_{u\in \mathbb S_2} J_{\mathrm{pp}} \mathopen{}\mathclose\bgroup\originalleft( u, (\Pgrad D)_z(u)  \aftergroup\egroup\originalright) \hd\mathopen{}\mathclose\bgroup\originalleft( \mathrm{d} z \aftergroup\egroup\originalright).
    \end{equation}
    Besides, for all distinct $D_1, D_2 \in \RegPD$, if $D_1 \le D_2$ and $\FdTmon(D_2) < \infty$, 
    \begin{equation}
        \FdTmon(D_1) > \FdTmon(D_2).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] Let $t=t(L,u)\geq 0$ and  integer $r=r(L,v){\geq0}$ for large enough $L$ be given by
\begin{eqnarray}
t&:=&L +  m\log L + u,\\
r&:=&eL+ \left((e-1)m-\frac{1}{2}\right)\log L+v.
\end{eqnarray}
Then, as $L\to\infty$,
\begin{align}
 \overline{P}_r(t)&\sim \frac{1}{e-1}p_r(t),
\\
\log p_r(t)&=
\\\notag&\hskip-3em
-L + (e-1)u-v -   \log\sqrt{2\pi e} -\frac{1}{2}\log\left( 1+\frac{v}{eL}\right) - \frac{(eu-v)^2}{2(eL+v)}+O\left(\frac{\log L} {L^{1/2}} \right)
\end{align}
uniformly in $u,v$ within the range
\begin{eqnarray}
\frac{u}{L}+1&\ge&\varepsilon,\\
|eu-v|&=&O(L^{1/2})

\end{eqnarray}
 for any fixed $\varepsilon>0$.

[Lemma 26 (Mellin reduction of the Poisson energy) of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] Let $a=1-2s$, $0<s<1$, and let $u_0\in\Sm$. Then, for a.e. $\xi$,
\begin{equation}
\int_0^\infty|\widehat U_0(\xi,z)|^2z^a\,dz
=
\frac{2^{1-2s}}{\G(s)^2}
\int_0^\infty \nu^s|\mathfrak G_\xi(\nu)|^2\,d\nu,
\end{equation}
where
\begin{equation}
\mathfrak G_\xi(\nu):=
\int_0^\infty e^{i\nu/\sigma}\sigma^{-1-s}g_\xi(\sigma)\,d\sigma.
\end{equation}

