body:
[Theorem 3 (Uniform finite-horizon error) of arXiv:2608.30261, 'Estimating Population-Risk Curves Along Nonconvex Gradient Flows from the Training Sample'] Under \cref{ass:tube},
\begin{equation}
 \sup_{\substack{1\leq i\leq n\\\lambda\in\Lambda}}
 \max\{\|\Delta_{i,t}^\lambda\|,\|d_{i,t}^\lambda\|\}
 \leq (n-1)^{-1}M\phi_\kappa(t),\qquad 0\leq t\leq T,
\end{equation}
and
\begin{equation}
 \sup_{\substack{1\leq i\leq n,\ 0\leq t\leq T\\\lambda\in\Lambda}}
 \|\Delta_{i,t}^\lambda-d_{i,t}^\lambda\|
 \leq \frac{L_3M^2}{2}(n-1)^{-2}\mathcal J_\kappa(T).
\end{equation}
If, in addition, there is a finite $G_{\rm out}\geq0$ such that
\begin{equation}
 \sup_{\substack{1\leq i\leq n,\ 0\leq t\leq T,\ \lambda\in\Lambda\\
                   x\in B(\theta_t^\lambda,r_{\rm tube})}}
 \|\nabla\ell^{\rm ev}_{\lambda,Z_i}(x)\|\leq G_{\rm out},
\end{equation}
then
\begin{equation}
 \sup_{(t,\lambda)\in\cH}
 |\widetilde\Score_n(t,\lambda)-\Score_n^{\LOO}(t,\lambda)|
 \leq\frac{G_{\rm out}L_3M^2}{2}(n-1)^{-2}\mathcal J_\kappa(T).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Suppose that Assumption~(assumptions_Neurons of the paper) holds with $\overline{b}-C_{f}J>0$. Suppose moreover that (equation neu1 of the paper) is satisfied for every $q=1,\dots,p'$ with $p'\geq 2$. Let
		$\gamma _{k}=\frac{1}{(1+k)^{\beta }}$  with $
		1\geq\beta >\frac{1}{2 }$,
		then, for every  
		\begin{equation*}
			\zeta \in \Big(0,1-\frac{C_fJ}{\bar{b}}\Big)\cap \Big(0,\frac{p'-1}{ 5 (p'-1)+4}\Big],
		\end{equation*}
		one has 
		\begin{align*}
			\mbox{if $\beta=1$:}&\quad \mathbb{E}[W_{1}(\rho _{k}(Y),\mu _{\ast
			})]\leq \frac{C}{(\ln k)^\zeta}, \\
			\mbox{if $1>\beta>\frac 1{2}$:} &\quad \mathbb{E}[W_{1}(\rho
			_{k}(Y),\mu _{\ast })]\leq \frac{C}{k^{(1-\beta)\zeta}}, \end{align*}
		$\mu_*$ denoting the invariant measure associated with the stochastic equation (equation SJE_Neuron of the paper).

[Prop 16 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $\delta\in\mathbb{R}^d$ and $B\in \mathbb{R}^{d\times m}$  as in Theorem \ref{thm:RIP}. Let $A=\mathrm{Diag}(a_1, \cdots, a_d)$ be a diagonal matrix. For any $r\ge 1$, we have
\begin{align}
    &\big(\mathbb{E}\Vert  B^\T\cdot \mathrm{Diag}(\delta)\cdot A\cdot \mathrm{Diag}(\delta)\cdot B\Vert^{r}_{F} \big)^{1/r}\nonumber\\
    \lesssim& \Vert B\Vert_{l_2\to l_2}\cdot\Vert A\Vert_{l_2\to l_2}\big(\Vert \mathrm{Diag}(\sqrt{p_1}, \cdots, \sqrt{p_d} )\cdot B\Vert_{F}+ r^{1/2}\Vert B\Vert_{l_2\to l_2}\big).
\end{align}

