						\mathrm{d}y_t &= A\left( y_t, \int_{-r}^{0} y_{\theta+t} \pi(\mathrm{d}\theta) \right) \mathrm{d}t + \epsilon C(y_t, y_{t-r}) \mathrm{d}B_t(\omega), \\
						y_{\theta} &= \xi_{\theta} \quad \text{for} \quad \theta \in [-r, 0], \quad \xi \in C([-r, 0], \mathbb{R}^n).
					\end{split}
				\end{align}
				Let $y^{\xi,\epsilon}_{t}$ denote the solution and $\lambda_{1}<$, where $\lambda_{1}$ is  defined in (equation TRFVV of the paper). Then We can find $\epsilon_0>0$ such that for every  $0<\epsilon<\epsilon_0$ exusts $\lambda^\epsilon<0$ such that if $\xi\in C([-r,0],\mathbb{ R}^d)$, then 
				\begin{align*}
					\limsup_{t\rightarrow \infty}\frac{1}{t}\log\Vert y^{\xi,\epsilon}_t\Vert\leq \lambda^\epsilon, \ \  a.e.
				\end{align*}

