[Lemma 17 of arXiv:2609.04095, '2609.04095'] We have \(e_j=0\) for \(j<0\), while
\begin{equation}
 \sum_{j\ge0}e_jz^j=(1-z)^{1-g}.
\end{equation}
Moreover,
\begin{equation}
 e_j=\binom{g+j-2}{j}>0
 \qquad(j\ge0),
\end{equation}
and
\begin{equation}
 \frac{e_{j-1}}{e_j}
 =\frac{j}{g+j-2}
 \qquad(j\ge1).
\end{equation}

