\begin{enumerate}
	\item $\mathbb{P}(\mathcal{C}^{\ge 0}_{m}\ \text{is nice})\gtrsim  e^{-c\lambda^4}\theta_d(M)$; 


	\item If $\mathcal{C}^{\ge 0}_{m}$ is nice, then $\mathcal{H}^{\ge 0}_m \gtrsim     e^{-\lambda^5}M^{-[(\frac{d}{2}-1)\boxdot (d-4)]}$. 


\end{enumerate}

