[Definition 33 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] For~$(\xi,\eta)\in [-1,1]^2$, the \emph{action function} is given by
\begin{equation*}
F(z;\xi,\eta)=\frac{1}{2}(1-\xi)\log w-\frac{\ell}{2}(1-\eta)\log z-\log\prod_{m=1}^\ell\left(\gamma_m+\alpha_m z^{-1}\right).
\end{equation*}

[Theorem thm_singlerec of arXiv:2411.09976, 'Occupation times on the legs of a diffusion spider'] For $n \geq1$, 
\begin{align} 

\nonumber
\mathcal{L}_t\Bigg\{ \mathbf{E}_\mathbf{0}\left((A_t^{(i)})^{n}\right) \Bigg\}(\lambda) = \sum_{k=1}^{n}& \frac{n! D_k^{(i)}(\lambda)}{(n-k)! \lambda^k} \mathcal{L}_t\Bigg\{ \mathbf{E}_\mathbf{0}\left( (A_t^{(i)})^{n-k} \right) \Bigg\}(\lambda)\\ 
&+ \frac{n!}{\lambda^{n-1}} \mathcal{L}_t\Bigg\{ \mathbf{E}_\mathbf{0}(A_t^{(i)}) \Bigg\}(\lambda)
- \frac{n!}{\lambda^{n+1}} \sum_{k=1}^{n} D_k^{(j)}(\lambda),
\end{align}
where $\mathcal{L}_t$ denotes the Laplace transform with respect to $t$ of the function in curly brackets, $\lambda$ is the Laplace parameter, and  
\begin{equation}
D_k^{(i)}(\lambda) := \frac{\lambda^k}{(k-1)!} \int_0^\infty \mathbf{g}_\lambda(\mathbf{0},(y,i)) \mathbf{E}_{(y,i)}(H_\mathbf{0}^{k-1} \mathrm{e}^{-\lambda H_\mathbf{0}}) \beta_i\,m(\mathop{}\!\mathrm{d} y). 
\end{equation}
Furthermore, if $X$ is self-similar, then  for any $\lambda>0$, 
\begin{equation} 
\mathbf{E}_\mathbf{0}\left((A_1^{(i)})^{n}\right) = \mathbf{E}_\mathbf{0}\left(A_1^{(i)}\right) - \sum_{k=1}^{n} D_k^{(i)}(\lambda) \left( 1 - \mathbf{E}_\mathbf{0}\left( (A_1^{(i)})^{n-k} \right) \right), 
\end{equation}
and, in particular, $D_k^{(i)}(\lambda)$ does not depend on $\lambda$ for any $i=1,\dotsc,R$ and $k=1,2,\dotsc$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] We have the following convergence as $m \to \infty$:

\begin{equation}
S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z}_m,\tilde{g}_m) \longrightarrow S_{\text{{\tiny $1,\!\delta,\!\nu$}}}(\tilde{z},\tilde{g}) \quad \left\{
\begin{array}{l}
\text{in} \quad C([0,T]\,;L^2(\Omega)),\\[0.1cm]
\text{weakly in} \quad W^{1,2}(0,T\,;L^2(\Omega)),\\[0.1cm]
\text{weakly$^*$ in} \quad L^\infty (0,T\,;H^1(\Omega)),\\[0.1cm]
\text{weakly in} \quad L^2(0,T\,;H^2(\Omega)),
\end{array}
\right.
\end{equation}

whenever a sequence $\{(\tilde{z}_m,\tilde{g}_m)\}_{m \in \mathbb{N}} \subset D(S_{\text{{\tiny $1,\!\delta,\!\nu$}}})$ and a pair 
$(\tilde{z},\tilde{g}) \in D(S_{\text{{\tiny $1,\!\delta,\!\nu$}}})$ satisfy the following convergence as $m \to \infty$:

\begin{equation}

(\tilde{z}_m,\tilde{g}_m) \longrightarrow (\tilde{z},\tilde{g}) \quad \text{in} \quad C([0,T]\,;L^2(\Omega)) \times L^2(0,T\,;L^2(\Omega)),
\end{equation}

and the following boundedness:

\begin{equation}
\sup_{m\,\in\,\mathbb{N}} \int_0^T \|z_m'(t)\|_{L^2(\Omega)} dt < \infty.
\end{equation}

