[Proposition 146 (Sharp control of $\upmu$ and its derivatives) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following estimates hold.

\medskip

\noindent \underline{\textbf{Minima of $\upmu$ occur precisely on $\argubarnewultorus{\ubar}$.}} For each $\ubar \in [\leftubar,\ubarboot]$, we have:
	\begin{align} 
		\min_{\ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,\moreinterestingu_2]}} \upmu  =  \min_{\argubarnewultorus{\ubar}} \upmu \ge \frac{1}{1.01} \weight\big|_{\argubarnewultorus{\ubar}}  = \frac{-1}{1.01} \ubar. 
	\end{align}

\medskip		

\noindent \underline{\textbf{$\upmu$ is large when $|u| \geq \frac{3}{4}\interestingu$}}.
	The following lower bound holds, where $\boringregionmupositive > 0$ is the constant appearing in 
	\eqref{E:DATAMUISLARGEINBORINGREGION}:
	\begin{align} 
			\min_{\characteristicdiamondtwoarg{[\leftubar,\ubarboot]}{[\moreinterestingu_1,\moreinterestingu_2]} \setminus \characteristicdiamondtwoarg{[\leftubar,\ubarboot]}{[-\frac{3}{4}\interestingu,\frac{3}{4}\interestingu]}} \upmu
			& \geq \frac{\boringregionmupositive}{2}.
	\end{align}\medskip

\noindent \underline{\textbf{Transversal convexity of $\upmu$ and its consequences}}.
The following estimates hold:

	\begin{align} 
			\frac{\secondtransversalderivativemulowerbound}{5}
