		\min_{\characteristicdiamondtwoarg{[\leftubar,\ubarboot]}{[\moreinterestingu_1,\moreinterestingu_2]}}
				\Big\lbrace
				\newuL \newuL \upmu, \newuL \muX \upmu, 
				\muX \muX \upmu \Big\rbrace &
			\leq 
			\max_{\characteristicdiamondtwoarg{[\leftubar,\ubarboot]}{[\moreinterestingu_1,\moreinterestingu_2]}}
			\Big\lbrace
				\newuL \newuL \upmu, \newuL \muX \upmu, \muX \muX \upmu
