[Lemma Lem:Indep-Increments-augmentation of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that  $(\Omega, \mathscr{F}, \mathbb{P})$ is a probability space 
 with the family  of all $\mathbb{P}$-null sets of $\mathscr{F}$ denoted by $\mathscr{N}$, i.e. 
	\begin{equation}
\mathscr{N}\coloneqq\bigl\{ A \subset \Omega: \exists B \in \mathscr{F}: A\subset B \mbox{  and } \mathbb{P}(B)=0 \bigr\}.
\end{equation}
 Assume that $\mathbb{H}$ is the filtration $\mathbb{H}=(\mathscr{H}_t)_{t\ge 0}$ and  $\mathbb{G}=(\mathscr{G}_t)_{t\ge 0}$ is the usual augmentation of $\mathbb{H}$, i.e.
	\begin{equation}
	\mathscr{G}_t=\bigcap_{s>t} \tilde{\mathscr{H}_s} ,\, t\ge 0,
	\end{equation}
	where $\tilde{\mathscr{H}_s}$ is  the $(\mathscr{F},\mathbb{P})$-completion of the
$\sigma$-field $\mathscr{H}_s$, i.e. 
	\begin{equation}
 \tilde{\mathscr{H}_s}\coloneqq\sigma(\mathscr{H}_s \cup  \mathscr{N}),\, s\ge 0.
	\end{equation}
If a process 	$\mathrm{M}=\left(M_t: t\geq 0\right)$ is a c\`adl\`ag $\mathbb{H}$-martingale on $(\Omega, \mathscr{F}, \mathbb{P})$,		Then, it is also a $\mathbb{G}$-martingale.

