[Proposition 22 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Let $\widetilde X^h$ be a strong solution of \eqref{eq:  h-regularized SDE}. Then $\widetilde X^h\in \mathbb L^{1,2}$, and in particular for every $i=1,\dots,n$ and every $t\leq T$
\begin{align*}
    \mathbb{E}[|D_r^i \widetilde X^h_T|^2]+\int_0^T \int_0^T \mathbb{E}[|D_s^i \widetilde X^h_t|^2]\,ds\,dt\leq C,
\end{align*}
where $C$ does not depend on $N$, or $h$. The constant is allowed to depend on $A$.

[Theorem th:OR of arXiv:2508.21055, 'Modern aspects of Markov chains:\\entropy, curvature and the cutoff phenomenon'] For each $\kappa\in\mathbb {R}$, the following  are equivalent:
\begin{enumerate}[(i)]
\item A lazy transition brings adjacent states closer by an amount at least $\kappa/2$,  on average:
\begin{eqnarray}

\forall \{x,y\}\in E, \qquad W\left(\widehat{T}(x,\cdot),\widehat{T}(y,\cdot)\right) & \le & 1-\frac{\kappa}{2}.
\end{eqnarray}
\item Lipschitz norms decay at rate at least $\kappa$ along the semi-group: 
\begin{eqnarray}

\forall f\in\mathcal {F},\quad \forall t\ge 0,\quad \mathrm {Lip}(P_tf) & \le & e^{-\kappa t}\mathrm {Lip}(f).
\end{eqnarray}
\item Wasserstein distances decay at rate at least $\kappa$ along the semi-group:
\begin{eqnarray}

\forall \mu,\nu\in\mathcal{P}(\mathbb{X}),\quad\forall t\ge 0,\quad W(\mu P_t,\nu P_t)  & \le &  e^{-\kappa t}W(\mu,\nu).
\end{eqnarray}
\end{enumerate}
Moreover, when those equivalent properties hold with  $\kappa>0$, we have the mixing-time estimate 
\begin{eqnarray}

\forall \varepsilon\in(0,1),\qquad {\rm t}_{\textsc{mix}}(\varepsilon) & \le & \frac{1}{\kappa}\log\left( \frac{\mathrm{diam}(\mathbb{X})}{\varepsilon}\right).
\end{eqnarray}

