[Lemma 15 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, there exists a constant $c_1>0$ such that, uniformly for $z\in\mb D(\tau,\eta_0)$, the following estimates hold.
        \begin{enumerate}[label=(\roman*)]
                \item The off-diagonal blocks satisfy
                      \begin{align}
                              \avg{\Pi_{21}\Sg\Pi_{21}^*}_N=\avg{\Pi_{12}^*\Sg\Pi_{12}}_N\leq1-c_1. 
                      \end{align}
                \item The diagonal blocks satisfy
                      \begin{align}
                              \|\Sg^{1/2}\Pi_{11}\Sg^{1/2}\|_{\rr{hs}}+\|\Pi_{22}\|_{\rr{hs}}\sim1. 
                      \end{align}
                \item The two imaginary parts are comparable:
                      \begin{align}
                              \frac{\Im m}{\eta+\Im g}\sim1,\qquad \Im m\sim\Im g. 
                      \end{align}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 41 of arXiv:2608.18075, '2608.18075'] Let $b>2$, $I=[s_0,s_1]$, and
\begin{align*}
 w\in L^p(I;H^b),\qquad 2<p\le\infty,\qquad
 \kappa_p=1-\frac2p,
\end{align*}
where $\kappa_\infty=1$. Let $U_w(t,s)$ be the evolution family
of
\begin{align*}
 \partial_tz=\nu\Delta z+\cS(w_t,z).
\end{align*}
Then:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $U_w(t,s)$ is bounded on $H^q$, $-1\le q\le b$.
On $\{\|w\|_{L^pH^b}\le M\}$ the bound is uniform for
$s_0\le s\le t\le s_1$.
\item If $0<\delta<\kappa_p$, then
\begin{align*}
 U_w(t,s):H^q\longrightarrow H^{q+\delta},
 \qquad -1\le q\le b,
\end{align*}
with norm locally uniform when $t-s$ is bounded away from zero. For
$q=b$, this endpoint estimate into $H^{b+\delta}$ does not require
the coefficient to belong to that stronger space.
\item If $-1\le q<r\le b$, then, for every $\varepsilon>0$,
\begin{align*}
 \sup_{\substack{s_0\le s<t\le s_1\\t-s\ge\varepsilon}}
 \|U_w(t,s)\|_{H^q\to H^r}
 \le C(\nu,b,p,q,r,I,M,\varepsilon).
\end{align*}
In particular, over a time gap bounded below,
\begin{align*}
 U_w(t,s):H^{-1}\to H^\delta,\qquad
 U_w(t,s):H\to H^b
\end{align*}
for every $0<\delta<b$.
\item The exact energy smoothing estimates
\begin{align*}
 \|U_w(t,s)\|_{H\to H^1}
 +\|U_w(t,s)\|_{H^{-1}\to H}
 \le C_{I,M}(t-s)^{-1/2}
\end{align*}
hold for $s<t$. The second map is the transposition extension. The same
conclusions hold for the backward adjoint evolution.
\end{enumerate}

