[Lemma 15 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] \(\forall G\in \LtSpace*[\Cuben{1}][\C^M]\), \(\forall (\xi,\delta)\in \SSetOne\),
    \begin{equation}
    \begin{split}
            \Vol[\BV{\xi}{\delta}]^{1/2} \LtNorm*{G}[\Cuben{1}] 
            &\approx \Vol[\BV{\xi}{\delta}]^{1/2} \LtNorm*{G(y)}[\Cuben{1},h_{\xi,\delta,1}(y)dy]
            \\&= \LtNorm*{G\circ \Phi_{\xi,\delta}^{-1}}[\Phi_{\xi,\delta}\left( \Cuben{1} \right), d\Vol].
    \end{split}    
    \end{equation}
    Similarly, 
    \(\forall G\in \LtSpace*[\Cubengeq{1}][\C^M]\), \(\forall (\xi,\delta)\in \SSetTwo\),
    \begin{equation}
    \begin{split}
            \Vol[\BV{\xi}{\delta}]^{1/2} \LtNorm*{G}[\Cubengeq{1}] 
            &\approx \Vol[\BV{\xi}{\delta}]^{1/2} \LtNorm*{G(y)}[\Cubengeq{1},h_{\xi,\delta,2}(y)dy]
            \\&= \LtNorm*{G\circ \Psi_{\xi,\delta}^{-1}}[\Psi_{\xi,\delta}\left( \Cubengeq{1} \right), d\Vol].
    \end{split}    
    \end{equation}
    Here, the implicit constants do not depend on \(\xi\), \(\delta\), or \(G\).

