body:
[Lem 24 of arXiv:2608.11695, 'Generalised stochastic curvature flow in $d \geq 2$, and sharp interface limit for the sto'] Fix $\alpha \in (0,\frac{1}{2})$. Let $\widetilde\oO \subset \RR^d$ be an open bounded domain with smooth boundary. Fix $R_0>0$ and $(\bar{u}, \bar{p}, \bar{q}) \in \RR \times \RR^d \times \RR^{d \times d}$. Consider the domains
\begin{equation*}
    Q_T = [0,T] \times \overline{\widetilde{\oO}}\times B\bigl((\bar u,\bar p,\bar q),R_0\bigr)\;, \qquad S=\overline{\widetilde{\oO}}\times B\bigl((\bar u,\bar p),R_0\bigr)\;. 
\end{equation*}
Suppose $\{\widetilde{F}_\eps\}$, $\{\widetilde{G}_\eps\}$ and $\{g_\eps\}$ are families of real-valued functions on $Q_T, S$ and $\overline{\widetilde{\oO}}$ and satisfy the followings:
\begin{enumerate}
\item $\widetilde{F}_\eps$ is differentiable in $q$ and satisfies the uniform ellipticity condition: there exists $\lambda>0$ such that
\begin{equation} 
\sum_{i,j=1}^d \d_{q_{ij}} \widetilde{F}_\eps(t,x,u,p,q) \, \eta_i \, \eta_j \geq \lambda |\eta|^2
\end{equation}
uniformly over $(t,x,u,p,q) \in Q_T$, $\eta \in \RR^d$ and $\eps \in [0,1]$. 

\item Each $\widetilde{F}_\eps$ is twice differentiable in $(u,p,q)$, and that the derivatives up to order two belongs to $\cC_\pa^{2\alpha}$ in $(t,x)$. More precisely, we have
\begin{equation} 
|\!|\!| \widetilde{F}_\eps |\!|\!|_{\mathcal F,\mathrm{PDE}}:=
\sup_{\substack{(u,p,q) \in B((\bar u,\bar p,\bar q),R_0)\\ |\beta|\leq 2}}
    \bigl\| D_{(u,p,q)}^\beta \widetilde F_\eps(\cdot\,,\cdot\,,u,p,q) \bigr\|_{\cC_{\pa}^{2\alpha}([0,T]\times\overline{\widetilde{\oO}})}
<+\infty\;.
\end{equation}

\item $\widetilde G_\eps$ is three times differentiable in $(u,p)$ and each derivative $D_{(u,p)}^\beta \widetilde G_\eps$ with $|\beta|\leq3$ belongs to $\cC^{1+2\alpha}(\overline{\widetilde{\oO}})$ in $x$, uniformly with respect to $(u,p)$. More precisely, we have
\begin{equation}
|\!|\!| \widetilde G_\eps |\!|\!|_{\mathcal G}:=
\sup_{\substack{(u,p) \in B((\bar u,\bar p),R_0) \\ |\beta|\leq 3}}
    \bigl\| D_{(u,p)}^\beta \widetilde G_\eps(\cdot\,,u,p) \bigr\|_{\cC^{1+2\alpha}(\overline{\widetilde{\oO}})} <+\infty\;.
\end{equation}

\item $g_\eps \in \cC^{2+2\alpha} (\overline{\widetilde{\oO}})$ satisfies the compatibility condition
\begin{equation*}
\widetilde G_\eps\bigl(x,g_\eps(x),\nabla g_\eps(x)\bigr)=0\;,\quad x\in\partial\widetilde\oO\;,
\end{equation*}
and the uniform non–tangentiality condition: there exists $c>0$ such that
\begin{equation} 
\inf_{x \in \d \widetilde{\oO},\eps\in[0,1]} \Big| \sum_{i=1}^d \d_{p_i} \widetilde{G}_\eps \big( x,g_\eps(x),\nabla g_\eps(x) \big) \nu_i(x) \Big| \geq c\;,
\end{equation}
where $\nu(x)$ denotes the unit outward normal at $x \in \partial \widetilde\oO$.
Moreover, the range of $(g_\eps,\nabla g_\eps,\nabla^2 g_\eps)$ is contained in the ball of radius $R_0/2$ centered at $(\bar u,\bar p,\bar q)$ . 
\end{enumerate}
Consider the second order fully nonlinear parabolic initial-boundary value problem
\begin{equation}
\left\{
\begin{aligned}
