\begin{equation}\begin{aligned}
\dot \Phi_x(t,x)&= A_x(\Phi(t,x) )\Phi_x(t,x),\\
\Phi_x(0,x)&=\mathrm{Id}.
\end{aligned}\end{equation}
For each $\varphi\in\mathbb{R}^d$ we have
\begin{equation}\begin{aligned}
\frac{\mathrm{d} }{\mathrm{d} t}\|\Phi_{x}(t,x) \varphi\|^2
