[Theorem prop:delocXY/IVGFFheight of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] There exist an inverse temperature $\beta_{\mathrm{Deloc}} \in (0 , \infty)$ and a constant $c_0 > 0$ such that 
\begin{itemize}
    \item For any $\beta \geq \beta_{\mathrm{Deloc}}$ and any $L \in \ensuremath{\mathbb{N}}^*$
    \begin{equation*}
         \mathrm{Var}_{L , \beta}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} \left[ \varphi(0) \right] \geq c_0 \ln L.
    \end{equation*}
    \item For any $\beta_1 , \beta_2 \geq \beta_{\mathrm{Deloc}}$ and any $L \in \ensuremath{\mathbb{N}}^*$
    \begin{equation*}
         \mathrm{Var}_{L , \beta_1 , \beta_2}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}/\mathrm{GFF}} \left[ \varphi(0) \right] \geq c_0 \ln L.
    \end{equation*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 26 of arXiv:2606.08115, '2606.08115'] Let $\left\{\ov{Z}_n\right\}$ be a group of $N$ branching processes in a joint random environment. Then,
\begin{itemize}
\item the following expressions
\begin{equation}

\prf\left(Z_n^{(i)} > 0 \right) = \left(\exp\left(-S_n^{(i)}\right) + \sum_{k = 0}^{n-1}\exp\left(-S_k^{(i)}\right) g_{k}^{(i)}\left( f_{k+2, n}^{(i)}(0)\right)\right)^{-1}, \quad i = 1, \ldots, N,
\end{equation}
are valid, where
\begin{align*}
&f_{k, n}^{(i)} (t): = f_k^{(i)} \circ f_{k+1}^{(i)} \circ \ldots \circ f_n^{(i)}(t), \quad k = 1, 2, \ldots, n, \quad f_{n+1, n}^{(i)}(t) := t, \quad i = 1, \ldots N,
\\&g_k^{(i)}(t) := \frac{1}{1 - f_{k+1}^{(i)}(t)} - \frac{1}{\left(f_{k+1}^{(i)}\right)'(1) \cdot (1 - t)}, \quad t \in [0, 1), \; i = 1, \ldots, N;
\end{align*}
\item the inequalities
\begin{equation}

\prf \left(Z_n^{(i)} > 0\right) \ge \left(\mathrm{exp} \left(-S_n^{(i)}\right) + \sum_{k = 0}^{n-1} \xi_k^{(i)} \mathrm{exp} \left(-S_k^{(i)}\right)\right)^{-1}, \quad i = 1, \ldots, N
\end{equation}
hold.
\end{itemize}

[Lemma lem:lmax-subharmonic-detailed of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] There is a constant $C$ such that $\Delta_\omega^{\mathbb C}\ell_{\max}\geq-C$ in
the viscosity sense.  Consequently,
\begin{equation}
 \frac1{\operatorname{Vol}(M)}\int_M(\sup_M\ell_{\max}-\ell_{\max})\,\omega\leq C.
\end{equation}

[Lemma lem-lowboundinteract of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Suppose that $v$ satisfies  Assumption (V). Then, for any ergodic  $P\in{\mathcal M }_1^{{{\scriptscriptstyle{({\rm s}})}}}({\mathcal L }\times{\mathcal S })$,
\begin{equation}
\langle P,F_U\rangle \geq\frac{C\beta}2\big\langle P, \big(\widetilde{\mathfrak N}_{U}^{\ssup\ell}\big)^2\big\rangle -\frac {5C \beta}4,
\end{equation}
where $C$ is introduced in (equation LowBoundAss of the paper). Moreover, the maps ${\mathcal M }_1^{{{\scriptscriptstyle{({\rm s}})}}}({\mathcal L }\times{\mathcal S })\ni P\mapsto  \langle P, \widetilde{\mathfrak N}_{U}^{\ssup{\ell,{\mathcal L }}}\rangle$ and  ${\mathcal M }_1^{{{\scriptscriptstyle{({\rm s}})}}}({\mathcal L }\times{\mathcal S })\ni P\mapsto  \langle P, \widetilde{\mathfrak N}_{U}^{\ssup{\ell,{\mathcal S }}}\rangle$ are continuous on the set $\{P\colon \langle P, (\widetilde{\mathfrak N}_{U}^{\ssup\ell})^2\rangle\leq L\}$ for any $L\in(0,\infty)$.

