[Theorem 4 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] Suppose that $u$ solves \eqref{main_eq} with the same assumptions as \Cref{main_result_theorem}. Then
        \begin{enumerate}[(i)]
            \item
            If $0 \leq \chi < 1$, then
            \begin{equation}
                w(t, x + m(t)) \leq \frac{C}{t} \1_{\{x \leq 0\}} + \frac{C(1+x)^2e^{-x}}{t} \1_{\{x \geq 0\}}. 
            \end{equation}
            \item
            	 If $\chi = 1$, then
            \begin{equation}
                w(t, x+m(t)) \leq \frac{C}{t} \1_{\{x \leq 0\}} + \frac{C(1+x)e^{-x}}{t} \1_{\{x \geq 0\}}. 
            \end{equation}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm mainresult of arXiv:2411.11552, 'Convergence rate of Smoluchowski--Kramers approximation with stable Lévy noise'] (i) Let $0\leq\theta<1.$ Under assumption $\mathbf{(A)}$,
		\begin{equation}
			\mathbb{E}\sup\limits_{0\leq t\leq T}|U^\epsilon(t)-\bar{U}^\epsilon(t)|\lesssim \epsilon^\theta.
		\end{equation} 	
		(ii) Let $\theta=0.$ Under assumption $\mathbf{(A)}$,
		\begin{equation}
			\lim\limits_{\epsilon\rightarrow 0}d^o(U^\epsilon,\bar{U})=0\quad\text{in probability}.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop no_individual_bubble_long of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] There exist $\beta>0$ and a constant $C(R,\alpha)>0$ such that
\begin{equation}
    \begin{split}
        \mathbf{P}\!\left(\exists i\colon X_{x_{i},x_{i+1}}> \mathbf{q}_n\right)\leq C(R,\alpha)\cdot R^{-(\alpha+\beta)k},
    \end{split}
\end{equation}
for all $n> R^k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

