[Prop trunbiliearestis of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Let $s\geq 0$, $3/8<b<1/2$, $\varepsilon<2b-3/4$, $R>0$, $0<T<1$. Then, we have
		\begin{equation*}
			\left\|\int_0^tU(t-t')(B_R(u))_x~dt'\right\|_{Z_T^{s,b}}\lesssim RT^\varepsilon\|u\|_{Z_T^{s,b}}
		\end{equation*}
		and
		\begin{equation*}
		\left\|\int_0^tU(t-t')(B_R(u)-B_R(v))_x~dt'\right\|_{Z_T^{0,b}}\lesssim RT^{\varepsilon}\|u-v\|_{Z_T^{0,b}}.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 7 (Answer to OP1) of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $u$ be a reference density such that that $\mathbf{H_{a,b}^{\sqrt{u}}}$ and $\mathbf{H_{\sf \lesssim u}}$ hold. 
Then the following assertions hold:
    \begin{enumerate}
        \item[(i)] There exists a maximal extension $\left(\overline{\sf L}_1,{\sf{D}(\overline{\sf{L}}_1)}\right)$ of $\left(\overline{\sf L},C_c^{\infty}((0,\infty)\times \mathbb{R}^d))\right)$ on $L^1\left([0,\infty)\times \mathbb{R}^d;\overline{\mu}\right)$. 
        It generates a $C_0$-resolvent $\overline{\mathcal{U}}=\left(\overline{U}_\alpha\right)_{\alpha> 0}$ on $L^1\left([0,\infty)\times \mathbb{R}^d;\overline{\mu}\right)$, which, keeping the same notation, induces a $C_0$-resolvent of Markov contractions $\overline{\mathcal{U}}$ on every $L^p\left([0,\infty)\times \mathbb{R}^d;\overline{\mu}\right)$, and whose corresponding generator is further denoted by $\left(\overline{\sf L}_p,{\sf{D}(\overline{\sf{L}}_p)}\right)$, $p\in[1,\infty)$.
        Moreover, for every $N>0$ we have 
        \begin{equation*}
        \overline{U}_\alpha \left(f1_{[0,N)\times \mathbb{R}^d}\right)|_{[0,N)\times \mathbb{R}^d}=\overline{U}_\alpha^N \left(f|_{[0,N)\times \mathbb{R}^d}\right), \quad f \in L^p([0,\infty)\times \mathbb{R}^d;\overline{\mu}),
        \end{equation*}
        where $\overline{U}_\alpha^N$ is given in \Cref{thm:Stannat}.
        \item[(ii)] There exists a set $E\in \mathcal{B}([0,\infty)\times \mathbb{R}^d)$ and a conservative right (hence strong Markov) process  on $E$
        \begin{equation*}
        X=\left(\Omega,\mathcal{F},\mathcal{F}_t,X(t),\mathbb{P}_{s,x}, (s,x)\in E, t\geq 0\right) \mbox{ such that:}
        \end{equation*} 
        \begin{enumerate}
            \item[(ii.1)] $\overline{\mu}([0,\infty)\times \mathbb{R}^d\setminus E)=0$ and $\mu_s\left(\left\{x\in \mathbb{R}^d, (s,x)\in E\right\}\right)=1$, $s>0$.
            \item[(ii.2)] The transition function of $X$ denoted by $\left(P_t\right)_{t\geq 0}$, and the corresponding resolvent $\mathcal{U}:=\left(U_\alpha\right)_{\alpha>0}$, are such that 
            \begin{enumerate}
                \item[\scalebox{0.7}{$\bullet$}] $P_t\left(f|_E\right)$ is finely continuous for every $f\in C_b([0,\infty)\times \mathbb{R}^d)$
                \item[\scalebox{0.7}{$\bullet$}] $U_\alpha \left(f|_E\right)$ is a finely continuous $\overline{\mu}$-version of $\left(\alpha-\overline{\sf{L}}_p\right)^{-1}f$, $\alpha>0$, $f\in p\mathcal{B}([0,\infty)\times \mathbb{R}^d)\cap L^p([0,\infty)\times\mathbb{R}^d;\overline{\mu})$. 
            \end{enumerate}
            \item[(ii.3)] For $(s,x)\in E$ we have
            \begin{equation*}
                \mathbb{P}_{s,x}\left( [0,\infty)\ni t\mapsto X(t) \in E\subset [0,\infty)\times \mathbb{R}^d \mbox{ is continuous }  \right)=1.
            \end{equation*}
            \item[(ii.4)] If we set $X(t)=(X_1(t),X_2(t)), t\geq 0$, then for $(s,x)\in E$ we have
            \begin{equation*}
            \mathbb{P}_{s,x}\left( X_1(t)= t+s; 0\leq t<\infty  \right)=1.
            \end{equation*}
            Moreover, we have 
            \begin{equation*}
            \mathbb{P}_{s,\mu_s}\circ \left(X_2(t)\right)^{-1}=\mu_{t+s} \quad \mbox{ for every } s> 0 \mbox{ and } t\geq 0.
            \end{equation*}
            \item[(ii.5)]
            For every $(s,x)\in E$ and every $f\in C_c^{2}([0,\infty)\times \mathbb{R}^d)$ we have that
            \begin{equation*}
                \mathbb{E}_{(s,x)}\left\{\int_0^{t} \left|\overline{\sf L}f(X(r))\right|\; dr
               \right\}<\infty, \quad t\geq 0,
            \end{equation*}
            and
            \begin{equation*}
                f(X(t))-f(X(0))-\int_0^{t} \overline{\sf L}f(X(r))\; dr, \quad t\geq 0
            \end{equation*}
            is a continuous $\left(\mathcal{F}(t)\right)$-martingale under $\mathbb{P}_{(s,x)}$.
            \item[(ii.6)]
            For every $s\in (0,\infty)$, and every $\nu_s\in \mathcal{P}(\mathbb{R}^d)$ which satisfies $\nu_s\leq c \mu_s$ for some constant $c>0$, we hav

[Theorem 8 (Optional--singular interchange) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Let \(\widetilde A^{(m)},\widetilde A\) be normalized adapted càdlàg
\(\widetilde G\)-valued anchors, write
\(A^{(m)}:=p(\widetilde A^{(m)})\) and
\(A:=p(\widetilde A)\) for their base anchors, and assume
\begin{equation}
 \sup_{t\le T}\|\widetilde A^{(m)}_t-\widetilde A_t\|
 \longrightarrow0
 \qquad\text{in probability}.

\end{equation}
Define their perfected lifted characters by
\begin{equation}
 \widetilde\Phi^{(m)}_{s,t}
 :=\bigl(\widetilde\alpha_{t,s}(\widetilde A^{(m)}_s)\bigr)^{-1}
   \star\widetilde A^{(m)}_t,
 \qquad
 \widetilde\Phi_{s,t}
 :=\bigl(\widetilde\alpha_{t,s}(\widetilde A_s)\bigr)^{-1}
   \star\widetilde A_t.

\end{equation}
Then
\begin{equation}
 \sup_{0\le s\le t\le T}
 \|\widetilde\Phi^{(m)}_{s,t}-\widetilde\Phi_{s,t}\|
 \longrightarrow0
 \qquad\text{in probability}.

\end{equation}
In particular, for every possibly \(m\)-dependent stopping pair
\(\sigma_m\le\tau_m\le T\),
\begin{equation}
 \widetilde\Phi^{(m)}_{\sigma_m,\tau_m}
 \longrightarrow\widetilde\Phi_{\sigma_m,\tau_m}
 \qquad\text{in probability}.

\end{equation}
For a fixed stopping pair, the two routes agree in the following
commuting-limit sense:
\begin{equation}
 \bigl(\widetilde\alpha_{\tau,\sigma}
       (\widetilde A_\sigma)\bigr)^{-1}
       \star\widetilde A_\tau
 =
 \lim_{m\to\infty}
 \bigl(\widetilde\alpha_{\tau,\sigma}
       (\widetilde A^{(m)}_\sigma)\bigr)^{-1}
       \star\widetilde A^{(m)}_\tau
 \quad\text{in probability}.

\end{equation}
It is compatible with the projection \(p:\widetilde G\to G\).

More generally, suppose raw counterterm-corrected intervals
\(\widehat\Phi^{(m)}_{s,t}\) have measurable stopped evaluations and
measurable displayed suprema (as holds, for example, for jointly measurable
fields with separable sample paths), have anchors
\(\widetilde A^{(m)}_t=\widehat\Phi^{(m)}_{0,t}\), satisfy
\eqref{cc:eq-lifted-anchor-ucp}, and have uniform anchored defect
\begin{equation}
 \sup_{s\le t\le T}
 \left\|
 \widetilde A^{(m)}_t-
 \widetilde\alpha_{t,s}(\widetilde A^{(m)}_s)
   \star\widehat\Phi^{(m)}_{s,t}
 \right\|
 \longrightarrow0
 \quad\text{in probability}.

\end{equation}
Then \(\widehat\Phi^{(m)}\) has the same uniform triangle limit
\(\widetilde\Phi\), in the explicit sense that
\[
 \sup_{s\le t\le T}
 \|\widehat\Phi^{(m)}_{s,t}-\widetilde\Phi_{s,t}\|
 \longrightarrow0
 \qquad\text{in probability},
\]
and hence the same stopped limits.  Thus
\eqref{cc:eq-lifted-anchor-ucp} together with
\eqref{cc:eq-uniform-anchored-defect} is the robust upgrade of a
fixed-interval renormalization certificate.

[Corollary CorSingleBlock of arXiv:2608.28949, 'The information geometry of product-reference discrete diffusion: Interaction growth compl'] For any choice of $r_0 \in (0, 1/2)$ and iteration number $N
    \geq 2 \ell_d$, applying the \textsf{PRD}\xspace sampler with the stepsize
    protocol~(equation EqnSingleBlockGrid of the paper) over the interval $[r_0, 1
      - r_0]$ returns output $\ensuremath{\widehat{Z}}$ such that
\begin{align}

  \ensuremath{D_{\scaleto{\operatorname{KL}}{4pt}}}(\ensuremath{\mathbb{P}}_Z \| \ensuremath{\mathbb{P}}_{\ensuremath{\widehat{Z}}}) & \leq \frac{8 \ell_d}{N}
  \mathsf{G}(r_0, 1 - r_0) +  \ensuremath{\mathsf{TC}}(\ensuremath{X}_{r_0}) + \ensuremath{\mathsf{TC}}(Z \mid
  X_{1 - r_0}) \qquad \mbox{where
    $\ell_d = \log\left( \frac{1 - r_0}{r_0} \right)$.}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm 5 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] Let $\mu \in \mathcal{P}_2(\mathbb{R})$ and $F_{\mu}^{-1}$ be its representative in $\mathcal{U}^2(\mathbb{S})$ as defined in \eqref{inverse}. Then, the following holds for    any fixed {$h\in T/{\mathbb N}^*$}:
	\begin{itemize}
	\item[i.] The difference ${F}^{-1}_{\mu*\Gamma_h}-{F}^{-1}_{\mu}$ is monotone: \text{ if} $\phi \in \mathcal{U}^2(\mathbb{S})$, then $\langle \phi,{F}^{-1}_{\mu*\Gamma_h}-{F}^{-1}_{\mu}\rangle \geq 0$;
	\item[ii.] In addition, if $\phi$ is also in $\mathcal{C}^1(\mathbb{S})$, then the following identity holds:
	\begin{align*}
		\left\langle \phi,F^{-1}_{\mu\star\Gamma_h}-F^{-1}_{\mu}\right\rangle :=\frac{1}{4}\int_{\mathbb{R}}\int_{0}^h \phi'\bigg(\frac{(\tilde{F}_{\mu}\star\Gamma_t)(z)}{2}\bigg)\big[D_z (\tilde{F}_{\mu}\star\Gamma_t)(z)\big]^2\mathrm{d}t\mathrm{d}z.
	\end{align*}
	\end{itemize}

[Corollary cor: Lp decoupling inequality of arXiv:2602.04429, 'Disordered systems and (subcritical) polynomial chaos\\ with heavy-tail disorder'] {}
	Assume that $\omega^{(j)} = (\omega_n^{(j)})_{n \in {\ensuremath{\mathbb N}}  }$ are sequences of independent and centered random variables.
	There exist a constant $C_2$ such that for every $ p \in (1,2]$, for every $k \, \geqslant\, 1$, $N \, \geqslant\, 1$ and any tetrahedral function $f \in {\ensuremath{\mathcal T}} _N^k$, 
	\begin{equation*}
		\big\|X_N(f; \omega^{(1)},\dots,\omega^{(k)})\big\|_p \, \leqslant\, \Big( \frac{C_2}{p-1} \Big)^k  \bigg(\sum\limits_{1 \, \leqslant\, n_1 <\dots<n_k \, \leqslant\, N} |f(n_1,\dots,n_k)|^p \prod\limits_{j=1}^k \|\omega_{n_j}^{(j)}\|_p^p\bigg)^{1/p}. 
	\end{equation*}

