[Lemma lemma_image_og_phi_sigma_right_set of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] Consider $\rho \in \{-,0,+\}$ and $w \in \mathscr{C}_{n}^{\rho}(\mu,2^{-R}\varepsilon)$.
\begin{enumerate}
\item If $\alpha_0 > 0$, then there exists a constant $C_1>0$, which only depends on $\alpha_0$, such that
\begin{equation*}
\phi^0(w) \in \Omega^{(0)}_{\overline{\alpha}_{0,n}}(\mu_0,C_1 \varepsilon).
\end{equation*}

\item If $\sigma \in \{-,+\}$ and $\sigma =\rho$, 
\begin{equation*}
\phi^{\sigma}(w) \in 
\Omega_{\overline{\alpha}_{\sigma,n},\textup{mea}}^{\sigma}.
\end{equation*}

\item If $\sigma \in \{-,+\}$ and $\sigma \neq \rho$, 
\begin{equation*}
\phi^{\sigma}(w) \in \Omega_{\overline{\alpha}_{\sigma,n},\textup{exc}}^{\sigma}.
\end{equation*}

\end{enumerate}

