[Lemma 14 of arXiv:2608.29152, 'Uniform Statistical Convergence of Empirical Sinkhorn Potentials\\ with Exponential and Po'] For a continuous cost $c$, define its rectangular interaction oscillation by
\begin{equation}
 \Delta_\square(c) := \sup_{x,x'\in\cX, y,y'\in\cY} |c(x,y)+c(x',y')-c(x,y')-c(x',y)|.
\end{equation} 
Fix $x_0\in\cX$, $y_0\in\cY$, and set $a(x)=c(x,y_0)$, $b(y)=c(x_0,y)-c(x_0,y_0)$, and $\bar c(x,y)=c(x,y)-a(x)-b(y)$.
Then $\|\bar c\|_\infty\le\Delta_\square(c)$ and $\osc(\bar c)\le2\Delta_\square(c)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2608.17562, '2608.17562'] Let $(X_{i})_{i \ge 1}$ be a sequence of \iid random variables with common distribution function $F$. Assume that
  $\widebar{F} \in \SRV{\alpha}{\rho}$, with $\alpha > 0$, $\rho < 0$,
  and auxiliary function~$A$.
  Set
  $$Z_n \coloneq a_n^{-1}
  \max(X_{1},\dots,X_{n}),
  $$
  where   
  $a_n \coloneq F^{\leftarrow}(1 - 1/n)$,
  $n\geq 1$. Let $\mathcal{H}$ be a set of functions $h : \R \to \R$ such that the associated Stein solution $g_{h}$ exists, belongs to $\mathcal{C}^{1}((0,\infty))$, where $x \mapsto xg_{h}'(x)$ is absolutely continuous and satisfies 
\begin{align}
x\vert g_{h}'(x) \vert \leq C_{1}x^{\beta} 
\end{align}
 and 
\begin{align}
\vert (xg_{h}'(x))'\vert \leq C_{2}x^{\gamma} 
\end{align}
for almost every $x >0 $, some $\beta \in (-\infty, \alpha),\ \gamma \in (-\infty, \alpha - 1)$,
 $C_{1}, C_{2} > 0$ independent of $h$. Then,
 there exists $C_{\alpha} > 0$ such that 
\begin{align}
  \underset{h \in \mathcal{H}}{\sup}\ \big\vert \esp[h(Z_{n})] - \esp[h(Z)]\big\vert \leq C_{\alpha}\Big(\frac{1}{n} + A(a_n)\Big) + \underset{h \in \mathcal{H}}{\sup}\ \big\vert\esp\big[h(Z_{n})\ind_{U^{c}_{n}}\big] - \esp[h(Z)]\prob(U_{n}^{c})\big\vert,
   \quad n \geq 1.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 25 of arXiv:2608.18075, '2608.18075'] For every $T>0$ and every $\theta>0$, there are $\delta>0$ and $r>0$ such
that the following holds.  Let
\begin{align*}
 \mathcal U_r=\{(w,\iota(\eta)):\norm{(w,\eta)}_{E_b}<r\}
\end{align*}
be the $r$ neighborhood of the prepared state. If $\mathcal A\subset\Omega_T$ is Borel and
\begin{align*}
 \mathcal A\subset\{\norm{Y_T(W)}_{\mathsf Y_T}\le\delta\},\qquad
 \mathbf P(\mathcal A)>0,
\end{align*}
then, for every $z,z'\in\mathcal U_r$, write
$h=\Delta_{(0,[\phi])}(z')-\Delta_{(0,[\phi])}(z)$, equivalently
$h=z'-z$ in the prepared coordinates, and put $g=K_Th$.  There is a coupling law
$\mathbf Q^{\rm br}_{z,z'}$ of two standard Wiener paths
$(W,\widetilde W)$, Borel in $(z,z')$, such that
\begin{align}
 \mathbf Q^{\rm br}_{z,z'}\left\{W\in\mathcal A,\
  \widetilde W=W-\int_0^\cdot g_s\,\dd s\right\}
 \ge\mathbf P(\mathcal A)-\frac12\norm g_{\cH_T}.
\end{align}
The corresponding endpoints have the exact transition laws
$P_T(z,\cdot)$ and $P_T(z',\cdot)$.  On the event in
\eqref{eq:eventwise-bridge},
\begin{align}
 \norm{F_T(z',Y_T(\widetilde W))-F_T(z,Y_T(W))}_{E_b}
 \le\theta\norm h_{E_b}.
\end{align}

