[Lemma 42 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] Let \( (u_t)_{0 \leqslant t \leqslant T} \) be a continuous stochastic process satisfying assumption $\mathbf{(A3)}$. Fix \( \beta > 0 \), \( 0 < a < b \leqslant T \) and \( M > 0 \). Then the following statements hold true.
\begin{itemize}
\item There exists a constant \( C_1 > 0 \) such that
\begin{equation}
\mathbb{P}\big(u([a, b]) \cap A \neq \emptyset\big) \leqslant C_1\, \mathcal{H}_{\beta - 1/H}(A)
\end{equation}for all Borel sets \( A \subseteq B_d(o, M) \).

\item For every \( \eta > 0 \), there exists a constant \( C_2 > 0 \) depending additionally on 
\( \eta \), such that
\begin{equation}
\mathbb{P}\big(u([a, b]) \cap A \neq \emptyset\big) \leqslant C_2\, \textnormal{Cap}_{\beta - 1/H - \eta}(A)
\end{equation}for all compact sets \( A \subseteq B_d(o, M) \).
\end{itemize}

[Defn eq:slope_ineq1 of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] We define a partial relation $\prec$ on (finite) fine slopes generated by the following inequalities:
    \begin{equation}
        s^\heartsuit \prec t^\diamondsuit
    \end{equation}
    whenever $s < t$ and $\heartsuit, \diamondsuit \in \{\natural, \flat, \sharp, \dagger\}$, and
    \begin{equation}
        s^\flat \prec s^\dagger \prec s^\sharp, \qquad \text{and} \qquad s^\dagger \prec s^\dagger.
    \end{equation}

[Theorem 6 of arXiv:2606.02786, 'Non-local SDEs, critical drifts and local blow-ups'] Let the interaction kernel $K:\mathbb R^d \rightarrow \mathbb R^d$ be Borel measurable.
The following are true:

\begin{enumerate}

\item[{\rm (\textit{i})}] {\rm (Finite particle system)} Assume additionally that $K$ is weakly form-bounded with respect to the fractional Laplacian on $\mathbb R^d$, i.e. $|K| \in L^1_{\loc}(\mathbb R^d)$ and
$$
\||K|^{\frac{1}{2}}(\lambda+(-\Delta)^{\frac{\alpha}{2}})^{-\frac{1}{2}\frac{\alpha-1}{\alpha}}\|_{L^2(\mathbb R^d) \rightarrow L^2(\mathbb R^d)} \leq \sqrt{\delta}
$$
for some $\lambda>0$. For instance, $K$ satisfies the elliptic Morrey class condition $$|K|^{\frac{1}{\alpha-1}} \in M_{1+\epsilon}$$
with sufficiently small elliptic Morrey  norm (see \eqref{morrey_e}). Then there exists a constant $C_{d,N,\alpha}$ such that if $\delta<C_{d,N,\alpha}$, then there exist (unique, see below) probability measures $\{\mathbb P_{x}\}_{x \in \mathbb R^{dN}}$ on the canonical space of c\`{a}dl\`{a}g paths $\mathbf{D}=\mathbf{D}_{[0,\infty[}$ that deliver a weak solution to the particle system
\begin{equation}

X_t^i=x^i-\frac{1}{N}\sum_{j=1, j \neq i}^N \int_0^t K(X_s^i-X_s^j)ds+Z_t^i,
\end{equation}
where $Z_t^i$ are independent $\alpha$-stable processes, and determine a strongly continuous Feller semigroup via
$$
e^{-t\Lambda}f(x):=\mathbb E_{\mathbb P_x} f(X_t^1,\dots,X_t^N), \quad f \in C_\infty(\mathbb R^{dN}),
$$
where $\Lambda$ is an appropriate operator realization of $\sum_{i=1}^N (-\Delta)^{\frac{\alpha}{2}}_{x^i}+\frac{1}{N}\sum_{i=1}^N \sum_{j=1, j \neq i}^N K(x^i-x^j) \cdot \nabla_{x^i}$ on $C_\infty$.

\smallskip

\item[{\rm (\textit{ii})}] {\rm (A priori Sobolev regularity for McKean-Vlasov equation)} Assume that $K$ satisfies the elliptic Morrey class condition $$|K|^{\frac{1}{\alpha-1}} \in M_{1+\epsilon}$$
with sufficiently small Morrey norm. Then, whenever $1<p<\frac{d+1}{d}$, for every $x \in \mathbb R^d$, the solution to the Cauchy problem for the McKean-Vlasov equation
\begin{align*}
\left\{
\begin{array}{l}
\lambda w +\partial_t w +(-\Delta)^{\frac{\alpha}{2}} w - {\rm div\,}\big((K \star w)w\big)=0, \\
w|_{t=0}=\delta_x,
\end{array}
\right.
\end{align*}
satisfies $w \in \mathbb{W}_\alpha^{\frac{\alpha-1}{\alpha}\frac{2}{p},p} \cap L^\infty(\mathbb R_+,L^1(\mathbb R^d))$ and
\begin{align}

&(\lambda+\partial_t +(- \Delta)^{\frac{\alpha}{2}})^{\frac{\alpha-1}{\alpha}\frac{1}{p}} w\notag\\
&\quad = (\lambda+\partial_t +(- \Delta)^{\frac{\alpha}{2}})^{-1+\frac{\alpha-1}{\alpha}\frac{1}{p}}\delta_{t=0}\delta_x - \nabla (\lambda+\partial_t +(- \Delta)^{\frac{\alpha}{2}})^{-1+\frac{\alpha-1}{\alpha}\frac{1}{p}}[(K \star w)w].
\end{align}
 Here we assume additionally that $K$ is smooth to ensure the existence and uniqueness of $w$, but the Sobolev norm $\|w\|_{\mathbb{W}_\alpha^{\frac{\alpha-1}{\alpha}\frac{2}{p},p} }$ is independent of the smoothness of $K$.
 \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop I<=00003D-Phi of arXiv:2603.27144, 'On the critical fugacity of the hard-core model on regular bipartite graphs'] There exist $C,c>0$ such that the following
holds. Let $G$ be a finite $\delta$-regular bipartite graph, satisfying
the local expansion property with parameters \emph{$C_{\mathrm{LE}},M_{\mathrm{LE}}$}.
Let $\boldsymbol{\sigma}$ be sampled from \emph{any measure} on $\Omega_{\mathrm{hc}}^{G}$.
Let $\lambda>0$. Then
\begin{equation}
\frac{1}{|V|}I(\boldsymbol{\sigma})-\frac{1}{2}\tilde{\lambda}\le-\frac{1}{4}\tilde{\lambda}\mathbb{E}\boldsymbol{\Phi}+\frac{CC_{\mathrm{LE}}}{\delta}\left(\mathbb{E}\boldsymbol{\Phi}\log\frac{e}{\mathbb{E}\boldsymbol{\Phi}}+\frac{1}{M_{\mathrm{LE}}}\right).
\end{equation}
Consequently,
\begin{equation}
I(\boldsymbol{\sigma})-\tilde{\lambda}\frac{|V|}{2}\le-c\tilde{\lambda}|V|\mathbb{E}\boldsymbol{\Phi}
\end{equation}
 whenever 
\begin{equation}
\tilde{\lambda}>\frac{9CC_{\mathrm{LE}}}{\delta}\max\left\{ \log\frac{e}{\mathbb{E}\boldsymbol{\Phi}},\frac{1}{M_{\mathrm{LE}}\mathbb{E}\boldsymbol{\Phi}}\right\} .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma tail_prob of arXiv:2608.12056, 'Deviation inequalities for U-processes of growing order, with applications to half-space d'] Let $\{X_t, \ t\in T\}$ be the homogeneous Rademacher chaos of order $j$. Then for any $u > 0$,
\begin{align*}
    \mathbb P\left(|X_t| \geq ue\|X_t\|_2\right) \leq e^{-u^{2/j}}\,.
\end{align*}

