[Thm 8 (Answer to OP2) of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $u$ be a reference density such that $\mathbf{H_{a,b}^{\sqrt{u}}}$, $\mathbf{H_{\sf \lesssim u}}$ hold.
If, in addition, $\mathbf{H^{\sf TV}_0}$ holds, then in assertions (ii.1), (ii.4), and (ii.6) from \Cref{thm:main0} we can include the case $s=0$ as well; more precisely, the three assertions can be respectively replaced with the following stronger ones:
        \begin{enumerate}
            \item[(ii.1')] $\overline{\mu}([0,\infty)\times \mathbb{R}^d)\setminus E=0$ and $\mu_s\left(\left\{x\in \mathbb{R}^d, (s,x)\in E\right\}\right)=1$, $s\geq 0$.
            \item[(ii.4')] If we set $X(t)=(X_1(t),X_2(t)), t\geq 0$, then for $(s,x)\in E$ we have
            \begin{equation*}
            \mathbb{P}_{s,x}\left( X_1(t)= t+s; 0\leq t<\infty  \right)=1.
            \end{equation*}
            Moreover, we have 
            \begin{equation*}
            \mathbb{P}_{s,\mu_s}\circ \left(X_2(t)\right)^{-1}=\mu_{t+s} \quad \mbox{ for every } s\geq 0 \mbox{ and } t\geq 0.
            \end{equation*}
            \item[(ii.6')]
            For every $s\in [0,\infty)$, and every $\nu_s\in \mathcal{P}(\mathbb{R}^d)$ which satisfies $\nu_s\leq c \mu_s$ for some constant $c>0$, we have that
            \begin{equation*}
            \nu_{t+s}:=\mathbb{P}_{\delta_s\otimes\nu_s}\circ \left(X_2(t)\right)^{-1}, \quad t\geq 0,
            \end{equation*}
            is the unique weakly continuous solution to the LFPE \eqref{eq:LFPshort} on $[s,N)$ which consists of probability measures, belongs to $\mathcal{A}_{\lesssim u}^{s,N}$, and whose initial condition (at time $s$) is $\nu_s$, for all $N>s$.
            Moreover, the (strong Markov) process $X$ is the unique solution to the martingale problem on $[s,N)$ associated with $\left(\overline{\sf L}, C_c^{\infty}((0,\infty)\times \mathbb{R}^d)\right)$, with initial distribution $\delta_s\otimes\nu_s$ and with $(X_2(t))_{t\geq 0}$ having the one-dimensional marginals in $\mathcal{A}_{\lesssim u}^{s,N}$, for every $N>s$.
        \end{enumerate}

[Lemma 5 of arXiv:2606.24703, 'Scheduling jobs with unknown size distribution in a M/G/1 queue: the shifted empirical Git'] Let $\Delta \in \N$. Denoting $A := d(\widehat{f_{n, \Delta}}, f_\Delta)$. Then for all $i \in [0, \Delta]$:
    \begin{equation}
        \left(\frac{1 - \frac{A\Delta}{L}}{1+\frac{A \Delta}{\ell}}\right) \nu_\Delta(\frac{i}{\Delta})
    \leq \widehat{\nu_{n, \Delta}}(\frac{i}{\Delta}) \leq \left(\frac{1 + \frac{A\Delta}{\ell}}{1 -
        \frac{A\Delta}{L}}\right) \nu_\Delta(\frac{i}{\Delta}).
  \end{equation}

