[Definition def:AGG-3.1 of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] For any subgroup $\Gamma$ in $\mathrm{SL}(n, \mathbb{Z})$, we define $W(\Gamma)$ to be the vector space of functions $f \colon \mathrm{SL}(n, \mathbb{Z}) \to \mathbb{C}$ with compact support modulo $\Gamma$ that satisfy:
    \begin{enumerate}
        \item $f(m \gamma) = f(m)$ for all $\gamma \in \Gamma$;
        \item $f(\sigma_1 m) = -f(m)$;
        \item $f(\sigma_2 m) = (-1)^{n + 1} f(m)$;
        \item $f(m) + f(hm) + f(h^2 m) = 0$;
    \end{enumerate}
    for all $m \in \mathrm{SL}(n, \mathbb{Z})$.

[Theorem the3.4 of arXiv:2411.13266, '\bf A new maximal regularity for parabolic equations and an application'] Let $\alpha,p,\rho,a,\vartheta,\varsigma$ and $f$ be stated in Theorem (the3.1 of the paper) with $\alpha\geqslant 2/p-1$, and let $\lambda\geqslant 0$. Let $u$ be given by~((3.6 of the paper)).

(i) If $\alpha\, \notin \, \{2/p-1,2/p\}$, then $u\in L^\infty([0,T];{\mathcal C}_{\vartheta,\varsigma}^{2+\alpha-\frac{2}{p},\rho}({\mathbb R}^n))$ and
\begin{eqnarray}
\|u\|_{L^\infty([0,T];{\mathcal C}_{\vartheta,\varsigma}^{2+\alpha-\frac{2}{p},\rho}({\mathbb R}^n))}\leqslant C\|f\|_{L^p([0,T];{\mathcal C}_{\vartheta,\varsigma}^{\alpha,\rho}({\mathbb R}^n))}.
\end{eqnarray}

(ii) Let $\varsigma=d$. If $\alpha=2/p-1$,  then $u\in L^\infty([0,T];{\mathcal C}_{\vartheta,s}^{1,\hat{\rho}}({\mathbb R}^n))$, and if $\alpha=2/p$, then  $u\in L^\infty([0,T];{\mathcal C}_{\vartheta,s}^{2,\hat{\rho}}({\mathbb R}^n))$. Moreover, there exists a positive constant $C$ such that
\begin{eqnarray}
\|u\|_{L^\infty([0,T];{\mathcal C}_{\vartheta,s}^{2+\alpha-\frac{2}{p},\hat{\rho}}({\mathbb R}^n))} \leqslant C\|f\|_{L^p([0,T];{\mathcal C}_{\vartheta,d}^{\alpha,\rho}({\mathbb R}^n))}, \ \ \alpha\in \Big\{\frac{2}{p}-1, \frac{2}{p}\Big\},
\end{eqnarray}
where
\begin{eqnarray}
\hat{\rho}(r)=\int\limits_0^r\frac{\rho(\tau)}{\tau}d\tau+ \rho(r)+r\int\limits_r^1\frac{\rho(\tau)}{\tau^2}d\tau, \ \ r\in (0,1].
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi Mild-det of arXiv:2506.08202, 'Stochastic dissipative systems in Banach spaces driven by L\'evy noise'] For every  $x\in E$ we call mild solution of (equation eq of the paper) a function $y(\cdot,x)$ such that, for every $t\in [0,T]$, we have

\begin{align}
 y(t,x)=e^{tA}x+\int_0^te^{(t-s)A}F(y(s,x)+f(s))ds.
\end{align}

