Then,
\begin{align*}
    \|\KM^\mu_{\delta\gets} - \KM^\nu_{\delta\gets}\|_{L^2(\gamma)}
    &\leq W_2(\mu,\nu)\int_\delta^\infty \frac{\exp\bigl(\textstyle \int_\delta^t \theta_\omega \dd \omega\bigr)}{\sqrt{c(t)}}\dd t\,,
\end{align*}
where $c(t)$ is defined in \eqref{eq:ct}.

