				&\leqslant\frac{4}{|{\scaleobj{1.2}{\square}}_m|}\sum_{y\in\mathbb{Z}}\left(|{\mathsf{D}}_1\overline{g}_\lambda(y,x)|+|{\mathsf{D}}_1\overline{g}_\lambda(y,x+1)|\right).
			\end{align*}
			By the definition of the averaged slope $[{\mathsf{D}}\overline{G}_\lambda]_m^z$ in (equation eq.AveSlopeDeg2 of the paper), we can obtain
			\begin{equation*}
				\norm{[{\mathsf{D}}\overline{G}_\lambda]_m^z}_{L^\infty}\leqslant \sum_{y\in\mathbb{Z}}\frac{2}{|{\scaleobj{1.2}{\square}}_m|}\sum_{x\in z+{\scaleobj{1.2}{\square}}_m}|{\mathsf{D}}_1\overline{g}_\lambda(x,y)|.
