[Lemma 9 of arXiv:2608.04644, 'Khinchin's and Chung's Laws of the Iterated Logarithm at Time Zero for the Linear Stochast'] Recall that $H$ is defined in \eqref{def:H}. Suppose that Condition \ref{hypo}  holds  and that $H<1$.
For $R>0$, define
\begin{equation}
	J(R):=\int_{\RR^d}\left| \int_0^{R}e^{ir}r^{\beta+\gamma-1}E_{\beta, \beta+\gamma}\left(-r^\beta|\eta|^\alpha\right)dr\right|^2 |\eta|^{\ell-d} d\eta.
\end{equation}
Then there exists a constant $c_{2,2}>0$, independent of $R$, such that
\begin{equation}
	J(R)\le c_{2,2}\begin{cases}
		R^{2(H+1-H_0)},  & 0<R\le1, \\[2.5ex]
		1, &  R>1, H<H_0, \\[2.5ex]
		(\log R)^2,&  R>1, H=H_0, \\[2.5ex]
		R^{2(H-H_0)},& R>1, H>H_0.
	\end{cases}
\end{equation}

