body:
[Def compact-BC of arXiv:2608.26876, 'Local Bousfield classes via homological support'] Let $\cat T$ be a rigidly-compactly generated tensor-triangulated category. For arbitrary $A\in\cat T$ the functor
	\begin{equation}
		\Hom_{\bbZ}(\cat T(\unit,A\otimes-),\bbQ/\bbZ)\colon \cat T\op\longrightarrow \Ab
	\end{equation}
	is homological and sends coproducts in $\cat T$ to products in $\Ab$. It is thus represented by an object $I_A\in\cat T$ by Brown representability. Consequently, there is an isomorphism
	\begin{equation}
		\cat T(t,I_A)\simeq \Hom_{\bbZ}(\cat T(\unit,A\otimes t),\bbQ/\bbZ)
	\end{equation}
	which is natural in $t\in\cat T$. It follows formally from Yoneda that $A \mapsto I_A$ provides a functor $\cat T\op \to \cat T$.

[Proposition 2 of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] Let $\{\xi_t\}_{t\geq 0}$ be a $\mathbb{R}^{d_2}$-dimensional progressively measurable process independent of $W$, and assume
  \begin{align*}
    \int_0^tE\left[ |\xi_s|^2 \right]ds<\infty.
  \end{align*} 
  for every $t\geq 0$. Then, 
  \begin{align*}
    M_t=&\exp\left( \int_0^t \xi_s^\top (\sigma(s)\sigma(s)^\top)^{-1} \sigma(s) \, dW_s \right. \\
    &\quad \left. - \frac{1}{2} \int_0^t \xi_s^\top (\sigma(s)\sigma(s)^\top)^{-1} \xi_s \, ds \right).
  \end{align*}
  is a martingale.

  Furthermore, if we define a probability measure $Q$ on $\mathcal{F}_T$ by 
  \begin{align*}
    Q(A)=E[1_AM_T]~~(A\in \mathcal{F}_T)
  \end{align*}
  for a fixed $T$, then for any multi-dimensional random variable $U$ which is independent of $W$, the law of $(U,\{Y_t^\epsilon\}_{0\le t\le T})$ under $Q$ coincides with the law of $(U,\{\tilde Y_t^\epsilon\}_{0\le t\le T})$ under $P$, where
  \begin{align*}
    d\tilde{Y}_t^\epsilon=\{H_t^\epsilon+\xi_t\}dt+\sigma(t)dW_t,~~\tilde{Y}_0^\epsilon=0.
  \end{align*}

[Lemma lemme approx kappa to 4 of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] {BECriLQG}}]
	Jointly for all $n\ge 1$,
	\begin{equation*}
	\left( (D^{\kappa,n}_t)_{t\ge 0}, \tau^{\kappa,n}, (e^{\kappa,n}_k)_{1 \le k \le \Lambda^{\kappa,n}}\right) \mathop{\longrightarrow}\limits_{\kappa \downarrow 4}^{(\mathrm{d})}
	\left( (D^n_t)_{t\ge 0}, \tau^n, (e^{n}_k)_{1 \le k \le \Lambda^n}\right),
	\end{equation*}
	where the first coordinate converges in the space $\SD$, the second one converges in $\BR$ and where the excursions converge for the topology of uniform convergence on compact subsets. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lemma: backtrack cancellations of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Suppose that $\ell=\pi_1 \, \mathbf{e} \, \mathbf{e}^{-1} \, \pi_2$ is a loop with backtrack $\mathbf{e} \, \mathbf{e}^{-1}$ and $(\ell,K)$ is a balanced pair. Then 
\begin{equation*}
	\phi^K(\pi_1 \, \mathbf{e} \, \mathbf{e}^{-1} \, \pi_2) = \phi^K(\pi_1 \, \pi_2),
\end{equation*}
where $\phi^K$ has been introduced in the statement of Theorem~(thm: surface sum representation in 't hooft limit of the paper).

[Theorem main1 of arXiv:2605.10309, 'Exponential Decay of $L^2$-Solutions to Stochastic Nonlinear Schr\"odinger Equations Drive'] Assume (H1), (H2) with $r_j=\infty$ for all $j$ and (H3), and let $1<\alpha<1+\frac{4}{d}$. 
Then, for each $x\in L^2$ and $0<T<\infty$, there is a unique solution $X=X(t,\xi)$ to (equation SNLS of the paper) in the sense of Definition (sol1 of the paper), which satisfies
\begin{align}
X&\in L^2(\Omega;C([0,T];L^2)), \\
X&\in L^q(0,T;L^{\alpha+1}), \ {
{\mathbf{P}}\text{-a.s.}}
\end{align}
where $q=\frac{4(\alpha+1)}{d(\alpha-1)}\in (2+\frac{4}{d},\infty).$
Moreover, for ${
{\mathbf{P}}\text{-a.s.}} \ \omega\in\Omega$, the map $x\mapsto X(\cdot,x,\omega)$ is continuous from $L^2$ to $C([0,T];L^2)\cap L^q(0,T;L^{\alpha+1})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Satz 67 of arXiv:2511.20322, 'Dissertation'] Suppose we are given a sequence $(\si_N)_{N\in \N}$ of random $J$-dimensional permutations, such that \assref{assum:limitCopulas} holds true.
Then $(X^N_t)_{t\in [0,1]}$ converges in distribution to a centered Gaussian process $W$, as $N\to \infty$, with
\begin{equation}

\Cov(W^i_s, W^j_t) = F^{ij}_{\mu}(s,t), \quad s,t\in [0,1], i, j < J.
\end{equation}

Conversely, given a centered Gaussian process $W$ and a $J$-permuton $\mu$, such that \eqref{eq:covShuffledDonsker} holds true, there exists a sequence $(\si_N)_{N\in \N}$ of random $J$-dimensional permutations, such that \assref{assum:limitCopulas} holds true and so $(X^N)_{t\in [0,1]}$ converges in distribution to $W$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Wells' disorder of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given an integer $L \in \ensuremath{\mathbb{N}}$, an integer $n \geq 2$, a parameter $\lambda > 0$, two inverse temperatures $\beta_1 , \beta_2 \geq 0$, we define the Wells' disorder by the identity, for $r \in \{ 0 , 1\}^{\Lambda_L}$,
 \begin{equation*}
     \nu_{L , n , \beta_1 , \beta_2 , \lambda}(\{ r \}) := \frac{Z_{\Lambda_L , n , \beta_1 , \beta_2 , \lambda, r}^{\mathrm{XY}}}{\bar{Z}_{\Lambda_L , n , \beta_1 , \beta_2 , \lambda}^{\mathrm{XY}}} ~~\mbox{with}~~ \bar{Z}_{\Lambda_L , n , \beta_1 , \beta_2 , \lambda}^{\mathrm{XY}} := \sum_{r \in \{0, 1\}^{\Lambda_L}} Z_{\Lambda_L , n , \beta_1 , \beta_2 , \lambda, r}^{\mathrm{XY}}.
 \end{equation*}

[Definition def:recovery of arXiv:2603.14906, 'Four Levels of Thermodynamic Convergence of Singularly Perturbed Markov Semigroups'] Fix $t>0$. A sequence $(\psi_k)_{k\in\mathbb N}\subset C_b(\bar E;\mathbb R^n)$ is called a
recovery sequence at time $t$ if
\begin{equation}
  \int_{\bar E}
  \bar u(t,x)\,
  \big\|\psi_k(x)-\bar A(x)^{-1}\bar\gamma(x)\big\|_{\bar A(x)}^2\,d\bar\pi(x)
  \ \longrightarrow\ 0
  \qquad\text{as }k\to\infty,
\end{equation}
where $\|v\|_{\bar A(x)}^2:=v^\top \bar A(x)\,v$.

[Pro 16 of arXiv:2605.30779, '2605.30779'] There exists a coupling under which
\(\widetilde{\mathcal G}_{N,r}\) and \(\mathcal G_{r-1}\) are defined
on the same probability space and
\begin{equation*} 
\widetilde{\mathcal G}_{N,r}
\xrightarrow{\mathrm{mer}}
\mathcal G_{r-1}
\qquad\text{almost surely}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 34 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] [Level lines of the macroscopic shape]


		For any $a, b, c >0$, $\mq \in \mathbb{R}$ and $0<h<b$, define $\mathcal{U}_{\mq; a, b, c}^h : [0,a+c]\mapsto [0,b+c] $ by setting
		\begin{equation} 
                  \mathcal{U}_{\mq; a, b, c}^h (x) = y\in [0,b+c]: \mathcal{H}_{\mq; a, b, c}(x,y)=h.
		\end{equation}
 If instead $h=0$ or $h=b$, then given $x$ there may exist multiple $y$ satisfying $ \mathcal{H}_{\mq; a, b, c}(x,y)=h$. In that case,  we define
 \begin{flalign}

   \begin{aligned}
                  \mathcal{U}_{\mq; a, b, c}^0 (x) & = \sup\{y\in [0,b+c]: \mathcal{H}_{\mq; a, b, c}(x,y)=0 \}; \\
                  \mathcal{U}_{\mq; a, b, c}^b (x) & = \inf\{y\in [0,b+c]: \mathcal{H}_{\mq; a, b, c}(x,y)=b\}.
                  \end{aligned}
                \end{flalign}
Also, define
                 $\mathfrak{l}_{\mq; a, b, c} : [0,y^W_{q;a,b,c}] \rightarrow [0,x^{SW}_{q;a,b,c}]$  by letting
                  $\mathfrak{l}_{\mq; a, b, c} (y)$ be the $x$ coordinate of the unique point of $\mathfrak A^{SW}_{q;a,b,c}$ with vertical coordinate $y$ (namely, so that $(\mathfrak{l}_{q;a,b,c}, y) \in \mathfrak{A}^{SW}_{q;a,b,c}$). 
                  Note that  $ \mathfrak{l}_{\mq; a, b, c} (0)=x^{SW}_{q;a,b,c}$ and $\mathfrak{l}_{\mq;a,b,c}(y^W_{q;a,b,c})=0$.
                See Figure \ref{fig:U}. As usual, if either $q=0$ or $a=b=c=1$, we drop these indices from the notation.

[Lemma 15 of arXiv:2605.11877, 'Fluctuation analysis for a randomly perturbed dynamical system with state-dependent impuls'] There exists a constant $C_{\ref{L:CLT-comparison-G}}>0$ depending on $\sfK_b$, $\|h^\prime\|$, $\|h^{\prime\prime}\|$,  $\sfT$, $\sfN$ such that for $\eps \in (0,1)$ small enough, $t \in [0,\sfT]$, we have
\begin{equation*}
\begin{aligned}
|R^\eps_{\lambda^\eps_t}-r(t)-\eps R^1_t|\cdot \ind_{G^\eps_\sfN} & \le C_{\ref{L:CLT-comparison-G}}\left\{\|J^\eps_\cdot-1\|_\infty+ \sup_{[0, \sfT]} |R^\eps_{\lambda^\eps_t} - r(t)|^2 + \int_0^t \sup_{0 \le u \le s}|R^\eps_{\lambda^\eps_u}-r(u)|^2 \thinspace ds \right.\\& \left. +\eps \sup_{\substack{0 \le s<t \le \sfT\\ |t-s|<\delta}} |W_t - W_s|\right\}e^{C_{\ref{L:CLT-comparison-G}}t}\cdot \ind_{G^\eps_\sfN}
\end{aligned}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem SPDE-G-lem of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Under (SPDE-G-sass of the paper), we have the following assertions:
    \begin{enumerate}[label=(\roman*)]
        \item There is $\beta \in (-1/2,0]$ such that $\|x \cdot H\|_{\beta,r} \lesssim \|x\|_{L^r}$ for all $r \in [2,\infty)$ and $x \in L^r$. In particular, the estimate is valid for any $\beta \in \big(-\frac{1}{2},  -N(\frac{1}{4} - \frac{1}{2p})\big)$, and additionally for $\beta = 0$ if (equation eq:an-en-assumption of the paper) holds with $p = 2$.
        \item For all $r > 2$ there is $\epsilon > 0$ such that the following holds for all $x,y \in \{x \in C(\overline D)_+ \mid \|x\|_{L^1} \leq 1\}$: 







        \begin{equation}
        \begin{aligned}
        \|H^*(x)\|_\mathcal{U}^2\|y\|_{\epsilon-1,r} + \|y\cdot H H^*(x)\|_{\epsilon-1,r} +\|H^*(x)\|_\mathcal{U}\|y\|_{\epsilon-1/2,r} \\
        \lesssim \|x\|_{L^2}^2 + \|x\|_{L^r} + \|y\|_{L^2}^2 + \|y\|_{L^r}\,,
        \end{aligned}
        \end{equation}
         where the adjoint of $H$ is taken in $\mathcal{L}(\mathcal{U},L^2)$.



         \item With $\beta$ as in (i),
\begin{equation}
    \|G(x)^*1\|_\mathcal{U}\|x\|_{\beta,2} \lesssim \|x\|_{\beta+1/2,2}\|x\|_{L^1} \,,
\end{equation}
where the adjoint of $G(x)$ taken in $\mathcal{L}(\mathcal{U},L^2)$.
    \end{enumerate}

