{"artifact_digest":"sha256:6ae063a38bb40a1d1768c5337c228e190ead47a78d24ea43a151916f87b02ea9","artifact_path":"objects/sha256/6a/6ae063a38bb40a1d1768c5337c228e190ead47a78d24ea43a151916f87b02ea9.md","bundle_digest":"sha256:581c285c623fa6d2b643595218a61916d3e57e9d675d5033a0ce6c06fe437e20","bundle_entry_key":"2608-10876-lemma-11-le1n","bundle_id":"population.tex-extract-s3_093","claim_kind":"lemma","conditions":[],"domain":"probability theory","draft":"tex-extract-20260907/bundle_s3_093.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2608-10876-lemma-11-le1n","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: Since the proof is technical, we divide it into the following four steps.

