[Thm 7 of arXiv:2607.11076, 'Smoluchowski-Kramers Approximation for Stochastic Differential Equations driven by Fractio'] (i) Let $0<\alpha<1.$ Under assumption \textbf{(A1)},
		\begin{equation}
			\mathbb{E}\sup\limits_{0\leq t\leq T}|X^\mu(t)-\bar{X}^\mu(t)|\lesssim \mu^\alpha.
		\end{equation} 	
		(ii) Let $\alpha=0.$ Under assumption \textbf{(A1)},
		\begin{equation}
			\lim_{\mu \to 0} \sup\limits_{0\leq t\leq T} \mathbb{E} |X^\mu(t)-\bar{X}^\mu(t)| = 0.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:rectangle of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:rectangles}
Let $V=(V_1,\ldots,V_m)$ be a centered Gaussian vector with
$\operatorname{Var}(V_i)=1$ for every $i$.  For
$r_1,\ldots,r_m\in[0,\infty]$,
\begin{equation}
  \mathbb P\{|V_i|\leq r_i\text{ for all }i\}
  \geq\prod_{i=1}^m\mathbb P\{|Z|\leq r_i\},
  \qquad Z\sim\mathcal N(0,1).
\end{equation}
If $0<r_i<\infty$ for every $i$, then equality in
(equation eq:rectangle of the paper) holds if and only if
$\operatorname{Cov}(V)=I_m$.

