[Proposition 1 (Heat-kernel representation and closed form) of arXiv:2607.07712, 'Parameter-Space Heat Flow, Gaussian Density Ratios, and Sharp Hermite Truncation Rates'] For the temperature-extended generating function
\(U(\tau,u;v)=\Phi_\tau(u;v)\), the following heat-kernel representation holds.
For \(\tau>0\),
\begin{equation}
U(\tau,u;v)
=
\int_{\mathbb R^d}
\frac{1}{(2\pi\tau)^{d/2}}
\exp\!\left(-\frac{|u-z|^2}{2\tau}\right)
\Phi(z;v)\,dz.

\end{equation}
Moreover, this integral is explicitly equal to
\begin{equation}
U(\tau,u;v)
=
(1+\tau)^{-d/2}
\exp\!\left(
\frac{\tau |v|^2+2u\cdot v-|u|^2}{2(1+\tau)}
\right).

\end{equation}
In particular,
\[
U(0,u;v)=\Phi(u;v)
\]
by taking \(\tau\downarrow0\).

[Lemma 4 of arXiv:2506.17470, 'The coalescent of a sample from a linear-fractional branching process'] Let $\tau$ be an ultrametric, oriented tree with $n$ tips and node depths $x_1, \dots, x_{n-1}\in \{1,\dots, T\}$ and $x_0=T$. The likelihood function of the parameters $(p,r)$ given the outcome $\{\mathbf{T}_y=\tau\}$ is
   \begin{equation*}
    \mathcal{L}(p, r \mid  \tau, y)=
      \mathbb{P}(\mathbf{T}_y=\tau)=\mathbb{P}(H_y>T)\prod_{i=1}^{n-1} \mathbb{P}(H_y = x_i).
   \end{equation*}
Moreover, the likelihood of $(p,r)$ conditioned on $\{K=n\}$ is given by
      \begin{equation*}
      \mathcal{L}(p, r \mid  \tau, y, n):= \mathbb{P}(\mathbf{T}_y=\tau \mid K = n)=\prod_{i=1}^{n-1} \frac{\mathbb{P}(H_y = x_i)}{\mathbb{P}(H_y\le T)}.
   \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 51 (\cite{Ber21, BB23, BB24a}) of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] There is a diffeomorphism~$\Omega:\mathcal F_R\to \mathcal R_0$, such that for~$q\in \mathcal R_0$,
\begin{equation*}
\d F(q;\xi,\eta)=0 \iff q=\Omega(\xi,\eta).
\end{equation*}
Moreover,~$\Omega(\xi,\eta)$ is a simple zero of~$\d F(q;\xi,\eta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 13 of arXiv:2607.29534, 'Expected signatures via partial integration, coordinate change and symmetrization'] The rows $(\Psi^{-1}_w)_{w\in\mathcal{W}_{\mathcal{A}}}$ from
\Cref{prop:Psi} satisfy
\begin{equation}
\Psi^{-1}_r
=
r,
\qquad
\Psi^{-1}_{w\blue{i}\orange{i_1}\cdots\orange{i_m}}
=
\sum_{k=0}^{m}
(-1)^k
\bigl(
    \Psi^{-1}_w
    \gammashuffle
    \orange{i_k}\cdots\orange{i_1}
\bigr)
\blue{i}
\orange{i_{k+1}}\cdots\orange{i_m},
\end{equation}
for $w\in\mathcal{W}_{\mathcal{A}}$,
$\blue{i}\in\mathcal{A}^{\prime}$, and
$\orange{i_1},\ldots,\orange{i_m}\in\mathcal{A}^{\prime\prime}$, where
empty strings of letters are omitted.

[Lemma low1 of arXiv:2412.09471, 'On the moderate deviation principles in the sparse multi-type Erd\H{o}s R\'enyi random gra'] For any scaling sequence $n^{\frac{1}{4}}\ll a_n\ll\sqrt{n}$ and $\beta>0$,
    the corresponding conditional inferior limit satisfies the following:
\begin{equation*}
\begin{aligned}
    &\lim_{\delta\to 0}{\liminf_{n\rightarrow \infty}\frac{1}{a_n^2}\log{\mathbb P}}\left(\frac{1}{a_n\sqrt{n}}\left(\max_{1\leq i\leq N(nZ_n)}X_i^n-(\mu-c)n\right)\in B_\delta(\beta)\bigg|\sum_{i=1}^{N(nZ_n)}X_i^n=\mu^n n\right)\\
    \geq& -\frac{1}{2}\left\langle\left(I-D_c\kappa\right)\beta,D_v\left(I-D_c\kappa\right)\beta\right\rangle.
\end{aligned}
\end{equation*}

