body:
[Theorem 34 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $(G_n)_{n \in \N}$,  $|G(V_n)| \asymp n^d$, be the sequence of boxes $[-n, n]^d$ in $\mathbb{L}^d$, $d \geq 5$. There exists constants $p^*, c_1, c_2, \gamma > 0$, all depending only on $d$, such that for a sequence of environment distributions $(\mu_n)_{n\geq 1}$ and $a_1 = a_1(n), a_2 = a_2(n)$ satisfying
    \begin{equation} 
    \begin{aligned}
        a_1 &:= F^{-1}_{\mu_n} \big( \frac{1}{2d - 1} - \frac{p^*}{2} \big), \\
        a_2 &:= F^{-1}_{\mu_n}(1 - p^* ), \\
        a_2 - a_1 &\ll \log n,
    \end{aligned}
    \end{equation}
    for all $n \in \N$, we have for any $\delta > n^{-\gamma}$ that
    \begin{equation}
            \widehat \P \left( \frac{n^{d/2}}{c_1 \chi^{c_2} } \leq \diam(\cT) \leq c_1 \chi^{c_2} n^{d/2}  \right) \geq 1-\delta,
    \end{equation}
        where
    \begin{equation*}
            \chi = \chi(a_1,a_2, \delta, n) = \exp(a_2-a_1) \delta^{-1} \log n.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Gamma-exact of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Under the two-mode approximation, for every $k\ge1$,
\begin{equation}
\Gamma_k = \frac{x_k(1-\rho_\star^2)^2}{(1+x_k\rho_\star^2)^2},
\end{equation}
exactly, with no asymptotic approximation; consequently
\begin{equation}
\Gamma_k = (1-\rho_\star^2)^2\, x_k + O(x_k^2).
\end{equation}

[Proposition 4 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[proposition]{prop:well_effective}
    Assuming \cref{hp:noise} and $\psi_0\in L^2(\R^d)$, there exists a unique solution of \eqref{eq:simplified_model} in the sense of \cref{def:weak_sol_effective}. Moreover, 
    \begin{align}
        \|\Psi^{\tau}_t\|^2=\|\psi_0\|^2 \quad \text{for all }t\geq 0, \quad  \mathbb{P}-a.s.
    \end{align}
   In particular, $\Psi^{\tau}$ has paths in $C([0,T];L^2)\ \mathbb{P}-a.s.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

