[Prop 2 of arXiv:2608.30796, 'Tumor boundary instability induced by pressure feedback'] Let \(\lambda>0\) and \(l\geq2\). Then the two iterated limits satisfy
\begin{subequations}

\begin{align}
\lim_{\gamma\to0^+}\lim_{R\to+\infty}
R^2\mathcal{F}_l(R;\lambda,\gamma)
&=
\frac{l^2-1}
{2\sqrt{\lambda}(\sqrt{\lambda}+1)},
\\
\lim_{R\to+\infty}\lim_{\gamma\to0^+}
R^2\mathcal{F}_l(R;\lambda,\gamma)
&=
\frac{(l^2-1)(\sqrt{\lambda}-1)}
{2\lambda(\sqrt{\lambda}+1)}.
\end{align}
\end{subequations}

[Definition 3 of arXiv:2604.10705, '#1'] A functional $F:[0,T]\times D([0,T],\mathbb{R}^d)\to \mathbb{R}$ is \emph{boundedness-preserving} if for every $t \in [0,T)$ and compact set $K \subset \mathbb{R}^d$, there exists a constant $C_{t,K}> 0$ such that:
        \begin{align}
            x(s) \in K,\,\, \forall s \in [0,t] \implies |F(s,x_{\wedge s})| \leq C_{t,K},\,\,\forall s \in [0,t].\nonumber
        \end{align}

