[Lemma lem:disi of arXiv:2602.00853, 'Mixing times for the stochastic $p$-Laplace equation'] Let $r\geq 1$ be fixed.
Assume that there exists a unique invariant probability measure $\mu_\ast$ on $(H,\mathcal{B}(H))$ with finite absolute moment of order $r$ for the dual semigroup $(P^\ast_t)_{t\ge 0}$ on the space of probability measures on $(H,{\mathcal B}(H))$.
Then for any $x\in H$ and $0<s\leq t$
it follows that
\begin{equation}
\mathcal{W}_r(P^*_t\delta_x,P^*_t\mu_\ast)\leq \int_{H}
\int_{H}\mathcal{W}_r(P^*_s\delta_z,P^*_s\delta_y)P^*_{t-s}\delta_x(\mathrm{d} z)\mu_\ast(\mathrm{d} y).
\end{equation}
In particular, it follows that
\begin{equation}
\mathcal{W}_r(P^*_t\delta_x,\mu_\ast)=\mathcal{W}_r(P^*_t\delta_x,P^*_t\mu_\ast)
\leq \int_{H} \mathcal{W}_r(P^*_t\delta_x,P^*_t\delta_y)\mu_\ast(\mathrm{d} y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 17 of arXiv:2603.28702, 'Distribution of the magnetization of the critical Ising model on sparse random graphs'] \begin{enumerate}
\item
The random variable $X_{\ell,n}$ has
\begin{align*}
&\E(X_{\ell,n})=(1+O(n^{-1}))\cdot\dfrac{1}{2}nd^\ell\ \ \text{and}\\ &\text{Var}(X_{\ell,n})=(1+O(n^{-1}))\cdot\dfrac{1}{2}nd^{2\ell}\dfrac{\ell^2}{d-1}\left(1+\gamma_\ell^{(2)}\right),
\end{align*}
where $\lim\limits_{\ell\to\infty}\gamma_\ell^{(2)}=0$.
\item 
Let $m$ be as in statement 4 of Proposition \ref{cyc-path-ER}. Then, under the planted measure $\PR_m^*$,
\begin{align*}
&\E_m^*(X_{\ell,n})=(1+O(n^{-1}))\cdot\dfrac{1}{2}nd^\ell\left(1+m^2n^{-2}\dfrac{\ell}{d-1}\left(1+\gamma_\ell^{(1)}\right)\right)\ \ \text{and}\\ &\text{Var}_m^*(X_{\ell,n})\sim\text{Var}(X_{\ell,n}),
\end{align*}
where $\lim\limits_{\ell\to\infty}\gamma_\ell^{(1)}=0$.
\end{enumerate}

