body:
[Lemma 12 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Let $L$ be a cylindrical L\'evy process in $U$, and let $\Psi$ be a predictable, $L_2(U,H)$-valued process that is integrable with respect to $L$. Then the integral process $(Y(t):\, t\in [0,T])$, defined by $Y(t):=\int_{(0,t]} \Psi\,{\rm d}L$, satisfies the following properties: 
	\begin{enumerate}
        \item [{\rm (a)}] Let $V$  be a separable Hilbert space  and $B \in L(H,V)$. Then, for all $0\leq p<q\leq T$ and $S \in \mathcal{F}_{p}$, we have that $\mathbb{1}_S B\Psi$ is $L$-integrable and
        	\begin{equation}
        		\mathbb{1}_{S}B \left(\int_{(p,q]} \Psi(s)\,{\rm d}L(s)\right)=\int_{(p,q]} \mathbb{1}_S B\Psi(s)\,{\rm d}L(s).
        \end{equation}
		\item [{\rm (b)}] Let $\Phi:\Omega\times[0,T]\rightarrow H$ be a uniformly bounded, adapted, càglàd process. Then, for each fixed $t>0$,  it follows that $\langle \Psi^\dagger \Phi, \cdot \rangle$ is $L$-integrable and
		\[\int_{(0,t]} \langle\Phi(s),\cdot\rangle \, {\rm d}Y(s)=\int_{(0,t]} \big\langle \Psi^\dagger(s)\Phi(s),\cdot\big\rangle \, {\rm d}L(s).\]
		\item [{\rm (c)}] For every stopping time $\tau$, we have that $\1_{(0,\tau]}\Psi$ is $L$-integrable and
		\[Y(\tau \wedge T)=\int_{(0,T]} \1_{(0,\tau]}(s)\Psi(s)\,{\rm d}L(s).\]
	\end{enumerate}

