[Prop 3-6-0-CP of arXiv:2412.00708, 'Stochastic PDE approach to fluctuating interfaces'] For every $t>0$ and $G\in L^2({\mathbb{R}})\cap L^1({\mathbb{R}})$, we have
\begin{align*} 
\lim_{K\to\infty} \| e^{-tK\mathcal{A}^K} G(z) 
- \langle G, e\rangle_{L^2({\mathbb{R}})} e(z)\|_{L^2(\sqrt{K}{\mathbb{T}})} =0,
\end{align*}
with the first $G$ interpreted as $G|_{\sqrt{K}{\mathbb{T}}}$, where
\begin{align}  
e(z) := U_0'(-z) /\|U_0'\|_{L^2({\mathbb{R}})}, \quad z\in {\mathbb{R}}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 19 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] If $X$ has bounded variation, then for every non-empty word $I = i_1\dots i_n$, $n\leq \kappa-1$:
    \[
K^{(I)}
=
\sum_{\pi \in NC(n)}
\left(
\prod_{(p,q) \in P(\pi)} (-1) \delta_{i_p,i_q}
\right)
K_{\,i_{U_1},\ldots,i_{U_r}},
\]
with the convention $K^{(\emptyset)} = K_\emptyset$ and for a non-empty word $J = j_1 \dots j_m$
\begin{equation}
K_{J}(s,t) =   (-1)^{m} \int_{s < u_1 < \dots < u_m <t} K(s, u_1)K(u_1, u_2) \dots K(u_{m-1}, u_{m})K(u_{m}, t) dX^{(j_1)}_{u_1}\dots dX^{(j_m)}_{u_m}.
\end{equation}

[Theorem 6 (Fundamental theorem of the infimal convolution) of arXiv:2604.02312, 'A weak transport approach to the Schrödinger--Bass bridge'] In the setting of \Cref{prop:properties_inf_conv}, assume in addition that $C_{V\Box W}$ is continuous and admits a $p$-growth bound.
    Then, the following hold for every $\mu \in \cP_p(\mathcal X)$ and $\nu\in\cP_p(\mathcal{Z})$:
    \begin{enumerate}[label = (\roman*)]
        \item  \textbf{Primal attainment.} The infimal convolution $V \Box W$ is a standard WOT problem, and the infimum is attained, that is,
        \[
            V\Box W(\mu,\nu) = \min_{\pi \in \cpl(\mu,\nu)} \int_\mathcal{X} C_{V \Box W}(x,\pi_x) \,\mu(\rmd x).
        \]

        \item  \textbf{Strong duality.} $V \Box W$ admits the dual representation
        \begin{align*}
             V \Box W(\mu,\nu)
             &=\sup_{f \in C_{b,p}(\mathcal Z)} \left\{\int_\mathcal{Z} f \, \rmd\nu + \int_\mathcal{X} (-f^{C_W})^{C_V} \,\rmd\mu \right\}.
        \end{align*}
    \end{enumerate}
    If, in addition, $W(\rho,\nu) < +\infty$ for all $\rho \in \cP_p(\mathcal Y)$, then:
    \begin{enumerate}[label = (\roman*),resume*]
        \item  \textbf{Dual attainment.} The dual problem is attained, that is,
        \begin{align*}
             V \Box W(\mu,\nu)
             &= \max_{f \in L^1(\nu)} \left\{\int_\mathcal{Z} f \, \rmd\nu + \int_\mathcal{X} (-f^{C_W})^{C_V} \, \rmd\mu\right\}.
        \end{align*}

        \item  \textbf{Complementary slackness.} Let $\rho^\circ \in \cP_p(\mathcal Y)$ and $f^\circ \in L^1(\nu)$. Then $\rho^\circ$ is optimal for
        \[
            \inf_{\rho \in \cP_p(\mathcal Y)} \bigl\{V(\mu,\rho)+W(\rho,\nu)\bigr\}
        \]
        and $f^\circ$ is optimal for the dual problem in \ref{it:thm.fundamental.3} if and only if
        \begin{equation}
            \begin{aligned}
                V(\mu,\rho^\circ) &= \int_\mathcal{Y} -(f^\circ)^{C_W} \,\rmd\rho^\circ + \int_\mathcal{X} (-(f^\circ)^{C_W})^{C_V} \, \rmd\mu, \\
                W(\rho^\circ,\nu) &= \int_\mathcal{Y} (f^\circ)^{C_W} \, \rmd\rho^\circ + \int_\mathcal{Z} f^\circ \,\rmd\nu.
            \end{aligned}
        \end{equation}
    \end{enumerate}

[Corollary 31 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Assume \textnormal{(A1)-(A5)}, and let $\mu_\epsilon^*$ and $\xi_\epsilon$ be given by Corollary~\ref{Cor2}. Then there exists a unique $\bar u\in H$ such that the constant trajectory $u(t)\equiv\bar u$ is a self-consistent stationary variational solution of \eqref{Eq3} with $\epsilon=0$. If $\delta_{\bar u}$ denotes the Dirac measure at $\bar u$, then, for every $\omega\in\Omega_0$,
	\begin{align}
		\mathcal A^0(\omega)
		=\big\{(\bar u,\delta_{\bar u})\big\},
		\qquad
		\xi_0(\omega)=\bar u,
		\qquad
		\mu_0^*=\delta_{\bar u}.
	\end{align}
	Moreover,
	\begin{align}
		\lim_{\epsilon\to0}
		\|\xi_\epsilon(\omega)-\bar u\|=0,
		\qquad \omega\in\Omega_0,
	\end{align}
	and, for every $\epsilon\in[0,\epsilon_0]$,
	\begin{align}
		\left(
		\mathbb E\|\xi_\epsilon-\bar u\|^2
		\right)^{1/2}
		=
		\mathcal W_2(\mu_\epsilon^*,\delta_{\bar u})
		\leq
		\epsilon
		\Big(
		\frac1{\kappa_0}
		\sum_{j=1}^{m}\|h_j\|^2
		\Big)^{1/2}.
	\end{align}

