[Lemma 89 of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Let $0<\delta<1$ with $\delta=O(\tfrac{\log\log\alpha}{\log\alpha})$, and let $\mu_1,\mu_2>0$ with $\mu_2=\Omega(1)$, $\mu_1+\mu_2=1$, and
		\begin{equation}
			\delta\geq\tfrac1{\mu_1}\left(8\left(1-\tfrac{\log M}{\log\alpha}\right)+2+\Omega(1)\right)\tfrac{\log\log\alpha}{\log\alpha}.
		\end{equation}
		Let $r=0,\ldots,\alpha-k-1$ with $t:=\alpha-k-r=O(M)$. Then $$\mathbb{E}(\Pi_t1_{\mathcal{P}_t^{\delta}}|S_r)\leq\exp\left((\tfrac{1}{2\mu_2}+o(1))t\log\log\alpha+O(\tfrac1{\delta}k)\right).$$

[Theo thm:RSW-s-embeddings of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] In the previous setup, there exist $c(r_0,\theta_0)>0$, only depending on $r_0,\theta_0$, such that
\begin{equation}
\mathbb{P}^{\textnormal{free}}_{\textnormal{FK}} \big( \textnormal{There exist an open circuit in } \mathrm{A}_{\frac{\rho}{2},\rho} \big) > c(r_0,\theta_0).		
\end{equation}
A similar estimate holds for the dual model. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 110 (Canonical massive-GFF Wick multipliers) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Assume \eqref{eq:geom-wick-subcritical}, let $1\le p,q<\infty$, and
suppose
\begin{equation}

 a>\beta_{d,m},\qquad b>\beta_{d,m},\qquad
 a+b>\beta_{d,m}+\frac dq.
\end{equation}
Then
\begin{equation}

 T_N^{a,b}[\chi]
 :=\Lambda_g^{-a}M_{\Phi_{m,N}^{[\chi]}}\Lambda_g^{-b}
\end{equation}
converges in $L^p(\Omega;\Sch_q)$ and almost surely in $\Sch_q$ along
dyadic $N$ to a canonical operator $T^{a,b}$.  The convergence has a
polynomial rate in every finite $L^p(\Omega;\Sch_q)$, and the limit is
independent of the admissible ultraviolet profile and of the dyadic
resolution inside the common spectral realization.  Moreover,
\begin{equation}

 (T^{a,b})^*=T^{b,a}.
\end{equation}

[Definition of arXiv:2503.21737, 'High-intensity Voronoi percolation on manifolds'] Let \(r, \rho > 0\).
    We say that a locally finite point set \(\xi\subset\mathbb R^d\) is \emph{\((r,\rho)\)-robust}, when the following holds for all \(x,y \in \xi \cap B_{\mathbb R^d}(0,r)\):
    \begin{enumerate}
        \item If the (Euclidean) Voronoi cells of \(x\) and \(y\) intersect in \(B_{\mathbb R^d}(0,2r)\), then there exists a \(w_{xy} \in B_{\mathbb R^d}(0,2r)\) such that
        \begin{equation*}
            \mathrm{d}_{\mathbb{R}^d}(w_{xy},x) = \mathrm{d}_{\mathbb{R}^d}(w_{xy}, y) < \mathrm{d}_{\mathbb{R}^d}(w_{xy}, \xi\setminus\{x,y\}) - \rho \cdot r.
        \end{equation*}
        \item If the (Euclidean) Voronoi cells of \(x\) and \(y\) do not intersect then
        \begin{equation*}
            \max\{ \mathrm{d}_{\mathbb{R}^d}(w,x), \mathrm{d}_{\mathbb{R}^d}(w,y) \} > \mathrm{d}_{\mathbb{R}^d}(w, \xi) + \rho \cdot r
        \end{equation*}
        holds for all \(w \in B_{\mathbb R^d}(0,2r)\).
    \end{enumerate}

