[Lemma sym-path-to-fwick of arXiv:2411.06131, 'Non-Markovian dynamics: the memory-dependent probability density evolution equations'] {ducan2000stochastic}}]
	If $ F\in \mathscr{L}^2_{\phi}(0, T)$, then the symmetric pathwise integral $\int_{0}^{t} F_s  \circ \mathrm{d} B^H_s$ and the FWIS integral $\int_{0}^{t} F_s \diamond\mathrm{d}B^H_s$ exist, and the following equality is satisfied:
	\begin{equation}
	\int_{0}^{t} F_s  \circ \mathrm{d} B^H_s= \int_{0}^{t} F_s \diamond\mathrm{d}B^H_s+\int_{0}^{t}D^{\phi}_sF_s\mathrm{d}s, \,  \forall t\in[0,T], \,a.s.,
	\end{equation}
	where $ D^{\phi}_t F_t $ is the Mallivian derivative of $F_t$ {\rm [ducan2000stochastic]}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theoremalpha thm:second-moment of arXiv:2608.30829, 'Free energy and phase transition for\\ 2D directed polymers with critical spatial correlat'] Suppose that Assumption~(main-assumption of the paper) holds and that \((\beta_N)_{N\geq 0}\) is given as in Assumption~(hyp:scaling of the paper).

  \begin{enumerate}[label=(\roman*)]
    \item Under~(equation finite-sum of the paper), we have that
    \begin{equation}

      \lim_{N\to\infty} \mathbb{E}\Big[ (W_N^{\beta_N})^2 \Big] =
      \begin{cases}
        (1-\hat\beta^2)^{-1} =: \exp(\varsigma^2(\hat \beta)) & \quad \text{ if } \hat \beta<1 \,,\\
        +\infty & \quad \text{ if } \hat \beta \geq 1 \,.\\
      \end{cases}
    \end{equation}

    \item Under~(equation def:h of the paper), letting \(\tilde{J}_{\alpha}(z) \coloneqq \Gamma(\alpha+1) (z/2)^{-\alpha} J_{\alpha}(z)\) be a modified Bessel function (recall~(equation eq:Bessel-function of the paper)) and \(z_a\) is its first zero, we have that
    \begin{equation}

      \lim_{N\to\infty} \mathbb{E}\Big[ (W_N^{\beta_N})^2 \Big] =
      \begin{cases}
        \tilde{J}_{\alpha}(\hat\beta)^{-1} =: \exp(\varsigma^2(\hat \beta)) & \quad \text{ if } \hat \beta<z_a \,,\\
        +\infty & \quad \text{ if } \hat \beta \geq z_a \,.\\
      \end{cases}
    \end{equation}
  \end{enumerate}
In particular, there is a phase transition for the second moment at the critical point
\begin{equation}

  \hat \beta_c= 1 \quad \text{under (equation finite-sum of the paper)} 
  \qquad \text{ and } \qquad  
  \hat \beta_c=z_a \quad \text{under (equation def:h of the paper)} .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] Let $M$ be admissible. Let $h,(h_{\ell})_{l\in\N}$ be as in Proposition \ref{prop: approxwick} and $0<\gamma<\sqrt{2n}$. Then
	for all $\varphi\in L^\infty(M)$ we have 
	\begin{align*}
		\sum_{\alpha=0}^\infty\frac{\gamma^\alpha}{\alpha!}\scalar{\wick{h^\alpha}}{\varphi}=\int_M \varphi(x)\, d\mu^{\gamma  h}(x),
	\end{align*}
	where the above sum converges in $L^2(\Omega)$.

