[Theorem thm:4.4 of arXiv:2608.27474, 'Nonlocality of Cover-Time Changes Under Edge Addition'] For every connected finite simple \(G\), genuine nonedge \(uv\), and
start \(s\),
\begin{equation}
\boxed{
\ell_s:=\lim_{\lambda\to\infty}
\frac{f_s(\lambda)-f_s(0)}{\lambda}
=\frac{2}{d_u+d_v}\,
\mathbb E_{\bar s}^{\bar G}L_w\ge0.
}

\end{equation}

Moreover:

\begin{enumerate}
\def\arabic{enumi}.{\arabic{enumi}.}
\tightlist
\item
  if \(s\in\{u,v\}\), then \(\ell_s>0\);
\item
  if \(s\notin\{u,v\}\), then \(\ell_s=0\) if and only if the underlying
  simple graph of \(\bar G\) is a path whose endpoints are \(s\) and
  \(w\);
\item
  in terms of the original simple graph, the zero case is exactly
\begin{equation}
  s=x_0-x_1-\cdots-x_L=c,
  \qquad cu,cv\in E,

  \end{equation}
with no other vertices or edges. Here \(L\ge0\) is the number of
  path edges; \(u,v\) are the two pendant leaves at \(c\).
\end{enumerate}

