[Lemma 41 (Schatten ideal facts) of arXiv:2607.10813, '2607.10813'] For $2\le r<\infty$ and $T\in\Sch_2\cap\mathcal L$,
\begin{equation}
 \|T\|_{\Sch_r}
 \le \|T\|_{\mathcal L}^{1-2/r}\|T\|_{\Sch_2}^{2/r}.
\end{equation}
If $A,B$ are bounded and $T\in\Sch_r$, then
\begin{equation}
 \|ATB\|_{\Sch_r}\le\|A\|\,\|T\|_{\Sch_r}\,\|B\|.
\end{equation}
Canonical regroupings of Hilbert tensor products are unitary, so a mere
reorientation of tensor legs preserves the Hilbert--Schmidt norm.

[Thm fixed K 't Hooft master loop equation for surface sum of arXiv:2508.13827, 'Surface sums in two-dimensional large-$N$ lattice Yang--Mills: Cancellations and explicit '] {borga2024surfacesumslatticeyangmills}}] 
	Fix a non-null-loop $\ell$ and a finite plaquette assignment  $K:\mathcal{P}\to\mathbb{Z}_{\geq 0}$. Let $\mathbf{e}$ be a specific edge of the loop $\ell$. Suppose that the  edge $\mathbf{e}$ is a copy of the lattice edge $e\in E_{\mathbb{Z}^2}$. Then
	\begin{align}
		\phi^K(\ell) =&\sum_{\{\ell_1,\ell_2\}\in \mathbb{S}_-(\mathbf{e},\ell)}
		\sum_{K_1+K_2=K}
		\phi^{K_1}(\ell_1)\phi^{K_2}(\ell_2) - \sum_{\{\ell_1,\ell_2\}\in \mathbb{S}_+(\mathbf{e},\ell)}
		\sum_{K_1+K_2=K}\phi^{K_1}(\ell_1)\phi^{K_2}(\ell_2) \notag\\
		&+ \upbeta
		\sum_{p\in \mathcal{P}(e^{-1},K)}
		\phi^{K\setminus p}(\ell \ominus_{\mathbf{e}}p)
		-\upbeta\sum_{q\in \mathcal{P}(e,K)}
		\phi^{K\setminus q}(\ell \oplus_{\mathbf{e}}q),
	\end{align}
	where $\mathcal{P}(e,K)$ denotes the collection of plaquettes in $\mathcal{P}$ containing $e$ as one of the four boundary edges (with the correct orientation) such that $K(p)\geq 1$, and $K\setminus p$ denotes the plaquette assignment $K'$ such that $K'(p)=K(p)-1$ and $K'(q)=K(q)$ for all $q\neq p$.

	We also used the (more compact) notation $\sum_{K_1+K_2=K}$ to indicate the sum $\sum_{\substack{K_1,K_2:\\K_1+K_2=K}}$, where $K_1+K_2=K$ means that $K_1(p) + K_2(p)=K(p)$ for all $p\in \mathcal{P}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 (\textit{Estimates I}) of arXiv:2607.21062, 'A new probabilistic approach for\\ mean field games of optimal stopping'] Suppose that Assumptions \ref{assumption:1A}, \ref{assumption:1B} and \ref{assumption: 1C} (or \ref{assumption:1A}, \ref{assum:Tarski_1}.i)-ii) and \ref{assum:Tarski_2}) hold. For every $i \in \{1, \dots, N\}$, let $\hat X^i$ be the solution of \eqref{N-player SDE} and let $\bar{X}^i$ be the solution of the following McKean--Vlasov stochastic differential equation:
\begin{equation}

\bar X_t^i=X_0^i+\int_0^tb\big(s,\bar X_s^i,\mathbb E\big[\bar b(s,\bar X_s^i)\hat L_s^i\big]\big)ds+\int_0^t\sigma\big(s,\bar X_s^i,\mathbb E\big[\bar\sigma(s,\bar X_s^i)\hat L_s^i\big]\big)dW_s^i,
\end{equation}
for all $0\leq t\leq T$. Then, there exists a constant $C\geq0$, independent of $(\hat L^1,\ldots,\hat L^N)$, $N$, $i$, such that, for every $i=1,\ldots,N$,
\[
\mathbb{E}\bigg[\sup_{0 \le t \le T}|\bar{X}^i_t-\hat X^i_t|^2\bigg]\le \frac{C}{N}\big(1+\mathbb E\big[|X_0|^{2}\big]\big).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 106 of arXiv:2601.16377, '2601.16377'] \cite[(2.2)]{Olsh_hyper}  Suppose $\,\text{Re}(\mathsf{z}_1 + \mathsf{z}_2 + \mathsf{w}_1 + \mathsf{w}_2 + 1) > 0$ and set
\begin{equation}

 \begin{split}
\Z^{zw}_{N} & = \prod_{1\leq i<j\leq N} \frac{\Gamma\big(\theta(j-i)+1\big) \cdot \Gamma\big(\theta(j-i)+\theta\big) }{\Gamma\big(\theta(j-i)\big)\cdot
 \Gamma\big(\theta(j-i)+1-\theta\big)} \\
 & \quad \times \prod_{i=1}^N \frac{\Gamma\big(\mathsf{z}_1+\mathsf{z}_2+\mathsf{w}_1+\mathsf{w}_2+(i-1)\theta+1\big)}{\Gamma\big((i-1)\theta+1\big) \prod_{k,\ell \in \{1,2\}} \Gamma\big(\mathsf{z}_k + \mathsf{w}_{\ell} +(i-1)\theta+1\big)}.
 \end{split}
 \end{equation}
 If the parameters are chosen so that this quantity does not vanish, then the measure \eqref{eq_zw_1} has mass $1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

