body:
[Corollary 4 of arXiv:2605.21005, 'Double-transform Tauberian method\\ for precise large deviations'] Let $(S_n,C_n)_{n\in\N_0}$ be as in Section~\ref{sec:leapGut}, with $Y_1=X_1+W_1$ defined in~\eqref{eq:GutDistr}. Then, for $( x_t)_{t\geq 0}$ such that $ x_t\to\infty $ and $t/ x_t^\beta\to 0$ as $t\to\infty$, we have
\begin{equation*}
\lim_{t\to\infty} \sup_{x\geq x_t}\left|\mu\Gamma(1-\beta)\ell(t) \frac{\P(C_{\tau(t)}>x)}{t\ell(x)x^{-\beta}}- 1 \right| =0.
\end{equation*}

[Proposition 3 of arXiv:2609.02801, 'Ratio and limiting zero distribution asymptotics for symmetric multiple orthogonal polynom'] Suppose $P_n(x)$ is a polynomial of degree $n$ satisfying \eqref{eq:1} with $\gamma_n>0$ 
and that \eqref{eq:asper} holds. If $\alpha=\max\limits_{k\in\mathbb{Z}_r}\{\alpha_k\}$, then 
the largest zero in absolute value $|x_{n,n}|$ of $P_n(x)$ satisfies
\begin{equation}
	|x_{n,n}| \leq  \left( 1 + \frac{1}{r}\right) \left( \alpha\  r \ n^{\gamma} \right)^{1/(r+1)}+ o(n^{\gamma/(r+1)}) \quad \text{as}\quad n\to+\infty.
\end{equation}

[Prop pr:exponential_decay_general of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] Let $u\in C([0, \infty); \mathcal{X})$ be a strong Markov process with state space $\mathcal{X}$ and natural filtration $\{\mathcal{F}_t\}_{t\in [0, \infty)}$\,. Let $T: C([0, \infty); \mathcal{X}) \rightarrow [0, \infty)$ be a stopping time satisfying the following properties. 
	\begin{enumerate}
	\item There exists some $t_0$ independent of $u[0]$ such that $\mathbb{P}(T < t_0) \leq \frac{1}{10}\, ;$
	\item There exist some Lyapunov functions $V, \Tilde V: \mathcal{X} \rightarrow [0, \infty)$ such that $\Tilde V \leq V$ and
	\begin{equs}

		\mathbb{E} V(u[T\wedge t_0]) &\leq \rho \Tilde V(u[0]) + C_1 \; , \\

		\sup_{a \leq t_0} \mathbb{E} \Tilde{V}(u[T\wedge a]) &\leq C_2 V(u[0]) + C_3\;,
	\end{equs}
	with constants $0 < \rho < 1$ and $C_1, C_2, C_3>0$.
	\end{enumerate}
	Then there exist constants $\gamma = \gamma(t_0, \rho, C_2), C= C(t_0, \rho) > 0$ such that for any $t \geq t_0$\,, we have
	\begin{equ}

		\mathbb{E} \Tilde{V}(u[t]) \leq C C_2 e^{-\gamma t} \Tilde V(u[0]) + C \big(\log C_2 + 1\big) C_1 C_2 + 2C_3\;.
	\end{equ} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:tail-integration of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] If $Y\geq0$, $T>0$, and $H>0$, then
\begin{equation}
 \mathbb{E}\min\!\left\{\log_{+}\frac{T}{Y},H\right\}
 =\int_0^H \mathbb{P}(Y\leq e^{-t}T)\,dt.
\end{equation}

[Lemma lem_flow_1 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Suppose that $H_{t_0}$ and $ \Lambda_{t_0}$ satisfy the assumptions (for $H$ and $\Lambda$) in (mix of the paper). Consider the characteristic flow in  (flow of the paper) with $z_{t_0}=E_{t_0}+\mathrm{i} \eta_{t_0} \in \bf D\left({\tau}\right)$, where \smash{$\eta_{t_0}\gtrsim N^{-1/3+\tau_e}$} for a constant $\tau_e>0$ and $t_c-t_0 \sim N^{-\varepsilon_g}$ for a constant $\varepsilon_g\in \pa{0,({1/8})\wedge ({\delta_A/4})}$. Define 
\[t_m:=\inf\ha{t\ge t_0: N\eta_t\im m\left({z_t}\right)\le N^{C_0\varepsilon_g}}\] 
for an absolute constant $C_0>6$. Then, for any $(z_1)_t, (z_2)_t\in \{z_t, \overline z_t\}$ and all $t\in [t_0,t_m]$, we have that
    \begin{equation}
        \begin{aligned}
            \left\|L_{(1,2), t}-K_{(1,2), t}\right\|_2 \prec \frac{\left(t_c-t_0\right)^2}{\left(t_c-t\right)^2}\left\|L_{(1,2), t_0}-K_{(1,2), t_0}\right\|_2+\frac{1}{N\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^2}.
        \end{aligned}
    \end{equation}
Combining this with (equation t_eta of the paper), (equation im_m_t_sim_through_evolution of the paper), and (equation largG_Ent of the paper), and applying the estimates (equation 1-M of the paper) and (equation 1-M-2 of the paper) below to bound \smash{$\|\p{1-\widehat M_{\left({1,2}\right)}}^{-1}\|$}, we obtain that for all $t\in\left[{t_0,t_m}\right]$,
    \begin{equation}
        \begin{aligned}
            \left\|L_{(1,2), t}-K_{(1,2), t}\right\|_2 \prec \frac{N^{\varepsilon_g}}{N\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^2}\ .
        \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 26 of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] There exists a constant $C$ independent of $n$, such that
\begin{align*}
n^2\int_0^T\left|(\E[Y_t^n]-r_t)^+\right|^2 dt\leq {C},\
n^2\int_0^T\left|(\E[Y_t^n]-l_t)^-\right|^2 dt\leq {C}.
\end{align*}

