body:
[Thm 35 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $(\mu_t)_{t\geq 0}\subset \mathcal{P}(\mathbb{R}^d)$ be a weakly continuous solution to the nonlinear Fokker-Planck equation \eqref{eq:NLFPshort} on $(0,\infty)$, such that $\mu_t:= u(t,x) dx,\; t\geq 0$ for a jointly measurable density
$u:[0,\infty)\times \mathbb{R}^d\rightarrow \mathbb{R}_+$.  
Furthermore, assume that the "linearized" conditions
\begin{equation*}
\mathbf{H_{a^u,b^u}^{\sqrt{u}}},\quad \mathbf{H_{\sf \lesssim u}}({\sf L}^u), \quad \mathbf{H^{\sf TV}_0}({\sf L}^u) \quad \mbox{ are fulfilled}.
\end{equation*}
Then there exists a set $E\in \mathcal{B}([0,\infty)\times \mathbb{R}^d)$ and a conservative right (hence strong Markov) process on $E$
\begin{equation*}
X=\left(\Omega,\mathcal{F},\mathcal{F}(t),X(t),\mathbb{P}_{s,x}, (s,x)\in E, t\geq 0\right), \quad \mbox{with transition function } (P_t)_{t\geq 0},
\end{equation*} 
such that the following assertions hold:
\begin{enumerate}
            \item[(i)] $\overline{\mu}([0,\infty)\times \mathbb{R}^d\setminus E)=0$ and $\mu_s\left(\left\{x\in \mathbb{R}^d, (s,x)\in E\right\}\right)=1$, $s\geq 0$.
            \item[(ii)] For $(s,x)\in E$ we have
            \begin{equation*}
                \mathbb{P}_{s,x}\left( [0,\infty)\ni t\mapsto X(t) \in E\subset [0,\infty)\times \mathbb{R}^d \mbox{ is continuous }  \right)=1.
            \end{equation*}
            \item[(iii)] If we set $X(t)=(X_1(t),X_2(t)), t\geq 0$, then for $(s,x)\in E$ we have
            \begin{equation*}
            \mathbb{P}_{s,x}\left( X_1(t)= t+s; 0\leq t<\infty  \right)=1.
            \end{equation*}
            \item[(iv)] The process $(X_2(t))_{t\geq 0}$ has the following properties:
            \begin{enumerate}
                \item[(iv.1)] For every $s,t\geq 0$
                \begin{equation*}
                \mathbb{P}_{s,\mu_s}\circ \left(X_2(t)\right)^{-1}=\mu_{t+s}.
                \end{equation*}
            \item[(iv.2)] Regarded on the filtered probability space $\left(\Omega, \mathcal{F},\mathcal{F}(t),\mathbb{P}_{0,\mu_0}\right)$, the process $(X_2(t))_{t\geq 0}$ is the unique weak solution to the McKean-Vlasov SDE \eqref{eq:MV SDE}, with initial condition $\mathcal{L}_{X_2(0)}=\mu_0$ and such that $\mathcal{L}_{X_2(t)}\leq c \mu_t, \;t\geq 0$ for some constant $c\in (0,\infty)$.
            \item[(iv.3)] Regarded on the filtered probability space $\left(\Omega, \mathcal{F},\mathcal{F}(t),\mathbb{P}_{0,\mu_0}\right)$ the process $(X_2(t))_{t\geq 0}$ is strong Markov, in the sense that for every finite $\mathcal{F}(t)$-stopping times $\tau$ we have that
            \begin{equation*}
                \mathbb{E}_{\delta_0\otimes \mu_0}\left\{ f(t+\tau,X_2(t+\tau)) \;\big|\;\mathcal{F}(\tau) \right\}=P_tf(\tau,X_2(\tau)),\quad t\geq 0, f\in b\mathcal{B}([0,\infty)\times \mathbb{R}^d).
            \end{equation*}
            \end{enumerate}
\end{enumerate}

[Lemma 12 of arXiv:2605.02713, '2605.02713'] Consider $f=f_n=\sum_{q=m}^p c_q  H_{q,n} =\sum_{q=m}^p c_q  H_q(\cdot;\mathrm{Var} (\cdot))$  for some fixed family $(c_q)$. Then
	\begin{itemize}
		\item[(i)] If $\sigma_n^2 \gg  (1 - \alpha_n^2) $, then $  \hat{S}_{n,t}(f_n) = c_p \hat{S}_{n,t}(H_p^{(n)})  + R_{n,t}(f_n)$,
		where $R_{n,t}(f_n) \longrightarrow_{L^2} 0$ for $n \to \infty$. Moreover, for any $t\in [0,1]$
		\begin{align*}
			\hat{S}_{n,t}(H_p^{(n)}) &= \frac{ \sum_{i=1}^{\lfloor nt \rfloor}   \big( \mathrm{Var} X_{1,n} \big)^{p/2}  H_{p}  \big( Z_{i,n} \big)}{\sqrt{\mathrm{Var}S_{n,1}(H_p^{(n)})}}  \quad\text{and}\\
			\mathrm{Var} S_{n,t}(H_p^{(n)}) &=  \left( \mathrm{Var} X_{1,n} \right)^{p}  p! \, \Lambda_{p}(n,t). 
		\end{align*}
		\item[(ii)] If $\sigma_n^2 = \sigma^2 (1 - \alpha_n^2) $, then for any $t\in [0,1]$
		\begin{align*}
			\mathrm{Var} S_{n,t}(f_n) = \mathrm{Var} S_{n,t}(f) = \sum_{q=m}^p  c_q^2 q!  \left(   \sigma^2  \right)^q \Lambda_{q}(n,t) .
		\end{align*}  
		\item[(iii)] If $\sigma_n^2 \ll  (1 - \alpha_n^2) $, then 
		$  \hat{S}_{n,t}(f_n) = c_m \hat{S}_{n,t}(H_{m,n})  + R_{n,t}(f_n)$,
		where $R_{n,t}(f_n) \longrightarrow_{L^2} 0$ for $n \to \infty$. Moreover, for any $t\in [0,1]$
		\begin{align*}
			\hat{S}_{n,t}(H_{m,n}) &= \frac{ \sum_{i=1}^{\lfloor nt \rfloor}   \big( \mathrm{Var} X_{1,n} \big)^{m/2}  H_{m}  \big( Z_{i,n} \big)}{\sqrt{\mathrm{Var}S_{n,1}(H_{m,n})}}  \quad\text{and}\\
			\mathrm{Var} S_{n,t}(H_{m,n}) &=  \left( \mathrm{Var} X_{1,n} \right)^{m}  m! \, \Lambda_{m}(n,t). 
		\end{align*}
	\end{itemize}

[Lemma PZ of arXiv:2505.13382, 'The localization transition for the directed polymer in a random environment is smooth'] Given $Z$ a nonnegative random variable with mean one and $p>1$ we have
\begin{equation}
 {\ensuremath{\mathbb P}} \left[Z \ge \theta\right] \ge  (1-\theta)^\frac{p}{p-1}{\ensuremath{\mathbb E}} \left[ Z^p\right]^{-\frac{1}{p-1}}.
\end{equation}

[Theorem 1 of arXiv:2609.02175, '2609.02175'] Let $V_1,V_2\in C_c^\infty(\mathbb R^n)$, $n\geq3$, and let
	$\lambda>0$ satisfy
	\begin{equation}
		\lambda>\sup_{\mathbb R^n}V_j,
		\qquad j=1,2.
	\end{equation}
Assume moreover the virial condition
\begin{equation}
	2(\lambda-V_j(x))-x\cdot\nabla V_j(x)>0,
	\qquad x\in\mathbb R^n,
	\qquad j=1,2.
\end{equation}
	If
	\begin{equation}
		\|S_1(\lambda,h)-S_2(\lambda,h)\|_
		{\mathcal B(L^2(\mathbb S^{n-1}))}
		=
		o(1),
		\qquad h\to0,
	\end{equation}
	then
	\begin{equation}
		V_1=V_2.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma range_estimates_main_text of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Consider a random walk on $\mathbb Z^d$ driven by $Q$. Let $D \subseteq H(r)$ with $|D|/|H(r)| \leq 3/4$. Define $\widetilde{\mathrm{R}}(k) := \mathrm{R}(k) \cap (H(r) \setminus D)$. Then, there exist positive constants $c_0, c_1$ depending on $Q$ such that for any $r \in \mathbb N^+$ and any $x \in H(r)$:
    \begin{align} 
        \mathbf P_x \left( \, \left|\widetilde{\mathrm{R}}\left(\ell(r)\right) \right| \geq c_1 f(r) \right) \geq c_0,
    \end{align}
    where $f(r)$ is defined as follows with $\ell(r)$ defined in (equation def: s(r) of the paper):
    \begin{align*}
        f(r) := \begin{cases}
            \ell(r) & \text{if } d \ge 3 \text{ or } (d = 2 \text{ and } \alpha < 2), \\
            \ell(r) / \log \log \ell(r) & \text{if } d = 2 \text{ and } \alpha = 2, \\
            \ell(r) / \log \ell(r) & \text{if } d = 2 \text{ and } \alpha > 2.
        \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

