[Lemma p:ssmsingle-wsm of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] If  the function \(\mathcal{A}'_{\Psi({\cal X })}\) satisfies
~(equation ssmsingle of the paper)  for all singletons  \( {\cal X }'' = \{x\}  \subset {\cal X } \)
then the following inequality  holds
for any configuration of sets \( {\cal X }'', {\cal Z} \subset {\cal X } \)  such that ${\cal Z} \cap {\cal X }'' = \emptyset$,

\begin{equation} 
d_{\textnormal{TV}} \left( \mathcal{L}(V_{{\cal X }''} \mid V_{{\cal Z}} = \v_{{\cal Z}}),
\mathcal{L}(V_{{\cal X }''} \mid V_{{\cal Z}} = {z}_{{\cal Z}}) \right) \leq 
\sum_{y\in{\cal X }''} \mathcal{A}'(\{y\},{\cal Z}_{\neq}).
\end{equation}

[Defn Neutrality condition of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] A double divisor $\left(\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right)$ satisfies the neutrality condition  if 
\begin{equation}
\int\boldsymbol{\sigma}=\int \boldsymbol{\sigma}^{+}+ \int \boldsymbol{\sigma}^{-}=-2.
\end{equation}

[Prop 11 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta \subseteq \mathbb{R}^d \times \mathbb{S}_+^d \times \mathcal{L}$ be closed, convex, and satisfy Assumptions \ref{B} and \ref{J}. Moreover, let $\ell$ satisfy Assumption~\ref{ellcontinuous}. Then the function 
\begin{equation*}
H: [0,1]\times\mathbb{R}^d\times\mathbb{R}^d\times\mathbb{S}_{+}^{d}\times C_b^2(\mathbb{R}^d) \to \mathbb{R}
\end{equation*} 
is continuous.

[Definition def1 of arXiv:2411.02030, 'Finite ergodic components for upper probabilities'] A measurable partition $\alpha$ of $\Omega$ is said to be a finite irreducible invariant set partition (with respect to $P$ and $T$) if $\#(\alpha)<\infty$ and  for any $A\in \alpha$, 
	\begin{enumerate}
		\item [(i)]$P(A)>0$;
		\item [(ii)]$A\in\mathcal{I}$;
		\item [(iii)] none of $T$-invariant sets $B\subset A$ with $0<P(B)<P(A)$. 
	\end{enumerate}
In this case,	we call  $(\Omega,\mathcal{F},P)$   satisfies the finite irreducible invariant set partition assumption.

[Thm 4 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] Assume that $\varphi:\R\mapsto \R_+$ vanishes on $(-\infty,0)$, satisfies \eqref{e:critical} and 
 \begin{equation}

m_\varphi:=\int_0^\infty x\varphi(x)dx<\infty.
  \end{equation}
Moreover, assume that the number of offspring of a single particle has finite variance denoted by $\sigma_G^2$ and let 
\begin{equation}
 F_T=T^2
\end{equation}
Then
 the process $Y_T$ given by
 \eqref{e:YT} converges in the sense of finite dimensional distributions and in law in $D([0,\infty))$ equipped with $M_1$ topology to a nonnegative process $Y^*_\infty=(Y^*_\infty(t))_{t\ge 0}$ whose finite dimensional distributions are
 such that for any $m\in \N$, $\theta_1, \ldots, \theta_k\ge 0$ and $t_1,\ldots, t_m\ge 0$ we have 
 \begin{equation}
  E \exp\{-\sum_{k=1}^m\theta_kY^*_{\infty}(t_k)\}=\exp\{-\mu\int_0^\infty v_f^*(t)dt\},

 \end{equation}
where $v_f^*$ is a unique nonnegative bounded function with compact support satisfying the equation
\begin{equation}
v_f^*(t)=\frac 1{m_\varphi}\int_0^\infty \left(f(t+s)-\frac{\sigma_G^2}2 (v_f^*(t+s))^2\right) ds,

 \end{equation}
where $f$ is given by \eqref{e:f_funct_thm}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] For any $E\subseteq K$, let
    \begin{equation*}
        \begin{aligned}
        b(E)
        := \sup\{\nu(E)\colon \nu\in\mathcal{M}_b(K),\|R_{1/2,1}(\mathbf{1}_E\nu)\|_{L^2}\leq 1\}.
        \end{aligned}
    \end{equation*}
Then, for every open set $A\subset K$ it holds that
    \begin{equation}
    \mathrm{cap}(A)= b(A)^2.
    \end{equation}

