[Theorem thm:ik-completeness-detailed of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] \begin{equation*}
    \textbf{IK} = \set{ \varphi \in \mathscr{L}_{\Box\Diamond}; \forall \mathfrak{F} \in \FrameClass{\Diamond\text{-p}} \cap \mathscr{F}_{FS2}\,(\mathfrak{F} \vDash^{\text{h}} \varphi) }.
  \end{equation*}
  \begin{proof}
    ($\subseteq$) It suffices to show that $\textsf{FS2}$ is h-valid on any $\Diamond$-p and FS2 frame,
    which is already proven in Proposition (prop:ik-model-validates-cdia-and-fs2 of the paper).

    ($\supseteq$) By Proposition (prop:canonical-model-is-dia-p of the paper) and Truth lemma,
    it suffices to show that $\mathfrak{M}_{\textbf{IK}}^*$ satisfies the FS2 condition.
    Take any $x = (\Gamma_x, \Delta_x)$, $y = (\Gamma_y, \Delta_y)$, and $y' = (\Gamma_y', \Delta_y')$ such that $x \sqsubset^* y \leq^* y'$,
    then $\Box^{-1} \Gamma_x \subseteq \Gamma_y \subseteq \Gamma_y'$
    and $\Diamond^{-1} \Delta_x \subseteq \Delta_y$ by definition.
    \begin{claim*}
      $(\Gamma_x \cup \Diamond \Gamma_y', \Box \Delta_y')$ is $\textbf{IK}$-consistent.
      \begin{subproof}
        Suppose not, then there are finite $A \subseteq \Gamma_x$,
        $B \subseteq \Gamma_y'$,
        and $C \subseteq \Delta_y'$
        such that $\textbf{IK} \vdash \left(\bigwedge A \land \bigwedge \Diamond B \right) \to \bigvee \Box C$, then:
        \begin{center}
          \AxiomC{$\left(\bigwedge A \land \bigwedge \Diamond B \right) \to \bigvee \Box C$}
          \RightLabel{\scriptsize{$\textsf{M}_\Box$, $\textsf{M}_\Diamond$}}
          \UnaryInfC{$\left(\bigwedge A \land \Diamond \bigwedge B \right) \to \Box \bigvee C$}
          \UnaryInfC{$\bigwedge A \to \left(\Diamond \bigwedge B \to \Box \bigvee C \right)$}
          \RightLabel{\scriptsize{$\textsf{FS2}$}}
          \UnaryInfC{$\bigwedge A \to \Box \left(\bigwedge B \to \bigvee C \right)$}
          \DisplayProof
        \end{center}
        Then $\Box \left(\bigwedge B \to \bigvee C\right) \in \Gamma_x$ by $\textbf{IK}$-consistency,
        so $\left(\bigwedge B \to \bigvee C\right) \in \Gamma_y'$ by $\Box^{-1} \Gamma_x \subseteq \Gamma_y'$.
        Here, $\bigwedge B \in \Gamma_y'$ by $B \subseteq \Gamma_y'$,
        then $\bigvee C \in \Gamma_y'$ by the above,
        so there is at least one $\psi \in C$ such that $\psi \in \Gamma_y'$,
        which is a contradiction since $C \subseteq \Delta_y'$.
      \end{subproof}
    \end{claim*}
    Now that $(\Gamma_x \cup \Diamond \Gamma_y', \Box \Delta_y')$ is $\textbf{IK}$-consistent,
    then by Lindenbaum lemma, there is $x' = (\Gamma_x', \Delta_x') \in W_{\textbf{IK}}^*$ such that
    $\Gamma_x \cup \Diamond \Gamma_y' \subseteq \Gamma_x'$ and $\Box \Delta_y' \subseteq \Delta_x'$.
    It is clear that $x \leq^* x'$, so it remains to show that $x' \sqsubset^* y'$.
    Take any $\Box \psi \in \Gamma_x'$, then $\Box \psi \notin \Delta_x'$,
    then $\Box \psi \notin \Box \Delta_y'$, then $\psi \notin \Delta_y'$, so $\psi \in \Gamma_y'$.
    Now take any $\Diamond \varphi \in \Delta_x'$, then $\Diamond \varphi \notin \Gamma_x'$,
    then $\Diamond \varphi \notin \Diamond \Gamma_y'$, then $\varphi \notin \Gamma_y'$, so $\varphi \in \Delta_y'$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:condition reduction lebesgue of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $f:\R^d\to [0,\infty)$ is measurable, and define $\Psi_f$ by
    \begin{equation}
        \Psi_f(dy) := \bigg(\int f(x)\, |K^\ast|(y, dx)\bigg)\, |\Phi|(dy),\quad y\in\R^d.
    \end{equation}
    Then 
    \begin{equation}
        \BE\bigg[\bigg(\int f(x)\, |\tilde{K}_0|(dx)\bigg)^2\bigg] < \infty
    \end{equation}
    if $\Psi$ is locally absolutely square-integrable. The converse is true if $K$ and $\Phi$ are nonnegative, as then
    \begin{equation}
        \Psi_f(B_1) = \kappa_d\int f(x) \tilde{K}_0(dx).
    \end{equation}
    Moreover, the following statements hold.
    \begin{enumerate}[label=(\roman*)]
        \item If Condition~(c:condition square-integrable general with p of the paper) holds with respect to $p\in[-d, \infty)$ and a strongly log-dominating function $\rho$, then
        \begin{equation}
            \BE\bigg[\bigg(\int \sqrt{\|x\|^{d+\max(p,0)}\rho(\|x\|)+1}\, |\tilde{K}_0|(dx)\bigg)^2\bigg] < \infty.
        \end{equation}
        \item If Condition~(c:condition square-integrable Markov with p of the paper) holds with respect to $p\in[-d, \infty)$, then
        \begin{equation}
            \BE\bigg[\bigg(\int \sqrt{\|x\|^{d+\max(p,0)}+1}\, |\tilde{K}_0|(dx)\bigg)^2\bigg] < \infty.
        \end{equation}
        \item If Condition~(c:condition square-integrable stealthy of the paper) holds with respect to $\varepsilon>0$, then
        \begin{equation}
            \BE\bigg[\bigg(\int e^{\varepsilon\|x\|}\, |\tilde{K}_0|(dx)\bigg)^2\bigg] < \infty.
        \end{equation}
    \end{enumerate}
    \begin{proof}
        Let $f:\R^d\to[0,\infty)$ be measurable. By construction, we have $|\tilde{K}_0|\leq |K||L_0|= \kappa_d^{-1}|K||\I_{B_1}\cdot\Phi|$. Therefore,
        \begin{equation*}
            \int f(x) |\tilde{K}_0|(dx) \leq \kappa_d^{-1}\int_{B_1}\int f(x) |K|(y, dx)\, |\Phi|(dy) = \kappa_d^{-1} \Psi_f(B_1).
        \end{equation*}
        The inequality becomes an equality if $K$ and $\Phi$ are nonnegative. The remaining assertions follow with an appropriate choice of $f$.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 40 (Asymptotics strictly inside the dotted pink region) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose that $x^* \in (0, \M)$. Let $z_0 \in \R^2$ and $\alpha_0 \in [0,\alpha^*_+)$. Then: 
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha_0, \alpha > 0}{\sim} C^+_{*}f_{*}(z_0) e^{-r(\cos(\alpha)x^* + \sin(\alpha)Y^+(x^*))}
\end{equation}
where \begin{equation}
    f_{*}(a_0,b_0) = \begin{cases}
e^{x^*a_0 + Y^-(x^*)b_0} & \text{if } b_0 \geq 0 \\
e^{x^*a_0 + Z^+(x^*)b_0} & \text{if } b_0 < 0.
\end{cases}
\end{equation}
and 
\begin{equation}
    C^+_{*} = \frac{\gamma(x^*,Y^+(x^*),Z^+(x^*))}{\partial_y\gamma_+(x^*,Y^+(x^*))\frac{d}{dx}\gamma(x,Y^-(x), Z^+(x))\big|_{x=x^*}}.
\end{equation}
The symmetric result holds for angles $\alpha_0 \in (\alpha^*_-, 2\pi].$

[Theorem 4 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] Let $b_n$ and $c_n$ be given by \eqref{bt}--\eqref{bc}.
Then
\begin{align}

  \lim_{n\to\infty}d_{\rm  TV}(M_n-b_n,Z_n)=0
\end{align}
with
\begin{equation}
Z_n: =\lceil \xi_1 + (e-1)\tau+c_n\rceil,
\end{equation}
where $\xi_1$ is standard Gumbel-distributed and independent of
$\tau\stackrel{\rm d}{=}{\rm Gumbel}(\ell+1)$ given by \eqref{ell-Gum}. (Proof in the paper; no proof environment follows the statement in the TeX.)

