[Proposition P:sojourn:LD of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] There exist constants $\varepsilon_0\in(0,1)$ and $K_1, K_2\in(0,\infty)$ such that
\begin{align}
{\mathbb P}\{ T_\varepsilon \ge u\varepsilon^d \Psi(\varepsilon) \} \ge \tfrac14 e^{-K_1 u}
\end{align}
for all $\varepsilon \in (0, \varepsilon_0)$ and $1 \le u \le K_2 \log\log\log(1/\varepsilon)$.

[Proposition 75 (Evaluated tail--defect stability below the Hilbert endpoint) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $1\le r<2$, put $\theta_r:=1/r-1/2$, and retain the block
projections and effective ranks $d_{\lambda,\mu}$ from
Theorem~\ref{thm:below-Hilbert}.  Let
$K_{N;\lambda,\mu}\in
 \mathfrak W_{m,2}(\cH_{\R};Q_\mu\cC,P_\lambda\cE)$ be realized over
one common isonormal Gaussian process.  Suppose that there is
$M=(M_{\lambda,\mu})\in\ell^r(\Lambda\times\cM)$ such that
\begin{equation}

 d_{\lambda,\mu}^{\theta_r}
 \Prof_{m,2}(K_{N;\lambda,\mu})\le M_{\lambda,\mu}
 \qquad(N\ge1).
\end{equation}
Let $(F_R)_{R\ge1}$ be an increasing finite exhaustion of
$\Lambda\times\cM$, and assume that $\delta(N)\to0$ and
\begin{equation}

 \left\{\sum_{(\lambda,\mu)\in F_R}
 \left[d_{\lambda,\mu}^{\theta_r}
 \Prof_{m,2}(K_{N;\lambda,\mu}-K_{N';\lambda,\mu})\right]^r
 \right\}^{1/r}
 \le \delta(N)G(R),
 \qquad N'\ge N.
\end{equation}
Set
\[
 \tau_r(R):=
 \norm{M\mathbf1_{(\Lambda\times\cM)\setminus F_R}}_{\ell^r}.
\]
Then the evaluated reconstructions
\[
 T_N:=\sum_{\lambda,\mu}I_m(K_{N;\lambda,\mu})
\]
are Cauchy in $L^p(\Omega;\Sch_r)$ for every $1\le p<\infty$, and,
with $p_*:=\max\{p,r\}$,
\begin{equation}

 \norm{T_N-T_{N'}}_{L^p(\Omega;\Sch_r)}
 \le A_m(p_*+2)^{m/2}
 \inf_{R\ge1}\{\delta(N)G(R)+2\tau_r(R)\},
 \qquad N'\ge N.
\end{equation}
The same estimate holds for the limit $T$ in place of $T_{N'}$.
If, for some $\theta_0,\sigma>0$ and $A\ge0$,
\[
 \delta(N)\lesssim N^{-\theta_0},\qquad
 G(R)\lesssim R^A,
\]
then
\begin{align}
 \tau_r(R)\lesssim R^{-\sigma}
 &\quad\Longrightarrow\quad
 \norm{T_N-T}_{L^p(\Omega;\Sch_r)}
 \lesssim (p_*+2)^{m/2}
 N^{-\theta_0\sigma/(A+\sigma)},
 \\
 \tau_r(R)\lesssim \ell_R^{-\sigma}
 &\quad\Longrightarrow\quad
 \norm{T_N-T}_{L^p(\Omega;\Sch_r)}
 \lesssim (p_*+2)^{m/2}\ell_N^{-\sigma}.

\end{align}
The conclusions remain valid for fixed finite-overlap colorings, with
the right-hand sides multiplied by
$(\chi_+\chi_-)^{1-1/r}$.

[Theorem th:analytic of arXiv:2508.21055, 'Modern aspects of Markov chains:\\entropy, curvature and the cutoff phenomenon'] For each $\kappa\ge 0$, the exponential decay ((generic:decay of the paper)) is equivalent to the static criterion
\begin{eqnarray}

\forall f\in{\mathcal {F}_1^{++}},\qquad \mathscr {E}(f,\nabla\Phi(f)) & \ge &\kappa\Phi(f).
\end{eqnarray}
Moreover, when this holds, we have the mixing-time estimate
\begin{eqnarray*}
\forall\varepsilon\in(0,1),\quad {\rm t}_{\textsc{mix}}(\varepsilon) & \le & \frac{1}{\kappa}\log\frac{\Delta}{\delta(\varepsilon)},
\end{eqnarray*}
where we have introduced the quantities
\begin{eqnarray*}
\Delta\ :=\ \max_{x\in\mathbb{X}}\Phi\left(f^x\right), &  & \delta(\varepsilon) \ := \ \min\left\{\Phi\left(\frac{\,\mathrm{d} \mu}{\,\mathrm{d} \pi} \right)\colon \mu\in\mathcal{P}(\mathbb{X}),{\rm d}_{\textsc{tv}}(\mu,\pi)\ge \varepsilon\right\}.
\end{eqnarray*}

