[Lemma lem:Nash of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] For $f\in W^1_2(\mathbf S_N)\cap L^1(\mathbf S_N)$, we have
    \begin{align*}
        \frac{N(q-2)}{N-1} \left\lVert\nabla f\right\rVert_2^2+\left\lVertf\right\rVert_2^2\geq \left\lVertf\right\rVert_q^2\geq \left\lVertf\right\rVert_2^{\frac{2N+2}{N-1}}\left\lVertf\right\rVert_1^{-\frac{4}{N-1}}\,.
    \end{align*}
    Equivalently
    \begin{align*}
        \left\lVert\nabla f\right\rVert_2^2\geq &\,\frac{N-1}{N(q-2)}\Big(-\left\lVertf\right\rVert_2^2+\left\lVertf\right\rVert_2^{\frac{2N+2}{N-1}}\left\lVertf\right\rVert_1^{-\frac{4}{N-1}}\Big)\nonumber\\
        >&\,c_2N\Big(-\left\lVertf\right\rVert_2^2+\left\lVertf\right\rVert_2^{\frac{2N+2}{N-1}}\left\lVertf\right\rVert_1^{-\frac{4}{N-1}}\Big)\,,
    \end{align*}
    for $c_2$ a constant independent of $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

