body:
[Theorem 1 of arXiv:2604.16002, 'Normal approximation for iterated inner functions'] Let $f$ be an inner function with $f(0)=0$ which is not a rotation. Let $(a_n)_{n=1}^\infty$ be a sequence of complex numbers satisfying
	\begin{align}\sum_{n=1}^\infty |a_n|^2 = \infty,\quad \text{and} \quad \lim_{N\to \infty} \frac{|a_N|^2}{\sum_{n=1}^N |a_n|^2} = 0,
	\end{align} 
	and set $$Z_N:= \frac{1}{\sigma_N}\sum_{n=1}^N a_n f^{\circ n},\quad \text{and }\,\, \sigma_N:= \bigg\| \sum_{n=1}^N a_n f^{\circ n }\bigg\|_{L^2(\T)}.$$ Then for any $\delta\geq 1$, there exist positive constants $C(\delta,f)$ (depending only on $\delta$ and $f$), such that the following Cram\'er-Wold error estimate holds: 
		\begin{equation}
			\begin{split}
		&\sup_{x\in \R,\, \alpha \in \T} \bigg| \PP\Big( {\rm Re}\, \big( \alpha Z_N\big) \leq x \Big) - \PP\Big( \cal{N}(0,1/2) \leq x \Big)\bigg|  \\ 
		& \,\leq \,C(\delta,f) \cdot \bigg(\sum_{n=1}^N |a_n|^{4} \bigg)^{\frac{1+\delta}{6+4\delta}}  \bigg(\sum_{n=1}^N |a_n|^{2} \bigg)^{-\frac{1+\delta}{3+2\delta}} + 2.7 \cdot \frac{|\lambda|}{1-|\lambda|} \frac{\big|\sum_{n=1}^N \lambda^{N-n} a_n\big|}{\sqrt{\sum_{n=1}^N |a_n|^2}}.
			\end{split}
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_mu_stir_pi_alpha of arXiv:2412.09532, 'Percolation on the stationary distributions of the voter model with stirring'] Let~$\Lambda \subset \mathbb{Z}^d$ be finite and~$E,F \in \mathcal G_\Lambda$ be an increasing and a decreasing event, respectively. In the space of the graphical construction, we consider an~$\mathcal F_t$-measurable random configuration~$\eta \in \{0,1\}^\Lambda$ with the property that the coalescing random walks started at~$\{x \in \Lambda: \eta(x) = 0\}$ do not coalesce until time~$t$. Then for any~$\alpha \in (0,1)$ and~$\mathsf v \ge 0$
    \begin{align*}
        & \mu_{\alpha,\mathsf v}(E) \leq \mathbb{E} \Big[ \pi_\alpha(\zeta: \zeta \vee \eta \in E) \cdot \prod_{ \substack{ x,y \in \Lambda \setminus \Xi \\ x< y} } \big( 1+ h(Y^x_t,Y^y_t) \cdot (\widehat{\alpha}^{-2}-1) \big) \Big], \\[0.2cm]
        & \mu_{\alpha,\mathsf v}(F) \leq \mathbb{E} \Big[ \pi_\alpha(\zeta: \zeta \wedge (1-\eta) \in F) \cdot \prod_{ \substack{ x,y \in \Lambda \setminus \Xi \\ x< y} } \big( 1+ h(Y^x_t,Y^y_t) \cdot (\widehat{\alpha}^{-2}-1) \big) \Big].
    \end{align*}
    where~$\Xi = \Xi(\eta) = \{x \in \Lambda : \eta(x) = 1 \}$.

[Proposition 23 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Equation \eqref{eq:path-dep-inhom-heston-vol} possesses a $[0,\infty)$-valued continuous weak solution $V$.
    Furthermore,
    \begin{equation}
        S(t) = S(0)e^{\int_{0}^{t} \eta(s)\sqrt{V(s)}\bigl(\sqrt{1-\rho^2}dW_1(s) + \rho dW_2(s)\bigr) - \int_{0}^{t} \tfrac{\eta(s)^2V(s)}{2} ds}, \quad t \in [0,T],
    \end{equation}
    is a solution of \eqref{eq:path-dep-inhom-heston-spot-price}, and $S$ is a martingale.

