[Lemma of arXiv:2412.04032, 'Cutoff for the mixing time of the Facilitated Exclusion Process'] For all $0<\varepsilon<1$, there exist $C_{\varepsilon}>0$ and $s=s_\varepsilon >0 $ such that for $N$ large enough, 
for all $t \le \frac{K^2}{8\pi^2} \log P - C_\varepsilon K^2$, 
\eq{eq:piA1}{\pi_{N,K}^\textsc{fep}(A_s) \le \varepsilon'}
\eq{eq:2eps1}{\mathbb{P}_{\bar{\eta}}(\bar{\eta}(t) \in A_s) > \varepsilon+\varepsilon',}
where $\varepsilon' = \min(\varepsilon, \frac{1-\varepsilon}{2})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 9 of arXiv:2608.15379, 'Stochastic Jacobi fields along discontinuous martingales on Riemannian submanifolds'] Let $\bJ=(X,J)$ be a $TM$-valued semimartingale. Then the following are equivalent:
\begin{itemize}
\item[(i)]$\bJ$ is a $\gamma^{\bcl}$-martingale;
\item[(ii)]$X$ is a $\gamma$-martingale and for any $\cX \in \mathfrak{X}(M)$,
\begin{align*}
&\int \langle \cX(X_-), dJ \rangle_{\delta_{\mathbb{R}^d}} + \frac{1}{2}\int \langle \II(\cX(X_-),\bJ_-),\II(dX^c,dX^c)\rangle_{\delta_{\mathbb{R}^d}}\\
&+\sum_{0<s\leq \cdot} \langle \II( \cX(X_-) ,\bJ_{s-}), \gamma^{\perp}(X_-,X) \rangle_{\delta_{\mathbb{R}^d}}
\end{align*}
is a local martingale.
\item[(iii)]$X$ is a $\gamma$-martingale and for any $\cX \in \mathfrak{X}(M)$, $\int \lambda_{g^{\bcl}}(\cX^{\bcl}(\bJ_-))\, d^{\gamma^{\bcl}}\bJ_s$ is a local martingale.
\end{itemize}

