[Corollary 17 (Gaussian limit) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] Assume $0<a,b<1$ are fixed and $L\to\infty$.  Then
\begin{equation}
        \frac{B-\dfrac{2La}{1-a^2}}
        {\sqrt{\dfrac{2La(1+a^2)}{(1-a^2)^2}}}
        \Longrightarrow N(0,1),
\end{equation}
\begin{equation}
        \frac{R-\dfrac{2Lb}{1-b^2}}
        {\sqrt{\dfrac{2Lb(1+b^2)}{(1-b^2)^2}}}
        \Longrightarrow N(0,1),
\end{equation}
and the two limiting normal random variables are independent.

[Proposition 50 (Cyclotomic valuations) of arXiv:2608.29585, '2608.29585'] Let $M=\lfloor k/\ell_d\rfloor$.  The diagonal Newton factor
\begin{equation}
 C_{k+1,k}^{(n)}
 =\prod_{i=0}^{k-1}\{k-i\}\{k+n+i\}
 =\{k\}!\prod_{m=n+k}^{n+2k-1}\{m\}
\end{equation}
satisfies
\begin{equation}
 \val_{\Phi_d}\!\left(C_{k+1,k}^{(n)}\right)
 =\left\lfloor\frac{k}{\ell_d}\right\rfloor
 +\left\lfloor\frac{n+2k-1}{\ell_d}\right\rfloor
 -\left\lfloor\frac{n+k-1}{\ell_d}\right\rfloor.
\end{equation}
The full Vandermonde factor has valuation
\begin{align}
 \val_{\Phi_d}(V_k^{(n)})
 &=M(k+1)-\ell_d\frac{M(M+1)}2
 \notag\\
 &\quad+
 \frac12\left(
  \sum_{a\in\Z/\ell_d\Z}c_ac_{-n-a}
  -\sum_{\substack{a\in\Z/\ell_d\Z\\
                       2a\equiv-n\pmod{\ell_d}}}c_a
 \right).

\end{align}

[Theorem thm:4.1 of arXiv:2608.27474, 'Nonlocality of Cover-Time Changes Under Edge Addition'] Let \(H_s^\lambda(S)\) be the \(G_\lambda\) hitting time of \(S\). Then

\begin{equation}
\boxed{
H_s^\lambda(S)-H_s^0(S)
=\frac{\lambda(A_S+\lambda B_S)}{1+\lambda\rho_S}.
}

\end{equation}
If \(b_B=0\), the response is zero.

[Lemma 23 of arXiv:2608.26693, '2608.26693'] For every $L<\infty$ there exists $C_L<\infty$ such that, for all $\tau\ge1$,
\begin{equation}
\sup_{0\le x\le L}
\bigl|f_\tau(x)-f_\infty(x)\bigr|
\le \frac{C_L}{\tau}.
\end{equation}

[Theorem 6 of arXiv:2605.12269, 'It\^o integral for a two-sided L\'evy process'] Let $p \geq 2$ be an even integer such that $m_p<\infty$. For any $X \in \cL_p^*$,
\begin{equation}

\|I(X)\|_p \leq \cC_p \big[ X\big]_{p}.
\end{equation}

