[Corollary cor: path-red of arXiv:2604.08462, 'Convergence of $k$-point functions in\\ high dimensional percolation'] Suppose $|w_1|, \, |w_2|, \, |w_3| \le \epsilon^{-1} n$ and $|w_i-w_j|\ge\epsilon n$ for $i\neq j$. Then, for $u,v\in \mathbb{Z}^d$, we have
\begin{equation}
\begin{split}
&\langle u-w_2\rangle^{-d+2}\langle v-w_3\rangle^{-d+2} \sum_{w\in \mathbb{Z}^d}\langle w-u\rangle^{-d+2}\langle w-v\rangle^{-d+2}\langle w-w_1\rangle^{-d+2}\\
\le &~Cn^{4-d}(\langle u-w_1\rangle^{-d+2}+\langle u-w_2\rangle^{-d+2})(\langle v-w_3\rangle^{-d+2}+\langle v-w_1\rangle^{-d+2}) \langle u -v \rangle^{-d+2}.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor downexc of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] For $k \in \mathbb{N}$ and $p \in (0,1)$ let $W^*_{1/2}$ and $W^*_p$ both start in $0$. Then, with $\tau_k$ defined in~(equation deftauk of the paper),
\begin{align*}
  \max_{1\le k \le N} \max_{\tau_{k}(W_p^*)\le n < \tau_{k+1}(W_p^*)}
    & \big(\log_N(k)- \log_N(W_p^*(n)\big)
  \quad \mbox{ is stochastically not larger than }\\
  \max_{1\le k \le N} \max_{\tau_{k}(W_{1/2}^*)\le n < \tau_{k+1}(W_{1/2}^*)}
    & \big(\log_N(k)- \log_N(W_{1/2}^*(n)\big). 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: tight bound on P(q_infty = 0) of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Tight Gaussian Tail Bound on $\mathbb{P}(q = 0)$)}
    For SSQ, under assumption (ass:heavy_overload of the paper), the probability of empty queue at equilibrium $\mathbb{P}(q = 0)$ is bounded in
    \begin{align*}
        \mathbb{P}(q = 0) &\leq C_{\lambda,\mu}' \sqrt{\gamma/\mu} \exp(-\frac{1}{\gamma/\mu} (\lambda/\mu - 1 - \ln (\lambda/\mu))) \\
        \mathbb{P}(q = 0) &\geq D_{\lambda,\mu}' \sqrt{\gamma/\mu} \exp(-\frac{1}{\gamma/\mu} (\lambda/\mu - 1 - \ln (\lambda/\mu))) 
    \end{align*}
    Where $C_{\lambda,\mu}'$ and $D_{\lambda,\mu}'$ are constants $C_{\lambda,\mu}' =  \lambda/\mu(e\vee \frac{(1+C)(2+C)}{C^2+C-1}), D_{\lambda,\mu}' = \frac{\sqrt{\mu}}{(2\sqrt{\mu} + \sqrt{2\pi e^2 \lambda})}$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop PropEntireEvolGL of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $\theta\in \mathbb{R}$ and suppose $\mathfrak{gl}_{0;N} \overset{N \to \infty}{\longrightarrow} \mathfrak{E}_{\boldsymbol{v}}^+$ in $\mathfrak{LP}_+$. Then, as $N\to \infty$,
\begin{equation*}
\mathfrak{gl}_{\bullet;N}\overset{\mathrm{d}}{\longrightarrow} \mathfrak{gl}_\bullet,
\end{equation*}
in $\mathrm{C}(\mathbb{R}_+;\mathfrak{LP}_+)$ where $\mathfrak{gl}_t(z)=\mathfrak{E}_{\mathbf{X}_{GL}^t}^+(z)$ is a Markov process in $\mathfrak{LP}_+$ which solves the equation (equation GLequation of the paper).

