\begin{equation}
    \gap(P_i) = \inf_{f\in L^2(\pi_i)\setminus\{0\}}\frac{\mathcal E_i (f)}{\var_{\pi_i}(f)}\,,
\end{equation}
where
\[
\mathcal E_i(f) \defeq \frac{1}{2} \int_{\mathcal X}\int_{\mathcal X} |f(y)-f(x)|^2\, P_i(x,dy)\,\pi_i(dx).
\]
Let~$Z_i \defeq \int_{\mathcal X} \tilde p_i(x)\, m(dx)$ be the normalizing constants, so that $\pi_i(dx) = p_i(x)m(dx)$ with $p_i = \tilde p_i/Z_i$. By the definition of the Metropolis random walk and the symmetry of the proposal kernel, we have
\begin{equation}
    \mathcal E_i(f) = \frac{1}{2}\int_{\mathcal X}\int_{\mathcal X} |f(y)-f(x)|^2 q(x,y)\min\{p_i(y), p_i(x)\}\, m(dy)m(dx)\,.
\end{equation}

