[Theorem semicircle of arXiv:2412.02087, 'The spectral distribution of random graphs with given degree sequences'] Consider the degree sequence $\{ d_1^{(n)}, d_2^{(n)}, \cdots, d_n^{(n)} \}$ with total degree $D^{(n)}=d_1^{(n)}+d_2^{(n)}+\cdots+d_n^{(n)}$ for each $n\geq 1$. Suppose that $\min\{d_i^{(n)}\}_{i\in [n]} \gg \sqrt{D^{(n)}/n}$ as $n \rightarrow \infty$. Consider the normalized Laplacian matrix $M^{(n)}$ as defined in (equation e:defM of the paper). Then, the moments of the empirical eigenvalue distribution of $M^{(n)}$ converge to the moments of the semicircle distribution:
    \begin{align}

    \lim_{n\rightarrow \infty}\frac{1}{n}\mathbb{E}[{\rm Tr}[({M^{(n)}})^k]] =  
        \begin{cases} 
            C_{k/2} & \text{for even $k$}, \\
            0 & \text{for odd $k$},
        \end{cases}
   \end{align}
    where $C_{k/2}$ is the $k/2$-th Catalan number. Moreover, the empirical eigenvalue distribution $\mu_n$ of $M^{(n)}$ weakly converges to the semicircle distribution $\rho_{\rm sc}$ in probability:
    \begin{align}
        \mu_n \xrightarrow{D} \rho_{\rm sc},\quad  \text{in probability}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition1 def_Lclose of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] For $L > 0$, we say that $f_1$ and $f_2$ (see Figure~(Lclose of the paper)) are \emph{$L$-close} if:
\begin{itemize}
    \item each vertex $x_1,x_2,x_3$ is at distance at most $L$ from $\{y_1,y_2,y_3\}$ along $\partial t$,
    \item each vertex $y_1,y_2,y_3$ is at distance at most $L$ from $\{x_1,x_2,x_3\}$ along $\partial t$.
\end{itemize}

\begin{figure}[H]
\centering
\includegraphics[scale=0.5]{Lclose.png}
\caption{Example where the triangles $f_1$ and $f_2$ are $L$-close. Note that it is possible that $i=j$.}

\end{figure}

