[Lemma lem:T1-limit of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] We have
\begin{equation}
    \lim_{n \to \infty} T_{1, n, q} = \begin{cases}
    \frac{1}{2q-1}\int_0^1\frac{u^{-2q + 1} - 1}{1 - u} \cdot \frac{(1 - \frac{u}{2})^{q - 1} - 1}{u} du & \text{if } q \in (0, 1) \setminus \{\frac{1}{2}\}, \\[5pt]
    \int_0^1 \frac{-\ln u}{1-u}\cdot\frac{\left(1-\frac{u}{2}\right)^{-1/2}-1}{u}\,du & \text{if } q = \frac{1}{2}.
    \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 14 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let $\alpha$ be a fixed ordinal and $\calL$ be a $\rmbeta$-language. Now let $\calL_\alpha$ be the language obtained from $\calL$ by adding constant symbols $\overline{\xi}$ for $\xi\in\alpha$. The rules of Tait-style $\LK_\alpha$ are obtained from the rules of first-order logic with the following additional rules:
    \begin{center}
        \vspace{1em}
        \begin{mathprooftree}
            \AxiomC{}
            \RightLabel{$(<_\ord)$ ($\eta<\xi$)}
            \UnaryInfC{$\overline{\eta}<_\ord\overline{\xi}$}
        \end{mathprooftree} 
        \hspace{3em}
        \begin{mathprooftree}
            \AxiomC{}
            \RightLabel{$(\le_\ord)$ ($\eta\le\xi$)}
            \UnaryInfC{$\overline{\eta}\le_\ord\overline{\xi}$}
        \end{mathprooftree}

        \vspace{1em}
        \begin{mathprooftree}
            \AxiomC{$\cdots \quad \Gamma, A(\overline{\xi}) \quad\cdots \quad (\text{for all }\xi<\alpha)$}
            \RightLabel{$\forall^\ord$}
            \UnaryInfC{$\Gamma,\forall^\ord x A(x)$}
        \end{mathprooftree} 
        \hspace{3em}
        \begin{mathprooftree}
            \AxiomC{$\Gamma,A(\overline{\xi})$}
            \RightLabel{$\exists^\ord$}
            \UnaryInfC{$\Gamma,\exists^\ord x A(x)$}
        \end{mathprooftree} 
    \end{center}
    We also assume that we can apply structural rules (Weakening, Contraction, Exchange) without explicit application of these rules; These rules can be simultaneously applied to other rules.

[Lem lem-walk-pos-prob of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] Recall that $\widehat{\mathbbm P}_{(x,y)}$ denotes the law of the (conditioned) walk $\widehat{\mathcal Z}$ started from $(x,y)$.
For $x\geq 0$ and $s \in [0,x]\cap\mathbbm Z$,
\begin{equation*}
\widehat{\mathbbm P}_{(x,y)}\mathopen{}\mathclose\bgroup\originalleft[ \widehat{\mathcal L}(j)  \geq x  - s , \, \forall j \geq 0 \aftergroup\egroup\originalright] 
= \frac{ s+1}{x+1}. 
\end{equation*}

