[Defn 1 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume \ref{H0}--\ref{H3} hold. We say that $(\Omega,\mathcal F,(\mathcal F_t)_{t\geq0},\mathbb P, W,X)$ is a weak mild solution to \eqref{abstract_formulation} if $(\Omega,\mathcal F,(\mathcal F_t)_{t\geq0},\mathbb P)$ is a complete filtered probability space, $X=\{X(t)\}_{t\in[0,T]}$ is a continuous $(\mathcal F_t)_{t\in[0,T]}$-adapted $H$-valued process and $W=(W(t))_{t\geq0}$ is a $U$-valued cylindrical Wiener process such that, for every $t\in[0,T]$,
\begin{align}

X(t)=e^{tA}x+\int_0^te^{(t-s)A}\mathcal VC(s,X(s))ds+\int_0^t e^{(t-s)A}\mathcal GdW(s), \qquad \mathbb P\textrm{-a.s.}    
\end{align}

[Theorem thm:sources of arXiv:2606.30475, 'Ancestries in random $d$-DAGs'] For $M>0$, denote by $Z_M$ the number of sources (that is, vertices with in-degree 0 in $G_n$) among the first $\floor{Mn^{d/(d+1)}}$ vertices. As $n\to\infty$, we have
 \begin{equation}
  Z_M\stackrel{\mathrm{d}}{\longrightarrow} \mathsf{Poi}\left(\frac{M^{d+1}}{d+1}\right),
 \end{equation}
 with convergence of all moments. In particular, the threshold for source nodes in $G_n$ is $n^{d/(d+1)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2609.03248, 'Connections between colored restricted $b$-ary and ordinary partitions'] Let $\lambda_1=\dots=\lambda_\rho$ in \eqref{3.10}. Then the following hold:
\begin{enumerate}
\item[(a)] $Y_n$ counts the number of compositions of $n+\rho$ into exactly 
$\rho$ parts between $1$ and $\lambda_1+1$.
\item[(b)] When $\lambda_1=1$, then $Y_n=\binom{\rho}{n}$, $n=0,1,\ldots,\rho$.
\end{enumerate}

[Lemma 16 of arXiv:2607.16502, 'Asymptotic Behavior of Path Functionals for Vector-Valued Gaussian Processes at High Level'] Let \( \bm{W}(t), \ t \in E \) be a continuous stochastic process, \( G : \R^d
  \to \R \) a Borel function bounded on compacta and \( \mu \) a finite measure on
  \( E \). If
  \begin{equation}

    \pk{ \mu ( F^c ) = 0 } = 1
    \quad \text{for almost all } \bm{x} \in \R^d,
  \end{equation}
  where
  \begin{equation}

    F \coloneqq \{ t \in E : \bm{W}(t) - \bm{x} \in D(G) \},
  \end{equation}
  then \( \Gamma : C ( E, \R^d ) \to \R \) defined by
  \begin{equation}

    \Gamma ( \bm{f} )
    = \int_E G ( \bm{f} ( t ) ) \, d \mu ( t ) - L
  \end{equation}
  satisfies condition~\ref{F3}. If \( G \) is monotone, then
  condition~\eqref{F4_G_condition} is satisfied.

[Theorem 3 ({\cite[Theorem~1.1) of arXiv:2609.00936, 'Extended Abstract of Counting Divisorial Contractions with Centre a $cA_n$-Singularity'] {Kaw02}, \cite[Theorem~1.13]{Kaw03} and \cite[Theorem~6.1]{Pae24Counting}}] 
Let $k$ be a positive integer and $P$ a $cA_k$ singularity of a terminal variety~$X$. Let $\varphi\colon Y \to X$ be a proper birational morphism with centre~$P$. Then $\varphi$ is a divisorial contraction if and only if one of the following holds:
\begin{enumerate}
\item  $\varphi$ is locally analytically equivalent to the $(r_1, r_2, a, 1)$-blowup of $\mathbb V(f)$ at $\bm 0$ where $f \in \mathbb C\{x, y, z, t\}$ is such that
  \begin{enumerate}
  \item  $r_1, r_2$ and $a$ are positive integers such that $r_1 \leq r_2$, $a(k+1) = r_1 + r_2$ and $a$ is coprime to both $r_1$ and $r_2$, and
  \item  $f = xy + g(z, t)$ where $\operatorname{wt} g = r_1 + r_2$,
  \end{enumerate}
\item  $k = 1$ and $\varphi$ is locally analytically equivalent to the $(1, 5, 3, 2)$-blowup of $\mathbb V(f)$ at $\bm 0$ where $f \in \mathbb C\{x, y, z, t\}$ is such that
  \begin{enumerate}
  \item  $f = xy + z^2 + t^3$,
  \end{enumerate}
\item  $k = 2$ and $\varphi$ is locally analytically equivalent to the $(4, 3, 2, 1)$-blowup of $\mathbb V(f)$ at $\bm 0$ where $f \in \mathbb C\{x, y, z, t\}$ is such that
  \begin{enumerate}
  \item  $f = x^2 + y^2 + z^3 + x t^2$.
  \end{enumerate}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 3 of arXiv:2607.28728, '2607.28728'] Suppose that $0<p\le \frac{3}{4}$. Then we have
\begin{align}

\lim_{N\to \infty}\P(A\mid T_0>N)=\P\left[1_A\cdot \frac{h(m,S_m)}{h(0,0)}1_{\{T_0>m\}}\right],
\end{align}
for $A\in \sigma(S_0,...,S_m)$, where
\begin{align*}
h(0,0)&:=a_1,\\
h(m,y)&:=a_m|y|\qquad \text{for}\ m>0,\ y\neq 0.
\end{align*}
Moreover, $h(m,y)$ is a space-time harmonic function for the ERW killed upon hitting $0$, that is,
\begin{align}

\P_{(m,y)}\Big[h(m+1,S_{m+1}),\ S_{m+1}\neq 0\Big]=h(m,y),
\end{align}
for $(m,y)=(0,0),\ \text{or for}\ m\ge 1\ \text{and}\ y\neq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

