body:
[Corollary eq: discrete approx of arXiv:2411.02917, '\hspace*{2mm}\\[-16mm] Stein's Method for Spatial Random Graphs'] Let  $(\Xi,\Sigma)$ be an $\mathrm{RGG}(\lambda,\kappa)$ such that $\Xi$ is an inhibitory pairwise interaction process with constant activity function~$\beta$, i.e.\ $\lambda(x\,|\, \xi) = \beta \prod_{y\in\xi} \varphi(x,y)$ for $\beta\in\R_+$ and $\varphi:\mathcal{X}^2\to \R_+$ with $\varphi\leq 1$. Then
\begin{align} 
    W_{\mathbb{G},i}(&P^\lambda\otimes Q^{\kappa},P^{\lambda_{\Lambda}}\otimes Q^{\kappa_{\Lambda}}) \leq r_V + C_iB^*\,\beta^2\, \norm{\varphi - \varphi \circ t}_1 
      + \frac14 C_E\,\beta^2\,\norm{\kappa - \kappa_{\Lambda}\circ t}_1,
\end{align}
where we define $(g \circ t) (x,y):=g(t(x),t(y))$ for any function $g \colon \mathcal{X}^2 \to \R_+$. \\
If furthermore $\varphi$ and $\kappa$ are Lipschitz continuous in both components with constants $L_V$ and $L_E$, respectively, and we have $\kappa_{\Lambda}=\kappa$, then
\begin{align} 
    W_{\mathbb{G},i}(P^u\otimes Q^{\kappa},P^{u_{\Lambda}}\otimes Q^{\kappa}) 


    \leq \Bigl( 1 + \bigl(2 C_iB^*\,L_V + \tfrac12 C_E\,L_E \bigr) \beta^2 \alpha(\mathcal{X})^2 \Bigr) \, r_V.
\end{align}

