[Theorem thm:Robust2 of arXiv:2606.19313, 'Stability of Khintchine-type inequalities via log-monotonicity'] Suppose $p=2q$ for some integer $q\geq 2$ and $(a_1, a_2, \ldots, a_n)\in \mathbb{R}^n$ satisfies $\sum_ka_k^2=1$. Furthermore, suppose $X$ is a symmetric random variable and $X_1, X_2, \ldots, X_n$ are iid copies of $X$. Let $r_k=r_k(X)$. Then $S=\sum_ka_kX_k$ satisfies the following bounds.
\begin{enumerate}
\item If $(r_k)$ is log-concave, then $r_1^2-r_2\geq 0$ and
\begin{align*}
\| S \|_p^p\leq \gamma_p^p\| S \|_2^p-2^q\gamma_p^pr_1^{q-2}(r_1^2-r_2)\Delta_q(a);
\end{align*} 

\item If $(r_k)$ is log-convex, then $r_2-r_1^2\geq 0$ and
\begin{align*}
\| S \|_p^p\geq \gamma_p^p\| S \|_2^p+2^q\gamma_p^pr_1^{q-2}(r_2-r_1^2)\Delta_q(a).
\end{align*} 
\end{enumerate} Moreover, the constants are asymptotically sharp near the Gaussian extremizer. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:action_function of arXiv:2605.03896, 'Dimer models on astroidal zig-zag graphs'] The \emph{action function} is the multi-valued function on \(\Sigma\) defined by
\begin{equation}
\Lambda_c(\zeta;x,y)
:=
\sum_{\alpha\in\bm \alpha} \bigl(-b_{e(\alpha)} x+a_{e(\alpha)} y+c(e(\alpha))\bigr)\log E(\alpha,\zeta).
\end{equation}

[Lemma 46 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 7$ and $\lambda>2$, there exist $\Cl(d,\lambda),\Cl(d)>0$ such that for any $m\ge \Cref{const_prepare_highd1}$, $N\ge 10dm$ and $y\in \partial B(N)$, 
	\begin{equation}
		\mathbb{P}\big( \widehat{\mathcal{H}}_{m,\bm{0}}^+ \in \big[\lambda^{-1}m^2N^{2-d},\lambda m^2N^{2-d} \big]  \mid \bm{0}\xleftrightarrow{\ge 0} y \big)\le  \Cref{const_prepare_highd2} \lambda^{-1}. 
	\end{equation}

