[Lemma 39 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $r\geq 2$ be an even integer, $q\in [1,\infty)$ and $f(X)=\mrm{Tr}\left(X^{r}\right)^{q}$, then
	\begin{equation}
		\dfrac{\Var{f(X)}}{\Ec{\|\nabla f(X)\|_{\mrm{HS}}^2} \cdot\sup\limits_{\theta\in\mathbb{S}^{d_N-1}}\E\left[\braket{\theta,X}^2\right]}
		\leq \dfrac{d_N}{(rq)^2}
		\dfrac{\dfrac{G_{r,2q}}{\Gamma(u)\Gamma(u+2v_0)}-\dfrac{G_{r,q}^2}{\Gamma(u+v_0)^2}}
		{\dfrac{G_{2,1}}{\Gamma(u+v_1)} \cdot \dfrac{\E[\braket{\mu_N,x^r}^{2q-2}\braket{\mu_N,x^{2r-2}}]}{\Gamma(u+v_2)}},
	\end{equation}
	with $u=1+d_N/p$, $v_0=rq/p$, $v_1=2/p$ and $v_2=2(rq-1)/p$.

