body:
[Proposition 130 (Response-forced geometry of the backward first jet) of arXiv:2608.04993, '2608.04993'] The map
\begin{equation}
 \mathcal J_{\rm VI}:\mathscr W_{Q,\cP}^{1,2}
 \longrightarrow\mathscr R_{\rm VI}^{\rm bw},
 \qquad
 \mathcal J_{\rm VI}(Y,Z):=(Y,I(Z)),
\end{equation}
is a stable-causal bi-Lipschitz homeomorphism.  More precisely, for every two
first-jet states,
\begin{align}
 &\|Y-\widetilde Y\|_{\mathbb S_{\cP}^2}
   +\|Z-\widetilde Z\|_{\mathbb H_{\cP}^2}
 \notag\\
 &\qquad\le
 d_{\rm VI}\bigl(\mathcal J_{\rm VI}(Y,Z),
                   \mathcal J_{\rm VI}(\widetilde Y,\widetilde Z)\bigr)
 \notag\\
 &\qquad\le
 \|Y-\widetilde Y\|_{\mathbb S_{\cP}^2}
   +2\|Z-\widetilde Z\|_{\mathbb H_{\cP}^2}.

\end{align}
Its inverse is
\begin{equation}
 \mathcal D_{\rm VI}(Y,M):=(Y,I^{-1}M),
\end{equation}
where $I^{-1}$ is taken on the closed range of the common stochastic integral.
Consequently
\[
 \boxed{
 \text{value response}+\text{martingale response}
 \quad\Longrightarrow\quad
 \mathbb S_{\cP}^2\times\mathbb H_{\cP}^2
 \text{ first-jet geometry}.}
\]
In particular, the $\mathbb H_{\cP}^2$ topology is calibrated exactly by
the terminal martingale response and reconstructed from the full path response
by Doob propagation; it is not an independent ambient choice.

[Corollary 17 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] Let $y \in B_{r-1}^{\nc}(x)$. Then, we have
  \begin{equation*}
    D_{y}^{\nc} \leq D^{\check{\Tree}_{x}}_{\iota(y)} \leq D^{\Tree_{x}}_{\iota(y)}\,.
  \end{equation*}
  Furthermore, there exists a constant $C_{\nu} > 0$ such that with $\nu$-high probability
  \begin{equation*}
    D^{\check{\Tree}_{x}}_{\iota(y)} \leq D_{y}^{\nc} + C_{\nu}\,.
  \end{equation*}

[Corollary cor:useful-bound of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\alpha\in\mathbb R$ be a real number and $B,\Gamma$ be two continuous functions.
    Define the function
    \begin{align*}
        F_t(x,y)=\frac{t^\alpha}{B(x)}\exp\left(-\frac{t}{\Gamma(y)}\right)\,.
    \end{align*}
    Assume that $B,\Gamma$ are strictly positive on $(0,a_+]$ and that there exists $C_\beta,C_\gamma>0$ and $\beta,\gamma>0$ such that $B(x)\sim C_\beta x^\beta$ and $\Gamma(x)\sim C_\gamma x^\gamma$ when $x\rightarrow0$.
    Then, for any $\epsilon=\epsilon(t)$ converging to $0$ as $t$ diverges and $\Tilde{a}_+=\Tilde{a}_+(t)\leq a_+$, there exists $k=k(t)$ an integer depending on $t$ and a sequence of increasing values $(a_0\leq\ldots\leq a_k)$ (implicitly depending on $t$) such that $a_0=\epsilon$, $a_k=\Tilde{a}_+$, and satisfying
    \begin{align*}
        \lim_{t\rightarrow\infty}\sum_{i=1}^kF_t(a_{i-1},a_i)=0\,.
    \end{align*}

