[Lemma lemma_necessary_estimates of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] For any fixed integer $p\in \mathbb{N}$, let $(\Lambda_i)_{1\le i \le p}$ be an arbitrary sequence of $D\times D$ block matrices similar in form to $\Lambda$, consisting of $N\times N $ deterministic blocks $A_i$ and $A_i^*$ with $\|A_i\|=\mathrm{o}(1)$. Let $(B_i)_{1\le i \le p}$ be an arbitrary sequence of deterministic matrices satisfying $\|B_i\|\le 1$.  
Furthermore, consider a sequence of spectral parameters $z_i=E_i+\mathrm{i} \eta_i\in \mathbb{C}_+$ for $i\in[\![{p}]\!]$, satisfying $\left\lvert z_i \right\rvert\le \tau^{-1}$ for a small constant $\tau>0$.  
Suppose the anisotropic local law (equation eq:aniso_local of the paper) holds for all $G_i-M_i$, where $G_i\equiv  G(z_i,H,\Lambda_i)$ and $M_i\equiv M(z_i,\Lambda_i)$ is the deterministic limit of $G_i$ as defined in (defn_Mm of the paper) with parameter $z_i$. 
Moreover, denote $m_i\equiv \left\langle M_i \right\rangle$ and assume that $ N\eta_i \im m_i (z_i) \gtrsim 1$ for all $i\in [\![{p}]\!]$. Then, for any deterministic unit vectors ${\bf{u}}, {\bf{v}}\in\mathbb{C}^{DN}$ and $s_i\in \{\emptyset,*\}^{p}$, the following estimates hold:
    \begin{equation}
        \begin{aligned}
                {\bf{u}}^*\pa{\prod_{i=1}^p G_i^{s_i} B_i}{\bf{v}}\prec \frac{\pa{\max_{1\le i\le p} \im m_i}^{1_{p\ge 2}}}{\eta^{p-1}},\qquad \avga{\prod_{i=1}^p G_i^{s_i} B_i}\prec \frac{\pa{\max_{1\le i\le p} \im m_i}^{1_{p\ge 2}}}{\eta^{p-1}},
        \end{aligned}
    \end{equation}
    where we denote $\eta:=\min_{i}\eta_i$ and adopt the convention that $G_i^\emptyset=G_i$. 

    We denote by $\Pi_l$ a product consisting of $l$ elements in $\ha{G_i^{s}:i\in [\![{p}]\!],s\in \{\emptyset,*\}}$, along with some elements from $\left\{{M_i}\right\}$ and \smash{$\left\{{E_a}\right\}_{a=1}^D$}. Moreover, suppose all $\Lambda_i$ have the form $\Lambda_i=c_i\Lambda$ for some deterministic coefficients $c_i$ of order $\mathrm{O}(1)$. Then, we have the following estimates.
    \begin{enumerate}
        \item A loop containing one factor of $\Lambda$ satisfies that
    \begin{equation}
    \left\langle\Pi_l \Lambda\right\rangle \prec \begin{cases} N^{-1}\left\lVert \Lambda \right\rVert_{\text{\rm{HS}}}^2=D\left\langle \Lambda^2 \right\rangle, & \text { if } l=0, \\ N^{-1 / 2}\lVert \Lambda \rVert_{\text{\rm{HS}}}\cdot \pa{\max_{1\le i\le p} \im m_i }^{\mathbf 1_{l\ge 2}}\cdot \eta^{-(l-1)}, & \text { if } l \ge 1.\end{cases}
    \end{equation}
    \item A loop containing two factors of $\Lambda$ satisfies that
    \begin{equation}
        \left\langle\Pi_{l_1} \Lambda \Pi_{l_2} \Lambda\right\rangle \prec \begin{cases}N^{-1}\lVert \Lambda \rVert_{\text{\rm{HS}}}^2=D\left\langle \Lambda^2 \right\rangle, & \text { if } l_1+l_2=0, \\ N^{-1}\lVert \Lambda \rVert_{\text{\rm{HS}}}^2\cdot \pa{\max_{1\le i\le p} \im m_i}^{\mathbf 1_{l_1+l_2\ge 2}} \cdot \eta^{-(l_1+l_2-1)},  & \text { if } l_1+l_2 \ge 1.\end{cases}
    \end{equation}
    \end{enumerate}
    The same estimates also hold if some $\Lambda$ factors on the LHS of (equation one_loop_estimate of the paper) and (equation two_loop_estimate of the paper) are replaced by ${\widetilde{\Lambda}}$ (defined in (lem_regular_estimate_localized_eigenvector of the paper)) or ${\widehat{\Lambda}}_t$ (defined in (lem_regular_estimate_localized_eigenvalue of the paper)) for $t\in\left[{0,1}\right]$.

