[Thm t:InfMA of arXiv:2605.08983, 'A functional limit theorem for self-normalized linear processes with random coefficients a'] Let $(X_{i})$ be a linear process defined by
$$ X_{i} = \sum_{j=0}^{\infty}C_{j}Z_{i-j}, \qquad i \in \mathbb{Z},$$
where $(Z_{i})_{i \in \mathbb{Z}}$ is an i.i.d.~sequence of regularly varying random variables satisfying $((e:regvar of the paper))$ and $((eq:pq of the paper))$ with $\alpha \in (0,2)$. Assume conditions $((e:oceknula of the paper))$ and $((e:sim of the paper))$ hold. Let $(C_{i})_{i \geq 0}$ be a sequence of random variables, independent of $(Z_{i})$, satisfying conditions $((eq:InfiniteMAcond of the paper))$, $((e:momcond2 of the paper))$,
\begin{equation}
\sum_{j=0}^{\infty} (\mathrm{E}|C_{j}|^{2r})^{1/2} < \infty \qquad \textrm{for some}  \ r \in (\alpha/2, 1 \wedge \alpha),
\end{equation}
and
\begin{equation}
         \sum_{i=0}^{\infty}\mathrm{E}(|C_{i}|^{\gamma} + |C_{i}|^{2 \gamma}) < \infty
\end{equation}
for some $\gamma \in (\alpha, 1)$ if $\alpha \in (0,1)$ and $\gamma \in (\alpha/2, 1)$ if $\alpha \in [1,2)$.

If $\alpha \in [1,2)$ suppose further

\begin{equation}
\sum_{j=0}^{\infty} \mathrm{E}|C_{j}| < \infty.
\end{equation}

Then, as $n \to \infty$,
\begin{equation}
L_{n}(\,\cdot\,) \xrightarrow{d}  (C^{(1)}V(\,\cdot\,), C^{(2)}W(\,\cdot\,))
\end{equation}
 in $D^{2}$ with the weak $M_{2}$ topology,
 where $V$ is an $\alpha$--stable L\'{e}vy process with characteristic triple $(0, \mu, b)$, with $\mu$ as in $((eq:mu of the paper))$,
$$ b = \left\{ \begin{array}{cc}
                                   0, & \quad \alpha = 1,\\[0.4em]
                                   (p-r)\frac{\alpha}{1-\alpha}, & \quad \alpha \in (0,1) \cup (1,2),
                                 \end{array}\right.$$
with $p$ and $r$ defined in $((eq:pq of the paper))$, $W$ is an $\alpha/2$--stable L\'{e}vy process with characteristic triple $(0, \widetilde{\mu}, \alpha/(2-\alpha))$ with $\widetilde{\mu}(\mathrm{d} x) = (\alpha /2) x^{-\alpha/2-1} 1_{(0,\infty)}(x)\,\mathrm{d} x$,
and $(C^{(1)}, C^{(2)})$ is a random vector, independent of $(V, W)$, such that
$(C^{(1)}, C^{(2)}) \stackrel{d}{=} (C, C^{S})$, where $C=\sum_{i=0}^{\infty}C_{i}$ and $C^{S}=\sum_{i=0}^{\infty}C_{i}^{2}$.

[Prop p:rigidity of arXiv:2411.10586, 'A convergence framework for Airy$_\beta$ line ensemble\\ via pole evolution'] There exist small $\delta,c>0$ such that the following holds. Define the spectral domain 
    \begin{align}
        {\mathcal D}=\{\kappa+\mathrm{i}\eta: \eta\geq K,  \eta^{-1-\delta}K\leq \kappa\leq \sqrt{K^2+\eta^2}\}.
    \end{align}
    With probability at least $1-e^{-c(\log T)^2}$, for any $t\in [T, 2T]$, and $\sqrt w\in {\mathcal D}$, it holds
    \begin{align}
        \left|Y_t(w)-\sqrt{w}\right|\leq \frac{{\rm Im}[\sqrt w]^{1-\delta}}{{\rm Im}[w]}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:zb_nu of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] For $x>0$ and $y<0$, we have
\begin{align*}
    \mathcal{J}(t,x,y)= \int_D p_t^D(x,z)\nu(z,y)\,{\rm d}z\to \nu(x,y),
\end{align*}
as $t\to 0^+$.

[Lemma lem:accumulate_early of arXiv:2604.10214, 'Large deviations for maximum local time of simple random walk in dimensions \texorpdfstrin'] For any $\beta>1$ and $\varepsilon>0$, and any integer sequence $(k_n)$ satisfying
\(
k_n=\beta\alpha\log n+O(1)
\)
as $n\to\infty$, one has
\begin{align}
\sup_{j\ge \varepsilon n}
{\mathbb P}\big(\xi(\infty,0)\ge k_n,\ \xi(j,0)<k_n\big)
=o(n^{-\beta}).
\end{align}

